UPDATE Recipts SET 
PrvYearID = YearID
WHERE        (PrvYearID IS NULL) AND (ParentReciptID IS NULL)

UPDATE ReciptItems 
SET PrvYearID = YearID
WHERE        (PrvYearID IS NULL) AND (preReciptItemID IS NULL)


UPDATE       Customers
SET                StateCode = Zone.OstanCode, CityCode = Zone.ShahrCode
FROM            Customers INNER JOIN
                         Zone ON Customers.City = Zone.Shahr
WHERE        (Customers.City > '') AND ((Customers.StateCode = 0) OR (Customers.CityCode = 0))

