CREATE FUNCTION GetPayTypeFromParent
(
    @ServerID INT,
    @YearID INT,
    @FormItemID INT
)
RETURNS INT
AS
BEGIN
    DECLARE @PayType INT
    DECLARE @CurrentFormItemID INT
    DECLARE @PreFormItemID INT
    
    -- شروع از FormItemID داده شده
    SET @CurrentFormItemID = @FormItemID
    
    -- پیمایش به سمت والدین تا زمانی که preFormItemID = 0 باشد
    WHILE @CurrentFormItemID IS NOT NULL
    BEGIN
        -- گرفتن preFormItemID برای ردیف فعلی
        SELECT @PreFormItemID = preFormItemID
        FROM FormItems
        WHERE ServerID = @ServerID 
          AND YearID = @YearID 
          AND FormItemID = @CurrentFormItemID
        
        -- اگر preFormItemID = 0 باشد، یعنی به والد اولیه رسیده‌ایم
        IF @PreFormItemID = 0 OR @PreFormItemID IS NULL
        BEGIN
            -- گرفتن PayTypes از فرم مربوط به این FormItem
            SELECT @PayType = f.PayTypes
            FROM Forms f
            INNER JOIN FormItems fi ON f.FormID = fi.FormID 
                                   AND f.ServerID = fi.ServerID 
                                   AND f.YearID = fi.YearID
            WHERE f.ServerID = @ServerID 
              AND f.YearID = @YearID 
              AND fi.FormItemID = @CurrentFormItemID
              
            BREAK
        END
        ELSE
        BEGIN
            -- ادامه پیمایش به والد بعدی
            SET @CurrentFormItemID = @PreFormItemID
        END
    END
    
    RETURN @PayType
END
