CREATE FUNCTION dbo.GetBlacklistMarker(@IsBlacklisted BIT)
RETURNS VARCHAR(12)
AS
BEGIN
    DECLARE @Result VARCHAR(12);
    
    IF @IsBlacklisted = 1
        SET @Result = '(($$$))';  -- یا هر کاراکتر دیگری که می‌خواهید استفاده کنید
    ELSE
        SET @Result = '';

    RETURN @Result; 
END;

