							 C.Address, C.Tel, C.Fax, C.email, C.pobox, C.acc_DetailCode, C.MaxCredit, C.ServiceCalcType, C.ServicePrice, 
							 C.ExtServicePrice, C.RevenuePercent, C.EconomicNumber, C.PostalCode, C.State, C.ModifyDate, C.OperatorID, C.CustomerNote, 
							 C.ValuationType, C.ProjectID, C.BudgetID, C.InfoWeight, C.InfoDate, C.GrpActionCustomer, C.ContactRate, C.acc_CTopicCode, 
							 C.acc_CTopicCode2, C.BankId, C.BankName, C.AccountNumber, C.AccountKind, C.BankReports, C.ManageName, C.ManagerSells, 
							 C.ContactNo, C.DiscountNote, C.Discount, C.DayTime, C.ConveyKind, C.ArzTypeID, C.accStateDefault, C.NationalID, C.Mobile, 
							 C.CustomersRow, C.PersonID1, C.EstablishDate, C.SellsMethod, C.SellsEmporium, C.SellsDefaultState, C.MasirID, 
							 C.MaxCreditCurrentForm, C.CustomerActive, C.ReagentName, C.Tel2, C.Tel3, C.PersonID3, C.UseUnitID, C.InsertAutoEffectID, 
							 C.EffectID, C.CustomerGrpID2, C.PurchasePercent, C.TechnicalCode, C.acc_CTopicCode3, C.CustAccountNumber, C.acc_TopicCode, 
							 C.RegisterNumber, C.HCTarafGaradadTypeCode, C.HCKharidarTypeCode, C.CustFirstName, C.PerCityCode, C.StateCode, C.CityCode, 
							 C.LastUser, C.FirstUser, C.CustomerState, C.HCForoushandeType1Code, C.Max4WaterCo, C.SupervisorAllocation,C.CustomerCheckNote
							 ,C.DayOrder,C.DiscountOne,C.Buyerbbc,C.BlackList
  
  
	  ,  G.GroupType, G.CustomerGrpName,NationalCode

	  FROM            Customers C INNER JOIN
							 CustomersGroup G ON C.CustomerGrpID = G.CustomerGrpID
	WHERE (C.CustomerActive = 0)
	UNION ALL
	  SELECT       CustomersOtherGroups.CustomerGrpID AS CustomerGroupID,CASE WHEN LEN(isnull(CustFirstName,'')) = 0 THEN C.CustName 
														   ELSE  C.CustFirstName+' ' +C.CustName END+dbo.GetBlacklistMarker(Blacklist ) AS CustName,C.CustName_L2, 

	  C.CustID, C.CustomerGrpID, 

	  C.Balance, C.FirstBalance, C.Country, C.City, C.WebSite, C.Region, 
							 C.Address, C.Tel, C.Fax, C.email, C.pobox, C.acc_DetailCode, C.MaxCredit, C.ServiceCalcType, C.ServicePrice, 
							 C.ExtServicePrice, C.RevenuePercent, C.EconomicNumber, C.PostalCode, C.State, C.ModifyDate, C.OperatorID, C.CustomerNote, 
							 C.ValuationType, C.ProjectID, C.BudgetID, C.InfoWeight, C.InfoDate, C.GrpActionCustomer, C.ContactRate, C.acc_CTopicCode, 
							 C.acc_CTopicCode2, C.BankId, C.BankName, C.AccountNumber, C.AccountKind, C.BankReports, C.ManageName, C.ManagerSells, 
							 C.ContactNo, C.DiscountNote, C.Discount, C.DayTime, C.ConveyKind, C.ArzTypeID, C.accStateDefault, C.NationalID, C.Mobile, 
							 C.CustomersRow, C.PersonID1, C.EstablishDate, C.SellsMethod, C.SellsEmporium, C.SellsDefaultState, C.MasirID, 
							 C.MaxCreditCurrentForm, C.CustomerActive, C.ReagentName, C.Tel2, C.Tel3, C.PersonID3, C.UseUnitID, C.InsertAutoEffectID, 
							 C.EffectID, C.CustomerGrpID2, C.PurchasePercent, C.TechnicalCode, C.acc_CTopicCode3, C.CustAccountNumber, C.acc_TopicCode, 
							 C.RegisterNumber, C.HCTarafGaradadTypeCode, C.HCKharidarTypeCode, C.CustFirstName, C.PerCityCode, C.StateCode, C.CityCode, 
							 C.LastUser, C.FirstUser, C.CustomerState, C.HCForoushandeType1Code, C.Max4WaterCo, C.SupervisorAllocation,C.CustomerCheckNote
							  ,C.DayOrder,C.DiscountOne,C.Buyerbbc,C.BlackList

	  , G.GroupType, G.CustomerGrpName,NationalCode
	  FROM            CustomersOtherGroups INNER JOIN
							 Customers C ON CustomersOtherGroups.CustID = C.CustID INNER JOIN
							 CustomersGroup G ON CustomersOtherGroups.CustomerGrpID = G.CustomerGrpID
	WHERE (C.CustomerActive = 0)
