	CREATE VIEW AllDeficits_ForRecipts
	WITH SCHEMABINDING 
	AS
	SELECT     COUNT_BIG(*) C,RD.ReciptID,RD.ServerID,RD.YearID, SUM(DeficitAdd) AS DeficitAdd, SUM(DeficitDec) AS DeficitDec
		 , SUM(DeficitAdd - DeficitDec) AS DeficitAdd_Dec ,sum(ArzAmount) ArzAmount
	FROM         dbo.ReciptsDeficits RD
	GROUP BY RD.ReciptID,RD.ServerID,RD.YearID
	GO 
