	CREATE VIEW AllDeficits_ForReciptsDoc
	WITH SCHEMABINDING 
	AS
	SELECT  COUNT_BIG(*) C,
			RD.ReciptID,
			RD.ServerID,
			RD.YearID, 
			SUM(DeficitAdd) AS DeficitAdd, 
			SUM(DeficitDec) AS DeficitDec , 
			SUM(DeficitAdd - DeficitDec) AS DeficitAdd_Dec ,
			sum(CASE WHEN DeficitAdd>0 then ArzAmount ELSE 0 end) CurrencyDeficitAdd,
			sum(CASE WHEN DeficitDec>0 then ArzAmount ELSE 0 end) CurrencyDeficitDec,
			SUM(CASE WHEN DeficitAdd>0 then ArzAmount ELSE -ArzAmount end) AS CurrencyDeficitAdd_Dec ,
			sum(CASE WHEN DeficitAdd>0 then ArzAmount ELSE -ArzAmount end) ArzAmount -- this column has to delete , dont't use of this 
	FROM    dbo.ReciptsDeficits RD 
			JOIN dbo.Deficits D ON D.DeficitID = RD.DeficitID
	WHERE (D.AccFixedCoding = 0)
	GROUP BY RD.ReciptID,RD.ServerID,RD.YearID
	GO 
	SET QUOTED_IDENTIFIER OFF 
	GO 
	SET ANSI_NULLS ON 
	GO 


