	CREATE VIEW [dbo].[VU_aidrecal] WITH SCHEMABINDING
	AS 

	  SELECT	RI.PrvYearID, RI.preReciptItemID, RI.serverid, RI.StuffCode,
				SUM(RI.InputEntity + RI.OutputEntity) AS Entity, 
				SUM(RI.InputWeight + RI.OutputWeight) AS Weight, 
				SUM(cast(RI.TotalInputPrice as decimal(38,0)) + cast(RI.TotalOutputPrice as decimal(38,0)) ) AS Price,
				SUM(cast(RI.TotallSellPrice as decimal(38,0))) AS TotallSellPrice,
				COUNT_BIG( * ) as  CountNo

	  FROM	dbo.ReciptItems RI INNER JOIN
			dbo.Recipts R ON RI.ReciptID = R.ReciptID AND 
							 RI.ServerID = R.ServerID AND 
							 RI.YearID = R.YearID 
						  
	  WHERE	    (R.ReciptState < 3) 
			AND (R.ReciptType in ( 11 , 15))
		
		 
	GROUP BY RI.PrvYearID , RI.preReciptItemID, RI.serverid ,RI.StuffCode
	GO 
	SET QUOTED_IDENTIFIER OFF 
	GO 
	SET ANSI_NULLS ON 
	GO 

