	CREATE VIEW [dbo].[ReciptItems_Stock_Oper]
	AS
	SELECT     
			Recipts.ServerID, 
			Recipts.YearID, 
			Recipts.ReciptID, 
			Recipts.StoreID, 
			Ri.StuffCode, 
			Recipts.ReciptNumber, 
			Recipts.ReciptDate, 
			Recipts.PersonID1, 
			ISNULL(Recipts.PersonID2, 0) AS PersonID2, 
			Recipts.PersonID3,
			Recipts.PersonID4,
			Recipts.PersonID5, 
			ISNULL(Ri.PersonID1, 0) AS PersonID1D, 
			Ri.ProductCode, 
			ReciptTypes.EffectType, 
			Recipts.ReciptType, 
			ReciptTypes.ReciptCaption, 
			Ri.StuffSize, 
			Ri.StuffDiameter, 
			Ri.StuffAlloy, 
			Ri.ControlCode, 
			Ri.ItemNote, 
			Recipts.AidNumber, 
			Recipts.AidDate, 
			Ri.InputEntity, 
			Ri.InputWeight, 
			Ri.OutputEntity,
			Ri.OutputWeight, 
			Ri.UnitSellPrice, 
			Ri.TotallSellPrice - ISNULL(CASE WHEN ReciptTypes.EffectType = 2 THEN Ri.TaxValue ELSE 0 END, 0) AS TotallSellPrice, 
			Regular.RegPrice, 
			Ri.Portage,
			Ri.WaterCo, 
			Ri.DeficitValue+ Ri.DeficitValue2 + Ri.DeficitValue4 + Ri.DeficitValue3 AS DeficitValue, 
			Ri.DeficitValue AS DeficitValue1 , 
			Ri.DeficitValue2 , 
			Ri.DeficitValue4 , 
			Ri.DeficitValue3 , 
			Ri.Article, 
			Ri.Wage, 
			Ri.Scoria, 
			Ri.TaxValue, 
			Ri.TaxCo, 
			Ri.RollbackWeight, 
			Ri.AcceptWeight, 
			Ri.AcceptEntity, 
			Ri.RollbackEntity, 
			Ri.TotalStandardRate, 
			Ri.InvWeight, 
			Ri.InvEntity, 
			Ri.ContactRate, 
			Ri.TotalInputPrice + 
				ISNULL(CASE WHEN ReciptTypes.EffectType = 2 THEN Regular.RegPrice ELSE 0 END, 0) -
				ISNULL( CASE 
							WHEN ReciptTypes.EffectType = 2 THEN (Ri.DeficitValue+ Ri.DeficitValue2 + Ri.DeficitValue4+ Ri.DeficitValue3 ) 
							ELSE 0 
						END
						, 0) +  ---- برای اعمال تخفیف در رسید کالا در نظر گرفته شده است === 940603
			ISNULL(CASE WHEN ReciptTypes.EffectType = 2 THEN Ri.Portage ELSE 0 END, 0) +
				case when dbo.ReciptTypes.PawsFieldsActive= 4 then isnull(Ri.Article,0 ) else 0 end AS TotalInputPrice, 
			Ri.TotalOutputPrice + ISNULL(CASE WHEN ReciptTypes.EffectType = 2 THEN Regular.RegPrice ELSE 0 END, 0) +
				ISNULL(CASE WHEN ReciptTypes.EffectType = 2 THEN Ri.Portage ELSE 0 END, 0) 
	--zarf bast kimia 							+	case when dbo.ReciptTypes.PawsFieldsActive= 4 then isnull(ReciptItems.Article,0 ) else 0 end 
				AS TotalOutputPrice, 
			Ri.TotalInputPrice AS TotalInputPrice1,
			Ri.TotalOutputPrice  AS TotalOutputPrice1,
			Ri.ReciptItemID, 
			Recipts.ReciptState, 
			ReciptTypes.SellEffect, 
			Ri.TotalInputPrice AS TotalInputPriceBase, 
			Ri.TotalOutputPrice AS TotalOutputPriceBase, 
			Ri.TotallSellPrice AS TotallSellPriceBase, 
			Ri.UseUnitID, 
			Ri.ProductModel, 
			Recipts.StoreID2, 
			ReciptTypes.AutoPrice, 
			Stores.c_StoreName, 
			Stores.n_ValuationType, 
			CASE Config.EntityDisplayType 
				WHEN 0 THEN Ri.InputEntity 
				WHEN 1 THEN Ri.InputWeight 
				WHEN 2 THEN 
					CASE WHEN Ri.UnitSellPrice >=Config.EntityOutputLowerLimit THEN Ri.InputWeight ELSE Ri.InputEntity END 
				WHEN 3 THEN 
					CASE WHEN Ri.UnitSellPrice >= Config.EntityOutputLowerLimit	THEN Ri.InputEntity ELSE Ri.InputWeight END 
				ELSE 0 
			END AS In_Entity, 
			CASE Config.EntityDisplayType 
				WHEN 0 THEN Ri.OutputEntity 
				WHEN 1 THEN Ri.OutputWeight 
				WHEN 2 THEN 
					CASE WHEN Ri.UnitSellPrice >= Config.EntityOutputLowerLimit THEN Ri.OutputWeight ELSE Ri.OutputEntity END 
				WHEN 3 THEN 
					CASE WHEN Ri.UnitSellPrice >= Config.EntityOutputLowerLimit THEN Ri.OutputEntity ELSE Ri.OutputWeight END 
				ELSE 0 
			END AS Out_Entity, 
			Ri.AidNumber AS AidNumberD, 
			Ri.AidDate AS AidDateD, 
			Recipts.DocNo, 
			Recipts.DocDate, 
			Recipts.ReciptNote, 
			Recipts.MachineName, 
			Recipts.MachineNo, 
			Recipts.MachineInfo, 
			Recipts.TruckNumber, 
			LookUps.Code,
			Ri.TransFormID,
			ReciptTypes.BuyEffect ,
			Ri.preReciptItemID, 
			LookUps.Name AS SecondTypeName,
			Recipts.SellsMethod,
			SellsMethods.SellsMethodName, 
			Recipts.SellsEmporium, 
			SellsEmporiums.SellsEmporiumName,
			ISNULL(Recipts.ArzTypeID,0) AS ArzTypeID ,
			Currencies.CurrenciesName ,
			Ri.ArzRate,
			Ri.ArzAmount,
			Recipts.RialsEqual,
			Ri.Commission, 
			LookUpsItem.Name AS SecondTypeNameItem,
			Ri.DiagnosisCalcTotalPrice,
			Ri.ArzPortage,
			Ri.CurrencyDiscounts,
			Ri.acc_CTopicCode,
			Ri.acc_CTopicCode2,
			Ri.acc_CTopicCode3,
			Ri.RIDateMS,
			Ri.RIDateME,
			Recipts.SecondType, 
			Ri.UnitCommission,
			(Ri.InputEntity + Ri.OutputEntity) * Ri.UnitCommission AS TotallCommission, 
			StuffCoding.n_UnitCode,Ri.SecondTypeItem,StuffCoding.sd1,StuffCoding.Tierced, 
			Recipts.FirstUser, 
			Recipts.LastUser, 
			Recipts.InsertDate, 
			Recipts.ModifyDate, 
			Recipts.ExpireDate,
			Ri.ItemDate,
			Recipts.InvoiceTemplate,
			InvoiceTemplates.InvoiceTemplateName,
			UuD.UseUnitName, 
			Ri.UseOtherID_Item,
			Uo.UseOtherName,
			Ri.MachineNo MachineNoD ,
			Ri.MachineName MachineNameD ,
			Ri.acc_TopicCode acc_TopicCodeD,
			Ri.acc_DetailCode acc_DetailCodeD,
			Ri.acc_CTopicCode acc_CTopicCodeD,
			Ri.Function1,
			Ri.Waste1,
			Ri.Waste2, SG.GroupName,
			Recipts.TAXID,Recipts.IRTAXID,
			StuffCoding.NationalStuffCode,
			Ri.RequestedWeight

	FROM    Recipts 
			INNER JOIN ReciptItems Ri ON Recipts.ReciptID = Ri.ReciptID 
										AND Recipts.ServerID = Ri.ServerID 
										AND Recipts.YearID = Ri.YearID 
			INNER JOIN ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType 
			INNER JOIN Stores ON Recipts.StoreID = Stores.n_StoreID 
			INNER JOIN LookUps ON Recipts.SecondType = LookUps.LookUpID 
			LEFT OUTER JOIN
					(
						SELECT ServerID, 
							YearID, 
							ReciptItemID, 
							ReciptID, 
							SUM(RegPrice) AS RegPrice
						FROM  ReciptsRegulates
						where EffectAdjustments in (0,1)
						GROUP BY 
							ServerID, 
							YearID, 
							ReciptItemID, 
							ReciptID
					) AS Regular ON Ri.ReciptItemID = Regular.ReciptItemID 
									AND Ri.ReciptID = Regular.ReciptID 
									AND Ri.ServerID = Regular.ServerID 
									AND Ri.YearID = Regular.YearID 
			LEFT OUTER JOIN SellsEmporiums ON Recipts.SellsEmporium = SellsEmporiums.SellsEmporium  
			LEFT OUTER JOIN SellsMethods ON Recipts.SellsMethod = SellsMethods.SellsMethod 
			CROSS JOIN  Config
			LEFT OUTER JOIN Currencies ON ISNULL(Recipts.ArzTypeID,0) = Currencies.CurrenciesID 					  
			LEFT OUTER JOIN LookUps LookUpsItem ON Ri.SecondTypeItem = LookUpsItem.LookUpID	 
			INNER JOIN StuffCoding ON Ri.StuffCode = StuffCoding.c_StuffCode 
			INNER JOIN InvoiceTemplates ON Recipts.InvoiceTemplate = InvoiceTemplates.InvoiceTemplate
			LEFT OUTER JOIN UseUnits UuD ON Ri.UseUnitID = UuD.UseUnitID  
			LEFT OUTER JOIN UseOthers Uo ON Ri.UseOtherID_Item = Uo.UseOtherID  
			INNER JOIN StuffGroups AS SG ON StuffCoding.GroupID = SG.GroupID
                     			  
	--WHERE     (Recipts.ReciptState < 3)
	UNION ALL
	SELECT     
			Recipts.ServerID, 
			Recipts.YearID, 
			Recipts.ReciptID, 
			CASE dbo.ReciptTypes.IncreasingInventoryStore 
				WHEN 1 THEN dbo.Recipts.StoreID 
				WHEN 2 THEN dbo.Recipts.StoreID2 
				ELSE 0 
			END AS StoreID, 
			Ri.StuffCode, 
			Recipts.ReciptNumber, 
			Recipts.ReciptDate, 
			Recipts.PersonID1, 
			ISNULL(Recipts.PersonID2, 0) AS PersonID2, 
			Recipts.PersonID3,
			Recipts.PersonID4,
			Recipts.PersonID5,  
			ISNULL(Ri.PersonID1, 0) AS PersonID1D, 
			Ri.ProductCode, 
			ReciptTypes.EffectType, 
			Recipts.ReciptType, 
			ReciptTypes.ReciptCaption, 
			Ri.StuffSize, 
			Ri.StuffDiameter, 
			Ri.StuffAlloy, 
			Ri.ControlCode, 
			Ri.ItemNote, 
			Recipts.AidNumber, 
			Recipts.AidDate, 
			Ri.OutputEntity AS InputEntity, 
			Ri.OutputWeight AS InputWeight, 
			0.0 AS OutputEntity, 
			0.0 AS OutputWeight, 
			Ri.UnitSellPrice, 
			Ri.TotallSellPrice - ISNULL(Ri.TaxValue, 0) AS TotallSellPrice, 
			ISNULL(
				CASE dbo.ReciptTypes.IncreasingInventoryStore 
					WHEN 1 THEN Regular.RegPrice_Store_1 
					WHEN 2 THEN Regular.RegPrice_Store_2
					ELSE 0 
				END,0) RegPrice, 
			Ri.Portage,
			Ri.WaterCo, 
			Ri.DeficitValue+ Ri.DeficitValue2 + Ri.DeficitValue4 + Ri.DeficitValue3 AS DeficitValue , 
			Ri.DeficitValue AS DeficitValue1 , 
			Ri.DeficitValue2, 
			Ri.DeficitValue4 , 
			Ri.DeficitValue3 , 
			Ri.Article, 
			Ri.Wage, 
			Ri.Scoria, 
			Ri.TaxValue, 
			Ri.TaxCo, 
			Ri.RollbackWeight, 
			Ri.AcceptWeight, 
			Ri.AcceptEntity, 
			Ri.RollbackEntity, 
			Ri.TotalStandardRate, 
			Ri.InvWeight, 
			Ri.InvEntity, 
			Ri.ContactRate, 
			Ri.TotalOutputPrice + 
				ISNULL(
					CASE dbo.ReciptTypes.IncreasingInventoryStore 
						WHEN 1 THEN Regular.RegPrice_Store_1 
						WHEN 2 THEN Regular.RegPrice_Store_2
						ELSE 0 
					END , 0) + 
				ISNULL(Ri.Portage, 0) +
				case when dbo.ReciptTypes.PawsFieldsActive= 4 then isnull(Ri.Article,0 ) else 0 end AS TotalInputPrice, 
			0 AS TotalOutputPrice,
			Ri.TotalInputPrice AS TotalInputPrice1,
			Ri.TotalOutputPrice  AS TotalOutputPrice1,
			Ri.ReciptItemID, 
			Recipts.ReciptState, 
			ReciptTypes.SellEffect, 
			Ri.TotalOutputPrice AS TotalInputPriceBase, 
			0 AS TotalOutputPriceBase, 
			Ri.TotallSellPrice AS TotallSellPriceBase, 
			Ri.UseUnitID, 
			Ri.ProductModel, 
			Recipts.StoreID2, 
			ReciptTypes.AutoPrice, 
			CASE dbo.ReciptTypes.IncreasingInventoryStore 
				WHEN 1 THEN dbo.Stores.c_StoreName 
				WHEN 2 THEN Stores_1.c_StoreName 
				ELSE '' 
			END AS c_StoreName, 
			Stores.n_ValuationType, 
			CASE Config.EntityDisplayType 
				WHEN 0 THEN Ri.OutputEntity 
				WHEN 1 THEN Ri.OutputWeight 
				WHEN 2 THEN 
					CASE 
						WHEN Ri.UnitSellPrice >= Config.EntityOutputLowerLimit THEN Ri.OutputWeight ELSE Ri.OutputEntity END 
				WHEN 3 THEN 
					CASE WHEN Ri.UnitSellPrice >= Config.EntityOutputLowerLimit THEN Ri.OutputEntity ELSE Ri.OutputWeight END 
				ELSE 0 
			END AS In_Entity, 
			0 AS Out_Entity, 
			Ri.AidNumber AS AidNumberD, 
			Ri.AidDate AS AidDateD, 
			Recipts.DocNo, 
			Recipts.DocDate, 
			Recipts.ReciptNote, 
			Recipts.MachineName, 
			Recipts.MachineNo, 
			Recipts.MachineInfo, 
			Recipts.TruckNumber, 
			LookUps.Code,
			Ri.TransFormID,
			ReciptTypes.BuyEffect,
			Ri.preReciptItemID , 
			LookUps.Name AS SecondTypeName, 
			Recipts.SellsMethod,
			SellsMethods.SellsMethodName, 
			Recipts.SellsEmporium, 
			SellsEmporiums.SellsEmporiumName ,
			ISNULL(Recipts.ArzTypeID,0) AS ArzTypeID ,
			Currencies.CurrenciesName ,
			Ri.ArzRate,
			Ri.ArzAmount,
			Recipts.RialsEqual,
			Ri.Commission , 
			LookUpsItem.Name AS SecondTypeNameItem,
			Ri.DiagnosisCalcTotalPrice,
			Ri.ArzPortage,
			Ri.CurrencyDiscounts,
			Ri.acc_CTopicCode,
			Ri.acc_CTopicCode2,
			Ri.acc_CTopicCode3,
			Ri.RIDateMS,
			Ri.RIDateME,
			Recipts.SecondType , 
			Ri.UnitCommission,
			(Ri.InputEntity + Ri.OutputEntity) * Ri.UnitCommission AS TotallCommission, 
			StuffCoding.n_UnitCode,Ri.SecondTypeItem,StuffCoding.sd1,StuffCoding.Tierced
						  , Recipts.FirstUser, Recipts.LastUser, Recipts.InsertDate, Recipts.ModifyDate, Recipts.ExpireDate,Ri.ItemDate,Recipts.InvoiceTemplate,InvoiceTemplates.InvoiceTemplateName
						   ,UuD.UseUnitName, Ri.UseOtherID_Item,Uo.UseOtherName
						   ,Ri.MachineNo MachineNoD ,Ri.MachineName MachineNameD 
						   ,Ri.acc_TopicCode acc_TopicCodeD,Ri.acc_DetailCode acc_DetailCodeD,Ri.acc_CTopicCode acc_CTopicCodeD,
			Ri.Function1,
			Ri.Waste1,
			Ri.Waste2, 
			SG.GroupName,
			Recipts.TAXID,Recipts.IRTAXID,
			StuffCoding.NationalStuffCode,
			Ri.RequestedWeight

	 FROM	Recipts 
			INNER JOIN ReciptItems Ri ON Recipts.ReciptID = Ri.ReciptID 
										AND Recipts.ServerID = Ri.ServerID 
										AND Recipts.YearID = Ri.YearID 
			INNER JOIN ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType 
			INNER JOIN Stores ON Recipts.StoreID = Stores.n_StoreID 
			INNER JOIN LookUps ON Recipts.SecondType = LookUps.LookUpID 
			LEFT OUTER JOIN  Stores AS Stores_1 ON Recipts.StoreID2 = Stores_1.n_StoreID 
			LEFT OUTER JOIN
				  (
					SELECT	ServerID, 
							YearID, 
							ReciptItemID, 
							ReciptID, 
							SUM(case when EffectAdjustments in (0,1) then RegPrice else 0 end) as RegPrice_Store_1,
							SUM(case when EffectAdjustments in (0,2) then RegPrice else 0 end) as RegPrice_Store_2,
							SUM(RegPrice) AS RegPrice
					FROM	ReciptsRegulates
					GROUP BY 
							ServerID, 
							YearID, 
							ReciptItemID, 
							ReciptID
				) AS Regular ON Ri.ReciptItemID = Regular.ReciptItemID 
											AND Ri.ReciptID = Regular.ReciptID 
											AND Ri.ServerID = Regular.ServerID 
											AND Ri.YearID = Regular.YearID
			LEFT OUTER JOIN SellsEmporiums ON Recipts.SellsEmporium = SellsEmporiums.SellsEmporium  
			LEFT OUTER JOIN SellsMethods ON Recipts.SellsMethod = SellsMethods.SellsMethod 
			CROSS JOIN Config
			LEFT OUTER JOIN Currencies ON ISNULL(Recipts.ArzTypeID,0) = Currencies.CurrenciesID 					  
			LEFT OUTER JOIN LookUps LookUpsItem ON Ri.SecondTypeItem = LookUpsItem.LookUpID
			INNER JOIN StuffCoding ON Ri.StuffCode = StuffCoding.c_StuffCode 
			INNER JOIN InvoiceTemplates ON Recipts.InvoiceTemplate = InvoiceTemplates.InvoiceTemplate
			LEFT OUTER JOIN UseUnits UuD ON Ri.UseUnitID = UuD.UseUnitID  
			LEFT OUTER JOIN UseOthers Uo ON Ri.UseOtherID_Item = Uo.UseOtherID  
			INNER JOIN StuffGroups AS SG ON StuffCoding.GroupID = SG.GroupID
	WHERE	(dbo.ReciptTypes.EffectType IN (4,8)) 
			AND (dbo.ReciptTypes.IncreasingInventoryStore <>0 ) 
	--and (Recipts.ReciptState < 3)
	GO 
	SET QUOTED_IDENTIFIER OFF 
	GO 
