	--
	-- ReciptItems_Stock ReName To ReciptItems_Stock_Calc
	SET QUOTED_IDENTIFIER ON 
	GO 
	SET ANSI_NULLS OFF 
	GO 
	CREATE VIEW ReciptItems_Stock_Calc
	AS
	SELECT	1 AS  UnionKind, 
			dbo.Recipts.ServerID, 
			dbo.Recipts.YearID, 
			dbo.Recipts.ReciptID, 
			dbo.Recipts.StoreID, 
			ReciptItems.StuffCode, 
			dbo.Recipts.ReciptNumber, 
			dbo.Recipts.ReciptDate, 
			dbo.Recipts.PersonID1,  
			ISNULL(dbo.Recipts.PersonID2,0) AS PersonID2, 
			dbo.Recipts.PersonID3,
			ISNULL(ReciptItems.PersonID1,0) AS PersonID1D ,
			ReciptItems.ProductCode,
			case when dbo.ReciptTypes.EffectType= 8 then 4 else dbo.ReciptTypes.EffectType end as  EffectType, 
			dbo.Recipts.ReciptType, 
			dbo.ReciptTypes.ReciptCaption, 
			ReciptItems.StuffSize, 
			ReciptItems.StuffDiameter, 
			ReciptItems.StuffAlloy, 
			ReciptItems.ControlCode, 
			ReciptItems.ItemNote, 
			dbo.Recipts.AidNumber, 
			dbo.Recipts.AidDate,
			case when IneffectiveInput =1 then 0 else  ReciptItems.InputEntity end InputEntity ,
			case when IneffectiveInput =1 then 0 else  ReciptItems.InputWeight end InputWeight,--shajiei
			ReciptItems.OutputEntity, 
			ReciptItems.OutputWeight,	
			ReciptItems.UnitSellPrice, 
			ReciptItems.TotallSellPrice - ISNULL(CASE WHEN ReciptTypes.EffectType = 2 THEN ReciptItems.TaxValue ELSE 0 END, 0) AS TotallSellPrice, 
			Regular.RegPrice,
			isnull(ReciptItems.Portage,0)+ 
				case when IneffectiveInput =1 then 0 else  round((InputWeight + OutputWeight) * isnull(Commission,0),0) end as Portage, 
			ISNULL(ReciptItems.DeficitValue, 0) + ReciptItems.DeficitValue2 + ReciptItems.DeficitValue4 + ReciptItems.DeficitValue3 AS DeficitValue,
			ReciptItems.Article, 
			ReciptItems.Wage, 
			ReciptItems.Scoria,
			ReciptItems.TaxValue, 
			ReciptItems.TaxCo, 
			ReciptItems.RollbackWeight, 
			ReciptItems.AcceptWeight, 
			ReciptItems.AcceptEntity, 
			ReciptItems.RollbackEntity, 
			ReciptItems.TotalStandardRate, 
			ReciptItems.InvWeight, 
			ReciptItems.InvEntity, 
			ReciptItems.ContactRate,
			ReciptItems.TotalInputPrice
				+ ISNULL(CASE WHEN ReciptTypes.EffectType = 2 THEN ISNULL(Regular.RegPrice,0) ELSE 0 END, 0) 
				+ ISNULL(CASE WHEN ReciptTypes.EffectType = 2 THEN ISNULL(ReciptItems.Portage,0) +  (InputEntity + OutputEntity) * UnitCommission
				+ case when IneffectiveInput =1 then 0 else  round((InputWeight + OutputWeight) * isnull(Commission,0),0) end ELSE 0 END, 0) 
				- ISNULL(CASE WHEN ReciptTypes.EffectType = 2 THEN ISNULL(ReciptItems.DeficitValue, 0) + ReciptItems.DeficitValue2 + ReciptItems.DeficitValue4 + ReciptItems.DeficitValue3  ELSE 0 END, 0) 
	--  این خط بخاطر ایجاد مشکل در قیمت گذاری غیر فعال گردید برای قیمت گذاری تخفیف نیاز نیست
	--  دوباره خانم رشیدی و فلاحی گفتن نیاز هست فعال کردم خط بالا رو   USE BPMS_ShaidFaam_2
				+ case when dbo.ReciptTypes.PawsFieldsActive= 4 then isnull(ReciptItems.Article,0 ) else 0 end 
			AS TotalInputPrice, 
			ReciptItems.TotalOutputPrice 
				+ ISNULL(CASE WHEN ReciptTypes.EffectType = 2 THEN 0 ELSE Regular.RegPrice END, 0) 
				+ ISNULL(
						CASE 
							WHEN ReciptTypes.EffectType = 2 THEN 0 
							ELSE 
								isnull(ReciptItems.Portage,0) +  (InputEntity + OutputEntity) * UnitCommission
								+ case 
									when IneffectiveInput =1 then 0 
									else  round((InputWeight + OutputWeight) * isnull(Commission,0),0) 
								  end 
						END, 0) AS TotalOutputPrice,
			ReciptItems.ReciptItemID, 
			dbo.Recipts.ReciptState, 
			dbo.ReciptTypes.SellEffect, 
			ReciptItems.TotalInputPrice AS TotalInputPriceBase,	
			ReciptItems.TotalOutputPrice AS TotalOutputPriceBase,
			ReciptItems.TotallSellPrice AS TotallSellPriceBase, 
			ReciptItems.UseUnitID, ReciptItems.ProductModel, 
			dbo.Recipts.StoreID2, 
			dbo.ReciptTypes.AutoPrice, 
			dbo.Stores.c_StoreName,
			dbo.Stores.n_ValuationType,
			CASE Config.EntityDisplayType	
				WHEN 0 THEN ReciptItems.InputEntity	
				WHEN 1 THEN ReciptItems.InputWeight 
				WHEN 2 THEN 
					CASE 
						WHEN ReciptItems.UnitSellPrice >= Config.EntityOutputLowerLimit	THEN ReciptItems.InputWeight 
						ELSE ReciptItems.InputEntity 
					END 
				WHEN 3 THEN 
					CASE 
						WHEN ReciptTypes.CalculatedEntityOrWeight = 0 THEN
							CASE 
								WHEN ReciptItems.UnitSellPrice >= Config.EntityOutputLowerLimit	THEN ReciptItems.InputEntity 
								ELSE ReciptItems.InputWeight 
							END 
						ELSE 0 
					END 
				ELSE 
					CASE 
						WHEN ReciptItems.DiagnosisCalcTotalPrice = 0 then 
							case when IneffectiveInput =1 then 0 else  ReciptItems.InputEntity end
						else 
						case when IneffectiveInput =1 then 0 else  ReciptItems.InputWeight end 
					end
			END	AS In_Entity, 
			CASE Config.EntityDisplayType	
				WHEN 0 THEN ReciptItems.OutputEntity 
				WHEN 1 THEN ReciptItems.OutputWeight 
				WHEN 2 THEN 
					CASE 
						WHEN ReciptItems.UnitSellPrice >= Config.EntityOutputLowerLimit THEN ReciptItems.OutputWeight 
						ELSE ReciptItems.OutputEntity 
					END
				WHEN 3 THEN 
					CASE 
						WHEN ReciptTypes.CalculatedEntityOrWeight = 0 THEN	
							CASE 
								WHEN ReciptItems.UnitSellPrice >= Config.EntityOutputLowerLimit	THEN ReciptItems.OutputEntity 
								ELSE ReciptItems.OutputWeight 
							END 
						ELSE 0 
					END
				ELSE 
					CASE 
						WHEN ReciptItems.DiagnosisCalcTotalPrice = 0 then ReciptItems.OutputEntity else ReciptItems.OutputWeight end
			END AS Out_Entity,
			ReciptItems.AidNumber AS AidNumberD, 
			ReciptItems.AidDate AS AidDateD, 
			dbo.Recipts.DocNo,
			Recipts.DocDate,
			Recipts.ReciptNote,
			ReciptTypes.IncreasingInventory,
			Recipts.ParentReciptID,
			ReciptTypes.BuyEffect,
			ReciptItems.StuffGrade,
			ReciptItems.preReciptItemID ,
			ReciptItems.PrvYearID, 
			ReciptTypes.CalculatedEntityOrWeight,
			ReciptItems.DiagnosisCalcTotalPrice,
			dbo.Recipts.SellsEmporium,	
			ReciptItems.ItemDate			 
	FROM	dbo.Recipts 
			INNER JOIN dbo.ReciptItems ON dbo.Recipts.ReciptID = ReciptItems.ReciptID 
										AND dbo.Recipts.ServerID = ReciptItems.ServerID 
										AND dbo.Recipts.YearID = ReciptItems.YearID 
			INNER JOIN dbo.ReciptTypes ON dbo.Recipts.ReciptType = dbo.ReciptTypes.ReciptType 
			INNER JOIN dbo.Stores ON dbo.Recipts.StoreID = dbo.Stores.n_StoreID 
			LEFT OUTER JOIN
					(
						SELECT ServerID, 
								YearID, 
								ReciptItemID, 
								ReciptID, 
								SUM(RegPrice) AS RegPrice
						FROM    dbo.ReciptsRegulates
						GROUP BY 
								ServerID, 
								YearID, 
								ReciptItemID, 
								ReciptID
					 ) AS Regular ON ReciptItems.ReciptItemID = Regular.ReciptItemID 
									AND ReciptItems.ReciptID = Regular.ReciptID 
									AND ReciptItems.ServerID = Regular.ServerID 
									AND ReciptItems.YearID = Regular.YearID 
			CROSS JOIN dbo.Config
	WHERE   dbo.ReciptTypes.EffectType IN (2,4,6,7,8)
			AND (dbo.Recipts.ReciptState < 3)  
			AND (dbo.ReciptTypes.IncreasingInventoryStore<>1 ) 
			or 
			(
				dbo.ReciptTypes.EffectType IN (8)
				AND (dbo.ReciptTypes.IncreasingInventoryStore =0) 
				and (dbo.ReciptTypes.IncreasingInventory =0 )
			) 
	-- فرمی که افزاینده و کاهنده موجودی آن بر روی انبار1 تنظیم شده ، در گزارشات باید نمایش شود ولی در قیمت گذاری نباید اثر داشته باشد 
	-- کاهنده و افزاینده موجودی - بدون نمایش انبار 2  
	UNION ALL
	SELECT	2 AS UnionKind, 
			dbo.Recipts.ServerID, 
			dbo.Recipts.YearID, 
			dbo.Recipts.ReciptID, 
			CASE dbo.ReciptTypes.IncreasingInventoryStore 
				WHEN 1 THEN dbo.Recipts.StoreID 
				WHEN 2 THEN dbo.Recipts.StoreID2 
				ELSE 0 
			END AS StoreID, 
			ReciptItems.StuffCode, 
			dbo.Recipts.ReciptNumber, 
			dbo.Recipts.ReciptDate, 
			dbo.Recipts.PersonID1, 
			ISNULL(dbo.Recipts.PersonID2,0) AS PersonID2, 
			dbo.Recipts.PersonID3, 
			ISNULL(ReciptItems.PersonID1,0) AS PersonID1D ,
			ReciptItems.ProductCode,
			CASE dbo.ReciptTypes.EffectType 
				when 4 THEN 2 
				when 7 THEN 6 
				when 8 THEN 2 
				ELSE 2 
			END AS EffectType, 
			dbo.Recipts.ReciptType, 
			dbo.ReciptTypes.ReciptCaption, 
			ReciptItems.StuffSize, 
			ReciptItems.StuffDiameter, 
			ReciptItems.StuffAlloy, 
			ReciptItems.ControlCode, 
			ReciptItems.ItemNote, 
			dbo.Recipts.AidNumber, 
			dbo.Recipts.AidDate, 
			ReciptItems.OutputEntity AS InputEntity, 
			ReciptItems.OutputWeight AS InputWeight, 
			0.0 AS OutputEntity, 
			0.0 AS OutputWeight, 
			ReciptItems.UnitSellPrice, 
			ReciptItems.TotallSellPrice - ISNULL(ReciptItems.TaxValue, 0) AS TotallSellPrice, 
			Regular.RegPrice, 
			ReciptItems.Portage +  (InputEntity + OutputEntity) * UnitCommission
				+ case when IneffectiveInput =1 then 0.0 else  round((InputWeight + OutputWeight) * isnull(Commission,0),0) end as Portage, 

			ISNULL(ReciptItems.DeficitValue, 0) + ReciptItems.DeficitValue2 + ReciptItems.DeficitValue4 + ReciptItems.DeficitValue3 AS DeficitValue ,
			ReciptItems.Article, 
			ReciptItems.Wage, 
			ReciptItems.Scoria, 
			ReciptItems.TaxValue, 
			ReciptItems.TaxCo, 
			ReciptItems.RollbackWeight, 
			ReciptItems.AcceptWeight, 
			ReciptItems.AcceptEntity, 
			ReciptItems.RollbackEntity, 
			ReciptItems.TotalStandardRate, 
			ReciptItems.InvWeight, 
			ReciptItems.InvEntity, 
			ReciptItems.ContactRate, 
			ReciptItems.TotalOutputPrice + ISNULL(Regular.RegPrice, 0) + ISNULL(ReciptItems.Portage, 0) 
				+ (InputEntity + OutputEntity) * UnitCommission
				+ case when IneffectiveInput =1 then 0.0 else  round((InputWeight + OutputWeight) * isnull(Commission,0),0) end 
				+ case when dbo.ReciptTypes.PawsFieldsActive= 4 then isnull(ReciptItems.Article,0 ) else 0 end AS TotalInputPrice, 
			0 AS TotalOutputPrice, 
			ReciptItems.ReciptItemID, 
			dbo.Recipts.ReciptState, 
			dbo.ReciptTypes.SellEffect, 
			ReciptItems.TotalOutputPrice AS TotalInputPriceBase, 
			0 AS TotalOutputPriceBase, 
			ReciptItems.TotallSellPrice AS TotallSellPriceBase, 
			ReciptItems.UseUnitID, 
			ReciptItems.ProductModel, 
			dbo.Recipts.StoreID2, 
			CASE WHEN Stores.n_ValuationType = 9 THEN 1 ELSE 0 END  AS AutoPrice, 
			CASE dbo.ReciptTypes.IncreasingInventoryStore 
				WHEN 1 THEN dbo.Stores.c_StoreName 
				WHEN 2 THEN Stores_1.c_StoreName 
				ELSE '' 
			END AS c_StoreName, 
			dbo.Stores.n_ValuationType, 
			CASE Config.EntityDisplayType 
				WHEN 0 THEN ReciptItems.OutputEntity 
				WHEN 1 THEN ReciptItems.OutputWeight 
				WHEN 2 THEN 
					CASE 
						WHEN ReciptItems.UnitSellPrice	>= Config.EntityOutputLowerLimit THEN ReciptItems.OutputWeight 
						ELSE ReciptItems.OutputEntity 
					END 
				WHEN 3 THEN 
					CASE 
						WHEN ReciptItems.UnitSellPrice >= Config.EntityOutputLowerLimit	THEN ReciptItems.OutputEntity 
						ELSE ReciptItems.OutputWeight 
					END 
				ELSE 0 
			END AS In_Entity, 
			0 AS Out_Entity, 
			ReciptItems.AidNumber AS AidNumberD, 
			ReciptItems.AidDate AS AidDateD, 
			dbo.Recipts.DocNo,
			Recipts.DocDate,
			Recipts.ReciptNote,
			ReciptTypes.IncreasingInventory,
			Recipts.ParentReciptID,
			ReciptTypes.BuyEffect,
			ReciptItems.StuffGrade,
			ReciptItems.preReciptItemID,
			ReciptItems.PrvYearID, 
			ReciptTypes.CalculatedEntityOrWeight,
			ReciptItems.DiagnosisCalcTotalPrice	,
			dbo.Recipts.SellsEmporium,	
			ReciptItems.ItemDate

	FROM	Recipts 
			INNER JOIN  ReciptItems ON Recipts.ReciptID = ReciptItems.ReciptID 
									AND Recipts.ServerID = ReciptItems.ServerID 
									AND Recipts.YearID = ReciptItems.YearID 
			INNER JOIN  ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType 
			INNER JOIN  Stores ON Recipts.StoreID = Stores.n_StoreID 
			LEFT OUTER JOIN  Stores Stores_1 ON Recipts.StoreID2 = Stores_1.n_StoreID 
			LEFT OUTER JOIN  
					(
						SELECT
								ServerID, 
								YearID, 
								ReciptItemID, 
								ReciptID, 
								SUM(RegPrice) AS RegPrice
						FROM    dbo.ReciptsRegulates
						GROUP BY 
								ServerID, 
								YearID, 
								ReciptItemID, 
								ReciptID
					) Regular ON ReciptItems.ReciptItemID = Regular.ReciptItemID 
									AND ReciptItems.ReciptID = Regular.ReciptID 
									AND ReciptItems.ServerID = Regular.ServerID 
									AND ReciptItems.YearID = Regular.YearID 
			CROSS JOIN  Config
	WHERE  dbo.ReciptTypes.EffectType IN (4,7,  8  ) 
			AND (dbo.Recipts.ReciptState < 3) 
			AND (dbo.ReciptTypes.IncreasingInventoryStore =2)
	 -- فرمی که افزاینده و کاهنده موجودی آن بر روی انبار1 تنظیم شده ، در گزارشات باید نمایش شود ولی در قیمت گذاری نباید اثر داشته باشد 

	-- کاهنده و افزاینده موجودی - بدون نمایش انبار 2  
	union all 
	SELECT	3 AS  UnionKind, 
			dbo.Recipts.ServerID, 
			dbo.Recipts.YearID, 
			dbo.Recipts.ReciptID, 
			dbo.Recipts.StoreID ,
			ReciptItems.ProductCode, 
			dbo.Recipts.ReciptNumber, 
			dbo.Recipts.ReciptDate, 
			dbo.Recipts.PersonID1, 
			ISNULL(dbo.Recipts.PersonID2, 0) AS PersonID2, 
			dbo.Recipts.PersonID3, 
			ISNULL(ReciptItems.PersonID1, 0) AS PersonID1D, 
			ReciptItems.ProductCode, 
			CASE dbo.ReciptTypes.EffectType 
				when 4 THEN 2 
				when 7 THEN 6 
				when 8 THEN 2 
				ELSE 2 
			END AS EffectType, 
			dbo.Recipts.ReciptType, 
			dbo.ReciptTypes.ReciptCaption, 
			ReciptItems.StuffSize, 
			ReciptItems.StuffDiameter, 
			ReciptItems.StuffAlloy, 
			ReciptItems.ControlCode, 
			ReciptItems.ItemNote, 
			dbo.Recipts.AidNumber, 
			dbo.Recipts.AidDate, 
			ReciptItems.OutputEntity AS InputEntity, 
			ReciptItems.OutputWeight AS InputWeight, 
			0.0 AS OutputEntity, 
			0.0 AS OutputWeight, 
			ReciptItems.UnitSellPrice, 
			ReciptItems.TotallSellPrice - ISNULL(ReciptItems.TaxValue, 0) AS TotallSellPrice, 
			0 as RegPrice , 
			ReciptItems.Portage+  (InputEntity + OutputEntity) * UnitCommission
				+ case when IneffectiveInput =1 then 0 else  round((InputWeight + OutputWeight) * isnull(Commission,0),0) end as Portage, 
			ReciptItems.DeficitValue+ ReciptItems.DeficitValue2+ ReciptItems.DeficitValue4 + ReciptItems.DeficitValue3 AS DeficitValue,
			ReciptItems.Article, 
			ReciptItems.Wage, 
			ReciptItems.Scoria, 
			ReciptItems.TaxValue, 
			ReciptItems.TaxCo, 
			ReciptItems.RollbackWeight, 
			ReciptItems.AcceptWeight, 
			ReciptItems.AcceptEntity, 
			ReciptItems.RollbackEntity, 
			ReciptItems.TotalStandardRate, 
			ReciptItems.InvWeight, 
			ReciptItems.InvEntity, 
			ReciptItems.ContactRate, 
			ReciptItems.TotalOutputPrice + ISNULL(ReciptItems.Portage, 0) +  (InputEntity + OutputEntity) * UnitCommission
				+ case when IneffectiveInput =1 then 0 else  round((InputWeight + OutputWeight) * isnull(Commission,0),0) end 
				+ case when dbo.ReciptTypes.PawsFieldsActive= 4 then isnull(ReciptItems.Article,0 ) else 0 end AS TotalInputPrice, 
			0 AS TotalOutputPrice, 
			ReciptItems.ReciptItemID, 
			dbo.Recipts.ReciptState, 
			dbo.ReciptTypes.SellEffect, 
			ReciptItems.TotalOutputPrice AS TotalInputPriceBase, 
			0 AS TotalOutputPriceBase, 
			ReciptItems.TotallSellPrice AS TotallSellPriceBase,
			ReciptItems.UseUnitID, 
			ReciptItems.ProductModel, 
			dbo.Recipts.StoreID2, 
			0 AS AutoPrice, 
			c_StoreName, 
			dbo.Stores.n_ValuationType, 
			CASE Config.EntityDisplayType 
				WHEN 0 THEN ReciptItems.OutputEntity 
				WHEN 1 THEN ReciptItems.OutputWeight 
				WHEN 2 THEN 
					CASE 
						WHEN ReciptItems.UnitSellPrice >= Config.EntityOutputLowerLimit THEN ReciptItems.OutputWeight 
						ELSE ReciptItems.OutputEntity 
					END 
				WHEN 3 THEN
					CASE 
						WHEN ReciptItems.UnitSellPrice >= Config.EntityOutputLowerLimit THEN ReciptItems.OutputEntity 
						ELSE ReciptItems.OutputWeight 
					END
				ELSE 0 
			END AS In_Entity, 
			0 AS Out_Entity, 
			ReciptItems.AidNumber AS AidNumberD, 
			ReciptItems.AidDate AS AidDateD, 
			dbo.Recipts.DocNo, 
			Recipts.DocDate, 
			Recipts.ReciptNote, 
			ReciptTypes.IncreasingInventory, 
			Recipts.ParentReciptID  ,
			ReciptTypes.BuyEffect,
			ReciptItems.StuffGrade,
			ReciptItems.preReciptItemID,
			ReciptItems.PrvYearID, 
			ReciptTypes.CalculatedEntityOrWeight,
			ReciptItems.DiagnosisCalcTotalPrice,
			dbo.Recipts.SellsEmporium,	
			ReciptItems.ItemDate
	FROM    Recipts 
			INNER JOIN ReciptItems ON Recipts.ReciptID = ReciptItems.ReciptID 
								AND Recipts.ServerID = ReciptItems.ServerID 
								AND Recipts.YearID = ReciptItems.YearID 
			INNER JOIN ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType 
			INNER JOIN Stores ON Recipts.StoreID = Stores.n_StoreID  
			CROSS JOIN Config
	WHERE	dbo.ReciptTypes.EffectType IN (8) 
			AND dbo.Recipts.ReciptState < 3
			AND dbo.ReciptTypes.IncreasingInventoryStore =0 
			and dbo.ReciptTypes.IncreasingInventory =0 
-- end of 
--  

	GO 

-- Start of ReciptItems_Stock 
	CREATE VIEW ReciptItems_Stock
	AS
	SELECT	R.ServerID, 
			R.YearID, 
			R.ReciptID, 
			R.StoreID, 
			Ri.StuffCode, 
			R.ReciptNumber, 
			R.ReciptDate, 
			R.PersonID1, 
			ISNULL(R.PersonID2, 0) AS PersonID2, 
			R.PersonID3, 
			R.PersonID4, 
			ISNULL(Ri.PersonID1, 0) AS PersonID1D, 
			Ri.ProductCode, 
			T.EffectType, 
			R.ReciptType, 
			T.ReciptCaption, 
			Ri.StuffSize, 
			Ri.StuffDiameter, 
			Ri.StuffAlloy, 
			Ri.ControlCode, 
			Ri.ItemNote, 
			R.AidNumber, 
			R.AidDate, 
			case when IneffectiveInput =1 then 0 else  Ri.InputEntity end InputEntity,	
			case when IneffectiveInput =1 then 0 else  Ri.InputWeight end InputWeight, 
			Ri.OutputEntity, 
			Ri.OutputWeight,
			--, Ri.UnitSellPrice as UnitSellPrice
			case 
				when isnull(Ri.Portage,0) <> 0 and IncreasingInventoryStore =1 then 
					case 
						when (Ri.OutputEntity + Ri.OutputWeight ) <> 0 then  
							Ri.TotallSellPrice / 
							CASE C.EntityDisplayType	
								WHEN 0 THEN Ri.OutputEntity 
								WHEN 1 THEN Ri.OutputWeight 
								WHEN 2 THEN 
									CASE WHEN Ri.UnitSellPrice >= C.EntityOutputLowerLimit THEN Ri.OutputWeight ELSE Ri.OutputEntity END 
								WHEN 3 THEN 
									CASE 
										WHEN Ri.UnitSellPrice >= C.EntityOutputLowerLimit THEN 
											case when IneffectiveInput =1 then 0.0 else  Ri.OutputEntity end 
										ELSE 
											case when IneffectiveInput =1 then 0.0 else  Ri.OutputWeight  end 
									END 
								ELSE 0 
							END 
						else Ri.UnitSellPrice 
					end 
				else Ri.UnitSellPrice 
			end  as UnitSellPrice,
			Ri.TotallSellPrice - ISNULL(CASE WHEN T.EffectType = 2 THEN Ri.TaxValue ELSE 0 END, 0) AS TotallSellPrice, 
			isnull(Ri.Portage,0) 
				+ case when IneffectiveInput =1 then 0 else  round((InputWeight + OutputWeight) * isnull(Commission,0),0) end as Portage , 
			isnull(Ri.DeficitValue,0)+ isnull(Ri.DeficitValue2,0) + isnull(Ri.DeficitValue4,0)+ isnull(Ri.DeficitValue3,0) AS DeficitValue,
			Ri.Article, Ri.Wage, Ri.Scoria, Ri.TaxValue, Ri.TaxCo,
			Ri.RollbackWeight, Ri.AcceptWeight, Ri.AcceptEntity, Ri.RollbackEntity, Ri.TotalStandardRate, Ri.InvWeight, 
			Ri.InvEntity, Ri.ContactRate, 
			Ri.TotalInputPrice  
				- 
				case 
					when C.ActiveSellPrice2 = 0 then 
						ISNULL(
								CASE 
									WHEN T.EffectType in (2,6) THEN Ri.DeficitValue+ Ri.DeficitValue2 + Ri.DeficitValue4 + Ri.DeficitValue3  
									ELSE 0 
								END, 0)
		    		else 0 
				end  
				+ ISNULL(
						CASE 
							WHEN T.EffectType  in (2,6) THEN isnull(Ri.Portage ,0)
								+ 
								case 
									when IneffectiveInput =1 then 0 
									else  round((isnull(InputWeight,0) + isnull(OutputWeight,0)) * isnull(Commission,0),0) 
									end 
							ELSE 0 
						END, 0) 
				+ case when T.PawsFieldsActive in (4,7,  8  ) then isnull(Ri.Article,0 ) else 0 end
				+ InputEntity * UnitCommission 
			AS TotalInputPrice, 
			Ri.TotalOutputPrice + case when  IncreasingInventoryStore = 1  then  isnull(Ri.Portage,0) else 0 end AS TotalOutputPrice, 
			Ri.ReciptItemID, 
			R.ReciptState, 
			T.SellEffect, 
			Ri.TotalInputPrice AS TotalInputPriceBase, 
			Ri.TotalOutputPrice AS TotalOutputPriceBase, 
			Ri.TotallSellPrice AS TotallSellPriceBase, 
			Ri.UseUnitID,
			R.UseUnitID AS ReciptUseUnitID, 
			Ri.ProductModel, 
			R.StoreID2, 
			T.AutoPrice, 
			S.c_StoreName, 
			S.n_ValuationType, 
			CASE C.EntityDisplayType	
				WHEN 0 THEN Ri.InputEntity 
				WHEN 1 THEN Ri.InputWeight 
				WHEN 2 THEN 
					CASE WHEN Ri.UnitSellPrice >= C.EntityOutputLowerLimit THEN Ri.InputWeight ELSE Ri.InputEntity END 
				WHEN 3 THEN 
					CASE WHEN Ri.UnitSellPrice >= C.EntityOutputLowerLimit THEN 
							case when IneffectiveInput =1 then 0.0 else  Ri.InputEntity end 
							ELSE 
							case when IneffectiveInput =1 then 0.0 else  Ri.InputWeight end 
					END 
				ELSE 0 
			END AS In_Entity, 
			CASE C.EntityDisplayType	
				WHEN 0 THEN Ri.OutputEntity 
				WHEN 1 THEN Ri.OutputWeight 
				WHEN 2 THEN 
					CASE WHEN Ri.UnitSellPrice >= C.EntityOutputLowerLimit THEN Ri.OutputWeight ELSE Ri.OutputEntity END 
				WHEN 3 THEN 
					CASE WHEN Ri.UnitSellPrice >= C.EntityOutputLowerLimit THEN Ri.OutputEntity ELSE Ri.OutputWeight END
				ELSE 0.0 
			END	AS Out_Entity,
			Ri.AidNumber AS AidNumberD, 
			Ri.AidDate AS AidDateD, 
			R.DocNo, 
			R.DocDate, 
			R.ReciptNote, 
			T.IncreasingInventory, 
			R.ParentReciptID ,
			Ri.TotalInputPrice - Ri.TotalInputPrice as RegPrice ,
			R.SecondType , 
			isnull(S2.c_StoreName,'') AS c_StoreName2,
			Ri.SecondTypeItem,
			T.BuyEffect, 
			Ri.ID,Ri.ItemDate,
			Ri.StuffGrade, 
			Ri.Commission,
			Ri.DiagnosisCalcTotalPrice,
			C.EntityDisplayType,
			R.SellsEmporium ,
			Ri.SpecialCode,
			Ri.UseOtherID_Item,
			Ri.UnitCommission,
			Ri.UseUnitID AS UseUnitIDD, 
			R.UseOtherID,
			Ri.acc_TopicCode,
			Ri.acc_DetailCode,
			Ri.RequestedWeight

	FROM	dbo.Recipts R 
			INNER JOIN 	dbo.ReciptItems Ri ON R.ReciptID = Ri.ReciptID 
												AND R.ServerID = Ri.ServerID 
												AND R.YearID = Ri.YearID 
			INNER JOIN dbo.ReciptTypes T ON R.ReciptType = T.ReciptType 
			INNER JOIN dbo.Stores S ON R.StoreID = S.n_StoreID 
			LEFT OUTER JOIN Stores S2 ON R.StoreID2 = S2.n_StoreID 
			CROSS JOIN	dbo.Config C
	WHERE    (T.EffectType IN (2, 4, 6, 7,  8  )) AND (R.ReciptState < 3)

	UNION ALL

	SELECT	R.ServerID, 
			R.YearID, 
			R.ReciptID, 
			CASE T.IncreasingInventoryStore WHEN 1 THEN R.StoreID WHEN 2 THEN R.StoreID2 ELSE 0 END AS StoreID,
			Ri.StuffCode, 
			R.ReciptNumber, 
			R.ReciptDate, 
			R.PersonID1, 
			ISNULL(R.PersonID2, 0) 
			AS PersonID2, 
			R.PersonID3, 
			R.PersonID4, 
			ISNULL(Ri.PersonID1, 0) AS PersonID1D, 
			Ri.ProductCode, 
			CASE T.EffectType 
			when 4 THEN 2 
			when 7 THEN 6 
			when 8 THEN 2 
			ELSE 2 END AS EffectType,  
			R.ReciptType, 
			T.ReciptCaption, 
			Ri.StuffSize, 
			Ri.StuffDiameter, 
			Ri.StuffAlloy, 
			Ri.ControlCode, 
			Ri.ItemNote, 
			R.AidNumber, 
			R.AidDate, 
			Ri.OutputEntity AS InputEntity, 
			Ri.OutputWeight AS InputWeight, 
			0.0 AS OutputEntity, 
			0.0 AS OutputWeight, 
			Ri.UnitSellPrice, 
			Ri.TotallSellPrice - ISNULL(Ri.TaxValue, 0) AS TotallSellPrice, 
			isnull(Ri.Portage,0)+ case when IneffectiveInput =1 then 0 else  round((InputWeight + OutputWeight) * isnull(Commission,0),0) end as Portage, 
			Ri.DeficitValue+ Ri.DeficitValue2 + Ri.DeficitValue4 + Ri.DeficitValue3 AS DeficitValue,
			Ri.Article, 
			Ri.Wage, 
			Ri.Scoria, 
			Ri.TaxValue, 
			Ri.TaxCo, 
			Ri.RollbackWeight, 
			Ri.AcceptWeight, 
			Ri.AcceptEntity, 
			Ri.RollbackEntity, 
			Ri.TotalStandardRate, 
			Ri.InvWeight, 
			Ri.InvEntity, 
			Ri.ContactRate, 
			Ri.TotalOutputPrice + 
			-----------
				--	 ISNULL(Regular.RegPrice, 0) + --- dar tarikh 950304 disable shod 
			-----------
			ISNULL(Ri.Portage, 0) 
				+ case when IneffectiveInput =1 then 0 else  round((InputWeight + OutputWeight) * isnull(Commission,0),0) end 
				+ case when T.PawsFieldsActive= 4 then isnull(Ri.Article,0 ) else 0 end AS TotalInputPrice, 0 AS TotalOutputPrice, 
			Ri.ReciptItemID, 
			R.ReciptState, 
			T.SellEffect, 
			Ri.TotalOutputPrice AS TotalInputPriceBase, 
			0 AS TotalOutputPriceBase, 
			Ri.TotallSellPrice AS TotallSellPriceBase,
			Ri.UseUnitID,
			R.UseUnitID AS ReciptUseUnitID, 
			Ri.ProductModel, 
			R.StoreID2, 
			0 AS AutoPrice, 
			CASE T.IncreasingInventoryStore WHEN 1 THEN S.c_StoreName WHEN 2 THEN S2.c_StoreName ELSE '' END AS c_StoreName, 
			S.n_ValuationType, 
			CASE C.EntityDisplayType 
				WHEN 0 THEN Ri.OutputEntity 
				WHEN 1 THEN Ri.OutputWeight 
				WHEN 2 THEN 
					CASE WHEN Ri.UnitSellPrice >= C.EntityOutputLowerLimit THEN Ri.OutputWeight ELSE Ri.OutputEntity END 
				WHEN 3 THEN
					CASE WHEN Ri.UnitSellPrice >= C.EntityOutputLowerLimit THEN Ri.OutputEntity ELSE Ri.OutputWeight END
				ELSE 0.0 
			END AS In_Entity, 
			0 AS Out_Entity, 
			Ri.AidNumber AS AidNumberD, 
			Ri.AidDate AS AidDateD, 
			R.DocNo, 
			R.DocDate, 
			R.ReciptNote, 
			T.IncreasingInventory, 
			R.ParentReciptID , 
			0 as RegPrice ,
			R.SecondType , 
			S.c_StoreName  AS c_StoreName2,
			Ri.SecondTypeItem,
			T.BuyEffect,Ri.ID,
			Ri.ItemDate,Ri.StuffGrade, 
			Ri.Commission,
			Ri.DiagnosisCalcTotalPrice,
			C.EntityDisplayType	,
			R.SellsEmporium,
			Ri.SpecialCode,
			Ri.UseOtherID_Item,
			Ri.UnitCommission,
			Ri.UseUnitID AS UseUnitIDD, 
			R.UseOtherID,
			Ri.acc_TopicCode,
			Ri.acc_DetailCode,
			Ri.RequestedWeight

	FROM	Recipts R 
			INNER JOIN ReciptItems Ri ON R.ReciptID = Ri.ReciptID 
						AND R.ServerID = Ri.ServerID 
						AND R.YearID = Ri.YearID 
			INNER JOIN ReciptTypes T ON R.ReciptType = T.ReciptType 
			INNER JOIN Stores S ON R.StoreID = S.n_StoreID 
			LEFT OUTER JOIN	Stores S2 ON R.StoreID2 = S2.n_StoreID 
	 ------------
	 ---						 LEFT OUTER JOIN
	 ---                            (SELECT        ServerID, YearID, ReciptItemID, ReciptID, SUM(RegPrice) AS RegPrice
	 ---                               FROM            dbo.ReciptsRegulates
	 ---                               GROUP BY ServerID, YearID, ReciptItemID, ReciptID) Regular ON Ri.ReciptItemID = Regular.ReciptItemID AND 
	 ---                        Ri.ReciptID = Regular.ReciptID AND Ri.ServerID = Regular.ServerID AND Ri.YearID = Regular.YearID 
	 ------------
			CROSS JOIN	Config C
	WHERE   T.EffectType IN (4, 7,  8  ) 
			AND (R.ReciptState < 3) 
			AND (T.IncreasingInventoryStore <>0)

	----------------------------- خاص تعديلات 
	union all 
	SELECT	R.ServerID, 
			R.YearID, 
