			Ri.StuffGrade, 
			Ri.Commission,
			Ri.DiagnosisCalcTotalPrice,
			C.EntityDisplayType,
			R.SellsEmporium,
			Ri.SpecialCode,
			Ri.UseOtherID_Item,
			Ri.UnitCommission,
			Ri.UseUnitID AS UseUnitIDD, 
			R.UseOtherID,
			Ri.acc_TopicCode,
			Ri.acc_DetailCode,
			Ri.RequestedWeight

	FROM    dbo.ReciptItems Ri 
			INNER JOIN dbo.Recipts R  ON R.ReciptID = Ri.ReciptID 
										AND R.ServerID = Ri.ServerID 
										AND R.YearID = Ri.YearID 
			INNER JOIN dbo.ReciptTypes T ON R.ReciptType = T.ReciptType 
			INNER JOIN dbo.Stores S ON R.StoreID = S.n_StoreID 
			inner JOIN
					(
						SELECT 
							ServerID, 
							YearID, 
							ReciptItemID, 
							ReciptID, 
							RegDate,
							SUM(RegPrice) AS RegPrice
						FROM  ReciptsRegulates
						where EffectAdjustments in (0,1)
						GROUP BY 
							ServerID, 
							YearID, 
							ReciptItemID, 
							ReciptID,
							RegDate
					) AS Regular ON Ri.ReciptItemID = Regular.ReciptItemID 
								AND Ri.ReciptID = Regular.ReciptID 
								AND Ri.ServerID = Regular.ServerID 
								AND Ri.YearID = Regular.YearID 
		  CROSS JOIN dbo.Config C
	WHERE  T.EffectType IN (2, 4, 6, 7,  8 ) 
			AND R.ReciptState < 3
	UNION ALL
	SELECT	R.ServerID, 
			R.YearID, 
			R.ReciptID, 
			CASE T.IncreasingInventoryStore WHEN 1 THEN R.StoreID WHEN 2 THEN R.StoreID2 ELSE 0 END AS StoreID,
			Ri.StuffCode, 
			R.ReciptNumber, 
			regdate as ReciptDate, 
			R.PersonID1, 
			ISNULL(R.PersonID2, 0) AS PersonID2, 
			R.PersonID3,
			R.PersonID4, 
			ISNULL(Ri.PersonID1, 0) AS PersonID1D, 
			Ri.ProductCode, 
			CASE T.EffectType 
				when 4 THEN 2 
				when 7 THEN 6 
				when 8 THEN 2 
				ELSE 2 
			END AS EffectType, 
			R.ReciptType,
			' تعدیل '+    T.ReciptCaption ReciptCaption , 
			Ri.StuffSize, 
			Ri.StuffDiameter, 
			Ri.StuffAlloy, 
			Ri.ControlCode, 
			Ri.ItemNote, 
			R.AidNumber, 
			R.AidDate, 
			0.0 AS InputEntity, 
			0.0 AS InputWeight, 
			0.0 AS OutputEntity, 
			0.0 AS OutputWeight, 
			0 as UnitSellPrice, 
			0 AS TotallSellPrice,
			0 as Portage, 
			0 as DeficitValue, 
			0 AS Article,  
			0 AS Wage, 
			0 AS Scoria, 
			0 as TaxValue, 
			Ri.TaxCo, 
			0.0 AS RollbackWeight,  
