			0 AS AcceptEntity, 
			0 AS RollbackEntity, 
			0 AS TotalStandardRate,  
			0.0 AS InvWeight,  
			0 AS InvEntity, 
			Ri.ContactRate,  
			CASE T.IncreasingInventoryStore 
				WHEN 1 THEN ISNULL(Regular.RegPrice_Store_1, 0) 
				WHEN 2 THEN ISNULL(Regular.RegPrice_Store_2, 0) 
				ELSE 0 
			END AS TotalInputPrice, 
			0 AS TotalOutputPrice,
			Ri.ReciptItemID, 
			R.ReciptState, 
