			Ri.UnitCommission,
			Ri.UseUnitID AS UseUnitIDD, 
			R.UseOtherID,
			Ri.acc_TopicCode,
			Ri.acc_DetailCode,
			Ri.RequestedWeight

	FROM    ReciptItems Ri 
			INNER JOIN Recipts R ON R.ReciptID = Ri.ReciptID 
								AND R.ServerID = Ri.ServerID 
								AND R.YearID = Ri.YearID 
			INNER JOIN ReciptTypes T ON R.ReciptType = T.ReciptType 
			INNER JOIN Stores S ON R.StoreID = S.n_StoreID 
			LEFT OUTER JOIN	 Stores S2 ON R.StoreID2 = S2.n_StoreID 
			INNER  JOIN
				(
					SELECT	ServerID, 
							YearID, 
							ReciptItemID, 
							ReciptID, 
							RegDate,
							SUM(case when EffectAdjustments in (0,1) then RegPrice else 0 end) as RegPrice_Store_1,
							SUM(case when EffectAdjustments in (0,2) then RegPrice else 0 end) as RegPrice_Store_2,
							SUM(RegPrice) AS RegPrice
					FROM	ReciptsRegulates
					GROUP BY 
							ServerID, 
							YearID, 
							ReciptItemID, 
							ReciptID,
							RegDate
				) AS Regular ON Ri.ReciptItemID = Regular.ReciptItemID AND 
							 Ri.ReciptID = Regular.ReciptID 
							 AND Ri.ServerID = Regular.ServerID 
							 AND Ri.YearID = Regular.YearID 
			CROSS JOIN Config C
	WHERE   T.EffectType IN (4, 7,  8 )
			AND (R.ReciptState < 3) 
			AND (T.IncreasingInventoryStore<>0)
	---------------------------  پايان خاص تعديلات 
	----------------------------- کاهنده و افزاینده موجودی - بدون نمایش انبار 2  
	union all 
	SELECT	R.ServerID, 
			R.YearID, 
			R.ReciptID, 
			R.StoreID ,
			Ri.ProductCode, 
			R.ReciptNumber, 
			R.ReciptDate, 
			R.PersonID1, 
			ISNULL(R.PersonID2, 0) AS PersonID2, 
			R.PersonID3,
			R.PersonID4, 
			ISNULL(Ri.PersonID1, 0) AS PersonID1D, 
			Ri.ProductCode, 
			CASE T.EffectType 
				when 4 THEN 2 
				when 7 THEN 6 
				when 8 THEN 2 
				ELSE 2 
			END AS EffectType, 
			R.ReciptType, 
			T.ReciptCaption, 
			Ri.StuffSize, 
			Ri.StuffDiameter, 
			Ri.StuffAlloy, 
			Ri.ControlCode, 
			Ri.ItemNote, 
			R.AidNumber, 
			R.AidDate, 
			Ri.OutputEntity AS InputEntity, 
			Ri.OutputWeight AS InputWeight, 
			0.0 AS OutputEntity, 
			0.0 AS OutputWeight, 
			Ri.UnitSellPrice, 
			Ri.TotallSellPrice - ISNULL(Ri.TaxValue, 0) AS TotallSellPrice, 
			isnull(Ri.Portage,0), 
			Ri.DeficitValue+ Ri.DeficitValue2 + Ri.DeficitValue4 + Ri.DeficitValue3 AS DeficitValue,
			Ri.Article, 
			Ri.Wage, 
			Ri.Scoria, 
			Ri.TaxValue, 
			Ri.TaxCo, 
			Ri.RollbackWeight, 
			Ri.AcceptWeight, 
			Ri.AcceptEntity, 
			Ri.RollbackEntity, 
			Ri.TotalStandardRate, 
			Ri.InvWeight, 
			Ri.InvEntity, 
			Ri.ContactRate, 
			Ri.TotalOutputPrice 
				+ ISNULL(Ri.Portage, 0)  
				+ case when IneffectiveInput =1 then 0.0 else  round((InputWeight + OutputWeight) * isnull(Commission,0),0) end 
				+ isnull(Ri.Article,0 ) AS TotalInputPrice, 
			0 AS TotalOutputPrice, 
			Ri.ReciptItemID, 
			R.ReciptState, 
			T.SellEffect, 
			Ri.TotalOutputPrice AS TotalInputPriceBase, 
			0 AS TotalOutputPriceBase, 
			Ri.TotallSellPrice AS TotallSellPriceBase,
			Ri.UseUnitID,
			R.UseUnitID AS ReciptUseUnitID, 
			Ri.ProductModel, 
			R.StoreID2, 
			0 AS AutoPrice, 
			c_StoreName, 
			S.n_ValuationType, 
			CASE C.EntityDisplayType 
				WHEN 0 THEN Ri.OutputEntity 
				WHEN 1 THEN Ri.OutputWeight 
				WHEN 2 THEN 
					CASE WHEN Ri.UnitSellPrice >= C.EntityOutputLowerLimit THEN Ri.OutputWeight ELSE Ri.OutputEntity END 
				WHEN 3 THEN
					CASE WHEN Ri.UnitSellPrice >= C.EntityOutputLowerLimit THEN Ri.OutputEntity ELSE Ri.OutputWeight END
				ELSE 0.0 
			END AS In_Entity, 
			0 AS Out_Entity, 
			Ri.AidNumber AS AidNumberD, 
			Ri.AidDate AS AidDateD, 
			R.DocNo, 
			R.DocDate, 
			R.ReciptNote, 
			T.IncreasingInventory, 
			R.ParentReciptID , 
			0 as RegPrice ,
			R.SecondType , 
			S.c_StoreName  AS c_StoreName2,
			Ri.SecondTypeItem,
			T.BuyEffect,
			Ri.ID,
			Ri.ItemDate,
			Ri.StuffGrade,
			Ri.Commission,
			Ri.DiagnosisCalcTotalPrice,
			C.EntityDisplayType,
			R.SellsEmporium,
			Ri.SpecialCode,
			Ri.UseOtherID_Item,
			Ri.UnitCommission,
			Ri.UseUnitID AS UseUnitIDD, 
			R.UseOtherID,
			Ri.acc_TopicCode,
			Ri.acc_DetailCode,
			Ri.RequestedWeight

	FROM    ReciptItems Ri 
			INNER JOIN Recipts R ON R.ReciptID = Ri.ReciptID 
									AND R.ServerID = Ri.ServerID 
									AND R.YearID = Ri.YearID 
			INNER JOIN ReciptTypes T ON R.ReciptType = T.ReciptType 
			INNER JOIN Stores S ON R.StoreID = S.n_StoreID  
			CROSS JOIN Config C
	WHERE	T.EffectType IN (8)
			AND R.ReciptState < 3
			AND T.IncreasingInventoryStore =0 
			and T.IncreasingInventory =0 

	GO 


	-- CREATE VIEW AvailableEntity
	CREATE VIEW AvailableEntity
	AS
	SELECT	ReciptItemID, 
			SUM(Entity) AS Entity, 
			SUM(Weight) AS Weight, 
			SUM(Price) AS Price, 
			SUM(TotallSellPrice) AS TotallSellPrice
	FROM   (
				SELECT	ReciptItemID, 
						InputEntity - OutputEntity AS Entity, 
						InputWeight - OutputWeight AS Weight, 
						TotalInputPrice - TotalOutputPrice AS Price, 
						TotallSellPrice
				FROM         ReciptItems
				UNION ALL
				SELECT	preReciptItemID, 
						- InputEntity - OutputEntity AS Entity, 
						- InputWeight - OutputWeight AS Weight, 
						TotalInputPrice - TotalOutputPrice AS Price, 
						TotallSellPrice
				FROM ReciptItems
				WHERE     preReciptItemID > 0
			) AvailableEntityWeight
	GROUP BY ReciptItemID

	GO 

--	CREATE VIEW AvailAbleSpecialEntity

	CREATE VIEW AvailAbleSpecialEntity
	AS
	SELECT     SUM(entity) AS entity, SUM(weight) AS weight, SUM(Price) AS price
	FROM         (SELECT     ReciptItems.ReciptItemID, ReciptItems.InputEntity + ReciptItems.OutputEntity  AS entity, 
					ReciptItems.InputWeight +ReciptItems.OutputWeight AS weight, 
					ReciptItems.TotalInputPrice+ ReciptItems.TotalOutputPrice AS Price
							FROM         ReciptItems INNER JOIN
												  Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
												  ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
							WHERE     (ReciptTypes.EffectType in( 2,6,  8  ) )
							UNION ALL
							SELECT     ReciptItems.preReciptItemID, - ReciptItems.OutputEntity, - ReciptItems.OutputWeight, 
												  - ReciptItems.TotalOutputPrice
							FROM         ReciptItems INNER JOIN
												  Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
												  ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
							WHERE     (ReciptItems.preReciptItemID > 0) AND (ReciptTypes.EffectType in( 4,7,  8  )) --AND ReciptItems.ReciptItemID <> 55
							)    SpecialEntity
	WHERE     (ReciptItemID > 0)
	GO 
