	CREATE VIEW Calculate
	AS
	SELECT     TOP 100 PERCENT Recipts.ReciptType, ReciptItems.OutputEntity, ReciptItems.OutputWeight, ReciptItems.TotalOutputPrice, 
						  ReciptItems_1.InputEntity, ReciptItems_1.InputWeight, ReciptItems_1.TotalInputPrice, 
						  ROUND(ReciptItems_1.TotalInputPrice / ReciptItems_1.InputWeight, 0) AS price1, ReciptItems.StuffCode, 
						  ROUND(ReciptItems_1.TotalInputPrice / ReciptItems_1.InputWeight * ReciptItems.OutputWeight, 0) AS Sumprice, 
						  ReciptItems.UnitSellPrice
	FROM         ReciptItems LEFT OUTER JOIN
						  Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID LEFT OUTER JOIN
						  ReciptItems ReciptItems_1 ON ReciptItems.preReciptItemID = ReciptItems_1.ReciptItemID
	WHERE     (Recipts.ReciptType = 11) AND (ReciptItems.StuffCode <> 1181) AND (ReciptItems.StuffCode <> 1201) AND 
						  (ReciptItems.StuffCode <> 1191) AND (ReciptItems.StuffCode <> 1211) AND (ReciptItems.StuffCode <> 1294) AND 
						  (ReciptItems.StuffCode <> 1151)
	GO 
