	CREATE VIEW cashTransactionCust
	AS
	SELECT     *
	FROM         (SELECT     FormItems.CustomerID2, Forms.FormID, Forms.FormType, Forms.FormNumber, Forms.FormDate, FormTypes.FormCaption, 
											  isnull(Forms.FomNote,'') AS ItemNote, FormItems.ItemAmount AS bed, 0 AS bes, 2 AS kind, 
											  --+' '+   'چك شماره ' + FormItems.CheckNumber + 'سررسيد' + FormItems.CheckDate
												  Forms.CustomerID1 AS CustForShowForm
												  , Forms.ServerID, Forms.YearID
							FROM         Forms INNER JOIN
												  FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
												  FormItems ON Forms.FormID = FormItems.FormID and Forms.ServerID = FormItems.ServerID and Forms.YearID = FormItems.YearID  
							WHERE     (FormTypes.BedBes = 0) AND (FormTypes.Customer2DocType = 10) AND (FormTypes.DetailDataType = 3)
							UNION ALL
							SELECT     Forms.CustomerID1, Forms.FormID, Forms.FormType, Forms.FormNumber, Forms.FormDate, 
												  FormTypes.FormCaption, Forms.FomNote, 0 AS bed, Forms.Amount AS bes, 1 AS kind, 
												  Forms.CustomerID1 AS CustForShowForm
												, Forms.ServerID, Forms.YearID
								  FROM         Forms INNER JOIN
												  FormTypes ON Forms.FormType = FormTypes.FormType
							WHERE     (FormTypes.BedBes = 0) AND (FormTypes.Customer1DocType = 10) AND (FormTypes.DisplayFormType in(0,7)) AND 
												  (Forms.FormState < 10)
							UNION ALL
							SELECT     Forms.CustomerID1, Forms.FormID, Forms.FormType, Forms.FormNumber, Forms.FormDate, 
												  FormTypes.FormCaption, Forms.FomNote, Forms.Amount AS bed, 0 AS bes, 1 AS kind, 
												  Forms.CustomerID1 AS CustForShowForm
												  , Forms.ServerID, Forms.YearID
							FROM         Forms INNER JOIN
												  FormTypes ON Forms.FormType = FormTypes.FormType
							WHERE     (FormTypes.BedBes = 1) AND (FormTypes.Customer1DocType = 10) AND (FormTypes.DisplayFormType in(0,7)) AND 
												  (Forms.FormState < 10)
							UNION ALL
							SELECT     Forms.CustomerID2, Forms.FormID, Forms.FormType, Forms.FormNumber, Forms.FormDate, 
												  FormTypes.FormCaption, Forms.FomNote, Forms.Amount AS bed, 0 AS bes, 1 AS kind, 
												  Forms.CustomerID1 AS CustForShowForm
												  , Forms.ServerID, Forms.YearID
							FROM         Forms INNER JOIN
												  FormTypes ON Forms.FormType = FormTypes.FormType
							WHERE     (FormTypes.BedBes = 0) AND (FormTypes.DisplayFormType in(0,7)) AND (FormTypes.Customer2DocType = 10) AND 
												  (Forms.FormState < 10)
							UNION ALL
							SELECT     Forms.CustomerID2, Forms.FormID, Forms.FormType, Forms.FormNumber, Forms.FormDate, 
												  FormTypes.FormCaption, Forms.FomNote, 0 AS bed, Forms.Amount AS bes, 1 AS kind, 
												  Forms.CustomerID1 AS CustForShowForm
												  , Forms.ServerID, Forms.YearID
							FROM         Forms INNER JOIN
												  FormTypes ON Forms.FormType = FormTypes.FormType
							WHERE     (FormTypes.BedBes = 1) AND (FormTypes.DisplayFormType in(0,7)) AND (FormTypes.Customer2DocType = 10) AND 
												  (Forms.FormState < 10)
							UNION ALL
							SELECT     Forms.CustomerID1, Forms.FormID, Forms.FormType, Forms.FormNumber, Forms.FormDate, 
												  FormTypes.FormCaption,isnull(Forms.FomNote,'') AS ItemNote, 0 AS bed, 
												  --+' '+ 'چك شماره ' + FormItems.CheckNumber + 'سررسيد' + FormItems.CheckDate
												  FormItems.ItemAmount AS bes, 2 AS kind, Forms.CustomerID1 AS CustForShowForm
												  , Forms.ServerID, Forms.YearID
							FROM         Forms INNER JOIN
												  FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
												  FormItems ON Forms.FormID = FormItems.FormID and Forms.ServerID = FormItems.ServerID and Forms.YearID = FormItems.YearID
							WHERE     (FormTypes.BedBes = 1) AND (FormTypes.Customer1DocType = 10) AND (Forms.FormState < 10)
							UNION ALL
							SELECT     Forms.CustomerID1, Forms.FormID, Forms.FormType, Forms.FormNumber, Forms.FormDate, 
												  FormTypes.FormCaption,isnull(Forms.FomNote,'')--+' '+ 'چك شماره ' + FormItems.CheckNumber + 'سررسيد' + FormItems.CheckDate
												   AS ItemNote, 
												  FormItems.ItemAmount AS bed, 0 AS bes, 2 AS kind, Forms.CustomerID1 AS CustForShowForm
												  , Forms.ServerID, Forms.YearID
							FROM         Forms INNER JOIN
												  FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
												  FormItems ON Forms.FormID = FormItems.FormID and Forms.ServerID = FormItems.ServerID and Forms.YearID = FormItems.YearID
							WHERE     (FormTypes.BedBes = 0) AND (FormTypes.Customer1DocType = 10) AND (Forms.FormState < 10)
							UNION ALL
							SELECT     Forms.CustomerID2, Forms.FormID, Forms.FormType, Forms.FormNumber, Forms.FormDate, 
												  FormTypes.FormCaption,isnull(Forms.FomNote,'')--+' '+ 'چك شماره ' + FormItems.CheckNumber + 'سررسيد' + FormItems.CheckDate 
												  AS ItemNote, 
												  FormItems.ItemAmount AS bed, 0 AS bes, 2 AS kind, Forms.CustomerID1 AS CustForShowForm
												  , Forms.ServerID, Forms.YearID
							FROM         Forms INNER JOIN
												  FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
												  FormItems ON Forms.FormID = FormItems.FormID and Forms.ServerID = FormItems.ServerID and Forms.YearID = FormItems.YearID
							WHERE     (FormTypes.BedBes = 0) AND (FormTypes.Customer2DocType = 10) AND (Forms.FormState < 10)
							UNION ALL
							SELECT     Forms.CustomerID2, Forms.FormID, Forms.FormType, Forms.FormNumber, Forms.FormDate, 
												  FormTypes.FormCaption, isnull(Forms.FomNote,'')--+' '+ 'چك شماره ' + FormItems.CheckNumber + 'سررسيد' + FormItems.CheckDate
												   AS ItemNote, 0 AS bed, 
												  FormItems.ItemAmount AS bes, 2 AS kind, Forms.CustomerID1 AS CustForShowForm
												  , Forms.ServerID, Forms.YearID
							FROM         Forms INNER JOIN
												  FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
												  FormItems ON Forms.FormID = FormItems.FormID and Forms.ServerID = FormItems.ServerID and Forms.YearID = FormItems.YearID
							WHERE     (FormTypes.BedBes = 1) AND (FormTypes.Customer2DocType = 10) AND (Forms.FormState < 10)) AccCust
