	CREATE VIEW cashTransactionItemsCust
	AS
	SELECT     CustomerID1, FormID, FormNumber, FormDate, Formtype, FormCaption, CheckNumber, CheckDate, BankName , 0 AS StuffCode, '' AS C_StuffName, '' AS Unitename, 
						  0 AS entity, 0 AS Waight, bed, bes, kind, CustForShowForm, FomNote AS ItemNote, 0.0 AS StuffDiameter, '0' AS StuffSize, 0 AS UnitSellPrice,ModifyDate,0 as ControlCode, 
						  CustName,SecondTypeCode
						  ,CustomerID2 , CustName2, SellsMethodName, ServerID, YearID

	FROM         (
		SELECT     Forms.CustomerID1, Forms.FormID, Forms.FormNumber, Forms.FormDate, FormTypes.FormType, FormTypes.FormCaption, Forms.FomNote , 
						  str(Forms.AidInfoNo) AS CheckNumber, Forms.AidInfoDate AS CheckDate, '' AS AccountNumber, '' AS BankName, 0 AS bed, Forms.Amount AS bes, 1 AS kind, 
						  Forms.CustomerID1 AS CustForShowForm, Forms.ModifyDate, LookUps.Code AS SecondTypeCode
						  , Forms.CustomerID2, Customers.CustName , Customers2.CustName as CustName2
						  , SellsMethods.SellsMethodName, Forms.ServerID, Forms.YearID
	FROM         Forms INNER JOIN
						  FormTypes ON Forms.FormType = FormTypes.FormType LEFT OUTER JOIN
						  LookUps ON Forms.PayTypes = LookUps.LookUpID
						  LEFT OUTER JOIN  Customers ON Forms.CustomerID1 = Customers.CustID
						  LEFT OUTER JOIN  Customers as Customers2 ON Forms.CustomerID2 = Customers2.CustID
						  LEFT OUTER JOIN  SellsMethods ON Forms.SellsMethod = SellsMethods.SellsMethod
	WHERE     (FormTypes.BedBes = 0) AND (FormTypes.Customer1DocType = 10) AND (FormTypes.DisplayFormType in(0,7)) AND (Forms.FormState < 10)

							UNION ALL
