												  FormTypes.FormCaption, FormItems.ItemNote, FormItems.CheckNumber, FormItems.CheckDate, 
												  FormItems.AccountNumber, FormItems.BankName, 0 AS bed, FormItems.ItemAmount AS bes, 2 AS kind, 
												  Forms.CustomerID1 AS CustForShowForm,Forms.ModifyDate
							, LookUps.Code AS SecondTypeCode
						  , Forms.CustomerID2, Customers.CustName , Customers2.CustName as CustName2, SellsMethods.SellsMethodName
						  , Forms.ServerID, Forms.YearID
							FROM         Forms INNER JOIN
												  FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
												  FormItems ON Forms.FormID = FormItems.FormID and Forms.ServerID = FormItems.ServerID and Forms.YearID = FormItems.YearID
							 LEFT OUTER JOIN  LookUps ON Forms.PayTypes = LookUps.LookUpID
						  LEFT OUTER JOIN  Customers ON Forms.CustomerID1 = Customers.CustID
						  LEFT OUTER JOIN  Customers as Customers2 ON Forms.CustomerID2 = Customers2.CustID
						  LEFT OUTER JOIN  SellsMethods ON Forms.SellsMethod = SellsMethods.SellsMethod
							WHERE     (FormTypes.BedBes = 1) AND (FormTypes.Customer2DocType = 10) AND (Forms.FormState < 10)) cashtransactionCust

	GO 
	SET QUOTED_IDENTIFIER OFF 
	GO 
	SET ANSI_NULLS ON 
	GO 
	SET QUOTED_IDENTIFIER ON 
	GO 
	SET ANSI_NULLS ON 
	GO 
