	CREATE VIEW GeneralAccCustR
	AS
	SELECT     *
	FROM         (SELECT     Recipts.PersonID1, Recipts.ReciptNumber, Recipts.ReciptDate, ReciptTypes.ReciptCaption, Recipts.ReciptNote, 
												  SUM(ReciptItems.TotalInputPrice + ReciptItems.TotalOutputPrice + ISNULL(ReciptsDeficits.DeficitAdd - ReciptsDeficits.DeficitDec,
												   0)) AS bed, SUM(0) AS bes
							FROM         ReciptItems INNER JOIN
												  Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
