							WHERE     (ReciptTypes.BedType = 1)
							GROUP BY Recipts.PersonID1, Recipts.ReciptNumber, Recipts.ReciptDate, ReciptTypes.ReciptCaption, 
												  Recipts.ReciptNote
							UNION ALL
							SELECT     Recipts.PersonID1, Recipts.ReciptNumber, Recipts.ReciptDate, ReciptTypes.ReciptCaption, Recipts.ReciptNote, 
												  SUM(0) AS bed, 
												  SUM(ReciptItems.TotalInputPrice + ReciptItems.TotalOutputPrice + ISNULL(ReciptsDeficits.DeficitAdd - ReciptsDeficits.DeficitDec,
												   0)) AS Bes
							FROM         ReciptItems INNER JOIN
												  Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
												  ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType LEFT OUTER JOIN
												  ReciptsDeficits ON Recipts.ReciptID = ReciptsDeficits.ReciptID
							WHERE     (ReciptTypes.BesType = 1)
							GROUP BY Recipts.PersonID1, Recipts.ReciptNumber, Recipts.ReciptDate, ReciptTypes.ReciptCaption, Recipts.ReciptNote
	) Acc
