							GROUP BY Forms.CustomerID1, Forms.FormID, Forms.FormNumber, Forms.FormDate, Forms.FormType, 
												  FormTypes.FormCaption, Forms.Amount
							UNION ALL
							SELECT     Forms.CustomerID1, Forms.FormID, Forms.FormNumber, Forms.FormDate, Forms.FormType, 
												  FormTypes.FormCaption, 0 AS bed, Forms.Amount AS bes, 2 AS kind
							FROM         Forms INNER JOIN
												  FormTypes ON Forms.FormType = FormTypes.FormType
							WHERE     (FormTypes.DisplayFormType in(0,7)) AND (FormTypes.Customer1DocType = 10) AND (FormTypes.BedBes = 0)
							GROUP BY Forms.CustomerID1, Forms.FormID, Forms.FormNumber, Forms.FormDate, Forms.FormType, 
												  FormTypes.FormCaption, Forms.Amount
							UNION ALL
							SELECT     Forms.CustomerID2, Forms.FormID, Forms.FormNumber, Forms.FormDate, Forms.FormType, 
												  FormTypes.FormCaption, Forms.Amount AS bed, 0 AS bes, 2 AS kind
							FROM         Forms INNER JOIN
												  FormTypes ON Forms.FormType = FormTypes.FormType
							WHERE     (FormTypes.DisplayFormType in(0,7)) AND (FormTypes.Customer2DocType = 10) AND (FormTypes.BedBes = 0)
							GROUP BY Forms.CustomerID2, Forms.FormID, Forms.FormNumber, Forms.FormDate, Forms.FormType, 
												  FormTypes.FormCaption, Forms.Amount
							UNION ALL
							SELECT     Forms.CustomerID2, Forms.FormID, Forms.FormNumber, Forms.FormDate, Forms.FormType, 
												  FormTypes.FormCaption, 0 AS bed, Forms.Amount AS bes, 2 AS kind
							FROM         Forms INNER JOIN
												  FormTypes ON Forms.FormType = FormTypes.FormType
							WHERE     (FormTypes.DisplayFormType in(0,7)) AND (FormTypes.Customer2DocType = 10) AND (FormTypes.BedBes = 1)
