	CREATE VIEW SpecialRecall
	AS
	SELECT     ReciptItems.ReciptItemID, Recipts.StoreID, Stores.c_StoreName, ReciptItems.StuffCode, StuffCoding.c_StuffName, 
						  Units.UnitName, ReciptItems.StuffSize, ReciptItems.StuffDiameter, ReciptItems.StuffAlloy, ReciptItems.StuffGrade, 
						  AvailableEntity.Entity, AvailableEntity.Weight, AvailableEntity.Price, Recipts.PersonID1, Customers.CustName, 
						  Recipts.ReciptNumber, Recipts.ReciptDate, ReciptTypes.ReciptCaption
	FROM         ReciptItems INNER JOIN
						  Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
						  StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode INNER JOIN
						  AvailableEntity ON ReciptItems.ReciptItemID = AvailableEntity.ReciptItemID INNER JOIN
						  ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType INNER JOIN
						  Units ON StuffCoding.n_UnitCode = Units.UnitCode LEFT OUTER JOIN
						  Customers ON Recipts.PersonID1 = Customers.CustID LEFT OUTER JOIN
						  Stores ON Recipts.StoreID = Stores.n_StoreID
	WHERE     (AvailableEntity.Entity > 0) AND (Recipts.StoreID = 1) AND (Recipts.ReciptType IN (1, 2, 3, 4, 5, 6)) OR
						  (AvailableEntity.Weight > 0)
