	CREATE VIEW TransaationCash_Check
	AS
	SELECT     *, bed + bes AS Balance
	FROM         (SELECT     Forms.CustomerID1, Forms.FormID, Forms.FormNumber, Forms.FormDate, FormTypes.Formtype, 
												  FormTypes.FormCaption, Forms.FomNote, '0' AS CheckNumber, '' AS CheckDate, '' AS AccountNumber, '' AS BankName, 0 AS bed, 
												  Forms.Amount AS bes, 1 AS kind, Forms.CustomerID1 AS CustForShowForm, Forms.BudgetCode, 
												  FormTypes.Customer1DocType
							FROM         Forms INNER JOIN
												  FormTypes ON Forms.FormType = FormTypes.FormType
							WHERE     (FormTypes.BedBes = 1) AND (FormTypes.DisplayFormType in(0,7))
							UNION ALL
							SELECT     Forms.CustomerID1, Forms.FormID, Forms.FormNumber, Forms.FormDate, FormTypes.Formtype, 
												  FormTypes.FormCaption, Forms.FomNote, '0' AS CheckNumber, '' AS CheckDate, '' AS AccountNumber, '' AS BankName, 
												  Forms.Amount AS bed, 0 AS bes, 1 AS kind, Forms.CustomerID1 AS CustForShowForm, Forms.BudgetCode, 
												  FormTypes.Customer1DocType
							FROM         Forms INNER JOIN
												  FormTypes ON Forms.FormType = FormTypes.FormType
							WHERE     (FormTypes.BedBes = 0) AND (FormTypes.DisplayFormType in(0,7))
							UNION ALL
							SELECT     Forms.CustomerID2, Forms.FormID, Forms.FormNumber, Forms.FormDate, FormTypes.Formtype, 
												  FormTypes.FormCaption, Forms.FomNote, '0' AS CheckNumber, '' AS CheckDate, '' AS AccountNumber, '' AS BankName, 
												  Forms.Amount AS bed, 0 AS bes, 1 AS kind, Forms.CustomerID1 AS CustForShowForm, Forms.BudgetCode, 
												  FormTypes.Customer2DocType
							FROM         Forms INNER JOIN
												  FormTypes ON Forms.FormType = FormTypes.FormType
							WHERE     (FormTypes.BedBes = 0) AND (FormTypes.DisplayFormType in(0,7))
							UNION ALL
							SELECT     Forms.CustomerID2, Forms.FormID, Forms.FormNumber, Forms.FormDate, FormTypes.Formtype, 
												  FormTypes.FormCaption, Forms.FomNote, '0' AS CheckNumber, '' AS CheckDate, '' AS AccountNumber, '' AS BankName, 0 AS bed, 
												  Forms.Amount AS bes, 1 AS kind, Forms.CustomerID1 AS CustForShowForm, Forms.BudgetCode, 
												  FormTypes.Customer2DocType
							FROM         Forms INNER JOIN
												  FormTypes ON Forms.FormType = FormTypes.FormType
							WHERE     (FormTypes.BedBes = 1) AND (FormTypes.DisplayFormType in(0,7))
							UNION ALL
							SELECT     Forms.CustomerID1, Forms.FormID, Forms.FormNumber, Forms.FormDate, FormTypes.Formtype, 
												  FormTypes.FormCaption, FormItems.ItemNote, FormItems.CheckNumber, FormItems.CheckDate, 
												  FormItems.AccountNumber, FormItems.BankName, 0 AS bed, FormItems.ItemAmount AS bes, 2 AS kind, 
												  Forms.CustomerID1 AS CustForShowForm, FormItems.BudgetCode, FormTypes.Customer1DocType
							FROM         Forms INNER JOIN
												  FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
												  FormItems ON Forms.FormID = FormItems.FormID and Forms.ServerID = FormItems.ServerID and Forms.YearID = FormItems.YearID
							WHERE     (FormTypes.BedBes = 1)
							UNION ALL
							SELECT     Forms.CustomerID1, Forms.FormID, Forms.FormNumber, Forms.FormDate, FormTypes.Formtype, 
												  FormTypes.FormCaption, FormItems.ItemNote, FormItems.CheckNumber, FormItems.CheckDate, 
												  FormItems.AccountNumber, FormItems.BankName, FormItems.ItemAmount AS bed, 0 AS bes, 2 AS kind, 
												  Forms.CustomerID1 AS CustForShowForm, FormItems.BudgetCode, FormTypes.Customer1DocType
							FROM         Forms INNER JOIN
												  FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
												  FormItems ON Forms.FormID = FormItems.FormID and Forms.ServerID = FormItems.ServerID and Forms.YearID = FormItems.YearID
							WHERE     (FormTypes.BedBes = 0)
							UNION ALL
							SELECT     FormItems.CustomerID2, Forms.FormID, Forms.FormNumber, Forms.FormDate, FormTypes.Formtype, 
												  FormTypes.FormCaption, FormItems.ItemNote, FormItems.CheckNumber, FormItems.CheckDate, 
												  FormItems.AccountNumber, FormItems.BankName, FormItems.ItemAmount AS bed, 0 AS bes, 2 AS kind, 
												  Forms.CustomerID1 AS CustForShowForm, FormItems.BudgetCode, FormTypes.Customer2DocType
							FROM         Forms INNER JOIN
												  FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
												  FormItems ON Forms.FormID = FormItems.FormID and Forms.ServerID = FormItems.ServerID and Forms.YearID = FormItems.YearID
							WHERE     (FormTypes.BedBes = 1)
							UNION ALL
							SELECT     Forms.CustomerID2, Forms.FormID, Forms.FormNumber, Forms.FormDate, FormTypes.Formtype, 
												  FormTypes.FormCaption, FormItems.ItemNote, FormItems.CheckNumber, FormItems.CheckDate, 
												  FormItems.AccountNumber, FormItems.BankName, 0 AS bed, FormItems.ItemAmount AS bes, 2 AS kind, 
												  Forms.CustomerID1 AS CustForShowForm, FormItems.BudgetCode, FormTypes.Customer2DocType
							FROM         Forms INNER JOIN
												  FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
												  FormItems ON Forms.FormID = FormItems.FormID and Forms.ServerID = FormItems.ServerID and Forms.YearID = FormItems.YearID
							WHERE     (FormTypes.BedBes = 0)) cashtransactionCust
	WHERE     (FormDate BETWEEN '1' AND '9999999') AND (Customer1DocType BETWEEN 0 AND 9999999) AND (Formtype BETWEEN 0 AND 9999999) AND 
						  (CustomerID1 BETWEEN 0 AND 9999999) AND (CustForShowForm BETWEEN 0 AND 9999999) AND (BudgetCode BETWEEN 0 AND 9999999)
	GO 
	SET QUOTED_IDENTIFIER OFF 
	GO 
	SET ANSI_NULLS ON 
	GO 
