	GO 
	SET ANSI_NULLS ON 
	GO 
	CREATE VIEW [dbo].[YearStuffControlCode]
	AS
	SELECT     TOP 100 PERCENT ReciptItems_Stock.YearID, ReciptItems_Stock.StoreID, ReciptItems_Stock.StuffCode, 0.0 AS StuffDiameter, '' AS StuffSize, '' AS StuffAlloy, 1 AS StuffGrade, 
						  ROUND(SUM(ReciptItems_Stock.InputEntity - ReciptItems_Stock.OutputEntity), 3) AS Entity, 
						  ROUND(SUM(ReciptItems_Stock.InputWeight - ReciptItems_Stock.OutputWeight), 3) AS Weight, 
						  SUM(ReciptItems_Stock.TotalInputPrice - ReciptItems_Stock.TotalOutputPrice) AS Price, Stores.n_ValuationType,  0 AS PersonID1, 
						  '' AS ItemNote, ISNULL(ReciptItems_Stock.ControlCode, 0)  AS ControlCode
						  , ISNULL(SpecialCode,'') as SpecialCode,ISNULL(ReciptItems_Stock.UseUnitID, 0)  AS UseUnitID
						  ,SUM(case when ReciptItems_Stock.TotalInputPrice>0 Then TotallSellPrice else -TotallSellPrice end ) AS TotallSellPrice
	FROM         ReciptItems_Stock INNER JOIN
						  Stores ON ReciptItems_Stock.StoreID = Stores.n_StoreID

	GROUP BY ReciptItems_Stock.YearID,ReciptItems_Stock.StoreID, ReciptItems_Stock.StuffCode, Stores.n_ValuationType
			 ,  ISNULL(ReciptItems_Stock.ControlCode, 0) 
			 , ISNULL(SpecialCode,'') , UseUnitID
	HAVING      (SUM(ReciptItems_Stock.InputEntity - ReciptItems_Stock.OutputEntity) >= 0.0001) OR
				(SUM(ReciptItems_Stock.InputEntity - ReciptItems_Stock.OutputEntity) <= - 0.0001) OR
				(SUM(ReciptItems_Stock.InputWeight - ReciptItems_Stock.OutputWeight) >= 0.0001) OR
				(SUM(ReciptItems_Stock.InputWeight - ReciptItems_Stock.OutputWeight) <= - 0.0001)
	ORDER BY ReciptItems_Stock.StuffCode, ISNULL(ReciptItems_Stock.ControlCode, 0) 
	GO 
	SET QUOTED_IDENTIFIER OFF 
	GO 
	SET ANSI_NULLS ON 
	GO 
	-----------------------------------------------------------------------------------------------------------------
	---------------------------------------------------------------------------------------------------------------------------
	SET QUOTED_IDENTIFIER ON 
	GO 
	SET ANSI_NULLS ON 
	GO 
