	CREATE VIEW YearStuffSpecialinventory
	AS
	SELECT TOP 100 PERCENT ReciptItems.ReciptItemID, ReciptItems.StuffCode, ReciptItems.ControlCode, ReciptItems.StuffSize, 
					   ReciptItems.StuffDiameter, ReciptItems.StuffAlloy, ISNULL(ReciptItems.PersonID1, 0) AS PersonID1, 
			 ROUND(ReciptItems.InputEntity - ReciptItems.OutputEntity + ISNULL(RecallSpecial.Entity, 0), 3) AS Entity, 
			 ROUND(ReciptItems.InputWeight - ReciptItems.OutputWeight + ISNULL(RecallSpecial.Weight, 0), 3) AS Weight, 
			 ROUND(ReciptItems.TotalInputPrice - ReciptItems.TotalOutputPrice + ISNULL(RecallSpecial.Price, 0), 3) AS Price, 
			 ISNULL(ReciptItems.TotallSellPrice - RecallSpecial.TotallSellPrice, 0) AS TotallSellPrice, 
			 ReciptItems.StuffGrade, Recipts.StoreID, 
			 Stores.n_ValuationType, ReciptItems.ItemNote,ReciptItems.YearID,ReciptItems.ServerID
			 , ISNULL(Recipts.PersonID3, 0) AS PersonID3 ,case when Stores.n_ValuationType<>2 then 0 else ISNULL(ReciptItems.UseUnitID, 0) end AS UseUnitID
			 , ISNULL(SpecialCode,'') as SpecialCode
	
	FROM         Units INNER JOIN
						  StuffCoding ON Units.UnitCode = StuffCoding.n_UnitCode INNER JOIN
						  ReciptItems INNER JOIN
						  Recipts ON ReciptItems.ReciptID = Recipts.ReciptID 
						  AND ReciptItems.ServerID = Recipts.ServerID 
						  AND ReciptItems.YearID = Recipts.YearID INNER JOIN
						  ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType LEFT OUTER JOIN
						  Customers ON ReciptItems.PersonID1 = Customers.CustID INNER JOIN
						  Stores ON Recipts.StoreID = Stores.n_StoreID ON StuffCoding.c_StuffCode = ReciptItems.StuffCode LEFT OUTER JOIN
						  RecallSpecial ON ReciptItems.ReciptItemID = RecallSpecial.preReciptItemID
										and ReciptItems.YearID = RecallSpecial.YearID
										AND ReciptItems.ServerID = RecallSpecial.ServerID
	WHERE     (ReciptTypes.EffectType = 2 OR
						  ReciptTypes.EffectType = 2) AND (ReciptItems.InputEntity - ReciptItems.OutputEntity + ISNULL(RecallSpecial.Entity, 0) >= 0.0001 OR
						  ReciptItems.InputEntity - ReciptItems.OutputEntity + ISNULL(RecallSpecial.Entity, 0) <= - 0.0001) AND (Recipts.ReciptState < 3) OR
						  (ReciptTypes.EffectType = 2 OR
						  ReciptTypes.EffectType = 2) AND (Recipts.ReciptState < 3) AND (Recipts.StoreID BETWEEN 0 AND 999999) AND 
						  (ReciptItems.InputWeight - ReciptItems.OutputWeight + ISNULL(RecallSpecial.Weight, 0) >= 0.0001) OR
						  (ReciptTypes.EffectType = 2 OR
						  ReciptTypes.EffectType = 2) AND (Recipts.ReciptState < 3) AND (Recipts.StoreID BETWEEN 0 AND 999999) AND 
						  (ReciptItems.InputWeight - ReciptItems.OutputWeight + ISNULL(RecallSpecial.Weight, 0) <= - 0.0001)
	ORDER BY ReciptItems.StuffCode, ReciptItems.StuffDiameter, ReciptItems.StuffSize, ISNULL(SpecialCode,'') 
	GO 
	SET QUOTED_IDENTIFIER OFF 
	GO 
	SET ANSI_NULLS ON 
	GO 
	SET QUOTED_IDENTIFIER ON 
	GO 
	SET ANSI_NULLS ON 
	GO 
	CREATE VIEW FormsCustomer
	AS
	SELECT Forms.FormID,Forms.ServerID,Forms.YearID, Forms.FormNumber, Forms.FormDate, Forms.CustomerID2, Forms.AidInfoNo, Forms.AidInfoDate,forms.parentformid, 
		   (CASE WHEN Customers.CustName IS NULL THEN Customers_1.CustName ELSE Customers.CustName END) AS CustName,Customers.ReagentName, 
						  Forms.FormType, Forms.CustomerID1, FormItems.CheckNumber, FormItems.CheckDate, Forms.Amount, 
						  isnull(Forms.CustomerName2, '')as CustomerName2
	FROM         Forms LEFT OUTER JOIN
						  FormItems ON 
						  Forms.FormID = FormItems.FormID and Forms.ServerID = FormItems.ServerID and Forms.YearID = FormItems.YearID  
						  LEFT OUTER JOIN
						  Customers ON Forms.CustomerID2 = Customers.CustID LEFT OUTER JOIN
						  Customers Customers_1 ON FormItems.CustomerID2 = Customers_1.CustID
	GO 
