	CREATE VIEW [dbo].[vu_FormTypes_MakeDoc]
	AS
	SELECT	FormType , 
			InfoKind ,
			case InfoKind 
				when 1 then 'DebitWage'
				when 2 then 'CreditWage'
				when 3 then 'TAX'
				when 4 then 'CurrencyExchange'
			end ACC_KIND,
			TopicCode,
			DetailCode,
			CTopicCode,
			CTopicCode2,
			CTopicCode3,
			BedBes
	FROM dbo.FormTypesAccCode FTAC
	--
	UNION 
	--
	select	ft.FormType , 
			InfoKind ,
			dc.ACC_KIND ACC_KIND,
			0 TopicCode,
			0 DetailCode,
			0 CTopicCode,
			0 CTopicCode2,
			0 CTopicCode3,
			0 BedBes

	From FormTypes FT
		CROSS JOIN 
				(
					Select 'Debit' ACC_KIND, 100 InfoKind 
					UNION 
					Select 'Credit' ACC_KIND,101 InfoKind 
				) DC

	GO 





