	CREATE FUNCTION FormItemsAccount (@TypeDoc varchar (2)=[1] )
	RETURNS table  AS  
	return (SELECT		Forms.FormID, Forms.FormNumber, Forms.FormDate, FormItems.CheckNumber, FormItems.CheckDate, Forms.FormType, 
			FormTypes.FormCaption, Forms.CustomerID1 ,
	---------------------برحسب نوع انتخاب كد مشتر ي2 در ديتيل كد مشتري 2 مشخص شده است  -----------
			case FormTypes.Customer2ActiveOnDetail
				when 0 then Forms.CustomerID2
				when 1 then FormItems.CustomerID2
				when 2 then FormItems.CustomerID2
				when 3 then Forms.CustomerID2
			else Forms.CustomerID2 end as CustomerID2 , 
			Forms.FomNote, Forms.AidInfoNo, Forms.AidInfoDate,
			case FormTypes.bedbes when 0 then FormItems.ItemAmount else 0 end as Debt ,
			case FormTypes.bedbes when 1 then FormItems.ItemAmount else 0 end as Credit ,
			case FormTypes.BudgetCodePosition
				when 0 then 0
				when 1 then FormItems.BudgetCode
				when 2 then FormItems.BudgetCode
				when 3 then Forms.BudgetCode
			else 0 end as BudgetCode ,
			case FormTypes.BudgetCodePosition
				when 0 then 0
				when 1 then FormItems.ProjectID
				when 2 then FormItems.ProjectID
				when 3 then Forms.ProjectID
			else 0 end as ProjectID ,
			case FormTypes.Customer2ActiveOnDetail
				when 0 then Forms.CustomerName2
				when 1 then null
				when 2 then null
				when 3 then Forms.CustomerName2
			else str(Forms.CustomerID2) end as CustomerName2 
	FROM		Forms INNER JOIN
			FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
			FormItems ON Forms.FormID = FormItems.FormID and Forms.ServerID = FormItems.ServerID and Forms.YearID = FormItems.YearID

	WHERE		(case FormTypes.Customer1DocType 
			when 2 then
				case FormItems.CheckType  when 1 then 6 else 2 end
			when 6 then 
				case FormItems.CheckType  when 0 then 2 else 6 end
			else FormTypes.Customer1DocType  end  =@TypeDoc) 

	union all
	SELECT		Forms.FormID, Forms.FormNumber, Forms.FormDate, FormItems.CheckNumber, FormItems.CheckDate, Forms.FormType, 
			FormTypes.FormCaption, 
	---------------------برحسب نوع انتخاب كد مشتر ي2 در ديتيل كد مشتري 2 مشخص شده است  -----------
			case FormTypes.Customer2ActiveOnDetail
				when 0 then Forms.CustomerID2
				when 1 then FormItems.CustomerID2
				when 2 then FormItems.CustomerID2
				when 3 then Forms.CustomerID2
			else Forms.CustomerID2 end as CustomerID2 ,Forms.CustomerID1, 
			Forms.FomNote, Forms.AidInfoNo, Forms.AidInfoDate,
			case FormTypes.bedbes when 1 then FormItems.ItemAmount else 0 end as Debt ,
			case FormTypes.bedbes when 0 then FormItems.ItemAmount else 0 end as Credit ,
			case FormTypes.BudgetCodePosition
				when 0 then 0
				when 1 then FormItems.BudgetCode
				when 2 then FormItems.BudgetCode
				when 3 then Forms.BudgetCode
			else 0 end as BudgetCode ,
			case FormTypes.BudgetCodePosition
				when 0 then 0
				when 1 then FormItems.ProjectID
				when 2 then FormItems.ProjectID
				when 3 then Forms.ProjectID
			else 0 end as ProjectID ,
			case FormTypes.Customer2ActiveOnDetail
				when 0 then Forms.CustomerName2
				when 1 then null
				when 2 then null
				when 3 then Forms.CustomerName2
			else null end as CustomerName2

	FROM		Forms INNER JOIN
			FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
			FormItems ON Forms.FormID = FormItems.FormID and Forms.ServerID = FormItems.ServerID and Forms.YearID = FormItems.YearID

	WHERE		(case FormTypes.Customer2DocType 
			when 2 then
				case FormItems.CheckType  when 1 then 6 else 2 end
			when 6 then 
				case FormItems.CheckType  when 0 then 2 else 6 end
			else FormTypes.Customer2DocType  end  =@TypeDoc) 
	)
	GO 
	SET QUOTED_IDENTIFIER OFF 
	GO 
	SET ANSI_NULLS ON 
	GO 
	SET QUOTED_IDENTIFIER OFF 
	GO 
	SET ANSI_NULLS OFF 
	GO 
	CREATE FUNCTION FormsAccount (@TypeDoc varchar (2)=[1] )
	RETURNS table  AS  
	return (
	SELECT     Forms.FormID, Forms.FormNumber, Forms.FormDate, '0' as checkNumber , '0' as checkDate ,Forms.FormType, FormTypes.FormCaption, 
			Forms.CustomerID1, Forms.CustomerID2, Forms.FomNote,Forms.AidInfoNo, Forms.AidInfoDate,
			case FormTypes.bedbes when 0 then Forms.Amount else 0 end as Debt ,
			case FormTypes.bedbes when 1 then Forms.Amount else 0 end as Credit ,
			Forms.BudgetCode, Forms.ProjectID, Forms.CustomerName2

	FROM         Forms INNER JOIN
						  FormTypes ON Forms.FormType = FormTypes.FormType
	WHERE     (FormTypes.DetailDataType = 0) AND (FormTypes.Customer1DocType =@TypeDoc) 
	union all
	SELECT     Forms.FormID, Forms.FormNumber, Forms.FormDate,  '0' as checkNumber , '0' as checkDate , Forms.FormType, FormTypes.FormCaption, 
			Forms.CustomerID2, Forms.CustomerID1, Forms.FomNote,Forms.AidInfoNo, Forms.AidInfoDate,
			case FormTypes.bedbes when 0 then Forms.Amount else 0 end as Debt ,
			case FormTypes.bedbes when 1 then Forms.Amount else 0 end as Credit ,
			Forms.BudgetCode, Forms.ProjectID, Forms.CustomerName2

	FROM         Forms INNER JOIN
						  FormTypes ON Forms.FormType = FormTypes.FormType
	WHERE     (FormTypes.DetailDataType = 0) AND (FormTypes.Customer2DocType = @TypeDoc) 
	)
	GO 
	SET QUOTED_IDENTIFIER OFF 
	GO 
	SET ANSI_NULLS ON 
	GO 
