	CREATE FUNCTION FormItemsAmount (@FormID int=1 ,@ServerID int=0, @YearID int=88
	)
	RETURNS money 
	begin
	  DECLARE @ItemAmount money
	  DECLARE @DisplayFormType tinyint
	  SET @DisplayFormType=(SELECT FormTypes.DisplayFormType FROM Forms INNER JOIN FormTypes ON 
															Forms.FormType=FormTypes.FormType 
							  WHERE  Forms.FormID = @FormID
								and ServerID = @ServerID and  YearID = @YearID)

	  SET @ItemAmount=(SELECT Amount FROM Forms WHERE FormID=@FormID  and ServerID = @ServerID and  YearID = @YearID)
	  if @DisplayFormType not in (0,7)
		 SET @ItemAmount=(SELECT SUM(ItemAmount)FROM FormItems WHERE FormID=@FormID and ServerID = @ServerID and  YearID = @YearID)
	RETURN(@ItemAmount)
	end
	GO 
	SET QUOTED_IDENTIFIER OFF 
	GO 
	SET ANSI_NULLS ON 
	GO 
	SET QUOTED_IDENTIFIER OFF 
	GO 
	SET ANSI_NULLS OFF 
	GO 
	CREATE FUNCTION rptBalanceCoffer (    @FormDateFrom Varchar(10) =['0'] ,@FormDateTo Varchar(10) =['99/12/29'] , 
						@CustIDFrom int =[0] ,@CustIDTo int =[999999999]  )
	RETURNS table  AS  
	return (select CustID, CustName  , sum(firstBalance) as firstBalance  ,sum(bed) as bed , sum(bes) as bes
	  from (
		SELECT  Forms.CustomerID1 as CustID ,Customers.CustName, FormTypes.Customer1DocType,
		case when FormDate   between    @FormDateFrom      and   @FormDateTo   then 0 else 
			(case FormTypes.DisplayFormType 
				when 0 then Forms.Amount 
				when 7 then Forms.Amount 
				else FormItems.ItemAmount end )*(	case  FormTypes.BedBes  
								when 1 then 1 else -1 end ) 
			end  as firstBalance ,
		case when FormDate   between 	@FormDateFrom  and    @FormDateTo   then 
			case  FormTypes.BedBes  
				when 1 then( case FormTypes.DisplayFormType 
						when 0 then Forms.Amount 
						when 7 then Forms.Amount 
						else FormItems.ItemAmount end )
				else 0 end 
			else 0 end as bed ,
		case when FormDate   between    @FormDateFrom    and     @FormDateTo   then 
					case  FormTypes.BedBes  
				when 0 then ( case FormTypes.DisplayFormType 
						when 0 then Forms.Amount 
						when 7 then Forms.Amount 
						else FormItems.ItemAmount end )
				else 0 end 
			else 0 end as bes 
	FROM         FormItems RIGHT OUTER JOIN
						  Forms INNER JOIN
						  FormTypes ON Forms.FormType = FormTypes.FormType LEFT OUTER JOIN
						  CustomersGroup INNER JOIN
						  Customers ON CustomersGroup.CustomerGrpID = Customers.CustomerGrpID ON Forms.CustomerID1 = Customers.CustID ON 
						  FormItems.FormID = Forms.FormID	
	where FormDate <=  @FormDateTo  and  GroupType in(1,2)  and FormTypes.Customer1DocType in(1,2,10)  
			and isnull(FormItems.checkType,1)<>0
	-------------	-- اين قسمت براي جداسازي اطلاعات برداشت چكهاي تاريخ روز از بانك به شرط اضافه شده است --------
			--and FormTypes.Customer2DocType <>6    880420
	UNION ALL

		SELECT	Forms.CustomerID2, Customers.CustName ,FormTypes.Customer2DocType ,
		case when FormDate   between   @FormDateFrom   and  @FormDateTo    then 0 else 
			(case FormTypes.DisplayFormType 
				when 0 then Forms.Amount 
				when 7 then Forms.Amount 
				else FormItems.ItemAmount end )*(	case  FormTypes.BedBes  
									when 0 then 1 else -1 end ) 
			end  as firstBalance ,
		case when FormDate   between   @FormDateFrom    and    @FormDateTo    then 
			case  FormTypes.BedBes  
				when 0 then(case FormTypes.DisplayFormType 
						when 0 then Forms.Amount 
						when 7 then Forms.Amount 
						else FormItems.ItemAmount end )
				else 0 end 
			else 0 end  as bed ,
		case when FormDate   between   @FormDateFrom    and  @FormDateTo   then 
			case  FormTypes.BedBes  
				when 1 then(case FormTypes.DisplayFormType 
						when 0 then Forms.Amount 
						when 7 then Forms.Amount 
						else FormItems.ItemAmount end )
				else 0 end 
			else 0 end as bes 
	FROM         FormItems RIGHT OUTER JOIN
						  Forms INNER JOIN
						  FormTypes ON Forms.FormType = FormTypes.FormType LEFT OUTER JOIN
						  CustomersGroup INNER JOIN
						  Customers ON CustomersGroup.CustomerGrpID = Customers.CustomerGrpID ON Forms.CustomerID2 = Customers.CustID ON 
						  FormItems.FormID = Forms.FormID	
	where FormDate <=  @FormDateTo and GroupType in(1,2) and FormTypes.Customer2DocType in(1,2,10) and 
	  isnull(FormItems.checkType,1)<>0
	-------------	-- اين قسمت براي جداسازي اطلاعات برداشت چكهاي تاريخ روز از بانك به شرط اضافه شده است --------
			and FormTypes.Customer2DocType <>6 
	UNION ALL
			SELECT CustID , Customers.CustName , CustomersGroup.GroupType AS Customer1DocType , firstBalance   ,
			   0 AS bed ,   0   AS bes 
			FROM    CustomersGroup INNER JOIN    Customers ON  
				CustomersGroup.CustomerGrpID =  Customers.CustomerGrpID
			where GroupType in(1,2) and firstBalance<>0

	UNION ALL
	------------اين قسمت خاص وصول اسناد پرداختني ميباشد -----------------------------------------------------
		SELECT  Forms.CustomerID1 as CustID ,Customers.CustName, FormTypes.Customer1DocType,
		case when CheckDate   between    @FormDateFrom      and   @FormDateTo   then 0 else 
			(case FormTypes.DisplayFormType 
				when 0 then Forms.Amount 
				when 7 then Forms.Amount 
				else FormItems.ItemAmount end )*(	case  FormTypes.BedBes  
								when 1 then 1 else -1 end ) 
			end  as firstBalance ,
		case when CheckDate   between 	@FormDateFrom  and    @FormDateTo   then 
			case  FormTypes.BedBes  
				when 1 then( case FormTypes.DisplayFormType 
						when 0 then Forms.Amount 
						when 7 then Forms.Amount 
						else FormItems.ItemAmount end )
				else 0 end 
			else 0 end as bed ,
		case when CheckDate   between    @FormDateFrom    and     @FormDateTo   then 
					case  FormTypes.BedBes  
				when 0 then ( case FormTypes.DisplayFormType 
						when 0 then Forms.Amount 
						when 7 then Forms.Amount 
						else FormItems.ItemAmount end )
				else 0 end 
			else 0 end as bes 
	FROM         FormItems RIGHT OUTER JOIN
						  Forms INNER JOIN
						  FormTypes ON Forms.FormType = FormTypes.FormType LEFT OUTER JOIN
						  CustomersGroup INNER JOIN
						  Customers ON CustomersGroup.CustomerGrpID = Customers.CustomerGrpID ON Forms.CustomerID1 = Customers.CustID ON 
						  FormItems.FormID = Forms.FormID	
	where CheckDate <=  @FormDateTo  and  GroupType in(1,2)  and FormTypes.Customer1DocType in(2) 
	 and isnull(FormItems.checkType,1) = 0
	--and FormItems.checkType=0

	UNION ALL

		SELECT	Forms.CustomerID2, Customers.CustName ,FormTypes.Customer2DocType ,
		case when CheckDate   between   @FormDateFrom   and  @FormDateTo    then 0 else 
			(case FormTypes.DisplayFormType 
				when 0 then Forms.Amount 
				when 7 then Forms.Amount 
				else FormItems.ItemAmount end )*(	case  FormTypes.BedBes  
									when 0 then 1 else -1 end ) 
			end  as firstBalance ,
		case when CheckDate   between   @FormDateFrom    and    @FormDateTo    then 
			case  FormTypes.BedBes  
				when 0 then(case FormTypes.DisplayFormType 
						when 0 then Forms.Amount 
						when 7 then Forms.Amount 
						else FormItems.ItemAmount end )
				else 0 end 
			else 0 end  as bed ,
		case when CheckDate   between   @FormDateFrom    and  @FormDateTo   then 
			case  FormTypes.BedBes  
				when 1 then(case FormTypes.DisplayFormType 
						when 0 then Forms.Amount 
						when 7 then Forms.Amount 
						else FormItems.ItemAmount end )
				else 0 end 
			else 0 end as bes 
	FROM         FormItems RIGHT OUTER JOIN
						  Forms INNER JOIN
						  FormTypes ON Forms.FormType = FormTypes.FormType LEFT OUTER JOIN
						  CustomersGroup INNER JOIN
						  Customers ON CustomersGroup.CustomerGrpID = Customers.CustomerGrpID ON Forms.CustomerID2 = Customers.CustID ON 
						  FormItems.FormID = Forms.FormID	
	where CheckDate <=  @FormDateTo and GroupType in(1,2) and FormTypes.Customer2DocType in(2)  
	--and FormItems.checkType=0  
	and isnull(FormItems.checkType,1)=0
	) rptBalance

	where CustID between @CustIDFrom and @CustIDTo
	group by CustID , CustName
	)
	GO 
	SET QUOTED_IDENTIFIER OFF 
	GO 
	SET ANSI_NULLS ON 
	GO 



	SET QUOTED_IDENTIFIER ON 
