CREATE FUNCTION dbo.ChkIsStepCorrelate (@ReciptType int,@ReciptID int, @ParentReciptID  int  )
RETURNS bit 
BEGIN
 DECLARE @StepCorrelate int 
 SELECT @StepCorrelate=ISNULL(MAX(StepCorrelate) ,0)
      FROM            ReciptTypes
      WHERE  ( (ReciptType = @ReciptType) OR (CorrelateReciptType = @ReciptType)) 
	     AND (StepCorrelate > 1) 

    if @StepCorrelate > 1 
      if @ReciptID < @ParentReciptID RETURN(1)
	  else RETURN( 0) 
    else
      if @ReciptID > @ParentReciptID RETURN(1)
	  else RETURN( 0) 
  RETURN(1) 
  
END
