CREATE PROCEDURE [dbo].[ReciptsOk4DeleteStateTo3] @ReciptID int=[1], @ServerID int=0, @YearID int=88,@ReciptItemID int =5405, @CountUpDate int=0 OUTPUT ,@FormName varchar(1000) OUTPUT as
begin
--  RETURN(0) not  delete ReciptID or ReciptItemID
DECLARE @ReciptType int
SELECT  @ReciptType=ReciptType FROM Recipts WHERE (ReciptID=@ReciptID) AND (ServerID=@ServerID)AND (YearID=@YearID)


set @CountUpDate=0
  UPDATE  Recipts  set Recipts.ReciptState = 3   FROM Recipts WHERE (ParentReciptID=@ReciptID)  AND --(ReciptID > ParentReciptID) 
                              (dbo.ChkIsStepCorrelate(@ReciptType , ReciptID , ParentReciptID)=1)
                            AND (Recipts.ServerID=@ServerID)AND (Recipts.YearID=@YearID)
							AND (Recipts.ReciptState <> 3) 

set     @CountUpDate =    @CountUpDate +@@ROWCOUNT



  UPDATE  Recipts  set Recipts.ReciptState = 3  
  FROM ReciptItems AS Recipt_Items
  INNER JOIN
                         Recipts ON Recipt_Items.ReciptID = Recipts.ReciptID AND Recipt_Items.ServerID = Recipts.ServerID AND Recipt_Items.YearID = Recipts.YearID 
						 INNER JOIN
                         ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
 
  WHERE (preReciptItemID IN
                          (SELECT  DISTINCT   Items.ReciptItemID FROM Recipts INNER JOIN
                                      ReciptItems as Items ON Recipts.ReciptID = Items.ReciptID 
									  AND Recipts.ServerID = Items.ServerID AND Recipts.YearID = Items.YearID
                           WHERE     (Items.ReciptID = @ReciptID) AND (Items.ServerID=@ServerID)AND (Items.YearID=@YearID) 
						      AND Items.StuffCode=Recipt_Items.StuffCode
							  AND ReciptItemID=case when  @ReciptItemID=0 then ReciptItemID else @ReciptItemID end
							  AND (Recipts.ReciptState <> 3)

						   ))
						     AND Recipt_Items.ServerID=@ServerID and Recipt_Items.YearID=@YearID 
							 AND (Recipts.ReciptState <> 3)

set     @CountUpDate =    @CountUpDate +@@ROWCOUNT

SELECT     @FormName=isnull(@FormName ,'')+isnull(    ReciptTypes1.ReciptCaption+ str(Recipts_P.ReciptNumber) ,'')
FROM            ReciptTypes1 INNER JOIN
                         Recipts AS Recipts_P ON ReciptTypes1.ReciptType = Recipts_P.ReciptType RIGHT OUTER JOIN
                         Recipts ON Recipts_P.YearID = Recipts.YearID AND Recipts_P.ServerID = Recipts.ServerID AND Recipts_P.ParentReciptID = Recipts.ReciptID
 WHERE     (Recipts.ReciptID = @ReciptID) AND (Recipts.ServerID=@ServerID)AND (Recipts.YearID=@YearID) 


end

