CREATE FUNCTION GetReciptsDeficits()
RETURNS table  AS  
return (
SELECT     Recipts.PersonID1, ReciptsDeficits.ReciptID, Recipts.ReciptNumber, Recipts.ReciptDate, Recipts.ReciptType, Deficits.DeficitName AS ReciptCaption, 
                      0 AS StuffCode, 'كسورات/اضافات ' + ReciptTypes.ReciptCaption AS c_StuffName, ' ' AS UnitName, 0.0 AS entity, 0.0 AS weight, 

                      --(CASE ReciptTypes.BedType WHEN 1 THEN SUM(ReciptsDeficits.DeficitDec) ELSE 0 END) AS bed, 
                      --(CASE ReciptTypes.BesType WHEN 1 THEN SUM(ReciptsDeficits.DeficitAdd) ELSE 0 END) AS bes, 0 AS kind, 

                      (CASE ReciptTypes.BesType WHEN 1 THEN SUM(ReciptsDeficits.DeficitDec) ELSE SUM(ReciptsDeficits.DeficitAdd) END) AS bed, 
                      (CASE ReciptTypes.BesType WHEN 1 THEN SUM(ReciptsDeficits.DeficitAdd) ELSE SUM(ReciptsDeficits.DeficitDec) END) AS bes, 0 AS kind, 
               
                      Recipts.StoreID, Recipts.ReciptNote AS ItemNote, 0.0 AS StuffDiameter, '0' AS StuffSize, 0 AS UnitSellPrice, ' ' AS ModifyDate, Customers.CustName, 
                      LookUps.Code AS SecondTypeCode, Recipts.PersonID2, Customers2.CustName AS CustName2, SellsMethods.SellsMethodName, 
                      ReciptsDeficits.ServerID, ReciptsDeficits.YearID
FROM         Recipts INNER JOIN
                      ReciptsDeficits ON Recipts.ReciptID = ReciptsDeficits.ReciptID AND Recipts.ServerID = ReciptsDeficits.ServerID AND 
                      Recipts.YearID = ReciptsDeficits.YearID INNER JOIN
                      ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType INNER JOIN
                      Vu_CustomersGroups AS Customers ON Recipts.PersonID1 = Customers.CustID LEFT OUTER JOIN
                      LookUps ON Recipts.SecondType = LookUps.LookUpID LEFT OUTER JOIN
                      Deficits ON ReciptsDeficits.DeficitID = Deficits.DeficitID LEFT OUTER JOIN
                      Vu_CustomersGroups AS Customers2 ON Recipts.PersonID2 = Customers2.CustID LEFT OUTER JOIN
                      SellsMethods ON Recipts.SellsMethod = SellsMethods.SellsMethod
WHERE     (Recipts.ReciptState < 3)
and (ReciptTypes.BedType=1 or ReciptTypes.BesType=1)
GROUP BY ReciptsDeficits.ReciptID, Recipts.PersonID1, Recipts.ReciptNumber, Recipts.ReciptDate, Recipts.ReciptType, Recipts.ReciptNote, Recipts.StoreID, 
                      ReciptTypes.BesType, Deficits.DeficitName, ReciptTypes.ReciptCaption, Customers.CustName, LookUps.Code, Recipts.PersonID2, 
                      Customers2.CustName, SellsMethods.SellsMethodName, ReciptsDeficits.ServerID, ReciptsDeficits.YearID
                      ,BedType

)
