	when (@Month-1)  then ReciptItems.OutputWeight end ,0 )) 
	else 1 end ,0) AS AVeWeight_LastMonth,
-----------------------
	Round(SUM(isnull(case  ABS(SUBSTRING(Recipts.ReciptDate, 6, 2))
	when @Month  then ReciptItems.OutputEntity  end,0 )) ,0) AS Entity_Month, 
	Round(SUM(isnull(case  ABS(SUBSTRING(Recipts.ReciptDate, 6, 2))
	when @Month then ReciptItems.OutputWeight  end,0 )) ,0 ) AS Weight_Month, 

	Round(SUM(isnull(case  ABS(SUBSTRING(Recipts.ReciptDate, 6, 2))
	when @Month  then ReciptItems.TotalOutputPrice  end,0 )) ,0) AS Price_Month, 

	Round(SUM(isnull(case  ABS(SUBSTRING(Recipts.ReciptDate, 6, 2))
	when @Month  then ReciptItems.TotallSellPrice  end,0 )) ,0) AS TotallSellPrice_Month, 
	
	Round(SUM(isnull(case  ABS(SUBSTRING(Recipts.ReciptDate, 6, 2))
	when @Month  then ReciptItems.TotalOutputPrice end,0 )) /
	case when 
	SUM(isnull(case  ABS(SUBSTRING(Recipts.ReciptDate, 6, 2))
	when @Month  then ReciptItems.OutputEntity end,0 ))  >0 then 
	SUM(isnull(case  ABS(SUBSTRING(Recipts.ReciptDate, 6, 2))
	when @Month  then ReciptItems.OutputEntity end ,0 )) 
	else 1 end ,0)  AS AVeEntity_Month,
	Round(SUM(isnull(case  ABS(SUBSTRING(Recipts.ReciptDate, 6, 2))
	when @Month  then ReciptItems.TotalOutputPrice end,0 )) /
	case when 
	SUM(isnull(case  ABS(SUBSTRING(Recipts.ReciptDate, 6, 2))
	when @Month  then ReciptItems.OutputWeight end,0 ))  >0 then 
	SUM(isnull(case  ABS(SUBSTRING(Recipts.ReciptDate, 6, 2))
	when @Month  then ReciptItems.OutputWeight end ,0 )) 
	else 1 end ,0) AS AVeWeight_Month,
-----------------
	Round(SUM(ReciptItems.OutputEntity) ,0 ) AS TOutputEntity, 
	Round(SUM(ReciptItems.OutputWeight) ,0 ) AS TOutputWeight, 
	Round(SUM(ReciptItems.TotalOutputPrice)  ,0 ) AS TTotalOutputPrice,

	Round(SUM(ReciptItems.TotallSellPrice)  ,0 ) AS TTotallSellPrice,
	
	Round(case when 
	SUM(ReciptItems.OutputEntity) >0 then 
	SUM(ReciptItems.TotalOutputPrice) /SUM(ReciptItems.OutputEntity) 
	else 1 end  ,0 ) AS TAveEntity ,
	Round(case when 
	SUM(ReciptItems.OutputWeight) >0 then 
	SUM(ReciptItems.TotalOutputPrice) /SUM(ReciptItems.OutputWeight) 
	else 1 end ,0) AS TAveWeight
-------------------
FROM         ReciptItems INNER JOIN
                      Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
                      StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode
where      (ABS(SUBSTRING(Recipts.ReciptDate, 4, 2 )) <= @Month)  
GROUP BY    StuffCoding.GroupID ,  ReciptItems.StuffCode 
HAVING  (ReciptItems.StuffCode BETWEEN @StuffCodeFrom AND @StuffCodeTo )
