CREATE FUNCTION rptanalyzSells  (    @Month int =[5] , @StuffCodeFrom bigint =[0] ,@StuffCodeTo bigint =9999999999999999  ) 
RETURNS table  AS  
return (
SELECT  rptanalyzSellsStuffCode.StuffCode, rptanalyzSellsStuffCode.GroupID,
	rptanalyzSellsStuffCode.Entity_LastMonth, rptanalyzSellsStuffCode.Weight_LastMonth, 
	rptanalyzSellsStuffCode.Price_LastMonth, 
	rptanalyzSellsStuffCode.TotallSellPrice_LastMonth, 
	rptanalyzSellsStuffCode.AVeEntite_LastMonth, 
	rptanalyzSellsStuffCode.AVeWeight_LastMonth,
	case when rptanalyzSellsGroup.Entity_LastMonth>0  
		then round ((rptanalyzSellsStuffCode.Entity_LastMonth/ rptanalyzSellsGroup.Entity_LastMonth *100),0)else 0 end as Entity_LastMonthShare ,
	case when rptanalyzSellsGroup.Weight_LastMonth>0  
		then round ((rptanalyzSellsStuffCode.Weight_LastMonth/ rptanalyzSellsGroup.Weight_LastMonth *100),0)else 0 end as Weight_LastMonthShare ,
	case when rptanalyzSellsGroup.Price_LastMonth>0  
		then round ((rptanalyzSellsStuffCode.Price_LastMonth/ rptanalyzSellsGroup.Price_LastMonth *100),0)else 0 end as Price_LastMonthShare ,

	case when rptanalyzSellsGroup.TotallSellPrice_LastMonth>0  
		then round ((rptanalyzSellsStuffCode.TotallSellPrice_LastMonth/ rptanalyzSellsGroup.TotallSellPrice_LastMonth *100),0)else 0 end as TotallSellPrice_LastMonthShare ,


	rptanalyzSellsStuffCode.Entity_Month, rptanalyzSellsStuffCode.Weight_Month, 
	rptanalyzSellsStuffCode.Price_Month	, 
	rptanalyzSellsStuffCode.TotallSellPrice_Month	, 
	rptanalyzSellsStuffCode.AVeEntity_Month, 
	rptanalyzSellsStuffCode.AVeWeight_Month, 
	case when rptanalyzSellsGroup.Entity_Month>0  
		then round ((rptanalyzSellsStuffCode.Entity_Month/ rptanalyzSellsGroup.Entity_Month *100),0)else 0 end as Entity_MonthShare ,
	case when rptanalyzSellsGroup.Weight_Month>0  
		then round ((rptanalyzSellsStuffCode.Weight_Month/ rptanalyzSellsGroup.Weight_Month *100),0)else 0 end as Weight_MonthShare ,
	case when rptanalyzSellsGroup.Price_Month>0  
		then round ((rptanalyzSellsStuffCode.Price_Month/ rptanalyzSellsGroup.Price_Month *100),0)else 0 end as Price_MonthShare ,

	case when rptanalyzSellsGroup.TotallSellPrice_Month>0  
		then round ((rptanalyzSellsStuffCode.TotallSellPrice_Month/ rptanalyzSellsGroup.TotallSellPrice_Month *100),0)else 0 end as TotallSellPrice_MonthShare ,


	rptanalyzSellsStuffCode.TOutputEntity, rptanalyzSellsStuffCode.TOutputWeight, 
	rptanalyzSellsStuffCode.TTotalOutputPrice,
	rptanalyzSellsStuffCode.TTotallSellPrice,	
	rptanalyzSellsStuffCode.TAveEntity, 
	rptanalyzSellsStuffCode.TAveWeight, 
	case when rptanalyzSellsGroup.TOutputEntity>0  
		then round ((rptanalyzSellsStuffCode.TOutputEntity/ rptanalyzSellsGroup.TOutputEntity *100),0)else 0 end as TOutputEntityShare ,
	case when rptanalyzSellsGroup.TOutputWeight>0  
		then round ((rptanalyzSellsStuffCode.TOutputWeight/ rptanalyzSellsGroup.TOutputWeight *100),0)else 0 end as TOutputWeightShare ,
	case when rptanalyzSellsGroup.TTotalOutputPrice>0  
		then round ((rptanalyzSellsStuffCode.TTotalOutputPrice/ rptanalyzSellsGroup.TTotalOutputPrice *100),0)else 0 end as TTotalOutputPriceShare  ,
	case when rptanalyzSellsGroup.TTotallSellPrice>0  
		then round ((rptanalyzSellsStuffCode.TTotallSellPrice/ rptanalyzSellsGroup.TTotallSellPrice *100),0)else 0 end as TTotallSellPriceShare 



FROM         rptanalyzSellsStuffCode(@Month, @StuffCodeFrom, @StuffCodeTo) rptanalyzSellsStuffCode INNER JOIN
                      rptanalyzSellsGroup(@Month, @StuffCodeFrom, @StuffCodeTo) rptanalyzSellsGroup ON rptanalyzSellsStuffCode.GroupID = rptanalyzSellsGroup.GroupID
)
GO 
