CREATE VIEW YearChek
AS
SELECT     TOP 100 PERCENT FormItems.FormItemID, Forms.FormType, Forms.CustomerID1, FormItems.FormID, FormItems.CheckNumber, 
                      FormItems.CheckDate, FormItems.CheckType, FormItems.ItemAmount, FormItems.ItemNote, FormItems.BankName, 
                      FormItems.AccountNumber, FormItems.City, FormItems.CustomerID2, FormItems.TopicCode, FormItems.DetailCode, 
                      FormItems.CTopicCode, FormItems.CTopicCode2, FormItems.BudgetCode, FormItems.ProjectID, FormItems.preFormItemID, 
                      FormItems.AidInfoNo, FormItems.AidInfoDate, FormItems.FirstUser, FormItems.LastUser, FormItems.AmountArz, 
                      FormItems.CheckState, FormItems.CheckFor, FormItems.AccountNumberNew, FormItems.Row,
                      FormItems.ServerID,Forms.YearID, FormItems.CashWage, FormItems.AccState, 
                         FormItems.ItemState, FormItems.ItemStateComment, FormItems.SeverableAmount, FormItems.RelatedID, FormItems.VAT, FormItems.TopicTypesI, 
                         FormItems.AccountNumberNew1, FormItems.CTopicCode3 , FormItems.ArzTypeID, FormItems.ArzAmount, 
                         FormItems.ArzRate, FormItems.DayDelay, FormItems.AmountDelay, FormItems.PerServerID, FormItems.CheckCounter, FormItems.ProductCode
FROM         FormItems INNER JOIN
                      Forms ON FormItems.FormID = Forms.FormID  AND FormItems.ServerID = Forms.ServerID AND FormItems.YearID = Forms.YearID INNER JOIN
                      FormTypes ON Forms.FormType = FormTypes.FormType LEFT OUTER JOIN
                      Customers Customers_2 ON FormItems.CustomerID2 = Customers_2.CustID LEFT OUTER JOIN
                      Customers Customers_1 ON Forms.CustomerID1 = Customers_1.CustID LEFT OUTER JOIN
                      FormItems FormItems_1 ON FormItems.FormItemID = FormItems_1.preFormItemID
WHERE     (FormItems_1.preFormItemID IS NULL) AND (Forms.FormState <>10)
ORDER BY FormItems.CheckDate
