CREATE VIEW RefineSell
AS
--SELECT     Recipts.ReciptID, Recipts.ReciptNumber, Recipts.ReciptDate, ReciptTypes.ReciptType, ReciptTypes.ReciptCaption, 
--                      ReciptItems.StuffCode, StuffCoding.c_StuffName, Units.UnitName, ReciptItems.StuffSize, ReciptItems.StuffDiameter, 
--                      ReciptItems.StuffAlloy, ReciptItems.ControlCode, ReciptItems.OutputEntity - ReciptItems.InputEntity AS Entity, 
--                      ReciptItems.OutputWeight - ReciptItems.InputWeight AS Weight, ReciptItems.UnitSellPrice, 
--                      ReciptItems.TotalOutputPrice - ReciptItems.TotalInputPrice AS Price, Recipts.StoreID, ReciptItems.ItemNote, 
--                      ReciptItems.PersonID1 AS ItemPersonID, Customers_2.CustID, Customers_2.CustName, CustomersGroup.CustomerGrpID, 
--                      CustomersGroup.CustomerGrpName, StuffGroups.GroupID, StuffGroups.GroupName, CT1.CustName AS ItemPersonName, 
--                      LookUps.Name AS SecondTypeName, StuffCoding.c_StuffTecInfo, StuffCoding.OwnerShipKind, ReciptItems.StandardRate,                     
--  					  ISNULL(case  ReciptTypes.SellEffect when 2 then -ReciptItems.TotalStandardRate else ReciptItems.TotalStandardRate end,0) as TotalStandardRate,
--					  ReciptTypes.SellEffect,Recipts.YearID,
--					  ISNULL(case  ReciptTypes.SellEffect when 2 then -ReciptItems.TotallSellPrice else ReciptItems.TotallSellPrice end,0) as TotallSellPrice,
--					  ISNULL(case  ReciptTypes.SellEffect when 2 then -ReciptItems.DeficitValue else ReciptItems.DeficitValue end,0)  as DeficitValue,
--					  ISNULL(case  ReciptTypes.SellEffect when 2 then -ReciptItems.TaxValue else ReciptItems.TaxValue end,0) as TaxValue

					  
--FROM         Customers Customers_2 LEFT OUTER JOIN
--                      CustomersGroup ON Customers_2.CustomerGrpID = CustomersGroup.CustomerGrpID RIGHT OUTER JOIN
--                      ReciptTypes RIGHT OUTER JOIN
--                      Recipts LEFT OUTER JOIN
--                      LookUps ON Recipts.SecondType = LookUps.LookUpID ON ReciptTypes.ReciptType = Recipts.ReciptType ON 
--                      Customers_2.CustID = Recipts.PersonID1 RIGHT OUTER JOIN
--                      Customers CT1 RIGHT OUTER JOIN
--                      ReciptItems ON CT1.CustID = ReciptItems.PersonID1 LEFT OUTER JOIN
--                      StuffGroups RIGHT OUTER JOIN
--                      StuffCoding ON StuffGroups.GroupID = StuffCoding.GroupID ON ReciptItems.StuffCode = StuffCoding.c_StuffCode LEFT OUTER JOIN
--                      Units ON StuffCoding.n_UnitCode = Units.UnitCode ON Recipts.ReciptID = ReciptItems.ReciptID AND Recipts.ServerID = ReciptItems.ServerID AND Recipts.YearID = ReciptItems.YearID
--WHERE     (Recipts.ReciptState < 3) AND (ReciptTypes.SellEffect <> 0)
SELECT                   dbo.Recipts.ReciptID, Recipts.ServerID, dbo.Recipts.ReciptNumber, dbo.Recipts.ReciptDate, dbo.ReciptTypes.ReciptType, dbo.ReciptTypes.ReciptCaption, ReciptItems.StuffCode, 
                         dbo.StuffCoding.c_StuffName, dbo.Units.UnitName, ReciptItems.StuffSize, ReciptItems.StuffDiameter, ReciptItems.StuffAlloy, 
                         ReciptItems.ControlCode, ReciptItems.OutputEntity - ReciptItems.InputEntity AS Entity, 
                         ReciptItems.OutputWeight - ReciptItems.InputWeight AS Weight, ReciptItems.UnitSellPrice, 
                         ReciptItems.TotalOutputPrice - ReciptItems.TotalInputPrice AS Price, dbo.Recipts.StoreID, dbo.Stores.c_StoreName, ReciptItems.ItemNote, 
                         ReciptItems.PersonID1 AS ItemPersonID, CT1.CustID, CT1.CustName, dbo.CustomersGroup.CustomerGrpID, 
                         dbo.CustomersGroup.CustomerGrpName, dbo.StuffGroups.GroupID, dbo.StuffGroups.GroupName, Customers_D.CustName AS ItemPersonName, 
                         dbo.LookUps.Name AS SecondTypeName, dbo.StuffCoding.c_StuffTecInfo, dbo.StuffCoding.OwnerShipKind, ReciptItems.StandardRate, 
                         ISNULL(CASE ReciptTypes.SellEffect WHEN 2 THEN - ReciptItems.TotalStandardRate ELSE ReciptItems.TotalStandardRate END, 0) AS TotalStandardRate, 
                         dbo.ReciptTypes.SellEffect, dbo.Recipts.YearID, 
                         ISNULL(CASE ReciptTypes.SellEffect WHEN 2 THEN - ReciptItems.TotallSellPrice ELSE ReciptItems.TotallSellPrice END, 0) AS TotallSellPrice, 
                         ISNULL(CASE ReciptTypes.SellEffect WHEN 2 THEN - (ReciptItems.DeficitValue+ ReciptItems.DeficitValue2 + ReciptItems.DeficitValue4+ ReciptItems.DeficitValue3 ) 
						                                           ELSE   (ReciptItems.DeficitValue+ ReciptItems.DeficitValue2 + ReciptItems.DeficitValue4+ ReciptItems.DeficitValue3 ) END, 0) AS DeficitValue, 

						 ISNULL(CASE ReciptTypes.SellEffect WHEN 2 THEN - (ReciptItems.DeficitValue ) 
						                                           ELSE   (ReciptItems.DeficitValue ) END, 0)  as DeficitValue1,
						 ISNULL(CASE ReciptTypes.SellEffect WHEN 2 THEN - (ReciptItems.DeficitValue2 ) 
						                                           ELSE   (ReciptItems.DeficitValue2 ) END, 0) as DeficitValue2,
						 ISNULL(CASE ReciptTypes.SellEffect WHEN 2 THEN - (ReciptItems.DeficitValue4 ) 
						                                           ELSE   (ReciptItems.DeficitValue4 ) END, 0) as DeficitValue4,
						 ISNULL(CASE ReciptTypes.SellEffect WHEN 2 THEN - (ReciptItems.DeficitValue3 ) 
						                                           ELSE   (ReciptItems.DeficitValue3 ) END, 0) as DeficitValue3,

                         ISNULL(CASE ReciptTypes.SellEffect WHEN 2 THEN - ReciptItems.TaxValue ELSE ReciptItems.TaxValue END, 0) AS TaxValue
						 ,Recipts.SellsMethod,Recipts.SellsEmporium,dbo.Recipts.PersonID2 as CustID2 ,
						  isnull(CT2.CustFirstName ,'') +' '+ CT2.CustName as CT2NAME
						 ,ReciptItems.Portage,ReciptItems.DiagnosisCalcTotalPrice														
FROM			dbo.Units 
			RIGHT OUTER JOIN	dbo.Customers AS Customers_D 
			RIGHT OUTER JOIN    dbo.LookUps 
			RIGHT OUTER JOIN	dbo.StuffGroups 
			INNER JOIN          dbo.CustomersGroup 
			INNER JOIN			dbo.Customers AS CT1 
			INNER JOIN          dbo.ReciptTypes 
			INNER JOIN          dbo.Recipts 
			INNER JOIN          dbo.Stores	ON dbo.Recipts.StoreID = dbo.Stores.n_StoreID ON dbo.ReciptTypes.ReciptType = dbo.Recipts.ReciptType 
											ON CT1.CustID = dbo.Recipts.PersonID1 ON dbo.CustomersGroup.CustomerGrpID = CT1.CustomerGrpID 
			INNER JOIN          dbo.ReciptItems ON dbo.Recipts.ReciptID = ReciptItems.ReciptID AND dbo.Recipts.ServerID = ReciptItems.ServerID AND dbo.Recipts.YearID = ReciptItems.YearID 
			INNER JOIN          dbo.StuffCoding ON ReciptItems.StuffCode = dbo.StuffCoding.c_StuffCode	ON dbo.StuffGroups.GroupID = dbo.StuffCoding.GroupID 
												ON dbo.LookUps.LookUpID = dbo.Recipts.SecondType			ON Customers_D.CustID = ReciptItems.PersonID1 
												ON dbo.Units.UnitCode = dbo.StuffCoding.n_UnitCode
			INNER JOIN			dbo.Customers AS CT2 on dbo.Recipts.PersonID2=CT2.CustID


WHERE        (dbo.Recipts.ReciptState < 3) AND (dbo.ReciptTypes.SellEffect <> 0)
  
  
  

