CREATE FUNCTION ChkUsersCustomersGroups ( @UserAdmin Tinyint , @UserID  int ,@CustID int )
RETURNS bit 
BEGIN
  IF @UserAdmin = 1  RETURN(1)
  IF @CustID = 0  RETURN(1)
  IF ( SELECT COUNT(CustomerGrpID) FROM UsersCustomersGroups WHERE (UserID = @UserID) ) = 0
   RETURN(1)
  ELSE
  BEGIN
    IF (SELECT COUNT(Customers.CustID) 
          FROM UsersCustomersGroups INNER JOIN
               CustomersGroup ON UsersCustomersGroups.CustomerGrpID = CustomersGroup.CustomerGrpID INNER JOIN
               Customers ON CustomersGroup.CustomerGrpID = Customers.CustomerGrpID
           WHERE (UsersCustomersGroups.UserID = @UserID) AND (Customers.CustID = @CustID)) = 0
      RETURN(0)
    ELSE
      RETURN(1)
  END
  RETURN(0)
END
