CREATE  FUNCTION AidRecallSpecial_2 (@YearId int = 1395 , @reciptType int = 12 	)

RETURNS table  AS  

return (  

SELECT	ReciptItems.PrvYearID  as PrvYearid , ReciptItems.preReciptItemID, ReciptItems.serverid  , --Recipts.ReciptType,
		SUM(ReciptItems.InputEntity + ReciptItems.OutputEntity) AS Entity, 
		SUM(ReciptItems.InputWeight + ReciptItems.OutputWeight) AS Weight, 
		ISNULL( SUM(cast(ReciptItems.TotalInputPrice as decimal(38,0)) + cast(ReciptItems.TotalOutputPrice as decimal(38,0)) ), 0) AS Price ,
		SUM(cast(ReciptItems.TotallSellPrice as decimal(38,0))) AS TotallSellPrice ,count(*) as  CountNo
FROM	ReciptItems INNER JOIN
		Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND 
					ReciptItems.ServerID = Recipts.ServerID AND 
					ReciptItems.YearID = Recipts.YearID   INNER JOIN
		ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
WHERE	(Recipts.ReciptState < 3) 
 
		AND
		 (Recipts.ReciptType in ( 11 , 15))
		--between 
			--				case when RecallType in(22) then 0 else @reciptType end 
				--				and  
					--		case when RecallType in(22) then 999999 else @reciptType end 
			--)
		AND 
		(Recipts.yearid in(1396,1397)) 
		--and 
	--	ReciptItems.preReciptItemID = 1739999
		--between 
		--			case 
		--				when (select FilterYearIDActive from ReciptTypes1 where recipttype = @reciptType )=1 
		--					then 0 
		--				else @YearId 
		--			end  and @YearId )
 
GROUP BY ReciptItems.PrvYearID , ReciptItems.preReciptItemID, ReciptItems.serverid  --, Recipts.ReciptType
)

