CREATE  FUNCTION RecallSpecial_2
			
(
                @ReciptType int=12            ,@AidDate char(10) ='90/01/02', 
				@StuffCodeFrom Bigint =0      ,@StuffCodeTo Bigint = 9999999999,
				@StoreIDFrom smallint =0      ,@StoreIDTo smallint=999, 
				@ControlcodeFrom bigint = 0   ,@ControlcodeTo bigint =999999, 
				@DiameterFrom float =0        ,@DiameterTo float=0, 
				@RcpNumberFrom int=99999999   ,@RcpNumberTo int=99999, 
				@ItemPersonIDFrom int=0       ,@ItemPersonIDTo int=99999 ,
				@DateFrom char(10)='01/01/01' ,@DateTo char(10)='99/12/29', 
				@YearIDFrom int=0             ,@YearIDTo int=9999, 
				@SecondTypeItemFrom int=0     ,@SecondTypeItemTo int=9999, 
				@SellsEmporiumFrom int=0     ,@SellsEmporiumTo int=9999
			)

RETURNS table  AS  
return (  

SELECT * 
FROM (
		SELECT  RI.YearID, RI.ReciptItemID, RI.StuffCode, SC.c_StuffName, 
				RI.ControlCode, RI.StuffSize , RI.StuffDiameter, RI.StuffAlloy, 
				RI.PersonID1, ISNULL(CT1.CustFirstName,'')+' '+ CT1.CustName+dbo.GetBlacklistMarker(Blacklist ) as CustName,  CT1.ReagentName ,
				RI.InputEntity + RI.OutputEntity  as BaseEntity ,
				RI.InputWeight + RI.OutputWeight  as BaseWeight ,
				ARS.Entity as DecEntity ,
				ARS.Weight as DecWeight ,
				ROUND(RI.InputEntity + RI.OutputEntity - ISNULL(ARS.Entity, 0.0), 3) AS Entity,
				ROUND(RI.InputWeight + RI.OutputWeight - ISNULL(ARS.Weight, 0.0), 3) AS Weight,
				case when ROUND(RI.InputEntity + RI.OutputEntity - ISNULL(ARS.Entity, 0), 3) <> 0
						then ROUND ((RI.InputWeight + RI.OutputWeight - ISNULL(ARS.Weight, 0)) / (RI.InputEntity + RI.OutputEntity - ISNULL(ARS.Entity, 0)),3) 
						else 0 
				end as  WeightOnEntity ,
				cast(RI.TotalInputPrice as decimal(38,0)) + cast(RI.TotalOutputPrice as decimal(38,0)) - cast(ISNULL(ARS.Price,0) as decimal(38,0)) AS Price , 
				cast(RI.TotallSellPrice as decimal(38,0)) - cast(ARS.TotallSellPrice as decimal(38,0)) AS TotallSellPrice , 
				RI.StuffGrade, 
				CASE RT.IncreasingInventoryStore WHEN 2 THEN R.StoreID2 ELSE R.StoreID END AS StoreID,
				S.c_StoreName,	SC.UnitName, R.ReciptNumber, R.ReciptDate,
				R.AidNumber AS MAidNumber, R.AidDate AS MAidDate , RT.ReciptCaption, 
				RI.ItemNote, RI.Auxiliary,RI.UnitSellPrice, 
				'' AS قطع, '' AS مؤلف, '' AS مترجم, '' AS نويسنده, '' AS جلد,
				'' AS پخش, '' AS طبقه, '' AS موضوع, 
				cast(ARS.CountNo as int) CountNo , 
				RI.Portage, RI.Article, RI.Wage, RI.Scoria,RI.AidNumber, 
				RI.AidDate, RI.UseUnitID, '' as UseUnitName ,RI.SecondTypeItem, 
				Fitful.FitfulID AS _Checked  , Fitful.FitfulID AS  __EntityEdit,
				isnull(RI.RequestedEntity,0) as RequestedEntity,
				ROUND(RI.InputEntity + RI.OutputEntity - ISNULL(ARS.Entity, 0), 3) - isnull(RI.RequestedEntity,0) as Entity2 , 
				RI.WaterCo, RI.DeficitValue, RI.DeficitValue2, RI.DeficitValue4, RI.DeficitValue3,  
				RI.TaxCo,RI.TaxValue,LU.Name AS SecondTypeName,
				CASE WHEN ISNULL(ARS.Entity,0) <> 0 THEN ROUND(ISNULL(ARS.Price,0) / ARS.Entity,2) ELSE 0 END UnitSellPricePost,
				CASE WHEN (ROUND(CASE WHEN ISNULL(ARS.Entity,0) <> 0 THEN ROUND(ISNULL(ARS.Price,0) / ARS.Entity,2) ELSE 0 END,2) 
				          = ROUND(RI.UnitSellPrice,2)) 
						  OR
						  (ROUND(CASE WHEN ISNULL(ARS.Entity,0) <> 0 THEN ROUND(ISNULL(ARS.Price,0) / ARS.Entity,2) ELSE 0 END,2) = 0) 
					THEN 0 
					ELSE 1 
				END AS UnitSellPriceCHK, 
				RI.MachineNo, RI.MachineName, RI.ItemDate, '' AS  padidAvarandehName, SC.c_StuffTecInfo, 
				RI.ProductCode, RI.ProductModel, RI.ArzAmount, RI.ArzRate, 
				R.PersonID2, R.ServerID, R.ReciptID, R.PersonID3, R.MasirID, ReciptNote, 
				CT1.RegisterNumber ,R.PersonID1 AS PersonID1M,R.PersonID2 AS PersonID2M,R.PersonID3 AS PersonID3M,
				'' AS CustName1M,'' AS CustName2M,'' AS CustName3M, 
				SC.sd1, SC.sd2, SC.sd3, SC.sd4, SC.sd5, SC.sd6, SC.sd7, SC.sd8, SC.sd9, R.ReciptState
				,UseUnitsM.UseUnitName AS UseUnitNameM , ProductModelS.Name AS ProductModelName,RI.CommissionPrice, RI.Commission, RI.CommissionCurrency, 
				RI.UnitCommissionCo, RI.StandardConsumption, RI.UnitCommission, RI.StandardConsumptionCo


	FROM	            Recipts         R
			INNER JOIN	ReciptItems     RI  ON	RI.ReciptID = R.ReciptID 
									        AND RI.ServerID = R.ServerID 
									        AND RI.YearID   = R.YearID 
			INNER JOIN	ReciptTypes     RT  ON R.ReciptType = RT.ReciptType 
			INNER JOIN	Stores          S   ON R.StoreID = S.n_StoreID
			INNER JOIN	Vu_StuffCoding2  SC  on  SC.c_StuffCode=RI.StuffCode
			LEFT  JOIN	Customers       CT1 ON RI.PersonID1 = CT1.CustID 
			LEFT  JOIN	VU_aidrecal     ARS ON		RI.ReciptItemID = ARS.preReciptItemID 
											    AND RI.YearID       = ARS.PrvYearid 
												AND RI.stuffcode    = ARS.stuffcode 
			LEFT  JOIN LookUps          LU ON RI.SecondTypeItem = LU.LookUpID 
            LEFT OUTER JOIN UseUnits AS UseUnitsM ON UseUnitsM.UseUnitID = R.UseUnitID
            LEFT JOIN LookUps AS ProductModelS ON RI.ProductModel = ProductModelS.LookUpID

			CROSS JOIN 	Fitful

WHERE			(R.ReciptState <3) 
			AND (R.ReciptType in (25))
			AND (RI.StuffCode	BETWEEN	@StuffCodeFrom AND @StuffCodeTo)
			AND (RI.PersonID1	BETWEEN @ItemPersonIDFrom AND @ItemPersonIDTo OR RI.PersonID1 IS NULL)
			AND (R.ReciptDate		BETWEEN @DateFrom AND @DateTo )
			AND (R.YearID			BETWEEN 1397 AND @YearIDTo)
			AND (StoreID                BETWEEN @StoreIDFrom and  @StoreIDTo )
			AND (ROUND(RI.InputWeight + RI.OutputWeight - ISNULL(ARS.Weight, 0), 3) >0   )
            AND (R.SellsEmporium BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)
 
) DERIVEDTBL 
)
