CREATE VIEW Vu_StoreReciptItems
AS
SELECT R_S_P.ReciptCaption as 'نوع فرم',R_S_P.ReciptNumber as 'شماره فرم ', 
R_S_P.ReciptDate as 'تاریخ فرم', R_S_P.StuffCode as 'کدکالا', StuffCoding.c_StuffName as 'شرح کالا',StuffCoding.c_StuffTecInfo as 'مشخصات فنی',StuffCoding.GroupID,StuffCoding.sd7,
R_S_P.PersonID1 as 'مشتری1', R_S_P.ProductCode, StuffCoding_1.c_StuffName AS ProductName ,Customers_1.CustName AS 'نام مشتری1', Customers_1.Mobile,
R_S_P.PersonID2 as 'مشتری2',
Customers_2.CustName AS 'نام مشتری2', R_S_P.PersonID3 as 'مشتری3', Customers_3.CustName AS 'نام مشتری3',
R_S_P.PersonID4, Customers_4.CustName AS CustName4,
R_S_P.InputEntity  as 'مقدار وارده', R_S_P.OutputEntity as 'مقدار صادره',
R_S_P.InputWeight as 'وزن وارده', R_S_P.OutputWeight as 'وزن صادره', R_S_P.UnitSellPrice as 'فی',
R_S_P.WaterCo , R_S_P.DeficitValue as 'تخفیف', R_S_P.TaxCo, R_S_P.TaxValue as 'مالیات'
,R_S_P.TotalInputPrice as 'مبلغ پس از تفیف وارده' , R_S_P.TotalOutputPrice As 'مبلغ پس از تخفیف صادره',
R_S_P.TotalInputPrice1 As 'بهای کل وارده', R_S_P.TotalOutputPrice1 as 'بهای کل صادره',
AllDeficits_ForRecipts.DeficitAdd_Dec , 
R_S_P.StoreID as 'کدانبار', Stores.c_StoreName as 'نام انبار',R_S_P.AidNumber, R_S_P.AidDate, R_S_P.AidNumberD, R_S_P.AidDateD,
R_S_P.PersonID1D, Customers_D.CustName AS CustNameD, R_S_P.DocNo, R_S_P.DocDate,
R_S_P.ReciptNote, R_S_P.ReciptID, R_S_P.YearID, R_S_P.ServerID,
R_S_P.TotallSellPriceBase AS 'خالص', R_S_P.ReciptState, R_S_P.MachineName, R_S_P.MachineNo,
R_S_P.MachineInfo, R_S_P.TruckNumber, R_S_P.Code, R_S_P.TransFormID
,Customers_1.City, Zone.Shahr, Zone.Ostan, UnitName
,'' AS ParentForm
,Customers_1.CustomerGrpID, CustomersGroup_1.CustomerGrpName
,cast( R_S_P.ProductModel as bigint) AS ProductModel, ProductModelS.Name AS ProductModelName , R_S_P.SecondTypeName
, R_S_P.SellsMethod,R_S_P.SellsMethodName, R_S_P.SellsEmporium, R_S_P.SellsEmporiumName,R_S_P.ItemNote
,R_S_P.ArzTypeID ,R_S_P.CurrenciesName ,R_S_P.ArzRate,R_S_P.ArzAmount
,R_S_P.RialsEqual,R_S_P.Commission , SecondTypeNameItem
,case when R_S_P.DiagnosisCalcTotalPrice = 0 then (R_S_P.InputEntity+R_S_P.OutputEntity)*R_S_P.Commission 
else (R_S_P.InputWeight+R_S_P.OutputWeight)*R_S_P.Commission end as CommissionCo,R_S_P.ControlCode
,R_S_P.acc_CTopicCode,R_S_P.acc_CTopicCode2,R_S_P.acc_CTopicCode3
,R_S_P.RIDateMS,R_S_P.RIDateME,R_S_P.ReciptType as 'کد نوع فرم'
FROM ReciptItems_Stock_Oper AS R_S_P INNER JOIN
StuffCoding ON R_S_P.StuffCode=StuffCoding.c_StuffCode INNER JOIN
Units ON StuffCoding.n_UnitCode = Units.UnitCode INNER JOIN
Vu_CustomersGroups_F AS Customers_1 ON R_S_P.PersonID1=Customers_1.CustID INNER JOIN
Vu_CustomersGroups_F AS Customers_2 ON R_S_P.PersonID2=Customers_2.CustID INNER JOIN
Vu_CustomersGroups_F AS Customers_3 ON R_S_P.PersonID3=Customers_3.CustID INNER JOIN
Vu_CustomersGroups_F AS Customers_4 ON R_S_P.PersonID4=Customers_4.CustID INNER JOIN
Vu_CustomersGroups_F AS Customers_D ON R_S_P.PersonID1D=Customers_D.CustID INNER JOIN
Stores ON R_S_P.StoreID = Stores.n_StoreID
INNER JOIN StuffCoding AS StuffCoding_1 ON R_S_P.ProductCode = StuffCoding_1.c_StuffCode
INNER JOIN CustomersGroup AS CustomersGroup_1 ON Customers_1.CustomerGrpID = CustomersGroup_1.CustomerGrpID
 LEFT OUTER JOIN Zone ON Customers_1.CityCode = Zone.ShahrCode
INNER JOIN LookUps AS ProductModelS ON R_S_P.ProductModel = ProductModelS.LookUpID
LEFT OUTER JOIN Stores AS Stores_2 ON R_S_P.StoreID2 = Stores_2.n_StoreID
LEFT OUTER JOIN AllDeficits_ForRecipts ON R_S_P.ReciptID = AllDeficits_ForRecipts.ReciptID
AND AllDeficits_ForRecipts.ServerID = R_S_P.ServerID AND AllDeficits_ForRecipts.YearID = R_S_P.YearID
WHERE 
 R_S_P.StuffCode in(3501000,3501001,3501002,3601000,3601001,3601003,3601004) and
(R_S_P.ReciptType = 5 or R_S_P.ReciptType =6 or R_S_P.ReciptType =9 or R_S_P.ReciptType =11 or 
R_S_P.ReciptType =14 or R_S_P.ReciptType =17 or R_S_P.ReciptType =21 or R_S_P.ReciptType =22 or
 R_S_P.ReciptType =31 or R_S_P.ReciptType =56)

