CREATE FUNCTION ChkUsersSellsEmporium( @UserAdmin Tinyint , @UserID  int ,@UserSecurityCheckActive bigint  , @SellsEmporium  int)
RETURNS bit 
BEGIN
  IF  ( (@UserAdmin = 1) OR ((@UserSecurityCheckActive  &  1024)<>1024))  RETURN(1)
  IF ( SELECT COUNT(SellsEmporium) FROM UsersSellsEmporium WHERE (UserID = @UserID) ) = 0
   RETURN(1)
ELSE
  BEGIN
    IF (SELECT COUNT(SellsEmporium) 
          FROM UsersSellsEmporium
           WHERE (UserID = @UserID) AND (SellsEmporium = @SellsEmporium)) = 0
      RETURN(0)
    ELSE
      RETURN(1)
  END
  RETURN(0)
END
