CREATE FUNCTION AddDecCommaDilmetr (@OperatorID  varchar(max) ,@ADDID varchar(max) , @DecID varchar(max) )
RETURNS varchar(max) 
begin
declare @OperatorIDs varchar(max)='' 
declare @ADDIDs varchar(max)='' 
declare @DecIDs varchar(max)='' 

set @OperatorIDs=','+@OperatorID+','
set @ADDIDs=','+@ADDID+','
set @DecIDs=','+@DecID+','

--print str(CHARINDEX(@ADDIDs,@OperatorIDs)) + '  ' +@ADDIDs
if @ADDID <>'' and CHARINDEX(@ADDIDs,@OperatorIDs)=0
  set @OperatorIDs=@OperatorIDs+@ADDID+','
   
--print CHARINDEX(@DecIDs,@OperatorIDs)
if @DecID <>'' and CHARINDEX(@DecIDs,@OperatorIDs)<>0
  set @OperatorIDs=REPLACE( @OperatorIDs,@DecIDs,',')

declare @l int
set @l=len(@OperatorIDs)
set @OperatorIDs=left(@OperatorIDs,@l-1)
set @OperatorIDs=RIGHT (@OperatorIDs,@l-2)


  RETURN(@OperatorIDs)
end

