		    else 0 end 
	when 2  then case FormTypes.CustCodeUse4Bed ---- اسناد درجريان وصول----
			when 1 then CustomersGroup_1.acc_ReChecksTopicCode 
			when 2 then CustomersGroup_2.acc_ReChecksTopicCode 
		    else 0 end 
	when 3  then case FormTypes.CustCodeUse4Bed ----اسناد دريافتني----
			when 1 then CustomersGroup_1.acc_ChecksTopicCode 
			when 2 then CustomersGroup_2.acc_ChecksTopicCode 
		    else 0 end 
	when 4  then case FormTypes.CustCodeUse4Bed ----اسناد واخواستي ----
			when 1 then CustomersGroup_1.acc_ReChecksTopicCode 
			when 2 then CustomersGroup_2.acc_ReChecksTopicCode 
		    else 0 end 
	when 5  then case FormTypes.CustCodeUse4Bed ----اسناد تضميني ----
			when 1 then CustomersGroup_1.acc_CertifyTopicCode 
			when 2 then CustomersGroup_2.acc_CertifyTopicCode 
		    else 0 end 
	when 6  then case FormTypes.CustCodeUse4Bed --- اسناد پرداختني ----
			when 1 then CustomersGroup_1.acc_ChecksTopicCode 
			when 2 then CustomersGroup_2.acc_ChecksTopicCode 
		    else 0 end 
	when 7  then case FormTypes.CustCodeUse4Bed ----اسناد پرداختني خاص----
			when 1 then CustomersGroup_1.acc_ChecksTopicCode 
			when 2 then CustomersGroup_2.acc_ChecksTopicCode 
		    else 0 end 
	when 9  then Forms.TopicCode  ---کد حساب در فرم ----
	when 11  then LookUps_1.acc_TopicCode ---- موضوع دريافت و پرداخت 1------
	when 12  then LookUps_2.acc_TopicCode ---- موضوع دريافت و پرداخت 2------
	when 13  then FormTypes.ConstTopicCode_Bed ---- کد ثابت ------
--	when 15 then BT.AccCode -- کد حساب بر اساس کد بودجه 
else 0 end 
--end 
as TopicCode_Bed,
 case  FormTypes.DefaultDetail_Bed 
	when 1 then case FormTypes.CustCodeUse4Bed ---- اطلاعات مشتري ----
			when 1 then Customers_1.acc_DetailCode 
