CREATE VIEW FN_Recal_Weight
AS

   SELECT R25.ReciptID, R25.yearid,R25.ServerID, R25.PersonID1, RI25.ReciptItemID ,
	      Rec15.StuffCode RECStuffCode, RI25.StuffCode , 
	      RI25.OutputEntity  as r25Entity, RI25.OutputWeight as  r25Weight , Rec15.OutputEntity as r15Entity,  Rec15.OutputWeight as r15Weight ,
		  isnull(RI25.RollbackEntity,0) as RollbackEntity
          
   FROM Recipts R25 INNER JOIN
		ReciptItems RI25 on RI25.ReciptID = R25.ReciptID and RI25.YearID = R25.YearID  AND 
		RI25.ServerID = R25.ServerID INNER JOIN 
	
		(
			SELECT		ri15.preReciptItemID,  ri15.StuffCode, r15.YearID, r15.ServerID, 
						ri15.PrvYearID, Sum(ri15.OutputEntity) OutputEntity , Sum(ri15.OutputWeight) OutputWeight
			FROM		Recipts     AS r15 INNER JOIN
						ReciptItems AS ri15 ON ri15.ReciptID = r15.ReciptID AND ri15.YearID = r15.YearID AND ri15.ServerID = r15.ServerID
            GROUP BY    ri15.StuffCode, ri15.preReciptItemID,  r15.YearID, r15.ServerID, ri15.PrvYearID

		) Rec15 on Rec15.preReciptItemID=RI25.ReciptItemID and Rec15.ServerID=RI25.ServerID and RI25.YearID=Rec15.PrvYearID

        LEFT OUTER JOIN Recipts R12 on R25.YearID=R12.yearid 
									AND R25.ParentReciptID=R12.ReciptID AND R25.ServerID=R12.ServerID
		                            AND R12.ReciptState < 3             AND R12.ReciptType = 12

	 
			
   WHERE R25.ReciptType=25  and R25.ParentReciptID is null   

