CREATE FUNCTION dbo.MakeDocuments_Coffer 
							(
								@AllDocAble Tinyint=0,
								@FormDateFrom varchar(10)='0000/00/00', 
								@FormDateTo varchar(10)='9999/99/99',
								@FormNoFrom int =-9999999, 
								@FormNoTo int= 99999999,
								@CustNoFrom int=0 , 
								@CustNoTo int=999999999, 
								-- @FormType varchar (3)= [50],
								@SellsEmporiumFrom int=0,
								@SellsEmporiumTo int = 999999999 ,
								@PayTypesFrom int=0,
								@PayTypesTo int = 999999999 ,
								@MakeDocKind int =1 ,
								@AidDateFrom char(10)='0000/00/00', 
								@AidDateTo char(10)='9999/99/99' , 
								@DateSelect int = 0
							)
RETURNS @retFindReports TABLE 
  (
	ID bigint NULL,
	FormType tinyint NOT NULL,
	FormCaption varchar(50) NOT NULL,
	FormID int NOT NULL,
	FormNumber int NOT NULL,
	FormDate char(10) NOT NULL,
	Amount money NOT NULL,
	AidInfoNo varchar(40) NOT NULL,
	AidInfoDate char(10) NOT NULL,
	AidAmount int NOT NULL,
	FomNote varchar(1255) NULL,
	TopicCode bigint NULL,
	DetailCode int NULL,
	CTopicCode int NULL,
	CTopicCode2 int NULL,
	CTopicCode3 int NULL,
	debt float NULL,
	credit float NULL,
	bedbes int NOT NULL,
	ServerID int NOT NULL,
	YearID int NOT NULL,
	CustName1 varchar(150) NULL,
	CustName2 varchar(150) NULL,
	ArzAmount money NOT NULL,
	PO varchar(30) NULL,
	ArzTypeID int NULL,
	BudgetCode int NULL,
	ProjectID int NULL,
	Currencydebit float NULL,
	Currencycredit float NULL,
	CurrencyRate float NOT NULL

  )
	AS BEGIN

	
INSERT INTO @retFindReports

SELECT	CASE @MakeDocKind WHEN 2 THEN 0 ELSE Forms.ID END AS ID,
		FormTypes.FormType  ,  
		FormTypes.FormCaption,
		CASE @MakeDocKind WHEN 2 THEN 0 ELSE Forms.FormID END AS FormID,
        CASE @MakeDocKind WHEN 2 THEN 0 ELSE Forms.FormNumber END FormNumber, 
		Forms.FormDate,
		Forms.Amount, 
		isnull(Forms.AidInfoNo,'') as AidInfoNo , 
		isnull(Forms.AidInfoDate,'') as AidInfoDate,
		0 AidAmount,
		Forms.FomNote,
		-- TopicCode 
		case FM.ACC_KIND 
		when 'Debit' then 
			case  FormTypes.DefaultTopic_Bed 
				when 1 then case FormTypes.CustCodeUse4Bed-- كد حساب --
						when 1 then 
							case when Customers_1.acc_TopicCode > 0 then Customers_1.acc_TopicCode 
								else CustomersGroup_1.acc_TopicCode end 
						when 2 then 
							case when Customers_2.acc_TopicCode > 0 then Customers_2.acc_TopicCode 
								else CustomersGroup_2.acc_TopicCode end 
						when 3 then 
							case when Customers_3.acc_TopicCode > 0 then Customers_3.acc_TopicCode 
								else CustomersGroup_3.acc_TopicCode end 
						else 0 end 
				when 2  then case FormTypes.CustCodeUse4Bed ---- اسناد درجريان وصول----
						when 1 then CustomersGroup_1.acc_ReChecksTopicCode 
						when 2 then CustomersGroup_2.acc_ReChecksTopicCode 
						else 0 end 
				when 3  then case FormTypes.CustCodeUse4Bed ----اسناد دريافتني----
						when 1 then CustomersGroup_1.acc_ChecksTopicCode 
						when 2 then CustomersGroup_2.acc_ChecksTopicCode 
						else 0 end 
				when 4  then case FormTypes.CustCodeUse4Bed ----اسناد واخواستي ----
						when 1 then CustomersGroup_1.acc_ReChecksTopicCode 
						when 2 then CustomersGroup_2.acc_ReChecksTopicCode 
						else 0 end 
				when 5  then case FormTypes.CustCodeUse4Bed ----اسناد تضميني ----
						when 1 then CustomersGroup_1.acc_CertifyTopicCode 
						when 2 then CustomersGroup_2.acc_CertifyTopicCode 
						else 0 end 
				when 6  then case FormTypes.CustCodeUse4Bed --- اسناد پرداختني ----
						when 1 then CustomersGroup_1.acc_ChecksTopicCode 
						when 2 then CustomersGroup_2.acc_ChecksTopicCode 
						else 0 end 
				when 7  then case FormTypes.CustCodeUse4Bed ----اسناد پرداختني خاص----
						when 1 then CustomersGroup_1.acc_ChecksTopicCode 
						when 2 then CustomersGroup_2.acc_ChecksTopicCode 
						else 0 end 
				when 9  then Forms.TopicCode  ---کد حساب در فرم ----
				when 11  then LookUps_1.acc_TopicCode ---- موضوع دريافت و پرداخت 1------
				when 12  then LookUps_2.acc_TopicCode ---- موضوع دريافت و پرداخت 2------
				when 13  then FormTypes.ConstTopicCode_Bed ---- کد ثابت ------
			--	when 15 then BT.AccCode -- کد حساب بر اساس کد بودجه 
			else 0 end 

		when 'Credit' then 
			 case  FormTypes.DefaultTopic_Bes 
				when 1 then case FormTypes.CustCodeUse4BeS--  كد حساب --
						when 1 then 
							case when Customers_1.acc_TopicCode > 0 then Customers_1.acc_TopicCode 
								else CustomersGroup_1.acc_TopicCode end 
						when 2 then 
							case when Customers_2.acc_TopicCode > 0 then Customers_2.acc_TopicCode 
								else CustomersGroup_2.acc_TopicCode end 
						when 3 then 
							case when Customers_3.acc_TopicCode > 0 then Customers_3.acc_TopicCode 
								else CustomersGroup_3.acc_TopicCode end 

						else 0 end 
				when 2  then case FormTypes.CustCodeUse4Bes ---- اسناد درجريان وصول----
						when 1 then CustomersGroup_1.acc_ReChecksTopicCode 
						when 2 then CustomersGroup_2.acc_ReChecksTopicCode 

						else 0 end 
				when 3  then case FormTypes.CustCodeUse4Bes ----اسناد دريافتني----
						when 1 then CustomersGroup_1.acc_ChecksTopicCode 
						when 2 then CustomersGroup_2.acc_ChecksTopicCode 

						else 0 end 
				when 4  then case FormTypes.CustCodeUse4Bes ----اسناد واخواستي ----
						when 1 then CustomersGroup_1.acc_ReChecksTopicCode 
						when 2 then CustomersGroup_2.acc_ReChecksTopicCode 

						else 0 end 
				when 5  then case FormTypes.CustCodeUse4Bes ----اسناد تضميني ----
						when 1 then CustomersGroup_1.acc_CertifyTopicCode 
						when 2 then CustomersGroup_2.acc_CertifyTopicCode 

						else 0 end 
				when 6  then case FormTypes.CustCodeUse4Bes -- اسناد پرداختني --
						when 1 then CustomersGroup_1.acc_ChecksTopicCode 
						when 2 then CustomersGroup_2.acc_ChecksTopicCode 

						else 0 end 
				when 7  then case FormTypes.CustCodeUse4Bes --اسناد پرداختني خاص--
						when 1 then CustomersGroup_1.acc_ChecksTopicCode 
						when 2 then CustomersGroup_2.acc_ChecksTopicCode 

						else 0 end 

				when 9  then Forms.TopicCode  --کد حساب در فرم --

				when 11  then LookUps_1.acc_TopicCode -- موضوع دريافت و پرداخت 1--
				when 12  then LookUps_2.acc_TopicCode -- موضوع دريافت و پرداخت 2--
				when 13  then FormTypes.ConstTopicCode_Bes -- کد ثابت --
				--when 15 then BT.AccCode -- کد حساب بر اساس کد بودجه 
				else 0 end 
			ELSE FM.TopicCode
			END as TopicCode ,
		case FM.ACC_KIND 
		when 'Debit' then -- case ACC_KIND 
			 case  FormTypes.DefaultDetail_Bed 
				when 1 then case FormTypes.CustCodeUse4Bed ---- اطلاعات مشتري ----
						when 1 then Customers_1.acc_DetailCode 
						when 2 then Customers_2.acc_DetailCode 
						when 3 then Customers_3.acc_DetailCode 
						else 0 end 
				when 2 then LookUps_1.acc_DetailCode ---- موضوع دريافت و پرداخت 1------
				when 3 then LookUps_2.acc_DetailCode ---- موضوع دريافت و پرداخت 2------
				when 4  then Forms.DetailCode  ---کد حساب در فرم ----
			--	when 8 then BT.DetailCode -- کد تفصیلی بر اساس کد بودجه 
			else 0 end
		when 'Credit' then -- case ACC_KIND 
			case  FormTypes.DefaultDetail_Bes 
				when 1 then case FormTypes.CustCodeUse4Bes ---- اطلاعات مشتري ----
						when 1 then Customers_1.acc_DetailCode 
						when 2 then Customers_2.acc_DetailCode 
						when 3 then Customers_3.acc_DetailCode 
						else 0 end 
				when 2 then LookUps_1.acc_DetailCode ---- موضوع دريافت و پرداخت 1------
				when 3 then LookUps_2.acc_DetailCode ---- موضوع دريافت و پرداخت 2------
				when 4  then Forms.DetailCode  ---کد حساب در فرم ----
				--when 8 then BT.DetailCode -- کد تفصیلی بر اساس کد بودجه 
			else 0 end
		ELSE FM.DetailCode -- case ACC_KIND 
		END  as DetailCode ,-- case ACC_KIND 
		case FM.ACC_KIND 
		when 'Debit' then -- case ACC_KIND 
			case  FormTypes.DefaultCTopic_Bed 
			when 1 then case FormTypes.CustCodeUse4Bed ---- اطلاعات گروه مشتري ----
					when 1 then CustomersGroup_1.acc_CTopicCode 
					when 2 then CustomersGroup_2.acc_CTopicCode 
					when 3 then CustomersGroup_3.acc_CTopicCode 

					else 0 end 
			when 2 then LookUps_1.acc_CTopicCode ---- موضوع دريافت و پرداخت 1------
			when 3 then LookUps_2.acc_CTopicCode ---- موضوع دريافت و پرداخت 2------
			when 4  then Forms.CTopicCode  ---کد حساب در فرم ----
			when 6 then case FormTypes.CustCodeUse4Bed ---- اطلاعات مشتري ----
					when 1 then Customers_1.acc_CTopicCode 
					when 2 then Customers_2.acc_CTopicCode 
					when 3 then Customers_3.acc_CTopicCode 
					else 0 end 
			when 7 then Customers_3.acc_CTopicCode 	
			when 8 then SellsEmporiums.CTopicCode	
		else 0 end
		when 'Credit' then -- case ACC_KIND 
			 case  FormTypes.DefaultCTopic_Bes 
				when 1 then case FormTypes.CustCodeUse4Bes ---- اطلاعات گروه مشتري ----
						when 1 then CustomersGroup_1.acc_CTopicCode 
						when 2 then CustomersGroup_2.acc_CTopicCode 
						when 3 then CustomersGroup_3.acc_CTopicCode 

						else 0 end 
				when 2 then LookUps_1.acc_CTopicCode ---- موضوع دريافت و پرداخت 1------
				when 3 then LookUps_2.acc_CTopicCode ---- موضوع دريافت و پرداخت 2------
				when 4  then Forms.CTopicCode  ---کد حساب در فرم ----

				when 6  then case FormTypes.CustCodeUse4Bes ---- اطلاعات مشتري ----
						when 1 then Customers_1.acc_CTopicCode 
						when 2 then Customers_2.acc_CTopicCode 
						when 3 then Customers_3.acc_CTopicCode 
						else 0 end 
				when 7 then Customers_3.acc_CTopicCode	
				when 8 then SellsEmporiums.CTopicCode	    
			else 0 
			end
		ELSE FM.CTopicCode -- case ACC_KIND 
		END  as CTopicCode ,-- case ACC_KIND 
		case FM.ACC_KIND 
		when 'Debit' then -- case ACC_KIND 
			case  FormTypes.DefaultCTopic2_Bed 
			when 1 then case FormTypes.CustCodeUse4Bed ---- اطلاعات گروه مشتري ----
					when 1 then CustomersGroup_1.acc_CTopicCode2 
					when 2 then CustomersGroup_2.acc_CTopicCode2 
					when 3 then CustomersGroup_3.acc_CTopicCode2 
					else 0 end 
			when 2 then LookUps_1.acc_CTopicCode2 ---- موضوع دريافت و پرداخت 1------
			when 3 then LookUps_2.acc_CTopicCode2 ---- موضوع دريافت و پرداخت 2------
			when 4  then Forms.CTopicCode2  ---کد حساب در فرم ----

			when 6 then case FormTypes.CustCodeUse4Bed ---- اطلاعات مشتري ----
					when 1 then Customers_1.acc_CTopicCode2 
					when 2 then Customers_2.acc_CTopicCode2 
					when 3 then Customers_3.acc_CTopicCode2
					else 0 end 
			when 7 then Customers_3.acc_CTopicCode2 
		else 0 end
		when 'Credit' then -- case ACC_KIND 
			case  FormTypes.DefaultCTopic2_Bes 
				when 1 then case FormTypes.CustCodeUse4Bes ---- اطلاعات گروه مشتري ----
						when 1 then CustomersGroup_1.acc_CTopicCode2 
						when 2 then CustomersGroup_2.acc_CTopicCode2 
						when 3 then CustomersGroup_3.acc_CTopicCode2 
						else 0 end 
				when 2 then LookUps_1.acc_CTopicCode2 ---- موضوع دريافت و پرداخت 1------
				when 3 then LookUps_2.acc_CTopicCode2 ---- موضوع دريافت و پرداخت 2------
				when 4  then Forms.CTopicCode2  ---کد حساب در فرم ----

				when 6 then case FormTypes.CustCodeUse4Bes ---- اطلاعات مشتري ----
						when 1 then Customers_1.acc_CTopicCode2 
						when 2 then Customers_2.acc_CTopicCode2 
						when 3 then Customers_3.acc_CTopicCode2 
						else 0 end 
				when 7 then Customers_3.acc_CTopicCode2		    
			else 0 
			end
		ELSE FM.CTopicCode2 -- case ACC_KIND 
		END  as CTopicCode2 ,-- case ACC_KIND 
		case FM.ACC_KIND 
		when 'Debit' then -- case ACC_KIND 
			 case  FormTypes.DefaultCTopic3_Bed 
				when 1 then case FormTypes.CustCodeUse4Bed ---- اطلاعات گروه مشتري ----
						when 1 then CustomersGroup_1.acc_CTopicCode3
						when 2 then CustomersGroup_2.acc_CTopicCode3 
						when 3 then CustomersGroup_3.acc_CTopicCode3 
						else 0 end 
				when 2 then LookUps_1.acc_CTopicCode3 ---- موضوع دريافت و پرداخت 1------
				when 3 then LookUps_2.acc_CTopicCode3 ---- موضوع دريافت و پرداخت 2------
				when 4  then Forms.CTopicCode3  ---کد حساب در فرم ----
				when 6 then case FormTypes.CustCodeUse4Bed ---- اطلاعات مشتري ----
						when 1 then Customers_1.acc_CTopicCode3
						when 2 then Customers_2.acc_CTopicCode3 
						when 3 then Customers_3.acc_CTopicCode3

						else 0 end 
				when 7 then Customers_3.acc_CTopicCode3	
			else 0 
			end
		when 'Credit' then -- case ACC_KIND 
			case  FormTypes.DefaultCTopic3_Bes 
			when 1 then case FormTypes.CustCodeUse4Bes ---- اطلاعات گروه مشتري ----
					when 1 then CustomersGroup_1.acc_CTopicCode3 
					when 2 then CustomersGroup_2.acc_CTopicCode3 
					when 3 then CustomersGroup_3.acc_CTopicCode3 
					else 0 end 
			when 2 then LookUps_1.acc_CTopicCode3 ---- موضوع دريافت و پرداخت 1------
			when 3 then LookUps_2.acc_CTopicCode3 ---- موضوع دريافت و پرداخت 2------
			when 4  then Forms.CTopicCode3  ---کد حساب در فرم ----

			when 6 then case FormTypes.CustCodeUse4Bes ---- اطلاعات مشتري ----
					when 1 then Customers_1.acc_CTopicCode3 
					when 2 then Customers_2.acc_CTopicCode3 
					when 3 then Customers_3.acc_CTopicCode3 
					else 0 end 
			when 7 then Customers_3.acc_CTopicCode3		    
			else 0 
			end
		ELSE FM.CTopicCode3 -- case ACC_KIND 
		END  as CTopicCode3 ,-- case ACC_KIND 
		CASE FM.ACC_KIND 
			when 'Debit' then -- case ACC_KIND 
				case when DefaultCurrencyType_Bed in (2,3)
					then round(ArzAmountExchange * ArzRateExchange,0)
				else Forms.Amount
				End 
			when 'CurrencyExchange' then -- case ACC_KIND 
				case when round(ArzAmountExchange * ArzRateExchange,0) -forms.Amount >0 
					then round(ArzAmountExchange * ArzRateExchange,0) -forms.Amount 
					else 0
				end 
		ELSE 0 -- case ACC_KIND 
		END AS debt ,-- case ACC_KIND 
		CASE ACC_KIND 
			when 'Credit' then -- case ACC_KIND 
				case when DefaultCurrencyType_Bes in (2,3)
					then round(ArzAmountExchange * ArzRateExchange,0)
				else Forms.Amount
				End 
			when 'CurrencyExchange' then -- case ACC_KIND 
				case 
					when forms.Amount - round(ArzAmountExchange * ArzRateExchange ,0) >0 
					then forms.Amount - round(ArzAmountExchange * ArzRateExchange ,0)
				else 0
				end 
		ELSE 0 -- case ACC_KIND 
		END AS credit ,-- case ACC_KIND 
		CASE ACC_KIND 
			when 'Debit' then -- case ACC_KIND 
				0
			when 'Credit' then -- case ACC_KIND 
				1 
		ELSE 0 -- case ACC_KIND 
		END AS bedbes ,-- case ACC_KIND 
		Forms.ServerID,
		Forms.YearID ,
		Customers_1.CustName AS CustName1 , 
		Customers_2.CustName AS CustName2,
		isnull(Forms.ArzAmount,0) as ArzAmount,
		PO,
		CASE 
			when ACC_KIND = 'Debit' then 
				case 
					when DefaultCurrencyType_Bed in (2,3) then Forms.ArzTypeIDExchange
					else isnull(forms.ArzTypeID,0)
				end 
			WHEN ACC_KIND = 'Credit' then 
				case 
					when DefaultCurrencyType_BeS in (2,3) then Forms.ArzTypeIDExchange
					else isnull(forms.ArzTypeID,0)
				end 
			ELSE 0 
		END ArzTypeID,
		forms.BudgetCode,
		forms.ProjectID,
		CASE ACC_KIND 
			when 'Debit' then -- case ACC_KIND 
				case DefaultCurrencyType_Bed 
					WHEN 0 then isnull(Forms.ArzAmount,0)
					when 2 then isnull(Forms.ArzAmountExchange,0)
				else isnull(Forms.ArzAmount,0)
				END 
			when 'Credit' then -- case ACC_KIND 
				0
			when 'CurrencyExchange' then -- case ACC_KIND 
				case when round(ArzAmountExchange * ArzRateExchange,0) -forms.Amount >0 
					then round(ArzAmountExchange * ArzRateExchange,0) -forms.Amount 
					else 0
				end
			
		ELSE  0  -- case ACC_KIND 
		END AS Currencydebit, 
		CASE ACC_KIND 
			when 'Debit' then -- case ACC_KIND 
				0
			when 'Credit' then -- case ACC_KIND 
				case DefaultCurrencyType_BeS 
					WHEN 0 then isnull(Forms.ArzAmount,0)
					when 2 then isnull(Forms.ArzAmountExchange,0)
				else isnull(Forms.ArzAmount,0)
				END 
			when 'CurrencyExchange' then -- case ACC_KIND 
				case 
					when forms.Amount - round(ArzAmountExchange * ArzRateExchange ,0) >0 
					then forms.Amount - round(ArzAmountExchange * ArzRateExchange ,0)
				else 0
				end
		ELSE 0 -- case ACC_KIND 
		END AS Currencycredit, 
		CASE ACC_KIND 
			when 'Debit' then -- case ACC_KIND 
				case DefaultCurrencyType_Bed 
					WHEN 0 then isnull(Forms.ArzRate,1)
					when 2 then isnull(Forms.ArzRateExchange,1)
				else 1
				END 
			when 'Credit' then -- case ACC_KIND 
				case DefaultCurrencyType_BeS 
					WHEN 0 then isnull(forms.ArzRate,1)
					when 2 then isnull(Forms.ArzRateExchange,1)
				else 1
				END  
		ELSE 1 -- case ACC_KIND 
		END CurrencyRate
FROM	Forms 
		INNER JOIN FormTypes ON Forms.FormType = FormTypes.FormType 
		LEFT JOIN Customers Customers_1 ON Forms.CustomerID1= Customers_1.CustID 
		LEFT JOIN CustomersGroup CustomersGroup_1 ON CustomersGroup_1.CustomerGrpID = Customers_1.CustomerGrpID 
		LEFT JOIN Customers Customers_3  ON Customers_3.CustID = Forms.CustomerID3 
		LEFT JOIN CustomersGroup CustomersGroup_3 ON Customers_3.CustomerGrpID = CustomersGroup_3.CustomerGrpID
		LEFT JOIN Customers Customers_2 ON Forms.CustomerID2 = Customers_2.CustID  
        LEFT JOIN CustomersGroup CustomersGroup_2 ON CustomersGroup_2.CustomerGrpID = Customers_2.CustomerGrpID
		LEFT JOIN LookUps LookUps_1 ON Forms.PayTypes = LookUps_1.LookUpID
        LEFT JOIN LookUps LookUps_2 ON Forms.TopicTypes = LookUps_2.LookUpID 
		LEFT JOIN SellsEmporiums on forms.SellsEmporium=SellsEmporiums.SellsEmporium and Forms.ServerID =SellsEmporiums.ServerID
		INNER JOIN vu_FormTypes_MakeDoc FM on FormTypes.FormType  = fm.FormType 
		LEFT OUTER JOIN dbo.VU_BudgetTopics BT on	Forms.BudgetCode	 = bt.[BudgetTopicID]

WHERE	(FormTypes.DisplayFormType in(0,7))	 
		AND ((Forms.DocNo =0)OR(@AllDocAble=1)) 
		-- AND (FormTypes.FormType = @FormType) 
		AND (Forms.FormNumber BETWEEN @FormNoFrom AND @FormNoTo ) 
		AND (Forms.FormDate BETWEEN @FormDateFrom  AND @FormDateTo ) 
		AND (
				case when @DateSelect = 0 and  (ISNULL(Forms.AidInfoDate, '') = '') OR (Forms.AidInfoDate = '/  /') 
				then 1 
				else 0 
				end = 1
	       OR (Forms.AidInfoDate BETWEEN @AidDateFrom AND @AidDateTo)
			)
		AND (Forms.FormState < 10) 
		AND Forms.CustomerID1 between @CustNoFrom and @CustNoTo
		AND (Forms.SellsEmporium BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)
		AND (Forms.PayTypes BETWEEN @PayTypesFrom AND @PayTypesTo)
		AND ((case when FormTypes.FormStateDefault4Doc = 0 then Forms.FormState else FormTypes.FormStateDefault4Doc end) = Forms.FormState)
RETURN
end


