CREATE FUNCTION GetAmountDelay( @DayDelay INT, @ItemAmount MONEY)
RETURNS MONEY
AS
BEGIN
DECLARE @Price MONEY

SET @Price= CASE WHEN @DayDelay > 1 THEN round(@ItemAmount * 0.24 * @DayDelay / 365, 0) ELSE 0 END

RETURN (@Price)

END
