CREATE  FUNCTION Fn_RecallReciptsEntity (  @ReciptType int, @YearIDFrom int, @YearIDTo int, @PersonID1From int, @PersonID1To int
, @ReciptDateFrom char(10), @ReciptDateTo char(10), @ReciptNumberFrom int, @ReciptNumberTo int, @LookUpsCodeFrom int, @LookUpsCodeTo int 
)
RETURNS TABLE 
AS
RETURN 
(
 SELECT  Recall_price.ServerID,Recall_price.ReciptID AS Recall_ReciptID,Recall_price.ReciptDate,Recall_price.ReciptNumber,
ReciptItems.YearID, ReciptItems.StuffCode, StuffCoding.c_StuffName, Units.UnitName,
 Recall_price.PersonID1 AS MasterPersonID1 ,Customers_1.CustName as MasterCustName1,
    ReciptItems.PersonID1 as PersonID1, Customers.CustName, Recall_price.PersonID2 , Customers_2.CustName as CustName_2,
    ROUND(ReciptItems.InputEntity + ReciptItems.OutputEntity - ISNULL(Aid_RecallSpecial.Entity, 0), 3) AS Entity,
    ROUND(ReciptItems.InputWeight + ReciptItems.OutputWeight - ISNULL(Aid_RecallSpecial.Weight, 0), 3) AS Weight,
     Recall_price.UnitSellPrice ,
      ROUND (Recall_price.UnitPrice_C * ROUND(ReciptItems.InputEntity + ReciptItems.OutputEntity - ISNULL(Aid_RecallSpecial.Entity, 0), 3) ,0) as TotalPrice  , 
    Recall_price.WaterCo,
     ROUND (ISNULL(Recall_price.UniteDeficitValue,0) * ROUND(ISNULL(ReciptItems.InputEntity,0) + ISNULL(ReciptItems.OutputEntity,0) - ISNULL(Aid_RecallSpecial.Entity, 0), 3) ,0) as DeficitValue , 
    Recall_price.TaxCo, 
     ROUND (ISNULL(Recall_price.UniteTaxValue,0) * ROUND(ISNULL(ReciptItems.InputEntity,0) + ISNULL(ReciptItems.OutputEntity,0) - ISNULL(Aid_RecallSpecial.Entity, 0), 3) ,0) as TaxValue , 
    Recall_price.ReciptCaption + '  : ' + LTRIM(str(Recall_price.ReciptNumber))  + ' تاریخ : ' +Recall_price.ReciptDate + ' ' +
    ReciptTypes.ReciptCaption + '  : ' + LTRIM(str(Recipts.ReciptNumber))  + ' تاریخ : ' +Recipts.ReciptDate +' '+ISNULL(ReciptItems.ItemNote,'')  as ItemNote,
         ROUND (ISNULL(Recall_price.UnitPrice_C,0) * ROUND(ISNULL(ReciptItems.InputEntity,0) + ISNULL(ReciptItems.OutputEntity,0) - ISNULL(Aid_RecallSpecial.Entity, 0), 3) ,0)-
         ROUND (ISNULL(Recall_price.UniteDeficitValue,0) * ROUND(ISNULL(ReciptItems.InputEntity,0) + ISNULL(ReciptItems.OutputEntity,0) - ISNULL(Aid_RecallSpecial.Entity, 0), 3) ,0)+
         ROUND (ISNULL(Recall_price.UniteTaxValue,0) * ROUND(ISNULL(ReciptItems.InputEntity,0) + ISNULL(ReciptItems.OutputEntity,0) - ISNULL(Aid_RecallSpecial.Entity, 0), 3) ,0) 
     +isnull(round(ROUND(ReciptItems.InputEntity + ReciptItems.OutputEntity - ISNULL(Aid_RecallSpecial.Entity, 0), 3)
      * isnull(Recall_price.Portage,0) ,0),0)
     
     
     AS TotallSellPrice ,
     Recall_price.UnitCommission,
    ReciptItems.PersonID1 as ItemPersonID1,ReciptItems.ReciptItemID as NewReciptItemID  ,
    Recipts.ReciptNumber as AidNumber , Recipts.ReciptDate as AidDate , ReciptTypes.ReciptCaption ,Recall_price.SecondType, Recall_price.PersonID2Bed, Fitful.FitfulID as Flag
      ,LookUps_SecondType.Name AS SecondTypeName,ReciptItems.preReciptItemID
    ,isnull(round(ROUND(ReciptItems.InputEntity + ReciptItems.OutputEntity - ISNULL(Aid_RecallSpecial.Entity, 0), 3)
     * Recall_price.Portage ,0),0) as portage ,Recall_price.SellsEmporium, Recipts.PersonID3,StuffCoding.GroupID, Recipts.PersonID4, Recipts.PersonID5, Recipts.PO, Recipts.StoreID
FROM  ReciptItems INNER JOIN
    Recipts ON  ReciptItems.ReciptID = Recipts.ReciptID 
          AND ReciptItems.ServerID = Recipts.ServerID 
          AND ReciptItems.YearID = Recipts.YearID INNER JOIN
    ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType  LEFT OUTER JOIN
    (
      SELECT  ReciptItems.serverid  ,ReciptItems.PrvYearID , ReciptItems.preReciptItemID,  
        SUM(ReciptItems.InputEntity + ReciptItems.OutputEntity) AS Entity, 
        SUM(ReciptItems.InputWeight + ReciptItems.OutputWeight) AS Weight, 
        COUNT(*) as  CountNo
      FROM  ReciptItems INNER JOIN
          Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND 
          ReciptItems.ServerID = Recipts.ServerID AND 
          ReciptItems.YearID = Recipts.YearID   INNER JOIN
          ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
      WHERE (Recipts.ReciptState < 3) 
          AND (Recipts.ReciptType = @ReciptType )
          AND (Recipts.yearid BETWEEN @YearIDFrom  and @YearIDTo )
          AND ReciptItems.preReciptItemID is not null
      GROUP BY  ReciptItems.serverid , ReciptItems.PrvYearID , ReciptItems.preReciptItemID 
    ) AS Aid_RecallSpecial ON
          ReciptItems.ReciptItemID = Aid_RecallSpecial.preReciptItemID 
          AND ReciptItems.YearID = Aid_RecallSpecial.PrvYearid   
          AND ReciptItems.ServerID = Aid_RecallSpecial.ServerID   LEFT OUTER JOIN
    (
      SELECT  ReciptItems.serverid  ,ReciptItems.YearID , ReciptItems.ReciptItemID,  
          (ReciptItems.TotalInputPrice + ReciptItems.TotalOutputPrice) /
          (ReciptItems.InputEntity + ReciptItems.OutputEntity) AS UnitPrice_C ,
          ReciptItems.UnitSellPrice ,
          ReciptItems.WaterCo, ReciptItems.DeficitValue / (ReciptItems.InputEntity + ReciptItems.OutputEntity) as UniteDeficitValue , 
          ReciptItems.TaxCo,ReciptItems.TaxValue / (ReciptItems.InputEntity + ReciptItems.OutputEntity) as UniteTaxValue ,
          ReciptItems.UnitCommission,
          Recipts.ReciptNumber , Recipts.ReciptDate , ReciptTypes.ReciptCaption, Recipts.SecondType, Recipts.PersonID2Bed
          , Recipts.PersonID2, Recipts.PersonID1, Recipts.ReciptID
      ,(ReciptItems.Portage) /
          (ReciptItems.InputEntity + ReciptItems.OutputEntity) as Portage,Recipts.SellsEmporium
      FROM  ReciptItems INNER JOIN
          Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND 
          ReciptItems.ServerID = Recipts.ServerID AND 
          ReciptItems.YearID = Recipts.YearID   INNER JOIN
          ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
      WHERE (Recipts.ReciptState < 3) 
          AND (Recipts.yearid BETWEEN @YearIDFrom and @YearIDTo )
          AND ((ReciptItems.InputEntity + ReciptItems.OutputEntity)<>0)
      ) AS Recall_price ON
          ReciptItems.preReciptItemID = Recall_price.ReciptItemID 
          AND ReciptItems.Yearid/*PrvYearid*/ = Recall_price.Yearid
          AND ReciptItems.ServerID = Recall_price.ServerID  LEFT OUTER JOIN
      StuffCoding ON StuffCoding.c_StuffCode = ReciptItems.StuffCode LEFT OUTER JOIN
                                                Units ON Units.UnitCode = StuffCoding.n_UnitCode LEFT OUTER JOIN 
      Customers ON  Customers.CustID = ReciptItems.PersonID1 LEFT OUTER JOIN
      Customers as Customers_2 ON  Customers_2.CustID = Recall_price.PersonID2   LEFT OUTER JOIN
      Customers as Customers_1 ON  Customers_1.CustID = Recall_price.PersonID1   LEFT OUTER JOIN
      LookUps as LookUps_SecondType ON  LookUps_SecondType.LookUpID = Recall_price.SecondType
      CROSS JOIN Fitful

WHERE (Recipts.ReciptState <2 )
    AND (Recipts.YearID BETWEEN @YearIDFrom AND @YearIDTo)
    AND (Recipts.ReciptType in
     (select part from  dbo.SplitString((select RecallReciptTypes from ReciptTypes1
        where recipttype =@ReciptType) ,',')))
    AND (Recall_price.PersonID1 BETWEEN @PersonID1From AND @PersonID1To)
    AND (Recipts.ReciptDate BETWEEN @ReciptDateFrom and @ReciptDateTo)
    AND (Recipts.ReciptNumber BETWEEN @ReciptNumberFrom and @ReciptNumberTo)
    AND (Aid_RecallSpecial.preReciptItemID is null )
    AND (LookUps_SecondType.Code BETWEEN @LookUpsCodeFrom AND @LookUpsCodeTo)
--Order By  Recall_price.ReciptID , Recipts.ReciptDate, ReciptItems.PersonID1,  Recall_price.PersonID2,ReciptItems.preReciptItemID

)

