CREATE  FUNCTION Fn_RecallReciptsWeight (  @ReciptType int, @YearIDFrom int, @YearIDTo int, @PersonID1From int, @PersonID1To int
, @ReciptDateFrom char(10), @ReciptDateTo char(10), @ReciptNumberFrom int, @ReciptNumberTo int, @LookUpsCodeFrom int, @LookUpsCodeTo int 
)
RETURNS TABLE 
AS
RETURN 
(

SELECT  RP.ServerID, RP.ReciptID AS Recall_ReciptID, RP.ReciptDate, RP.ReciptNumber, RI.YearID, 
		RI.StuffCode, S.c_StuffName, U.UnitName, 
		RP.PersonID1 AS MasterPersonID1, isnull(CR1.CustFirstName,'') +' '+ CR1.CustName AS MasterCustName1, 
		RI.PersonID1, isnull(CT1.CustFirstName,'') +' '+ CT1.CustName  CustName , 
		RP.PersonID2, isnull(CR2.CustFirstName,'') +' '+ CR2.CustName  CustName_2, 
		ROUND(RI.InputEntity + RI.OutputEntity - ISNULL(ARS.Entity, 0), 3) AS Entity, 
        ROUND(RI.InputWeight + RI.OutputWeight - ISNULL(ARS.Weight, 0), 3) AS Weight, RP.UnitSellPrice, 
		                 ROUND(RP.UnitPrice_C * ROUND(ISNULL(RI.InputWeight, 0) + ISNULL(RI.OutputWeight, 0) - ISNULL(ARS.Weight, 0), 3), 0) AS TotalPrice, RP.WaterCo, 
		ROUND(ISNULL(RP.UniteDeficitValue, 0) * ROUND(ISNULL(RI.InputWeight, 0) + ISNULL(RI.OutputWeight, 0) - ISNULL(ARS.Weight, 0), 3), 0) AS DeficitValue, RP.TaxCo, 
        ROUND(ISNULL(RP.UniteTaxValue, 0)     * ROUND(ISNULL(RI.InputWeight, 0) + ISNULL(RI.OutputWeight, 0) - ISNULL(ARS.Weight, 0), 3), 0) AS TaxValue, 
		RP.ReciptCaption + '  : ' + LTRIM(STR(RP.ReciptNumber)) 
        + ' تاریخ : ' + RP.ReciptDate + ' ' + RT.ReciptCaption + '  : ' + LTRIM(STR(R.ReciptNumber)) + ' تاریخ : ' + R.ReciptDate 
		+ ' ' + isnull(RP.ItemNote,'')  AS ItemNote, 
	      ROUND(ISNULL(RP.UnitPrice_C, 0)       * ROUND(ISNULL(RI.InputWeight, 0) + ISNULL(RI.OutputWeight, 0) - ISNULL(ARS.Weight, 0), 3), 0)
		- ROUND(ISNULL(RP.UniteDeficitValue, 0) * ROUND(ISNULL(RI.InputWeight, 0) + ISNULL(RI.OutputWeight, 0) - ISNULL(ARS.Weight, 0), 3), 0) 
        + ROUND(ISNULL(RP.UniteTaxValue, 0)     * ROUND(ISNULL(RI.InputWeight, 0) + ISNULL(RI.OutputWeight, 0) - ISNULL(ARS.Weight, 0), 3), 0) AS TotallSellPrice, 
		RP.UnitCommission, RI.PersonID1 AS ItemPersonID1, RI.ReciptItemID AS NewReciptItemID, R.ReciptNumber AS AidNumber, R.ReciptDate AS AidDate, RT.ReciptCaption, 
		RP.SecondType, RP.PersonID2Bed, Fitful.FitfulID AS Flag, LookUps_SecondType.Name AS SecondTypeName, RI.preReciptItemID, RI.InputEntity * 0 AS portage, 
		RP.SellsEmporium, T.PersonID2 AS PersonID3,S.GroupID, T.PersonID4, T.PersonID5, T.PO, R.StoreID

FROM			ReciptItems		AS RI 
	INNER JOIN  Recipts			AS R  ON RI.ReciptID = R.ReciptID AND RI.ServerID = R.ServerID AND RI.YearID = R.YearID 
	INNER JOIN  ReciptTypes		AS RT ON R.ReciptType = RT.ReciptType 
	LEFT  JOIN  (
			SELECT		RI.ServerID, RI.PrvYearID, RI.preReciptItemID, 
						SUM(RI.InputEntity + RI.OutputEntity) AS Entity, SUM(RI.InputWeight + RI.OutputWeight) AS Weight, 
						COUNT(*) AS CountNo

            FROM			ReciptItems AS RI 
				INNER JOIN  Recipts AS R ON RI.ReciptID = R.ReciptID AND RI.ServerID = R.ServerID AND RI.YearID = R.YearID 
				INNER JOIN  ReciptTypes AS RT ON R.ReciptType = RT.ReciptType

            WHERE	(R.ReciptState < 3)				AND (R.YearID BETWEEN @YearIDFrom-2 AND @YearIDTo) 
				AND (R.ReciptType = @ReciptType)    AND (RI.preReciptItemID IS NOT NULL)

            GROUP BY RI.ServerID, RI.PrvYearID, RI.preReciptItemID

			     ) AS ARS ON RI.ReciptItemID = ARS.preReciptItemID AND RI.YearID = ARS.PrvYearID AND RI.ServerID = ARS.ServerID 

    LEFT  JOIN	(
			SELECT		RI.ServerID, RI.YearID, RI.ReciptItemID, 
						(RI.TotalInputPrice + RI.TotalOutputPrice) / (RI.InputWeight + RI.OutputWeight) AS UnitPrice_C, RI.UnitSellPrice, RI.WaterCo, 
                         RI.DeficitValue / (RI.InputWeight + RI.OutputWeight) AS UniteDeficitValue, RI.TaxCo, 
						 RI.TaxValue     / (RI.InputWeight + RI.OutputWeight) AS UniteTaxValue, RI.UnitCommission, R.ReciptNumber, R.ReciptDate, 
                         RT.ReciptCaption, R.SecondType, R.PersonID2Bed, R.PersonID2, R.PersonID1, R.ReciptID, R.SellsEmporium,
						 RI.ItemNote,R.ReciptNote

			FROM			ReciptItems AS RI 
				INNER JOIN	Recipts     AS R  ON RI.ReciptID = R.ReciptID AND RI.ServerID = R.ServerID AND RI.YearID = R.YearID 
				INNER JOIN  ReciptTypes AS RT ON R.ReciptType = RT.ReciptType

			WHERE	(R.ReciptState < 3) 
				AND (R.YearID BETWEEN @YearIDFrom-2 AND @YearIDTo) 
				AND (RI.InputWeight + RI.OutputWeight <> 0)

				) AS RP ON RI.preReciptItemID = RP.ReciptItemID AND RI.PrvYearID = RP.YearID AND RI.ServerID = RP.ServerID 

    INNER JOIN	StuffCoding      AS S   ON S.c_StuffCode = RI.StuffCode 
	INNER JOIN  Units            AS U   ON U.UnitCode = S.n_UnitCode 
	INNER JOIN  Customers        AS CT1 ON CT1.CustID = RI.PersonID1 
	LEFT  JOIN  Customers        AS CR2 ON CR2.CustID = RP.PersonID2 
	LEFT  JOIN  Customers        AS CR1 ON CR1.CustID = RP.PersonID1 
	INNER JOIN  Tozin            AS T   ON T.TozinID = R.TozinID 
	LEFT  JOIN  LookUps          AS LookUps_SecondType ON LookUps_SecondType.LookUpID = RP.SecondType 
	CROSS JOIN  Fitful

WHERE	(R.ReciptState < 2) 
	AND (R.YearID BETWEEN @YearIDFrom AND @YearIDTo) 
	AND (R.ReciptType IN (SELECT part FROM SplitString ((SELECT RecallReciptTypes  FROM ReciptTypes1 WHERE (ReciptType = @ReciptType)), ',') AS SplitString_1)) 
	AND (RP.PersonID1 BETWEEN @PersonID1From  AND @PersonID1To) 
	AND (R.ReciptDate BETWEEN @ReciptDateFrom AND @ReciptDateTo) 
	AND (R.ReciptNumber BETWEEN @ReciptNumberFrom AND @ReciptNumberTo) 
	AND (ARS.preReciptItemID IS NULL) 
	AND (LookUps_SecondType.Code BETWEEN @LookUpsCodeFrom AND @LookUpsCodeTo)
)

GO 
