CREATE  FUNCTION Fn_ReciptPostOnCustomer2( @PersonID1 int , @ReciptDateFrom char(10), @ReciptDateTo char(10) ,@RelatedRecipts varchar(300))
RETURNS TABLE 
AS
RETURN 
(
--SELECT  TozinNumber  as شماره‏بارنامه,TozinDate as  تاریخ , c_StuffName as نام‏کالا ,NumberOfBags as مقدارارسالی ,UseUnitName as نوع‏پمپ
--,tozin.SecondType  as روش‏تخلیه,tozin.masir as مقصد
SELECT  TozinNumber ,TozinDate  , c_StuffName  ,NumberOfBags  ,UseUnitName ,tozin.SecondType  ,tozin.masir 
FROM	Recipts INNER JOIN
		ReciptItems on ReciptItems.ReciptID = Recipts.ReciptID and ReciptItems.YearID = Recipts.YearID  AND 
		ReciptItems.ServerID = Recipts.ServerID  INNER JOIN 
		Customers ON Recipts.PersonID1 = Customers.CustID INNER JOIN
		
		(
			SELECT RelatedRecipts ,TozinNumber,TozinDate,c_StuffName,NumberOfBags,UseUnits.UseUnitName+'>'+c1.CustName+'>'+c2.CustName+'>'+c3.CustName+'>'+c4.CustName as UseUnitName 
			,LookUps.Name as SecondType,CustomersMasir.MasirNote as masir
			FROM tozin 
			INNER JOIN UseUnits on tozin.UseUnitID=UseUnits.UseUnitID
			INNER JOIN  Customers c1 on c1.CustID=UseUnits.CustID1
			INNER JOIN  Customers c2 on c2.CustID=UseUnits.CustID2
			INNER JOIN  Customers c3 on c3.CustID=UseUnits.CustID3
			INNER JOIN  Customers c4 on c4.CustID=UseUnits.CustID4
			INNER JOIN LookUps on LookUps.LookUpID=tozin.SecondType
			INNER JOIN CustomersMasir on tozin.MasirID=CustomersMasir.ID
			INNER JOIN StuffCoding on tozin.StuffCode=StuffCoding.c_StuffCode
			
			WHERE RelatedRecipts IS NOT  NULL AND (ReciptType = 26 ) and (tozin.TozinState <> 3) And (tozin.MachineFullWeight >0)

			--group by  RelatedRecipts	
		) tozin on LTRIM(Recipts.ServerID) + '-' + LTRIM(Recipts.YearID) + '-' + LTRIM(ReciptItems.ReciptItemID) = RelatedRecipts   

			WHERE	(Recipts.ReciptState < 3) and Recipts.ReciptType=25
		
        AND (Recipts.PersonID1 = @PersonID1 )
		AND (Recipts.AidDate BETWEEN @ReciptDateFrom and @ReciptDateTo )
        AND (tozin.RelatedRecipts = @RelatedRecipts )

		
)
