CREATE   FUNCTION Fn_RecallReciptsEW (  @ReciptType int, @YearIDFrom int, @YearIDTo int, @PersonID1From int, @PersonID1To int
, @ReciptDateFrom char(10), @ReciptDateTo char(10), @ReciptNumberFrom int, @ReciptNumberTo int, @LookUpsCodeFrom int, @LookUpsCodeTo int 
)
    RETURNS @retFindReports TABLE 
  (
ServerID int, Recall_ReciptID int , ReciptDate char(10)   COLLATE DATABASE_DEFAULT NULL, ReciptNumber int ,
 YearID  int , StuffCode bigint ,    c_StuffName char(300)   COLLATE DATABASE_DEFAULT NULL, UnitName char(300)   COLLATE DATABASE_DEFAULT NULL,
 MasterPersonID1 int , MasterCustName1 char(300)   COLLATE DATABASE_DEFAULT NULL, PersonID1  int , CustName  char(300)   COLLATE DATABASE_DEFAULT NULL,  
 PersonID2 int , CustName_2  char(300)   COLLATE DATABASE_DEFAULT NULL,   Entity float  ,  Weight float ,  OutputEntity float,OutputWeight float,
 UnitSellPrice money ,  TotalPrice money ,  WaterCo float ,  DeficitValue money ,  TaxCo float ,  TaxValue money ,  
 ItemNote char(1000)   COLLATE DATABASE_DEFAULT NULL, 
 TotallSellPrice money, UnitCommission float ,  ItemPersonID1 int ,  NewReciptItemID int ,  AidNumber varchar(40) ,  AidDate char(10)   COLLATE DATABASE_DEFAULT NULL,
 ReciptCaption char(300)   COLLATE DATABASE_DEFAULT NULL,    SecondTypeItem int ,  PersonID2Bed int ,  Flag decimal(18,2) ,  SecondTypeName  char(300),
  preReciptItemID int ,SecondType int, RollbackEntity float,portage float, SellsEmporium int, PersonID3  int, RDeficitValue money ,GroupID int
  , PersonID4 int , PersonID5 int, PO varchar(300), StoreID smallint
  )
  AS begin 
----===============================================================================================================
--exec sp_executesql N'SELECT * From
--dbo.Fn_RecallReciptsEW ( @P1 , @P2 , @P3 , @P4 , @P5, @P6 , @P7 , @P8 , @P9 , @P10 , @P11)
--where (AidDate BetWeen @P12 AND @P13 ) 
--Order By Recall_ReciptID , AidDate, PersonID1, PersonID2, preReciptItemID
--',N'@P1 int,@P2 int,@P3 int,@P4 bigint,@P5 bigint,@P6 nvarchar(8),@P7 nvarchar(8),@P8 bigint,@P9 bigint,@P10 bigint,@P11 bigint,@P12 nvarchar(8),@P13 nvarchar(8)',12,98,98,204753,204753,N'98/05/13',N'98/05/13',1,11197,0,0,N'00/00/00',N'99/12/30'

----===============================================================================================================
  
INSERT INTO  @retFindReports
 SELECT DISTINCT R25.ServerID, R25.ReciptID AS Recall_ReciptID,R25.ReciptDate,R25.ReciptNumber,
		RI25.YearID, RI25.StuffCode, sc.c_StuffName AS c_StuffName , OU.UnitName,
		R25.PersonID1 AS MasterPersonID1 ,isnull(CT1.CustFirstName,' ') +' '+ CT1.CustName  AS MasterCustName1,
		R25.PersonID1 AS PersonID1       ,isnull(CT1.CustFirstName,' ') +' '+ CT1.CustName  AS CustName,
		R25.PersonID2 AS PersonID2       ,isnull(CT2.CustFirstName,' ') +' '+ CT2.CustName  AS CustName_2,
		ar2.r15Entity AS Entity, ar2.r15Weight AS Weight, OutputEntity, OutputWeight,
		RI25.UnitSellPrice , ROUND (ROUND(ar2.r15Entity,2) *  RI25.UnitSellPrice,0)                      AS TotalPrice  , 
		RI25.WaterCo,        ROUND (ROUND(ar2.r15Entity,2) * (RI25.DeficitValue / RI25.OutputEntity) ,0) AS DeficitValue , 
		RI25.TaxCo,          ROUND (ROUND(ar2.r15Entity,2) * (RI25.TaxValue     / RI25.OutputEntity) ,0) AS TaxValue , 
		case 
		    when DeficitValue <> 0 then rtrim(ltrim ('تخفیف پمپ بلند')) 
			else '' 
		end +	
		' - ' + sc.c_StuffName       +
		' متراژ: ' + cast (ar2.r15Entity AS nvarchar) +
		' - ' + UseUnits.UseUnitName + ' م.ب : '  + rtrim(ltrim(cast(isnull(ar2.RollbackEntity,0) AS char(250)))) +
		' - ' + 'به‏آدرس:'+ left(CM.MasirNote,250) +
		Case when RI25.DeficitValue > 0 then ' - با تخفیف ' 
		     else ''   
	    end AS ItemNote,
        ROUND (ROUND(ar2.r15Entity,2) *  RI25.UnitSellPrice,0) -
        ROUND (ROUND(ar2.r15Entity,2) * (isnull(RI25.DeficitValue,0) / RI25.OutputEntity),0) + 
		ROUND (ROUND(ar2.r15Entity,2) * (isnull(RI25.TaxValue,0)     / RI25.OutputEntity),0) AS TotallSellPrice ,
		0.0 AS UnitCommission,	ar2.PersonID1 AS ItemPersonID1,RI25.ReciptItemID AS NewReciptItemID  ,
		R25.ReciptNumber AS AidNumber , R25.AidDate AS AidDate , rc.ReciptCaption ,RI25.SecondTypeItem,R25.PersonID2Bed, 0 AS Flag,
		'' AS SecondTypeName,RI25.preReciptItemID, 0 AS SecondType,(isnull(ar2.RollbackEntity,0)) AS RollbackEntity, 0 AS  portage,
		R25.SellsEmporium, 0 AS PersonID3  , isnull(RI25.DeficitValue,0) RDeficitValue,SC.GroupID, R25.PersonID4, R25.PersonID5, R25.PO, R25.StoreID

from       Recipts R25 
INNER JOIN ReciptItems RI25			on RI25.ReciptID = R25.ReciptID and RI25.YearID = R25.YearID  AND RI25.ServerID = R25.ServerID 
INNER JOIN FN_Recal_Weight  ar2		on ar2.ReciptID=R25.ReciptID and R25.YearID =ar2.YearID and ar2.ServerID=R25.ServerID
INNER JOIN StuffCodingLinked  l		on RI25.StuffCode=l.c_StuffCode
INNER JOIN StuffCoding  sc			on RI25.StuffCode=sc.c_StuffCode
INNER JOIN Units  ou				on sc.n_UnitCode =ou.UnitCode
INNER JOIN Customers  CT1			on CT1.CustID=R25.PersonID1
INNER JOIN Customers  CT2			on CT2.CustID=R25.PersonID2
INNER JOIN ReciptTypes1  rc			on R25.ReciptType=rc.ReciptType
INNER JOIN (
			SELECT		MAX(isnull(UseUnitID,0)) AS UseUnitID, ReciptID, ServerID, YearID
            FROM		ReciptItems
			GROUP BY ReciptID, ServerID, YearID
			) masirselect on	R25.ReciptID=masirselect.ReciptID and R25.YearID=masirselect.YearID and masirselect.ServerID=R25.ServerID
INNER JOIN UseUnits on masirselect.UseUnitID=UseUnits.UseUnitID
LEFT  JOIN CustomersMasir CM		on R25.MasirID=CM.ID

where R25.ParentReciptID is null and R25.ReciptType=25
 and (R25.PersonID1 between @PersonID1From and @PersonID1To)
 and (R25.ReciptDate between @ReciptDateFrom and @ReciptDateTo)

 order by R25.PersonID1,StuffCode desc

INSERT INTO  @retFindReports

	SELECT		ServerID, Recall_ReciptID, ReciptDate, ReciptNumber, YearID,
				case	when StuffCode=500 and Entity < 6.0 then 502
						when StuffCode=501 and Entity < 30	then 503 else 0 end  AS StuffCode , 
				c_StuffName, UnitName, MasterPersonID1, MasterCustName1, PersonID1, CustName, PersonID2, CustName_2,													  
				round (case when StuffCode=500  then 6.0 - Entity
							when StuffCode=501  then 30  - Entity else 0 end ,2) as	 Entity,
				round (case when Weight < OutputWeight then OutputWeight - Weight 
							else 0 end ,0) AS  Weight, 
				case when StuffCode=500  then 6.0 	when StuffCode=501 	then 30 else 0 end AS OutputEntity,
				OutputWeight, UnitSellPrice,
				ROUND (UnitSellPrice * abs(round(case when StuffCode=500  then 6.0 - Entity	
										    	   	  when StuffCode=501  then 30  - Entity 
													  else 0 end ,2) )
											     ,0)  AS  TotalPrice,
				WaterCo, 
				round(( RDeficitValue / OutputEntity) *  (round(case   when StuffCode=500  then 6.0 - Entity
																       when StuffCode=501  then 30  - Entity 
																else 0 end 
												   ,2))
					  ,0) DeficitValue
     			, TaxCo, 
				case when isnull(TaxCo,0) > 0 then 
				round((ROUND (UnitSellPrice * abs(round(case when StuffCode=500  then 6.0 - Entity	
										    	   	  when StuffCode=501  then 30  - Entity 
													  else 0 end ,2) )
											     ,0)
				- round(( RDeficitValue / OutputEntity) *  (round(case   when StuffCode=500  then 6.0 - Entity
																         when StuffCode=501  then 30  - Entity 
																         else 0 end 
												   ,2))
					  ,0)) * (TaxCo/100),0) else 0 end  TaxValue, 

				case when DeficitValue <> 0 then rtrim(ltrim ('تخفیف پمپ بلند' + ItemNote )) else 
				ItemNote end AS ItemNote
				,
				ROUND (UnitSellPrice  *  abs(round(case when StuffCode=500  then 6.0 - Entity	
													    when StuffCode=501  then 30  - Entity else 0 end 
												,2)) 
											,0)
				- round(( RDeficitValue / OutputEntity) *  (round(case   when StuffCode=500  then 6.0 - Entity
																         when StuffCode=501  then 30  - Entity 
																         else 0 end 
												   ,2))
					  ,0)
				+ round((ROUND (UnitSellPrice * abs(round(case when StuffCode=500  then 6.0 - Entity	
										    	   	  when StuffCode=501  then 30  - Entity 
													  else 0 end ,2) )
											     ,0)
				- round(( RDeficitValue / OutputEntity) *  (round(case   when StuffCode=500  then 6.0 - Entity
																         when StuffCode=501  then 30  - Entity 
																         else 0 end 
												   ,2))
					  ,0)) * (TaxCo/100),0) AS TotallSellPrice,
				UnitCommission, ItemPersonID1, NewReciptItemID, AidNumber, AidDate, ReciptCaption, 
                SecondTypeItem, PersonID2Bed, Flag, SecondTypeName, preReciptItemID,0 AS SecondType,RollbackEntity,
				0 AS  portage,SellsEmporium, 0 AS PersonID3 , 0 as  RDeficitValue,0 AS GroupID, PersonID4, PersonID5, PO, StoreID

	from @retFindReports
	where StuffCode in (500,501) and case	when StuffCode=500 and Entity < 6.0 then 1 
											when StuffCode=501 and Entity < 30	then 1 else 0 end =1




  
order by PersonID1,StuffCode desc  
  
       RETURN
END


GO 
SET QUOTED_IDENTIFIER OFF 
GO 
SET ANSI_NULLS ON 
GO 




CREATE FUNCTION [dbo].[Aid_MakeDocuments_Check] 
								(
									 @AllDocAble Tinyint=0
									,@FormDateFrom varchar(10)=[00/00/00]
									,@FormDateTo varchar(10)=[99/99/99]
									,@FormNoFrom varchar (12)=[-9999999]
									,@FormNoTo varchar (12)=[99999999] 
									--, @FormType varchar (3)= [50] 😳😳😳
                                    ,@CheckStateFrom varchar (12)=[0]
									,@CheckStateTo varchar (12)=[99]  
                                    ,@SellsEmporiumFrom int=0
									,@SellsEmporiumTo int = 999999999 
                                    ,@PayTypesFrom int=0
									,@PayTypesTo int = 999999999 
									,@MakeDocKind int =1
									,@AidDateFrom char(10)='0000/00/00'
									,@AidDateTo char(10)='9999/99/99'
								)

        RETURNS @retFindReports TABLE 
  (
	ID Bigint ,
	FormType tinyint ,
	FormCaption varchar(150)  COLLATE DATABASE_DEFAULT ,
	FormItemID int ,
	FormID int ,
	FormNumber int ,
	FormDate char(10)   COLLATE DATABASE_DEFAULT ,
	CheckNumber char(20)   COLLATE DATABASE_DEFAULT ,
