					  then CustomersGroup_2.acc_CTopicCode2  else CustomersGroup_1.acc_CTopicCode2 end 
				else 0 end 
		when 2 then LookUps_1.acc_CTopicCode2 ---- موضوع دريافت و پرداخت 1------
		when 3 then LookUps_2.acc_CTopicCode2 ---- موضوع دريافت و پرداخت 2------
		when 4  then Forms.CTopicCode2  ---کد حساب در فرم ----
		when 5  then FormItems.CTopicCode2  ---- کد حساب در اطلاعات فرم ------
		when 6 then case   ---- اطلاعات مشتري ----
				when FormTypes.CustCodeUse4Bes in  (1,4,5)  then Customers_1.acc_CTopicCode2 
				when FormTypes.CustCodeUse4Bes in  (2)  then Customers_2.acc_CTopicCode2 
				when FormTypes.CustCodeUse4Bes in  (3)  then Customers_3.acc_CTopicCode2 
				when FormTypes.CustCodeUse4Bes in  (7)  then Customers_3Master.acc_CTopicCode2 
				when FormTypes.CustCodeUse4Bes in  (8)  then Case FormItems.CheckType when 0 
					  then Customers_2.acc_CTopicCode2  else Customers_1.acc_CTopicCode2 end
				else 0  end 
		when 7 then Customers_3Master.acc_CTopicCode2		    
	else 0  end as CTopicCode2_Bes ,
	-----------------------------------------------------------------------------------------------------    مركز هزينه 2
	 case  FormTypes.DefaultCTopic3_Bes 
		when 1 then case   ---- اطلاعات گروه مشتري ----
				when FormTypes.CustCodeUse4Bes in  (1,4,5)  then CustomersGroup_1.acc_CTopicCode3 
				when FormTypes.CustCodeUse4Bes in  (2)  then CustomersGroup_2.acc_CTopicCode3 
				when FormTypes.CustCodeUse4Bes in  (3)  then CustomersGroup_3.acc_CTopicCode3 
				when FormTypes.CustCodeUse4Bes in  (8)  then Case FormItems.CheckType when 0 
					  then CustomersGroup_2.acc_CTopicCode3  else CustomersGroup_1.acc_CTopicCode3 end
				else 0 end 
		when 2 then LookUps_1.acc_CTopicCode3 ---- موضوع دريافت و پرداخت 1------
		when 3 then LookUps_2.acc_CTopicCode3 ---- موضوع دريافت و پرداخت 2------
		when 4  then Forms.CTopicCode3  ---کد حساب در فرم ----
		when 5  then FormItems.CTopicCode3  ---- کد حساب در اطلاعات فرم ------
		when 6 then case   ---- اطلاعات مشتري ----
				when FormTypes.CustCodeUse4Bes in  (1,4,5)  then Customers_1.acc_CTopicCode3 
				when FormTypes.CustCodeUse4Bes in  (2)  then Customers_2.acc_CTopicCode3 
				when FormTypes.CustCodeUse4Bes in  (3)  then Customers_3.acc_CTopicCode3 
					when FormTypes.CustCodeUse4Bes in  (8)  then Case FormItems.CheckType when 0 
					  then Customers_2.acc_CTopicCode3  else Customers_1.acc_CTopicCode3 end
				else 0  end 
		when 7 then Customers_3Master.acc_CTopicCode3			    
		when 8 then SE.CTopicCode3									 
		else 0  
	 end as CTopicCode3_Bes 
	,FormTypes.InfoUse4Bed 
	,FormTypes.InfoUse4Bes
	,CASE @MakeDocKind WHEN 2 THEN 0 ELSE Forms.CashCheckFormID END AS CashCheckFormID
	,FormItems.CustomerID2
	,Customers_3.CustName
	,FormTypes.UseBudgetKind -- to do -- add field on formtype 
    ,case when FormItems.BudgetCode!= 0 then FormItems.BudgetCode else forms.BudgetCode end BudgetCode
	,Forms.ServerID
	,Forms.YearID
	,FormItems.ArzAmount
	,FormItems.ArzAmountExchange as ArzAmountExchange 
	,forms.RelatedRecipts  as RelatedRecipts
	,FormItems.ArzRate
	,FormTypes.ConstTopicCode_ArzBed
	,ConstTopicCode_ArzBes 
	,Customers_1.CustName as ct1name
	,FormTypes.SeparationDoc
	,FormItems.ArzRate as RialsEqual
	,FormItems.CheckFor
	,FormItems.PO
	,Forms.ArzTypeID
	,FormTypes.InsertSeverableOnRecall
	,FormTypes.CashWageActive
	,FormItems.ArzTypeIDExchange
	,FormItems.ArzRateExchange
	,formtypes.DefaultCurrencyType_Bed
	,formtypes.DefaultCurrencyType_Bes
FROM    CustomersGroup CustomersGroup_2 INNER JOIN
		Customers Customers_2 ON CustomersGroup_2.CustomerGrpID = Customers_2.CustomerGrpID RIGHT OUTER JOIN
		FormItems INNER JOIN
		Forms ON FormItems.FormID = Forms.FormID  AND FormItems.ServerID = Forms.ServerID AND FormItems.YearID = Forms.YearID INNER JOIN
		FormTypes ON Forms.FormType = FormTypes.FormType LEFT OUTER JOIN
		Customers Customers_3 INNER JOIN
		CustomersGroup CustomersGroup_3 ON Customers_3.CustomerGrpID = CustomersGroup_3.CustomerGrpID ON 
		FormItems.CustomerID2 = Customers_3.CustID LEFT OUTER JOIN
		LookUps LookUps_1 ON Forms.PayTypes = LookUps_1.LookUpID LEFT OUTER JOIN
		LookUps LookUps_2 ON Forms.TopicTypes = LookUps_2.LookUpID LEFT OUTER JOIN
		CustomersGroup CustomersGroup_1 INNER JOIN
		Customers Customers_1 ON CustomersGroup_1.CustomerGrpID = Customers_1.CustomerGrpID 
		ON Forms.CustomerID1 = Customers_1.CustID ON 
		Customers_2.CustID = Forms.CustomerID2
----abedi
        INNER JOIN  Customers AS Customers_3Master ON Forms.CustomerID3 = Customers_3Master.CustID 
		INNER JOIN  CustomersGroup AS CustomersGroup_3Master ON Customers_3Master.CustomerGrpID = CustomersGroup_3Master.CustomerGrpID 
----abedi
        LEFT OUTER JOIN LookUps LookUps_TopicTypesI ON FormItems.TopicTypesI = LookUps_TopicTypesI.LookUpID 
		LEFT OUTER JOIN SellsEmporiums SE on SE.SellsEmporium=Forms.SellsEmporium
----abedi

		LEFT OUTER JOIN dbo.VU_BudgetTopics BTD  on  FormItems.BudgetCode = btD.[BudgetTopicID]
		LEFT OUTER JOIN dbo.VU_BudgetTopics BT on	Forms.BudgetCode	 = bt.[BudgetTopicID]
WHERE  ((Forms.DocNo =0)OR(@AllDocAble=1)) 
	  --(FormTypes.FormType = @FormType) AND 
       AND (Forms.FormNumber BETWEEN @FormNoFrom AND @FormNoTo ) 
	   AND (Forms.FormDate BETWEEN @FormDateFrom  AND @FormDateTo ) 
	   AND ((ISNULL(Forms.AidInfoDate, '') = '') OR (Forms.AidInfoDate = '/  /') OR (Forms.AidInfoDate BETWEEN @AidDateFrom AND @AidDateTo))
	   AND (FormItems.CheckState BETWEEN @CheckStateFrom  AND @CheckStateTo ) 
	   AND (Forms.FormState < 10) 
	   AND (FormItems.CheckType between 0 and  (case when ( FormTypes.DefaultTopic_Bed=7 or FormTypes.DefaultTopic_Bes=7 ) then 0 else   99 end ))
	   AND (Forms.SellsEmporium BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)
       AND (Forms.PayTypes BETWEEN @PayTypesFrom AND @PayTypesTo)
	   AND ((case when FormTypes.FormStateDefault4Doc = 0 then Forms.FormState else FormTypes.FormStateDefault4Doc end) = Forms.FormState)

   RETURN
END

