CREATE FUNCTION CofferAccount (@CustNoFrom varchar (12)=[0] , @CustNoTo varchar (12)=[999999999999] ,
				@FormDateFrom varchar(10)=[00/00/00], @FormDateTo varchar(10)=[99/99/99],
				@FormNoFrom varchar (12)=[-99999999], @FormNoTo varchar (12)=[99999999999]    )
RETURNS table  AS  
return (
-------------------------- acckind  نشان دهنده قطعي و غير قطعي بودن اعداد ميباشد و براي اسناد ÷راختني کاربرد دارد -----------------
---------------------------------------------------------------------------------------------------------------Forms----------------------------------------------------------------------------------------------------------------
SELECT     Forms.FormID, Forms.FormNumber, Forms.FormDate, '0' as checkNumber , '0' as checkDate ,Forms.FormType, FormTypes.FormCaption, 
		Forms.CustomerID1, Forms.CustomerID2, Forms.FomNote,Forms.AidInfoNo, Forms.AidInfoDate,
		case FormTypes.Customer1Effect when 1 then Forms.Amount else 0 end as Debt ,
		case FormTypes.Customer1Effect when 2 then Forms.Amount else 0 end as Credit ,
		Forms.BudgetCode, Forms.ProjectID, Forms.CustomerName2 ,Forms.FormDate as EffectDate , 0 as AccKind
FROM      Forms INNER JOIN
                FormTypes ON Forms.FormType = FormTypes.FormType
WHERE  (FormTypes.DetailDataType = 0) AND (FormTypes.Customer1Effect between 1 and 2 ) AND  Forms.FormState <10 AND
	  Forms.FormNumber between @FormNoFrom and @FormNoTo and 
	  Forms.FormDate between @FormDateFrom and @FormDateTo and
	  Forms.CustomerID1 between @CustNoFrom and @CustNoTo 

UNION ALL

SELECT Forms.FormID, Forms.FormNumber, Forms.FormDate,  '0' as checkNumber , '0' as checkDate , Forms.FormType, FormTypes.FormCaption, 
	 Forms.CustomerID2, Forms.CustomerID1, Forms.FomNote,Forms.AidInfoNo, Forms.AidInfoDate,
	 case FormTypes.Customer2Effect when 1 then Forms.Amount else 0 end as Debt ,
	 case FormTypes.Customer2Effect when 2 then Forms.Amount else 0 end as Credit ,
	 Forms.BudgetCode, Forms.ProjectID, Forms.CustomerName2 ,Forms.FormDate as EffectDate , 0 as AccKind
FROM         Forms INNER JOIN
                      FormTypes ON Forms.FormType = FormTypes.FormType
WHERE     (FormTypes.DetailDataType = 0) AND (FormTypes.Customer2Effect between 1 and 2 ) AND   Forms.FormState <10 AND
	  Forms.FormNumber between @FormNoFrom and @FormNoTo and 
	  Forms.FormDate between @FormDateFrom and @FormDateTo and
	  Forms.CustomerID2 between @CustNoFrom and @CustNoTo 

-----------------------------------------------------------------------------------------------------------Forms End------------------------------------------------------------------------------------------------------------
UNION ALL

SELECT	Forms.FormID, Forms.FormNumber, Forms.FormDate, FormItems.CheckNumber, FormItems.CheckDate, Forms.FormType, 
		FormTypes.FormCaption, Forms.CustomerID1 , Forms.CustomerID2  , 
		Forms.FomNote, Forms.AidInfoNo, Forms.AidInfoDate,
		case FormTypes.Customer1Effect when 1 then FormItems.ItemAmount else 0 end as Debt ,
		case FormTypes.Customer1Effect when 2 then FormItems.ItemAmount else 0 end as Credit ,
		0 as BudgetCode ,0 as ProjectID , Forms.CustomerName2 ,
		case when FormTypes.Customer1Effect  in(1,2) then Forms.FormDate else FormItems.CheckDate end as EffectDate , 0 as AccKind
FROM		Forms INNER JOIN
		FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
		FormItems ON Forms.FormID = FormItems.FormID and Forms.ServerID = FormItems.ServerID and Forms.YearID = FormItems.YearID
WHERE	FormTypes.Customer1Effect between 1 and 4 AND   Forms.FormState <10 AND
	  Forms.FormNumber between @FormNoFrom and @FormNoTo and 
               case when FormTypes.Customer1Effect  in(1,2) then Forms.FormDate else FormItems.CheckDate end  between @FormDateFrom and @FormDateTo and
	  Forms.CustomerID1 between @CustNoFrom and @CustNoTo 

UNION ALL

SELECT	Forms.FormID, Forms.FormNumber, Forms.FormDate, FormItems.CheckNumber, FormItems.CheckDate, Forms.FormType, 
		FormTypes.FormCaption,  Forms.CustomerID2  ,Forms.CustomerID1, 
		Forms.FomNote, Forms.AidInfoNo, Forms.AidInfoDate,
		case FormTypes.Customer2Effect when 1 then FormItems.ItemAmount else 0 end as Debt ,
		case FormTypes.Customer2Effect when 2 then FormItems.ItemAmount else 0 end as Credit ,
		0  as BudgetCode ,0 as ProjectID , Forms.CustomerName2,
		case when FormTypes.Customer1Effect  in(1,2) then Forms.FormDate else FormItems.CheckDate end as EffectDate , 0 as AccKind
FROM		Forms INNER JOIN
		FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
		FormItems ON Forms.FormID = FormItems.FormID and Forms.ServerID = FormItems.ServerID and Forms.YearID = FormItems.YearID

WHERE	FormTypes.Customer2Effect between 1 and 4 and   Forms.FormState <10 AND
	  Forms.FormNumber between @FormNoFrom and @FormNoTo and 
               case when FormTypes.Customer2Effect  in(1,2) then Forms.FormDate else FormItems.CheckDate end  between @FormDateFrom and @FormDateTo and
	  Forms.CustomerID2 between @CustNoFrom and @CustNoTo 

---------------------------------------------------------------
UNION ALL

SELECT     Forms.FormID, Forms.FormNumber, Forms.FormDate, FormItems.CheckNumber, FormItems.CheckDate, Forms.FormType, 
                      FormTypes.FormCaption, Forms.CustomerID1, Forms.CustomerID2, Forms.FomNote, Forms.AidInfoNo, Forms.AidInfoDate, 
		case FormTypes.Customer1Effect when 1 then FormItems.ItemAmount else 0 end as Debt ,
		case FormTypes.Customer1Effect when 2 then FormItems.ItemAmount else 0 end as Credit ,
		0 AS BudgetCode, 0 AS ProjectID, Forms.CustomerName2, FormItems.CheckDate  as EffectDate , 1 as AccKind
FROM         Forms INNER JOIN
                      FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
                      FormItems ON Forms.FormID = FormItems.FormID and Forms.ServerID = FormItems.ServerID and Forms.YearID = FormItems.YearID  LEFT OUTER JOIN
                      FormItems FormItems_1 ON FormItems.FormItemID = FormItems_1.preFormItemID
WHERE     (FormTypes.Customer1Effect BETWEEN 5 AND 6) AND (FormItems_1.preFormItemID IS NULL) and    Forms.FormState <10 AND
	  Forms.FormNumber between @FormNoFrom and @FormNoTo and 
               FormItems.CheckDate  between @FormDateFrom and @FormDateTo and
	  Forms.CustomerID1 between @CustNoFrom and @CustNoTo 

union all
SELECT	Forms.FormID, Forms.FormNumber, Forms.FormDate, FormItems.CheckNumber, FormItems.CheckDate, Forms.FormType, 
		FormTypes.FormCaption,  Forms.CustomerID2  ,Forms.CustomerID1, 
		Forms.FomNote, Forms.AidInfoNo, Forms.AidInfoDate,
		case FormTypes.Customer2Effect when 1 then FormItems.ItemAmount else 0 end as Debt ,
		case FormTypes.Customer2Effect when 2 then FormItems.ItemAmount else 0 end as Credit ,
		0  as BudgetCode ,0 as ProjectID , Forms.CustomerName2,
		FormItems.CheckDate  as EffectDate , 1 as AccKind
FROM         Forms INNER JOIN
                      FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
                      FormItems ON Forms.FormID = FormItems.FormID and Forms.ServerID = FormItems.ServerID and Forms.YearID = FormItems.YearID  LEFT OUTER JOIN
                      FormItems FormItems_1 ON FormItems.FormItemID = FormItems_1.preFormItemID

WHERE	FormTypes.Customer2Effect between 5 and 6 AND (FormItems_1.preFormItemID IS NULL) and    Forms.FormState <10 AND
	  Forms.FormNumber between @FormNoFrom and @FormNoTo and 
               FormItems.CheckDate   between @FormDateFrom and @FormDateTo and
	  Forms.CustomerID2 between @CustNoFrom and @CustNoTo )
--------------------------------------------------------------
