CREATE VIEW dbo.vW_OutputReciptsArzi
as
select r.reciptid,r.yearid,r.serverid,rtype.reciptcaption,isnull(round(sum(ri.outputentity), 2), 0) as meghdarsadere,
           isnull(sum(ri.totaloutputprice), 0) as bahasadere,isnull(sum(isnull(ri.deficitvalue, 0) + isnull(ri.deficitvalue2, 0) + isnull(ri.deficitvalue4, 0)+ isnull(ri.deficitvalue3, 0)), 0) as takhfif,
           isnull(sum(ri.taxvalue), 0) as maliat, isnull(sum(ri.totallsellprice), 0) as khales,isnull(sum(ri.arzamount), 0) as marzi,
           isnull(sum(ri.commissionprice), 0) as mzakhire,isnull(sum(ri.commissioncurrency), 0) as zakhirearzi
    from reciptitems ri inner join recipts r on r.reciptid = ri.reciptid and r.serverid = ri.serverid and r.yearid = ri.yearid
        inner join recipttypes1 as rtype on r.recipttype = rtype.recipttype  where  (r.ReciptType IN (171, 172, 170, 12))
    group by r.reciptid,rtype.reciptcaption,r.yearid,r.serverid

