CREATE VIEW dbo.vW_EXchTo
as
SELECT  c.CurrenciesID, MAX(c.EqualityWithMainUnit) AS EqualityWithMainUnit , c.CurrenciesDate,c.CurrenciesTime
                        FROM    CurrenciesItems c
                         INNER JOIN (
SELECT m.CurrenciesDate,m.t,m.CurrenciesID FROM
(SELECT        CurrenciesDate,  MAX(CurrenciesTime) AS t,CurrenciesID
FROM            CurrenciesItems
where      (CurrenciesID >= 10)  
GROUP BY  CurrenciesDate,CurrenciesID) AS M) AS CI2 ON c.CurrenciesTime=ci2.t
 WHERE   (c.CurrenciesID >= 10) AND c.CurrenciesDate=ci2.CurrenciesDate AND c.CurrenciesID=ci2.CurrenciesID 
 GROUP BY c.CurrenciesDate,c.CurrenciesTime,c.CurrenciesID


