CREATE PROCEDURE dbo.GetANewCode @FormName VARCHAR(100), @tblName  VARCHAR(2000), @fldName  VARCHAR(100),
  @YearID  Int=1399,  @ISKey  Bit = 0 , @ID bigint out
AS
SET NOCOUNT ON
BEGIN
DECLARE @isID bigint
    SET @FormName = Lower(@FormName);
    SET @tblName = Lower(@tblName);
    SET @fldName = Lower(@fldName);
	if @tblName ='recipts'
         Select @ID=isnull(max(ReciptID),0)+1 from Recipts where YearID = @YearID
	  else
	  	if @tblName ='reciptitems'
          Select @ID=isnull(max(ReciptItemID),0)+1 from Reciptitems where YearID = @YearID
		  else
	  		if @tblName ='forms'
			  Select @ID=isnull(max(FormID),0)+1 from Forms where YearID = @YearID
			  else
	  			if @tblName ='formitems'
				  Select @ID=isnull(max(FormItemID),0)+1 from Formitems where YearID = @YearID




   Select @isID=MAX(Value) + 1 from  util.CodesInProcess where (TableName =@tblName) 
         and (FieldName = @fldName)       and (type = 0)
      and case when  @ISKey=0 then  FormName else @FormName end =@FormName


      if (isnull(@isID,0) <> 0) and (@isID > @ID) 
     SET   @ID = @isID
      Insert Into util.CodesInProcess
	            (UserID,FormName,TableName,FieldName,[Value],[Ip],[Type]) 
         values (0,@FormName ,@tblName,@fldName,@ID, '127001' , 0)
    

end



GO 




CREATE PROCEDURE dbo.FreeReservedCodes @FormName VARCHAR(100), @tblName  VARCHAR(2000), 
         @fldName  VARCHAR(100),  @UserID  Int=0
AS
SET NOCOUNT ON
BEGIN
	SET @FormName = Lower(@FormName)
	SET @tblName = Lower(@tblName)
	SET @fldName = Lower(@fldName)
	DELETE FROM Util.CodesInProcess
	WHERE (UserID = @UserID) AND (Ip = '127001') 
	AND (@FormName <> '' OR FormName = @FormName) 
    AND (TableName <> '' OR TableName = @tblName) 
	AND (FieldName <> '' OR FieldName = @fldName)
    

END




GO 


CREATE PROCEDURE dbo.Sp_Recipts_In
@ExternalId    VARCHAR(100),    
@ReciptType    int,
@YearID        int  ,
@StoreID       int,
@StoreID2      int,
@PersonID1     int,  
@PersonID2     int,
@PersonID3     int,
@OperatorID    int,
@ReciptDate    CHAR(10),
@ReciptNote    VARCHAR(400),
@ReciptNumber  int            out,
@ReciptCaption NVARCHAR(70)   out,
@ID            Bigint         OUT ,
@ErrorNumber   int            OUT,
@ErrorMessage  NVARCHAR(4000) OUT 
AS
SET NOCOUNT ON
BEGIN
DECLARE @ReciptID int  
DECLARE @ServerID int=0
DECLARE @SellsEmporium int=1
DECLARE @ReciptState int  
DECLARE @DocNo int  


SET @ID = 0
 SELECT @ReciptCaption=ReciptCaption FROM ReciptTypes
     WHERE  (ReciptType = @ReciptType)

 SELECT  @ReciptNumber=ReciptNumber,@ReciptID=ReciptID,@ID=ID,@ReciptState=ReciptState,@DocNo=DocNo FROM Recipts   WHERE   (LTRIM(RTRIM(TruckNumber)) = LTRIM(RTRIM(@ExternalId)))

if   ((@ReciptNumber is NULL) or (@ReciptNumber=''))
begin
SET @ReciptNumber=@ExternalId
DECLARE  @UserName VARCHAR(50)='كاربر SQL'

EXEC	 [dbo].[GetANewCode] 		@FormName = N'12', 		@tblName = N'Recipts',
		@fldName = N'ReciptID',		@YearID = 1399, 		@ISKey = 1, 		@ID = @ID OUTPUT

SET @ReciptID = @ID

BEGIN TRY  
INSERT INTO 
Recipts(ReciptID,  StoreID, StoreID2 ,  ReciptNumber,InsertDate , ModifyDate,  PersonID1 , PersonID2,   PersonID3, ReciptType, ReciptDate,  OperatorID,  
          FirstUser, YearID,  ServerID , PrvYearID,UseOtherID , SellsEmporium,ReciptState,TruckNumber,ReciptNote)
VALUES (@ReciptID, @StoreID, @StoreID2 , @ReciptNumber,GETDATE(), GETDATE(), @PersonID1 , @PersonID2 ,@PersonID3 ,    @ReciptType, @ReciptDate, ISNULL(  @OperatorID,0)  ,    
          @UserName, @YearID, @ServerID, @YearID,      0 ,  @SellsEmporium ,0,@ExternalId,RTRIM(LTRIM(@ReciptNote))  )

SET @ID =(CONVERT(bigint,(LTRIM(@YearID)+right('0'+LTRIM(@ServerID),(2)))+LTRIM(abs(@ReciptID)),0))
END TRY  
BEGIN CATCH  
    SET @ID =0
    SELECT     @ErrorNumber= ERROR_NUMBER() ,@ErrorMessage= ERROR_MESSAGE()   
END CATCH; 

EXEC	 [dbo].FreeReservedCodes 		@FormName = N'12', 		@tblName = N'Recipts',		@fldName = N'ReciptID',
		         @UserID = 0

END
else 
begin
BEGIN TRY  
  if @ReciptState in (1, 2, 3) 
  begin
    set @ErrorNumber=-1
    set @ErrorMessage ='فقط ' + @ReciptCaption +
      ' كه نوع اطلاعات آن موقت/پیش نویس/رزرو است قابل ویرایش است'      
    RETURN
  end;
  
  if @DocNo <> 0 
  begin
    set @ErrorNumber=-2
    set @ErrorMessage ='فقط ' + @ReciptCaption +
      'که برایش سند حسابداری ثبت نشده باشد قابل ویرایش است‏'      
    RETURN
  end;

  UPDATE  Recipts SET                
     StoreID = @StoreID , StoreID2 = @StoreID2 ,ModifyDate =GETDATE() , PersonID1 = @PersonID1 
  , PersonID2 = @PersonID2 , PersonID3 = @PersonID3 ,ReciptDate = @ReciptDate , LastUser = @UserName
  , SellsEmporium = @SellsEmporium , ReciptNote  = RTRIM(LTRIM(@ReciptNote)) 
   WHERE   (LTRIM(RTRIM(TruckNumber)) = LTRIM(RTRIM(@ExternalId))) 
END TRY  
BEGIN CATCH  
    SET @ID = 0
    SELECT     @ErrorNumber= ERROR_NUMBER() ,@ErrorMessage= ERROR_MESSAGE()   
END CATCH; 
end
END 
  
GO 


CREATE PROCEDURE dbo.Sp_ReciptItems_In
@ExternalId    VARCHAR(100),    
@MasterID bigint,
@StuffCode bigint,
@Entity float ,
@Weight float ,
@UnitSellPrice float ,
@TotalPrice money ,
@ItemNote  VARCHAR(400),
@PersonID1 int ,
@ID Bigint OUT ,
@ErrorNumber  int OUT,
@ErrorMessage NVARCHAR(4000) OUT 
AS
SET NOCOUNT ON
BEGIN
DECLARE  @FormOutput tinyint 
DECLARE  @ReciptItemID int  
DECLARE  @ReciptID int  
DECLARE  @YearID int   
DECLARE  @ServerID int 
DECLARE @ReciptState int  
DECLARE @DocNo int  
DECLARE @ReciptCaption varchar(70)  

 SELECT @ReciptID=Recipts.ReciptID,@YearID=Recipts.YearID,@ServerID=Recipts.ServerID,@FormOutput = CASE WHEN ReciptTypes1.EffectType  in (3, 4, 5, 7 ,  8  ) THEN 1 ELSE 0 END
     ,@ReciptState=Recipts.ReciptState,@DocNo=Recipts.DocNo ,@ReciptCaption = ReciptTypes1.ReciptCaption
 FROM            Recipts INNER JOIN
                         ReciptTypes1 ON Recipts.ReciptType = ReciptTypes1.ReciptType
WHERE        (Recipts.ID = @MasterID)
     
DECLARE  @FirstUser VARCHAR(50)='كاربر SQL'
DECLARE  @InputEntity float = 0 
DECLARE  @OutputEntity float = 0  
DECLARE  @InputWeight float = 0 
DECLARE  @OutputWeight float = 0  
DECLARE  @TotalInputPrice money = 0 
DECLARE  @TotalOutputPrice money = 0 
DECLARE  @TotallSellPrice money = 0  

if @FormOutput = 1
begin
  SET @OutputEntity = @Entity
  SET @OutputWeight = @Weight
  SET @TotalOutputPrice = @TotalPrice
  if  @TotalOutputPrice = 0
    SET @TotalOutputPrice =round( @Entity * @UnitSellPrice,0)
  SET @TotallSellPrice = @TotalOutputPrice
end
else
begin
  SET @InputEntity = @Entity
  SET @InputWeight = @Weight
  SET @TotalInputPrice = @TotalPrice
  if  @TotalInputPrice = 0
    SET @TotalInputPrice =round( @Entity * @UnitSellPrice,0)
  SET @TotallSellPrice = @TotalInputPrice
end

declare  @MachineNo varchar(100)

 SELECT  @MachineNo=MachineNo,@ID=ID FROM ReciptItems   WHERE   (LTRIM(RTRIM(MachineNo)) = LTRIM(RTRIM(@ExternalId)))

if   ((@MachineNo is NULL) or (@MachineNo=''))
begin

EXEC	 [dbo].[GetANewCode]
		@FormName = N'12',
		@tblName = N'ReciptItems',
		@fldName = N'ReciptItemID',
		@YearID = 1399,
		@ISKey = 1,
		@ID = @ID OUTPUT
SET @ReciptItemID = @ID


BEGIN TRY  

INSERT INTO 
ReciptItems(MachineNo,ReciptItemID, ReciptID, ServerID, YearID, PrvYearID, StuffCode, InputEntity, OutputEntity, InputWeight, OutputWeight, TotalInputPrice, 
    TotalOutputPrice, UnitSellPrice, TotallSellPrice, ItemNote, PersonID1, FirstUser)
VALUES (@ExternalId,@ReciptItemID,@ReciptID, @ServerID, @YearID , @YearID, @StuffCode, @InputEntity, @OutputEntity, @InputWeight, @OutputWeight, @TotalInputPrice, 
    @TotalOutputPrice, @UnitSellPrice, @TotallSellPrice, @ItemNote, @PersonID1 , @FirstUser)
	
  SET @ID =(CONVERT(bigint,(LTRIM(@YearID)+right('0'+LTRIM(@ServerID),(2)))+LTRIM(abs(@ReciptItemID)),0))
END TRY  
BEGIN CATCH  
    SET @ID =0
    SELECT     @ErrorNumber= ERROR_NUMBER() ,@ErrorMessage= ERROR_MESSAGE()   
END CATCH; 

EXEC	 [dbo].FreeReservedCodes
		@FormName = N'12',
		@tblName = N'ReciptItems',
		@fldName = N'ReciptItemID',
		@UserID = 0
end
else 
begin
BEGIN TRY  
  if @ReciptState in (1, 2, 3) 
  begin
    set @ErrorNumber=-1
    set @ErrorMessage ='فقط ' + @ReciptCaption +
      ' كه نوع اطلاعات آن موقت/پیش نویس/رزرو است قابل ویرایش است'      
    RETURN
  end;
  
  if @DocNo <> 0 
  begin
    set @ErrorNumber=-2
    set @ErrorMessage ='فقط ' + @ReciptCaption +
      'که برایش سند حسابداری ثبت نشده باشد قابل ویرایش است‏'      
    RETURN
  end;
  UPDATE  Reciptitems SET                
     StuffCode = @StuffCode , InputEntity = @InputEntity , OutputEntity = @OutputEntity
  , InputWeight = @InputWeight , OutputWeight = @OutputWeight ,TotalInputPrice = @TotalInputPrice , LastUser = @FirstUser
  , TotalOutputPrice = @TotalOutputPrice , ItemNote  = RTRIM(LTRIM(@ItemNote)) ,UnitSellPrice =@UnitSellPrice
  ,TotallSellPrice=@TotallSellPrice,PersonID1 =@PersonID1
   WHERE   (LTRIM(RTRIM(MachineNo)) = LTRIM(RTRIM(@ExternalId))) 

END TRY  
BEGIN CATCH  
    SELECT     @ErrorNumber= ERROR_NUMBER() ,@ErrorMessage= ERROR_MESSAGE()   
END CATCH; 
end





END 
  
GO 
CREATE PROCEDURE dbo.Sp_Recipts_Delete
@ExternalId    VARCHAR(100),    
@ID            Bigint         ,
@ErrorNumber   int            OUT,
@ErrorMessage  NVARCHAR(4000) OUT 
AS
SET NOCOUNT ON
BEGIN
DECLARE @ReciptState INT
DECLARE @DocNo INT
DECLARE @ReciptCaption VARCHAR(70)
SELECT    @ReciptState= Recipts.ReciptState,@DocNo= Recipts.DocNo, @ReciptCaption=ReciptTypes1.ReciptCaption+'('+ltrim(Recipts.ReciptNumber)+')'
FROM            Recipts INNER JOIN ReciptTypes1 ON Recipts.ReciptType = ReciptTypes1.ReciptType
WHERE        (Recipts.ID = @ID)AND (Recipts.TruckNumber = @ExternalId)

  if @ReciptState in (1, 2, 3) 
  begin
    set @ErrorNumber=-1
    set @ErrorMessage ='فقط ' + @ReciptCaption +
      ' كه نوع اطلاعات آن موقت/پیش نویس/رزرو است قابل حذف است'      
    RETURN
  end;
  
  if @DocNo <> 0 
  begin
    set @ErrorNumber=-2
    set @ErrorMessage ='فقط ' + @ReciptCaption +
      'که برایش سند حسابداری ثبت نشده باشد قابل حذف است‏'      
    RETURN
  end;



BEGIN TRY  
DELETE FROM Recipts WHERE        (Recipts.ID = @ID)AND (Recipts.TruckNumber = @ExternalId)
END TRY  
BEGIN CATCH  
    SELECT     @ErrorNumber= ERROR_NUMBER() ,@ErrorMessage= ERROR_MESSAGE()   
END CATCH; 


END


  
