CREATE PROCEDURE dbo.Sp_Forms_In
@ExternalId VARCHAR(100),
@YearID int  ,
@FormType int,
@CustomerID1 int,
@CustomerID2 int,
@CustomerID3 int,
@OperatorID int,
@FormDate CHAR(10),
@Amount money ,
@FormNote  VARCHAR(400),
@FormNumber int out,
@FormCaption NVARCHAR(70) out,
@ID Bigint OUT ,
@ErrorNumber  int OUT,
@ErrorMessage NVARCHAR(4000) OUT 
AS
SET NOCOUNT ON
BEGIN
DECLARE @FormID int  
DECLARE @ServerID int=0
DECLARE @SellsEmporium int=1

SET @ID = 0
 SELECT @FormCaption=FormCaption FROM FormTypes
     WHERE  (FormType = @FormType)

declare @FormState int
declare @DocNo int
SELECT  @FormNumber=FormNumber,@FormID=FormID,@ID=ID,@FormState=FormState,@DocNo=DocNo FROM Forms   WHERE   (LTRIM(RTRIM(TruckNumber)) = LTRIM(RTRIM(@ExternalId)))

if   ((@FormNumber is NULL) or (@FormNumber=''))
begin
SET @FormNumber=@ExternalId
DECLARE  @UserName VARCHAR(50)='كاربر SQL'

EXEC	 dbo.GetANewCode 		@FormName = N'1', 		@tblName = N'Forms',
		@fldName = N'FormID',		@YearID = 1399, 		@ISKey = 1, 		@ID = @ID OUTPUT

SET @FormID = @ID

BEGIN TRY  
INSERT INTO 
Forms(FormID,   FormNumber,Amount, ModifyDate,  CustomerID1 , CustomerID2,   CustomerID3, FormType, FormDate,  OperatorID,  
          FirstUser, YearID,  ServerID ,  SellsEmporium,FormState,TruckNumber,FomNote)
VALUES (@FormID,  @FormNumber,@Amount,GETDATE(), @CustomerID1 , @CustomerID2 ,@CustomerID3 ,    @FormType, @FormDate, ISNULL(  @OperatorID,0)  ,    
          @UserName, @YearID, @ServerID, @SellsEmporium ,0,@ExternalId,RTRIM(LTRIM(@FormNote))  )

SET @ID =(CONVERT(bigint,(LTRIM(@YearID)+right('0'+LTRIM(@ServerID),(2)))+LTRIM(abs(@FormID)),0))
END TRY  
BEGIN CATCH  
    SET @ID =0
    SELECT     @ErrorNumber= ERROR_NUMBER() ,@ErrorMessage= ERROR_MESSAGE()   
END CATCH; 

EXEC	 [dbo].FreeReservedCodes 		@FormName = N'1', 		@tblName = N'Forms',		@fldName = N'FormID',
		         @UserID = 0

END
else 
begin
BEGIN TRY  
  if @FormState > 0 
  begin
    set @ErrorNumber=-1
    set @ErrorMessage ='فقط ' + @FormCaption +
      ' كه نوع اطلاعات آن موقت است قابل ویرایش است'      
    RETURN
  end;
  
  if @DocNo <> 0 
  begin
    set @ErrorNumber=-2
    set @ErrorMessage ='فقط ' + @FormCaption +
      'که برایش سند حسابداری ثبت نشده باشد قابل ویرایش است‏'      
    RETURN
  end;

  UPDATE  Forms SET                
     FormNumber = @FormNumber , Amount = @Amount ,ModifyDate = GETDATE() , CustomerID1 = @CustomerID1 
  , CustomerID2 = @CustomerID2 , CustomerID3 = @CustomerID3 ,FormDate = @FormDate , LastUser = @UserName
  , SellsEmporium = @SellsEmporium , FomNote  = RTRIM(LTRIM(@FormNote)) 
    WHERE   (LTRIM(RTRIM(TruckNumber)) = LTRIM(RTRIM(@ExternalId))) 

END TRY  
BEGIN CATCH  
    SET @ID = 0
    SELECT     @ErrorNumber= ERROR_NUMBER() ,@ErrorMessage= ERROR_MESSAGE()   
END CATCH; 
end

END 
  
GO 

