CREATE PROCEDURE dbo.Sp_Forms_Delete
@ExternalId    VARCHAR(100),    
@ID            Bigint         ,
@ErrorNumber   int            OUT,
@ErrorMessage  NVARCHAR(4000) OUT 
AS
SET NOCOUNT ON
BEGIN
DECLARE @FormState INT
DECLARE @DocNo INT
DECLARE @FormCaption VARCHAR(70)
SELECT    @FormState= Forms.FormState,@DocNo= Forms.DocNo, @FormCaption=FormTypes.FormCaption+'('+ltrim(Forms.FormNumber)+')'
FROM            Forms INNER JOIN FormTypes ON Forms.FormType = FormTypes.FormType
WHERE        (Forms.ID = @ID)AND (Forms.TruckNumber = @ExternalId)

  if @FormState > 0 
  begin
    set @ErrorNumber=-1
    set @ErrorMessage ='فقط ' + @FormCaption +' كه نوع اطلاعات آن موقت است قابل حذف است'      
    RETURN
  end;
  
  if @DocNo <> 0 
  begin
    set @ErrorNumber=-2
    set @ErrorMessage ='فقط ' + @FormCaption + 'که برایش سند حسابداری ثبت نشده باشد قابل حذف است‏'      
    RETURN
  end;



BEGIN TRY  
DELETE FROM Forms WHERE(Forms.ID = @ID)AND (Forms.TruckNumber = @ExternalId)
END TRY  
BEGIN CATCH  
    SELECT     @ErrorNumber= ERROR_NUMBER() ,@ErrorMessage= ERROR_MESSAGE()   
END CATCH; 


END

