CREATE FUNCTION StuffCodeEntity  (  @YearIDFrom  int =88 , @YearIDTo int =88,@Date as Char(10) =[88/12/29]) 
RETURNS table  AS  
return (
--SELECT    Recipts.YearID, Recipts.StoreID, ReciptItems.StuffCode, StuffCoding.c_StuffName, Units.UnitName, 
--                     ISNull( ROUND(SUM(ReciptItems.InputEntity - ReciptItems.OutputEntity), 3),0) AS Entity, 
--                     ISNull( ROUND(SUM(ReciptItems.InputWeight - ReciptItems.OutputWeight), 3),0) AS Weight, 
--case when SUM(ReciptItems.InputEntity - ReciptItems.OutputEntity)<>0 then
--          SUM(ReciptItems.TotalInputPrice - ReciptItems.TotalOutputPrice) 
--     else 0 end AS Price, 
--                     -- SUM((CASE ReciptTypes.EffectType WHEN 2 THEN ReciptItems.TotallSellPrice ELSE - 1 * ReciptItems.TotallSellPrice END)) 
--                     -- AS TotallSellPrice, 
--                      SUM( ReciptItems.TotallSellPrice )  AS TotallSellPrice, 
----	       max((CASE ReciptTypes.EffectType WHEN 2 THEN ReciptItems.UnitSellPrice ELSE 0 END))  AS MaxUnitPrice
--	       max( ReciptItems.UnitSellPrice )  AS MaxUnitPrice
--FROM      ReciptItems_Stock as   ReciptItems INNER JOIN
--                      Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
--                      StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode INNER JOIN
--                      Units ON StuffCoding.n_UnitCode = Units.UnitCode INNER JOIN
--                      ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
--WHERE   
-- -- (ReciptTypes.EffectType IN (2, 4)) AND (Recipts.ReciptState < 3)  AND 
--  (Recipts.yearID between @YearIDFrom And @YearIDTo ) 
--          AND (Recipts.ReciptDate <= @Date )
--GROUP BY  Recipts.YearID, Recipts.StoreID, ReciptItems.StuffCode, StuffCoding.c_StuffName, Units.UnitName
--HAVING      (SUM(ReciptItems.InputEntity - ReciptItems.OutputEntity) >= 0.0001) OR
--                      (SUM(ReciptItems.InputEntity - ReciptItems.OutputEntity) <= - 0.0001) OR
--                      (SUM(ReciptItems.InputWeight - ReciptItems.OutputWeight) >= 0.0001) OR
--                      (SUM(ReciptItems.InputWeight - ReciptItems.OutputWeight) <= - 0.0001) OR
--                      (SUM(ReciptItems.TotalInputPrice - ReciptItems.TotalOutputPrice) >= 0.1) OR
--                      (SUM(ReciptItems.TotalInputPrice - ReciptItems.TotalOutputPrice) <= - 0.1)

SELECT        ReciptItems_Stock.YearID, ReciptItems_Stock.StoreID, ReciptItems_Stock.StuffCode, StuffCoding.c_StuffName, Units.UnitName, 
                         ISNULL(ROUND(SUM(ReciptItems_Stock.InputEntity - ReciptItems_Stock.OutputEntity), 4), 0) AS Entity, 
                         ISNULL(ROUND(SUM(ReciptItems_Stock.InputWeight - ReciptItems_Stock.OutputWeight), 4), 0) AS Weight, 
                         CASE WHEN SUM(ReciptItems_Stock.InputEntity - ReciptItems_Stock.OutputEntity) 
                         <> 0 THEN SUM(ReciptItems_Stock.TotalInputPrice - ReciptItems_Stock.TotalOutputPrice) ELSE 0 END AS Price
						 , SUM(CAST(ReciptItems_Stock.TotallSellPrice as decimal(25,0)) ) AS TotallSellPrice, MAX(ReciptItems_Stock.UnitSellPrice) AS MaxUnitPrice
FROM            ReciptItems_Stock INNER JOIN
                         StuffCoding ON ReciptItems_Stock.StuffCode = StuffCoding.c_StuffCode INNER JOIN
                         Units ON StuffCoding.n_UnitCode = Units.UnitCode
WHERE        (ReciptItems_Stock.YearID BETWEEN @YearIDFrom AND @YearIDTo) AND (ReciptItems_Stock.ReciptDate <= @Date) 
GROUP BY ReciptItems_Stock.YearID, ReciptItems_Stock.StoreID, ReciptItems_Stock.StuffCode, StuffCoding.c_StuffName, Units.UnitName
HAVING        (SUM(ReciptItems_Stock.InputEntity - ReciptItems_Stock.OutputEntity) >= 0.0001) OR
                         (SUM(ReciptItems_Stock.InputEntity - ReciptItems_Stock.OutputEntity) <= - 0.0001) OR
                         (SUM(ReciptItems_Stock.InputWeight - ReciptItems_Stock.OutputWeight) >= 0.0001) OR
                         (SUM(ReciptItems_Stock.InputWeight - ReciptItems_Stock.OutputWeight) <= - 0.0001) OR
                         (SUM(ReciptItems_Stock.TotalInputPrice - ReciptItems_Stock.TotalOutputPrice) >= 0.1) OR
                         (SUM(ReciptItems_Stock.TotalInputPrice - ReciptItems_Stock.TotalOutputPrice) <= - 0.1)

)
