CREATE FUNCTION StuffCodeCountingItems ( @YearIDFrom  int =88 , @YearIDTo int =88,@Date as Char(10) =[88/12/29] )
RETURNS table  AS  
return (SELECT	CountingItems.StuffCode, StuffCoding.c_StuffName, CountingItems.StuffSize, 	CountingItems.StuffDiameter, 
		CountingItems.StuffAlloy, CountingItems.StuffGrade, CountingItems.ControlCode, CountingItems.Count1Entity, 
		CountingItems.Count1Weight, CountingItems.Count2Entity, CountingItems.Count2Weight, CountingItems.Count3Entity, 
		CountingItems.Count3Weight, 
		CountingItems.ReciptID,
		CASE  Counting.CountingCalckind 
		WHEN 0 THEN (CASE WHEN (CountingItems.Count3Entity >=0 ) 
				THEN CountingItems.Count3Entity 
				ELSE  case when (CountingItems.Count1Entity = CountingItems.Count2Entity)  and not (CountingItems.Count2Entity IS NULL)
				then 	CountingItems.Count1Entity  else null  end  END) 
		WHEN 1 THEN  (CASE  
		
		                   ---ADD By Abedi orderby Shabanian
						   WHEN (CountingItems.Count2Entity = 0 ) THEN 0
		
		                    WHEN (CountingItems.Count2Entity >0 ) 
				THEN CountingItems.Count2Entity 
				ELSE  case when CountingItems.Count1Entity = isnull(StuffCodeEntity_c.Entity,0) 
				then 	CountingItems.Count1Entity  else null  end  END) 

		WHEN 2 THEN (CASE WHEN (CountingItems.Count3Entity >=0 ) 
				THEN CountingItems.Count3Entity 
				ELSE  case when ( CountingItems.Count1Entity = isnull(StuffCodeEntity_c.Entity,0)  ) 
						or ( CountingItems.Count2Entity = isnull(StuffCodeEntity_c.Entity,0)  ) 
				then 	isnull(StuffCodeEntity_c.Entity,0)  else null  end  END) 
		ELSE null END AS DifferEntity, 

		CASE  Counting.CountingCalckind 
		WHEN 0 THEN (CASE WHEN (CountingItems.Count3Weight >0 ) 
				THEN CountingItems.Count3Weight 
				ELSE  case when (CountingItems.Count1Weight = CountingItems.Count2Weight) and not (CountingItems.Count2Weight IS NULL)
				then 	CountingItems.Count1Weight  else null  end  END) 
		WHEN 1 THEN  (CASE  
		
		                   ---ADD By Abedi orderby Shabanian
						   WHEN (CountingItems.Count2Weight = 0 ) THEN 0
		
		                    WHEN (CountingItems.Count2Weight >0 ) 
				THEN CountingItems.Count2Weight 
				ELSE  case when CountingItems.Count1Weight = isnull(StuffCodeEntity_c.Weight,0) 
				then 	CountingItems.Count1Weight  else null  end  END) 

		WHEN 2 THEN (CASE WHEN (CountingItems.Count3Weight >=0 ) 
				THEN CountingItems.Count3Weight 
				ELSE  case when ( CountingItems.Count1Weight = isnull(StuffCodeEntity_c.Weight,0)  ) 
						or ( CountingItems.Count2Weight = isnull(StuffCodeEntity_c.Weight,0)  ) 
				then 	isnull(StuffCodeEntity_c.Weight,0)  else null  end  END) 
		ELSE null END AS DifferWeight , 

		CountingItems.StoreID, CountingItems.CountID

FROM            CountingItems INNER JOIN
                         StuffCoding ON CountingItems.StuffCode = StuffCoding.c_StuffCode INNER JOIN
                         Counting ON CountingItems.CountID = Counting.CountID LEFT OUTER JOIN
                         dbo.StuffCodeEntity(@YearIDFrom, @YearIDTo, @Date ) AS StuffCodeEntity_C ON CountingItems.StoreID = StuffCodeEntity_C.StoreID AND 
                         CountingItems.StuffCode = StuffCodeEntity_C.StuffCode  )

/*SELECT     CountingItems.StuffCode, StuffCoding.c_StuffName, CountingItems.StuffSize, CountingItems.StuffDiameter, 
                      CountingItems.StuffAlloy, CountingItems.StuffGrade, CountingItems.ControlCode, CountingItems.Count1Entity, 
                      CountingItems.Count1Weight, CountingItems.Count2Entity, CountingItems.Count2Weight, CountingItems.Count3Entity, 
                      CountingItems.Count3Weight, 
    --(CASE IsNull(CountingItems.Count2Entity,0) - IsNull(CountingItems.Count1Entity,0) WHEN 0 THEN IsNull(CountingItems.Count2Entity,0) ELSE IsNull(CountingItems.Count3Entity,0) 
    --                   END) AS DifferEntity, 
    --(CASE IsNull(CountingItems.Count2Weight,0) - IsNull(CountingItems.Count1Weight,0) WHEN 0 THEN IsNull(CountingItems.Count2Weight,0) ELSE IsNull(CountingItems.Count3Weight,0)
    --                   END) AS DifferWeight

CASE  Counting.CountingCalckind
WHEN 0 THEN 
    (CASE IsNull(CountingItems.Count2Entity,0) - IsNull(CountingItems.Count1Entity,0) 
	   WHEN 0 THEN IsNull(CountingItems.Count2Entity,0) ELSE IsNull(CountingItems.Count3Entity,0)  END) 
					   
WHEN 1 THEN 
    (CASE WHEN IsNull(CountingItems.Count2Entity,0)>0 THEN IsNull(CountingItems.Count2Entity,0) ELSE
       IsNull(CountingItems.Count1Entity,0) end)
ELSE 
   (CASE WHEN IsNull(CountingItems.Count3Entity,0)>0 THEN IsNull(CountingItems.Count3Entity,0) ELSE
   IsNull(CountingItems.Count2Entity,0) end)

END AS DifferEntity, 

CASE  Counting.CountingCalckind
WHEN 0 THEN 
