ELSE 
   (CASE WHEN IsNull(CountingItems.Count3Weight,0)>0 THEN IsNull(CountingItems.Count3Weight,0) ELSE
   IsNull(CountingItems.Count2Weight,0) end)

END  AS DifferWeight

					   
					   
					   , CountingItems.StoreID, CountingItems.CountID
