CREATE VIEW Vu_UseUnitName
AS
SELECT	distinct	UseUnits.UseUnitID, UseUnits.UseUnitName + 
			CASE WHEN isnull(UseUnits.CustID1,0) <> 0 THEN '>' + isnull(c1.CustFirstName,'')+' '+c1.CustName ELSE '' END + 
			CASE WHEN isnull(UseUnits.CustID2,0) <> 0 THEN '>' + isnull(c2.CustFirstName,'')+' '+c2.CustName ELSE '' END + 
			CASE WHEN isnull(UseUnits.CustID3,0) <> 0 THEN '>' + isnull(c2.CustFirstName,'')+' '+c3.CustName ELSE '' END + 
			CASE WHEN isnull(UseUnits.CustID4,0) <> 0 THEN '>' + isnull(c2.CustFirstName,'')+' '+c4.CustName ELSE '' END AS UseUnitName,
			UseUnits.IndexNum, UseUnits.Note, UseUnits.ProjectID, UseUnits.acc_TopicCode, UseUnits.acc_DetailCode, UseUnits.acc_CTopicCode, UseUnits.acc_CTopicCode2, 
            UseUnits.UseActive, UseUnits.YearID, UseUnits.acc_CTopicCode3, UseUnits.CustID1, UseUnits.CustID2, UseUnits.CustID3, UseUnits.CustID4

FROM		UseUnits
			LEFT OUTER JOIN Customers AS c1 ON UseUnits.CustID1 = c1.CustID 
			LEFT OUTER JOIN	Customers AS c2 ON UseUnits.CustID2 = c2.CustID 
			LEFT OUTER JOIN	Customers AS c3 ON UseUnits.CustID3 = c3.CustID 
			LEFT OUTER JOIN	Customers AS c4 ON UseUnits.CustID4 = c4.CustID
WHERE        (UseUnits.UseActive = 0)

