CREATE VIEW ReciptItemSum_Darayi
WITH
	SCHEMABINDING
AS
	SELECT Ri.ReciptID, Ri.ServerID, Ri.YearID,
		SUM ( case when ( T.CommissionActive = 2 and Ri.UnitCommission >0 ) then
    (Ri.InputEntity + Ri.OutputEntity ) * Ri.UnitCommission else
    CASE T.SellEffect WHEN 1 THEN 1 ELSE -1 END *(Ri.TotalOutputPrice + Ri.TotalInputPrice) end ) AS SumTotalOutputPrice
	, COUNT_BIG(*) as C
	FROM dbo.ReciptItems Ri INNER JOIN
		dbo.Recipts  R ON Ri.ReciptID = R.ReciptID AND Ri.ServerID = R.ServerID AND Ri.YearID = R.YearID INNER JOIN
		dbo.ReciptTypes1 T ON R.ReciptType = T.ReciptType

	GROUP BY Ri.ReciptID, Ri.ServerID, Ri.YearID
GO 
