CREATE VIEW ReciptItemSum
WITH
	SCHEMABINDING
AS
	SELECT T.YearID, T.ServerID, T.ReciptID,
		SUM(ISNULL(t.DeficitValue + t.DeficitValue2+ t.DeficitValue4 ,0)) AS DeficitValue,
		SUM(ISNULL( t.DeficitValue3,0)) AS DeficitValue3,
		SUM(ISNULL(t.InputEntity + t.OutputEntity,0)) AS Entity,
		SUM(ISNULL(t.InputWeight + t.OutputWeight,0)) AS Weight,
		SUM(ISNULL(t.TotalInputPrice + t.TotalOutputPrice,0)) AS Price,
		SUM(ISNULL(t.TotallSellPrice,0)) AS TotallSellPrice,
		SUM(ISNULL(t.TaxValue,0)) AS TaxValue,
		SUM(ISNULL(t.TotalStandardRate,0)) AS StandardRate, 
		SUM(ISNULL(t.Portage,0)) AS Portage, 
		SUM(ISNULL(t.UnitCommission,0)) AS UnitCommission,
		SUM(ISNULL(t.ArzAmount,0)) AS ArzAmount ,
		SUM(ISNULL(t.ArzRate,0)) AS ArzRate ,	 
		SUM(ISNULL(t.Article,0)) AS Article , 
		SUM(ISNULL(t.Wage,0))    AS Wage,
		SUM(ISNULL(t.Scoria,0))  AS Scoria,
		COUNT_BIG(*) as C

	FROM dbo.ReciptItems as T
	GROUP BY T.ReciptID, T.ServerID, T.YearID
GO 
