CREATE FUNCTION [dbo].[AutoUnitSellPrice2]
(
    @ReciptItem_ID decimal(26,0),
    @Kind tinyint = 0
)
RETURNS money
BEGIN

DECLARE @UnitSellPrice money
DECLARE @SellPrice money
DECLARE @BuyPrice money
DECLARE @StandardRate money
DECLARE @Total money
DECLARE @LowerLimit money  
DECLARE @Entity float
DECLARE @Weight float 
DECLARE @AutoPrice int
DECLARE @CustValuationType tinyint
DECLARE @EntityDisplayType tinyint
DECLARE @SellPrice1 money
DECLARE @SellPrice2 money
DECLARE @SellPrice3 money
DECLARE @SellPrice4 money
DECLARE @DiscountPercent float 
DECLARE @DiscountAmount float 
DECLARE @DiscountOne float 
DECLARE @TaxCo float

DECLARE @ReciptItemID int
DECLARE @ReciptID int
DECLARE @ServerID int
DECLARE @YearID int
DECLARE @b bit
DECLARE @ChaneAuto bit = 0

DECLARE @ChangeAidReciptDate bigint
--DECLARE @ReciptDate char(10)

SELECT 
    @ReciptItemID = ReciptItemID,
    @ReciptID = ReciptID,
    @ServerID = ServerID,
    @YearID = YearID
FROM ReciptItems
WHERE ID = @ReciptItem_ID


SELECT
    @ChangeAidReciptDate = ReciptTypes.ChangeAidReciptDate,
    @AutoPrice = ISNULL(ReciptTypes.AutoPrice,0)
FROM ReciptTypes
WHERE ReciptType IN
(
    SELECT ISNULL(ReciptTypes.CorrelateReciptType,0)
    FROM ReciptItems
    INNER JOIN Recipts 
        ON ReciptItems.ReciptID = Recipts.ReciptID
        AND ReciptItems.ServerID = Recipts.ServerID
        AND ReciptItems.YearID = Recipts.YearID
    INNER JOIN ReciptTypes 
        ON Recipts.ReciptType = ReciptTypes.ReciptType
    WHERE ReciptItems.ReciptItemID = @ReciptItemID
      AND ReciptItems.ReciptID = @ReciptID
      AND ReciptItems.ServerID = @ServerID
      AND ReciptItems.YearID = @YearID
)


SELECT
    @CustValuationType = ISNULL(Customers.ValuationType,0),
    @DiscountOne = ISNULL(DiscountOne,0),
    @b = ISNULL(ReciptTypes.RecuestActive,0) & 64--,
    --@ReciptDate = ReciptDate
    
    
FROM ReciptItems
INNER JOIN Recipts 
    ON ReciptItems.ReciptID = Recipts.ReciptID
    AND ReciptItems.ServerID = Recipts.ServerID
    AND ReciptItems.YearID = Recipts.YearID
LEFT JOIN Customers 
    ON Recipts.PersonID1 = Customers.CustID
INNER JOIN ReciptTypes 
    ON Recipts.ReciptType = ReciptTypes.ReciptType
WHERE ReciptItems.ReciptItemID = @ReciptItemID
  AND ReciptItems.ReciptID = @ReciptID
  AND ReciptItems.ServerID = @ServerID
  AND ReciptItems.YearID = @YearID


/* ----------- Price Source ----------- */

IF @AutoPrice IN (6,7,13,18)
BEGIN

    SELECT TOP 1
        @UnitSellPrice = A.Rate ,@SellPrice1 = A.Rate, @DiscountPercent = A.DiscountPercent ,@TaxCo = TaxCoA
    FROM Agreements A
    INNER JOIN ReciptItems Ri 
        ON A.StuffCode = Ri.StuffCode 
        AND A.YearID = Ri.YearID
    INNER JOIN Recipts R
        ON Ri.ReciptID = R.ReciptID
        AND Ri.ServerID = R.ServerID
        AND Ri.YearID = R.YearID
        AND A.PersonID1 = R.PersonID1
        AND A.SellsMethod = R.SellsMethod
    WHERE AgrState = 0
      AND Ri.ReciptItemID = @ReciptItemID
      AND Ri.ReciptID = @ReciptID
      AND Ri.ServerID = @ServerID
      AND Ri.YearID = @YearID
      AND AgreementsDate <=  case when  ((@ChangeAidReciptDate &   4096) <> 0)   then  R.AidDate else R.ReciptDate end
    ORDER BY AgreementsDate DESC , AgreementsID DESC

    if @UnitSellPrice is  null 
    begin
    set @ChaneAuto=1
    --set @UnitSellPrice =55555555
    end

END

    IF @AutoPrice = 5 or @ChaneAuto=1
    BEGIN

SELECT TOP 1 @SellPrice1=Mi.SellPrice1,
             @SellPrice2=Mi.SellPrice2,
             @SellPrice3=Mi.SellPrice3,
             @SellPrice4=Mi.SellPrice4,
             @DiscountPercent=isnull(Mi.DiscountPercent,0),
             @DiscountAmount=isnull(DiscountAmount,0),
			 @TaxCo=case when  isnull(Mi.MTaxCo,0)<>0 then Mi.MTaxCo else Ri.TaxCo end
           
FROM  Manifesto M INNER JOIN
	ManifestoItems Mi ON M.ManifestoID = Mi.ManifestoID INNER JOIN
	StuffCoding ON Mi.StuffCode = StuffCoding.c_StuffCode INNER JOIN
	Customers ON M.CustomerGrpIDFrom <= Customers.CustomerGrpID 
    AND M.CustomerGrpIDTo >= Customers.CustomerGrpID AND M.CustIDFrom <= Customers.CustID AND 
	M.CustIDTo >= Customers.CustID INNER JOIN
	ReciptItems Ri ON Mi.StuffCode = Ri.StuffCode INNER JOIN
	Recipts ON Ri.ReciptID = Recipts.ReciptID AND Ri.ServerID = Recipts.ServerID AND Ri.YearID = Recipts.YearID 
	AND M.ManifestoRunDate <=  case when  ((@ChangeAidReciptDate &   4096) <> 0)   then  Recipts.AidDate else Recipts.ReciptDate end
	AND M.SellsMethod = Recipts.SellsMethod AND (@b=1 OR M.SellsEmporium = Recipts.SellsEmporium) 
    AND Customers.CustID = Recipts.PersonID1
WHERE    (Ri.ReciptItemID = @ReciptItemID )  AND (Ri.ReciptID = @ReciptID ) AND (Ri.ServerID = @ServerID) 
AND (Ri.YearID = @YearID ) 
AND ISNULL(M.Active, 1) = 1 AND ISNULL(Mi.Active, 1) = 1
ORDER BY M.ManifestoRunDate DESC

        

    END
IF @AutoPrice IN (0,1,2,3,4,8,9,10,11,12,14,15,16,17)
    BEGIN
        SELECT
            @SellPrice1 = Sc.SellPrice1,
            @SellPrice2 = Sc.SellPrice2,
            @SellPrice3 = Sc.SellPrice3,
            @SellPrice4 = Sc.SellPrice4,
            @DiscountPercent = Ri.WaterCo,
            @DiscountAmount = Ri.DeficitValue,
            @TaxCo = Ri.TaxCo
        FROM ReciptItems Ri
        INNER JOIN StuffCoding Sc
            ON Ri.StuffCode = Sc.c_StuffCode
        WHERE Ri.ReciptItemID = @ReciptItemID
          AND Ri.ReciptID = @ReciptID
          AND Ri.ServerID = @ServerID
          AND Ri.YearID = @YearID

    END

--END


/* ----------- Price Selection ----------- */

SET @SellPrice =
CASE @CustValuationType
    WHEN 0 THEN @SellPrice1
    WHEN 1 THEN @SellPrice2
    WHEN 2 THEN @SellPrice3
    WHEN 3 THEN @SellPrice4
    ELSE 0
END


SELECT
    @BuyPrice = Sc.BuyPrice,
    @StandardRate = Sc.StandardRate
FROM ReciptItems Ri
INNER JOIN StuffCoding Sc
    ON Ri.StuffCode = Sc.c_StuffCode
WHERE Ri.ReciptItemID = @ReciptItemID
  AND Ri.ReciptID = @ReciptID
  AND Ri.ServerID = @ServerID
  AND Ri.YearID = @YearID


SET @UnitSellPrice =
CASE @AutoPrice
    WHEN 2 THEN @SellPrice
    WHEN 3 THEN @BuyPrice
    WHEN 4 THEN @StandardRate
    WHEN 5 THEN @SellPrice
    WHEN 6 THEN @UnitSellPrice
    WHEN 7 THEN @SellPrice1
    ELSE 0
END


SELECT 
    @EntityDisplayType = EntityDisplayType,
    @LowerLimit = EntityOutputLowerLimit
FROM Config


SELECT
    @Entity = InputEntity + OutputEntity,
    @Weight = InputWeight + OutputWeight
FROM ReciptItems
WHERE ReciptItemID = @ReciptItemID
  AND ReciptID = @ReciptID
  AND ServerID = @ServerID
  AND YearID = @YearID


SELECT @Total =
CASE @EntityDisplayType
    WHEN 0 THEN @Entity * @UnitSellPrice
    WHEN 1 THEN @Weight * @UnitSellPrice
    WHEN 2 THEN CASE WHEN @UnitSellPrice >= @LowerLimit THEN @Weight*@UnitSellPrice ELSE @Entity*@UnitSellPrice END
    WHEN 3 THEN CASE WHEN @UnitSellPrice >= @LowerLimit THEN @Entity*@UnitSellPrice ELSE @Weight*@UnitSellPrice END
END


IF @AutoPrice not IN (6,7,13,18)
IF @DiscountOne <> 0
    SET @DiscountPercent = @DiscountOne


SET @UnitSellPrice =
CASE @Kind
    WHEN 0 THEN @UnitSellPrice
    WHEN 1 THEN @Total
    WHEN 2 THEN @DiscountPercent
    WHEN 3 THEN @DiscountAmount
    WHEN 4 THEN @TaxCo
    ELSE @UnitSellPrice
END


RETURN ISNULL(@UnitSellPrice,0)

END
GO 
