CREATE  FUNCTION dbo.AutoUnitSellPrice (@ReciptItemID decimal(26,0) ,@Kind  bit =0 ,@ServerID int=0, @YearID int=88)
RETURNS money                                                 /* @Kind=0=UnitSellPrice @Kind=1=Total...Price */    
begin
  DECLARE @UnitSellPrice     money
  DECLARE @SellPrice         money
  DECLARE @BuyPrice          money
  DECLARE @StandardRate      money
  DECLARE @Total             money
  DECLARE @LowerLimit        money  
  DECLARE @Entity            float
  DECLARE @Weight            float 
  DECLARE @AutoPrice         int
  DECLARE @CustValuationType tinyint
  DECLARE @EntityDisplayType tinyint
  DECLARE @b bit


  SELECT @b=ISNULL(ReciptTypes.RecuestActive,0)& 64
                    FROM ReciptItems INNER JOIN Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
                    ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType 
                    WHERE (ReciptItems.ReciptItemID = @ReciptItemID AND ReciptItems.ServerID= @ServerID AND ReciptItems.YearID= @YearID)

  SET @AutoPrice=(SELECT  ISNULL(ReciptTypes.AutoPrice,0)AS AutoPrice FROM ReciptTypes WHERE ReciptType in ( SELECT ISNULL(ReciptTypes.CorrelateReciptType,0)AS CorrelateReciptType
                    FROM ReciptItems INNER JOIN Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
                    ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType 
                    WHERE (ReciptItems.ReciptItemID = @ReciptItemID AND ReciptItems.ServerID= @ServerID AND ReciptItems.YearID= @YearID)))
  SET @CustValuationType=(SELECT     ISNULL(Customers.ValuationType, 0) AS ValuationType
                          FROM ReciptItems INNER JOIN Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID LEFT OUTER JOIN
                          Customers ON Recipts.PersonID1 = Customers.CustID
                          WHERE (ReciptItems.ReciptItemID = @ReciptItemID AND ReciptItems.ServerID= @ServerID AND ReciptItems.YearID= @YearID))

 if @AutoPrice<>5 
		 SET @SellPrice=(SELECT (CASE @CustValuationType 
							 WHEN 0 THEN (SELECT StuffCoding.SellPrice1 FROM ReciptItems INNER JOIN
											StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode
											WHERE (ReciptItems.ReciptItemID = @ReciptItemID AND ReciptItems.ServerID= @ServerID AND ReciptItems.YearID= @YearID))
							 WHEN 1 THEN (SELECT StuffCoding.SellPrice2 FROM ReciptItems INNER JOIN
											StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode
											WHERE (ReciptItems.ReciptItemID = @ReciptItemID AND ReciptItems.ServerID= @ServerID AND ReciptItems.YearID= @YearID))
							 WHEN 2 THEN (SELECT StuffCoding.SellPrice3 FROM ReciptItems INNER JOIN
											StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode
											WHERE (ReciptItems.ReciptItemID = @ReciptItemID AND ReciptItems.ServerID= @ServerID AND ReciptItems.YearID= @YearID))
							 WHEN 3 THEN (SELECT StuffCoding.SellPrice4 FROM ReciptItems INNER JOIN
											StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode
											WHERE (ReciptItems.ReciptItemID = @ReciptItemID AND ReciptItems.ServerID= @ServerID AND ReciptItems.YearID= @YearID))

							 ELSE 0     
							 END ))
else SET @SellPrice=(SELECT (CASE @CustValuationType 
							 WHEN 0 THEN (SELECT TOP 1 ManifestoItems.SellPrice1
           --                                 FROM         Manifesto INNER JOIN
											--ManifestoItems ON Manifesto.ManifestoID = ManifestoItems.ManifestoID INNER JOIN
											--ReciptItems ON ManifestoItems.StuffCode = ReciptItems.StuffCode INNER JOIN
											--Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID AND Manifesto.ManifestoRunDate <= Recipts.ReciptDate
											--WHERE (ReciptItems.ReciptItemID = @ReciptItemID AND ReciptItems.ServerID= @ServerID AND ReciptItems.YearID= @YearID)
											FROM            Manifesto INNER JOIN
												ManifestoItems ON Manifesto.ManifestoID = ManifestoItems.ManifestoID INNER JOIN
												StuffCoding ON ManifestoItems.StuffCode = StuffCoding.c_StuffCode INNER JOIN
												Customers ON Manifesto.CustomerGrpIDFrom <= Customers.CustomerGrpID AND Manifesto.CustomerGrpIDTo >= Customers.CustomerGrpID AND Manifesto.CustIDFrom <= Customers.CustID AND 
												Manifesto.CustIDTo >= Customers.CustID INNER JOIN
												ReciptItems ON ManifestoItems.StuffCode = ReciptItems.StuffCode INNER JOIN
												Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID AND Manifesto.ManifestoRunDate <= Recipts.ReciptDate AND 
												Manifesto.SellsMethod = Recipts.SellsMethod AND (@b=1 or Manifesto.SellsEmporium = Recipts.SellsEmporium) AND Customers.CustID = Recipts.PersonID1
											WHERE        (ReciptItems.ReciptItemID = @ReciptItemID) AND (ReciptItems.ServerID = @ServerID) AND (ReciptItems.YearID = @YearID)
                                            AND ISNULL(Manifesto.Active, 1) = 1 AND ISNULL(ManifestoItems.Active, 1) = 1
											ORDER BY Manifesto.ManifestoRunDate DESC)
							 WHEN 1 THEN (SELECT TOP 1 ManifestoItems.SellPrice2
           --                                 FROM         Manifesto INNER JOIN
											--ManifestoItems ON Manifesto.ManifestoID = ManifestoItems.ManifestoID INNER JOIN
											--ReciptItems ON ManifestoItems.StuffCode = ReciptItems.StuffCode INNER JOIN
											--Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID AND Manifesto.ManifestoRunDate <= Recipts.ReciptDate
											--WHERE (ReciptItems.ReciptItemID = @ReciptItemID AND ReciptItems.ServerID= @ServerID AND ReciptItems.YearID= @YearID)
											FROM            Manifesto INNER JOIN
												ManifestoItems ON Manifesto.ManifestoID = ManifestoItems.ManifestoID INNER JOIN
												StuffCoding ON ManifestoItems.StuffCode = StuffCoding.c_StuffCode INNER JOIN
												Customers ON Manifesto.CustomerGrpIDFrom <= Customers.CustomerGrpID AND Manifesto.CustomerGrpIDTo >= Customers.CustomerGrpID AND Manifesto.CustIDFrom <= Customers.CustID AND 
												Manifesto.CustIDTo >= Customers.CustID INNER JOIN
												ReciptItems ON ManifestoItems.StuffCode = ReciptItems.StuffCode INNER JOIN
												Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID AND Manifesto.ManifestoRunDate <= Recipts.ReciptDate AND 
												Manifesto.SellsMethod = Recipts.SellsMethod AND (@b=1 or Manifesto.SellsEmporium = Recipts.SellsEmporium) AND Customers.CustID = Recipts.PersonID1
											WHERE        (ReciptItems.ReciptItemID = @ReciptItemID) AND (ReciptItems.ServerID = @ServerID) AND (ReciptItems.YearID = @YearID)
                                            AND ISNULL(Manifesto.Active, 1) = 1 AND ISNULL(ManifestoItems.Active, 1) = 1
											ORDER BY Manifesto.ManifestoRunDate DESC)
							 WHEN 2 THEN (SELECT TOP 1 ManifestoItems.SellPrice3
           --                                 FROM         Manifesto INNER JOIN
											--ManifestoItems ON Manifesto.ManifestoID = ManifestoItems.ManifestoID INNER JOIN
											--ReciptItems ON ManifestoItems.StuffCode = ReciptItems.StuffCode INNER JOIN
											--Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID AND Manifesto.ManifestoRunDate <= Recipts.ReciptDate
											--WHERE (ReciptItems.ReciptItemID = @ReciptItemID AND ReciptItems.ServerID= @ServerID AND ReciptItems.YearID= @YearID)
											FROM            Manifesto INNER JOIN
												ManifestoItems ON Manifesto.ManifestoID = ManifestoItems.ManifestoID INNER JOIN
												StuffCoding ON ManifestoItems.StuffCode = StuffCoding.c_StuffCode INNER JOIN
												Customers ON Manifesto.CustomerGrpIDFrom <= Customers.CustomerGrpID AND Manifesto.CustomerGrpIDTo >= Customers.CustomerGrpID AND Manifesto.CustIDFrom <= Customers.CustID AND 
												Manifesto.CustIDTo >= Customers.CustID INNER JOIN
												ReciptItems ON ManifestoItems.StuffCode = ReciptItems.StuffCode INNER JOIN
												Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID AND Manifesto.ManifestoRunDate <= Recipts.ReciptDate AND 
												Manifesto.SellsMethod = Recipts.SellsMethod AND (@b=1 or Manifesto.SellsEmporium = Recipts.SellsEmporium) AND Customers.CustID = Recipts.PersonID1
											WHERE        (ReciptItems.ReciptItemID = @ReciptItemID) AND (ReciptItems.ServerID = @ServerID) AND (ReciptItems.YearID = @YearID)
                                            AND ISNULL(Manifesto.Active, 1) = 1 AND ISNULL(ManifestoItems.Active, 1) = 1
											ORDER BY Manifesto.ManifestoRunDate DESC)
							 WHEN 3 THEN (SELECT TOP 1 ManifestoItems.SellPrice4
           --                                 FROM         Manifesto INNER JOIN
											--ManifestoItems ON Manifesto.ManifestoID = ManifestoItems.ManifestoID INNER JOIN
											--ReciptItems ON ManifestoItems.StuffCode = ReciptItems.StuffCode INNER JOIN
											--Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID AND Manifesto.ManifestoRunDate <= Recipts.ReciptDate
											--WHERE (ReciptItems.ReciptItemID = @ReciptItemID AND ReciptItems.ServerID= @ServerID AND ReciptItems.YearID= @YearID)
											FROM            Manifesto INNER JOIN
												ManifestoItems ON Manifesto.ManifestoID = ManifestoItems.ManifestoID INNER JOIN
												StuffCoding ON ManifestoItems.StuffCode = StuffCoding.c_StuffCode INNER JOIN
												Customers ON Manifesto.CustomerGrpIDFrom <= Customers.CustomerGrpID AND Manifesto.CustomerGrpIDTo >= Customers.CustomerGrpID AND Manifesto.CustIDFrom <= Customers.CustID AND 
												Manifesto.CustIDTo >= Customers.CustID INNER JOIN
												ReciptItems ON ManifestoItems.StuffCode = ReciptItems.StuffCode INNER JOIN
												Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID AND Manifesto.ManifestoRunDate <= Recipts.ReciptDate AND 
												Manifesto.SellsMethod = Recipts.SellsMethod AND (@b=1 or Manifesto.SellsEmporium = Recipts.SellsEmporium) AND Customers.CustID = Recipts.PersonID1
											WHERE        (ReciptItems.ReciptItemID = @ReciptItemID) AND (ReciptItems.ServerID = @ServerID) AND (ReciptItems.YearID = @YearID)
                                            AND ISNULL(Manifesto.Active, 1) = 1 AND ISNULL(ManifestoItems.Active, 1) = 1
											ORDER BY Manifesto.ManifestoRunDate DESC)

							 ELSE 0     
							 END ))




SET @BuyPrice = (SELECT StuffCoding.BuyPrice FROM ReciptItems INNER JOIN
                                    StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode
                                    WHERE (ReciptItems.ReciptItemID = @ReciptItemID AND ReciptItems.ServerID= @ServerID AND ReciptItems.YearID= @YearID))
  
SET @StandardRate = (SELECT StuffCoding.StandardRate FROM ReciptItems INNER JOIN
                                    StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode
                                    WHERE (ReciptItems.ReciptItemID = @ReciptItemID AND ReciptItems.ServerID= @ServerID AND ReciptItems.YearID= @YearID))

SET @UnitSellPrice=(SELECT (CASE @AutoPrice 
                     WHEN 2 THEN @SellPrice
                     WHEN 3 THEN @BuyPrice
                     WHEN 4 THEN @StandardRate
                     WHEN 5 THEN @SellPrice
                     ELSE 0  END ))

SET @EntityDisplayType=(Select EntityDisplayType from Config)
SET @LowerLimit=  (Select EntityOutputLowerLimit from Config)

SET @Entity = (SELECT InputEntity+OutputEntity AS Entity FROM ReciptItems WHERE (ReciptItems.ReciptItemID= @ReciptItemID AND ReciptItems.ServerID= @ServerID AND ReciptItems.YearID= @YearID))
SET @Weight = (SELECT InputWeight+OutputWeight AS Weight FROM ReciptItems WHERE (ReciptItems.ReciptItemID= @ReciptItemID AND ReciptItems.ServerID= @ServerID AND ReciptItems.YearID= @YearID))
SET @Total=(SELECT (CASE @EntityDisplayType 
                     WHEN 0 THEN @Entity*@UnitSellPrice
                     WHEN 1 THEN @Weight*@UnitSellPrice
                     WHEN 2 THEN (CASE WHEN @UnitSellPrice>= @LowerLimit then @Weight*@UnitSellPrice
                                                                        else @Entity*@UnitSellPrice end)
                     WHEN 3 THEN (CASE WHEN @UnitSellPrice>= @LowerLimit then @Entity*@UnitSellPrice
                                                                        else @Weight*@UnitSellPrice end)
                     END ))
if  @Kind<>0  set @UnitSellPrice= @Total
RETURN(ISNULL( @UnitSellPrice,0))

end

