CREATE  FUNCTION [dbo].[CalcTotallSellPric](@TotallPrice money ,@WaterCo float ,@TaxCo float ,@CalcFiled  varchar(50) ='TotallSellPrice' )
RETURNS money                                            
begin
	DECLARE @TotallSellPrice         money
	--DECLARE @TotallPrice         money
	DECLARE @CommissionPrice         money=0
	DECLARE @CalcTaxValue         money
	DECLARE @DeficitValue    float 
  	--SELECT @CommissionPrice=CommissionPrice ,@TotallPrice = TotalInputPrice + TotalOutputPrice
	--FROM ReciptItems 
	--WHERE (ID = @ReciptItem_ID)
	set @DeficitValue = floor(@TotallPrice * @WaterCo / 100)
	if @CalcFiled = 'DeficitValue'
	  RETURN(@DeficitValue)

	set @CalcTaxValue = @TotallPrice - @DeficitValue 
	set       @CalcTaxValue = floor( @CalcTaxValue * @TaxCo / 100 )

	if @CalcFiled = 'TaxValue'
	  RETURN(@CalcTaxValue)

     set @TotallSellPrice = floor(@TotallPrice + @CalcTaxValue -@DeficitValue + @CommissionPrice);	
	if @CalcFiled = 'TotallSellPrice'
	  RETURN(ISNULL( @TotallSellPrice,0))

	RETURN(0.00000000001)



END
