CREATE PROCEDURE NewReciptsCorrelateDeficits( @OldReciptID int,@NewReciptID int, @ServerID int=0, @YearID int=88)as
begin
declare @NewServerID int
declare @CorrelateServerID int

SELECT @CorrelateServerID=ReciptTypes.ChangeAidReciptDate FROM Recipts INNER JOIN
      ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
      WHERE (ReciptID = @OldReciptID) AND (ServerID= @ServerID) AND (YearID= @YearID)

   if (((@CorrelateServerID & 2)) <> 0) 
     select  @NewServerID = ServerID from Config
    else
   set   @NewServerID = @ServerID



if ((SELECT ReciptTypes.StepCorrelate FROM Recipts INNER JOIN
      ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
      WHERE (ReciptID = @OldReciptID) AND (ServerID= @ServerID) AND (YearID= @YearID) )<>1)
begin
	INSERT INTO ReciptsDeficits
	   (ReciptDeficitID, ReciptID, DeficitID, DeficitAdd, DeficitDec, DeficitNote, YearID, ServerID, 
	   ArzAmount, DeficitCo, TopicCode, DetailCode, CTopicCode, CTopicCode2, CTopicCode3, ArzTypeID
)
	SELECT   ReciptDeficitID - 1  , 
		 @NewReciptID, DeficitID, DeficitAdd, DeficitDec, DeficitNote, YearID, @NewServerID, 
		 ArzAmount, DeficitCo, TopicCode, DetailCode, CTopicCode, CTopicCode2, CTopicCode3, ArzTypeID

	FROM         ReciptsDeficits
	WHERE ((ReciptID = @OldReciptID) AND (ServerID= @ServerID) AND (YearID= @YearID))

end
else      
begin

    --declare   @minReciptDeficitID int
    declare   @ReciptDeficitID int
	--SET @minReciptDeficitID=(SELECT MIN(ReciptDeficitID)FROM ReciptsDeficits WHERE (ReciptID = @OldReciptID) AND (ServerID= @ServerID) AND (YearID= @YearID))
	SET @ReciptDeficitID=   (SELECT isnull(MAX(ReciptDeficitID),0)+1  FROM ReciptsDeficits WHERE (ServerID= @ServerID) AND (YearID= @YearID))
	INSERT INTO ReciptsDeficits
	   (ReciptDeficitID, ReciptID, DeficitID, DeficitAdd, DeficitDec, DeficitNote, YearID, ServerID, 
	   ArzAmount, DeficitCo, TopicCode, DetailCode, CTopicCode, CTopicCode2, CTopicCode3, ArzTypeID
)
	SELECT   @ReciptDeficitID+ ROW_NUMBER() OVER(ORDER BY ReciptDeficitID ASC)  , 
		 @NewReciptID, DeficitID, DeficitAdd, DeficitDec, DeficitNote, YearID, @NewServerID, 
		 ArzAmount, DeficitCo, TopicCode, DetailCode, CTopicCode, CTopicCode2, CTopicCode3, ArzTypeID

	FROM         ReciptsDeficits
	WHERE ((ReciptID = @OldReciptID) AND (ServerID= @ServerID) AND (YearID= @YearID))

end
      


end
