CREATE PROCEDURE dbo.NewReciptsCorrelateKind8 @NewReciptID int, @ReciptID int=0, @YearID int=88,  @ServerID int  as
begin
SET NOCOUNT ON;
DECLARE @ReciptItemID INT
SELECT @ReciptItemID=MAX(ReciptItemID)  FROM ReciptItems WHERE (YearID = @YearID) AND (ServerID = @ServerID)
INSERT INTO ReciptItems
  (ReciptItemID,ReciptID,ServerID, YearID, StuffCode , OutputEntity, OutputWeight, PersonID1  )

SELECT      ROW_NUMBER() OVER(ORDER BY ProductCode ASC)+@ReciptItemID AS ReciptItemID
    , @NewReciptID AS ReciptID,@ServerID ServerID,@YearID YearID, ProductCode AS StuffCode,  1 AS OutputEntity,  1 AS OutputWeight,0  PersonID1
FROM            ReciptItems
where   (ReciptID = @ReciptID) AND (YearID = @YearID) AND (ServerID = @ServerID)
GROUP BY  ProductCode	

END

