CREATE PROCEDURE NewReciptsCorrelateChkEntity @OldID bigint,  @Description varchar(2000) OUTPUT as
DECLARE @ChangeAidReciptDate bigint
DECLARE @CorrelateReciptType int
BEGIN
SET NOCOUNT ON;
DECLARE @ReciptDate char(10)
DECLARE @StoreID   int
DECLARE @YearID int
DECLARE @EntityDisplayType int
SELECT @ReciptDate =ReciptDate , @StoreID=StoreID ,@YearID=YearID  FROM Recipts WHERE (ID = @OldID)
DECLARE @EntityCaption   varchar(150)
DECLARE @WeightCaption   varchar(150)
select @EntityCaption=EntityCaption,@WeightCaption = WeightCaption,@Description='',@EntityDisplayType=EntityDisplayType from Config 

SELECT @Description=@Description+case when isnull( Rs.Entity ,0)-Cur.Entity<0 then 'موجودی کالای' +ltrim(Cur.StuffCode) +'> '+
                    case when @EntityDisplayType <>1 then @EntityCaption+ isnull(ltrim( Rs.Entity  ),'0') else '' end +
					case when @EntityDisplayType <>0 then @WeightCaption+isnull(ltrim(Rs.Weight) ,'0')  else '' end 
					else '' end
--,@AllEntity=@AllEntity+case when isnull( Rs.Entity ,0)-Cur.Entity>=0 then 1 else 0 end  ,@CountStuff =@CountStuff+1
--,SUM(TotalInputPrice -TotalOutputPrice) AS Price-- ,Cur.Entity ,Cur.Weight   ,SUM(InputEntity - OutputEntity )-Cur.Entity ReEntity, SUM(InputWeight - OutputWeight )-Cur.Weight ReWeight
 FROM (
 SELECT        Ri.StuffCode, sum(InputEntity + OutputEntity ) AS Entity,sum(InputWeight + OutputWeight ) AS Weight
FROM    Recipts AS R INNER JOIN
        ReciptItems AS Ri ON R.ReciptID = Ri.ReciptID AND R.ServerID = Ri.ServerID AND R.YearID = Ri.YearID
WHERE        (R.ID = @OldID)
 GROUP BY StuffCode
 ) AS Cur 
 left outer JOIN
  (SELECT StuffCode,SUM(InputEntity - OutputEntity ) Entity,SUM(InputWeight - OutputWeight )Weight from
  ReciptItems_Stock  

WHERE ((ReciptDate <= @ReciptDate)  AND (StoreID = @StoreID) AND (EffectType in(2,4,6,7)     )
AND(ReciptState < 3) AND YearID = @YearID )
 GROUP BY StuffCode
)Rs  on Cur.StuffCode = Rs.StuffCode 


 END
