CREATE PROCEDURE NewReciptsCorrelate @OldID bigint,@FirstUser varchar(100),  @ID bigint OUTPUT as
DECLARE @ReciptNumber float
DECLARE @ReciptItemID int
DECLARE @ReciptType int
DECLARE @CorrelateKind int
DECLARE @InEffectType int
DECLARE @OutEffectType int
--DECLARE @MINItemsID int
DECLARE @COUNTReciptID int
DECLARE @Factor int
DECLARE @ChangeAidReciptDate bigint
DECLARE @NewStoreID int
DECLARE @NewStoreID2 int
DECLARE @StepCorrelate int
DECLARE @CorrelateReciptType int


begin
set nocount on;
	--declare @trancount int;
	--set @trancount = @@trancount;
	--begin try
	--	if @trancount = 0
	--		begin transaction NewRecipt
	--	else
