DECLARE @ConfigSettings bigint
SELECT  @ConfigSettings = ConfigSettings FROM Config

declare @NewServerID int
declare @CorrelateServerID int
--set @ID=0
declare @OldReciptID int, @ServerID int, @YearID int,  @ReciptID int

SELECT    @OldReciptID= Recipts.ReciptID ,  @ServerID= Recipts.ServerID ,  @YearID= Recipts.YearID 
 FROM Recipts   WHERE (Recipts.ID= @OldID) 

declare  @PriceCo float
declare  @Correlate4EditActive int
declare  @CorrelateReciptNumberKind int

SELECT  @CorrelateReciptNumberKind=CorrelateReciptNumberKind, @CorrelateReciptType= ReciptTypes.CorrelateReciptType ,@CorrelateServerID=ReciptTypes.ChangeAidReciptDate,
		@PriceCo=ReciptTypes.PriceCo, @Correlate4EditActive = Correlate4EditActive,
		@ChangeAidReciptDate=ReciptTypes.ChangeAidReciptDate
	FROM ReciptTypes INNER JOIN Recipts ON ReciptTypes.ReciptType = Recipts.ReciptType
  --WHERE (Recipts.ReciptID= @OldReciptID) AND (Recipts.ServerID= @ServerID) AND (Recipts.YearID= @YearID)
   WHERE (Recipts.ID= @OldID) 

   if (((@CorrelateServerID & 2)) <> 0) 
   begin
     select  @NewServerID = ServerID from Config
     SET @COUNTReciptID=(SELECT COUNT(*)FROM Recipts 
                    WHERE (ParentReciptID= @OldReciptID) AND (ServerID in(@NewServerID)) AND (YearID= @YearID)
						   AND (ReciptType = @CorrelateReciptType) )

   end
    else
   begin
   set   @NewServerID = @ServerID
       SET @COUNTReciptID=(SELECT COUNT(*)FROM Recipts 
                    WHERE (ParentReciptID= @OldReciptID) AND (ServerID= @ServerID) AND (YearID= @YearID)
						   AND (ReciptType = @CorrelateReciptType) )

   end

if @Correlate4EditActive=6
begin
DELETE FROM ReciptItems
FROM            Recipts INNER JOIN
                         ReciptItems ON Recipts.ReciptID = ReciptItems.ReciptID AND Recipts.ServerID = ReciptItems.ServerID
						 AND Recipts.YearID = ReciptItems.YearID
                    WHERE (ParentReciptID= @OldReciptID) AND (ReciptItems.ServerID= @ServerID) AND (ReciptItems.YearID= @YearID)
						   AND (ReciptType = @CorrelateReciptType) 
end

--SET @COUNTReciptID=(SELECT COUNT(*)FROM Recipts 
--                    WHERE   ( ReciptID IN(SELECT ParentReciptID FROM Recipts 
--                           WHERE (ReciptID= @OldReciptID) AND (ServerID= @ServerID) AND (YearID= @YearID)
--						   AND (ReciptType = @CorrelateReciptType)
--						   ))
--                           AND (ServerID= @ServerID) AND (YearID= @YearID) 
						   
--						   AND ( ParentReciptID= @OldReciptID)
						   
--						    )



if @COUNTReciptID>0  and @Correlate4EditActive<>6
begin
  --raiserror('براي اين فرم فرم مرتبط ثبت شده',16,1)
  --commit TRANSACTION NewRecipt;
  RETURN (0)
end 



if ((@ChangeAidReciptDate &   8) = 0) 
begin
	if (SELECT COUNT(*) FROM Util.CodesInProcess)>0  
	begin
	  --commit TRANSACTION NewRecipt;
	  raiserror('كليه كاربران از سيستم خارج شوندو دوباره سعي كنيد',16,1)
	  RETURN (0)
	end 
end




SET @StepCorrelate=(SELECT ReciptTypes.StepCorrelate FROM Recipts INNER JOIN
      ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
     -- WHERE (ReciptID = @OldReciptID) AND (ServerID= @ServerID) AND (YearID= @YearID) )
	    WHERE (Recipts.ID= @OldID) )

if (@StepCorrelate<>1)
  SET     @ReciptID= @OldReciptID - 1
else
     if (((@CorrelateServerID & 2)) <> 0) 
   begin
      SET     @ReciptID=(SELECT MAX(ReciptID)+1 FROM Recipts WHERE (ServerID= @NewServerID) AND (YearID= @YearID))
   end
    else
   begin
      SET     @ReciptID=(SELECT MAX(ReciptID)+1 FROM Recipts WHERE (ServerID= @ServerID) AND (YearID= @YearID))
   end

if @ID<>0 set  @ReciptID= @ID
  

/*شماره فرم جاري
شماره جديد با توجه به فرم مرتبط
شماره فرم توزین به فرم مرتبط انتقال داد شود
شماره جديد با توجه به فرم مرتبط و سال مربوط
*/
if @CorrelateReciptNumberKind = 1
SET     @ReciptNumber=(SELECT ISNULL(max(ReciptNumber),0)+1 FROM Recipts 
    WHERE  (ReciptType = @CorrelateReciptType) AND (ServerID= @ServerID) AND (YearID= @YearID))
	else
SET     @ReciptNumber=(SELECT ReciptNumber FROM Recipts 
    WHERE (ReciptID = @OldReciptID)AND (ServerID= @ServerID) AND (YearID= @YearID))


SELECT @NewStoreID2=StoreID,@NewStoreID=StoreID2 FROM Recipts
                  WHERE (ReciptID = @OldReciptID)AND (ServerID= @ServerID) AND (YearID= @YearID)
                  
if @NewStoreID=0 
begin                   
set @NewStoreID= @NewStoreID2
set @NewStoreID2=0
end

SET     @ReciptType=(SELECT     ReciptTypes.CorrelateReciptType
                     FROM         Recipts INNER JOIN  ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
                     WHERE (Recipts.ReciptID = @OldReciptID)AND (ServerID= @ServerID) AND (YearID= @YearID))

SET     @CorrelateKind=(SELECT     ReciptTypes.CorrelateKind
                     FROM         Recipts INNER JOIN  ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
                     WHERE (Recipts.ReciptID = @OldReciptID)AND (ServerID= @ServerID) AND (YearID= @YearID))
if @CorrelateKind=0  
begin
  RETURN (0)
  --commit TRANSACTION NewRecipt;
end



--0 ندارد 1 ثبت در وارده‏ها با مبلغ 3- ثبت در وارده‏ها بدون مبلغ 4  ثبت در صادره‏ها با مبلغ5 ثبت در صادره‏ها بدون مبلغ
--SET     @InEffectType=(SELECT     ReciptTypes.EffectType
--                     FROM         Recipts INNER JOIN  ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
--                     WHERE (Recipts.ReciptID = @OldReciptID))

IF (@CorrelateKind>2) BEGIN   SET     @InEffectType=0  SET     @OutEffectType=1 end
  else               BEGIN   SET     @InEffectType=1  SET     @OutEffectType=0 end

set @Factor=(SELECT
case @CorrelateKind 
         WHEN 1 THEN 1
         WHEN 2 THEN 0
         WHEN 3 THEN 1
         WHEN 4 THEN 0
         WHEN 5 THEN 1
         WHEN 6 THEN 1
         WHEN 7 THEN 0
         WHEN 8 THEN 1
      END)

DECLARE @FactorDeficitValue int
SET @FactorDeficitValue=(SELECT
case @CorrelateKind 
         WHEN 6 THEN 0
		        ELSE 1
      END)

declare   @Settings bigint
declare   @ShowNotEntityOnSearch bigint
declare   @ReciptStatecreatedForm tinyint


SELECT    @ChangeAidReciptDate= ReciptTypes.ChangeAidReciptDate , @ShowNotEntityOnSearch= ReciptTypes.ShowNotEntityOnSearch ,
          @Settings=ReciptTypes.Settings,@ReciptStatecreatedForm=ReciptStatecreatedForm
                     FROM         Recipts INNER JOIN  ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
                     WHERE (Recipts.ReciptID = @OldReciptID)AND (ServerID= @ServerID) AND (YearID= @YearID)

declare   @Query varchar(8000)
--if (@ChangeAidReciptDate>0)
  if ((@ChangeAidReciptDate &   1) <> 0) 
 set @Query='AidDate,ReciptDate,'
  else  
      begin
        if (@ShowNotEntityOnSearch &  32 <> 0) 
         set @Query=''''+RIGHT( dbo.MiladiToShamsi(GETDATE()),10) + ''' AS ReciptDate,AidDate,'
        else
         set @Query='ReciptDate,AidDate,'
      end


declare   @QueryAidNumber varchar(800)
        if (@Settings &  8 <> 0) 
         set @QueryAidNumber=',NULL as AidNumber'
        else
         set @QueryAidNumber=',AidNumber'

declare   @QryReciptState varchar(100)
        if (@ReciptStatecreatedForm = 0 ) 
         set @QryReciptState=',ReciptState '
        else
         set @QryReciptState=','+STR(@ReciptStatecreatedForm-1)+' AS ReciptState'

if @Correlate4EditActive<>6
begin
set @Query='INSERT INTO Recipts
  (ReciptID, StoreID, ReciptNumber, ParentReciptID, ModifyDate,  PersonID1, PersonID2,PersonID3,PersonID4,PersonID5, ReciptType, 
  SecondType, ServiceValue,ReciptValue, ReciptDate, AidDate,TotalValue, AddDecValue, ReciptNote, OperatorID, ReciptState, 
  UseUnitID, [ExpireDate], ProjectID, BudgetID, AidNumber, ReciptStartDate, ReciptEndDate,UseOtherID,StoreID2
  , TruckNumber, MachineNo, MachineName, ArzTypeID, RialsEqual, ReciptsRow, SellsMethod, SellsEmporium, 
  MasirID, DeliveryID, PersonID2Bed, RelatedID,  CostDownSave, ServerID, YearID
  , DefaultDate, InsertDate, MachineInfo, InsertTime, EditTime, UserRegistrationDoc, DefaultDuration, 
  CalcGiftItems, ReciptDateMiladi, MachineFullWeight, MachineWeight, CalcCostStorage, PortageBedbes , ReciptNote2, PO, ReciptNumberFormer , FirstUser )
SELECT '+STR(@ReciptID)+', '+STR(@NewStoreID)+', '+STR(@ReciptNumber)+', '+STR(@OldReciptID)+', 
 GETDATE(), PersonID1, PersonID2,PersonID3,PersonID4,PersonID5, '+STR(@ReciptType)+', SecondType, ServiceValue, ReciptValue,
  '+@Query+'TotalValue, AddDecValue, ReciptNote, OperatorID'+@QryReciptState+', UseUnitID, [ExpireDate], ProjectID, BudgetID'+@QueryAidNumber+', 
 ReciptStartDate, ReciptEndDate,UseOtherID,'+STR(@NewStoreID2)+', TruckNumber, MachineNo, MachineName, 
 ArzTypeID, RialsEqual, ReciptsRow, SellsMethod, SellsEmporium, MasirID, DeliveryID, PersonID2Bed, 
 RelatedID,  CostDownSave, '+STR(@NewServerID)+', '+STR(@YearID)+'
 , DefaultDate, InsertDate, MachineInfo, InsertTime, EditTime, UserRegistrationDoc, DefaultDuration, 
 CalcGiftItems, ReciptDateMiladi, MachineFullWeight, MachineWeight, CalcCostStorage, PortageBedbes , ReciptNote2, PO, ReciptNumberFormer ,'''+@FirstUser+''' AS FirstUser
 FROM  Recipts WHERE (ReciptID = '+STR(@OldReciptID)+' AND ServerID = '+STR(@ServerID)+' AND YearID = '+STR(@YearID)+')'
Exec (@Query)
end


  if ( @CorrelateKind = 8 ) 
     exec dbo.NewReciptsCorrelateKind8 @ReciptID , @OldReciptID , @YearID ,  @ServerID
  else
  begin 


	SELECT @ID = ID FROM Recipts WHERE (ReciptID = @ReciptID)AND (ServerID= @ServerID) AND (YearID= @YearID)
	--SET @MINItemsID=(SELECT MIN(ReciptItemID)FROM ReciptItems WHERE (ReciptID = @OldReciptID)AND (ServerID= @ServerID) AND (YearID= @YearID))
	SET     @ReciptItemID=  (SELECT MAX(ReciptItemID)+1  FROM ReciptItems WHERE (ServerID= @ServerID) AND (YearID= @YearID))

  if ((@ChangeAidReciptDate &   512) <> 0)   --تبت فرم مرتبط با توجه به فرم اعلامیه قیمت انجام شود  *
	INSERT INTO ReciptItems
	(ReciptItemID, ReciptID, StuffCode, StuffSize, StuffDiameter, StuffAlloy, InputEntity, OutputEntity, InputWeight, OutputWeight, RequestedEntity, 
	RequestedWeight, ControlCode, StuffGrade, TotalInputPrice, TotalOutputPrice, UnitSellPrice, TotallSellPrice, ItemNote,/* preReciptItemID,*/ acc_TopicCode,
	acc_DetailCode, acc_CTopicCode, UseUnitID, AidNumber, AidDate, Discount, acc_CTopicCode2, PersonID1, ProductCode, ProductModel, ItemDate, 
	ContactRate, WaterCo, OrderState, StandardRate, TotalStandardRate, Shift, YearID, ServerID, DeficitValue, UnitSellPrice2, 
	MachineWeight, TotalWeight, Auxiliary, MachineNo, MachineName, MachineFullWeight, SugarCo, SugarEntity, ArzAmount, InvEntity, InvWeight, 
	SecondTypeItem, AcceptEntity, RollbackEntity, AcceptWeight, RollbackWeight, TaxCo, TaxValue 
	, Portage, Article, Wage, Scoria, Waste1, Waste2, FUNCTION1, CustomerRate, PestEntity, ArzRate, InsertTime, EditTime, IRow
	,acc_CTopicCode3,UnitCommission,TransFormID
	/*, PrvYearID*/, Confirming, StuffCodingItemID, Length_, Width, DiagnosisCalcTotalPrice, StandardConsumptionCo
	,DeficitValue2,DeficitValue3,DeficitValue4,inbox,SpecialCode , ArzRate2, HowConvert, ArzTypeID2, ArzAmount2, ExchangePrice,  
	CommissionPrice,  UseOtherID_Item, PO

	, Commission, CurrencyDiscounts, RIDateMS, RIDateME, StuffpublicPercentI, ArzPortage, 
	IneffectiveInput, CommissionCurrency,FirstUser


)

	SELECT 	case when (@StepCorrelate<>1) then  ReciptItemID - 1 else 
	@ReciptItemID +   ROW_NUMBER() OVER(ORDER BY ReciptItemID ASC)   end 
	, @ReciptID AS Expr2, StuffCode, StuffSize, StuffDiameter, StuffAlloy, 
	CASE @CorrelateKind WHEN 7 THEN  @InEffectType  * RequestedEntity else @InEffectType * (InputEntity + OutputEntity)  end AS InputEntity, 
	CASE @CorrelateKind WHEN 7 THEN  @OutEffectType * RequestedEntity else @OutEffectType * (InputEntity + OutputEntity) end AS OutputEntity,
	CASE @CorrelateKind WHEN 7 THEN  @InEffectType  * RequestedWeight else @InEffectType * (InputWeight + OutputWeight)  end AS InputWeight, 
	CASE @CorrelateKind WHEN 7 THEN  @OutEffectType * RequestedWeight else @OutEffectType * (InputWeight + OutputWeight) end AS OutputWeight, 
	RequestedEntity, 
	RequestedWeight, ControlCode, StuffGrade, 
	@Factor * (CASE @CorrelateKind  WHEN 5 THEN @InEffectType * dbo.AutoUnitSellPrice2(ID, 1 ) 
	ELSE  dbo.FnPriceCo(@InEffectType , (TotalInputPrice + TotalOutputPrice),@PriceCo) END) AS TotalInputPrice, 
	@Factor * (CASE @CorrelateKind WHEN 5 THEN @OutEffectType * dbo.AutoUnitSellPrice2(ID, 1 ) 
	ELSE dbo.FnPriceCo(@OutEffectType , (TotalInputPrice + TotalOutputPrice),@PriceCo) END) AS TotalOutputPrice, 
	@Factor * (CASE @CorrelateKind WHEN 5 THEN dbo.AutoUnitSellPrice2(ID, 0) ELSE dbo.FnPriceCo(1,UnitSellPrice,@PriceCo) END) AS UnitSellPrice,  
	/* @Kind=0=UnitSellPrice @Kind=1=Total...Price @Kind=2=DiscountPercent @Kind=3=DiscountAmount   @Kind=4=TaxCo*/     
	CASE @PriceCo WHEN 1 THEN 
	--@Factor * (CASE @CorrelateKind WHEN 5 THEN dbo.AutoUnitSellPrice2(ID, 1) ELSE dbo.FnPriceCo(1,UnitSellPrice,@PriceCo) END) 
	--       /* * (ISNULL(InputEntity,0) + ISNULL(OutputEntity,0))*/-@FactorDeficitValue*ISNULL(DeficitValue,0)+ISNULL(TaxValue,0)
	dbo.CalcTotallSellPric( dbo.AutoUnitSellPrice2(ID, 1 )  ,dbo.AutoUnitSellPrice2(ID, 2)  ,dbo.AutoUnitSellPrice2(ID, 4)  ,'TotallSellPrice' )
	ELSE   dbo.FnPriceCo(1,TotallSellPrice,@PriceCo)  end 							 
	AS TotallSellPrice, 								 
	ItemNote,/* preReciptItemID,*/ acc_TopicCode, acc_DetailCode, acc_CTopicCode, UseUnitID, AidNumber, 
	AidDate, Discount, acc_CTopicCode2, PersonID1, 
	ProductCode, ProductModel, ItemDate, ContactRate, @Factor *  dbo.AutoUnitSellPrice2(ID, 2) as WaterCo, OrderState,  
	StandardRate,  @Factor * TotalStandardRate,ReciptItemID AS Shift, YearID, 
	@NewServerID
	,  @Factor * @FactorDeficitValue*  dbo.CalcTotallSellPric( dbo.AutoUnitSellPrice2(ID, 1 )  ,dbo.AutoUnitSellPrice2(ID, 2)  ,dbo.AutoUnitSellPrice2(ID, 4)  ,'DeficitValue' ) as   DeficitValue,  @Factor * UnitSellPrice2, MachineWeight, TotalWeight, Auxiliary, 
	MachineNo, MachineName, MachineFullWeight, SugarCo, SugarEntity, 
	ArzAmount, InvEntity, InvWeight, SecondTypeItem, AcceptEntity, RollbackEntity, AcceptWeight, 
	RollbackWeight, @Factor * dbo.AutoUnitSellPrice2(ID, 4) as TaxCo
	, @Factor *   dbo.CalcTotallSellPric( dbo.AutoUnitSellPrice2(ID, 1 )  ,dbo.AutoUnitSellPrice2(ID, 2)  ,dbo.AutoUnitSellPrice2(ID, 4)  ,'TaxValue' ) as TaxValue   
	, @Factor * Portage,  @Factor * Article,  @Factor * Wage,  @Factor * Scoria, Waste1, Waste2, 
	FUNCTION1, CustomerRate, PestEntity, ArzRate, InsertTime, EditTime, IRow
	,acc_CTopicCode3, @Factor * UnitCommission,TransFormID
	/*, PrvYearID*/, Confirming, StuffCodingItemID, Length_, Width, DiagnosisCalcTotalPrice, StandardConsumptionCo
	,@FactorDeficitValue*DeficitValue2,@FactorDeficitValue*DeficitValue3,@FactorDeficitValue*DeficitValue4,inbox,SpecialCode, ArzRate2, HowConvert, ArzTypeID2, ArzAmount2, ExchangePrice, 
	CommissionPrice,  UseOtherID_Item, PO
	, Commission, CurrencyDiscounts, RIDateMS, RIDateME, StuffpublicPercentI, ArzPortage, IneffectiveInput, CommissionCurrency,@FirstUser
	FROM         ReciptItems AS ReciptItems_1 
	WHERE (ReciptID = @OldReciptID)AND (ServerID= @ServerID) AND (YearID= @YearID)
	AND StuffCode NOT IN ( SELECT StuffCoding.c_StuffCode
                            FROM ReciptTypesStuffGroups INNER JOIN
                           StuffCoding ON ReciptTypesStuffGroups.GroupID = StuffCoding.GroupID
                         WHERE (ReciptTypesStuffGroups.ReciptType = @ReciptType ))
	AND (((@ChangeAidReciptDate &   16384) = 0) or (InputEntity + OutputEntity)>0)--{ مقدارهای بزرگتر از صفر انتقال داده شود } CHKEntityNotZero = 16384

    else
	INSERT INTO ReciptItems
						  (ReciptItemID, ReciptID, StuffCode, StuffSize, StuffDiameter, StuffAlloy, InputEntity, OutputEntity, InputWeight, OutputWeight, RequestedEntity, 
						  RequestedWeight, ControlCode, StuffGrade, TotalInputPrice, TotalOutputPrice, UnitSellPrice, TotallSellPrice, ItemNote,/* preReciptItemID,*/ acc_TopicCode,
						   acc_DetailCode, acc_CTopicCode, UseUnitID, AidNumber, AidDate, Discount, acc_CTopicCode2, PersonID1, ProductCode, ProductModel, ItemDate, 
						  ContactRate, WaterCo, OrderState, StandardRate, TotalStandardRate, Shift, YearID, ServerID, DeficitValue, UnitSellPrice2, 
						  MachineWeight, TotalWeight, Auxiliary, MachineNo, MachineName, MachineFullWeight, SugarCo, SugarEntity, ArzAmount, InvEntity, InvWeight, 
						  SecondTypeItem, AcceptEntity, RollbackEntity, AcceptWeight, RollbackWeight, TaxCo, TaxValue
						  , Portage, Article, Wage, Scoria, Waste1, Waste2, FUNCTION1, CustomerRate, PestEntity, ArzRate, InsertTime, EditTime, IRow
                         ,acc_CTopicCode3,UnitCommission,TransFormID
						 /*, PrvYearID*/, Confirming, StuffCodingItemID, Length_, Width, DiagnosisCalcTotalPrice, StandardConsumptionCo
						 ,DeficitValue2,DeficitValue3,DeficitValue4,inbox,SpecialCode , ArzRate2, HowConvert, ArzTypeID2, ArzAmount2, ExchangePrice,  
						 CommissionPrice,  UseOtherID_Item, PO

, Commission, CurrencyDiscounts, RIDateMS, RIDateME, StuffpublicPercentI, ArzPortage, 
                         IneffectiveInput, CommissionCurrency,FirstUser


)
	SELECT   
	
	case when (@StepCorrelate<>1) then  ReciptItemID - 1 else 
	           @ReciptItemID +   ROW_NUMBER() OVER(ORDER BY ReciptItemID ASC)   end 
	  , @ReciptID AS Expr2, StuffCode, StuffSize, StuffDiameter, StuffAlloy, 
						 CASE @CorrelateKind WHEN 7 THEN  @InEffectType  * RequestedEntity else @InEffectType * (InputEntity + OutputEntity)  end AS InputEntity, 
						 CASE @CorrelateKind WHEN 7 THEN  @OutEffectType * RequestedEntity else @OutEffectType * (InputEntity + OutputEntity) end AS OutputEntity,
						 CASE @CorrelateKind WHEN 7 THEN  @InEffectType  * RequestedWeight else @InEffectType * (InputWeight + OutputWeight)  end AS InputWeight, 
						 CASE @CorrelateKind WHEN 7 THEN  @OutEffectType * RequestedWeight else @OutEffectType * (InputWeight + OutputWeight) end AS OutputWeight, 
						  RequestedEntity, 
						  RequestedWeight, ControlCode, StuffGrade, 
						  @Factor * (CASE @CorrelateKind  WHEN 5 THEN @InEffectType * dbo.AutoUnitSellPrice(ReciptItemID, 1, ReciptItems_1.ServerID, ReciptItems_1.YearID ) 
						  ELSE  dbo.FnPriceCo(@InEffectType , (TotalInputPrice + TotalOutputPrice),@PriceCo) END) AS TotalInputPrice, 
						  @Factor * (CASE @CorrelateKind WHEN 5 THEN @OutEffectType * dbo.AutoUnitSellPrice(ReciptItemID, 1, ReciptItems_1.ServerID, ReciptItems_1.YearID) 
						  ELSE dbo.FnPriceCo(@OutEffectType , (TotalInputPrice + TotalOutputPrice),@PriceCo) END) AS TotalOutputPrice, 
						  @Factor * (CASE @CorrelateKind WHEN 5 THEN dbo.AutoUnitSellPrice(ReciptItemID, 0, ReciptItems_1.ServerID, ReciptItems_1.YearID) ELSE dbo.FnPriceCo(1,UnitSellPrice,@PriceCo) END) AS UnitSellPrice,  

						CASE @PriceCo WHEN 1 THEN 
						  @Factor * (CASE @CorrelateKind WHEN 5 THEN dbo.AutoUnitSellPrice(ReciptItemID, 1, ReciptItems_1.ServerID, ReciptItems_1.YearID) ELSE dbo.FnPriceCo(1,TotalInputPrice + TotalOutputPrice,@PriceCo) END) 
						         /* * (ISNULL(InputEntity,0) + ISNULL(OutputEntity,0))*/-@FactorDeficitValue*ISNULL(DeficitValue,0)+ISNULL(TaxValue,0)
						ELSE   dbo.FnPriceCo(1,TotallSellPrice,@PriceCo)  end 							 
						  AS TotallSellPrice, 								 
						  ItemNote,/* preReciptItemID,*/ acc_TopicCode, acc_DetailCode, acc_CTopicCode, UseUnitID, AidNumber, 
						  AidDate, Discount, acc_CTopicCode2, PersonID1, 
						  ProductCode, ProductModel, ItemDate, ContactRate, @Factor * WaterCo, OrderState,  
						  StandardRate,  @Factor * TotalStandardRate,ReciptItemID AS Shift, YearID, 
						  @NewServerID,  @Factor * @FactorDeficitValue*DeficitValue,  @Factor * UnitSellPrice2, MachineWeight, TotalWeight, Auxiliary, 
						  MachineNo, MachineName, MachineFullWeight, SugarCo, SugarEntity, 
						  ArzAmount, InvEntity, InvWeight, SecondTypeItem, AcceptEntity, RollbackEntity, AcceptWeight, 
						  RollbackWeight, @Factor * TaxCo, @Factor *  TaxValue
						  , @Factor * Portage,  @Factor * Article,  @Factor * Wage,  @Factor * Scoria, Waste1, Waste2, 
						  FUNCTION1, CustomerRate, PestEntity, ArzRate, InsertTime, EditTime, IRow
						  ,acc_CTopicCode3, @Factor * UnitCommission,TransFormID
						  /*, PrvYearID*/, Confirming, StuffCodingItemID, Length_, Width, DiagnosisCalcTotalPrice, StandardConsumptionCo
						 ,@FactorDeficitValue*DeficitValue2,@FactorDeficitValue*DeficitValue3,@FactorDeficitValue*DeficitValue4,inbox,SpecialCode, ArzRate2, HowConvert, ArzTypeID2, ArzAmount2, ExchangePrice, 
						 CommissionPrice,  UseOtherID_Item, PO
, Commission, CurrencyDiscounts, RIDateMS, RIDateME, StuffpublicPercentI, ArzPortage, 
                         IneffectiveInput, CommissionCurrency,@FirstUser




	FROM         ReciptItems AS ReciptItems_1
	WHERE (ReciptID = @OldReciptID)AND (ServerID= @ServerID) AND (YearID= @YearID)
	AND StuffCode NOT IN ( SELECT StuffCoding.c_StuffCode
                            FROM ReciptTypesStuffGroups INNER JOIN
                           StuffCoding ON ReciptTypesStuffGroups.GroupID = StuffCoding.GroupID
                         WHERE (ReciptTypesStuffGroups.ReciptType = @ReciptType ))
	AND (((@ChangeAidReciptDate &   16384) = 0) or (InputEntity + OutputEntity)>0)






	INSERT INTO ReciptItemsDetails     (ReciptItemID,   ServerID,   YearID,   ReciptID,   DetailCaption, ReciptType, StuffGrade)
     SELECT      @ReciptItemID +Row1 AS ReciptItemID, D.ServerID, D.YearID,  @ReciptID AS ReciptID, D.DetailCaption, D.ReciptType, D.StuffGrade
     FROM            ReciptItemsDetails AS D INNER JOIN
                         (SELECT       ReciptItemID, ServerID, YearID, ReciptID,ROW_NUMBER() OVER( ORDER BY ReciptItemID ASC)     AS Row1
                              FROM                              ReciptItems 
                           WHERE (ReciptID = @OldReciptID)AND (ServerID= @ServerID) AND (YearID= @YearID) 
                            	AND (((@ChangeAidReciptDate &   16384) = 0) or (InputEntity + OutputEntity)>0)
						   	AND StuffCode NOT IN ( SELECT StuffCoding.c_StuffCode
                            FROM ReciptTypesStuffGroups INNER JOIN
                           StuffCoding ON ReciptTypesStuffGroups.GroupID = StuffCoding.GroupID
                         WHERE (ReciptTypesStuffGroups.ReciptType = @ReciptType ))

     ) AS Ri ON D.ReciptItemID = Ri.ReciptItemID AND D.ReciptID = Ri.ReciptID AND D.ServerID = Ri.ServerID AND D.YearID = Ri.YearID
	 WHERE (D.ReciptID = @OldReciptID)AND (D.ServerID= @ServerID) AND (D.YearID= @YearID) 



  end ---if

if (@ConfigSettings &  8 = 0) 
UPDATE Recipts SET ParentReciptID = @ReciptID 
WHERE (ReciptID = @OldReciptID)AND (ServerID= @ServerID) AND (YearID= @YearID)

if (SELECT     CorrelateReciptsDeficits
                     FROM         Recipts INNER JOIN  ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
                     WHERE (Recipts.ReciptID = @OldReciptID)AND (ServerID= @ServerID) AND (YearID= @YearID))=1
   exec NewReciptsCorrelateDeficits @OldReciptID, @ReciptID, @ServerID, @YearID

	--	if @trancount = 0	
		--	commit TRANSACTION NewRecipt;
  RETURN(1)
  

	
	--end try
	--begin catch
	--	declare @error int, @message varchar(4000), @xstate int;
