CREATE  FUNCTION  ReciptsList(  @ReciptTypeFrom int=9,@ReciptTypeTo int=11,
  @NumberFrom int=-1999999999, @NumberTo int=1999999999 , 
  @DateFrom char(10)='0000/00/00', @DateTo char(10)='9999/99/99',@StoreFrom smallint=-9999,
  @StoreTo smallint=9999,
--  @StateFrom int=0 ,@StateTo int=9999 ,
  @States varchar(20) ='0,1,2,3,4,5,6,7' ,
  @LookUpsCodeFrom int=-1999999999 ,@LookUpsCodeTo int=1999999999,
  @PersonID1From  int=-1999999999 , @PersonID1To int=1999999999, 
  @UseUnitIDFrom  int=-1999999999 , @UseUnitIDTo int=1999999999,
  @PersonID3From  int=-1999999999 , @PersonID3To int=1999999999,
  @PersonID4From  int=-1999999999 , @PersonID4To int=1999999999,
  @PersonID5From  int=-1999999999 , @PersonID5To int=1999999999,
  @SellsMethodFrom int=-1999999999 ,@SellsMethodTo int=1999999999,
  @SellsEmporiumFrom int=-1999999999 , @SellsEmporiumTo int=1999999999,
  @ReciptsRowFrom int=-1999999999 , @ReciptsRowTo int=1999999999,
  @AidNumberFrom varchar(40)='' , @AidNumberTo varchar(40)='9999999999999999999999999999999999999999',  
  @PersonID2From  int=-1999999999 , @PersonID2To int=1999999999 ,
  @MasirIDFrom  int=-1999999999 , @MasirIDTo int=1999999999 ,
  @UserID int=0 , @UserAdmin Tinyint =1 ,
  @CustomerGrpIDFrom int=-1999999999 , @CustomerGrpIDTo int=1999999999,
  @DEFAULTDateFrom char(10)='0000/00/00', @DEFAULTDateTo char(10)='9999/99/99' ,
  @AidDateFrom char(10)='0000/00/00', @AidDateTo char(10)='9999/99/99' ,
  @CorrelateReciptTypes varchar(1000)='0',
  @Store2From smallint=-9999,  @Store2To smallint=9999,
  @YearIDFrom int=-9999,  @YearIDTo int=9999

  )
  
RETURNS table  AS  
return (
SELECT  R.ID,
--case when RISUM.Price>0 then '$' Else '' end+
--case when Recipts.DocNo<>0 then '®' Else '' end+
--case when Recipts.ReciptState in(1,2) then '®' Else '' end+
--case when ParentRecipts.ReciptNumber IS NOT NULL then '®' Else '' end  AS ReciptsFlag,
case when RISUM.Price>0 then N'$' Else '' end+
case when R.DocNo<>0 then N'®' Else '' end+
case when R.ReciptState in(1,2) then N'ø' Else '' end+
case when PRecipts.ReciptNumber IS NOT NULL then N'©' Else '' end  AS ReciptsFlag,


R.ReciptID, R.ReciptNumber, R.ReciptNumberFormer, R.ReciptDate, R.ReciptDateMiladi, R.PersonID1, 
		CASE WHEN LEN(ISNULL(C1.CustFirstName,'')) = 0 THEN C1.CustName  ELSE  C1.CustFirstName+' ' +C1.CustName END+dbo.GetBlacklistMarker(C1.Blacklist ) AS _PersonName1,C1.ReagentName
		, R.ReciptState,
        RISUM.price
		, RISUM.price +ISNULL(DeficitAdd_Dec , 0) AS priceWithDef 
		, RISUM.price +ISNULL(DeficitAdd_Dec , 0)-ISNULL(RISUM.DeficitValue,0) AS priceWithDef2 ,
        ISNULL(DeficitAdd_Dec , 0) AS DeficitAddDec,            
        R.StoreID, S.c_StoreName , S.c_StoreName as _StoresName,
        R.StoreID2, Stores_2.c_StoreName as c_StoreName2,
        R.ReciptType, R.PersonID2, 
		CASE WHEN LEN(ISNULL(C2.CustFirstName,'')) = 0 THEN C2.CustName  ELSE  C2.CustFirstName+' ' +C2.CustName END+dbo.GetBlacklistMarker(C2.Blacklist )  AS CustName2
		, R.ReciptNote,
           ROUND(RISUM.Entity,4) as Entity,
		    ROUND(RISUM.[Weight],4) as [Weight],
  
        C1.Address as _PersonAddress, C1.Tel _Tel, 
        C1.Tel as _PersonTel, C1.Fax as _PersonFax,
		C1.EconomicNumber as _EconomicNumber, C1.PostalCode as _PostalCode,S.n_ValuationType as _ValuationType,
       ISNULL(R.AidNumber,'0') AidNumber,R.AidDate,R.DocNo,R.DocDate,
       ISNULL( PRecipts.ReciptNumber,0) AS FactorNumber, 
       R.FirstUser, R.LastUser,R.ParentReciptID, 
       LookUps.code as SecondType , LookUps.Name  as SecondTypeName, ISNULL(RISUM.DeficitValue,0) DeficitValue,  ISNULL(RISUM.DeficitValue3,0) DeficitValue3 ,
     RISUM.TotallSellPrice,
       RISUM.Price - 
       ISNULL( DeficitAdd_Dec , 0) -ISNULL(RISUM.DeficitValue,0) as  PayebelPrice,
		RISUM.TotallSellPrice+ 
		ISNULL	(DeficitAdd_Dec, 0) AS PayebelPrice2,RISUM.TaxValue ,
		RISUM.StandardRate as StandardRate , R.UseOtherID, 
		UseOthers.UseOtherName AS _UseOtherID, UseOthers.Code AS _UseOtherCode,
		R.UseUnitID ,UseUnits.UseUnitName as _UseUnitName, 
		C2.CustName AS  _PersonName2, R.PersonID3, 
		CASE WHEN LEN(ISNULL(C3.CustFirstName,'')) = 0 THEN C3.CustName  ELSE  C3.CustFirstName+' ' +C3.CustName END+dbo.GetBlacklistMarker(C3.Blacklist ) AS _PersonName3
		, R.PersonID4, 
		CASE WHEN LEN(ISNULL(C4.CustFirstName,'')) = 0 THEN C4.CustName  ELSE  C4.CustFirstName+' ' +C4.CustName END+dbo.GetBlacklistMarker(C4.Blacklist ) AS _PersonName4
		, R.PersonID5, 
		CASE WHEN LEN(ISNULL(C5.CustFirstName,'')) = 0 THEN C5.CustName  ELSE  C5.CustFirstName+' ' +C5.CustName END+dbo.GetBlacklistMarker(C5.Blacklist ) AS _PersonName5

        , R.SellsMethod, SellsMethods.SellsMethodName, R.SellsEmporium, SellsEmporiums.SellsEmporiumName
, R.ServerID, R.YearID,T.ReciptCaption,R.ReciptsRow,R.ParentCoReciptID,R.ModifyDate
,  Regular.RegDocNo, Regular.RegDocDate,Regular.RegPrice ,R.UserRegistrationDoc ,R.DefaultDate,R.DefaultDuration,PRecipts.ReciptType AS RelatedReciptType
, LTRIM(STR(tozin.TozinNumber))  +'    '+ tozin.TozinDate + ' - ' +  ISNULL(tozin.MachineName,'')+' - ' +ISNULL(tozin.MachineNo,'')  
		+ ' - ' + STR(tozin.PersonID2) AS Tozin_Note,R.InsertDate
		,R.RelatedID,R.CalcCostStorage,RISUM.ArzAmount,R.MachineName,R.TruckNumber,R.MachineInfo
		,CG1.CustomerGrpName AS CustomerGrpName1,RISUM.Article ,RISUM.Wage ,RISUM.Scoria ,R.MachineNo,C1.Address,
		
		 --SUBSTRING(ltrim(RISUM.TotallSellPrice+ISNULL(DeficitAdd_Dec, 0)),1,len(RISUM.TotallSellPrice+ISNULL(DeficitAdd_Dec, 0))-cast(InsuranceValue as int))
		 --+REPLICATE('0', cast(InsuranceValue as int)) AS InsuranceValue


		cast( Round(RISUM.TotallSellPrice+ISNULL(DeficitAdd_Dec, 0),-T.InsuranceValue) AS bigint)AS InsuranceValue,S.WarehouseID,R.External_ID,r.ExpireDate
		,R.tax_status ,   CASE R.tax_status WHEN 1 THEN 'ارسال شده'  WHEN 0 THEN 'خطا در ارسال' WHEN 2 THEN 'در صف انتظار تائید' ELSE 'آماده جهت ارسال' END AS tax_statusNote
		,R.LoanPayment,R.TAXID,R.IRTAXID,REFERENCENUMBER,InvoiceTemplate,DATE_OF_SEND_TO_TAX ,C1.HCTarafGaradadTypeCode,C1.HCKharidarTypeCode,C1.NationalID _NationalID,C1.NationalCode,C1.EconomicNumber,C1.PostalCode
		,Currencies.CurrencyCode,R.RialsEqual,R.ArzTypeID,R.TAXUID,RISUM.Portage
		,R.Insr,R.Indati2m,R.Nti1,R.Nti2

FROM	Recipts R LEFT OUTER JOIN
		AllDeficits_ForRecipts 	ON R.ReciptID = AllDeficits_ForRecipts.ReciptID 
		 AND R.ServerID = AllDeficits_ForRecipts.ServerID AND R.YearID = AllDeficits_ForRecipts.YearID 
		LEFT OUTER JOIN
		ReciptTypes AS T ON R.ReciptType = T.ReciptType LEFT OUTER JOIN
	    ReciptItemSum As RISUM ON R.ReciptID = RISUM.ReciptID AND R.ServerID = RISUM.ServerID AND R.YearID = RISUM.YearID LEFT OUTER JOIN
		LookUps ON R.SecondType = LookUps.LookUpID LEFT OUTER JOIN
		Stores S ON R.StoreID = S.n_StoreID LEFT OUTER JOIN
		Stores Stores_2 ON R.StoreID2 = Stores_2.n_StoreID LEFT OUTER JOIN
		Customers C1 ON R.PersonID1 = C1.CustID LEFT OUTER JOIN
		Customers C2 ON R.PersonID2 = C2.CustID LEFT OUTER JOIN
		Customers C3 ON R.PersonID3 = C3.CustID LEFT OUTER JOIN
		Customers C4 ON R.PersonID4 = C4.CustID LEFT OUTER JOIN 
		Customers C5 ON R.PersonID5 = C5.CustID LEFT OUTER JOIN 
		UseOthers ON R.UseOtherID = UseOthers.UseOtherID LEFT OUTER JOIN 
		UseUnits  ON R.UseUnitID  = UseUnits.UseUnitID LEFT OUTER JOIN 
		SellsMethods  ON R.SellsMethod  = SellsMethods.SellsMethod LEFT OUTER JOIN 
		SellsEmporiums  ON R.SellsEmporium  = SellsEmporiums.SellsEmporium
		INNER JOIN CustomersGroup CG1 ON C1.CustomerGrpID=CG1.CustomerGrpID 
        LEFT OUTER JOIN (SELECT ServerID, YearID, ReciptID, MAX(RegDocNo) AS RegDocNo, MAX(RegDocDate) AS RegDocDate, SUM(RegPrice) AS RegPrice
					      FROM  ReciptsRegulates
						  GROUP BY ServerID, YearID, ReciptID) AS Regular ON R.ReciptID = Regular.ReciptID AND R.ServerID = Regular.ServerID 
							 AND R.YearID = Regular.YearID
 LEFT OUTER JOIN
		Tozin ON R.TozinID = Tozin.TozinID
		cross join Config 
		LEFT OUTER JOIN
		--Recipts AS ParentRecipts ON Recipts.ParentReciptID = ParentRecipts.ReciptID 
		-- AND (Recipts.ServerID = ParentRecipts.ServerID /*or Recipts.ServerID = Config.ServerID  or ParentRecipts.ServerID = Config.ServerID*/) AND Recipts.YearID = ParentRecipts.YearID 
		 		dbo.Fn_ParentRecipts ( @CorrelateReciptTypes  ) AS PRecipts ON (R.ReciptID = PRecipts.ParentReciptID OR R.ParentReciptID = PRecipts.ReciptID)
		 AND (R.ServerID = PRecipts.ServerID /*or Recipts.ServerID = Config.ServerID  or ParentRecipts.ServerID = Config.ServerID*/) AND R.YearID = PRecipts.YearID 
         AND (LTRIM(T.CorrelateReciptType) <> LTRIM(T.RecallReciptTypes)) -- این شرط برای جاهایی که هم فرم مرتیط و هم فرا خوانی با هم از یک فرم انجام شود فرم ها تکرار نشوند

		  LEFT OUTER JOIN Currencies ON R.ArzTypeID = Currencies.CurrenciesID

WHERE (R.PersonID1 BETWEEN @PersonID1From AND @PersonID1To)
AND ((R.ReciptType BETWEEN @ReciptTypeFrom AND @ReciptTypeTo) --OR ((len(ReciptNumberOfType)>3) and (','+ReciptNumberOfType+',' LIKE N'%,'+LTRIM(STR(R.ReciptType))+',%'))
)
AND (R.ReciptNumber BETWEEN @NumberFrom AND @NumberTo)
AND (R.ReciptDate BETWEEN @DateFrom AND @DateTo)
AND ((R.DefaultDate ='/  /')OR(ISNULL(R.DefaultDate,'0000/00/00') BETWEEN @DefaultDateFrom AND @DefaultDateTo)OR(LTRIM(R.DefaultDate)=''))
AND ((R.AidDate ='/  /')OR(ISNULL(R.AidDate,'0000/00/00') BETWEEN @AidDateFrom AND @AidDateTo)OR(LEN( LTRIM(R.AidDate))<10))
AND (R.StoreID  BETWEEN @StoreFrom AND @StoreTo )
AND (R.StoreID2 BETWEEN @Store2From AND @Store2To )
AND (R.YearID   BETWEEN @YearIDFrom AND @YearIDTo )

AND(','+@States+',' LIKE N'%,'+LTRIM(STR(R.ReciptState))+',%')
AND (LookUps.Code BETWEEN   @LookUpsCodeFrom AND @LookUpsCodeTo)
AND ((R.UseUnitID BETWEEN   @UseUnitIDFrom AND @UseUnitIDTo) OR R.UseUnitID is null)
AND (ISNULL(R.PersonID3,0) BETWEEN @PersonID3From AND @PersonID3To)
AND (ISNULL(R.PersonID4,0) BETWEEN @PersonID4From AND @PersonID4To)
AND (ISNULL(R.PersonID5,0) BETWEEN @PersonID5From AND @PersonID5To)
AND (R.SellsMethod BETWEEN @SellsMethodFrom AND @SellsMethodTo)
AND (R.SellsEmporium BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)
AND (ISNULL(R.ReciptsRow,0) BETWEEN @ReciptsRowFrom AND @ReciptsRowTo)

AND (  ((T.ShowSettings & 1 ) = 0) or  
  ((R.AidNumber='')or(R.AidNumber='0')or(ISNULL(R.AidNumber,'0') BETWEEN @AidNumberFrom AND @AidNumberTo)))

AND (ISNULL(R.PersonID2,0) BETWEEN @PersonID2From AND @PersonID2To)
AND (R.MasirID BETWEEN @MasirIDFrom AND @MasirIDTo OR R.MasirID IS NULL)

AND ( (@UserAdmin = 1) OR ((T.UserSecurityCheckActive  &  64)<>64) OR (R.OperatorID = @UserID)  )

AND ((@UserAdmin = 1) OR (C1.OperatorID IS NULL) OR (LTRIM(C1.OperatorID) ='')OR (LTRIM(C1.OperatorID) ='0')  
OR (CG1.GroupType=2)OR(','+C1.OperatorID+',' LIKE N'%,'+LTRIM(STR(@UserID))+',%'))
AND (dbo.ChkUsersCustomersGroups(@UserAdmin , @UserID, R.PersonID1) = 1)
AND (ISNULL(CG1.CustomerGrpID,0) BETWEEN @CustomerGrpIDFrom AND @CustomerGrpIDTo)
AND (dbo.ChkUsersSellsEmporium(@UserAdmin , @UserID,T.UserSecurityCheckActive,R.SellsEmporium) = 1)
)

