CREATE  FUNCTION  ReciptsListItems( @ReciptTypeFrom int=9,@ReciptTypeTo int=11,
  @NumberFrom int=-9999999, @NumberTo int=99999999 , 
  @DateFrom char(10)='0000/00/00', @DateTo char(10)='9999/99/99',@StoreFrom smallint=-999,
  @StoreTo smallint=999,
--  @StateFrom int=0 ,@StateTo int=9999 ,
  @States varchar(20) ='0,1,2,3,4,5' ,
  @LookUpsCodeFrom int=0 ,@LookUpsCodeTo int=9999,
  @PersonID1From  int=0 , @PersonID1To int=999999999, 
  @UseUnitIDFrom  int=0 , @UseUnitIDTo int=999999999,
  @PersonID3From  int=0 , @PersonID3To int=999999999,
  @PersonID4From  int=0 , @PersonID4To int=999999999,
  @PersonID5From  int=0 , @PersonID5To int=999999999,
  @SellsMethodFrom int=0 ,@SellsMethodTo int=999999999,
  @SellsEmporiumFrom int=0 , @SellsEmporiumTo int=999999999,
  @ReciptsRowFrom int=0 , @ReciptsRowTo int=999999999,
  @AidNumberFrom varchar(40)='' , @AidNumberTo varchar(40)='9999999999999999999999999999999999999999',  
  @PersonID2From  int=0 , @PersonID2To int=999999999 ,
  @MasirIDFrom  int=0 , @MasirIDTo int=999999999 ,
  @UserID int=0 , @UserAdmin Tinyint =1 ,
  @CustomerGrpIDFrom int=0 , @CustomerGrpIDTo int=999999999,
  @DefaultDateFrom char(10)='0000/00/00', @DefaultDateTo char(10)='9999/99/99',
  @AidDateFrom char(10)='0000/00/00', @AidDateTo char(10)='9999/99/99' ,
  @CorrelateReciptType int=0  ,
  @Store2From smallint=-9999,  @Store2To smallint=9999,
  @YearIDFrom int=-9999,  @YearIDTo int=9999)
  
RETURNS table  AS  
return (
SELECT Recipts.*

FROM	ReciptsList(@ReciptTypeFrom,@ReciptTypeTo ,  @NumberFrom , @NumberTo  ,   @DateFrom , @DateTo ,@StoreFrom ,
  @StoreTo ,  @States  ,  @LookUpsCodeFrom  ,@LookUpsCodeTo ,  @PersonID1From   , @PersonID1To ,   @UseUnitIDFrom   , @UseUnitIDTo ,
  @PersonID3From  , @PersonID3To ,  @PersonID4From   , @PersonID4To ,  @PersonID5From   , @PersonID5To,  @SellsMethodFrom  ,@SellsMethodTo ,  @SellsEmporiumFrom  , @SellsEmporiumTo ,
  @ReciptsRowFrom  , @ReciptsRowTo ,  @AidNumberFrom  , @AidNumberTo ,    @PersonID2From   , @PersonID2To  ,  @MasirIDFrom   , @MasirIDTo  ,
  @UserID  , @UserAdmin  ,  @CustomerGrpIDFrom  , @CustomerGrpIDTo ,  @DefaultDateFrom , @DefaultDateTo , @AidDateFrom , @AidDateTo , @CorrelateReciptType
  , @Store2From ,  @Store2To ,  @YearIDFrom ,  @YearIDTo  )AS Recipts LEFT OUTER JOIN
		ReciptItems  ON Recipts.ParentReciptID = ReciptItems.ReciptID 
		 AND Recipts.ServerID = ReciptItems.ServerID AND Recipts.YearID = ReciptItems.YearID 
        LEFT OUTER JOIN Customers Customers_1 ON ReciptItems.PersonID1 = Customers_1.CustID 
--WHERE (ReciptItems.PersonID1 BETWEEN 0 AND 0)

)


