CREATE FUNCTION RptDialy4Proc (@DateFrom varchar(10)=[86/08/15] , @DateTo varchar(10)=[86/08/15]  )
RETURNS table  AS  
return (

SELECT     ReciptItems.StuffCode, StuffCoding.c_StuffName, Units.UnitName, 
	   round(SUM(case when (Recipts.ReciptDate <@DateFrom )  then 
	   ReciptItems.InputEntity - ReciptItems.OutputEntity else 0 end ),0) AS Column1 , 
	   round(SUM(case when (Recipts.ReciptDate between @DateFrom and @DateTo )  then 
	   ReciptItems.InputEntity  else 0 end ),0) AS Column2 , 
	   round(SUM(case when (Recipts.ReciptDate between @DateFrom  and @DateTo )and 
	   NOT (Recipts.PersonID1 IN (1500, 1501, 1502, 1503))  then 
	   ReciptItems.OutputEntity  else 0 end ),0) AS Column3 , 
	   round(SUM(case when (Recipts.ReciptDate between  @DateFrom  and @DateTo )and 
	   (Recipts.PersonID1 IN (1500, 1501))  then 
	   ReciptItems.OutputEntity  else 0 end ),0) AS Column4 , 
	   round(SUM(case when (Recipts.ReciptDate between @DateFrom  and @DateTo )and 
	   (Recipts.PersonID1 IN (1502))  then 
	   ReciptItems.OutputEntity  else 0 end ),0) AS Column5 , 
	   round(SUM(case when (Recipts.ReciptDate between @DateFrom  and @DateTo  )and 
	   (Recipts.PersonID1 IN ( 1503))  then 
	   ReciptItems.OutputEntity  else 0 end ),0) AS Column6 , 
	   round(SUM(case when (Recipts.ReciptDate <= @DateTo )  then 
	   ReciptItems.InputEntity - ReciptItems.OutputEntity else 0 end ),0) AS Column7  

FROM         ReciptItems INNER JOIN
                      Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
                      StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode INNER JOIN
                      ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType LEFT OUTER JOIN
                      Units ON StuffCoding.n_UnitCode = Units.UnitCode

WHERE (Recipts.StoreID = 7)AND (ReciptTypes.EffectType IN (2, 4))
GROUP BY   ReciptItems.StuffCode, StuffCoding.c_StuffName, Units.UnitName
)
