CREATE VIEW Aid_StuffCoding
AS
SELECT  Sf.StoreID,Sc.c_StuffCode, Sc.c_StuffName as c_StuffName, U.UnitName, Sc.c_StuffTecInfo, Sc.Carton, 
		Sc.SellPrice1, Sc.sd2 AS chapDate, Sc.sd3 AS chapNo, Sc.sd4 AS Virayesh, 
		Sc.sd5 AS jeldNo, Sc.sd6 AS PageNo, '' AS gerdavarndeh, SF.Tierced AS radif, 
		Sc.sd1 AS tabageh, '' AS PadidAvarndeh, '' AS nevisandeh, '' AS moalef, 
		'' AS motarjem, '' AS tasvirgar, '' AS nasher, '' AS gateketab, Sc.SellPrice2, 
		Sc.SellPrice3, Sc.SellPrice4, Sc.StandardRate, Sc.BuyPrice, 
		'' AS PakhshCompany, '' AS noejeldName, Sc.State, Sc.st13 AS PakhshCode, 
		Sc.st13, '' AS MozoName, '' AS MoshahaName, '' AS Virastar, Sc.StuffNote,
        Sc.c_StuffName+' '+ISNULL(Sc.sd1,'')+' '+ISNULL(Sc.sd2,'')+' '+ISNULL(Sc.sd3,'')+' '+ISNULL(Sc.sd4,'')+' '+
                                    ISNULL(Sc.sd5,'')+' '+ISNULL(Sc.sd6,'')+' '+ISNULL(Sc.sd7,'')+' '+ISNULL(Sc.sd8,'')+' '+
                                    ISNULL(Sc.sd9,'') as StuffName  ,
        '' AS gonehName, '' AS JanarName ,acc_DetaiCode,StanCode
        --,case Control_orderPoint_Entity  when 0 then 'غيرفعال'  else 'فعال' end as Control_orderPoint_Entity
        ,UnitPriceUseKind ,SellPrice_S ,Sf.KeepPlace c_KeepPlace,StuffpublicPercent,StuffpurePercent ,SG.GroupID ,'' as nevisandehCode,'' as MozoCode
		,Sc.VendorBarcode
       ,SG.GroupID AS GroupID0, SG.GroupName AS GroupName0, SG1.GroupID AS GroupID1, SG1.GroupName AS GroupName1, 
       SG2.GroupID AS GroupID2, SG2.GroupName AS GroupName2, 
       SG3.GroupID AS GroupID3, SG3.GroupName AS GroupName3
	   ,Sc.sd7	, Sc.VatExempt, Sc.VatExemptCo,U2.UnitName as 	UnitName2 ,
	   Sc.DefaultValue,Sc.ExternalId,Sc.NationalStuffCode,U.Tax_mu
	   , Scs.MinOrder n_minOrder , Scs.MaxOrder n_maxOrder, Scs.OrderPoint n_orderPoint, Scs.OptimumPoint, Scs.DayOfStorage, Scs.ProductModel,Sc.MaterialUsageCo


FROM         StuffCoding Sc INNER JOIN
             Units U ON Sc.n_UnitCode = U.UnitCode  LEFT OUTER JOIN
             Units AS U2  ON Sc.UnitCode2 = U2.UnitCode 
			 --LEFT OUTER JOIN -LookUps4Type(313) AS PakhshCompany ON Sc.st13 = PakhshCompany.Code LEFT OUTER JOIN--LookUps4Type(312) AS noejeld ON Sc.st12 = noejeld.Code LEFT OUTER JOIN
             --LookUps4Type(311) AS gateketab ON Sc.st11 = gateketab.Code LEFT OUTER JOIN--LookUps4Type(307) AS nasher ON Sc.st7 = nasher.Code LEFT OUTER JOIN
             --LookUps4Type(306) AS tasvirgar ON Sc.st6 = tasvirgar.Code LEFT OUTER JOIN--LookUps4Type(305) AS motarjem ON Sc.st5 = motarjem.Code LEFT OUTER JOIN
             --LookUps4Type(304) AS moalef ON Sc.st4 = moalef.Code LEFT OUTER JOIN--LookUps4Type(303) AS nevisandeh ON Sc.st3 = nevisandeh.Code LEFT OUTER JOIN
             --LookUps4Type(302) AS PadidAvarndeh ON Sc.st2 = PadidAvarndeh.Code LEFT OUTER JOIN--LookUps4Type(301) AS GerdAvarandeh ON Sc.st1 = GerdAvarandeh.Code LEFT OUTER JOIN
             --LookUps4Type(308) AS Mozo ON Sc.st8 = Mozo.Code LEFT OUTER JOIN--LookUps4Type(309) AS Virastars ON Sc.st9 = Virastars.Code LEFT OUTER JOIN
             --LookUps4Type(310) AS Moshaha ON Sc.st10 = Moshaha.Code LEFT OUTER JOIN--LookUps4Type(314) AS GO neh ON Sc.st14 = GO neh.Code LEFT OUTER JOIN--LookUps4Type(315) AS Janar ON Sc.st15 = Janar.Code                      
			 INNER JOIN StuffGroups SG ON Sc.GroupID = SG.GroupID  LEFT OUTER JOIN
     StuffGroups AS SG1 ON SG.UperGroupId =   SG1.GroupID LEFT OUTER JOIN
     StuffGroups AS SG2 ON SG1.UperGroupId = SG2.GroupID LEFT OUTER JOIN
     StuffGroups AS SG3 ON SG2.UperGroupId = SG3.GroupID  LEFT OUTER JOIN
     StuffCodingStock AS Scs ON Sc.c_StuffCode = Scs.StuffCode LEFT OUTER JOIN
	 StuffCodingFacilities AS Sf ON Sc.c_StuffCode = Sf.StuffCode
	 
					  ---------
 CROSS JOIN
                      Config
WHERE   (Sc.State = 0) or (Config.StuffCodingKind = 0)                     
