CREATE FUNCTION ReciptItemUses (@Kind int=[1]  )
RETURNS table  AS  
return (

SELECT  RT.ReciptType, RI.preReciptItemID, RI.StuffCode, 
		SUM(RI.InputEntity) AS InputEntity, SUM(RI.OutputEntity) AS OutputEntity, SUM(RI.InputWeight) AS InputWeight, SUM(RI.OutputWeight) AS OutputWeight, 
        SUM(RI.RequestedEntity) AS RequestedEntity, SUM(RI.RequestedWeight) AS RequestedWeight, 
		SUM(RI.TotalInputPrice) AS TotalInputPrice, SUM(RI.TotalOutputPrice) AS TotalOutputPrice, RT.Kind

FROM            Recipts AS R 
	INNER JOIN  ReciptItems AS RI ON R.ReciptID = RI.ReciptID AND R.ServerID = RI.ServerID AND R.YearID = RI.YearID 
	INNER JOIN  ReciptTypeRange AS RT ON R.ReciptType = RT.RecalReciptType

WHERE        (RT.Kind = @Kind)

GROUP BY RI.preReciptItemID, RI.StuffCode, RT.ReciptType, RT.Kind

HAVING        (NOT (RI.preReciptItemID IS NULL))
)
