CREATE VIEW Recal_Entity
AS

SELECT		RI.ReciptItemID, RI.ReciptID, RI.StuffCode, RI.StuffSize, RI.StuffDiameter, RI.StuffAlloy, 
		    RI.InputEntity, CAST(RI.OutputEntity AS float) AS OutputEntity, RI.InputWeight, RI.OutputWeight, RI.RequestedEntity, RI.RequestedWeight, 
			RI.ControlCode, RI.StuffGrade, RI.TotalInputPrice, RI.TotalOutputPrice, RI.UnitSellPrice, RI.TotallSellPrice, RI.ItemNote, RI.preReciptItemID, 
			RI.acc_TopicCode, RI.acc_DetailCode, RI.acc_CTopicCode, RI.UseUnitID, RI.AidNumber, RI.AidDate, RI.Discount, RI.acc_CTopicCode2, 
			RI.PersonID1, RI.ProductCode, RI.ProductModel, RI.ItemDate, RI.OrderState, RI.ContactRate, RI.WaterCo, 
            RI.FirstUser, RI.LastUser, RI.Shift, RI.DeficitValue, RI.UnitSellPrice2, RI.MachineWeight, RI.TotalWeight, RI.Auxiliary, 
			RI.MachineNo, RI.MachineName, RI.MachineFullWeight, RI.SugarCo, RI.SugarEntity, RI.StandardRate, 
			CAST(RI.ArzAmount AS float) AS ArzAmount, CAST(RI.InvEntity AS float) AS InvEntity, RI.InvWeight, RI.SecondTypeItem, RI.TotalStandardRate, 
			RI.AcceptEntity, RI.RollbackEntity, RI.AcceptWeight, RI.RollbackWeight, RI.TaxCo, RI.TaxValue, RI.ServerID, RI.YearID, 
			RI.Portage, RI.Article, RI.Wage, RI.Scoria, RI.Waste1, RI.Waste2, RI.Function1, RI.CustomerRate, RI.PestEntity, RI.ArzRate, RI.InsertTime, 
            RI.EditTime, RI.IRow, RI.acc_CTopicCode3, 
			CAST(RI.InputEntity + RI.OutputEntity - ISNULL(RIU.InputEntity + RIU.OutputEntity, 0) AS float)  AS Entity, 
            CAST(RI.InputWeight + RI.OutputWeight - ISNULL(RIU.InputWeight + RIU.OutputWeight, 0) AS float)  AS Weight, 
			RI.TotalInputPrice + RI.TotalOutputPrice - ISNULL(RIU.TotalInputPrice + RIU.TotalOutputPrice, 0) AS Price, 
			S.c_StoreName, SC.c_StuffName, U.UnitName, CTD1.CustName, RT.ReciptCaption, R.StoreID, R.ReciptNumber, R.ReciptDate, 
			R.PersonID1 AS CustID1, R.PersonID2 AS CustID2, R.ReciptType, 
            R.SecondType, R.ServiceValue, R.ReciptValue, R.TotalValue, R.AddDecValue, R.DocNo, R.DocDate, R.ReciptNote, R.ParentReciptID, R.OperatorID, R.ModifyDate, 
			R.ReciptState, R.UseUnitID AS UseUnitID_M, R.ExpireDate, R.ProjectID, R.BudgetID, R.AidNumber AS AidNumberM, R.AidDate AS AidDateM, R.ReciptStartDate, 
			R.ReciptEndDate, R.DebtControlActive, R.StoreID2, R.TruckNumber, R.MachineNo AS MachineNoM, R.MachineName AS MachineNameM, SC.st13, 
			R.PersonID1 AS PersonID1M, R.PersonID2 AS PersonID2M, R.PersonID3 AS PersonID3M, 
			isnull(CT1.CustFirstName,'') + ' '+ CT1.CustName+dbo.GetBlacklistMarker(ct1.Blacklist ) AS CustName1M, isnull(CT2.CustFirstName,'') + ' '+ CT2.CustName+dbo.GetBlacklistMarker(CT2.Blacklist ) AS CustName2M, 
			isnull(CT3.CustFirstName,'') + ' '+ CT3.CustName+dbo.GetBlacklistMarker(CT3.Blacklist ) AS CustName3M

FROM			Recipts        AS R 
	INNER JOIN  ReciptItems    AS RI ON R.ReciptID = RI.ReciptID AND R.ServerID = RI.ServerID AND R.YearID = RI.YearID 
	INNER JOIN  ReciptTypes    AS RT ON R.ReciptType = RT.ReciptType 
	INNER JOIN  Stores         AS S  ON R.StoreID = S.n_StoreID 
	INNER JOIN  StuffCoding    AS SC ON RI.StuffCode = SC.c_StuffCode 
	LEFT  JOIN  ReciptItemUses (1) AS RIU ON R.ReciptType = RIU.ReciptType AND RI.ReciptItemID = RIU.preReciptItemID 
	LEFT  JOIN  Customers      AS CTD1 ON RI.PersonID1 = CTD1.CustID 
	LEFT  JOIN  Units          AS U    ON SC.n_UnitCode = U.UnitCode 
	INNER JOIN  Customers      AS CT1  ON ISNULL(R.PersonID1, 0) = CT1.CustID 
	INNER JOIN  Customers      AS CT2  ON ISNULL(R.PersonID2, 0) = CT2.CustID 
	INNER JOIN  Customers      AS CT3  ON ISNULL(R.PersonID3, 0) = CT3.CustID

WHERE	(RI.InputEntity + RI.OutputEntity - ISNULL(RIU.InputEntity + RIU.OutputEntity, 0) >= 0.001) OR
        (RI.InputWeight + RI.OutputWeight - ISNULL(RIU.InputWeight + RIU.OutputWeight, 0) >= 0.001)

GO 
