CREATE VIEW Recal_Request
AS
SELECT     ReciptItems.ReciptItemID, ReciptItems.ReciptID, ReciptItems.StuffCode, ReciptItems.StuffSize, ReciptItems.StuffDiameter, ReciptItems.StuffAlloy, 
                      ReciptItems.InputEntity, 
                      cast( ReciptItems.OutputEntity as float)as OutputEntity
                      , ReciptItems.InputWeight, ReciptItems.OutputWeight, ReciptItems.RequestedEntity, ReciptItems.RequestedWeight, 
                      ReciptItems.ControlCode, ReciptItems.StuffGrade, ReciptItems.TotalInputPrice, ReciptItems.TotalOutputPrice, ReciptItems.UnitSellPrice, ReciptItems.TotallSellPrice, 
                      ReciptItems.ItemNote, ReciptItems.preReciptItemID, ReciptItems.acc_TopicCode, ReciptItems.acc_DetailCode, ReciptItems.acc_CTopicCode, ReciptItems.UseUnitID, 
                      ReciptItems.AidNumber, ReciptItems.AidDate, ReciptItems.Discount, ReciptItems.acc_CTopicCode2, ReciptItems.PersonID1, ReciptItems.ProductCode, 
                      ReciptItems.ProductModel, ReciptItems.ItemDate, ReciptItems.OrderState, ReciptItems.ContactRate, ReciptItems.WaterCo, ReciptItems.FirstUser, 
                      ReciptItems.LastUser, ReciptItems.Shift, ReciptItems.DeficitValue, ReciptItems.UnitSellPrice2, ReciptItems.MachineWeight, ReciptItems.TotalWeight, 
                      ReciptItems.Auxiliary, ReciptItems.MachineNo, ReciptItems.MachineName, ReciptItems.MachineFullWeight, ReciptItems.SugarCo, ReciptItems.SugarEntity, 
                      ReciptItems.StandardRate, 
                      cast( ReciptItems.ArzAmount as float)as ArzAmount,
                      cast( ReciptItems.InvEntity as float)as InvEntity
                      , ReciptItems.InvWeight, ReciptItems.SecondTypeItem, ReciptItems.TotalStandardRate, 
                      ReciptItems.AcceptEntity, ReciptItems.RollbackEntity, ReciptItems.AcceptWeight, ReciptItems.RollbackWeight, ReciptItems.TaxCo, ReciptItems.TaxValue, 
                      ReciptItems.ServerID, ReciptItems.YearID, ReciptItems.Portage, ReciptItems.Article, ReciptItems.Wage, ReciptItems.Scoria, ReciptItems.Waste1, ReciptItems.Waste2, 
                      ReciptItems.FUNCTION1, ReciptItems.CustomerRate, ReciptItems.PestEntity, ReciptItems.ArzRate, ReciptItems.InsertTime, ReciptItems.EditTime, ReciptItems.IRow, 
                      ReciptItems.acc_CTopicCode3,

cast( ReciptItems.RequestedEntity - ISNULL(ReciptItemUses.InputEntity + ReciptItemUses.OutputEntity, 0)AS float) AS Entity, 
cast( ReciptItems.RequestedWeight - ISNULL(ReciptItemUses.InputWeight + ReciptItemUses.OutputWeight, 0)AS float) AS Weight, 
                      ReciptItems.TotalInputPrice + ReciptItems.TotalOutputPrice - ISNULL(ReciptItemUses.TotalInputPrice + ReciptItemUses.TotalOutputPrice, 0) 
                      AS Price, Stores.c_StoreName AS c_StoreName, StuffCoding.c_StuffName AS c_StuffName, Units.UnitName AS UnitName, 
                      Customers.CustName AS CustName, ReciptTypes.ReciptCaption AS ReciptCaption, Recipts.StoreID AS StoreID, 
                      Recipts.ReciptNumber AS ReciptNumber, Recipts.ReciptDate AS ReciptDate, Recipts.PersonID1 AS CustID1, 
                      Recipts.PersonID2 AS CustID2, Recipts.ReciptType AS ReciptType, Recipts.SecondType AS SecondType, 
                      Recipts.ServiceValue AS ServiceValue, Recipts.ReciptValue AS ReciptValue, Recipts.TotalValue AS TotalValue, 
                      Recipts.AddDecValue AS AddDecValue, Recipts.DocNo AS DocNo, Recipts.DocDate AS DocDate, Recipts.ReciptNote AS ReciptNote, 
                      Recipts.ParentReciptID AS ParentReciptID, Recipts.OperatorID AS OperatorID, Recipts.ModifyDate AS ModifyDate, 
                      Recipts.ReciptState AS ReciptState, Recipts.UseUnitID AS UseUnitID_M, Recipts.ExpireDate AS ExpireDate, 
                      Recipts.ProjectID AS ProjectID, Recipts.BudgetID AS BudgetID, Recipts.AidNumber AS AidNumberM, Recipts.AidDate AS AidDateM, 
                      Recipts.ReciptStartDate AS ReciptStartDate, Recipts.ReciptEndDate AS ReciptEndDate, Recipts.DebtControlActive AS DebtControlActive, 
                      Recipts.StoreID2 AS StoreID2, Recipts.TruckNumber AS TruckNumber, Recipts.MachineNo AS MachineNoM, 
                      Recipts.MachineName AS MachineNameM, StuffCoding.st13
,Recipts.PersonID1 AS PersonID1M,Recipts.PersonID2 AS PersonID2M,Recipts.PersonID3 AS PersonID3M
,Customers1.CustName AS CustName1M,Customers2.CustName AS CustName2M,Customers3.CustName AS CustName3M


FROM         Recipts INNER JOIN
                      ReciptItems ON Recipts.ReciptID = ReciptItems.ReciptID AND Recipts.ServerID = ReciptItems.ServerID AND Recipts.YearID = ReciptItems.YearID INNER JOIN
                      ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType INNER JOIN
                      Stores ON Recipts.StoreID = Stores.n_StoreID INNER JOIN
                      StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode LEFT OUTER JOIN
                      ReciptItemUses(2) ReciptItemUses ON Recipts.ReciptType = ReciptItemUses.ReciptType AND 
                      ReciptItems.ReciptItemID = ReciptItemUses.preReciptItemID LEFT OUTER JOIN
                      Customers ON ReciptItems.PersonID1 = Customers.CustID LEFT OUTER JOIN
                      Units ON StuffCoding.n_UnitCode = Units.UnitCode
INNER JOIN Customers AS Customers1 ON ISNULL(Recipts.PersonID1,0) = Customers1.CustID
INNER JOIN Customers AS Customers2 ON ISNULL(Recipts.PersonID2,0) = Customers2.CustID
INNER JOIN Customers AS Customers3 ON ISNULL(Recipts.PersonID3,0) = Customers3.CustID

WHERE (ReciptItems.RequestedEntity - ISNULL(ReciptItemUses.InputEntity + ReciptItemUses.OutputEntity, 0) >= 0.001) OR
                      (ReciptItems.RequestedWeight - ISNULL(ReciptItemUses.InputWeight + ReciptItemUses.OutputWeight, 0) >= 0.001)

