CREATE  FUNCTION  [dbo].[Aid_StuffCodingEntity] (@ReciptDate varchar(10)='9999/99/99' ,@StoreIDForm int =0,@StoreIDTo int =99999
                             ,@c_StuffCodeForm Bigint =0,@c_StuffCodeTo Bigint =2147483647000000)
RETURNS table  AS  
return (
SELECT     StuffCoding.c_StuffCode, StuffCoding.c_StuffName, SUM(ReciptItems.InputEntity - ReciptItems.OutputEntity) AS SUMEntity, 
                      SUM(ReciptItems.InputWeight - ReciptItems.OutputWeight) AS SUMWeight, Units.UnitName, StuffCoding.c_StuffTecInfo, StuffCoding.Carton, 
                      StuffCoding.sd2 AS chapDate, StuffCoding.sd3 AS chapNo, StuffCoding.sd4 AS Virayesh, StuffCoding.sd5 AS jeldNo, StuffCoding.sd6 AS PageNo, 
                      'GerdAvarandeh.Name' AS gerdavarndeh, StuffCoding.c_KeepPlace AS radif, StuffCoding.sd1 AS tabageh, 'PadidAvarndeh.Name' AS PadidAvarndeh, 
                      'nevisandeh.Name' AS nevisandeh, 'moalef.Name' AS moalef, 'motarjem.Name' AS motarjem, 'tasvirgar.Name' AS tasvirgar, 'nasher.Name' AS nasher, 
                      'gateketab.Name' AS gateketab, StuffCoding.SellPrice1, StuffCoding.SellPrice2, StuffCoding.SellPrice3, StuffCoding.SellPrice4, StuffCoding.StandardRate, StuffCoding.BuyPrice, 
                      'PakhshCompany.Name' AS PakhshCompany, 'noejeld.Name' AS noejeldName, StuffCoding.State, StuffCoding.st13 AS PakhshCode, StuffCoding.st13, 
                      'Mozo.Name' AS MozoName, 'Moshaha.Name' AS MoshahaName, 'Virastars.Name' AS Virastar, StuffCoding.StuffNote
                      ,avg(ReciptItems.UnitSellPrice) as UnitSellPrice,Recipts.StoreID
--FROM         Units LEFT OUTER JOIN
