--                      LookUps4Type(301) AS GerdAvarandeh ON StuffCoding.st1 = GerdAvarandeh.Code LEFT OUTER JOIN
--                      LookUps4Type(302) AS PadidAvarndeh ON StuffCoding.st2 = PadidAvarndeh.Code LEFT OUTER JOIN
--                      LookUps4Type(303) AS nevisandeh ON StuffCoding.st3 = nevisandeh.Code LEFT OUTER JOIN
--                      LookUps4Type(304) AS moalef ON StuffCoding.st4 = moalef.Code LEFT OUTER JOIN
--                      LookUps4Type(305) AS motarjem ON StuffCoding.st5 = motarjem.Code LEFT OUTER JOIN
--                      LookUps4Type(306) AS tasvirgar ON StuffCoding.st6 = tasvirgar.Code LEFT OUTER JOIN
--                      LookUps4Type(307) AS nasher ON StuffCoding.st7 = nasher.Code LEFT OUTER JOIN
--                      LookUps4Type(308) AS Mozo ON StuffCoding.st8 = Mozo.Code LEFT OUTER JOIN
--                      LookUps4Type(309) AS Virastars ON StuffCoding.st9 = Virastars.Code LEFT OUTER JOIN
--                      LookUps4Type(310) AS Moshaha ON StuffCoding.st10 = Moshaha.Code LEFT OUTER JOIN
--                      LookUps4Type(311) AS gateketab ON StuffCoding.st11 = gateketab.Code LEFT OUTER JOIN
--                      LookUps4Type(312) AS noejeld ON StuffCoding.st12 = noejeld.Code LEFT OUTER JOIN
--                      LookUps4Type(313) AS PakhshCompany ON StuffCoding.st13 = PakhshCompany.Code
FROM         StuffCoding LEFT OUTER JOIN
                      --LookUps AS GerdAvarandeh ON StuffCoding.st1 = GerdAvarandeh.Code AND GerdAvarandeh.Kind = 301 LEFT OUTER JOIN
                      --LookUps AS PadidAvarndeh ON StuffCoding.st2 = PadidAvarndeh.Code AND PadidAvarndeh.Kind = 302 LEFT OUTER JOIN
                      --LookUps AS nevisandeh    ON StuffCoding.st3 = nevisandeh.Code AND nevisandeh.Kind = 303 LEFT OUTER JOIN
                      --LookUps AS moalef        ON StuffCoding.st4 = moalef.Code AND moalef.Kind = 304 LEFT OUTER JOIN
                      --LookUps AS motarjem      ON StuffCoding.st5 = motarjem.Code AND motarjem.Kind = 305 LEFT OUTER JOIN
                      --LookUps AS tasvirgar     ON StuffCoding.st6 = tasvirgar.Code AND tasvirgar.Kind = 306 LEFT OUTER JOIN
                      --LookUps AS nasher        ON StuffCoding.st7 = nasher.Code AND nasher.Kind = 307 LEFT OUTER JOIN
                      --LookUps AS Mozo          ON StuffCoding.st8 = Mozo.Code AND Mozo.Kind = 308 LEFT OUTER JOIN
                      --LookUps AS Virastars     ON StuffCoding.st9 = Virastars.Code AND Virastars.Kind = 309 LEFT OUTER JOIN
                      --LookUps AS Moshaha       ON StuffCoding.st10 = Moshaha.Code AND Moshaha.Kind = 310 LEFT OUTER JOIN
                      --LookUps AS gateketab     ON StuffCoding.st11 = gateketab.Code AND gateketab.Kind = 311 LEFT OUTER JOIN
                      --LookUps AS noejeld       ON StuffCoding.st12 = noejeld.Code AND noejeld.Kind = 312 LEFT OUTER JOIN
                      --LookUps AS PakhshCompany ON StuffCoding.st13 = PakhshCompany.Code AND PakhshCompany.Kind = 313 RIGHT OUTER JOIN
                      Units ON StuffCoding.n_UnitCode = Units.UnitCode LEFT OUTER JOIN
                      Recipts RIGHT OUTER JOIN
                      ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType LEFT OUTER JOIN
                      ReciptItems ON Recipts.ReciptID = ReciptItems.ReciptID AND Recipts.ServerID = ReciptItems.ServerID AND Recipts.YearID = ReciptItems.YearID ON StuffCoding.c_StuffCode = ReciptItems.StuffCode


WHERE (StuffCoding.State = 0) AND ((Recipts.ReciptDate <= @ReciptDate)or Recipts.ReciptDate is null )
AND  ((Recipts.StoreID between @StoreIDForm and @StoreIDTo) or Recipts.StoreID is null)
AND (ReciptTypes.EffectType = 2 OR  ReciptTypes.EffectType = 4 or ReciptTypes.EffectType is null) 
AND (Recipts.ReciptState < 3 or Recipts.ReciptState is null)
AND  (StuffCoding.c_StuffCode between @c_StuffCodeForm and @c_StuffCodeTo)

GROUP BY StuffCoding.c_StuffCode, StuffCoding.c_StuffName, Units.UnitName, StuffCoding.c_StuffTecInfo, StuffCoding.Carton, StuffCoding.SellPrice1, 
                      StuffCoding.sd2, StuffCoding.sd3, StuffCoding.sd4, StuffCoding.sd5, StuffCoding.sd6, StuffCoding.c_KeepPlace, StuffCoding.sd1, 
                       StuffCoding.SellPrice2, 
                      StuffCoding.SellPrice3, StuffCoding.SellPrice4, StuffCoding.StandardRate, StuffCoding.BuyPrice, 
                      StuffCoding.State, StuffCoding.st13, StuffCoding.st13, StuffCoding.StuffNote,Recipts.StoreID
)
GO 
