SELECT     StoreID, StuffCode, StuffDiameter, SUM(Meters) AS Meters, SUM(Amount) AS Amount, ROUND(SUM(Amount) / SUM(Meters), 0) AS InMeters
FROM         BardashtInDaricheh_Field(

		@DateFrom, @DateTo, 
		@NoFrom, @NoTo, 
		@StoreIDFrom, @StoreIDTo, 
		@StuffCodeFrom, @StuffCodeTo, 
		@StuffDiameterFrom, @StuffDiameterTo, 
		@ControlCodeFrom, @ControlCodeTo

		) BardashtInDaricheh_Field
GROUP BY StoreID, StuffCode, StuffDiameter
)
