CREATE FUNCTION BardashtInDaricheh_RptField ( @DateFrom varchar(10)=['86/01/01'] , @DateTo  varchar(10)=['86/12/30'] ,
		    			@NoFrom int = [0] ,@NoTo int = [99999999] ,
		    			@StoreIDFrom int = [0] ,@StoreIDTo int = [99999999] ,
					@StuffCodeFrom varchar(10)=[0] , @StuffCodeTo  varchar (30)=[999999999]  ,
					@StuffDiameterFrom varchar(10)=[0] , @StuffDiameterTo  varchar (15)=[999999999]  ,
					@ControlCodeFrom varchar(20)=[0] , @ControlCodeTo  varchar (20)=[999999999]  
)
RETURNS table  AS  
return (
SELECT     Recipts.StoreID, ReciptItems.StuffCode, StuffCoding.c_StuffName, Units.UnitName, ReciptItems.StuffDiameter, ReciptItems.ControlCode, Earth.Meters, 
                      SUM(ISNULL(ReciptItems.RequestedWeight, 0)) AS Amount, ROUND(SUM(ISNULL(ReciptItems.RequestedWeight, 0)) / Earth.Meters, 2) 
                      AS AmountInPalce, BardashtInDaricheh_Field_Kol.Meters AS KolMeters, BardashtInDaricheh_Field_Kol.Amount AS KolAmount, 
                      BardashtInDaricheh_Field_Kol.InMeters AS KolInMeters
FROM         ReciptItems INNER JOIN
                      Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
                      StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode INNER JOIN
                      Units ON StuffCoding.n_UnitCode = Units.UnitCode LEFT OUTER JOIN
                      BardashtInDaricheh_Field_Kol(
                      @DateFrom, @DateTo, 
                      @NoFrom, @NoTo, 
                      @StoreIDFrom, @StoreIDTo, 
                      @StuffCodeFrom, @StuffCodeTo, 
                      @StuffDiameterFrom, @StuffDiameterTo, 
                      @ControlCodeFrom,   @ControlCodeTo

) BardashtInDaricheh_Field_Kol ON ReciptItems.StuffDiameter = BardashtInDaricheh_Field_Kol.StuffDiameter AND 
                      ReciptItems.StuffCode = BardashtInDaricheh_Field_Kol.StuffCode AND Recipts.StoreID = BardashtInDaricheh_Field_Kol.StoreID LEFT OUTER JOIN
                      agr.Earth Earth  ON ReciptItems.ControlCode = Earth.EarthField AND ReciptItems.StuffDiameter = Earth.Gate
WHERE          (Recipts.ReciptType IN (25, 26, 28))  AND 
                       (Recipts.ReciptDate BETWEEN @DateFrom  AND @DateTo) AND 
                       (Recipts.ReciptNumber BETWEEN @NoFrom AND @NoTo)   AND
                       (Recipts.StoreID BETWEEN @StoreIDFrom AND  @StoreIDTo)  AND
	          (ReciptItems.StuffCode BETWEEN   @StuffCodeFrom AND @StuffCodeTo) AND
                       (ReciptItems.StuffDiameter between @StuffDiameterFrom AND  @StuffDiameterTo )  AND
                       (ReciptItems.ControlCode between @ControlCodeFrom AND @ControlCodeTo ) 
GROUP BY Recipts.StoreID, ReciptItems.StuffDiameter, ReciptItems.ControlCode, ReciptItems.StuffCode, StuffCoding.c_StuffName, Units.UnitName, Earth.Meters,
                       BardashtInDaricheh_Field_Kol.Meters, BardashtInDaricheh_Field_Kol.Amount, BardashtInDaricheh_Field_Kol.InMeters
)
