CREATE FUNCTION Purchase_MinMax ( @DateFrom varchar(10)=['86/01/01'] , @DateTo  varchar(10)=['86/12/30'] ,
		    			@StoreIDFrom int = [0] ,@StoreIDTo int = [99999] ,
					@StuffCodeFrom varchar(10)=[0] , @StuffCodeTo  varchar (30)=[999999999]  ,
					@ReciptType varchar (2)=[5] )
RETURNS table  AS  
return (
SELECT       ReciptItems.StuffCode, Recipts.StoreID, MIN(Recipts.ReciptDate) AS MinDate, MAX(Recipts.ReciptDate) AS MaxDate, 
	       MIN(ReciptItems.UnitSellPrice) AS MinUnitPrice, MAX(ReciptItems.UnitSellPrice) AS MaxUnitPrice
		   ,MIN(ReciptItems.InputEntity) MinInputEntity,MIN(ReciptItems.InputWeight) MinInputWeight
		   ,MAX(ReciptItems.InputEntity) MAXInputEntity,MAX(ReciptItems.InputWeight) MAXInputWeight
FROM          ReciptItems INNER JOIN
                    Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID
WHERE      (Recipts.ReciptType = @ReciptType ) AND 
	      (Recipts.ReciptDate BETWEEN @DateFrom  AND @DateTo )
GROUP BY ReciptItems.StuffCode, Recipts.StoreID
HAVING      (ReciptItems.StuffCode BETWEEN @StuffCodeFrom AND @StuffCodeTo ) AND 
	      (Recipts.StoreID BETWEEN @StoreIDFrom AND @StoreIDTo )
)
