CREATE FUNCTION RptPurchase_MinMax ( @DateFrom varchar(10)=['86/01/01'] , @DateTo  varchar(10)=['86/12/30'] ,
		    			@StoreIDFrom int = [0] ,@StoreIDTo int = [99999] ,
					@StuffCodeFrom varchar(10)=[0] , @StuffCodeTo  varchar (30)=[999999999]  ,
					@ReciptType varchar (2)=[5] )
RETURNS table  AS  
return (
SELECT     Recipts.StoreID, ReciptItems.StuffCode, StuffCoding.c_StuffName, Units.UnitName, LastPurchase.LastPrice, LastPurchase.LastPriceDate
                 ,LastPurchase.LastInputEntity,LastPurchase.LastInputWeight, 
                      MinPurchase.MinPrice, MinPurchase.MinPriceDate1, MinPurchase.MinPriceDate2, MaxPurchase.MaxPrice, MaxPurchase.MaxPriceDate1, 
                      MaxPurchase.MaxPriceDate2 
--					  , round( case when SUM(ReciptItems.InputEntity)=0 then 0 else  SUM(ReciptItems.TotalInputPrice) / SUM(ReciptItems.InputEntity) end,1)  as AvragePrice
				  ,SUM(ROUND(CASE WHEN InputEntity + OutputEntity <> 0 THEN ((TotalInputPrice + TotalOutputPrice) +  (InputEntity + OutputEntity) * UnitCommission +
						   ROUND((InputWeight + OutputWeight) * ReciptItems.Commission,0)- DeficitValue - DeficitValue2 - DeficitValue4) / (InputEntity + OutputEntity) ELSE 0 END, 0)) AS AvragePrice
					
					  ,MinPurchase.MinEntity,MinPurchase.MinWeight
					   ,MaxPurchase.MaxEntity,MaxPurchase.MaxWeight
					   ,Recipts.PersonID1

FROM         ReciptItems INNER JOIN
                      Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
                      StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode INNER JOIN
                      Units ON StuffCoding.n_UnitCode = Units.UnitCode LEFT OUTER JOIN
                          (SELECT     Recipts.StoreID, ReciptItems.StuffCode
						  --, ReciptItems.UnitSellPrice AS MinPrice
						  ,MIN(ROUND(CASE WHEN InputEntity + OutputEntity <> 0 THEN ((TotalInputPrice + TotalOutputPrice) +  (InputEntity + OutputEntity) * UnitCommission +
						   ROUND((InputWeight + OutputWeight) * Commission,0)- DeficitValue - DeficitValue2 - DeficitValue4) / (InputEntity + OutputEntity) ELSE 0 END, 0)) AS MinPrice

						  , MIN(Recipts.ReciptDate) AS MinPriceDate1, 
                                                   MAX(Recipts.ReciptDate) AS MinPriceDate2
												   ,MIN(case when ReciptItems.InputEntity>0 then  ReciptItems.InputEntity else 99999999999 end) AS MinEntity, 
												    MIN(case when ReciptItems.InputWeight>0 then  ReciptItems.InputWeight else 99999999999 end) AS MinWeight
											
                             FROM         ReciptItems INNER JOIN
                                                   Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
                                                   Purchase_MinMax(@DateFrom, @DateTo , @StoreIDFrom, @StoreIDTo, @StuffCodeFrom, @StuffCodeTo, @ReciptType) Purchase_MinMax ON 
                                                   Recipts.StoreID = Purchase_MinMax.StoreID AND ReciptItems.StuffCode = Purchase_MinMax.StuffCode AND 
                                                   ReciptItems.UnitSellPrice = Purchase_MinMax.MinUnitPrice
    		   WHERE      (Recipts.ReciptType = @ReciptType ) AND 
			         (Recipts.ReciptDate BETWEEN @DateFrom  AND @DateTo )
                              GROUP BY Recipts.StoreID, ReciptItems.StuffCode, ReciptItems.UnitSellPrice
		   HAVING      (ReciptItems.StuffCode BETWEEN @StuffCodeFrom AND @StuffCodeTo ) AND 
			         (Recipts.StoreID BETWEEN @StoreIDFrom AND @StoreIDTo )
) MinPurchase ON ReciptItems.StuffCode = MinPurchase.StuffCode AND
                       Recipts.StoreID = MinPurchase.StoreID LEFT OUTER JOIN
                          (SELECT     Recipts.StoreID, ReciptItems.StuffCode
						 -- , ReciptItems.UnitSellPrice AS LastPrice
                            ,ROUND(CASE WHEN InputEntity + OutputEntity <> 0 THEN ((TotalInputPrice + TotalOutputPrice) +  (InputEntity + OutputEntity) * UnitCommission +
						   ROUND((InputWeight + OutputWeight) * Commission,0)- DeficitValue - DeficitValue2 - DeficitValue4) / (InputEntity + OutputEntity) ELSE 0 END, 0) AS LastPrice


						  , Purchase_MinMax.MaxDate AS LastPriceDate
						           ,ReciptItems.InputEntity  AS LastInputEntity,ReciptItems.InputWeight AS LastInputWeight 
                             FROM         ReciptItems INNER JOIN
                                                   Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
                                                   Purchase_MinMax(@DateFrom, @DateTo , @StoreIDFrom, @StoreIDTo, @StuffCodeFrom, @StuffCodeTo, @ReciptType)  Purchase_MinMax ON 
                                                   Recipts.StoreID = Purchase_MinMax.StoreID AND ReciptItems.StuffCode = Purchase_MinMax.StuffCode AND 
                                                   Recipts.ReciptDate = Purchase_MinMax.MaxDate
    		   WHERE      (Recipts.ReciptType = @ReciptType ) AND 
			         (Recipts.ReciptDate BETWEEN @DateFrom  AND @DateTo ) AND
		   	         (ReciptItems.StuffCode BETWEEN @StuffCodeFrom AND @StuffCodeTo ) AND 
			         (Recipts.StoreID BETWEEN @StoreIDFrom AND @StoreIDTo ) ) LastPurchase ON ReciptItems.StuffCode = LastPurchase.StuffCode AND 
                      Recipts.StoreID = LastPurchase.StoreID LEFT OUTER JOIN
                          (SELECT     Recipts.StoreID, ReciptItems.StuffCode
						  --, ReciptItems.UnitSellPrice AS MaxPrice
                            ,Max(ROUND(CASE WHEN InputEntity + OutputEntity <> 0 THEN ((TotalInputPrice + TotalOutputPrice) +  (InputEntity + OutputEntity) * UnitCommission +
						   ROUND((InputWeight + OutputWeight) * Commission,0)- DeficitValue - DeficitValue2 - DeficitValue4) / (InputEntity + OutputEntity) ELSE 0 END, 0)) AS MaxPrice

						  , MIN(Recipts.ReciptDate) AS MaxPriceDate1, 
                                                   MAX(Recipts.ReciptDate) AS MaxPriceDate2
												   , MAX(ReciptItems.InputEntity) AS MaxEntity, MAX(ReciptItems.InputWeight) AS MaxWeight
                             FROM         ReciptItems INNER JOIN
                                                   Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
                                                   Purchase_MinMax(@DateFrom, @DateTo , @StoreIDFrom, @StoreIDTo, @StuffCodeFrom, @StuffCodeTo, @ReciptType)  Purchase_MinMax ON 
                                                   Recipts.StoreID = Purchase_MinMax.StoreID AND ReciptItems.StuffCode = Purchase_MinMax.StuffCode AND 
                                                   ReciptItems.UnitSellPrice = Purchase_MinMax.MaxUnitPrice
    		   WHERE      (Recipts.ReciptType = @ReciptType ) AND 
			         (Recipts.ReciptDate BETWEEN @DateFrom  AND @DateTo )
                              GROUP BY Recipts.StoreID, ReciptItems.StuffCode, ReciptItems.UnitSellPrice
		   HAVING      (ReciptItems.StuffCode BETWEEN @StuffCodeFrom AND @StuffCodeTo ) AND 
			         (Recipts.StoreID BETWEEN @StoreIDFrom AND @StoreIDTo ) ) MaxPurchase ON 
                      ReciptItems.StuffCode = MaxPurchase.StuffCode AND Recipts.StoreID = MaxPurchase.StoreID
WHERE      (Recipts.ReciptType = @ReciptType ) AND 
	      (Recipts.ReciptDate BETWEEN @DateFrom  AND @DateTo )

GROUP BY Recipts.StoreID, ReciptItems.StuffCode, LastPurchase.LastPrice, LastPurchase.LastPriceDate, MinPurchase.MinPrice, MinPurchase.MinPriceDate1, 
                      MinPurchase.MinPriceDate2, MaxPurchase.MaxPrice, MaxPurchase.MaxPriceDate1, MaxPurchase.MaxPriceDate2, StuffCoding.c_StuffName, 
                      Units.UnitName,LastPurchase.LastInputEntity,LastPurchase.LastInputWeight
					 , MinPurchase.MinEntity ,MinPurchase.MinWeight
					 ,MaxPurchase.MaxEntity,MaxPurchase.MaxWeight
					 ,Recipts.PersonID1
HAVING      (ReciptItems.StuffCode BETWEEN @StuffCodeFrom AND @StuffCodeTo ) AND 
	      (Recipts.StoreID BETWEEN @StoreIDFrom AND @StoreIDTo )
)
