CREATE PROCEDURE [dbo].[GetNewStuffCode] @StuffCodeGroupID int,@UserID int,@Ip nvarchar(20),
@FormName nvarchar(50),@Year int,@ID BIGINT  OUTPUT as
begin
DECLARE @c_StuffCode BIGINT
DECLARE @IDValue int
DECLARE @CursorVar CURSOR
set @ID=(SELECT min(c_StuffCode) FROM  StuffCoding WHERE (GroupID = @StuffCodeGroupID))
SET @CursorVar = CURSOR SCROLL DYNAMIC
FOR SELECT c_StuffCode FROM StuffCoding WHERE (GroupID = @StuffCodeGroupID)ORDER BY c_StuffCode
OPEN @CursorVar
FETCH NEXT FROM @CursorVar INTO @c_StuffCode
WHILE @@FETCH_STATUS = 0
IF @ID<@c_StuffCode
  BEGIN
    BREAK
  END ELSE 
  BEGIN
    FETCH NEXT FROM @CursorVar  INTO @c_StuffCode
    set @ID= @ID+1
  END
CLOSE @CursorVar
DEALLOCATE @CursorVar
set  @FormName=Lower(@FormName)
set  @FormName =LTRIM( STR(@Year)) + '_' + @FormName
if @ID is null
  set @ID=(SELECT ISNULL(StartCode,0) FROM  StuffGroups WHERE (GroupID = @StuffCodeGroupID))   
  
set @IDValue=(SELECT max([Value]) FROM  Util.CodesInProcess WHERE ([Value] >= @ID) 
                                      AND (TableName = 'stuffcoding' ) 
									  and (FieldName = 'c_stuffcode') and (type = 0)   )  
if not( @IDValue is null )
  set @ID= @IDValue+1
INSERT INTO Util.CodesInProcess([UserID],FormName,[TableName]  ,[FieldName]  ,[Value],Ip )
            VALUES          (@UserID ,@FormName,'stuffcoding','c_stuffcode',@ID ,@Ip    )   
end
GO 
