CREATE  FUNCTION dbo.FnPriceCo(@EffectType int,@Price4Co money ,@Co  float)
RETURNS money                                         
begin
  DECLARE @Price     money
  SET @Price=@EffectType * ROUND(@Price4Co*@Co,0)
RETURN(ISNULL( @Price,0))

end
