CREATE PROCEDURE [dbo].[GetFirstEntityControlCode]
@OldBankName varchar(100)='dbo.Bsell_talachin_1392' ,
@YearNo varchar(4)='1392'    
, @YearID int
, @ServerID int
, @YearIDFrom int
as
begin
set nocount on
declare   @Query varchar(4000)
declare   @ReciptItemID int
set @ReciptItemID=(SELECT ISNULL(max(ReciptItemID),1)+1 FROM ReciptItems WHERE (ServerID= @ServerID) AND (YearID= @YearID))

IF  EXISTS(SELECT 1 FROM sysobjects WHERE id = object_id(N'ReciptItemsTemp') AND OBJECTPROPERTY(id, N'IsUserTable') = 1)
DROP TABLE ReciptItemsTemp

set @Query='create table ReciptItemsTemp (   
	 ReciptItemID int IDENTITY ('+STR(@ReciptItemID)+',1) NOT NULL ,	ReciptID int NOT NULL , 
	 StuffCode bigint NOT NULL ,	StuffSize varchar (12) NOT NULL , 
	 StuffDiameter float NOT NULL ,	StuffAlloy varchar (12) NOT NULL , 
	 InputEntity DECIMAL(38,8) NOT NULL ,	InputWeight DECIMAL(38,8) NOT NULL , 
	 StuffGrade tinyint NOT NULL ,	TotalInputPrice money NOT NULL , UnitSellPrice money  NULL , 
	 ControlCode bigint NOT NULL DEFAULT (0),	 
	 PersonID1 int NOT NULL DEFAULT (0),
	 PersonID3 int NOT NULL DEFAULT (0),
	 ItemNote varchar (100)	, 
 	 SpecialCode char (25)	,
     UseUnitID int NOT NULL DEFAULT (0),
	 TotallSellPrice Money ,
	 CONSTRAINT PK_ReciptItemsTemp PRIMARY KEY CLUSTERED 	(ReciptItemID	) ON [PRIMARY] ) ON [PRIMARY]  '
Exec (@Query)
set @Query='
  create view dbo.ReciptsStoresTemp AS
  SELECT R.StoreID, R.ControlCode
  FROM '+@OldBankName+'.ReciptItems_Stock AS R '
if @YearIDFrom<>0 
  set @Query= @Query +' WHERE R.YearID='+STR(@YearIDFrom)
set @Query= @Query +' GROUP BY R.StoreID,  R.ControlCode '
set @Query= @Query +' HAVING sum(InputEntity-OutputEntity)>0 '--or sum(InputWeight-OutputWeight)>0 
Exec (@Query)  
DECLARE StID CURSOR FOR  SELECT StoreID, ControlCode FROM ReciptsStoresTemp;
DECLARE @StoreID int 
DECLARE @ReciptID int 
DECLARE @ReciptNumber int 
DECLARE @ControlCode bigint 
DECLARE @YearStuffKind varchar(100)
set @YearStuffKind='YearStuffControlCode'
--DECLARE @StoreKind  TinyInt
OPEN StID;
FETCH NEXT FROM StID into @StoreID,@ControlCode--,@StoreKind
WHILE (@@FETCH_STATUS = 0)
begin
               
set @ReciptID=(SELECT ISNULL(max(ReciptID)+1,1) FROM Recipts WHERE (ServerID= @ServerID) AND (YearID= @YearID))
set @ReciptNumber=(SELECT ISNULL(max(ReciptNumber)+1,1) FROM Recipts WHERE (ReciptType=1)and(ServerID= @ServerID) AND (YearID= @YearID))
DECLARE @StartYear char(10)
SELECT @StartYear=StartYear  FROM Util.MaliYear WHERE (YearID= @YearNo)
INSERT INTO Recipts(ReciptID, StoreID, ReciptNumber, ReciptDate, ReciptType, ModifyDate,OperatorID,PersonID1,PersonID2,PersonID3,
             AddDecValue,TotalValue,ReciptValue, YearID, ServerID,ReciptNote) 
VALUES (@ReciptID, @StoreID, @ReciptNumber, @StartYear, 1, GETDATE(),127,0, 0 ,0
             ,0,0,0 , @YearID, @ServerID,@ControlCode)
  set @Query='INSERT INTO ReciptItemsTemp 
         ( ReciptID,StuffCode, StuffDiameter, StuffSize, StuffAlloy, StuffGrade, InputEntity, InputWeight, TotalInputPrice,ControlCode,PersonID1,ItemNote,SpecialCode,UseUnitID,TotallSellPrice) 
         SELECT '+STR(@ReciptID)+',StuffCode, StuffDiameter, StuffSize, StuffAlloy, StuffGrade, Entity, Weight, Price,ControlCode,PersonID1,ItemNote,SpecialCode,UseUnitID,TotallSellPrice 
         FROM '+@OldBankName+'.'+@YearStuffKind+' WHERE StoreID='+STR(@StoreID)+' AND ControlCode='+STR(@ControlCode)
if @YearIDFrom<>0 
  set @Query= @Query +' AND YearID = '+STR(@YearIDFrom)
Exec (@Query)
FETCH NEXT FROM StID into @StoreID,@ControlCode--,@StoreKind
end
CLOSE StID;
DEALLOCATE StID;
set @Query='declare @i int 
set @i=(SELECT MIN(CustomerGrpID) FROM CustomersGroup) 
if not exists (SELECT CustID FROM Customers WHERE (CustID = 0)) 
INSERT INTO Customers (CustID, CustName, ModifyDate, CustomerGrpID) 
VALUES (0, ''0'', GETDATE(), @i) '
Exec (@Query)
set @Query='INSERT INTO StuffCoding
                      (c_StuffCode, GroupID, c_StuffName, c_StuffTecInfo, n_UnitCode, n_minOrder, n_maxOrder, n_orderPoint, c_KeepPlace, BuyPrice, BudgetID, 
                      StandardRate, SellPrice1, SellPrice2, SellPrice3, SellPrice4, acc_DetaiCode, acc_CTopicCode, ModifyDate, OperatorID, State, s_s, Carton, 
                      acc_CTopicCode2, OptimumPoint, UnitPriceUseKind, StuffNote, sd1, sd2, sd3, sd4, sd5, sd6, sd7, sd8, sd9, Control_orderPoint_Entity, StanCode, 
                      OwnerShipKind, Acc_InComeTopicCode, Acc_BidTopicCode, Acc_CommissionTopicCode, Commission, StuffpurePercent, StuffpublicPercent, st1, st2, 
                      st3, st4, st5, st6, st7, st8, st9, st11, st10, st12, st13, st14, st15, StuffExpireDate, SellPrice_S,  ChangeState, Cabinet, Tierced, CustomerGrpID, 
					  TariffsID, VatExempt, VendorBarcode, acc_CTopicCode3, UnitCode2, StuffVolume, StuffWeight, DayOfStorage, SellPrice5, SellPrice6, SellPrice7, 
					  BlockOutput, c_StuffName_L2, DefaultValue, CustIdOrganic, ExternalId, ExportDateTime, NationalStuffCode, SD1Weight, VatExemptCo)
SELECT     c_StuffCode, GroupID, c_StuffName, c_StuffTecInfo, n_UnitCode, n_minOrder, n_maxOrder, n_orderPoint, c_KeepPlace, BuyPrice, BudgetID, 
                      StandardRate, SellPrice1, SellPrice2, SellPrice3, SellPrice4, acc_DetaiCode, acc_CTopicCode, ModifyDate, OperatorID, State, s_s, Carton, 
                      acc_CTopicCode2, OptimumPoint, UnitPriceUseKind, StuffNote, sd1, sd2, sd3, sd4, sd5, sd6, sd7, sd8, sd9, Control_orderPoint_Entity, StanCode, 
                      OwnerShipKind, Acc_InComeTopicCode, Acc_BidTopicCode, Acc_CommissionTopicCode, Commission, StuffpurePercent, StuffpublicPercent, st1, st2, 
                      st3, st4, st5, st6, st7, st8, st9, st11, st10, st12, st13, st14, st15, StuffExpireDate, SellPrice_S,  ChangeState, Cabinet, Tierced, CustomerGrpID, 
					  TariffsID, VatExempt, VendorBarcode, acc_CTopicCode3, UnitCode2, StuffVolume, StuffWeight, DayOfStorage, SellPrice5, SellPrice6, SellPrice7, 
					  BlockOutput, c_StuffName_L2, DefaultValue, CustIdOrganic, ExternalId, ExportDateTime, NationalStuffCode, SD1Weight, VatExemptCo
FROM         '+@OldBankName+'.StuffCoding AS StuffCoding_1
WHERE (c_StuffCode NOT IN (SELECT c_StuffCode FROM StuffCoding AS StuffCoding_2))'
Exec (@Query)

/*مقدار     وزن  مقدار/وزن     وزن/مقدار    */
DECLARE @EntityDisplayType tinyint
SELECT @EntityDisplayType=EntityDisplayType FROM Config

UPDATE ReciptItemsTemp
SET    UnitSellPrice=   CASE WHEN @EntityDisplayType in(0,2) then CASE WHEN   (InputEntity <> 0) then ROUND(TotalInputPrice / InputEntity, 2) else 0 end
                             ELSE CASE WHEN   (InputWeight <> 0) then ROUND(TotalInputPrice / InputWeight, 2) else 0 end
							  END



set @Query=' INSERT INTO ReciptItems  
			 (ReciptItemID, ReciptID,StuffCode, StuffDiameter, StuffSize, StuffAlloy, StuffGrade, InputEntity, InputWeight, TotalInputPrice,ControlCode
			 ,PersonID1,UnitSellPrice, YearID, ServerID,ItemNote,SpecialCode,UseUnitID,TotallSellPrice) 
 	   SELECT ReciptItemID, ReciptID,StuffCode, StuffDiameter, StuffSize, StuffAlloy, StuffGrade, InputEntity, InputWeight, TotalInputPrice,ControlCode
	   ,PersonID1,ISNULL(UnitSellPrice ,0) , '+STR(@YearID)+', '+STR(@ServerID)+',ItemNote,SpecialCode,UseUnitID,TotallSellPrice
			 FROM ReciptItemsTemp  '
Exec (@Query)
set @Query=' DROP table ReciptItemsTemp '
Exec (@Query)
set @Query=' DROP VIEW ReciptsStoresTemp '
Exec (@Query)
end  
