CREATE FUNCTION RptSellsWithPercent (@StuffcodFrom int= [0],@StuffcodTo int= [999999999] ,@DateFrom Varchar(10)= [0], @DateTo Varchar(10) = [99/99/99]     ,  @GrpIDFrom  int= [0],@GrpIdTo  int= [9999]   )
RETURNS table  AS  
return (
SELECT     StuffCoding.st13, StuffCoding.GroupID, ReciptItems.StuffCode, StuffCoding.c_StuffName, SUM(ReciptItems.OutputEntity) AS OutputEntity, SUM(ReciptItems.TotalOutputPrice) 
                      AS TotalOutputPrice, SUM(ReciptItems.DeficitValue+ReciptItems.DeficitValue2+ReciptItems.DeficitValue4+ReciptItems.DeficitValue3) AS DeficitValue, 
					  SUM(ReciptItems.TotalOutputPrice - (ReciptItems.DeficitValue+ReciptItems.DeficitValue2+ReciptItems.DeficitValue4+ReciptItems.DeficitValue3)) AS TotalPrice, 
                      (  cast (SUM(ReciptItems.TotalOutputPrice - (ReciptItems.DeficitValue+ReciptItems.DeficitValue2+ReciptItems.DeficitValue4+ReciptItems.DeficitValue3)) as float ) / Cast (MIN(SumRecipts.Price) as float )) * 100  AS PerPrice ,SUM(ReciptItems.OutputEntity) /min(SumRecipts.OutputEntity) *100  as PerEntity
		,   LookUps4Type.Name ,Recipts.StoreID, LookUps4Type8.Name as Mozo, LookUps4Type8.Code
FROM         ReciptItems INNER JOIN
                      Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
                      StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode LEFT OUTER JOIN
                      LookUps4Type(313) LookUps4Type ON StuffCoding.st13 = LookUps4Type.Code   LEFT OUTER JOIN
                                              dbo.LookUps4Type(308) AS LookUps4Type8 ON StuffCoding.st8 = LookUps4Type8.Code  CROSS JOIN
                          (SELECT     SUM(ReciptItems.OutputEntity) AS OutputEntity, SUM(ReciptItems.TotalOutputPrice) AS TotalOutputPrice
						    , SUM(ReciptItems.DeficitValue+ReciptItems.DeficitValue2+ReciptItems.DeficitValue4+ReciptItems.DeficitValue3) AS DeficitValue
							, SUM(ReciptItems.TotalOutputPrice - (ReciptItems.DeficitValue+ReciptItems.DeficitValue2+ReciptItems.DeficitValue4+ReciptItems.DeficitValue3)) AS Price
		FROM         ReciptItems INNER JOIN
             			      Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
	                      	      StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode
                             WHERE (Recipts.ReciptType = 12) AND (ReciptItems.StuffCode BETWEEN @StuffcodFrom AND @StuffcodTo ) AND
				 (Recipts.ReciptDate BETWEEN @DateFrom  AND @DateTo ) AND 
				 (StuffCoding.GroupID  between @GrpIDFrom and @GrpIdTo )  ) SumRecipts
WHERE (Recipts.ReciptType = 12) AND
				 (Recipts.ReciptDate BETWEEN @DateFrom  AND @DateTo )
GROUP BY  StuffCoding.st13,StuffCoding.GroupID, ReciptItems.StuffCode, StuffCoding.c_StuffName ,   LookUps4Type.Name,Recipts.StoreID
            , LookUps4Type8.Name, LookUps4Type8.Code
Having (ReciptItems.StuffCode BETWEEN @StuffcodFrom AND @StuffcodTo ) and  (StuffCoding.GroupID between @GrpIDFrom and @GrpIdTo)
)
GO 
