CREATE PROCEDURE ChangeCustIDWithAccCode @CustIDOld int,@CustIDNew int  
as
begin
SET NOCOUNT ON
BEGIN TRANSACTION;
    EXEC CopyCustID @CustIDOld ,@CustIDNew

	EXEC ChangeCustIDBsell @CustIDOld ,@CustIDNew

IF  EXISTS(SELECT * FROM SYSOBJECTS where id = object_id(N'Acc.Documents') and OBJECTPROPERTY(id, N'IsUserTable') = 1 )
begin 
	UPDATE Acc.Documents SET DetailCode = @CustIDNew     WHERE (DetailCode = @CustIDOld)
	UPDATE Acc.Documents SET CTopicCode = @CustIDNew     WHERE (CTopicCode = @CustIDOld)
	UPDATE Acc.Documents SET CTopicCode2 = @CustIDNew    WHERE (CTopicCode2 = @CustIDOld)
	UPDATE Acc.Documents SET CTopicCode3 = @CustIDNew    WHERE (CTopicCode3 = @CustIDOld)
end

UPDATE Customers     SET acc_DetailCode= @CustIDNew  WHERE (acc_DetailCode = @CustIDOld)
UPDATE Customers     SET acc_CTopicCode3= @CustIDNew WHERE (acc_CTopicCode3 = @CustIDOld)
UPDATE Customers     SET acc_CTopicCode= @CustIDNew  WHERE (acc_CTopicCode = @CustIDOld)
UPDATE Customers     SET acc_CTopicCode2= @CustIDNew WHERE (acc_CTopicCode2 = @CustIDOld)

IF OBJECT_ID ('TR_CheckDocument', 'TR') IS NOT NULL 
ALTER TABLE Customers DISABLE TRIGGER TR_CheckDocument
DELETE FROM  Customers WHERE (CustID = @CustIDOld )

IF OBJECT_ID ('TR_CheckDocument', 'TR') IS NOT NULL 
ALTER TABLE Customers ENABLE TRIGGER TR_CheckDocument

IF @@TRANCOUNT > 0      COMMIT TRANSACTION;
	else  ROLLBACK TRAN 

end

