CREATE FUNCTION [dbo].[GetRowReciptItems] (@ReciptItemID int=0, @ServerID int=0, @YearID int=88 )
RETURNS int 
begin
  DECLARE @ReciptID int
  DECLARE @RowID int
  SET @RowID=1
  SET @ReciptID=(SELECT top 1 ReciptID FROM ReciptItems WHERE (ReciptItemID= @ReciptItemID) AND (ServerID= @ServerID) AND (YearID= @YearID))
  DECLARE @NewReciptItemID int
  DECLARE @CursorVar CURSOR
	SET @CursorVar = CURSOR SCROLL DYNAMIC
	FOR SELECT ReciptItemID FROM ReciptItems  WHERE (ReciptID= @ReciptID) AND (ServerID= @ServerID) AND (YearID= @YearID)
	OPEN @CursorVar
	FETCH NEXT FROM @CursorVar INTO @NewReciptItemID
	WHILE @@FETCH_STATUS = 0
	IF @NewReciptItemID= @ReciptItemID 	BREAK
	  ELSE 
	  BEGIN
		FETCH NEXT FROM @CursorVar  INTO @NewReciptItemID
		set @RowID= @RowID+1
	  END
	CLOSE @CursorVar
	DEALLOCATE @CursorVar
	RETURN(@RowID)
END
