CREATE PROCEDURE [dbo].[GetNewCustID] @CustIDGroupID int,@UserID int,@Ip nvarchar(20)
,@FormName nvarchar(50),@Year int,@ID int OUTPUT as
begin
DECLARE @CustID int
DECLARE @CursorVar CURSOR
set @ID=(SELECT min(CustID) FROM  Customers WHERE (CustomerGrpID = @CustIDGroupID))
SET @CursorVar = CURSOR SCROLL DYNAMIC
FOR SELECT CustID FROM Customers WHERE (CustomerGrpID = @CustIDGroupID)ORDER BY CustID
OPEN @CursorVar
FETCH NEXT FROM @CursorVar INTO @CustID
WHILE @@FETCH_STATUS = 0
IF @ID<@CustID
  BEGIN
    BREAK
  END ELSE 
  BEGIN
    FETCH NEXT FROM @CursorVar  INTO @CustID
    set @ID= @ID+1
  END
CLOSE @CursorVar
DEALLOCATE @CursorVar
set  @FormName=Lower(@FormName)
set  @FormName =LTRIM( STR(@Year)) + '_' + @FormName
  
if @ID is null
  set @ID=(SELECT ISNULL(StartCode,0) FROM  CustomersGroup WHERE (CustomerGrpID = @CustIDGroupID))
INSERT INTO Util.CodesInProcess([UserID], FormName,[TableName],[FieldName],[Value],Ip )
            VALUES          (@UserID , @FormName,'customers','CustID'   ,@ID ,@Ip    )   
end
