CREATE FUNCTION [dbo].[GetReciptsIdDefStandardRate](@ReciptID int =185, @kind int=0, @ServerID int=0, @YearID int=88)
RETURNS money 
begin
  DECLARE @Amount money
  SET @Amount=(
SELECT SUM(StandardRate) from(
   SELECT (StandardRate)*(InputEntity + OutputEntity)as StandardRate FROM ReciptItems WHERE (ReciptID= @ReciptID) AND (ServerID= @ServerID) AND (YearID= @YearID))a

)
  if @kind=1
    SET @Amount= @Amount+(SELECT SUM(DeficitAdd)-SUM(DeficitDec) FROM ReciptsDeficits WHERE (ReciptID= @ReciptID))
  RETURN(@Amount)
end
