CREATE FUNCTION CycleDeficitAdd_After (@DateFrom Char(10)='0000/00/00', @DateTo Char(10)='9999/99/99' ,@Mastercode int=1,
               @StuffCodeFrom int=1 , @StuffCodeTo int=999999 ,@GroupIDFrom  int=1  , @GroupIDTo int=999999  )
RETURNS table  AS  
return (
SELECT          Recipts.StoreID as كدانبار, Stores.c_StoreName as نام‌انبار, 
                      Stores.n_ValuationType as نحوه‌قيمت‌گذاري, ReciptItems.StuffCode كد‌كالا, 
                      StuffCoding.c_StuffName as مشخصات‌كالا , Units.UnitName as واحد ,  
                      مقدار‌اول‌دوره = SUM(CASE WHEN Recipts.ReciptType BETWEEN 1 AND 3 THEN round(ReciptItems.InputEntity - ReciptItems.OutputEntity, 3) ELSE 0 END), 
                      پشت‌جلد‌اول‌دوره = SUM(CASE WHEN Recipts.ReciptType BETWEEN 1 AND  3 THEN round(ReciptItems.TotalInputPrice - ReciptItems.TotalOutputPrice, 3) ELSE 0 END), 
                      بهاي‌تمام‌شده‌اول‌دوره = SUM(CASE WHEN Recipts.ReciptType BETWEEN 1 AND  2 THEN round( ReciptItems.TotallSellPrice, 3) ELSE 0 END)
                                                           -SUM(CASE WHEN Recipts.ReciptType BETWEEN 3 AND 3 THEN round( ReciptItems.TotallSellPrice, 3) ELSE 0 END), 
                      مقداروارده = SUM(CASE WHEN  (Recipts.ReciptType >3 ) and (ReciptTypes.EffectType in( 2 ))  THEN round(ReciptItems.InputEntity, 3)   ELSE 0  END), 
                      پشت‌جلد‌وارده = SUM(CASE WHEN  (Recipts.ReciptType >3 ) and (ReciptTypes.EffectType in( 2 ))  THEN  round(ReciptItems.TotalInputPrice, 3)   ELSE 0 END), 
                      بهاي‌تمام‌شده‌‌وارده = SUM(CASE WHEN (Recipts.ReciptType >3 ) and (ReciptTypes.EffectType in( 2 )) THEN  round(ReciptItems.TotallSellPrice, 3)  ELSE   0 END), 
                      مقدارصادره = SUM(CASE WHEN ReciptTypes.EffectType=4 THEN  round(ReciptItems.OutputEntity, 3) else 0 END), 
                      پشت‌جلد‌صادره = SUM(CASE WHEN ReciptTypes.EffectType=4 THEN  round(ReciptItems.TotalOutputPrice, 3) else 0 END), 
                      بهاي‌تمام‌شده‌‌صادره = SUM(CASE WHEN ReciptTypes.EffectType=4 THEN  round(ReciptItems.TotallSellPrice, 3) else 0 END), 
                      مقدار‌موجودي = round(sum (case WHEN (ReciptTypes.EffectType in( 2 , 4)) Then (ReciptItems.InputEntity - ReciptItems.OutputEntity )else 0 end ) ,3) , 
                      پشت‌جلد‌موجودي = round(SUM  (case when (ReciptTypes.EffectType in( 2 , 4)) Then (ReciptItems.TotalInputPrice - ReciptItems.TotalOutputPrice )else 0 end ) , 3) ,
                      بهاي‌تمام‌شده‌موجودي=SUM(CASE WHEN  (ReciptTypes.EffectType in( 2 )) THEN round( ReciptItems.TotallSellPrice, 3) ELSE 0 END)
                                                           -SUM(CASE WHEN  (ReciptTypes.EffectType in( 4 ))  THEN round( ReciptItems.TotallSellPrice, 3) ELSE 0 END), 
                      مقدار‌نهايي = round(sum (case WHEN (ReciptTypes.EffectType in(2,4, 6 , 7)) Then (ReciptItems.InputEntity - ReciptItems.OutputEntity )else 0 end ) ,3) , 
                      پشت‌جلد‌نهايي =cast( round(SUM (case when (ReciptTypes.EffectType in( 2 , 4 , 6 , 7)) Then (ReciptItems.TotalInputPrice - ReciptItems.TotalOutputPrice )else 0 end ) , 3) as money ) ,
                      بهاي‌تمام‌شده‌‌نهايي =  SUM(CASE WHEN  (ReciptTypes.EffectType in( 2 , 6 )) THEN round( ReciptItems.TotallSellPrice, 3) ELSE 0 END)
                                                          - SUM(CASE WHEN  (ReciptTypes.EffectType in( 4 , 7 ))  THEN round( ReciptItems.TotallSellPrice, 3) ELSE 0 END) , 
                     مقدار‌كسري‌اضافه = round(sum (case WHEN (ReciptTypes.EffectType in( 6 , 7)) Then (ReciptItems.InputEntity - ReciptItems.OutputEntity )else 0 end ) ,3) ,
                     پشت‌جلد‌كسري‌اضافه =  round(SUM  (case when (ReciptTypes.EffectType in(6 , 7)) Then (ReciptItems.TotalInputPrice - ReciptItems.TotalOutputPrice )else 0 end ) , 3) ,
                     بهاي‌تمام‌شده‌كسري‌اضافه= SUM(CASE WHEN  (ReciptTypes.EffectType in( 6 )) THEN round( ReciptItems.TotallSellPrice, 3) ELSE 0 END)
                                                          -SUM(CASE WHEN  (ReciptTypes.EffectType in( 7 ))  THEN round( ReciptItems.TotallSellPrice, 3) ELSE 0 END) 
FROM         ReciptItems INNER JOIN                      Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
                      StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode INNER JOIN                       Stores ON Recipts.StoreID = Stores.n_StoreID INNER JOIN
                      Units ON StuffCoding.n_UnitCode = Units.UnitCode INNER JOIN                       ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType LEFT OUTER JOIN
                      StuffCodeCountingItems(0,999,@DateTo) StuffCodeCountingItems ON Recipts.StoreID = StuffCodeCountingItems.StoreID AND 
                      ReciptItems.StuffCode = StuffCodeCountingItems.StuffCode
 LEFT OUTER JOIN   StuffGroups ON StuffCoding.GroupID = StuffGroups.GroupID
WHERE         (Recipts.ReciptDate BETWEEN @DateFrom  AND @DateTo )
                      AND (Recipts.StoreID = @Mastercode )
                      AND (ReciptItems.StuffCode BETWEEN @StuffCodeFrom AND @StuffCodeTo )
                      And  (ReciptTypes.EffectType in (2 , 4 , 6 , 7)  ) 
                      AND (Recipts.ReciptState < 3) AND 
                    (StuffGroups.GroupID BETWEEN @GroupIDFrom  AND @GroupIDTo )
GROUP BY    Recipts.StoreID, Stores.c_StoreName, Stores.n_ValuationType, ReciptItems.StuffCode, StuffCoding.c_StuffName, 
                     Units.UnitName
)
