CREATE FUNCTION FormItemsCashWage (@FormID int=1 ,@ServerID int=0, @YearID int=88 )
RETURNS money 
begin
  DECLARE @CashWage money
  DECLARE @DisplayFormType tinyint
  SET @DisplayFormType=(SELECT FormTypes.DisplayFormType FROM Forms INNER JOIN FormTypes ON 
                                             Forms.FormType=FormTypes.FormType WHERE  Forms.FormID = @FormID
                                             and ServerID = @ServerID and  YearID = @YearID )

  SET @CashWage=(SELECT ISNULL(Amount,0)   FROM Forms WHERE FormID= @FormID and ServerID = @ServerID and  YearID = @YearID)
  if @DisplayFormType not in (0,7)  
     SET @CashWage=(SELECT ISNULL(SUM(CashWage),0) FROM FormItems WHERE FormID= @FormID and ServerID = @ServerID and  YearID = @YearID)
RETURN(@CashWage)
end
