CREATE  FUNCTION  [dbo].[RptExtension] ( @YearMounth varchar(5) =[87/04] , @GrpActionCustomer int = 29  )
RETURNS table  AS  
return (
SELECT     Customers.CustomerGrpID, Customers.CustID, Customers.CustName, Customers.Tel, Customers.Fax, Customers.InfoDate, LastRecipts.ReciptNumber, 
                      LastRecipts.ReciptDate, LastRecipts.ReciptStartDate, LastRecipts.ReciptEndDate, LastRecipts.ReciptNote , Customers.ContactRate
FROM         Customers LEFT OUTER JOIN
	(SELECT     PersonID1, ReciptNumber, ReciptDate, ReciptStartDate, ReciptEndDate, ReciptNote
	FROM         Recipts
	WHERE (ReciptType = 20) AND (StoreID = 2) AND (LEFT(ReciptEndDate, 5) = @YearMounth)) AS LastRecipts ON 
	Customers.CustID = LastRecipts.PersonID1
WHERE (Customers.GrpActionCustomer = @GrpActionCustomer) AND (Customers.InfoDate IS NULL) AND (Customers.CustID NOT IN
	(SELECT     PersonID1
	FROM         Recipts AS Recipts_2
	WHERE (ReciptType = 20) AND (StoreID = 2) AND (LEFT(ReciptEndDate, 5) >= @YearMounth) AND (LEFT(ReciptStartDate, 5) <= @YearMounth))) OR
	(Customers.GrpActionCustomer = @GrpActionCustomer) AND (Customers.CustID NOT IN
	(SELECT     PersonID1
	FROM         Recipts AS Recipts_1
	WHERE (ReciptType = 20) AND (StoreID = 2) AND (LEFT(ReciptEndDate, 5) >= @YearMounth) AND (LEFT(ReciptStartDate, 5) <= @YearMounth))) AND 
	(LEFT(Customers.InfoDate, 5) <= @YearMounth)
)
