CREATE FUNCTION [dbo].[GetWeekNo] ( @DateStr varchar(10) )
RETURNS varchar(10) 
begin
DECLARE @i int
DECLARE @KabisehCount int
DECLARE @TmpDateStr varchar(10)
DECLARE @TmpDate varchar(10)
DECLARE @Year int
DECLARE @YearTmp int
DECLARE @Month int
DECLARE @Day int
DECLARE @AllDay int
DECLARE @YearDay int
SET @i=charindex('/',@DateStr)
   IF LEN(@DateStr) - CHARINDEX('/', @DateStr,CHARINDEX('/', @DateStr,1)+1) = 4
   BEGIN
     SET @TmpDateStr = dbo.ReversDate(@DateStr)
     --IF ( ISDATE(@TmpDateStr) =1 )  
     --  RETURN(@TmpDateStr)--print @TmpDateStr
     --ELSE
     --   RETURN('')--print NULL
   END
   ELSE
     SET @TmpDateStr = @DateStr
   IF ((@i<>0) and (ISNUMERIC(REPLACE(@TmpDateStr,'/',''))=1) and (charindex('.',@TmpDateStr)=0)  )
   BEGIN
	   SET @Year=CAST(SUBSTRING(@TmpDateStr,1,@i-1) AS INT)
                IF ( @Year< 1300 )
                      SET @Year = @Year + 1300
                IF @Year > 9999
                  RETURN('')--print NULL
	   SET @TmpDate= SUBSTRING(@TmpDateStr,@i+1,Len(@TmpDateStr))
	   SET @i=charindex('/',@TmpDate)
	   SET @Month=CAST(SUBSTRING(@TmpDate,1,@i-1) AS INT)
	   SET @Month= @Month-- -1
	   SET @TmpDate= SUBSTRING(@TmpDate,@i+1,Len(@TmpDate))   
	   SET @Day=CAST(@TmpDate AS INT)
	   SET @Day= @Day-- - 1
   END
set @KabisehCount=0
set @YearTmp= @Year	   
WHILE @YearTmp >= 1376
BEGIN
   if @YearTmp%33 in(1,5,9,13,17,22,26,30)
        set @i=1
   else set @i=0
   set @KabisehCount= @KabisehCount+@i-- dbo.GetYearKabiseh(@YearTmp)
   set @YearTmp= @YearTmp-1     
END
if @Month>6 set @YearDay=(@Month-6)*31+(@Month-7)*30+@Day
else set @YearDay=(@Month-1)*31+@Day
set @AllDay= @Year*365+@KabisehCount
set @AllDay= @AllDay+@YearDay+1
if @AllDay%7=0 set @i=1 else  set @i=0
set @i= @AllDay/7-((@AllDay-@YearDay)/7)+@i
--print STR(@Year)+'Wsubstring('00ltrim(STR(@I)) ,len(@i)+1,2)
  RETURN(ltrim(STR(@Year))+'_W'+substring('00'+ltrim(STR(@i)) ,len(@i)+1,2)) -- ++STR(@AllDay%7) 
  
END
GO 
