CREATE PROCEDURE [dbo].[NewReciptsTotal] 
@ReciptID int , 
@ReciptNumber int,
@StoreID int,
@PersonID3 int,
@aDate Char(10),
@user nvarchar(50),
@YearID int , 
@ServerID int ,
@ReciptType int 
as
--DECLARE @MINItemsID int
DECLARE @ReciptItemID int
--DECLARE @ReciptItemID nvarchar(50)
begin

INSERT INTO Recipts( ReciptID,  StoreID,  ReciptNumber, ParentReciptID, ModifyDate, PersonID1, PersonID2, ReciptType,
SecondType, ServiceValue,ReciptValue, ReciptDate, TotalValue, AddDecValue , OperatorID, ReciptState,PersonID3, FirstUser,UseOtherID, YearID, ServerID)
VALUES             (@ReciptID, @StoreID, @ReciptNumber,   0            , GETDATE(),   0,          0,       @ReciptType,
  0,           0,            0 ,        @aDate,       0,         0,            0,           0      , @PersonID3,@user,         0,   @YearID, @ServerID)



--SET @MINItemsID = (SELECT  ISNULL(MIN(ReciptItems.ReciptItemID),0) FROM ReciptItems INNER JOIN  Recipts ON 
--                Recipts.ReciptID = ReciptItems.ReciptID AND Recipts.ServerID = ReciptItems.ServerID AND 
--                Recipts.YearID = ReciptItems.YearID
--				   WHERE (recipts.ParentReciptID = @ReciptID) and
--				          (recipts.YearID = @YearID) and
--				          (recipts.ServerID = @ServerID)   )
SELECT @ReciptItemID=ISNULL(MAX(ReciptItemID),0)+1  FROM ReciptItems 
        WHERE (YearID = @YearID) and      (ServerID = @ServerID)  

 if  exists (select * from dbo.sysobjects  WHERE id = object_id(N'__ReciptItems') 
          and OBJECTPROPERTY(id,N'IsUserTable') = 1)
 DROP TABLE __ReciptItems 


--SELECT   IDENTITY(int, 1,1) AS ReciptItemID, ISNULL(@ReciptID, 0) AS ReciptID, ReciptItems.StuffCode, 
--                      round(SUM(ISNULL(ReciptItems.InputEntity + ReciptItems.OutputEntity, 0)),2) AS OutputEntity, 
--                      round(SUM(ISNULL(ReciptItems.InputWeight + ReciptItems.OutputWeight, 0)),2) AS OutputWeight, 
--                      MAX(ISNULL(ReciptItems.UnitSellPrice, 0)) AS UnitSellPrice, 
--                      SUM(ISNULL(ReciptItems.TotalInputPrice + ReciptItems.TotalOutputPrice, 0)) AS TotalOutputPrice,
--                      round( SUM(ISNULL(ReciptItems.RequestedEntity, 0)),2) AS RequestedEntity, 
--                      round( SUM(ISNULL(ReciptItems.RequestedWeight, 0)),2) AS RequestedWeight, 
--                      round( SUM(ISNULL(ReciptItems.AcceptEntity, 0)),2) AS AcceptEntity,
--                      round( SUM(ISNULL(ReciptItems.AcceptWeight, 0)),2) AS AcceptWeight, 
--                      round( SUM(ISNULL(ReciptItems.RollbackEntity, 0)),2) AS RollbackEntity, 
--                       @YearID as YearID, @ServerID as ServerID
SELECT   IDENTITY(int, 1,1) AS ReciptItemID, ISNULL(@ReciptID, 0) AS ReciptID, ReciptItems.StuffCode, 
                      SUM(ISNULL(ReciptItems.InputEntity + ReciptItems.OutputEntity, 0)) AS OutputEntity, 
                      SUM(ISNULL(ReciptItems.InputWeight + ReciptItems.OutputWeight, 0)) AS OutputWeight, 
                      MAX(ISNULL(ReciptItems.UnitSellPrice, 0)) AS UnitSellPrice, 
                      SUM(ISNULL(ReciptItems.TotalInputPrice + ReciptItems.TotalOutputPrice, 0)) AS TotalOutputPrice,
                       SUM(ISNULL(ReciptItems.RequestedEntity, 0)) AS RequestedEntity, 
                       SUM(ISNULL(ReciptItems.RequestedWeight, 0)) AS RequestedWeight, 
                       SUM(ISNULL(ReciptItems.AcceptEntity, 0)) AS AcceptEntity,
                       SUM(ISNULL(ReciptItems.AcceptWeight, 0)) AS AcceptWeight, 
                       SUM(ISNULL(ReciptItems.RollbackEntity, 0)) AS RollbackEntity, 
                       @YearID as YearID, @ServerID as ServerID

            
INTO            __ReciptItems            
FROM    ReciptItems inner join Recipts on Recipts.ReciptID=ReciptItems.ReciptID  
           AND Recipts.ServerID = ReciptItems.ServerID 
           AND Recipts.YearID = ReciptItems.YearID
WHERE (Recipts.ParentReciptID = @ReciptID) and  (Recipts.YearID = @YearID) and
				          (Recipts.ServerID = @ServerID) 
GROUP BY  recipts.ParentReciptID, StuffCode

--ALTER TABLE __ReciptItems ADD  ReciptItemID int NOT NULL  IDENTITY(1,1)



INSERT INTO ReciptItems
 (ReciptItemID, ReciptID, StuffCode, OutputEntity,OutputWeight, UnitSellPrice, TotalOutputPrice ,
     RequestedEntity ,RequestedWeight,AcceptEntity,AcceptWeight,RollbackEntity, YearID, ServerID)
SELECT 
  ReciptItemID+@ReciptItemID , ReciptID, StuffCode, OutputEntity,OutputWeight, UnitSellPrice, TotalOutputPrice ,
     RequestedEntity ,RequestedWeight,AcceptEntity,AcceptWeight,RollbackEntity, YearID, ServerID
FROM __ReciptItems

END
