CREATE  FUNCTION InvoiceWithCash  
(	
	@ParentReciptID int, @ServerID int=0, @YearID int=88
)
RETURNS TABLE 
AS
RETURN 
(
SELECT      Recip.ParentReciptID, Recip.ReciptID, Recip.ServerID, Recip.YearID
   , Recip.UseUnitID, Recip.PersonID1, Recip.FormNumber, Recip.FormDate, Recip.Tel, Recip.CustName, 
                      Recip.Nakhales, Recip.RollBackPrice, Recip.Price, Cash.Price AS CashPrice, Checks.Cnt AS CheckCont, Checks.CheckPrice, 
					  DecExt.DeficatePrice - DeficitValue as DeficatePrice , 
                      Recip.TotallSellPrice - ISNULL(Cash.Price, 0) - ISNULL(Checks.CheckPrice, 0) + ISNULL(DecExt.DeficatePrice, 0) AS Balance,
    Recip.TotallSellPrice + ISNULL(DecExt.DeficatePrice, 0) as TotallSellPrice     
                      
FROM         (SELECT      Recipts.ParentReciptID, Recipts.ServerID, Recipts.YearID, Recipts.ReciptID, Recipts.UseUnitID, Recipts.PersonID1, Customers.CustName, 
                                              CASE recipttype WHEN 10 THEN Recipts.ReciptNumber WHEN 12 THEN cast(Recipts.AidNumber as int) ELSE 0 END AS FormNumber, 
                                              CASE recipttype WHEN 10 THEN Recipts.ReciptDate WHEN 12 THEN Recipts.AidDate ELSE '' END AS FormDate, Customers.Tel, 
                                              SUM(ReciptItems.AcceptWeight * ReciptItems.UnitSellPrice) AS Nakhales, SUM(ReciptItems.RollbackWeight * ReciptItems.UnitSellPrice) 
                                              AS RollBackPrice, SUM(ReciptItems.TotalInputPrice + ReciptItems.TotalOutputPrice) AS Price, 
                                               SUM(ReciptItems.TotalInputPrice + ReciptItems.TotalOutputPrice) 
											   -  Sum(ISNULL(DeficitValue,0)+ReciptItems.DeficitValue2+ReciptItems.DeficitValue4+ReciptItems.DeficitValue3) AS TotallSellPrice 
											   ,  Sum(ISNULL(DeficitValue,0)+ReciptItems.DeficitValue2+ReciptItems.DeficitValue4+ReciptItems.DeficitValue3)  as DeficitValue
                        FROM         Recipts INNER JOIN
                                              ReciptItems ON Recipts.ReciptID = ReciptItems.ReciptID AND Recipts.ServerID = ReciptItems.ServerID AND Recipts.YearID = ReciptItems.YearID INNER JOIN
                                              Customers ON Recipts.PersonID1 = Customers.CustID
                        WHERE (Recipts.ReciptType IN (10, 12)) and Recipts.ReciptState <3
                        GROUP BY Recipts.ParentReciptID, Recipts.ReciptID, Recipts.ServerID, Recipts.YearID, Recipts.UseUnitID, Recipts.PersonID1, Customers.CustName, Customers.Tel, 
                                              CASE recipttype WHEN 10 THEN Recipts.ReciptNumber WHEN 12 THEN cast(Recipts.AidNumber as int) ELSE 0 END, 
                                              CASE recipttype WHEN 10 THEN Recipts.ReciptDate WHEN 12 THEN Recipts.AidDate ELSE '' END) AS Recip LEFT OUTER JOIN
                          (SELECT      Forms_1.AidInfoNo, Forms_1.CustomerID2, COUNT(FormItems.CheckNumber) AS Cnt, SUM(FormItems.ItemAmount) 
                                                   AS CheckPrice
                             FROM         Forms AS Forms_1 INNER JOIN
                                                   FormItems ON Forms_1.FormID = FormItems.FormID
                                                   
AND Forms_1.ServerID = FormItems.ServerID AND Forms_1.YearID = FormItems.YearID                                                   

                             WHERE (Forms_1.FormType IN (10))
                             GROUP BY Forms_1.CustomerID2, Forms_1.AidInfoNo) AS Checks ON Recip.FormNumber = Checks.AidInfoNo AND 
                      Recip.PersonID1 = Checks.CustomerID2 LEFT OUTER JOIN
                          (SELECT      AidInfoNo, CustomerID2, SUM(Amount) AS Price
                             FROM         Forms
                             WHERE (FormType IN (1))
                             GROUP BY CustomerID2, AidInfoNo) AS Cash ON Recip.FormNumber = Cash.AidInfoNo AND Recip.PersonID1 = Cash.CustomerID2 LEFT OUTER JOIN
                          (SELECT      Recipts_1.ReciptID,Recipts_1.ServerID,Recipts_1.YearID, SUM(ReciptsDeficits.DeficitAdd - ReciptsDeficits.DeficitDec) AS DeficatePrice
                             FROM         Recipts AS Recipts_1 INNER JOIN
                                                   ReciptsDeficits ON Recipts_1.ReciptID = ReciptsDeficits.ReciptID
                                                   
AND Recipts_1.ServerID = ReciptsDeficits.ServerID AND Recipts_1.YearID = ReciptsDeficits.YearID                                                   
                                                   
                             GROUP BY Recipts_1.ReciptID,Recipts_1.ServerID,Recipts_1.YearID) AS DecExt ON Recip.ReciptID = DecExt.ReciptID
                             
                             AND Recip.ServerID = DecExt.ServerID AND Recip.YearID = DecExt.YearID                                                   

                             
WHERE Recip.ParentReciptID= @ParentReciptID AND Recip.ServerID= @ServerID AND Recip.YearID= @YearID
)
GO 
