CREATE FUNCTION GetLastReciptItems(@StuffCode bigint,@countCode int,@ResultKind as tinyint,@ReciptType int=36, @ReciptType1 int)
RETURNS 	Nvarchar(100)
BEGIN	
DECLARE @UnitSellPrice money
DECLARE @ReciptDate Nvarchar(10)
DECLARE @CustName Nvarchar(100)
DECLARE @InputEntity FLOAT

DECLARE @ID int
set @ID=1 
DECLARE @CursorVar CURSOR
SET @CursorVar = CURSOR SCROLL DYNAMIC
FOR 
SELECT  TOP 4 ISNULL(ReciptItems.UnitSellPrice,0), Recipts.ReciptDate, Customers.CustName, ReciptItems.InputEntity
FROM         Recipts INNER JOIN
                      ReciptItems ON Recipts.ReciptID = ReciptItems.ReciptID AND Recipts.ServerID = ReciptItems.ServerID AND Recipts.YearID = ReciptItems.YearID INNER JOIN
                      Customers ON Recipts.PersonID1 = Customers.CustID
WHERE ((Recipts.ReciptType = @ReciptType ) OR (Recipts.ReciptType = @ReciptType1)) 
              AND (ReciptItems.StuffCode = @StuffCode )
ORDER BY Recipts.ReciptDate DESC, Recipts.ReciptNumber DESC

OPEN @CursorVar
FETCH NEXT FROM @CursorVar INTO @UnitSellPrice, @ReciptDate, @CustName, @InputEntity
WHILE @@FETCH_STATUS = 0 and  @ID < @countCode
IF @ID= @countCode    BREAK
  ELSE 
  BEGIN
    FETCH NEXT FROM @CursorVar INTO @UnitSellPrice,@ReciptDate,@CustName, @InputEntity
    set @ID = @ID + 1
  END
CLOSE @CursorVar
DEALLOCATE @CursorVar
RETURN(CASE @ResultKind 
         WHEN 0 THEN 
           CAST(  (SELECT avg(UnitSellPrice) FROM (  SELECT  TOP 4 ISNULL(ReciptItems.UnitSellPrice,0)AS UnitSellPrice
             FROM Recipts INNER JOIN ReciptItems ON Recipts.ReciptID = ReciptItems.ReciptID AND Recipts.ServerID = ReciptItems.ServerID AND Recipts.YearID = ReciptItems.YearID INNER JOIN
             Customers ON Recipts.PersonID1 = Customers.CustID
             WHERE    ((Recipts.ReciptType = @ReciptType ) OR (Recipts.ReciptType = @ReciptType1)) 
                          AND (ReciptItems.StuffCode = @StuffCode )
             ORDER BY Recipts.ReciptDate DESC, Recipts.ReciptNumber DESC) AAA
             )--/@countCode   
               as Nvarchar(100)) 
         
         WHEN 1 THEN STR(@UnitSellPrice)
         WHEN 2 THEN @ReciptDate
         WHEN 3 THEN @CustName 
         WHEN 4 THEN CAST(@InputEntity AS Nvarchar(100)) END)
END
GO 
