CREATE  FUNCTION Benefit_Stuff  
(	
	@FindBackType int,
    @StoreIDFrom int = [0] ,@StoreIDTo int = [99999999] ,
	@StuffCodeFrom bigint =[0] ,@StuffCodeTo bigint =9999999999999999,
	@DateFrom varchar(10)=['88/01/01'] , @DateTo  varchar(10)=['88/12/30'] 
)
RETURNS TABLE 
AS
RETURN 
(
SELECT	ReciptItems.StuffCode, StuffCoding.c_StuffName, Units.UnitName,

		Sum(case when Recipts.ReciptType IN( 12, 44) then ReciptItems.OutputEntity else 0 end) as EntitySell ,  
		Sum(case when Recipts.ReciptType IN( 12, 44) then ReciptItems.OutputWeight else 0 end )as WeightSell ,  		
		Sum(case when Recipts.ReciptType IN( 12, 44) then ReciptItems.TotalOutputPrice else 0 end) as PriceSell ,
		Sum(case when Recipts.ReciptType = 11 then ReciptItems.TotalOutputPrice else 0 end) as PriceCost ,
		Sum(case when Recipts.ReciptType = 6 then ReciptItems.InputEntity else 0 end )as EntityBackSell ,  
		Sum(case when Recipts.ReciptType = 6 then ReciptItems.InputWeight else 0 end) as WeightBackSell ,  		
		Sum(case when Recipts.ReciptType = 6 then ReciptItems.TotalInputPrice else 0 end) as PriceBackSell ,
		Sum(case when @FindBackType=2 then 
			case when Recipts.ReciptType = 6 then ReciptItems.TotalInputPrice else 0 end  
		else 
			case when Recipts.ReciptType = 17 then ReciptItems.TotalInputPrice else 0 end  
		end ) as PriceBackCost ,
		Sum(ISNULL(Deficits.DeficitPrice / Deficits.price *
		(ReciptItems.TotalInputPrice+ ReciptItems.TotalOutputPrice),0)) as DeficitValue  , 
		Sum(case when Recipts.ReciptType IN( 12, 44) then ReciptItems.TotalOutputPrice else 0 end -
		case when Recipts.ReciptType = 6 then ReciptItems.TotalInputPrice else 0 end -
		case when Recipts.ReciptType = 11 then ReciptItems.TotalOutputPrice else 0 end +
		case when @FindBackType=2 then 
			case when Recipts.ReciptType = 6 then ReciptItems.TotalInputPrice else 0 end  
		else 
			case when Recipts.ReciptType = 17 then ReciptItems.TotalInputPrice else 0 end  
		end -
		ISNULL(Deficits.DeficitPrice / Deficits.price *
		(ReciptItems.TotalInputPrice+ ReciptItems.TotalOutputPrice),0)) as BeniefitPrice ,
		cast(
		Sum((
		case when Recipts.ReciptType IN( 12, 44) then ReciptItems.TotalOutputPrice else 0 end -
		case when Recipts.ReciptType = 6 then ReciptItems.TotalInputPrice else 0 end -
		case when Recipts.ReciptType = 11 then ReciptItems.TotalOutputPrice else 0 end +
		case when @FindBackType=2 then 
			case when Recipts.ReciptType = 6 then ReciptItems.TotalInputPrice else 0 end  
		else 
			case when Recipts.ReciptType = 17 then ReciptItems.TotalInputPrice else 0 end  
		end -
		ISNULL(Deficits.DeficitPrice / Deficits.price *
		(ReciptItems.TotalInputPrice+ ReciptItems.TotalOutputPrice),0)
		)) /
		Sum((
		case when 
		(
		case when Recipts.ReciptType = 11 then ReciptItems.TotalOutputPrice else 0 end +
		ISNULL(case when @FindBackType=2 then  
			case when Recipts.ReciptType = 6 then ReciptItems.TotalInputPrice else 0 end  
		else 
			case when Recipts.ReciptType = 17 then ReciptItems.TotalInputPrice else 0 end
		end ,0)
		)=0 then 1 else 

		case when Recipts.ReciptType = 11 then ReciptItems.TotalOutputPrice else 0 end +
		ISNULL(case when @FindBackType=2 then 
			case when Recipts.ReciptType = 6 then ReciptItems.TotalInputPrice else 0 end  
		else 
			case when Recipts.ReciptType = 17 then ReciptItems.TotalInputPrice else 0 end  
		end ,0)
		end 
		))*100    	as float)
		 as PercentBeniefit

		
FROM	ReciptItems INNER JOIN
		Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
		StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode LEFT OUTER JOIN
		(
		SELECT	Deficits.ReciptID , Deficits.DeficitPrice AS DeficitPrice , ReciptDeficits.price
		FROM	(
				SELECT	ReciptsDeficits.ReciptID, SUM(ReciptsDeficits.DeficitAdd + ReciptsDeficits.DeficitDec) AS DeficitPrice
				FROM	ReciptsDeficits INNER JOIN
						Deficits AS Deficits_1 ON ReciptsDeficits.DeficitID = Deficits_1.DeficitID
				WHERE (Deficits_1.DeficitType = 2)
				GROUP BY ReciptsDeficits.ReciptID) AS Deficits INNER JOIN
				(
				SELECT	Recipts.ReciptID, SUM(ReciptItems.TotalInputPrice + ReciptItems.TotalOutputPrice) AS price
				FROM	ReciptItems INNER JOIN
						Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID
				WHERE (Recipts.ReciptType IN (6, 11, 12, 17, 44)) AND (Recipts.ReciptState < 3)
				GROUP BY Recipts.ReciptID) AS ReciptDeficits ON Deficits.ReciptID = ReciptDeficits.ReciptID
		) AS Deficits ON ReciptItems.ReciptID = Deficits.ReciptID LEFT OUTER JOIN
		Units ON StuffCoding.n_UnitCode = Units.UnitCode
WHERE (Recipts.ReciptType IN (6, 11, 12, 17, 44)) and Recipts.Reciptstate<3
AND (Recipts.StoreID BETWEEN @StoreIDFrom AND  @StoreIDTo)  
AND (ReciptItems.StuffCode BETWEEN   @StuffCodeFrom AND @StuffCodeTo) 
AND (Recipts.ReciptDate BETWEEN @DateFrom  AND @DateTo) 
Group By ReciptItems.StuffCode, StuffCoding.c_StuffName, Units.UnitName 
) 
