CREATE  FUNCTION  [dbo].[InvoiceList_4_Pony]  
( @KindReport int =0 ,
  @FormNoFrom varchar (12)=[-9999999], @FormNoTo varchar (12)=[99999999] , 
  @DateFrom varchar(10)=[0], @DateTo varchar(10)=[99/99/99],
  @CalParamFrom  int=0 , @CalParamTo int=99999999 )
  
RETURNS table  AS  
RETURN (
SELECT     Recip.ParentReciptID, Recip.ReciptID, Recip.UseUnitID, Recip.PersonID1, Recip.Address, Recip.FormNumber, Recip.FormDate, Recip.Tel, 
                      Recip.CustName, Recip.Nakhales, Recip.RollBackPrice, Recip.Price, ReciptBack.BackPrice, Cash.Price AS CashPrice, Checks.Cnt AS CheckCont, 
                      Checks.CheckPrice, OtherTakhFif.Price AS OtherTakhfif, DecExt.DeficatePrice, Recip.Price - ISNULL(Cash.Price, 0) - ISNULL(Checks.CheckPrice, 0) 
                      + ISNULL(DecExt.DeficatePrice, 0) - ISNULL(ReciptBack.BackPrice, 0) - ISNULL(OtherTakhFif.Price, 0) AS Balance, Recip.PersonID2, 
                      Recip.CustName2, UseUnits.UseUnitName, Recip.SellsEmporium, Recip.SellsEmporiumName, Recip.SecondType
FROM         (SELECT     Recipts.ParentReciptID, Recipts.ReciptID, Recipts.UseUnitID, Recipts.PersonID1, Customers.CustName, Customers.Address, 
                                              Recipts.PersonID2, Customers_1.CustName AS CustName2, Recipts.SecondType,
                                              CASE Recipts.ReciptType WHEN 10 THEN Recipts.ReciptNumber ELSE cast(Recipts.AidNumber as int)END AS FormNumber, 
                                              Recipts.ReciptDate  FormDate, Customers.Tel, ISNULL(Recipts.SellsEmporium, 0) AS SellsEmporium, ISNULL(SellsEmporiums.SellsEmporiumName, '') AS SellsEmporiumName, 
                                              ISNULL(SUM(ReciptItems.AcceptWeight * ReciptItems.UnitSellPrice), 0) AS Nakhales, 
                                              ISNULL(SUM(ReciptItems.RollbackWeight * ReciptItems.UnitSellPrice), 0) AS RollBackPrice, 
                                              SUM(ReciptItems.TotalOutputPrice) AS Price
                  FROM         Recipts INNER JOIN
                      ReciptItems ON Recipts.ReciptID = ReciptItems.ReciptID AND Recipts.ServerID = ReciptItems.ServerID AND Recipts.YearID = ReciptItems.YearID INNER JOIN
                      Customers ON Recipts.PersonID1 = Customers.CustID INNER JOIN
                      ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType LEFT OUTER JOIN
                      Customers AS Customers_1 ON Recipts.PersonID2 = Customers_1.CustID LEFT OUTER JOIN
                      SellsEmporiums ON Recipts.SellsEmporium = SellsEmporiums.SellsEmporium
                        
                        
                        WHERE (Recipts.ReciptType IN (10) OR ReciptTypes.SellEffect = 1 ) AND (Recipts.ReciptState < 3)
                                   
                        GROUP BY Recipts.ParentReciptID, Recipts.ReciptID, Recipts.UseUnitID, Recipts.PersonID1, Customers.CustName, Customers.Tel, 
                                              Customers.Address, CASE Recipts.ReciptType WHEN 10 THEN Recipts.ReciptNumber ELSE cast(Recipts.AidNumber as int) END, 
                                               Recipts.ReciptDate , Recipts.PersonID2, Customers_1.CustName, Recipts.SellsEmporium,
                                                SellsEmporiums.SellsEmporiumName, Recipts.SecondType) 
                      AS Recip LEFT OUTER JOIN
                      UseUnits ON Recip.UseUnitID = UseUnits.UseUnitID LEFT OUTER JOIN
                          (SELECT     AidInfoNo, CustomerID1, SUM(Amount) AS Price
                             FROM         Forms AS Forms_2
                             WHERE (FormType IN (105))
                             GROUP BY CustomerID1, AidInfoNo) AS OtherTakhFif ON Recip.PersonID1 = OtherTakhFif.CustomerID1 AND 
                      Recip.FormNumber = OtherTakhFif.AidInfoNo LEFT OUTER JOIN
                          (SELECT     Recipts_2.PersonID1, Recipts_2.AidNumber, SUM(ReciptItems_1.TotalInputPrice) AS BackPrice
                             FROM         Recipts AS Recipts_2 INNER JOIN
                                                   ReciptItems AS ReciptItems_1 ON Recipts_2.ReciptID = ReciptItems_1.ReciptID
                             WHERE (Recipts_2.ReciptType = 6) AND (Recipts_2.ReciptState < 3)
                             GROUP BY Recipts_2.PersonID1, Recipts_2.AidNumber, Recipts_2.AidDate) AS ReciptBack ON Recip.FormNumber = cast(ReciptBack.AidNumber as int) AND 
                      Recip.PersonID1 = ReciptBack.PersonID1 LEFT OUTER JOIN
                          (SELECT     Forms_1.AidInfoNo, Forms_1.CustomerID2, COUNT(FormItems.CheckNumber) AS Cnt, SUM(FormItems.ItemAmount) AS CheckPrice
                             FROM         Forms AS Forms_1 INNER JOIN
                                                   FormItems ON Forms_1.FormID = FormItems.FormID
                             WHERE (Forms_1.FormType IN (10))
                             GROUP BY Forms_1.CustomerID2, Forms_1.AidInfoNo) AS Checks ON Recip.FormNumber = Checks.AidInfoNo AND 
                      Recip.PersonID1 = Checks.CustomerID2 LEFT OUTER JOIN
                          (SELECT     AidInfoNo, CustomerID2, SUM(Amount) AS Price
                             FROM         Forms
                             WHERE (FormType IN (1, 106))
                             GROUP BY CustomerID2, AidInfoNo) AS Cash ON Recip.FormNumber = Cash.AidInfoNo AND Recip.PersonID1 = Cash.CustomerID2 LEFT OUTER JOIN
                          (SELECT     Recipts_1.ReciptID, SUM(ReciptsDeficits.DeficitAdd - ReciptsDeficits.DeficitDec) AS DeficatePrice
                             FROM         Recipts AS Recipts_1 INNER JOIN
                                                   ReciptsDeficits ON Recipts_1.ReciptID = ReciptsDeficits.ReciptID
                             GROUP BY Recipts_1.ReciptID) AS DecExt ON Recip.ReciptID = DecExt.ReciptID
WHERE (Recip.ParentReciptID > 0) AND (Recip.FormNumber BETWEEN @FormNoFrom AND @FormNoTo) AND (ISNULL(Recip.FormDate, '0000/00/00') 
                      BETWEEN @DateFrom AND @DateTo) AND 
                      (CASE @KindReport WHEN 1 THEN Recip.PersonID1 WHEN 2 THEN Recip.PersonID2 WHEN 3 THEN ISNULL(Recip.UseUnitID, 0) WHEN 4 THEN ISNULL(Recip.SellsEmporium, 0) ELSE 0 END BETWEEN
                       @CalParamFrom AND @CalParamTo)
)

