CREATE VIEW CustomersUse
AS
SELECT     Customers.CustID, Customers.CustName, CustomersGroup.GroupType
FROM         (SELECT     CustomerID1
                        FROM         (SELECT     CustomerID1
                                                FROM         Forms
                                                GROUP BY CustomerID1
                                                UNION ALL
                                      SELECT     CustomerID2
                                                FROM         FormItems
                                                GROUP BY CustomerID2
                                                UNION ALL                                                
                                                
                                                SELECT     CustomerID2
                                                FROM         Forms AS Forms_1
                                                GROUP BY CustomerID2) AS abced
                        GROUP BY CustomerID1
                        UNION ALL
                        SELECT     PersonID1
                        FROM         Recipts
                        GROUP BY PersonID1) AS abcd INNER JOIN
                      Customers ON abcd.CustomerID1 = Customers.CustID INNER JOIN
                      CustomersGroup ON Customers.CustomerGrpID = CustomersGroup.CustomerGrpID
GROUP BY Customers.CustName, CustomersGroup.GroupType, Customers.CustID
HAVING      (Customers.CustID > 0)
