CREATE FUNCTION dbo.FindPart(@strInput VARCHAR(8000))
RETURNS @tblTemp TABLE (Number int )
AS 
BEGIN
   WHILE (CHARINDEX( ',', @strInput)<>0)
   BEGIN
       INSERT INTO @tblTemp(Number)
       SELECT SUBSTRING( @strInput, 1, CHARINDEX( ',', @strInput)-1)
    
       SET @strInput = SUBSTRING(@strInput, CHARINDEX( ',', @strInput)+1, LEN(@strInput)) 
   END
   INSERT INTO @tblTemp(Number)
   SELECT @strInput

   RETURN
END

