CREATE PROCEDURE [dbo].[NewTozin2Recipts] 
@TozinIDs varchar(8000),
@YearID int,
@ServerID int,
@ReciptID int OUTPUT as
DECLARE @ReciptNumber float
DECLARE @InEffectType int
DECLARE @OutEffectType int
DECLARE @Tozin_ID int

begin
DECLARE @T_TozinIDs Table(TozinID int)
 
INSERT INTO @T_TozinIDs(TozinID)  
SELECT Number FROM dbo.FindPart(@TozinIDs)

DECLARE @Temp int 
set @Tozin_ID=(SELECT top 1 TozinID FROM @T_TozinIDs)
set @Temp=(SELECT  max(ReciptNumber) FROM Tozin WHERE TozinID in(SELECT TozinID FROM @T_TozinIDs) )
if @Temp <>0 
begin
  RAISERROR ('براي سطر يا سطرهاي انتخاب شده فرم انبار ثبت شده است',16,1)
  RETURN 0
end 

SET @ReciptNumber=(SELECT MAX(Recipts.ReciptNumber) + 1 FROM Recipts INNER JOIN 
      Tozin ON Recipts.ReciptType = Tozin.ReciptType WHERE Tozin.TozinID = @Tozin_ID )


set @Temp=(SELECT ReciptTypes.RestartFormNumberOnStore FROM Tozin INNER JOIN ReciptTypes ON 
             Tozin.ReciptType = ReciptTypes.ReciptType WHERE Tozin.TozinID = @Tozin_ID 
                 GROUP BY ReciptTypes.RestartFormNumberOnStore)
if @Temp = 1 
SET     @ReciptNumber=(SELECT MAX(Recipts.ReciptNumber) + 1 FROM Recipts INNER JOIN
                         Tozin ON Recipts.ReciptType = Tozin.ReciptType AND Recipts.StoreID = Tozin.StoreID
                         WHERE     Tozin.TozinID = @Tozin_ID)

SET     @InEffectType=(SELECT     ReciptTypes.EffectType
                     FROM         Tozin INNER JOIN  ReciptTypes ON Tozin.ReciptType = ReciptTypes.ReciptType
                     WHERE (Tozin.TozinID = @Tozin_ID))

IF (@InEffectType>2) BEGIN   SET     @InEffectType=0  SET     @OutEffectType=1 end
  else               BEGIN   SET     @InEffectType=1  SET     @OutEffectType=0 end



SET     @ReciptID=(SELECT MAX(ReciptID)+1  FROM Recipts WHERE (ServerID= @ServerID) AND (YearID= @YearID))
INSERT INTO Recipts
                      (ReciptID, StoreID, ReciptNumber, ModifyDate, PersonID1, ReciptType, ReciptDate, ReciptNote, FirstUser, LastUser, MachineName, MachineNo
                      ,OperatorID, YearID, ServerID)
SELECT     @ReciptID AS Expr1, StoreID, @ReciptNumber, GETDATE() AS Expr4, PersonID1, ReciptType, TozinDate, TozinNote, FirstUser, LastUser, MachineName, 
                      MachineNo,127, @YearID, @ServerID
FROM         Tozin
WHERE (TozinID = @Tozin_ID ) and (ReciptNumber=0)


SELECT     @ReciptID AS ReciptID, StuffCode, @InEffectType * (MachineFullWeight - MachineWeight) AS InputEntity, 
                      @OutEffectType * (MachineFullWeight - MachineWeight) AS OutputEntity, @InEffectType * (MachineFullWeight - MachineWeight) AS InputWeight, 
                      @OutEffectType * (MachineFullWeight - MachineWeight) AS OutputWeight, FirstUser, LastUser, @YearID AS YearID, @ServerID AS ServerID
INTO            #ReciptItems
FROM         Tozin
WHERE (TozinID in(SELECT TozinID FROM @T_TozinIDs) )and (ReciptNumber=0)

declare @ReciptItemID int
set @ReciptItemID=(SELECT MAX(ReciptItemID) + 1 FROM ReciptItems WHERE (ServerID= @ServerID) AND (YearID= @YearID))

declare @qry Nvarchar(4000)
set @qry=' ALTER TABLE #ReciptItems ADD ReciptItemID INT IDENTITY('+STR(@ReciptItemID)+',1) '
exec(@qry)

INSERT INTO ReciptItems
      (ReciptItemID, ReciptID, StuffCode, InputEntity, OutputEntity, InputWeight, OutputWeight, 
       FirstUser, LastUser, YearID, ServerID)
SELECT ReciptItemID, ReciptID, StuffCode, InputEntity, OutputEntity, InputWeight, OutputWeight, 
       FirstUser, LastUser, YearID, ServerID
FROM   #ReciptItems

UPDATE Tozin SET   ReciptNumber= @ReciptNumber WHERE (TozinID in(SELECT TozinID FROM @T_TozinIDs) )

RAISERROR ('ثبت شد',16,1)
RETURN(@ReciptID)

end
