CREATE TRIGGER [dbo].[TR_AddressInMasir_MasirName]
On [dbo].[AddressInMasir]
For  Insert,UPDATE
As 
Begin
Declare @OldMasirID as int
set     @OldMasirID=0
Declare @MasirID as int
Declare @AddressID as int
Declare @MasirText as nvarchar(1000)
Declare @AddressName as nvarchar(80)
Declare @ParentID as int
-- set variable 
declare @Cnt as int 
select  @Cnt =  count(*) from inserted 

while (@Cnt <>0 ) 
begin 

select @AddressID = AddressID from Inserted WHERE MasirID>@OldMasirID
select @MasirID   = MasirID from Inserted WHERE MasirID>@OldMasirID

Select @MasirText = AddressName from AddressInfo WHERE AddressID= @AddressID
select @ParentID  = ParentID from AddressInfo WHERE AddressID= @AddressID

	while NOT (@ParentID is null )
	begin

		Select @AddressName = AddressName from AddressInfo WHERE AddressID= @ParentID
		Set @MasirText= @AddressName+ ' -> '+ @MasirText
							
		select @ParentID = ParentID from AddressInfo WHERE AddressID= @ParentID

	end --end while1

	set @Cnt= @cnt-1 

	UPDATE AddressInMasir
	set MasirText= @MasirText
	WHERE MasirID= @MasirID
	
	set @OldMasirID = @MasirID
	END -- while 2
END
