CREATE VIEW DeficitsCorrelationRecipts
AS
SELECT DISTINCT dbo.Recipts.ReciptID,dbo.Recipts.ServerID,dbo.Recipts.YearID, dbo.DeficitsCorrelation.DeficitID,
           ReciptItems.StuffCode,StuffCoding.GroupID--,Customers.CustID,Customers.CustomerGrpID
FROM         dbo.Recipts INNER JOIN
  dbo.ReciptItems ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID 
  AND ReciptItems.YearID = Recipts.YearID 
  --INNER JOIN  dbo.Customers ON dbo.Recipts.PersonID1 = dbo.Customers.CustID 
  INNER JOIN
  dbo.StuffCoding ON dbo.ReciptItems.StuffCode = dbo.StuffCoding.c_StuffCode INNER JOIN
  dbo.DeficitsCorrelation ON --dbo.Recipts.PersonID1 >= dbo.DeficitsCorrelation.CodeFrom AND 
  --dbo.Recipts.PersonID1 <= dbo.DeficitsCorrelation.CodeTo AND dbo.DeficitsCorrelation.Kind = 3 OR 
  dbo.StuffCoding.GroupID >= dbo.DeficitsCorrelation.CodeFrom AND dbo.StuffCoding.GroupID <= dbo.DeficitsCorrelation.CodeTo AND 
  dbo.DeficitsCorrelation.Kind = 0 --OR dbo.Customers.CustomerGrpID >= dbo.DeficitsCorrelation.CodeFrom AND 
  --dbo.Customers.CustomerGrpID <= dbo.DeficitsCorrelation.CodeTo AND dbo.DeficitsCorrelation.Kind = 2 
  OR 
  dbo.ReciptItems.StuffCode >= dbo.DeficitsCorrelation.CodeFrom AND dbo.ReciptItems.StuffCode <= dbo.DeficitsCorrelation.CodeTo AND 
  dbo.DeficitsCorrelation.Kind = 1 INNER JOIN
  dbo.Deficits ON dbo.DeficitsCorrelation.DeficitID = dbo.Deficits.DeficitID
WHERE (dbo.Recipts.ReciptDate BETWEEN dbo.Deficits.StartDate AND dbo.Deficits.EndDate)                      

