CREATE FUNCTION dbo.CreateTable(@MinNumber INT,@MaxNumber INT)
RETURNS @Table TABLE (Number INT)
AS 
BEGIN
  DECLARE @Id INT 
  SET @Id = @MinNumber
  WHILE  @Id <= @MaxNumber
  BEGIN
    INSERT INTO @Table(Number) VALUES (@Id)
    SET @Id = @Id + 1
  END  
  RETURN
END 
