CREATE PROCEDURE FindMissedReciptNum @ReciptType INT,@StoreID INT
AS   
  DECLARE @MinNumber INT
  DECLARE @MaxNumber INT
  SET @MinNumber=(SELECT MIN(ReciptNumber) FROM dbo.Recipts WHERE ReciptType= @ReciptType AND StoreID= @StoreID)
  SET @MaxNumber=(SELECT MAX(ReciptNumber) FROM dbo.Recipts WHERE ReciptType= @ReciptType AND StoreID= @StoreID)
  SELECT T.Number AS [شماره‏مرتب],ReciptNumber AS [شماره‏فرم] 
  FROM  (SELECT Number FROM dbo.CreateTable(@MinNumber,@MaxNumber))T 
         LEFT OUTER JOIN 
        (SELECT ReciptNumber FROM Recipts  WHERE (ReciptType= @ReciptType) AND (StoreID= @StoreID) ) R ON T.Number = R.ReciptNumber
ORDER BY T.Number
