CREATE TRIGGER [dbo].[TR_CheckDelRecipts]
ON [dbo].[Recipts]
INSTEAD OF DELETE
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Blocked TABLE (
        ReciptID   INT,
        ServerID   INT,
        YearID     INT,
        Reason     NVARCHAR(300)
    );

    ----------------------------------------------------------
    -- شرط ۱: استفاده در جدول Related (آنالیز مبلغ)
    ----------------------------------------------------------
    INSERT INTO @Blocked (ReciptID, ServerID, YearID, Reason)
    SELECT DISTINCT d.ReciptID, d.ServerID, d.YearID,
           N'[1] در جدول آنالیز مبلغ استفاده شده و قابل حذف نیست.'
    FROM Deleted d
    INNER JOIN Related r
        ON d.ReciptID = r.ParentID
    WHERE r.Kind IN (1, 2);

    ----------------------------------------------------------
    -- شرط ۲: اقلام ReciptItems در فرم‌های دیگر استفاده شده‌اند
    ----------------------------------------------------------
    INSERT INTO @Blocked (ReciptID, ServerID, YearID, Reason)
    SELECT DISTINCT d.ReciptID, d.ServerID, d.YearID,
           N'[2] حداقل یکی از اقلام این فرم در فرم‌های دیگر استفاده شده و قابل حذف نیست.'
    FROM Deleted d
    INNER JOIN ReciptItems ri
        ON ri.ReciptID = d.ReciptID
       AND ri.ServerID = d.ServerID
       AND ri.YearID = d.YearID
    WHERE EXISTS (
        SELECT 1
        FROM ReciptItems ri2
        WHERE ri2.preReciptItemID = ri.ReciptItemID
          AND ri2.ServerID = ri.ServerID
          AND ri2.YearID = ri.YearID
    );

    ----------------------------------------------------------
    -- شرط ۳: بررسی ارتباط پدر/فرزند در ParentReciptID
    -- شرط ۳: بررسی ارتباط پدر/فرزند واقعی با توجه به
    -- ParentReciptID + StepCorrelate + CorrelateReciptType
    ----------------------------------------------------------
	INSERT INTO @Blocked (ReciptID, ServerID, YearID, Reason)
	SELECT DISTINCT
		   d.ReciptID,
		   d.ServerID,
		   d.YearID,
		   N'[3] این فرم به عنوان پدر در فرم‌های مرتبط استفاده شده و قابل حذف نیست.'
	FROM Deleted d
	INNER JOIN ReciptTypes1 T
		ON d.ReciptType = T.ReciptType
	INNER JOIN Recipts r2
		ON r2.ServerID = d.ServerID
	   AND r2.YearID   = d.YearID
	   AND r2.ParentReciptID = d.ReciptID   
	WHERE
		T.CorrelateReciptType > 0
		AND
		(
			(T.StepCorrelate = 2 AND r2.ReciptID < d.ReciptID)

			OR

			(T.StepCorrelate = 1 AND r2.ReciptID > d.ReciptID)
		);

    ----------------------------------------------------------
    -- شرط ۴: استفاده در ParentCoReciptID (بدون منطق پدر/فرزند)
    ----------------------------------------------------------
    INSERT INTO @Blocked (ReciptID, ServerID, YearID, Reason)
    SELECT DISTINCT d.ReciptID, d.ServerID, d.YearID,
           N'[4] در فرم ضرائب استفاده شده و قابل حذف نیست.'
    FROM Deleted d
    INNER JOIN Recipts r3
        ON r3.ParentCoReciptID = d.ReciptID
       AND r3.ServerID = d.ServerID
       AND r3.YearID = d.YearID
       AND r3.ParentCoReciptID IS NOT NULL
       AND r3.ReciptID > d.ReciptID;

    ----------------------------------------------------------
    -- شرط ۵-۱۲: وجود رکورد در جداول فرزند داده شده
    ----------------------------------------------------------
    INSERT INTO @Blocked (ReciptID, ServerID, YearID, Reason)
    SELECT DISTINCT d.ReciptID, d.ServerID, d.YearID,
           N'[5] در جدول Costs مرتبط است و قابل حذف نیست.'
    FROM Deleted d
    INNER JOIN Costs c
        ON c.ReciptID = d.ReciptID
       AND c.ServerID = d.ServerID
       AND c.YearID = d.YearID;

    INSERT INTO @Blocked (ReciptID, ServerID, YearID, Reason)
    SELECT DISTINCT d.ReciptID, d.ServerID, d.YearID,
           N'[6] در جدول Insurances مرتبط است و قابل حذف نیست.'
    FROM Deleted d
    INNER JOIN Insurances i
        ON i.ReciptID = d.ReciptID
       AND i.ServerID = d.ServerID
       AND i.YearID = d.YearID;

    INSERT INTO @Blocked (ReciptID, ServerID, YearID, Reason)
    SELECT DISTINCT d.ReciptID, d.ServerID, d.YearID,
           N'[7] در جدول Negotiations مرتبط است و قابل حذف نیست.'
    FROM Deleted d
    INNER JOIN Negotiations n
        ON n.ReciptID = d.ReciptID
       AND n.ServerID = d.ServerID
       AND n.YearID = d.YearID;

    INSERT INTO @Blocked (ReciptID, ServerID, YearID, Reason)
    SELECT DISTINCT d.ReciptID, d.ServerID, d.YearID,
           N'[8] در جدول Proforma مرتبط است و قابل حذف نیست.'
    FROM Deleted d
    INNER JOIN Proforma p
        ON p.ReciptID = d.ReciptID
       AND p.ServerID = d.ServerID
       AND p.YearID = d.YearID;

    INSERT INTO @Blocked (ReciptID, ServerID, YearID, Reason)
    SELECT DISTINCT d.ReciptID, d.ServerID, d.YearID,
           N'[9] در جدول کسورات و اضافات ،ارتباط با خزانه ، نحوه پرداخت  یا اطلاعات صادرات/واردات  مرتبط است و قابل حذف نیست.'
    FROM Deleted d
    LEFT JOIN ReciptOnFormsRange rof ON rof.ReciptID = d.ReciptID AND rof.ServerID = d.ServerID AND rof.YearID = d.YearID
    LEFT JOIN ReciptsDeficits rd     ON rd.ReciptID  = d.ReciptID AND rd.ServerID  = d.ServerID AND rd.YearID  = d.YearID
    LEFT JOIN ReciptsPayments rp     ON rp.ReciptID  = d.ReciptID AND rp.ServerID  = d.ServerID AND rp.YearID  = d.YearID
    LEFT JOIN ReciptsTrades rt       ON rt.ReciptID  = d.ReciptID AND rt.ServerID  = d.ServerID AND rt.YearID  = d.YearID
    WHERE rof.ReciptID IS NOT NULL OR rd.ReciptID IS NOT NULL OR rp.ReciptID IS NOT NULL OR rt.ReciptID IS NOT NULL;

    ----------------------------------------------------------
    -- لاگ‌گیری قبل از حذف (در صورت وجود SP)
    ----------------------------------------------------------
    DECLARE @previousRowXmlValues XML;
    SET @previousRowXmlValues = (SELECT * FROM Deleted FOR XML AUTO);

    IF EXISTS (
        SELECT * FROM sysobjects
        WHERE id = OBJECT_ID(N'[dbo].[INsertTOLogFile]')
          AND OBJECTPROPERTY(id, N'IsProcedure') = 1
    )
    BEGIN
        EXEC INsertTOLogFile
            @previousRowXmlValues,
            NULL,
            'Recipts';
    END

    ----------------------------------------------------------
    -- حذف رکوردهای مجاز
    ----------------------------------------------------------
    DELETE FROM Recipts
    WHERE EXISTS (
        SELECT 1
        FROM Deleted d
        WHERE d.ReciptID = Recipts.ReciptID
          AND d.ServerID = Recipts.ServerID
          AND d.YearID = Recipts.YearID
          AND NOT EXISTS (
              SELECT 1
              FROM @Blocked b
              WHERE b.ReciptID = d.ReciptID
                AND b.ServerID = d.ServerID
                AND b.YearID = d.YearID
          )
    );

    ----------------------------------------------------------
    -- پیام‌های نهایی برای فرم‌های غیرقابل حذف
    -- با FOR XML PATH + .value('.', 'NVARCHAR(MAX)') برای جلوگیری از #x0D
    ----------------------------------------------------------
    IF EXISTS (SELECT 1 FROM @Blocked)
    BEGIN
        DECLARE @msg NVARCHAR(MAX);

        SELECT @msg = (
            SELECT Reason + NCHAR(13) + NCHAR(10)
            FROM @Blocked
            ORDER BY ReciptID
            FOR XML PATH(''), TYPE
        ).value('.', 'NVARCHAR(MAX)');

        RAISERROR(@msg, 16, 1);
        ROLLBACK TRANSACTION;
    END
END;
GO
