CREATE TRIGGER [dbo].[TR_CheckDelForms]
ON [dbo].[Forms]
FOR DELETE
AS
BEGIN
    SET NOCOUNT ON;

    -- شرط 1: آیا FormID در جدول Related با Kind=3 استفاده شده است؟
    IF EXISTS (
        SELECT 1
        FROM Deleted d
        INNER JOIN Related r 
            ON d.FormID = r.ParentID
        WHERE r.Kind = 3
    )
    BEGIN
        RAISERROR('این فرم در جدول آنالیز مبلغ استفاده شده و قابل حذف نیست.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    -- شرط 2: آیا FormID در ParentFormID سطرهای دیگر استفاده شده است؟
    IF EXISTS (
        SELECT 1
        FROM Deleted d
        WHERE EXISTS (
            SELECT 1
            FROM Forms f
            WHERE f.ParentFormID = d.FormID
              AND f.ServerID = d.ServerID
              AND f.YearID = d.YearID
        )
    )
    BEGIN
        RAISERROR('این فرم در سطرهای دیگری از طریق فراخوانی/فرم مرتبط استفاده شده و قابل حذف نیست.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END
END
