CREATE TRIGGER [dbo].[TR_CheckDelFormItems]
ON [dbo].[FormItems]
FOR DELETE
AS
BEGIN
    SET NOCOUNT ON;

    -- شرط 1: آیا در جدول Related استفاده شده است؟
    IF EXISTS (
        SELECT 1
        FROM Deleted d
        INNER JOIN Related r ON d.FormItemID = r.FormItemID
    )
    BEGIN
        RAISERROR('این رکورد در جدول آنالیز مبلغ استفاده شده و قابل حذف نیست.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    -- شرط 2: آیا FormItemID در preFormItemID سطرهای دیگر استفاده شده است؟
    IF EXISTS (
        SELECT 1
        FROM Deleted d
        WHERE EXISTS (
            SELECT 1
            FROM FormItems fi
            WHERE fi.preFormItemID = d.FormItemID
              AND fi.ServerID = d.ServerID
              AND fi.YearID = d.YearID
        )
    )
    BEGIN
        RAISERROR('این رکورد در سطرهای دیگری از طریق فراخوانی چکها استفاده شده و قابل حذف نیست.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END
END
	
