CREATE FUNCTION CalcControls (@StoreIDFrom int=0,@StoreIDTo int=99,
                                     @ReciptDateFrom Char(10)='0000/00/00' ,@ReciptDateTo Char(10)='9999/99/99' ,
                                     @StuffCodeFrom bigint=0 , @StuffCodeTo bigint=9999999999999999,
									 @YearID int=93)
RETURNS table  AS  
return (
SELECT  DISTINCT    Recipts.ReciptID, Recipts.StoreID, Recipts.ReciptNumber, Recipts.ReciptDate, ReciptTypes.ReciptCaption, Recipts.ReciptType, Recipts.DocNo, 
                      Recipts.DocDate, 'Main Form ' AS Kind, ReciptTypes.AutoPrice
FROM         Recipts INNER JOIN
                      ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType INNER JOIN
                      ReciptItems ON Recipts.ReciptID = ReciptItems.ReciptID AND Recipts.ServerID = ReciptItems.ServerID AND 
                      Recipts.YearID = ReciptItems.YearID
WHERE (   (ReciptTypes.EffectType = 4)  OR  (ReciptTypes.AutoPrice = 1))
AND (Recipts.DocNo <> 0)
AND (Recipts.StoreID BETWEEN @StoreIDFrom AND @StoreIDTo) 
AND (Recipts.ReciptDate BETWEEN @ReciptDateFrom AND @ReciptDateTo) 
AND (ReciptItems.StuffCode BETWEEN @StuffCodeFrom AND @StuffCodeTo)  
AND (ReciptItems.YearID = @YearID )
                      
UNION ALL

SELECT  DISTINCT    Recipts.ReciptID, Recipts.StoreID, Recipts.ReciptNumber, Recipts.ReciptDate, ReciptTypes.ReciptCaption, Recipts.ReciptType, 
                      ReciptsRegulates.RegDocNo, ReciptsRegulates.RegDocDate, 'Reg Form ' AS Kind, ReciptTypes.AutoPrice
FROM         Recipts INNER JOIN
                      ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType INNER JOIN
                      ReciptItems ON Recipts.ReciptID = ReciptItems.ReciptID AND Recipts.ServerID = ReciptItems.ServerID AND 
                      Recipts.YearID = ReciptItems.YearID INNER JOIN
                      ReciptsRegulates ON ReciptItems.ReciptItemID = ReciptsRegulates.ReciptItemID AND ReciptItems.ReciptID = ReciptsRegulates.ReciptID AND 
                      ReciptItems.ServerID = ReciptsRegulates.ServerID AND ReciptItems.YearID = ReciptsRegulates.YearID

WHERE ( (ReciptTypes.EffectType = 4)OR (ReciptTypes.AutoPrice = 1) )
AND (ReciptsRegulates.RegDocNo <> 0) 
AND (Recipts.StoreID BETWEEN @StoreIDFrom AND @StoreIDTo) 
AND (Recipts.ReciptDate BETWEEN @ReciptDateFrom AND @ReciptDateTo) 
AND (ReciptItems.StuffCode BETWEEN @StuffCodeFrom AND @StuffCodeTo)  
AND (ReciptItems.YearID = @YearID )
)
