CREATE FUNCTION StuffCodeTransEntity (  @YearIDFrom  int =88 , @YearIDTo int =88,
            @Date as Char(10) =[88/12/29]    )
RETURNS table  AS  
return (
SELECT     Recipts.StoreID, Stores.c_StoreName, Stores.n_ValuationType, ReciptItems.StuffCode, StuffCoding.c_StuffName,StuffCoding.c_StuffTecInfo,
         Units.UnitName,
         FirstEntity = sum( case when Recipts.ReciptType between 1 and 3  then  round(ReciptItems.InputEntity -ReciptItems.OutputEntity , 3 ) else 0 end) ,
         FirstWeight = sum( case when Recipts.ReciptType between 1 and 3  then  round(ReciptItems.InputWeight  -  ReciptItems.OutputWeight ,3)  else 0 end) ,

         FirstUnitSellPrice= case when
           sum( case when Recipts.ReciptType between 1 and 3  then  round(ReciptItems.InputEntity -ReciptItems.OutputEntity , 3 ) else 0 end) <>0
           then round(
           sum( case when Recipts.ReciptType between 1 and 3  then  round(ReciptItems.TotalInputPrice - ReciptItems.TotalOutputPrice ,3 )  else 0 end)
            /
           sum( case when Recipts.ReciptType between 1 and 3  then  round(ReciptItems.InputEntity -ReciptItems.OutputEntity , 3 ) else 0 end)
                   , 3 )  else 0 end ,

         FirstPrice  = sum( case when Recipts.ReciptType between 1 and 3  then  round(ReciptItems.TotalInputPrice - ReciptItems.TotalOutputPrice ,3 )  else 0 end) ,
         FirstSellPrice  = sum(  case when (Recipts.ReciptType between 1 and 3 ) then  round(ReciptItems.TotallsellPrice  ,3 )*
         (case when ReciptTypes.EffectType =2 then 1 else -1 end ) else 0 end) ,
         AddEntity   = sum( case when Recipts.ReciptType between 1 and 3  then  0 else round(ReciptItems.InputEntity , 3 ) end) ,
         AddWeight   = sum( case when Recipts.ReciptType between 1 and 3  then  0 else round(ReciptItems.InputWeight , 3 ) end) ,

         AddUnitSellPrice= case when
           sum( case when Recipts.ReciptType between 1 and 3  then  0 else round(ReciptItems.InputEntity , 3 ) end) <>0
           then round(
           sum( case when Recipts.ReciptType between 1 and 3  then  0 else round(ReciptItems.TotalInputPrice , 3 ) end)
            /
           sum( case when Recipts.ReciptType between 1 and 3  then  0 else round(ReciptItems.InputEntity , 3 ) end)
                   , 3 )  else 0 end ,

         AddPrice    = sum( case when Recipts.ReciptType between 1 and 3  then  0 else round(ReciptItems.TotalInputPrice , 3 ) end) ,
         AddSellPrice    = sum( case when ((Recipts.ReciptType >3 ) and (ReciptTypes.EffectType = 2))  then  round(ReciptItems.TotallsellPrice , 3 )  else 0  end) ,

         DecEntity   = sum( case when Recipts.ReciptType between 1 and 3  then  0 else round(ReciptItems.OutputEntity , 3 ) end) ,
         DecWeight   = sum( case when Recipts.ReciptType between 1 and 3  then  0 else round(ReciptItems.OutputWeight , 3 ) end) ,

         DecUnitSellPrice= case when
           sum( case when Recipts.ReciptType between 1 and 3  then  0 else round(ReciptItems.OutputEntity , 3 ) end) <>0
           then round(
           sum( case when Recipts.ReciptType between 1 and 3  then  0 else round(ReciptItems.TotalOutputPrice  , 3 ) end)
            /
           sum( case when Recipts.ReciptType between 1 and 3  then  0 else round(ReciptItems.OutputEntity , 3 ) end)
                   , 3 )  else 0 end ,

         DecPrice    = sum( case when Recipts.ReciptType between 1 and 3  then  0 else round(ReciptItems.TotalOutputPrice  , 3 ) end) ,
         DecSellPrice    = sum( case when (ReciptTypes.EffectType = 4)and (Recipts.ReciptType>3)  then round(ReciptItems.TotallsellPrice , 3 )  else 0 end) ,

	 InvEntity   = round(sum (ReciptItems.InputEntity - ReciptItems.OutputEntity  ), 3 ),
	 InvWeight   = round(sum( round(ReciptItems.InputWeight - ReciptItems.OutputWeight , 3 )),3),

         InvUnitSellPrice= case when
           round(sum (ReciptItems.InputEntity - ReciptItems.OutputEntity  ), 3 ) <>0
           then round(
           round(sum( round(ReciptItems.TotalInputPrice - ReciptItems.TotalOutputPrice , 3 )),3)
            /
           round(sum (ReciptItems.InputEntity - ReciptItems.OutputEntity  ), 3 )
                   , 3 )  else 0 end ,


	 InvPrice    = round(sum( round(ReciptItems.TotalInputPrice - ReciptItems.TotalOutputPrice , 3 )),3) ,
   InvSellPrice    = round(sum( round((case when  ReciptTypes.EffectType = 2 then 1 else -1 end ) *
                     ReciptItems.TotallsellPrice , 3 )),3),

                      ROUND(SUM(ReciptItems.InputEntity - ReciptItems.OutputEntity), 3) AS Entity, 
                      ROUND(SUM(ReciptItems.InputWeight - ReciptItems.OutputWeight), 3) AS Weight, 
                      SUM(ReciptItems.TotalInputPrice - ReciptItems.TotalOutputPrice) AS Price, 
                      SUM((CASE ReciptTypes.EffectType WHEN 2 THEN ReciptItems.TotallSellPrice ELSE - 1 * ReciptItems.TotallSellPrice END)) 
                      AS TotallSellPrice, 
	       max((CASE ReciptTypes.EffectType WHEN 2 THEN ReciptItems.UnitSellPrice ELSE 0 END)) 
                      AS MaxUnitPrice

FROM     ReciptItems INNER JOIN
         Recipts ON  ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID  INNER JOIN
         StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode INNER JOIN
         Stores ON Recipts.StoreID = Stores.n_StoreID INNER JOIN
         Units ON StuffCoding.n_UnitCode = Units.UnitCode INNER JOIN
         ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
WHERE (ReciptTypes.EffectType in ( 2 , 4)
          AND (StuffCoding.OwnerShipKind  in (0,1))
          AND (Recipts.ReciptState < 3) 
          AND (Recipts.yearID between @YearIDFrom And @YearIDTo ))
          AND (Recipts.ReciptDate <= @Date )          
GROUP BY Recipts.StoreID, Stores.c_StoreName, Stores.n_ValuationType, ReciptItems.StuffCode, StuffCoding.c_StuffName,StuffCoding.c_StuffTecInfo,
                      Units.UnitName
 
)
