CREATE FUNCTION FnRecallSpecial2 (@ReciptDateFrom Char(10)  , @ReciptDateTo Char(10)  )
RETURNS table  AS  
return (
SELECT	ReciptItems.ServerID ,ISNULL(ReciptItems.PrvYearID,ReciptItems.yearid ) as PrvYearID , ReciptItems.preReciptItemID, 
		SUM(ReciptItems.InputEntity - ReciptItems.OutputEntity) AS Entity, 
		SUM(ReciptItems.InputWeight - ReciptItems.OutputWeight) AS Weight, 
		SUM(ReciptItems.TotalInputPrice - ReciptItems.TotalOutputPrice) AS Price, 
		SUM(ReciptItems.TotallSellPrice) AS TotallSellPrice
FROM	ReciptItems INNER JOIN
		Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
		ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
WHERE	(ReciptTypes.EffectType in (2,6,4 ,7) ) 
		AND ReciptItems.preReciptItemID is not null 
		AND (Recipts.ReciptState < 3)
		AND (Recipts.ReciptDate BETWEEN @ReciptDateFrom AND @ReciptDateTo) 
GROUP BY ReciptItems.ServerID ,ISNULL(ReciptItems.PrvYearID,ReciptItems.yearid )  , ReciptItems.preReciptItemID
)
