CREATE FUNCTION S_F_GetColumnsName
(
	@TName varchar(100)	
)
RETURNS  varchar(4000)
AS
BEGIN

    DECLARE	 @Result varchar(4000)
    SET      @Result=''
	SELECT   @Result= @Result+', '+ syscolumns.name
	FROM     sysobjects INNER JOIN
			 syscolumns ON sysobjects.id = syscolumns.id
	WHERE   (sysobjects.xtype = 'U') AND (sysobjects.name = +@TName)
            AND UPPER(syscolumns.name)<> UPPER('ROWGUID') --- xusertype <> 36
			AND UPPER(syscolumns.name)<> UPPER('ID')
	ORDER BY syscolumns.colid
    SET      @Result=RIGHT(@Result, len(@Result)-1)
	RETURN   @Result
END
GO 
