CREATE PROCEDURE NewRecipts @OldReciptID int, @ServerID int=0, @YearID int=88,  @ReciptID int OUTPUT as
begin
set nocount on


DECLARE @Eslahi bit
SELECT @Eslahi = case when TAXID = '' then 0  else 1 end FROM Recipts WHERE (ReciptID = @OldReciptID )and(ServerID= @ServerID) AND (YearID= @YearID)

DECLARE @ReciptItemID int
declare   @Query varchar(8000) 
