CREATE PROCEDURE NewReciptsIrTax @OldReciptID int, @ServerID int=0, @YearID int=1403,  @ReciptID int OUTPUT as
begin
set nocount on
DECLARE @ID Bigint  
DECLARE @IRTAXID varchar(100)  --  پیدا کردن فاکتور فروش اصلی

SELECT  @IRTAXID = IRTAXID FROM  Recipts WHERE        (ReciptID = @OldReciptID)and (ServerID = @ServerID)and (YearID = @YearID)
 
DECLARE @irFound varchar(100)
SELECT @ID=id, @irFound=IRTAXID from Recipts WHERE 	(TAXID=@IRTAXID)
WHILE @irFound<>'' 
SELECT @ID=id,@irFound=IRTAXID from Recipts WHERE 	(TAXID=@irFound)

DECLARE @FoundReciptID int  
DECLARE @FoundServerID int  
DECLARE @FoundYearID int  
SELECT  @FoundReciptID = ReciptID ,@FoundServerID=ServerID ,@FoundYearID=YearID  FROM  Recipts WHERE (ID = @ID)

exec [dbo].[NewRecipts] @FoundReciptID , @FoundServerID , @FoundYearID ,  @ReciptID  OUTPUT 
 

RETURN(@ReciptID)
END
