CREATE PROCEDURE [dbo].[FlowAccount]
@BaseParam  VARCHAR(30),	
@CirculationCode VARCHAR(30),
@WHERE VARCHAR(2000)
AS 

BEGIN

	DECLARE @FinalSql VARCHAR(4000)
	DECLARE @SelectionField VARCHAR(1000)
	DECLARE @EffectTypes VARCHAR(1000)
	DECLARE @Temp VARCHAR(1000)
	
	SET @SelectionField = ''
	
	SELECT @SelectionField = @SelectionField + 'CAST ( '+ FieldName +' AS Varchar(30)) +''-''+' 
	FROM Util.Analyze INNER JOIN dbo.SplitString(@BaseParam,',') SP ON SP.part = Util.Analyze.ID 

	SET @SelectionField = LEFT(@SelectionField, LEN(@SelectionField)-5)
	
	IF(@WHERE = '')
	   SET @WHERE = 'WHERE ' + @SelectionField + '='''+ @CirculationCode+''''
	ELSE 
	   SET @WHERE = @WHERE + 'AND ' + @SelectionField + '=''' + @CirculationCode+'''';

	   
 
	SET @FinalSql ='SELECT R.ReciptID, R.ServerID, R.YearID, R.ReciptCaption, R.ReciptNumber,R.ReciptDate, R.StuffCode,StuffCoding.c_StuffName,StuffCoding.c_StuffTecInfo,Units.UnitName, '
                         + CHAR(13)+' R.InputEntity + R.OutputEntity AS Entity, R.InputWeight + R.OutputWeight AS Weight, CAST(R.TotalInputPrice + R.TotalOutputPrice as Money) AS Price, '
                         + CHAR(13)+' R.ProductCode, StuffCoding_Products.c_StuffName AS ProductName, R.PersonID1, C1.CustName AS CustName1, R.PersonID2, C2.CustName AS CustName2, R.PersonID3, C3.CustName AS CustName3'
                         + CHAR(13)+' FROM ReciptItems_Stock_Oper R INNER JOIN'
						 --+ CHAR(13)+' FROM Recipts INNER JOIN'
                         --+ CHAR(13)+' ReciptItems ON Recipts.ReciptID = R.ReciptID AND Recipts.ServerID = R.ServerID AND Recipts.YearID = R.YearID INNER JOIN'
                         --+ CHAR(13)+' ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType INNER JOIN'
                         + CHAR(13)+' StuffCoding ON R.StuffCode = StuffCoding.c_StuffCode INNER JOIN'
                         + CHAR(13)+' Customers AS C1 ON R.PersonID1 = C1.CustID INNER JOIN'
                         + CHAR(13)+' Customers AS C2 ON R.PersonID2 = C2.CustID INNER JOIN'
                         + CHAR(13)+' Customers AS C3 ON R.PersonID3 = C3.CustID LEFT OUTER JOIN'
                         + CHAR(13)+' LookUps AS L_ST ON R.SecondType = L_ST.LookUpID INNER JOIN'
                         + CHAR(13)+' Units ON StuffCoding.n_UnitCode = Units.UnitCode INNER JOIN'
                         + CHAR(13)+' StuffCoding AS StuffCoding_Products ON R.ProductCode = StuffCoding_Products.c_StuffCode'
					     + CHAR(13) + @WHERE
                         + CHAR(13)+' ORDER BY R.ReciptDate, R.ReciptNumber'

                      
    --PRINT (@FinalSql)
    EXEC (@FinalSql)
END
