CREATE FUNCTION dbo.DeficitsCorrelation3CustID (@CustID int ,@DeficitID int )
RETURNS int                                    /* */    
BEGIN
	DECLARE @ID int
	DECLARE @CustomerGrpID int
	SET @ID = @CustID
	
	--if @CustID = 0  RETURN(0)
	if (SELECT count(*) FROM DeficitsCorrelation WHERE Kind in  (2,3) AND DeficitID = @DeficitID   )= 0
	  RETURN(@ID)
	
	if (SELECT Top 1 DeficitID FROM DeficitsCorrelation
		 WHERE (Kind = 3) AND (CodeFrom >= @CustID) AND (CodeTo <= @CustID)  
			AND (DeficitID = @DeficitID )  )= @DeficitID
	BEGIN
	  RETURN(@ID)
	END
	  if (SELECT  Top 1  DeficitID FROM DeficitsCorrelation
		 WHERE (Kind = 3) AND (DeficitID = @DeficitID )  )= @DeficitID
		 BEGIN
	       SELECT @CustomerGrpID =CustomerGrpID FROM Customers WHERE CustID = @CustID
			if (SELECT  Top 1 DeficitID FROM DeficitsCorrelation
				 WHERE (Kind = 2) AND (CodeFrom >= @CustomerGrpID) AND (CodeTo <= @CustomerGrpID)  
					AND (DeficitID = @DeficitID )  )= @DeficitID
			BEGIN
			  RETURN(@ID)
			END
			  if (SELECT Top 1  DeficitID FROM DeficitsCorrelation
            		 WHERE (Kind = 2) AND (DeficitID = @DeficitID )  )= @DeficitID
              RETURN(0)
		 END 

	RETURN(0)

END

