CREATE FUNCTION [dbo].[Purchase_MinMaxForPerPerson] ( @DateFrom varchar(10)=['86/01/01'] , @DateTo  varchar(10)=['86/12/30'] ,
		     		@StoreIDFrom INT = [0] ,@StoreIDTo INT = [99999] ,
					@StuffCodeFrom varchar(10)=[0] , @StuffCodeTo  VARCHAR (30)=[999999999] ,
					@PersonID1From INT = [0], @PersonID1To INT = [999999999],
					@ReciptType VARCHAR (2)=[5] )
RETURNS TABLE  AS  
RETURN (
SELECT   ReciptItems.StuffCode, Recipts.StoreID, Recipts.PersonID1, MIN(Recipts.ReciptDate) AS MinDate, MAX(Recipts.ReciptDate) AS MaxDate, 
	     MIN(ReciptItems.UnitSellPrice) AS MinUnitPrice, MAX(ReciptItems.UnitSellPrice) AS MaxUnitPrice
FROM          ReciptItems INNER JOIN
                    Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID
WHERE      (Recipts.ReciptType = @ReciptType )  
	          AND (Recipts.ReciptDate BETWEEN @DateFrom  AND @DateTo )
	          AND (ReciptItems.StuffCode BETWEEN @StuffCodeFrom AND @StuffCodeTo )
	          AND (Recipts.StoreID BETWEEN @StoreIDFrom AND @StoreIDTo )
	          AND (Recipts.PersonID1 BETWEEN @PersonID1From AND @PersonID1To )
GROUP BY ReciptItems.StuffCode, Recipts.StoreID, Recipts.PersonID1
)

GO 
