CREATE FUNCTION GetPercentOfWeight (@Weight float = 5000)
RETURNS float 
begin
RETURN(case when @Weight between     0 and 2500  then 10
            when @Weight between  2500 and 5000  then 20
            when @Weight between  5000 and 7500  then 30
            when @Weight between  7500 and 10000 then 40
            when @Weight between 10000 and 12500 then 50
            when @Weight between 12500 and 15000 then 60
            when @Weight between 15000 and 17500 then 80
            when @Weight between 17500 and 20000 then 100
            when @Weight between 20000 and 22500 then 120
            when @Weight between 22500 and 25000 then 140
            when @Weight between 25000 and 27500 then 160
            when @Weight between 27500 and 30000 then 180
            when @Weight >       30000           then 200
            else 0 end
)  
end
