CREATE FUNCTION dbo.IntToTime(@DateTime DECIMAL(16,5))
RETURNS VARCHAR(10) 
AS  
BEGIN 
   DECLARE @IntDateTime VARCHAR(10)
   SET @IntDateTime = CAST(FLOOR(@DateTime) AS VARCHAR(10)) +':'+ CAST(FLOOR((@DateTime - FLOOR(@DateTime)) * 60) AS Varchar(10))    
   RETURN @IntDateTime
END
