CREATE FUNCTION dbo.TimeToInt(@DateTime DateTime)
RETURNS DECIMAL(16,5)
AS  
BEGIN 
   declare @IntDateTime DECIMAL(16,5)
   SET @IntDateTime = CAST({ fn HOUR(@DateTime) } AS DECIMAL(16, 5)) + CAST({ fn MINUTE(@DateTime) } AS DECIMAL(16, 5)) / 60 
   RETURN @IntDateTime
END
