CREATE PROCEDURE ReciptsSplit @OldReciptID int, @ServerID int=0, @YearID int=88,@SplitCount int =5,  @LastReciptID int OUTPUT as
begin
SET NOCOUNT ON
BEGIN TRANSACTION
DECLARE @ReciptID4c  AS INT
DECLARE @NewReciptID  AS INT
DECLARE @Jump  AS INT
DECLARE @ReciptType  AS INT

SET @LastReciptID= @OldReciptID

DECLARE @ReciptNumber  AS INT
SELECT @ReciptNumber=ReciptNumber,@ReciptType=ReciptType FROM Recipts
WHERE        (ReciptID = @OldReciptID) AND (ServerID = @ServerID) AND (YearID = @YearID)


declare   @Query varchar(8000)
declare   @ColumnsName varchar(8000)

DECLARE ReciptItems_CURSOR CURSOR FOR
SELECT ReciptID FROM ReciptItems
WHERE        (ReciptID = @OldReciptID) AND (ServerID = @ServerID) AND (YearID = @YearID)
ORDER BY ReciptItemID FOR UPDATE OF ReciptID
OPEN ReciptItems_CURSOR
FETCH NEXT FROM ReciptItems_CURSOR
INTO @ReciptID4c

DECLARE @FirstReciptID INT
SET @FirstReciptID = 1
WHILE (@FirstReciptID <= @SplitCount)
BEGIN
SET @FirstReciptID = @FirstReciptID + 1
FETCH NEXT FROM ReciptItems_CURSOR
INTO @ReciptID4c
END

SET @Jump= @SplitCount-1
SET @NewReciptID= @ReciptID4c
WHILE (@@FETCH_STATUS = 0)
BEGIN
	SET @Jump= @Jump+1
	if  @SplitCount- @Jump % @SplitCount= @SplitCount
	begin
		SET @ColumnsName = dbo.S_F_GetColumnsName('Recipts')
		set @Query='INSERT INTO Recipts  ('+@ColumnsName+')'

		SET @ColumnsName = REPLACE(@ColumnsName,' ReciptID,','')
		SET @LastReciptID=(SELECT MAX(ReciptID)+1 FROM Recipts WHERE (ServerID = @ServerID) AND (YearID = @YearID))
		SET @ColumnsName = REPLACE(@ColumnsName,' ModifyDate,',' GETDATE() AS ModifyDate,')
		SET @ReciptNumber=(SELECT MAX(ReciptNumber)+1 FROM Recipts WHERE (ServerID = @ServerID) AND (YearID = @YearID)
		                                                                 AND (ReciptType = @ReciptType)      )
		SET @ColumnsName = REPLACE(@ColumnsName,' ReciptNumber,',' '+STR(@ReciptNumber)+',')

		

		set @Query= @Query+
					' SELECT '+STR(@LastReciptID)+', '+@ColumnsName+'
					  FROM  Recipts WHERE (ReciptID = '+STR(@OldReciptID)+
					' AND ServerID = '+STR(@ServerID)+' AND YearID = '+STR(@YearID)+')'

		Exec (@Query)
    end
    UPDATE ReciptItems SET ReciptID = @LastReciptID WHERE CURRENT OF ReciptItems_CURSOR
    
    FETCH NEXT FROM ReciptItems_CURSOR
    INTO @ReciptID4c
END

CLOSE ReciptItems_CURSOR
DEALLOCATE ReciptItems_CURSOR

SET NOCOUNT OFF
COMMIT
RETURN(@LastReciptID)
END
