CREATE PROCEDURE dbo.NewTozin2Recipts2 @CorrelateORConversion Tinyint,@OldTozinID int, @ServerID int=0, @YearID int=88,  @ReciptID int OUTPUT as
DECLARE @ReciptNumber float
DECLARE @ReciptItemID int
DECLARE @ReciptType int
DECLARE @TozinCorrelateKind int
DECLARE @CorrelateKind int
DECLARE @InEffectType int
DECLARE @OutEffectType int
DECLARE @COUNTReciptID int
DECLARE @Factor int
DECLARE @ChangeAidReciptDate int
DECLARE @NewStoreID int
DECLARE @NewStoreID2 int
DECLARE @StepCorrelate int
DECLARE @Query VARCHAR(8000)='' 
DECLARE @ParentReciptID VARCHAR(20)

BEGIN
SET NOCOUNT ON

IF @CorrelateORConversion = 0
begin
  SELECT    @ReciptType= ReciptTypes1.CorrelateReciptType ,@TozinCorrelateKind =ReciptTypes1.CorrelateKind 
    FROM ReciptTypes1 INNER JOIN Tozin ON ReciptTypes1.ReciptType = tozin.ReciptType
    WHERE (Tozin.TozinID= @OldTozinID) 

  SET @COUNTReciptID=(SELECT COUNT(*)FROM Recipts 
                    WHERE (ParentReciptID= @OldTozinID) AND (ServerID= @ServerID) AND (YearID= @YearID)
						   AND (ReciptType = @ReciptType) )
  SET @ParentReciptID ='ParentReciptID'
end
ELSE
begin
  SELECT    @ReciptType= ReciptTypes1.ConversionCoSerial ,@TozinCorrelateKind =ReciptTypes1.CorrelateKind
    FROM ReciptTypes1 INNER JOIN Tozin ON ReciptTypes1.ReciptType = tozin.ReciptType
    WHERE (Tozin.TozinID= @OldTozinID) 

  SET @COUNTReciptID=(SELECT COUNT(*)FROM Recipts 
                    WHERE (ParentCoReciptID= @OldTozinID) AND (ServerID= @ServerID) AND (YearID= @YearID)
						   AND (ReciptType = @ReciptType) )
  SET @ParentReciptID ='ParentCoReciptID'

end

if @COUNTReciptID>0  
begin
  --raiserror('براي اين فرم فرم مرتبط ثبت شده',16,1)
  --commit TRANSACTION NewRecipt;
  RETURN 0
end 

--if (SELECT COUNT(*) FROM Util.CodesInProcess)>0  
--begin
--  --commit TRANSACTION NewRecipt;
--  raiserror('كليه كاربران از سيستم خارج شوندو دوباره سعي كنيد',16,1)
--  RETURN 0
--end 

SET @StepCorrelate=(SELECT ReciptTypes.StepCorrelate FROM Tozin INNER JOIN
      ReciptTypes ON Tozin.ReciptType = ReciptTypes.ReciptType
      WHERE (Tozin.TozinID = @OldTozinID)  )

if (@StepCorrelate<>1)
  SET     @ReciptID= @OldTozinID - 1
else
  SET     @ReciptID=(SELECT ISNULL(MAX(ReciptID),0)+1 FROM Recipts WHERE (ServerID= @ServerID) AND (YearID= @YearID))
  
SET     @ReciptNumber=(SELECT TozinNumber FROM Tozin 
    WHERE (Tozin.TozinID = @OldTozinID) )

SELECT @NewStoreID2=StoreID,@NewStoreID=StoreID FROM Tozin
                  WHERE (Tozin.TozinID = @OldTozinID)
                  
if @NewStoreID=0 
begin                   
set @NewStoreID= @NewStoreID2
set @NewStoreID2=0
end

SET     @CorrelateKind=(SELECT     ReciptTypes.CorrelateKind
                     FROM         Tozin INNER JOIN  ReciptTypes ON Tozin.ReciptType = ReciptTypes.ReciptType
                     WHERE (Tozin.TozinID = @OldTozinID) )
if @CorrelateKind=0  
begin
  RETURN 0
  --commit TRANSACTION NewRecipt;
end
--0 ندارد 1 ثبت در وارده‏ها با مبلغ 3- ثبت در وارده‏ها بدون مبلغ 4  ثبت در صادره‏ها با مبلغ5 ثبت در صادره‏ها بدون مبلغ
--SET     @InEffectType=(SELECT     ReciptTypes.EffectType
--                     FROM         Recipts INNER JOIN  ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
--                     WHERE (Recipts.ReciptID = @OldTozinID))

IF (@CorrelateKind>2) BEGIN  SET     @InEffectType=0  SET     @OutEffectType=1 end
  else               BEGIN   SET     @InEffectType=1  SET     @OutEffectType=0 end

set @Factor=(SELECT
case @CorrelateKind 
         WHEN 1 THEN 1
         WHEN 2 THEN 0
         WHEN 3 THEN 1
         WHEN 4 THEN 0
         WHEN 5 THEN 1
      END)

declare   @ShowNotEntityOnSearch int
declare   @RecuestActive int


SELECT    @ChangeAidReciptDate= ReciptTypes.ChangeAidReciptDate , @ShowNotEntityOnSearch= ReciptTypes.ShowNotEntityOnSearch
,@RecuestActive=RecuestActive
                     FROM         Tozin INNER JOIN  ReciptTypes ON Tozin.ReciptType = ReciptTypes.ReciptType
                     WHERE (Tozin.TozinID = @OldTozinID)

--if (@ChangeAidReciptDate>0) set @Query='AidDate,ReciptDate,'
--  else  
--      begin
--        if (@ShowNotEntityOnSearch &  32 <> 0) 
--         set @Query=''''+RIGHT( dbo.MiladiToShamsi(GETDATE()),10) + ''' AS ReciptDate,AidDate,'
--        else
--         set @Query='ReciptDate,AidDate,'
--      end


set @Query='INSERT INTO Recipts
  (ReciptID, StoreID, ReciptNumber, '+@ParentReciptID+',TozinID , ReciptDate,DefaultDate,ReciptDateMiladi , ModifyDate,InsertDate,  PersonID1, PersonID2,PersonID3,PersonID4,PersonID5,OperatorID, ReciptType, 
  FirstUser, LastUser, MachineNo, MachineName, ServerID, YearID,UseUnitID, UseOtherID,ReciptNote,AidNumber,AidDate,TruckNumber,MasirID
  )
SELECT '+STR(@ReciptID)+', '+STR(@NewStoreID)+', '+STR(@ReciptNumber)+', '+STR(@OldTozinID)+','+STR(@OldTozinID)+', TozinDate,TozinDate AS DefaultDate,dbo.ShamsiToMiladi(TozinDate) AS  ReciptDateMiladi ,
 GETDATE(),GETDATE(), PersonID1, PersonID2,PersonID3, PersonID4,PersonID5,999999999 as OperatorID, '+STR(@ReciptType)+', 
 FirstUser, LastUser,  MachineNo, MachineName,'+STR(@ServerID)+', '+STR(@YearID)+',0 as UseUnitID,0 as UseOtherID,TozinNote,TozinNumber,TozinDate,TozinNumber,MasirID
 FROM  Tozin WHERE (TozinID = '+STR(@OldTozinID)+')'


 
Exec (@Query)

if @TozinCorrelateKind<>0
BEGIN

SET     @ReciptItemID=  (SELECT ISNULL(MAX(ReciptItemID),0)+1  FROM ReciptItems WHERE (ServerID= @ServerID) AND (YearID= @YearID))

	INSERT INTO ReciptItems
						  (ReciptItemID, ReciptID, StuffCode, InputEntity, OutputEntity, InputWeight, OutputWeight,  ItemNote,  PersonID1
						  , FirstUser, LastUser,  YearID, ServerID, MachineWeight,  MachineNo, MachineName, MachineFullWeight
)
	SELECT   case when (@StepCorrelate<>1) then  TozinID - 1 else @ReciptItemID  end  AS ReciptItemID
	  , @ReciptID AS ReciptID, StuffCode,  
	                     case when(@RecuestActive &    256 <> 0) --CHKMachineEntity
                         then
						 @InEffectType  * ISNULL(NumberOfBags,0) 
						 else  @InEffectType  * ISNULL(MachineEntity,0) end 
						 AS InputEntity, 
					      case when(@RecuestActive &    256 <> 0) --CHKMachineEntity
                         then
						 @OutEffectType * ISNULL(NumberOfBags,0) 
						 else  @OutEffectType  * ISNULL(MachineEntity,0) end 
						   AS OutputEntity, 
						  @InEffectType * (((MachineFullWeight -  MachineWeight) -  case when (MoistureContent + RisingUseful + RisingNonUseFul) <> 0 
		                                                       then  (100 - (MoistureContent + RisingUseful + RisingNonUseFul)) else 0 end )) AS InputWeight, 
						  @OutEffectType * (((MachineFullWeight -  MachineWeight) -  case when (MoistureContent + RisingUseful + RisingNonUseFul) <> 0 
		                                                       then  (100 - (MoistureContent + RisingUseful + RisingNonUseFul)) else 0 end )) AS OutputWeight, 

						  TozinNote AS ItemNote,  PersonID1, FirstUser, LastUser, 
						   @YearID,  @ServerID,  MachineWeight,  
						  MachineNo, MachineName, MachineFullWeight


	FROM         Tozin 
	WHERE (Tozin.TozinID = @OldTozinID)
END

IF @CorrelateORConversion = 0
begin
  UPDATE Recipts SET   ParentReciptID= @ReciptID WHERE (ReciptID = @OldTozinID)AND (ServerID= @ServerID) AND (YearID= @YearID)
end
ELSE
begin
  UPDATE Recipts SET   ParentCoReciptID= @ReciptID WHERE (ReciptID = @OldTozinID)AND (ServerID= @ServerID) AND (YearID= @YearID)
end

 RETURN(@ReciptID)


END
