CREATE  FUNCTION  ReciptsListRegulates  ( @ReciptTypeChecked varchar(100)='5,12',
  @NumberFrom int=-9999999, @NumberTo int=99999999 , 
  @DateFrom char(10)='0000/00/00', @DateTo char(10)='9999/99/99',
  @StoreFrom smallint=-999,  @StoreTo smallint=999,
  @States varchar(20) ='0,1,2,3,4,5' ,
  @YearIDFrom int=96 , @YearIDTo int=96
)
  
RETURNS table  AS  
return (
SELECT        ReciptsRegulates.ServerID, ReciptsRegulates.YearID, ReciptsRegulates.RegRowId, Recipts.ReciptNumber,Recipts.ReciptNumberFormer , Recipts.ReciptDate, Recipts.ReciptState, RISUM.price, Recipts.StoreID, Stores.c_StoreName, 
                         Stores.c_StoreName AS _StoresName, Recipts.ReciptType, Recipts.ReciptNote, ROUND(RISUM.Entity, 4) AS Entity, ROUND(RISUM.Weight, 4) AS Weight, Recipts.DocNo, Recipts.DocDate, RISUM.TotallSellPrice, 
                         ReciptTypes.ReciptCaption, ReciptsRegulates.RegDate, ReciptsRegulates.RegPrice, ReciptsRegulates.RegDocNo, ReciptsRegulates.RegDocDate
FROM            Recipts INNER JOIN
                         ReciptsRegulates ON Recipts.ReciptID = ReciptsRegulates.ReciptID AND Recipts.ServerID = ReciptsRegulates.ServerID AND Recipts.YearID = ReciptsRegulates.YearID LEFT OUTER JOIN
                         ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType LEFT OUTER JOIN
                         ReciptItemSum AS RISUM ON Recipts.ReciptID = RISUM.reciptid AND Recipts.ServerID = RISUM.serverid AND Recipts.YearID = RISUM.yearid LEFT OUTER JOIN
                         Stores ON Recipts.StoreID = Stores.n_StoreID

WHERE 
    (','+@ReciptTypeChecked+',' LIKE N'%,'+LTRIM(STR(Recipts.ReciptType))+',%') 
AND (Recipts.ReciptNumber BETWEEN @NumberFrom AND @NumberTo)
AND (Recipts.ReciptDate BETWEEN @DateFrom AND @DateTo)
AND (Recipts.StoreID BETWEEN   @StoreFrom AND @StoreTo )
AND (','+@States+',' LIKE N'%,'+LTRIM(STR(Recipts.ReciptState))+',%')
AND (Recipts.YearID BETWEEN @YearIDFrom AND @YearIDTo )

)

