CREATE FUNCTION GetTariffsID (@StuffCode bigint , @StuffDiameter  float ,@StuffSize varchar(12) )
RETURNS varchar(15) 
begin
declare @CoilSheet tinyint
if @StuffCode in (11,21,31,41,61)
    set @CoilSheet=2
	else 
	begin
       if CHARINDEX('*', @StuffSize )=0 
         set @CoilSheet=1
       else
         set @CoilSheet=0
    end


    
RETURN(
SELECT  top 1      TariffsID
FROM            Tariffs
WHERE        (StuffCode = @StuffCode) AND
 (CoilSheet = @CoilSheet) AND (  @StuffDiameter BetWeen  StuffDiameterFrom  AND StuffDiameterTo )
)

end

