CREATE FUNCTION [dbo].[GetTransFormItemsCo] ( @StuffCodeproduct bigint=0 , @StuffCodeMavad bigint=0 ,@TransFormID int)
RETURNS float                                                
begin
  DECLARE @Entity  float  
SELECT     @Entity =    SUM(TransFormItems.Entity) 
FROM            TransFormItems INNER JOIN
                         TransForms ON TransFormItems.TransFormID = TransForms.TransFormID
WHERE        (TransForms.StuffCode = @StuffCodeproduct) --AND (TransForms.TransFormNo = @TransFormNo)
AND  (TransFormItems.StuffCode = @StuffCodeMavad) AND (TransFormItems.TransFormID = @TransFormID)
RETURN(ISNULL( @Entity,0))
end
