CREATE FUNCTION GetTransFormItems (@ReciptType int=9 ,@YearID  int =98 , @StuffCodeproduct bigint=0 
, @StuffCodeMavad bigint=0,@TransFormNo bigint=0 , @DateFrom char(10)='1000/01/01', @DateTo char(10)='9000/01/01')
RETURNS money                                                
begin
  DECLARE @OutputEntity  float

SELECT    @OutputEntity =sum(ReciptItems.OutputEntity)
FROM            Recipts INNER JOIN
                         ReciptItems ON Recipts.ReciptID = ReciptItems.ReciptID AND Recipts.ServerID = ReciptItems.ServerID AND Recipts.YearID = ReciptItems.YearID INNER JOIN
                         (SELECT DISTINCT StuffCode,TransFormID FROM TransFormItems )TransFormItems --  علت تعریف دو کالای تکرای در فرمول با دو مقدار متفادت
						 ON ReciptItems.StuffCode = TransFormItems.StuffCode AND ReciptItems.TransFormID = TransFormItems.TransFormID INNER JOIN
                         TransForms ON TransFormItems.TransFormID = TransForms.TransFormID
WHERE        (Recipts.ReciptType = @ReciptType) AND (Recipts.YearID = @YearID)
  AND (ReciptItems.StuffCode = @StuffCodeMavad)
AND (TransForms.StuffCode = @StuffCodeproduct) and (transforms.TransFormNo=@TransFormNo)
  AND (Recipts.ReciptDate BETWEEN @DateFrom AND @DateTo )

group by  ReciptItems.StuffCode,TransForms.TransFormNo
ORDER BY ReciptItems.StuffCode 
  

RETURN(ISNULL( @OutputEntity,0))
end
