SELECT    @OldFormID= Forms.FormID ,  @ServerID= Forms.ServerID ,  @YearID= Forms.YearID 
 FROM Forms   WHERE (Forms.ID= @OldID) 


SELECT    @CorrelateFormType= FormTypes.CorrelateFormType --,@CorrelateServerID=FormTypes.ChangeAidFormDate,@PriceCo=FormTypes.PriceCo    , @Correlate4EditActive = Correlate4EditActive
