						   AND (FormType = @CorrelateFormType) )



--SET @COUNTFormID=(SELECT COUNT(*)FROM Forms 
--                    WHERE   ( FormID IN(SELECT ParentFormID FROM Forms 
--                           WHERE (FormID= @OldFormID) AND (ServerID= @ServerID) AND (YearID= @YearID)
--						   AND (FormType = @CorrelateFormType)
--						   ))
--                           AND (ServerID= @ServerID) AND (YearID= @YearID) 
						   
--						   AND ( ParentFormID= @OldFormID)
						   
--						    )


if @COUNTFormID>0  
begin
  --raiserror('براي اين فرم فرم مرتبط ثبت شده',16,1)
  --commit TRANSACTION NewForm;
  RETURN (0)
end 

if (@StepCorrelate<>1)
  SET     @FormID= @OldFormID - 1
else
     --if (((@CorrelateServerID & 2)) <> 0) 
   begin
      SET     @FormID=(SELECT MAX(FormID)+1 FROM Forms WHERE (ServerID= @NewServerID) AND (YearID= @YearID))
   end
   -- else
   --begin
   --   SET     @FormID=(SELECT MAX(FormID)+1 FROM Forms WHERE (ServerID= @ServerID) AND (YearID= @YearID))
   --end

if @ID<>0 set  @FormID= @ID
  
SET     @FormNumber=(SELECT FormNumber FROM Forms 
    WHERE (FormID = @OldFormID)AND (ServerID= @ServerID) AND (YearID= @YearID))


SET     @FormType=(SELECT     FormTypes.CorrelateFormType
                     FROM         Forms INNER JOIN  FormTypes ON Forms.FormType = FormTypes.FormType
                     WHERE (Forms.FormID = @OldFormID)AND (ServerID= @ServerID) AND (YearID= @YearID))




if @COUNTFormID=0
begin
INSERT INTO Forms
  (FormID, FormType, FormNumber,ParentFormID , FormDate, CustomerID1, CustomerID2, Amount, BudgetCode, ProjectID, TopicCode, DetailCode, CTopicCode, FomNote, AidInfoNo, AidInfoDate, CTopicCode2, CustomerName2, 
  PayTypes, TopicTypes,  FormState, ModifyDate,  ManegerNote, CashCheckFormID, SubAmount, Rate,  ServerID, YearID, SellsMethod, SellsEmporium, DefaultDate, 
  CustomerID3, Transmittal, RelatedRecipts, AidFormType, CTopicCode3, ArzTypeID, ArzAmount, ArzRate, LoansFormID, GuaranteesFormID, AidInfoNo2, AidInfoDate2,  UserRegistrationDoc, DefaultDuration, 
  OperatorID, TruckNumber, CustomerID4, ArzAmountExchange, ArzRateExchange, ArzTypeIDExchange,  PO, MachineNo, CostFactorsType, CostFactorsCode, InsertDate,FirstUser  )
SELECT @FormID, @CorrelateFormType , @FormNumber , @OldFormID , 
 dbo.miladitoshamsi (GETDATE()) FormDate, CustomerID1, CustomerID2, Amount, BudgetCode, ProjectID, TopicCode, DetailCode, CTopicCode, FomNote, AidInfoNo, AidInfoDate, CTopicCode2, CustomerName2, 
  PayTypes, TopicTypes, 0 FormState, GETDATE()  ModifyDate,  ManegerNote, CashCheckFormID, SubAmount, Rate,  ServerID, YearID, SellsMethod, SellsEmporium, DefaultDate, 
  CustomerID3, Transmittal, RelatedRecipts, AidFormType, CTopicCode3, ArzTypeID, ArzAmount, ArzRate, LoansFormID, GuaranteesFormID, AidInfoNo2, AidInfoDate2,  UserRegistrationDoc, DefaultDuration, 
  OperatorID, TruckNumber, CustomerID4, ArzAmountExchange, ArzRateExchange, ArzTypeIDExchange,  PO, MachineNo, CostFactorsType, CostFactorsCode,GETDATE() InsertDate,@FirstUser 
 FROM  Forms WHERE (FormID = @OldFormID  AND ServerID = @ServerID  AND YearID = @YearID )

SELECT @ID =ID
 FROM  Forms WHERE (FormID = @FormID  AND ServerID = @ServerID  AND YearID = @YearID)

 end

  RETURN(1)





