CREATE VIEW YearCustomerSellPrice 
AS
SELECT     TOP 100 PERCENT AccCustomer.PersonID1, SUM(AccCustomer.bed - AccCustomer.bes) AS balance
FROM         (SELECT     PersonID1, ReciptID, reciptType, ReciptNumber, ReciptDate, ReciptCaption, ItemNote, bed, bes, kind
                        FROM         (SELECT     *
                                                FROM         CustomerTrancationsItemsSellPrice
                                                UNION ALL
                                                SELECT     *
                                                FROM         cashTransactionItemsCust) custTransaction
                        UNION ALL
                        SELECT     CustID, 0 AS ReciptID, 0 AS recipttype, 0 AS ReciptNumber, '' AS ReciptDate, ' ' AS ReciptCaption, ' نقل از قبل ' AS ReciptNote, SUM(bed) 
                                              AS bed, SUM(bes) AS bes, 0 AS kind
                        FROM         (SELECT     CustID, 0 AS ReciptID, 0 AS recipttype, 0 AS ReciptNumber, '' AS ReciptDate, ' ' AS ReciptCaption, ' نقل از قبل' AS ReciptNote, 
                                                                      firstBalance AS bed, 0 AS bes, 0 AS kind
                                                FROM         customers
                                                WHERE     firstBalance > 0
                                                UNION ALL
                                                SELECT     CustID, 0 AS ReciptID, 0 AS recipttype, 0 AS ReciptNumber, '' AS ReciptDate, ' ' AS ReciptCaption, ' نقل از قبل ' AS ReciptNote, 
                                                                      0 AS bed, - 1 * firstBalance AS bes, 0 AS kind
                                                FROM         customers
                                                WHERE     firstBalance < 0) firstBalance
                        GROUP BY CustID) AccCustomer LEFT OUTER JOIN
                      Customers ON AccCustomer.PersonID1 = Customers.CustID
GROUP BY AccCustomer.PersonID1
ORDER BY AccCustomer.PersonID1
