CREATE FUNCTION ReMainPerson (@FormID int=1, @ServerID int=0, @YearID int=88 ,@FormDate varchar(20)=[99/99/99],@PersonID varchar(20))
RETURNS money 
begin
DECLARE @ReMain money
set @ReMain=(SELECT sum(Bed)-sum(Bes) as ReMain
 from(
(SELECT Recipts.PersonID1 as PersonID,
       sum((CASE ReciptTypes.BedType WHEN 1 THEN  ReciptItems.TotalInputPrice+ReciptItems.TotalOutputPrice
                                    ELSE 0 END)) as Bed, 
       sum((CASE ReciptTypes.BesType WHEN 1 THEN  ReciptItems.TotalInputPrice+ReciptItems.TotalOutputPrice
                                    ELSE 0 END)) as Bes
FROM ReciptItems INNER JOIN
     Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
     ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
WHERE ((ReciptTypes.BedType = 1) OR (ReciptTypes.BesType = 1))--And(Recipts.ReciptID<>:ReciptID)
      And(Recipts.ReciptState<3)
GROUP BY Recipts.PersonID1)
union all
(SELECT  Forms.CustomerID1 as PersonID,
       sum((CASE  FormTypes.BedBes WHEN 1 THEN   FormItems.ItemAmount ELSE 0 END)) as Bed,
       sum((CASE  FormTypes.BedBes WHEN 0 THEN   FormItems.ItemAmount ELSE 0 END)) as Bes
FROM    FormItems INNER JOIN
        Forms ON  FormItems.FormID =  Forms.FormID INNER JOIN
        FormTypes ON  Forms.FormType =  FormTypes.FormType
WHERE ( FormTypes.Customer1DocType = 10)And(Forms.FormID<>@FormID or Forms.ServerID <> @ServerID or  Forms.YearID <> @YearID )
         And(Forms.FormDate<@FormDate)
                 And(Forms.FormState < 10)
GROUP BY  Forms.CustomerID1)
union all
(SELECT  Forms.CustomerID2 as PersonID,
        sum((CASE  FormTypes.BedBes WHEN 0 THEN   FormItems.ItemAmount ELSE 0 END)) as Bed,
        sum((CASE  FormTypes.BedBes WHEN 1 THEN   FormItems.ItemAmount ELSE 0 END)) as Bes
FROM     FormItems INNER JOIN
         Forms ON  FormItems.FormID =  Forms.FormID INNER JOIN
         FormTypes ON  Forms.FormType =  FormTypes.FormType
WHERE  ( FormTypes.Customer2DocType = 10)And(Forms.FormID<>@FormID or Forms.ServerID <> @ServerID or  Forms.YearID <> @YearID )And(Forms.FormDate<@FormDate)
                And(Forms.FormState < 10)
GROUP BY  Forms.CustomerID2)
union all
(SELECT  Forms.CustomerID1 as PersonID,
       sum((CASE  FormTypes.BedBes WHEN 1 THEN   Forms.Amount ELSE 0 END)) as Bed,
       sum((CASE  FormTypes.BedBes WHEN 0 THEN   Forms.Amount ELSE 0 END)) as Bes
FROM          Forms INNER JOIN
                       FormTypes ON  Forms.FormType =  FormTypes.FormType
WHERE ( FormTypes.Customer1DocType = 10) and( FormTypes.DisplayFormType in(0,7))
       And(Forms.FormID<>@FormID or ServerID <> @ServerID or  YearID <> @YearID )And(Forms.FormDate<@FormDate) And(Forms.FormState < 10)
GROUP BY  Forms.CustomerID1)
union all
(SELECT  Forms.CustomerID2 as PersonID,
       sum((CASE  FormTypes.BedBes WHEN 0 THEN   Forms.Amount ELSE 0 END)) as Bed,
       sum((CASE  FormTypes.BedBes WHEN 1 THEN   Forms.Amount ELSE 0 END)) as Bes
FROM          Forms INNER JOIN
                       FormTypes ON  Forms.FormType =  FormTypes.FormType
WHERE  ( FormTypes.Customer2DocType = 10)and( FormTypes.DisplayFormType in(0,7))
        And(Forms.FormID<>@FormID or ServerID <> @ServerID or  YearID <> @YearID )And(Forms.FormDate<@FormDate) And(Forms.FormState < 10)
GROUP BY  Forms.CustomerID2)
union all
SELECT     Recipts.PersonID1, SUM(ReciptsDeficits.DeficitAdd) AS Bed, SUM(ReciptsDeficits.DeficitDec) AS Bes
FROM         ReciptsDeficits INNER JOIN
                      Recipts ON ReciptsDeficits.ReciptID = Recipts.ReciptID
WHERE (Recipts.ReciptState<3)--And(Recipts.ReciptID<>:ReciptID2)
GROUP BY ReciptsDeficits.ReciptID, Recipts.PersonID1

)ReMain
WHERE (PersonID = @PersonID)
GROUP BY PersonID
--ORDER BY PersonID
)
set @ReMain=isnull(@ReMain,0)+(SELECT isnull(FirstBalance,0) FROM Customers WHERE CustID=@PersonID)
RETURN(@ReMain)
end
GO 
