CREATE FUNCTION [dbo].[ReMainPerson2] (@ReciptID int=1, @ServerID int=0, @YearID int=88, @Date varchar(20)=[99/99/99], @PersonID int=0 )
RETURNS money 
begin
DECLARE @ReMain money
set @ReMain=
(SELECT sum(Bed)-sum(Bes) as ReMain from (
SELECT PersonID1,Bed,Bes FROM(
SELECT PersonID1,bed,bes FROM CustomerTrancationsItems WHERE ((ReciptID<>@ReciptID) or (ServerID<>@ServerID) or (YearID<>@YearID)) AND (ReciptDate<=@Date)  
UNION ALL
SELECT CustomerID1,bed,bes FROM cashTransactionItemsCust WHERE (FormDate<=@Date) )a
UNION ALL
SELECT CustID as PersonID ,isnull(FirstBalance,0) as Bed ,0 as Bes FROM Customers)R
WHERE PersonID1 = @PersonID)
RETURN(@ReMain)
end
