CREATE VIEW CustomerTrancationsItems
AS
SELECT     PersonID1, ReciptID, ReciptNumber, ReciptDate, ReciptType, ReciptCaption, '0' AS CheckNo, '' AS CheckDate,'' as BankName, StuffCode, c_StuffName, UnitName, entity, 
                      weight, bed, bes, kind, StoreID, ItemNote,StuffDiameter, StuffSize,UnitSellPrice,ModifyDate ,ControlCode , CustName,  SecondTypeCode
                      , PersonID2, CustName2, SellsMethodName, ServerID, YearID,ReciptItemID
 
FROM         (SELECT     Recipts.PersonID1, Recipts.ReciptID, Recipts.ReciptNumber, Recipts.ReciptDate, Recipts.ReciptType, ReciptTypes.ReciptCaption, 
                      ReciptItems.StuffCode, StuffCoding.c_StuffName, Units.UnitName, ReciptItems.InputEntity + ReciptItems.OutputEntity AS entity, 
                      ReciptItems.InputWeight + ReciptItems.OutputWeight AS weight, ReciptItems.TotalInputPrice + ReciptItems.TotalOutputPrice AS bed, 
                      ReciptItems.TotalInputPrice - ReciptItems.TotalInputPrice AS bes, 3 AS kind, Recipts.StoreID,isnull(Recipts.ReciptNote,'')+' '+ isnull(ReciptItems.ItemNote,'') as ItemNote, ReciptItems.StuffDiameter, 
                      ReciptItems.StuffSize, ReciptItems.UnitSellPrice, Recipts.ModifyDate, ReciptItems.ControlCode, Customers.CustName as CustName, LookUps.Code AS SecondTypeCode
                      , Recipts.PersonID2,  Customers2.CustName as CustName2, SellsMethods.SellsMethodName, Recipts.ServerID, Recipts.YearID ,ReciptItemID

FROM         Recipts INNER JOIN
                      ReciptItems ON Recipts.ReciptID = ReciptItems.ReciptID AND Recipts.ServerID = ReciptItems.ServerID AND Recipts.YearID = ReciptItems.YearID INNER JOIN
                      ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType INNER JOIN
                      Units INNER JOIN
                      StuffCoding ON Units.UnitCode = StuffCoding.n_UnitCode ON ReciptItems.StuffCode = StuffCoding.c_StuffCode LEFT OUTER JOIN
                      LookUps ON Recipts.SecondType = LookUps.LookUpID
                      LEFT OUTER JOIN  Customers ON Recipts.PersonID1 = Customers.CustID
                      LEFT OUTER JOIN  Customers as Customers2 ON Recipts.PersonID2 = Customers2.CustID
                      LEFT OUTER JOIN  SellsMethods ON Recipts.SellsMethod = SellsMethods.SellsMethod

WHERE     (ReciptTypes.BedType = 1) AND (Recipts.ReciptState < 3)

                        UNION ALL
                        SELECT     Recipts.PersonID1, Recipts.ReciptID, Recipts.ReciptNumber, Recipts.ReciptDate, Recipts.ReciptType, ReciptTypes.ReciptCaption, 
                      ReciptItems.StuffCode, StuffCoding.c_StuffName, Units.UnitName, ReciptItems.InputEntity + ReciptItems.OutputEntity AS entity, 
                      ReciptItems.InputWeight + ReciptItems.OutputWeight AS weight, 0 AS bed, ReciptItems.TotalInputPrice + ReciptItems.TotalOutputPrice AS Bes, 
                      3 AS kind, Recipts.StoreID, isnull(Recipts.ReciptNote,'')+ ' '+isnull(ReciptItems.ItemNote,'') as ItemNote, ReciptItems.StuffDiameter, ReciptItems.StuffSize, ReciptItems.UnitSellPrice, Recipts.ModifyDate, 
                      ReciptItems.ControlCode, Customers.CustName as CustName,  LookUps.Code AS SecondTypeCode
                      , Recipts.PersonID2, Customers2.CustName as CustName2, SellsMethods.SellsMethodName, Recipts.ServerID, Recipts.YearID ,ReciptItemID

                       FROM   Recipts INNER JOIN
                      ReciptItems ON Recipts.ReciptID = ReciptItems.ReciptID AND Recipts.ServerID = ReciptItems.ServerID AND Recipts.YearID = ReciptItems.YearID INNER JOIN
                      ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType INNER JOIN
                      Units INNER JOIN
                      StuffCoding ON Units.UnitCode = StuffCoding.n_UnitCode ON ReciptItems.StuffCode = StuffCoding.c_StuffCode LEFT OUTER JOIN
                      LookUps ON Recipts.SecondType = LookUps.LookUpID LEFT OUTER JOIN  
                      Customers ON Recipts.PersonID1 = Customers.CustID LEFT OUTER JOIN  
                      Customers as Customers2 ON Recipts.PersonID2 = Customers2.CustID LEFT OUTER JOIN 
                      SellsMethods ON Recipts.SellsMethod = SellsMethods.SellsMethod
                       WHERE     (Recipts.ReciptState < 3) AND (ReciptTypes.BesType = 1)
                        UNION ALL  
SELECT     PersonID1, ReciptID, ReciptNumber, ReciptDate, ReciptType, ReciptCaption, StuffCode, c_StuffName, UnitName, entity, weight, bed, bes, kind, StoreID, 
                      ItemNote, StuffDiameter, StuffSize, UnitSellPrice, ModifyDate,0 as ControlCode, CustName,  SecondTypeCode, PersonID2, CustName2, SellsMethodName, ServerID, YearID ,0 as ReciptItemID

FROM         GetReciptsDeficits() GetReciptsDeficits
) AccTran  
