CREATE VIEW CustomerTrancations
AS
SELECT     *
FROM(SELECT Recipts.PersonID1, Recipts.ReciptID, Recipts.ReciptType, Recipts.ReciptNumber, Recipts.ReciptDate, 
                      ReciptTypes.ReciptCaption, Recipts.ReciptNote, SUM(ReciptItems.TotalInputPrice) + SUM(ReciptItems.TotalOutputPrice) 
                      - SUM(ISNULL(ReciptItems.DeficitValue+ReciptItems.DeficitValue2+ReciptItems.DeficitValue4+ReciptItems.DeficitValue3, 0)) 
                      + ISNULL
                          ((SELECT     SUM(DeficitAdd) - SUM(DeficitDec) AS DeficitAdd_Dec
                              FROM          ReciptsDeficits
                              where  ReciptID = Recipts.ReciptID and  ServerID = Recipts.ServerID and  YearID = Recipts.YearID
                              GROUP BY ReciptID), 0) AS bed, SUM(0) AS bes, 3 AS kind, Recipts.StoreID AS StoreIDForShow
, Recipts.ServerID, Recipts.YearID
                              
FROM         ReciptItems INNER JOIN
                      Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
                      ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
WHERE     (ReciptTypes.BedType = 1)AND (Recipts.ReciptState < 3)
GROUP BY Recipts.PersonID1, Recipts.ReciptID, Recipts.ReciptType, Recipts.ReciptNumber, Recipts.ReciptDate, 
                      ReciptTypes.ReciptCaption, Recipts.ReciptNote, Recipts.StoreID, Recipts.ServerID, Recipts.YearID
UNION ALL
SELECT     Recipts.PersonID1, Recipts.ReciptID, Recipts.ReciptType, Recipts.ReciptNumber, Recipts.ReciptDate, 
                      ReciptTypes.ReciptCaption, Recipts.ReciptNote, SUM(0) AS bed, SUM(ReciptItems.TotalInputPrice) 
                      + SUM(ReciptItems.TotalOutputPrice) + ISNULL
                          ((SELECT     SUM(DeficitAdd) - SUM(DeficitDec) AS DeficitAdd_Dec
                              FROM          ReciptsDeficits
                              where  ReciptID = Recipts.ReciptID and  ServerID = Recipts.ServerID and  YearID = Recipts.YearID
                              GROUP BY ReciptID), 0) AS Bes, 3 AS kind, Recipts.StoreID AS StoreIDForShow
, Recipts.ServerID, Recipts.YearID
FROM         ReciptItems INNER JOIN
                      Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
                      ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
WHERE     (ReciptTypes.BesType = 1)AND (Recipts.ReciptState < 3)
GROUP BY Recipts.PersonID1, Recipts.ReciptID, Recipts.ReciptType, Recipts.ReciptNumber, Recipts.ReciptDate, 
                      ReciptTypes.ReciptCaption, Recipts.ReciptNote, Recipts.StoreID, Recipts.ServerID, Recipts.YearID) Acc

