CREATE VIEW CustomerTrancationsDetails
AS
SELECT     AccTran.*, Customers.CustName AS CustName
FROM         (SELECT     Recipts.PersonID1, Recipts.ReciptID, Recipts.ReciptNumber, Recipts.ReciptDate, ReciptTypes.ReciptType, 
                                              ReciptTypes.ReciptCaption, ReciptItems.StuffCode, StuffCoding.c_StuffName, Units.UnitName, StuffSize, StuffDiameter, 
                                              StuffAlloy, ControlCode, ReciptItems.InputEntity + ReciptItems.OutputEntity AS entity, 
                                              ReciptItems.InputWeight + ReciptItems.OutputWeight AS weight, 
                                              ReciptItems.TotalInputPrice + ReciptItems.TotalOutputPrice + ISNULL(ReciptsDeficits.DeficitAdd - ReciptsDeficits.DeficitDec,
                                               0) AS bed, ReciptItems.TotalOutputPrice - ReciptItems.TotalOutputPrice AS bes, 3 AS kind, Recipts.StoreID
                        FROM         ReciptsDeficits RIGHT OUTER JOIN
                                              ReciptItems INNER JOIN
                                              Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
                                              ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType INNER JOIN
                                              Units INNER JOIN
                                              StuffCoding ON Units.UnitCode = StuffCoding.n_UnitCode ON ReciptItems.StuffCode = StuffCoding.c_StuffCode ON 
                                              ReciptsDeficits.ReciptID = Recipts.ReciptID
                        WHERE     (ReciptTypes.BedType = 1)
                        UNION ALL
                        SELECT     Recipts.PersonID1, Recipts.ReciptID, Recipts.ReciptNumber, Recipts.ReciptDate, ReciptTypes.ReciptType, 
                                              ReciptTypes.ReciptCaption, ReciptItems.StuffCode, StuffCoding.c_StuffName, Units.UnitName, StuffSize, StuffDiameter, 
                                              StuffAlloy, ControlCode, ReciptItems.InputEntity + ReciptItems.OutputEntity AS entity, 
                                              ReciptItems.InputWeight + ReciptItems.OutputWeight AS weight, 0 AS bed, 
                                              ReciptItems.TotalInputPrice + ReciptItems.TotalOutputPrice + ISNULL(ReciptsDeficits.DeficitAdd - ReciptsDeficits.DeficitDec,
                                               0) AS Bes, 3 AS kind, Recipts.StoreID
                        FROM         Units INNER JOIN
                                              StuffCoding ON Units.UnitCode = StuffCoding.n_UnitCode CROSS JOIN
                                              ReciptItems INNER JOIN
                                              Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
                                              ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType LEFT OUTER JOIN
                                              ReciptsDeficits ON Recipts.ReciptID = ReciptsDeficits.ReciptID
                        WHERE     (ReciptTypes.BesType = 1)) AccTran INNER JOIN
                      Customers ON AccTran.PersonID1 = Customers.CustID
WHERE     (AccTran.PersonID1 BETWEEN 1 AND 999999) AND (AccTran.ReciptDate BETWEEN '0' AND '9999/99/99') 
      AND (AccTran.StuffCode BETWEEN 1 AND  999999)
