CREATE  FUNCTION dbo.Cardex_Aid( 
			@StoreIDFrom int , @StoreIDTo int , 
			@StuffCodeFrom bigint=-2147483647 , @StuffCodeTo bigint=9223372036854775807  ,
			@ControlCodeFrom bigint=0 , @ControlCodeTo bigint=9999999  ,
			@DateFrom Char(10)='', @DateTo Char(10)= '9999/99/99' ,
			@YearIDFrom int=0 ,  @YearIDTo int=999999,
            @DiameterFrom float=0, @DiameterTo float=99999,
            @PersonID1DFrom INT=-2147483647  ,@PersonID1DTo INT=2147483647 , 
			@PersonID4From INT=-2147483647  ,@PersonID4To INT=2147483647 ,
            @PersonID1From INT=-2147483647  ,@PersonID1To INT=2147483647 , 
			@PersonID2From INT=-2147483647  ,@PersonID2To INT=2147483647  )
RETURNS table  AS  

return (

SELECT  --dbo.GetRowReciptItems(R.ReciptItemID, R.ServerID, R.YearID ) as Row,
		R.n_ValuationType,R.StoreID, S.c_StoreName, R.StuffCode,	SC.c_StuffName, U.UnitName,
		R.ReciptNumber, R.ReciptDate, R.ReciptType , R.ReciptCaption , 
		R.StuffSize,R.StuffDiameter, R.StuffAlloy, R.ControlCode , 
		SC.c_StuffTecInfo,ScS.MinOrder n_minOrder,ScS.MaxOrder n_maxOrder, ScS.OrderPoint n_orderPoint,
		Round(R.InputEntity,5) as InputEntity, 
		round(R.InputWeight,5)as InputWeight,
		R.TotalInputPrice , 
		round(R.OutputEntity,5)as OutputEntity,
        round(R.OutputWeight,5) as OutputWeight, 
		R.TotalOutputPrice ,
		round(R.InputEntity - R.OutputEntity,5) AS BackLogEntity,
		round(R.InputWeight - R.OutputWeight,5) AS BackLogWeight,
		R.TotalInputPrice - R.TotalOutputPrice  AS BacklogPrice,
		--R.OutputEntity AS CalcuBackLogEntity,
		--R.OutputWeight AS CalcuBackLogWeight,
		--R.TotalInputPrice - R.TotalOutputPrice  AS CalcuBacklogPrice ,

		R.ReciptID , 
		R.PersonID1,ISNULL(C1.CustName, 'مشتري ندارد') AS CustName ,
		
        R.PersonID2,C2.CustName AS CustName2 , 
        R.PersonID3,C3.CustName AS CustName3 , 
        R.PersonID4,C4.CustName AS CustName4 , 
        R.PersonID1D AS PersonID1D ,Customers1D.CustName AS CustName1D ,
        R.ProductCode,StuffCodProduct.c_StuffName AS ProductName,
		R.EffectType ,
		(case  when R.EffectType in (2,6)  THEN R.TotallSellPrice else 0 end )as InTotallSellPrice,
		(case  when R.EffectType in (4,7,  8  )  THEN R.TotallSellPrice else 0 end )as OutTotallSellPrice,
		(case  when R.EffectType in (2,6)  THEN 1 else -1 end )* R.TotallSellPrice as InvTotallSellPrice,
		--(case  when R.EffectType in (2,6)  THEN 1 else -1 end )* R.TotallSellPrice as CalcuBacklogSellPrice,
		R.ItemNote, R.AidNumber, R.AidDate, R.AidNumberD, R.AidDateD,
		--(case  when R.EffectType in (2,6)  THEN R.UnitSellPrice else 0 end )as UnitSellPriceIn,

		CASE  WHEN ISNULL(R.Portage,0) = 0 THEN 
		   (case  when R.EffectType in (2,6)  THEN R.UnitSellPrice else 0 end )
        else   case when R.EntityDisplayType <> 3 then 
	
			case when R.InputEntity <> 0 then round(case  when R.EffectType in (2,6)  THEN R.TotallSellPrice else 0 end / R.InputEntity ,5) else 0 end
					else case	when  DiagnosisCalcTotalPrice = 0 then  case when R.InputEntity <> 0 then round(case  when R.EffectType in (2,6)  THEN R.TotallSellPrice else 0 end / R.InputEntity ,5) else 0 end 
								when  DiagnosisCalcTotalPrice = 1 then  case when R.InputWeight <> 0 then round(case  when R.EffectType in (2,6)  THEN R.TotallSellPrice else 0 end / R.InputWeight ,5) else 0 end
		else 0 end end
		END as UnitSellPriceIn,
		  
		(case  when R.EffectType in (4,7,  8  )  THEN R.UnitSellPrice else 0 end )as UnitSellPriceOut,
		(round(
		(	R.TotalInputPrice - R.TotalOutputPrice 
		 ) /
		 (
			case R.InputWeight - R.OutputWeight 
				when 0 then 1 
				else R.InputWeight - R.OutputWeight end 
			)	 ,0))as UnitSellPriceBackLog1,
		 
		ISNULL(CASE WHEN R.EffectType in(2,6) THEN R.RegPrice ELSE - R.RegPrice END, 0) AS RegPrice ,
		ISNULL(CASE WHEN R.EffectType in(2,6,  8  ) THEN R.Portage ELSE - R.Portage END, 0) AS Portage ,
		ISNULL(CASE WHEN R.EffectType in(2,6) THEN R.DeficitValue ELSE - R.DeficitValue END, 0) AS DeficitValue
         ,R.ID,R.ReciptItemID, R.ServerID, R.YearID
		 ,R.StoreID2,  c_StoreName2,R.SecondTypeItem ,SC.Cabinet ,SC.c_KeepPlace,
		case when InputEntity +OutputEntity <>0 then (TotalInputPrice+TotalOutputPrice)/(InputEntity +OutputEntity) ELSE 0 END AS UnitEntityPrice ,
		case when InputWeight +OutputWeight <>0 then (TotalInputPrice+TotalOutputPrice)/(InputWeight +OutputWeight) ELSE 0 END AS UnitWeightPrice
		,R.ReciptNote,r.SellsEmporium,SellsEmporiums.SellsEmporiumName,R.ItemDate,R.autoPrice,R.IncreasingInventory,R.UnitCommission,R.UseUnitIDD,UsD.UseUnitName AS UseUnitNameD
		,R.DocNo,R.ReciptState,R.SpecialCode,R.DocDate
FROM	StuffCoding SC INNER JOIN
		Units U ON SC.n_UnitCode = U.UnitCode INNER JOIN
		ReciptItems_Stock AS R ON SC.c_StuffCode = R.StuffCode INNER JOIN
		Stores S ON R.StoreID = S.n_StoreID  INNER JOIN
		Customers C1 ON R.PersonID1 = C1.CustID INNER JOIN
		Customers AS C2 ON R.PersonID2 = C2.CustID INNER JOIN
		Customers AS C3 ON R.PersonID3 = C3.CustID INNER JOIN
		Customers AS C4 ON R.PersonID4 = C4.CustID INNER JOIN
		Customers AS Customers1D ON R.PersonID1D = Customers1D.CustID left outer JOIN
        StuffCoding AS StuffCodProduct ON R.ProductCode = StuffCodProduct.c_StuffCode LEFT OUTER JOIN
        SellsEmporiums ON R.SellsEmporium = SellsEmporiums.SellsEmporium LEFT OUTER JOIN
        UseUnits UsD ON R.UseUnitIDD = UsD.UseUnitID  LEFT OUTER JOIN
        StuffCodingStock AS ScS ON SC.c_StuffCode = ScS.StuffCode and  S.n_StoreID = ScS.StoreID

--		cross join Fitful
WHERE (R.EffectType in(2,4,6,7,  8  )) 
AND (R.StoreID between @StoreIdFrom and @StoreIdTo  ) 
AND (R.StuffCode between @StuffCodeFrom and @StuffCodeTo ) 
AND (R.ReciptDate BETWEEN @DateFrom AND @DateTo) 
AND (isnull(R.ControlCode,0)  BETWEEN @ControlCodeFrom AND @ControlCodeTo) 
AND (R.YearID between @YearIDFrom and @YearIDTo)
AND (R.StuffDiameter BETWEEN @DiameterFrom AND @DiameterTo)
AND (R.PersonID1D BETWEEN @PersonID1DFrom AND @PersonID1To)
AND (R.PersonID4 BETWEEN @PersonID4From AND @PersonID4To)
AND (R.PersonID1 BETWEEN @PersonID1From AND @PersonID1To)
AND (R.PersonID2 BETWEEN @PersonID2From AND @PersonID2To)


--SELECT  --dbo.GetRowReciptItems(R.ReciptItemID, R.ServerID, R.YearID ) as Row,
--		R.n_ValuationType,R.StoreID, S.c_StoreName, R.StuffCode,	SC.c_StuffName, U.UnitName,
--		R.ReciptNumber, R.ReciptDate, R.ReciptType , R.ReciptCaption , 
--		R.StuffSize,R.StuffDiameter, R.StuffAlloy, R.ControlCode , 
--		SC.c_StuffTecInfo,SC.n_minOrder,SC.n_maxOrder, SC.n_orderPoint,
