CREATE FUNCTION dbo.Cardex( 
			@StoreIDFrom int , @StoreIDTo int , 
			@StuffCodeFrom bigint , @StuffCodeTo bigint ,
			@ControlCodeFrom bigint , @ControlCodeTo bigint  ,
			@DateFrom Char(10), @DateTo Char(10) ,@DateFromRemain  Varchar(10) ,
			@YearIDFrom int=0 ,  @YearIDTo int=999999,
            @DiameterFrom float=0, @DiameterTo float=99999,
            @PersonID1DFrom INT=-2147483647  ,@PersonID1DTo INT=2147483647 ,
            @PersonID4From INT=-2147483647  ,@PersonID4To INT=2147483647,
            @PersonID1From INT=-2147483647  ,@PersonID1To INT=2147483647 , 
			@PersonID2From INT=-2147483647  ,@PersonID2To INT=2147483647   )
RETURNS table  AS  
return (

SELECT *
FROM Cardex_Aid ( @StoreIdFrom , @StoreIdTo,@StuffCodeFrom,@StuffCodeTo,@ControlCodeFrom,@ControlCodeTo,@DateFrom,@DateTo , @YearIDFrom , @YearIDTo
, @DiameterFrom , @DiameterTo ,@PersonID1DFrom ,@PersonID1DTo,@PersonID4From ,@PersonID4To ,@PersonID1From ,@PersonID1To ,@PersonID2From ,@PersonID2To ) as Cardex_Aid

UNION ALL

SELECT      n_ValuationType,StoreID, c_StoreName, StuffCode, c_StuffName, UnitName, 0 AS ReciptNumber, '' AS reciptdate, 0 AS ReciptType, 'نقل از قبل' AS ReciptCaption,
                       StuffSize, StuffDiameter, StuffAlloy, ControlCode, c_StuffTecInfo, n_minOrder, n_maxOrder, n_orderPoint, SUM(InputEntity) AS InputEntity, 
                      SUM(InputWeight) AS InputWeight, SUM(TotalInputPrice) AS TotalInputPrice, SUM(OutputEntity) AS OutputEntity, SUM(OutputWeight) AS OutputWeight, 
                      SUM(TotalOutputPrice) AS TotalOutputPrice, SUM(BackLogEntity) AS BackLogEntity, SUM(BackLogWeight) AS BackLogWeight, SUM(BacklogPrice) 
                      AS BacklogPrice
					  , 0 AS ReciptID, 
                      0 AS PersonID1,  '' AS CustName, 
                      0 AS PersonID2,  '' AS CustName2, 
                      0 AS PersonID3,  '' AS CustName3,
                      0 AS PersonID4,  '' AS CustName4,
                      0 AS PersonID1D, '' AS CustName1D,
                      0 AS ProductCode,'' AS ProductName,                     
                      0 AS EffectType, SUM(InTotallSellPrice) AS InTotallSellPrice, 
                      SUM(OutTotallSellPrice) AS OutTotallSellPrice, SUM(InvTotallSellPrice) AS InvTotallSellPrice, 
                      '' AS ItemNote, '0' AS AidNumber, '' AS AidDate,  '0' AS AidNumberD, '' AS AidDateD,
					  MIN(UnitSellPriceIn) AS UnitSellPriceIn, MIN(UnitSellPriceOut) AS UnitSellPriceOut, 
                      SUM(UnitSellPriceBackLog1) AS UnitSellPriceBackLog1, SUM(RegPrice) AS RegPrice, SUM(Portage) AS Portage, 
                      SUM(DeficitValue) AS DeficitValue, min(ID),0 as ReciptItemID, 0 AS ServerID, 0 AS YearID
					  ,0 as StoreID2,'' as c_StoreName2,min(SecondTypeItem) AS SecondTypeItem, '' AS Cabinet , '' AS c_KeepPlace,
		MIN(UnitEntityPrice) AS UnitEntityPrice ,
		MIN(UnitWeightPrice) AS UnitWeightPrice ,'' ReciptNote,SellsEmporium,SellsEmporiumName,ItemDate,min( autoPrice),min(IncreasingInventory),avg(UnitCommission)UnitCommission,0 AS UseUnitIDD,'' AS UseUnitNameD
		,-1 AS DocNo,-1 AS ReciptState, '' AS SpecialCode,'' DocDate
FROM         dbo.Cardex_Aid( @StoreIdFrom , @StoreIdTo, @StuffCodeFrom, @StuffCodeTo, @ControlCodeFrom, @ControlCodeTo, '', @DateFromRemain ,
                @YearIDFrom , @YearIDFrom, @DiameterFrom , @DiameterTo ,@PersonID1DFrom ,@PersonID1DTo ,@PersonID4From ,@PersonID4To  ,@PersonID1From ,@PersonID1To ,@PersonID2From ,@PersonID2To) 
                      AS Cardex_FirstEntity

		
GROUP BY   n_ValuationType, StoreID, c_StoreName, StuffCode, c_StuffName, UnitName, StuffSize, StuffDiameter, StuffAlloy, ControlCode, c_StuffTecInfo, n_minOrder, n_maxOrder, 
                      n_orderPoint,SellsEmporium,SellsEmporiumName,ItemDate  -- نقل از قبل دو سطری autoPrice ,IncreasingInventory,autoPrice
                      
--SELECT   0 as Row, StoreID, c_StoreName, StuffCode, c_StuffName, UnitName, ReciptNumber, 
--		reciptdate, ReciptType, ReciptCaption,StuffSize, StuffDiameter, StuffAlloy,
--		ControlCode, c_StuffTecInfo, n_minOrder, n_maxOrder, n_orderPoint, 
--		SUM(InputEntity) AS InputEntity, SUM(InputWeight) AS InputWeight,
--		SUM(TotalInputPrice) AS TotalInputPrice, 
--		SUM(OutputEntity) AS OutputEntity, SUM(OutputWeight) AS OutputWeight, 
--		SUM(TotalOutputPrice)AS TotalOutputPrice, 
--		SUM(BackLogEntity) AS BackLogEntity, SUM(BackLogWeight) AS BackLogWeight, 
--		SUM(BacklogPrice) AS BacklogPrice,
--		SUM(CalcuBackLogEntity) AS CalcuBackLogEntity, SUM(CalcuBackLogWeight) AS CalcuBackLogWeight, 
--		SUM(CalcuBacklogPrice)AS CalcuBacklogPrice, 
--		ReciptID, 0 AS PersonID1, '' AS CustName, EffectType, 
--		SUM(InTotallSellPrice) AS InTotallSellPrice, SUM(OutTotallSellPrice)AS OutTotallSellPrice, 
--		SUM(InvTotallSellPrice) AS InvTotallSellPrice, SUM(CalcuBacklogSellPrice) AS CalcuBacklogSellPrice, 
--		ItemNote, AidNumber,AidDate, 
--		MIN(UnitSellPriceIn) AS UnitSellPriceIn, MIN(UnitSellPriceOut) AS UnitSellPriceOut, 
--		SUM(UnitSellPriceBackLog)AS UnitSellPriceBackLog ,
--		0 as ServerID ,0 as YearID , sum(RegPrice ) as RegPrice ,sum(Portage) as Portage , sum(DeficitValue) as DeficitValue
		

--  FROM	Cardex_Aid (@StoreID,@StuffCodeFrom,@StuffCodeTo,@ControlCodeFrom,@ControlCodeTo,'',@DateFromRemain) as Cardex_FirstEntity 

--GROUP BY StoreID, c_StoreName, StuffCode, c_StuffName, UnitName, ReciptNumber, reciptdate, ReciptType, ReciptCaption, StuffSize, StuffDiameter, StuffAlloy,
  --                    ControlCode, c_StuffTecInfo, n_minOrder, n_maxOrder, n_orderPoint, ReciptID, EffectType, ItemNote, AidNumber, AidDate 
)
