CREATE FUNCTION dbo.MakeDocuments2_Check (@AllDocAble Tinyint=0,@FormDateFrom varchar(10)='0000/00/00', @FormDateTo varchar(10)='9999/99/99',
				@FormNoFrom int=-9999999, @FormNoTo int =99999999 --, @FormType varchar (3)= [50] 
                                                    ,@CheckStateFrom varchar (12)=[0], @CheckStateTo varchar (12)=[99]
                                                    ,@SellsEmporiumFrom int=0,@SellsEmporiumTo int = 999999999 
                                                    ,@PayTypesFrom int=0,@PayTypesTo int = 999999999 
													,@MakeDocKind int =1  ,
				@AidDateFrom char(10)='0000/00/00', @AidDateTo char(10)='9999/99/99')
  RETURNS @retFindReports TABLE 
  (
	ID bigint ,
    FormItemID int ,
	FormID int ,
	CheckNumber char(20)   COLLATE DATABASE_DEFAULT ,
	CheckDate char(10)   COLLATE DATABASE_DEFAULT ,
	FormNumber int ,
	FormDate char(10)   COLLATE DATABASE_DEFAULT ,
	FormType tinyint ,
	FormCaption varchar(150)  COLLATE DATABASE_DEFAULT ,
	CheckType tinyint ,
	TopicCode bigint ,
	DetailCode int ,
	CtopicCode int ,
	CtopicCode2 int ,
	CtopicCode3 int ,
	debt money ,
	credit money ,
	bedbes int ,
	ItemNote varchar(1000)  COLLATE DATABASE_DEFAULT ,
	FomNote varchar(1000)  COLLATE DATABASE_DEFAULT ,
	Row int ,
	ServerID int ,
	YearID int ,
	CustName varchar(160),
	Tahator int ,
	ct1name varchar(160),
	CheckFor varchar(255),
	PO varchar(30),
	AidInfoNo varchar(40) ,
	AidInfoDate char(10)   COLLATE DATABASE_DEFAULT ,
	AidInfoNoItem varchar(40) ,
	AidInfoDateItem char(10)  COLLATE DATABASE_DEFAULT ,
	ArzTypeID int NULL  ,
	ArzAmount float ,
	BudgetCode int ,
	Currencydebit   decimal(18, 4),
	Currencycredit   decimal(18, 4),
	CurrencyRate   decimal(18, 4)

  )
  AS 	
BEGIN  
INSERT INTO @retFindReports
SELECT    ID, FormItemID, FormID, CheckNumber, CheckDate, FormNumber, FormDate, FormType, FormCaption, checkType,
                      TopicCode_Bed AS TopicCode, 
                      DetailCode_Bed AS DetailCode, CTopicCode_Bed AS CtopicCode, CTopicCode2_Bed AS CtopicCode2,
                     CTopicCode3_Bed AS CtopicCode3,
                       ItemAmount AS debt, 0 AS credit, 
                      0 AS bedbes,ItemNote,FomNote , row ,ServerID,YearID                     --, @FormType
					  ,CustName, 0 as Tahator,ct1name,CheckFor,PO
		 ,AidInfoNo,AidInfoDate, AidInfoNoItem , AidInfoDateItem,AMDC.ArzTypeID,AMDC.Arzamount,BudgetCode, 0.0 AS Currencydebit, 0.0 AS Currencycredit, 0.0 CurrencyRate
FROM         Aid_MakeDocuments_Check(@AllDocAble ,@FormDateFrom, @FormDateTo, @FormNoFrom, @FormNoTo,@CheckStateFrom, @CheckStateTo,@SellsEmporiumFrom ,@SellsEmporiumTo 
                               ,@PayTypesFrom ,@PayTypesTo ,@MakeDocKind  ,@AidDateFrom , @AidDateTo  ) AMDC

UNION ALL

SELECT    ID, 0 as FormItemID,  FormID,'' as  CheckNumber,'' as  CheckDate, FormNumber, FormDate, FormType,
                      FormCaption, 0 as  checkType, TopicCode_Bes, DetailCode_Bes, 
                      CTopicCode_Bes, CTopicCode2_Bes, 
                     CTopicCode3_Bes AS CtopicCode3,
                      0 AS debt,
		 case when isnull(AMDC.ConstTopicCode_ArzBed,0) <>0
				and  isnull(AMDC.ConstTopicCode_ArzBes,0) <>0
		        and isnull( AMDC.RelatedRecipts  ,0) <>0
		 then isnull( round(AMDC.ArzAmountexchange * RialsEqual,0) ,0)   else  ItemAmount  end   AS credit,
					   1 AS bedbes,'' as ItemNote,FomNote , 9999 as row
                      ,AMDC.ServerID,AMDC.YearID
                                                                                  --@FormType,
		              ,CustName,case when ItemAmount<0 then 1 else 0 end  as tahator,
					  ct1name,CheckFor,po
		 ,AidInfoNo,AidInfoDate, AidInfoNoItem , AidInfoDateItem,AMDC.ArzTypeID,AMDC.Arzamount,BudgetCode, 0.0 AS Currencydebit, 0.0 AS Currencycredit, 0.0 CurrencyRate
FROM         Aid_MakeDocuments_Check(@AllDocAble ,@FormDateFrom, @FormDateTo, @FormNoFrom, @FormNoTo, @CheckStateFrom, @CheckStateTo,@SellsEmporiumFrom ,@SellsEmporiumTo
                               ,@PayTypesFrom ,@PayTypesTo ,@MakeDocKind  ,@AidDateFrom , @AidDateTo  ) AMDC	

UPDATE @retFindReports SET debt=ROUND(debt,0), credit=ROUND(credit,0)
     RETURN
END 
