CREATE  FUNCTION Fn_DarayiSells( 
  @Tax Float
, @TaxTown Float
, @Town Float
, @TaxTown1 Float
, @CustIdFrom int
, @CustIdTo int
, @StuffGrpFrom int
, @StuffGrpTo int
, @SeasonFrom int
, @SeasonTo int
, @DateFrom char(10)
, @DateTo char(10)
, @CustomerGrpIDFrom int
, @CustomerGrpIDTo int
, @SellsEmporiumFrom int
, @SellsEmporiumTo int
, @NotSellsEmporium varchar(2000) =''
, @YearIDFrom int
, @YearIDTo int
, @StoreID varchar(2000) ='21,32,31,30,26,20,0'
, @EconomicNumberNationalID int
, @StuffShow int =0
, @chkPriceParvane bit =1
, @StuffKindActive varchar(200) ='0,1'
, @ReciptsSecondType varchar(2000) ='21,32,31,30,26,20,0'
, @INSellsEmporium varchar(2000) =''
, @SellsMethodFrom int
, @SellsMethodTo int
, @NotSellsMethod varchar(2000) =''
, @INSellsMethod varchar(2000) ='' 
, @tax_status varchar(10) ='1,2'

)

RETURNS table  AS  
return (
   SELECT R.PersonID1, C1.CustName,C1.CustName_L2, C1.Address,len(C1.Address) as LenAddress,
    C1.PostalCode, C1.EconomicNumber, C1.NationalCode
	,case when @StuffShow = 0   then Ri.StuffCode 
          when @StuffShow = 200 then Cast(R.Reciptnumber AS BigInt)
          when @StuffShow = 201 then Cast(R.PersonID1 AS BigInt)
	    else Cast( StuffGroups.GroupID AS BigInt) end AS GroupID
	,case when @StuffShow = 0   then StuffCoding.c_StuffName 
          when @StuffShow = 200 then C1.CustName
          when @StuffShow = 201 then C1.CustName
	else StuffGroups.GroupName end AS c_StuffName
    , SUM ( case when ( ReciptTypes.CommissionActive = 2 and Ri.UnitCommission >0 ) then
    (Ri.InputEntity + Ri.OutputEntity ) * Ri.UnitCommission else
    CASE ReciptTypes.SellEffect WHEN 1 THEN 1 ELSE -1 END *(Ri.TotalOutputPrice + Ri.TotalInputPrice) end ) AS TotalOutputPrice
	,
    sum (CASE ReciptTypes.SellEffect WHEN 1 THEN
    - isnull(Ri.DeficitValue, 0)- Ri.DeficitValue2 - Ri.DeficitValue4 -  case when DiscountActive & 8 = 8 then 0 else  Ri.DeficitValue3 end
    ELSE + isnull(Ri.DeficitValue,0)+ Ri.DeficitValue2+ Ri.DeficitValue4 + Ri.DeficitValue3 END) as DeficitValue

, SUM ( case when ( ReciptTypes.CommissionActive = 2 and Ri.UnitCommission >0 ) then
    (Ri.InputEntity + Ri.OutputEntity ) * Ri.UnitCommission else
    CASE ReciptTypes.SellEffect WHEN 1 THEN 1 ELSE -1 END *(Ri.TotalOutputPrice + Ri.TotalInputPrice) end )
	+
	sum (CASE ReciptTypes.SellEffect WHEN 1 THEN
    - isnull(Ri.DeficitValue, 0)- Ri.DeficitValue2 - Ri.DeficitValue4 -  case when DiscountActive & 8 = 8 then 0 else  Ri.DeficitValue3 end
    ELSE + isnull(Ri.DeficitValue,0)+ Ri.DeficitValue2+ Ri.DeficitValue4 + Ri.DeficitValue3 END) 
	
	AS TotalOutputPriceDeficitValue

    , C1.City, CASE C1.NationalID WHEN '0' THEN '' ELSE C1.NationalID END AS NationalID
    , C1.Tel
    , CASE ReciptTypes.SellEffect WHEN 1 THEN 1 ELSE -1 END * SUM(Ri.TaxValue) AS TaxValue
    , ROUND((CASE ReciptTypes.SellEffect WHEN 1 THEN 1 ELSE -1 END * SUM(Ri.TaxValue) * CAST( @Tax AS
    Float) )/ CAST( @TaxTown AS Float) ,0) AS TaxValueOnTax
    , ROUND((CASE ReciptTypes.SellEffect WHEN 1 THEN 1 ELSE -1 END * SUM(Ri.TaxValue) * CAST( @Town AS
    Float))/ CAST( @TaxTown1 AS Float) ,0) AS TaxValueOnTown

    , CASE ReciptTypes.SellEffect WHEN 1 THEN 1 ELSE -1 END * SUM(Ri.TotallSellPrice)
    - SUM( case when ( ReciptTypes.CommissionActive =2 and Ri.UnitCommission >0 ) then
    Ri.TotalOutputPrice - Ri.TotalInputPrice else 0 end )
    - SUM(ISNULL(Ri.Portage, 0)) AS TotallSellPrice
    , C1.RegisterNumber, C1.HCTarafGaradadTypeCode, C1.HCKharidarTypeCode, C1.CustFirstName,
    C1.PerCityCode,
    C1.StateCode, C1.CityCode, Zone.Shahr, Zone_StateCode.Ostan, C1.Mobile,
    CASE WHEN C1.CustName LIKE N'%'+ ISNULL(C1.CustFirstName, '') +'%' THEN C1.CustName
    ELSE C1.CustName + ' ' + ISNULL(C1.CustFirstName, '') END AS FullCustName
    ,ReciptTypes.SellEffect
      --,R.ReciptDate AS ReciptDate,R.Reciptnumber,
	  --	--,case when @StuffShow = 201 then str(@YearIDFrom)+case when @SeasonFrom = 1 then '/03/31' when @SeasonFrom = 4 then '/06/31' when @SeasonFrom = 7 then '/09/30' else '/12/29' end	    else R.ReciptDate end AS ReciptDate
	  ,MAX(R.ReciptDate) AS ReciptDate
	,case when @StuffShow = 201 then 0
	    else R.Reciptnumber end AS Reciptnumber
	,MAX(R.TAXID) AS TAXID,

	  
	  
	  SellsMethods.VajhTypes, StuffGroups.SarFaslType
      ,StuffGroups.KalaType

      , RT.ForoushType, RT.KeshvarCode, RT.Kotaj_No, 
     RT.Kotaj_Date AS Kotaj_Date, RT.LC_No,
      RT.LC_Date AS LC_Date, 
      RT.GOmrok_Arzyabi,RT.GOmrok_khoruj,RT.AmountDeclaration,RT.AmountDeclarationArz
	  ,RT.RTCarton,RT.RTWeight,RT.ArzType
	  ,case when @chkPriceParvane=1 then 
	     SUM(((( SD1Weight*InBox*OutputEntity)/1000)*StuffpublicPercentI))
		else 0.0 end AS Arz_PriceParvane 
	  ,SUM(ArzAmount)ArzAmount 
	  ,SUM(ArzAmount * RialsEqual) as MoadelRialiPrice

      --, R.ReciptID, R.ServerID
	  ,case when @StuffShow = 201 then 0
	    else R.ReciptID end  AS ReciptID
	,case when @StuffShow = 201 then 0
	    else R.ServerID end ServerID
		, R.YearID


	  ,case when @chkPriceParvane=1 then 
             ROUND(SUM( (ISNULL(StuffCoding.StuffWeight,0)*(Ri.InputWeight + Ri.OutputWeight )/1000.0)
             *  ISNULL(Ri.StuffpublicPercentI,0)) * ISNULL(R.RialsEqual,0) ,0)
		else
            ROUND(SUM( (ISNULL(1,0)*(Ri.InputWeight + Ri.OutputWeight )/1000.0)
            *  ISNULL(Ri.StuffpublicPercentI,0)) * ISNULL(R.RialsEqual,0) ,0) end
	    AS PriceParvane
      --  AS PriceParvane // ISNULL(Ri.ArzRate,0) *
     ,ArzLookUps.Name AS ArzName,R.RialsEqual ,min( Ri.StuffpublicPercentI) AS StuffpublicPercentI ,SUM( ReciptItemSum_Darayi.SumTotalOutputPrice)SumTotalOutputPrice
	 ,sum(Ri.InputEntity+ri.OutputEntity) AS Entity ,SUM(Ri.InputWeight+ri.OutputWeight) AS Weight, AVG(Ri.UnitSellPrice) AS UnitSellPrice,
	 CASE R.tax_status WHEN 1 THEN 'ارسال شده'  WHEN 0 THEN 'خطا در ارسال' WHEN 2 THEN 'در صف انتظار تائید' ELSE 'آماده جهت ارسال'  END AS tax_statusNote

	 , CASE C3.NationalID WHEN '0' THEN '' ELSE C3.NationalID END AS NationalIDC3
	 , C3.Mobile MobileC3
	 , CASE WHEN C3.CustName LIKE N'%'+ ISNULL(C3.CustFirstName, '') +'%' THEN C3.CustName   ELSE C3.CustName + ' ' + ISNULL(C3.CustFirstName, '') END AS FullCustNameC3
    FROM ReciptItems Ri INNER JOIN
    Recipts R ON R.ReciptID = Ri.ReciptID AND R.ServerID = Ri.ServerID AND
    R.YearID = Ri.YearID INNER JOIN
    Customers C1 ON R.PersonID1 = C1.CustID INNER JOIN
    Customers C3 ON R.PersonID3 = C3.CustID	INNER JOIN
    StuffCoding ON Ri.StuffCode = StuffCoding.c_StuffCode INNER JOIN
    ReciptTypes ON R.ReciptType = ReciptTypes.ReciptType INNER JOIN
    StuffGroups ON StuffCoding.GroupID = StuffGroups.GroupID
--   (SELECT DISTINCT CASE WHEN @StuffShow = 2 THEN StuffGroups_2.GroupID
--					     WHEN @StuffShow = 1 THEN StuffGroups_1.GroupID
--					                ELSE StuffGroups.GroupID END AS GroupID, StuffGroups.GroupName
--												  , StuffGroups_1.GroupID AS GroupID2, StuffGroups_1.GroupName AS GroupName2, 
--      StuffGroups_2.GroupID AS GroupID3, StuffGroups_2.GroupName AS GroupName3
--   ,StuffGroups.SarFaslType,StuffGroups.KalaType
--FROM            StuffGroups AS StuffGroups_2 INNER JOIN
--                         StuffGroups AS StuffGroups_1 ON StuffGroups_2.UperGroupId = StuffGroups_1.GroupID RIGHT OUTER JOIN
--                         StuffGroups ON StuffGroups_1.UperGroupId = StuffGroups.GroupID)as StuffGroups ON StuffCoding.GroupID =
						 
--			CASE WHEN @StuffShow = 2 THEN StuffGroups.GroupID3
--				WHEN @StuffShow = 1 THEN StuffGroups.GroupID2
--						            ELSE case when StuffGroups.GroupID = 0 then StuffGroups.GroupID3 else StuffGroups.GroupID end  END


    LEFT OUTER JOIN
    dbo.Zone ON C1.CityCode = Zone.ShahrCode LEFT OUTER JOIN
    (SELECT DISTINCT OstanCode, Ostan
    FROM Zone) AS Zone_StateCode ON C1.StateCode = Zone_StateCode.OstanCode

      INNER JOIN SellsMethods ON R.SellsMethod = SellsMethods.SellsMethod
      LEFT OUTER JOIN ReciptsTrades RT ON R.ReciptID = RT.ReciptID 
      AND R.ServerID = RT.ServerID AND R.YearID = RT.YearID

    LEFT OUTER JOIN  LookUps ArzLookUps ON R.ArzTypeID = ArzLookUps.LookUpID 
      INNER JOIN ReciptItemSum_Darayi ON R.ReciptID = ReciptItemSum_Darayi.ReciptID 
      AND R.ServerID = ReciptItemSum_Darayi.ServerID AND R.YearID = ReciptItemSum_Darayi.YearID


    WHERE (ReciptTypes.SellEffect <> 0) And
    (R.PersonID1 BETWEEN @CustIdFrom AND @CustIdTo) AND
    (StuffGroups.GroupID BETWEEN @StuffGrpFrom AND @StuffGrpTo)AND
    ( CAST(SUBSTRING(R.ReciptDate, 6, 2) AS int) BETWEEN @SeasonFrom AND @SeasonTo ) AND
    ( R.ReciptDate BETWEEN @DateFrom AND @DateTo ) 
	AND ( C1.CustomerGrpID BETWEEN @CustomerGrpIDFrom AND @CustomerGrpIDTo)
    AND ( R.ReciptState < 3)
--	AND ((@StuffKindActive='-1') or StuffCoding.OwnerShipKind in (select part from SplitString(@StuffKindActive,',') ))
	AND ((@StuffKindActive='-1') or exists( Select part From dbo.SplitString(@StuffKindActive,',') where part = StuffCoding.OwnerShipKind)) 
	AND ((@ReciptsSecondType='-1') or R.SecondType in (select part from SplitString(@ReciptsSecondType,',') ))

    AND (R.SellsEmporium BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)
    And ((@INSellsEmporium='-1') or exists( Select part From dbo.SplitString(@INSellsEmporium,',') where part = R.SellsEmporium)) 
    And ((@NotSellsEmporium='-1') or Not exists( Select part From dbo.SplitString(@NotSellsEmporium,',') where part = R.SellsEmporium)) 

    AND (R.SellsMethod BETWEEN @SellsMethodFrom AND @SellsMethodTo)
    And ((@INSellsMethod='-1') or exists( Select part From dbo.SplitString(@INSellsMethod,',') where part = R.SellsMethod)) 
    And ((@NotSellsMethod='-1') or Not exists( Select part From dbo.SplitString(@NotSellsMethod,',') where part = R.SellsMethod)) 

    AND (R.YearID BETWEEN @YearIDFrom AND @YearIDTo)
    AND ((@StoreID='-1') or R.StoreID in (select part from SplitString(@StoreID,',') ))
    AND ((ISNULL(LEN(C1.EconomicNumber) + LEN(C1.NationalID), 0) <> 0) OR 0 = @EconomicNumberNationalID )
	AND ((@tax_status='-1') or exists( Select part From dbo.SplitString(@tax_status,',') where part =CASE WHEN R.tax_status = 0 THEN 0 WHEN R.tax_status = 1 THEN 1 ELSE 2 END)) 

    GROUP BY R.PersonID1, C1.CustName,C1.CustName_L2, C1.Address, C1.PostalCode, C1.EconomicNumber, C1.NationalCode,
		 C3.NationalID , C3.Mobile , C3.CustFirstName,  C3.CustName ,

    
    ReciptTypes.SellEffect, C1.City, C1.NationalID, C1.Tel
    , C1.RegisterNumber, C1.HCTarafGaradadTypeCode, C1.HCKharidarTypeCode, C1.CustFirstName,
    C1.PerCityCode,
    C1.StateCode, C1.CityCode, Zone.Shahr, Zone_StateCode.Ostan, C1.Mobile
      --,R.ReciptDate,R.Reciptnumber,
--	  --,case when @StuffShow = 201 then str(@YearIDFrom)+case when @SeasonFrom = 1 then '/03/31' when @SeasonFrom = 4 then '/06/31' when @SeasonFrom = 7 then '/09/30' else '/12/29' end	    else R.ReciptDate end 
		  
,case when @StuffShow = 201 then 0
	    else R.Reciptnumber end ,


	  SellsMethods.VajhTypes, StuffGroups.SarFaslType
      ,StuffGroups.KalaType
      , RT.ForoushType, RT.KeshvarCode, RT.Kotaj_No, 
      RT.Kotaj_Date, RT.LC_No, RT.LC_Date, 
      RT.GOmrok_Arzyabi,RT.GOmrok_khoruj,RT.AmountDeclaration,RT.AmountDeclarationArz
     ,RT.RTCarton,RT.RTWeight,RT.ArzType
--, R.ReciptID, R.ServerID
	  ,case when @StuffShow = 201 then 0
	    else R.ReciptID end
	,case when @StuffShow = 201 then 0
	    else R.ServerID end 
		, R.YearID ,
	  
	  R.RialsEqual
	,case when @StuffShow = 0   then Ri.StuffCode 
          when @StuffShow = 200 then Cast(R.Reciptnumber AS BigInt)
          when @StuffShow = 201 then Cast(R.PersonID1 AS BigInt)
	    else Cast( StuffGroups.GroupID AS BigInt) end
	,case when @StuffShow = 0   then StuffCoding.c_StuffName 
          when @StuffShow = 200 then C1.CustName
          when @StuffShow = 201 then C1.CustName
	else StuffGroups.GroupName end 
	 ,ArzLookUps.Name ,R.RialsEqual--,ReciptItemSum_Darayi.SumTotalOutputPrice
    --ORDER BY ReciptTypes.SellEffect
	,R.tax_status
	UNION ALL 

SELECT R.PersonID1, C1.CustName,C1.CustName_L2, 
C1.Address,len(C1.Address) as LenAddress,
C1.PostalCode, C1.EconomicNumber, C1.NationalCode
, 0 AS GroupID,min(Deficits.DeficitName)+'...'+max(Deficits.DeficitName) AS c_StuffName
, SUM ( (ReciptsDeficits.DeficitAdd -ReciptsDeficits.DeficitDec) ) AS TotalOutputPrice
,0 as DeficitValue
, SUM ( (ReciptsDeficits.DeficitAdd -ReciptsDeficits.DeficitDec) ) AS TotalOutputPriceDeficitValue
, C1.City, CASE C1.NationalID WHEN '0' THEN '' ELSE C1.NationalID END AS NationalID
, C1.Tel
, CASE ReciptTypes.SellEffect WHEN 1 THEN 1 ELSE -1 END * SUM(0) AS TaxValue
, ROUND((CASE ReciptTypes.SellEffect WHEN 1 THEN 1 ELSE -1 END * SUM(0) * CAST( @Tax AS
Float) )/ CAST( @TaxTown AS Float) ,0) AS TaxValueOnTax
, ROUND((CASE ReciptTypes.SellEffect WHEN 1 THEN 1 ELSE -1 END * SUM(0) * CAST( @Town AS
Float))/ CAST( @TaxTown1 AS Float) ,0) AS TaxValueOnTown
, CASE ReciptTypes.SellEffect WHEN 1 THEN 1 ELSE -1 END * SUM(0) AS TotallSellPrice
, C1.RegisterNumber, C1.HCTarafGaradadTypeCode, C1.HCKharidarTypeCode, C1.CustFirstName,
C1.PerCityCode,
C1.StateCode, C1.CityCode, Zone.Shahr, Zone_StateCode.Ostan, C1.Mobile,
CASE WHEN C1.CustName LIKE N'%'+ ISNULL(C1.CustFirstName, '') +'%' THEN C1.CustName
ELSE C1.CustName + ' ' + ISNULL(C1.CustFirstName, '') END AS FullCustName
,ReciptTypes.SellEffect
      --,R.ReciptDate AS ReciptDate,R.Reciptnumber,
	 -- 	--,case when @StuffShow = 201 then str(@YearIDFrom)+case when @SeasonFrom = 1 then '/03/31' when @SeasonFrom = 4 then '/06/31' when @SeasonFrom = 7 then '/09/30' else '/12/29' end	    else R.ReciptDate end AS ReciptDate
	  ,max(R.ReciptDate) AS ReciptDate

	,case when @StuffShow = 201 then 0
	    else R.Reciptnumber end AS Reciptnumber
	,MAX(R.TAXID) AS TAXID,

		

SellsMethods.VajhTypes, 0 as SarFaslType
, 12 as  KalaType
, RT.ForoushType, RT.KeshvarCode, RT.Kotaj_No, 
RT.Kotaj_Date AS Kotaj_Date, RT.LC_No,
RT.LC_Date AS LC_Date, 
RT.GOmrok_Arzyabi,RT.GOmrok_khoruj,RT.AmountDeclaration,RT.AmountDeclarationArz
     ,RT.RTCarton,RT.RTWeight,RT.ArzType
	  
	  , 0  AS Arz_PriceParvane 
	  ,SUM(ArzAmount)ArzAmount 
	  ,SUM(ArzAmount * RialsEqual) as MoadelRialiPrice


      --, R.ReciptID, R.ServerID
	  ,case when @StuffShow = 201 then 0
	    else R.ReciptID end AS ReciptID
	,case when @StuffShow = 201 then 0
	    else R.ServerID end ServerID
		, R.YearID
,0 * ISNULL(R.RialsEqual,0) AS PriceParvane     ,ArzLookUps.Name AS ArzName,R.RialsEqual,0.0 as StuffpublicPercentI
--,ReciptItemSum_Darayi.SumTotalOutputPrice
,SUM ( (ReciptsDeficits.DeficitAdd -ReciptsDeficits.DeficitDec) ) AS SumTotalOutputPrice
,0.0 AS Entity,0.0 AS Weight , 0 AS UnitSellPrice,CASE R.tax_status WHEN 1 THEN 'ارسال شده'  WHEN 0 THEN 'خطا در ارسال' WHEN 2 THEN 'در صف انتظار تائید' ELSE 'آماده جهت ارسال' END AS tax_statusNote
	 , CASE C3.NationalID WHEN '0' THEN '' ELSE C3.NationalID END AS NationalIDC3
	 , C3.Mobile MobileC3
	 , CASE WHEN C3.CustName LIKE N'%'+ ISNULL(C3.CustFirstName, '') +'%' THEN C3.CustName   ELSE C3.CustName + ' ' + ISNULL(C3.CustFirstName, '') END AS FullCustNameC3

FROM            Recipts R  INNER JOIN
    Customers C1 ON R.PersonID1 = C1.CustID INNER JOIN
    Customers C3 ON R.PersonID3 = C3.CustID	INNER JOIN
                         ReciptTypes ON R.ReciptType = ReciptTypes.ReciptType  LEFT OUTER JOIN
                         Zone ON C1.CityCode = Zone.ShahrCode LEFT OUTER JOIN
                             (SELECT DISTINCT OstanCode, Ostan
                                FROM            Zone AS Zone_1) AS Zone_StateCode ON C1.StateCode = Zone_StateCode.OstanCode INNER JOIN
                         SellsMethods ON R.SellsMethod = SellsMethods.SellsMethod INNER JOIN
                         ReciptsDeficits ON R.ReciptID = ReciptsDeficits.ReciptID AND R.ServerID = ReciptsDeficits.ServerID AND R.YearID = ReciptsDeficits.YearID LEFT OUTER JOIN
                         ReciptsTrades RT ON R.ReciptID = RT.ReciptID AND R.ServerID = RT.ServerID AND R.YearID = RT.YearID
    LEFT OUTER JOIN  LookUps ArzLookUps ON R.ArzTypeID = ArzLookUps.LookUpID JOIN
	Deficits ON Deficits.DeficitID = ReciptsDeficits.DeficitID
 --     INNER JOIN ReciptItemSum_Darayi ON R.ReciptID = ReciptItemSum_Darayi.ReciptID 
  --    AND R.ServerID = ReciptItemSum_Darayi.ServerID AND R.YearID = ReciptItemSum_Darayi.YearID
WHERE (ReciptTypes.SellEffect <> 0) AND (Deficits.TTMSActive = 1)
	And (R.PersonID1 BETWEEN @CustIdFrom AND @CustIdTo) 
	--AND (StuffGroups.GroupID BETWEEN @StuffGrpFrom AND @StuffGrpTo)
	AND (CAST(SUBSTRING(R.ReciptDate, 6, 2) AS int) BETWEEN @SeasonFrom AND @SeasonTo ) 
	AND (R.ReciptDate BETWEEN @DateFrom AND @DateTo ) 
	AND (C1.CustomerGrpID BETWEEN @CustomerGrpIDFrom AND @CustomerGrpIDTo)
    AND (R.ReciptState < 3)
	--AND ((@StuffKActive='-1') or StuffCoding.OwnerShipKind in (select part from SplitString(@StuffKindActive,',') ))
    AND ((@ReciptsSecondType='-1') or R.SecondType in (select part from SplitString(@ReciptsSecondType,',') ))

    AND (R.SellsEmporium BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)
    And ((@INSellsEmporium='-1') or exists( Select part From dbo.SplitString(@INSellsEmporium,',') where part = R.SellsEmporium)) 
    And ((@NotSellsEmporium='-1') or Not exists( Select part From dbo.SplitString(@NotSellsEmporium,',') where part = R.SellsEmporium)) 

    AND (R.SellsMethod BETWEEN @SellsMethodFrom AND @SellsMethodTo)
    And ((@INSellsMethod='-1') or exists( Select part From dbo.SplitString(@INSellsMethod,',') where part = R.SellsMethod)) 
    And ((@NotSellsMethod='-1') or Not exists( Select part From dbo.SplitString(@NotSellsMethod,',') where part = R.SellsMethod)) 



    AND (R.YearID BETWEEN @YearIDFrom AND @YearIDTo)
    AND ((@StoreID='-1') or R.StoreID in (select part from SplitString(@StoreID,',') ))
    AND ((ISNULL(LEN(C1.EconomicNumber) + LEN(C1.NationalID), 0) <> 0) OR 0 = @EconomicNumberNationalID )
	AND ((@tax_status='-1') or exists( Select part From dbo.SplitString(@tax_status,',') where part =CASE  WHEN R.tax_status = 0 THEN 0 WHEN R.tax_status = 1 THEN 1  ELSE 2 END)) 


GROUP BY R.PersonID1, C1.CustName,C1.CustName_L2, C1.Address, C1.PostalCode, C1.EconomicNumber, C1.NationalCode,
		 C3.NationalID , C3.Mobile , C3.CustFirstName,  C3.CustName ,

ReciptTypes.SellEffect, C1.City, C1.NationalID, C1.Tel
, C1.RegisterNumber, C1.HCTarafGaradadTypeCode, C1.HCKharidarTypeCode, C1.CustFirstName,
C1.PerCityCode,
C1.StateCode, C1.CityCode, Zone.Shahr, Zone_StateCode.Ostan, C1.Mobile
      --,R.ReciptDate AS ReciptDate,R.Reciptnumber,
	  	----,case when @StuffShow = 201 then str(@YearIDFrom)+case when @SeasonFrom = 1 then '/03/31' when @SeasonFrom = 4 then '/06/31' when @SeasonFrom = 7 then '/09/30' else '/12/29' end	    else R.ReciptDate end 
	,case when @StuffShow = 201 then 0
	    else R.Reciptnumber end ,

SellsMethods.VajhTypes
, RT.ForoushType, RT.KeshvarCode, RT.Kotaj_No, 
RT.Kotaj_Date, RT.LC_No, RT.LC_Date, 
RT.GOmrok_Arzyabi,RT.GOmrok_khoruj,RT.AmountDeclaration,RT.AmountDeclarationArz
     ,RT.RTCarton,RT.RTWeight,RT.ArzType
      --, R.ReciptID, R.ServerID
	  ,case when @StuffShow = 201 then 0
	    else R.ReciptID end 
	,case when @StuffShow = 201 then 0
	    else R.ServerID end 
		, R.YearID,
R.RialsEqual,R.tax_status
,ArzLookUps.Name--,ReciptItemSum_Darayi.SumTotalOutputPrice
)
