CREATE  FUNCTION Fn_DarayiBuys ( @FormType int ,
  @Tax Float
, @TaxTown Float
, @Town Float
, @TaxTown1 Float
, @CustIdFrom int
, @CustIdTo int
, @StuffGrpFrom int
, @StuffGrpTo int
, @SeasonFrom int
, @SeasonTo int
, @DateFrom char(10)
, @DateTo char(10)
, @CustomerGrpIDFrom int
, @CustomerGrpIDTo int
, @SellsEmporiumFrom int
, @SellsEmporiumTo int
, @NotSellsEmporium int
, @YearIDFrom int
, @YearIDTo int
, @StoreID  varchar(1000) ='21,32,31,30,26,20,0'
, @StuffShow int =0
, @StuffKindActive varchar(20) ='0,1'
, @ReciptsSecondType varchar(200) ='21,32,31,30,26,20,0'
, @INSellsEmporium varchar(2000) =''
, @SellsMethodFrom int
, @SellsMethodTo int
, @NotSellsMethod varchar(2000) =''
, @INSellsMethod varchar(2000) ='' 
)

RETURNS table  AS  
return (
    SELECT case when @FormType <> 0 then  Ri.PersonID1 else R.PersonID1 end as PersonID1, Customers.CustName,Customers.CustName_L2, 
    Customers.Address ,len(Customers.Address) as LenAddress,
    Customers.PostalCode, Customers.EconomicNumber, Customers.NationalCode
		  
     	,case when @StuffShow = 0   then Ri.StuffCode 
          when @StuffShow = 200 then Cast(R.Reciptnumber AS BigInt)
          when @StuffShow = 201 then Cast(R.PersonID1 AS BigInt)
	    else Cast( StuffGroups.GroupID AS BigInt) end AS GroupID
	,case when @StuffShow = 0   then StuffCoding.c_StuffName 
          when @StuffShow = 200 then Customers.CustName
          when @StuffShow = 201 then Customers.CustName
	else StuffGroups.GroupName end AS c_StuffName



    ,SUM( Ri.TotalInputPrice -Ri.TotalOutputPrice )  AS TotalPrice
    ,SUM(case ReciptTypes.BuyEffect when 1 then - isnull(Ri.DeficitValue,0)- Ri.DeficitValue2 - Ri.DeficitValue4 - Ri.DeficitValue3
    else + isnull(Ri.DeficitValue,0)+ Ri.DeficitValue2 + Ri.DeficitValue4 + Ri.DeficitValue3 end) as DeficitValue
    , Customers.Tel , Customers.City ,
    CASE Customers.NationalID WHEN '0' THEN '' ELSE Customers.NationalID END AS NationalID,
	Max(Ri.TaxCo) TaxCo,
    case ReciptTypes.BuyEffect when 1 then 1 else - 1 end * SUM(Ri.TaxValue) AS TaxValue,

	case when @TaxTown <>0 then
      ROUND( (case ReciptTypes.BuyEffect when 1 then 1 else - 1 end * SUM(Ri.TaxValue)* CAST( @Tax AS FLOAT)) /
      CAST( @TaxTown AS FLOAT) ,0) 
	else 0 end
	
	AS TaxValueOnTax,
   
	case when @TaxTown1 <>0 then
      ROUND( (case ReciptTypes.BuyEffect when 1 then 1 else - 1 end * SUM(Ri.TaxValue)* CAST( @Town AS FLOAT))/
       CAST( @TaxTown1 AS FLOAT) ,0)
	else 0 end	   
	   AS TaxValueOnTown,

    case ReciptTypes.BuyEffect when 1 then 1 else - 1 end * SUM(Ri.TotallSellPrice)
    - SUM(ISNULL(Ri.Portage, 0)) AS TotallSellPrice  

    , Customers.RegisterNumber, Customers.HCTarafGaradadTypeCode, Customers.HCKharidarTypeCode, Customers.CustFirstName,
    Customers.PerCityCode,
    Customers.StateCode, Customers.CityCode, Zone.Shahr, Zone_StateCode.Ostan, Customers.Mobile,
    CASE WHEN Customers.CustName LIKE N'%'+ ISNULL(Customers.CustFirstName, '') +'%' THEN Customers.CustName
    ELSE Customers.CustName + ' ' + ISNULL(Customers.CustFirstName, '') END AS FullCustName
    ,Customers.HCForoushandeType1Code
    ,ReciptTypes.BuyEffect

      --,R.ReciptDate AS ReciptDate,R.Reciptnumber,
	  	--,case when @StuffShow = 201 then str(@YearIDFrom)+case when @SeasonFrom = 1 then '/03/31' when @SeasonFrom = 4 then '/06/31' when @SeasonFrom = 7 then '/09/30' else '/12/29' end	    else R.ReciptDate end AS ReciptDate
	  ,MAX(R.ReciptDate) AS ReciptDate
	,case when @StuffShow = 201 then 0
	    else R.Reciptnumber end AS Reciptnumber,
	  
	  SellsMethods.VajhTypes, StuffGroups.SarFaslType
      ,StuffGroups.KalaType,ReciptTypes.SellEffect
	        --, R.ReciptID, R.ServerID
	  ,case when @StuffShow = 201 then 0
	    else R.ReciptID end  AS ReciptID
	,case when @StuffShow = 201 then 0
	    else R.ServerID end ServerID
		, R.YearID
    ,ArzLookUps.Name AS ArzName,R.RialsEqual      , RT.ForoushType, RT.KeshvarCode, RT.Kotaj_No, 
     RT.Kotaj_Date AS Kotaj_Date, RT.LC_No,
      RT.LC_Date AS LC_Date, 
      RT.GOmrok_Arzyabi,RT.GOmrok_khoruj,RT.AmountDeclaration,RT.AmountDeclarationArz
	  ,RT.RTCarton,RT.RTWeight,RT.ArzType
	  ,sum(Ri.InputEntity+ri.OutputEntity) AS Entity,SUM(Ri.InputWeight+ri.OutputWeight) AS Weight , AVG(Ri.UnitSellPrice) AS UnitSellPrice
	  , max(R.REFERENCENUMBER) AS REFERENCENUMBER ,max(R.TAXID) AS TAXID,max(R.ID) AS ID

    FROM ReciptItems Ri INNER JOIN
    Recipts R ON R.ReciptID = Ri.ReciptID AND
    R.ServerID = Ri.ServerID AND R.YearID = Ri.YearID INNER
    JOIN
    Customers ON case when @FormType <> 0 then  Ri.PersonID1 else R.PersonID1 end = Customers.CustID INNER JOIN
    StuffCoding ON Ri.StuffCode = StuffCoding.c_StuffCode INNER JOIN
    ReciptTypes ON R.ReciptType = ReciptTypes.ReciptType INNER JOIN
    StuffGroups ON StuffCoding.GroupID = StuffGroups.GroupID
--   (SELECT DISTINCT CASE WHEN @StuffShow = 2 THEN StuffGroups_2.GroupID
--					     WHEN @StuffShow = 1 THEN StuffGroups_1.GroupID
--					                ELSE StuffGroups.GroupID END AS GroupID, StuffGroups.GroupName
--												  , StuffGroups_1.GroupID AS GroupID2, StuffGroups_1.GroupName AS GroupName2, 
--      StuffGroups_2.GroupID AS GroupID3, StuffGroups_2.GroupName AS GroupName3
--   ,StuffGroups.SarFaslType,StuffGroups.KalaType
--FROM            StuffGroups AS StuffGroups_2 INNER JOIN
--                         StuffGroups AS StuffGroups_1 ON StuffGroups_2.UperGroupId = StuffGroups_1.GroupID RIGHT OUTER JOIN
--                         StuffGroups ON StuffGroups_1.UperGroupId = StuffGroups.GroupID)as StuffGroups ON StuffCoding.GroupID =
						 
--			CASE WHEN @StuffShow = 2 THEN StuffGroups.GroupID3
--				WHEN @StuffShow = 1 THEN StuffGroups.GroupID2
--						            ELSE case when StuffGroups.GroupID = 0 then StuffGroups.GroupID3 else StuffGroups.GroupID end  END


    INNER JOIN
    Zone ON Customers.CityCode = Zone.ShahrCode INNER JOIN
    (SELECT DISTINCT OstanCode, Ostan
    FROM Zone) AS Zone_StateCode ON Customers.StateCode = Zone_StateCode.OstanCode

      INNER JOIN SellsMethods ON R.SellsMethod = SellsMethods.SellsMethod
    LEFT OUTER JOIN  LookUps ArzLookUps ON R.ArzTypeID = ArzLookUps.LookUpID 
      LEFT OUTER JOIN ReciptsTrades RT ON R.ReciptID = RT.ReciptID 
      AND R.ServerID = RT.ServerID AND R.YearID = RT.YearID


    WHERE (ReciptTypes.BuyEffect <> 0 )AND
    ( CAST(SUBSTRING(R.ReciptDate, 6, 2) AS int) BETWEEN @SeasonFrom AND @SeasonTo ) AND
    ( R.ReciptDate BETWEEN @DateFrom AND @DateTo ) AND
    ( Customers.CustomerGrpID BETWEEN @CustomerGrpIDFrom AND @CustomerGrpIDTo) AND
    ( R.ReciptState < 3)

	AND ((@StuffKindActive='-1') or StuffCoding.OwnerShipKind in (select part from SplitString(@StuffKindActive,',') ))
	AND ((@ReciptsSecondType='-1') or R.SecondType in (select part from SplitString(@ReciptsSecondType,',') ))

    AND (R.SellsEmporium BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)
    And ((@INSellsEmporium='-1') or exists( Select part From dbo.SplitString(@INSellsEmporium,',') where part = R.SellsEmporium)) 
    And ((@NotSellsEmporium='-1') or Not exists( Select part From dbo.SplitString(@NotSellsEmporium,',') where part = R.SellsEmporium)) 

    AND (R.SellsMethod BETWEEN @SellsMethodFrom AND @SellsMethodTo)
    And ((@INSellsMethod='-1') or exists( Select part From dbo.SplitString(@INSellsMethod,',') where part = R.SellsMethod)) 
    And ((@NotSellsMethod='-1') or Not exists( Select part From dbo.SplitString(@NotSellsMethod,',') where part = R.SellsMethod)) 

    AND (R.YearID BETWEEN @YearIDFrom AND @YearIDTo)
    AND ( case when @FormType <> 0 then  Ri.PersonID1 else R.PersonID1 end BETWEEN @CustIdFrom AND @CustIdTo) 
    AND( StuffGroups.GroupID BETWEEN @StuffGrpFrom AND @StuffGrpTo)
    AND ((@StoreID='-1') or R.StoreID in (select part from SplitString(@StoreID,',') ))

    GROUP BY case when @FormType <> 0 then  Ri.PersonID1 else R.PersonID1 end, Customers.CustName,Customers.CustName_L2, Customers.Address, Customers.PostalCode, Customers.EconomicNumber, Customers.NationalCode,
    --StuffGroups.GroupID,    StuffGroups.GroupName,
	Customers.City, Customers.NationalID, Customers.Tel
    , Customers.RegisterNumber, Customers.HCTarafGaradadTypeCode, Customers.HCKharidarTypeCode, Customers.CustFirstName,
    Customers.PerCityCode,
    Customers.StateCode, Customers.CityCode,Zone.Shahr, Zone_StateCode.Ostan, Customers.Mobile
    ,Customers.HCForoushandeType1Code

      --,R.ReciptDate AS ReciptDate,R.Reciptnumber,
	  	--,case when @StuffShow = 201 then str(@YearIDFrom)+case when @SeasonFrom = 1 then '/03/31' when @SeasonFrom = 4 then '/06/31' when @SeasonFrom = 7 then '/09/30' else '/12/29' end	    else R.ReciptDate end 
	,case when @StuffShow = 201 then 0
	    else R.Reciptnumber end ,
	  
	  SellsMethods.VajhTypes, StuffGroups.SarFaslType
      ,StuffGroups.KalaType

	,case when @StuffShow = 0   then Ri.StuffCode 
          when @StuffShow = 200 then Cast(R.Reciptnumber AS BigInt)
          when @StuffShow = 201 then Cast(R.PersonID1 AS BigInt)
	    else Cast( StuffGroups.GroupID AS BigInt) end
	,case when @StuffShow = 0   then StuffCoding.c_StuffName 
          when @StuffShow = 200 then Customers.CustName
          when @StuffShow = 201 then Customers.CustName
	else StuffGroups.GroupName end 

    ,ReciptTypes.BuyEffect
	      --, R.ReciptID, R.ServerID
	  ,case when @StuffShow = 201 then 0
	    else R.ReciptID end  
	,case when @StuffShow = 201 then 0
	    else R.ServerID end 
		, R.YearID
	,ReciptTypes.SellEffect,ArzLookUps.Name,R.RialsEqual      , RT.ForoushType, RT.KeshvarCode, RT.Kotaj_No, 
     RT.Kotaj_Date , RT.LC_No,
      RT.LC_Date , 
      RT.GOmrok_Arzyabi,RT.GOmrok_khoruj,RT.AmountDeclaration,RT.AmountDeclarationArz
	  ,RT.RTCarton,RT.RTWeight,RT.ArzType

    --ORDER BY ReciptTypes.BuyEffect


	UNION ALL 

    SELECT R.PersonID1  as PersonID1, Customers.CustName,Customers.CustName_L2, 
    Customers.Address ,len(Customers.Address) as LenAddress,
    Customers.PostalCode, Customers.EconomicNumber, Customers.NationalCode


, 0 AS GroupID,min(Deficits.DeficitName)+'...'+max(Deficits.DeficitName)  AS c_StuffName


, SUM ( (ReciptsDeficits.DeficitAdd -ReciptsDeficits.DeficitDec) ) AS TotalPrice
,0.0  as DeficitValue

    , Customers.Tel , Customers.City ,
    CASE Customers.NationalID WHEN '0' THEN '' ELSE Customers.NationalID END AS NationalID,

    0 TaxCo,
    0 AS TaxValue,
    0 AS TaxValueOnTax,
    0 AS TaxValueOnTown,

    0.0 AS TotallSellPrice

    , Customers.RegisterNumber, Customers.HCTarafGaradadTypeCode, Customers.HCKharidarTypeCode, Customers.CustFirstName,
    Customers.PerCityCode,
    Customers.StateCode, Customers.CityCode, Zone.Shahr, Zone_StateCode.Ostan, Customers.Mobile,
    CASE WHEN Customers.CustName LIKE N'%'+ ISNULL(Customers.CustFirstName, '') +'%' THEN Customers.CustName
    ELSE Customers.CustName + ' ' + ISNULL(Customers.CustFirstName, '') END AS FullCustName
    ,Customers.HCForoushandeType1Code
    ,ReciptTypes.BuyEffect

      --,R.ReciptDate AS ReciptDate,R.Reciptnumber,
	  	--,case when @StuffShow = 201 then str(@YearIDFrom)+case when @SeasonFrom = 1 then '/03/31' when @SeasonFrom = 4 then '/06/31' when @SeasonFrom = 7 then '/09/30' else '/12/29' end	    else R.ReciptDate end AS ReciptDate
	  ,MAX(R.ReciptDate) AS ReciptDate
	,case when @StuffShow = 201 then 0
	    else R.Reciptnumber end AS Reciptnumber,
	  
	  SellsMethods.VajhTypes, 0 as SarFaslType
      ,0 as KalaType,ReciptTypes.SellEffect
	        --, R.ReciptID, R.ServerID
	  ,case when @StuffShow = 201 then 0
	    else R.ReciptID end  AS ReciptID
	,case when @StuffShow = 201 then 0
	    else R.ServerID end ServerID
		, R.YearID
     ,ArzLookUps.Name AS ArzName,R.RialsEqual      , RT.ForoushType, RT.KeshvarCode, RT.Kotaj_No, 
     RT.Kotaj_Date AS Kotaj_Date, RT.LC_No,
      RT.LC_Date AS LC_Date, 
      RT.GOmrok_Arzyabi,RT.GOmrok_khoruj,RT.AmountDeclaration,RT.AmountDeclarationArz
	  ,RT.RTCarton,RT.RTWeight,RT.ArzType

	  ,0.0 AS Entity,0.0 AS Weight , 0 AS UnitSellPrice, max(R.REFERENCENUMBER) AS REFERENCENUMBER ,max(R.TAXID) AS TAXID,max(R.ID) AS ID

    FROM  Recipts R  INNER  JOIN
    Customers ON R.PersonID1 = Customers.CustID  INNER JOIN
    ReciptTypes ON R.ReciptType = ReciptTypes.ReciptType 
    INNER JOIN
    Zone ON Customers.CityCode = Zone.ShahrCode INNER JOIN
    (SELECT DISTINCT OstanCode, Ostan
    FROM Zone) AS Zone_StateCode ON Customers.StateCode = Zone_StateCode.OstanCode

      INNER JOIN SellsMethods ON R.SellsMethod = SellsMethods.SellsMethod INNER JOIN
                         ReciptsDeficits ON R.ReciptID = ReciptsDeficits.ReciptID AND R.ServerID = ReciptsDeficits.ServerID AND R.YearID = ReciptsDeficits.YearID
    LEFT OUTER JOIN  LookUps ArzLookUps ON R.ArzTypeID = ArzLookUps.LookUpID  JOIN
	Deficits ON Deficits.DeficitID = ReciptsDeficits.DeficitID
      LEFT OUTER JOIN ReciptsTrades RT ON R.ReciptID = RT.ReciptID 
      AND R.ServerID = RT.ServerID AND R.YearID = RT.YearID

    WHERE (ReciptTypes.BuyEffect <> 0 ) AND (Deficits.TTMSActive = 1) AND
    ( CAST(SUBSTRING(R.ReciptDate, 6, 2) AS int) BETWEEN @SeasonFrom AND @SeasonTo ) AND
    ( R.ReciptDate BETWEEN @DateFrom AND @DateTo ) AND
    ( Customers.CustomerGrpID BETWEEN @CustomerGrpIDFrom AND @CustomerGrpIDTo) AND
    ( R.ReciptState < 3)


	AND ((@ReciptsSecondType='-1') or R.SecondType in (select part from SplitString(@ReciptsSecondType,',') ))

    AND (R.SellsEmporium BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)
    And ((@INSellsEmporium='-1') or exists( Select part From dbo.SplitString(@INSellsEmporium,',') where part = R.SellsEmporium)) 
    And ((@NotSellsEmporium='-1') or Not exists( Select part From dbo.SplitString(@NotSellsEmporium,',') where part = R.SellsEmporium)) 

    AND (R.SellsMethod BETWEEN @SellsMethodFrom AND @SellsMethodTo)
    And ((@INSellsMethod='-1') or exists( Select part From dbo.SplitString(@INSellsMethod,',') where part = R.SellsMethod)) 
    And ((@NotSellsMethod='-1') or Not exists( Select part From dbo.SplitString(@NotSellsMethod,',') where part = R.SellsMethod)) 

    AND (R.YearID BETWEEN @YearIDFrom AND @YearIDTo)
    AND ( R.PersonID1 BETWEEN @CustIdFrom AND @CustIdTo) 

    AND ((@StoreID='-1') or R.StoreID in (select part from SplitString(@StoreID,',') ))

    GROUP BY R.PersonID1 , Customers.CustName,Customers.CustName_L2, Customers.Address, Customers.PostalCode, Customers.EconomicNumber, Customers.NationalCode,
     Customers.City, Customers.NationalID, Customers.Tel
    , Customers.RegisterNumber, Customers.HCTarafGaradadTypeCode, Customers.HCKharidarTypeCode, Customers.CustFirstName,
    Customers.PerCityCode,
    Customers.StateCode, Customers.CityCode,Zone.Shahr, Zone_StateCode.Ostan, Customers.Mobile
    ,Customers.HCForoushandeType1Code

      --,R.ReciptDate AS ReciptDate,R.Reciptnumber,
	  	--,case when @StuffShow = 201 then str(@YearIDFrom)+case when @SeasonFrom = 1 then '/03/31' when @SeasonFrom = 4 then '/06/31' when @SeasonFrom = 7 then '/09/30' else '/12/29' end	    else R.ReciptDate end 
	,case when @StuffShow = 201 then 0
	    else R.Reciptnumber end ,
	  
	  SellsMethods.VajhTypes


	        --, R.ReciptID, R.ServerID
	  ,case when @StuffShow = 201 then 0
	    else R.ReciptID end  
	,case when @StuffShow = 201 then 0
	    else R.ServerID end
		, R.YearID
    ,ReciptTypes.BuyEffect,ReciptTypes.SellEffect,ArzLookUps.Name,R.RialsEqual      , RT.ForoushType, RT.KeshvarCode, RT.Kotaj_No, 
     RT.Kotaj_Date , RT.LC_No,
      RT.LC_Date , 
      RT.GOmrok_Arzyabi,RT.GOmrok_khoruj,RT.AmountDeclaration,RT.AmountDeclarationArz
	  ,RT.RTCarton,RT.RTWeight,RT.ArzType

)
