CREATE  FUNCTION Fn_DarayiEjare ( 
  @CustIdFrom int
, @CustIdTo int
, @SeasonFrom int
, @SeasonTo int
, @DateFrom char(10)
, @DateTo char(10)
, @CustomerGrpIDFrom int
, @CustomerGrpIDTo int
, @YearIDFrom int
, @YearIDTo int
, @ContractsStatus varchar(200) ='0,1,2,3,4,5'
 )

RETURNS table  AS  
return (
SELECT    Cn.EmployerId ,Cn.WorkShopId ,   Cn.CaseNo, Cn.ContractRow AS Radif, Cn.TarafeGharardadType, '' AS TedadShoraka, Cn.ContractNo AS GharardadNumber, Cn.ContractDate AS GharardadDate, Cn.GharardadTypeCode, Cn.EjariType, Cn.Tozih, Cn.Vasile, Cn.KarbariType, 
                         Melk.StateCode AS Melk_StateCode, Melk.CityCode AS Melk_CityCode, Melk.Address AS Melk_Address, Melk.PostalCode AS Melk_PostCode, Melk.PerCityCode AS Melk_TellPishCode, Melk.Tel AS Melk_Tell, 
                         Melk.PelakSabtiAsli, Melk.PelakSabtiFari, Melk.ReagentName AS BakhshSabti, Melk.RegisterNumber AS ShenaseMelk, Cn.MozuType, Cn.ContractBasePrice AS NaKhales, Taraf.HCKharidarTypeCode AS T_TypeCode, 
                         Taraf.T_Tabeiat, Taraf.CustFirstName AS T_Name, Taraf.CustName AS T_LastNameSherkatName, Taraf.EconomicNumber AS T_EconomicNO, Taraf.NationalID AS T_NationalCode, Taraf.PerCityCode AS T_TellPishCode, 
                         Taraf.Tel AS T_Tell, Taraf.StateCode AS T_StateCode, Taraf.CityCode AS T_CityCode, Taraf.Address AS T_Address, Taraf.PostalCode AS T_PostCode
FROM            Cnt.Contracts AS Cn INNER JOIN
                         Customers AS Taraf ON Cn.EmployerId = Taraf.CustID INNER JOIN
                         Customers AS Melk ON Cn.WorkShopId = Melk.CustID
WHERE        (Cn.CaseNo <> 0) AND (Cn.FromType = 145)
     And   (Cn.EmployerId BETWEEN @CustIdFrom AND @CustIdTo) 
	 AND    ( CAST(SUBSTRING(Cn.ContractDate, 6, 2) AS int) BETWEEN @SeasonFrom AND @SeasonTo ) AND
    ( Cn.ContractDate BETWEEN @DateFrom AND @DateTo ) 
	AND ( CN.CustomerGrpID BETWEEN @CustomerGrpIDFrom AND @CustomerGrpIDTo)
	AND ((@ContractsStatus='-1') or Cn.ContractsStatus in (select part from SplitString(@ContractsStatus,',') ))
    AND (Cn.YearID BETWEEN @YearIDFrom AND @YearIDTo)


--ORDER BY Cn.CaseNo


)

