CREATE  FUNCTION [dbo].[Fn_HagholAmalKari] ( 
  @Tax Float
, @TaxTown Float
, @Town Float
, @TaxTown1 Float
, @CustIdFrom int
, @CustIdTo int
, @StuffGrpFrom int
, @StuffGrpTo int
, @SeasonFrom int
, @SeasonTo int
, @DateFrom char(10)
, @DateTo char(10)
, @CustomerGrpIDFrom int
, @CustomerGrpIDTo int
, @SellsEmporiumFrom int
, @SellsEmporiumTo int
, @NotSellsEmporium varchar(2000) =''
, @YearIDFrom int
, @YearIDTo int
, @StoreID varchar(2000) ='21,32,31,30,26,20,0'
, @EconomicNumberNationalID int
, @StuffShow int =0
, @chkPriceParvane bit =1
, @StuffKindActive varchar(200) ='0,1'
, @ReciptsSecondType varchar(2000) ='21,32,31,30,26,20,0'
, @INSellsEmporium varchar(2000) =''
, @SellsMethodFrom int
, @SellsMethodTo int
, @NotSellsMethod varchar(2000) =''
, @INSellsMethod varchar(2000) ='' 
 )

RETURNS table  AS  
return (
   SELECT R.PersonID1, Customers.CustName, Customers.Address,len(Customers.Address) as LenAddress,
    Customers.PostalCode, Customers.EconomicNumber
	, cast (1 as bigint ) as GroupID
	, 'نام کالا' as c_StuffName
	--,case when @StuffShow=0 then Ri.StuffCode else Cast( StuffGroups.GroupID AS BigInt) end AS GroupID
	--,case when @StuffShow=0 then StuffCoding.c_StuffName else StuffGroups.GroupName end AS c_StuffName
    , SUM ( case when ( ReciptTypes.CommissionActive = 2 and Ri.UnitCommission >0 ) then
    (Ri.InputEntity + Ri.OutputEntity ) * Ri.UnitCommission else
    CASE ReciptTypes.SellEffect WHEN 1 THEN 1 ELSE -1 END *(Ri.TotalOutputPrice + Ri.TotalInputPrice) end ) AS TotalOutputPrice
	,
    sum (CASE ReciptTypes.SellEffect WHEN 1 THEN
    - isnull(Ri.DeficitValue, 0)- Ri.DeficitValue2 - Ri.DeficitValue4 -  case when DiscountActive & 8 = 8 then 0 else  Ri.DeficitValue3 end
    ELSE + isnull(Ri.DeficitValue,0)+ Ri.DeficitValue2 + Ri.DeficitValue4 + Ri.DeficitValue4 + Ri.DeficitValue3 END) as DeficitValue

    , Customers.City, CASE Customers.NationalID WHEN '0' THEN '' ELSE Customers.NationalID END AS NationalID
    , Customers.Tel

    , CASE ReciptTypes.SellEffect WHEN 1 THEN 1 ELSE -1 END * SUM(Ri.TaxValue) AS TaxValue
    , ROUND((CASE ReciptTypes.SellEffect WHEN 1 THEN 1 ELSE -1 END * SUM(Ri.TaxValue) * CAST( @Tax AS
    Float) )/ CAST( @TaxTown AS Float) ,0) AS TaxValueOnTax
    , ROUND((CASE ReciptTypes.SellEffect WHEN 1 THEN 1 ELSE -1 END * SUM(Ri.TaxValue) * CAST( @Town AS
    Float))/ CAST( @TaxTown1 AS Float) ,0) AS TaxValueOnTown

    , CASE ReciptTypes.SellEffect WHEN 1 THEN 1 ELSE -1 END * SUM(Ri.TotallSellPrice)
    - SUM( case when ( ReciptTypes.CommissionActive =2 and Ri.UnitCommission >0 ) then
    Ri.TotalOutputPrice - Ri.TotalInputPrice else 0 end )
    - SUM(ISNULL(Ri.Portage, 0)) AS TotallSellPrice
    , Customers.RegisterNumber, Customers.HCTarafGaradadTypeCode, Customers.HCKharidarTypeCode, Customers.CustFirstName,
    Customers.PerCityCode,
    Customers.StateCode, Customers.CityCode, Zone.Shahr, Zone_StateCode.Ostan, Customers.Mobile,
    CASE WHEN Customers.CustName LIKE N'%'+ ISNULL(Customers.CustFirstName, '') +'%' THEN Customers.CustName
    ELSE Customers.CustName + ' ' + ISNULL(Customers.CustFirstName, '') END AS FullCustName
    ,ReciptTypes.SellEffect
      --,R.ReciptDate AS ReciptDate,R.Reciptnumber,
	  	--,case when @StuffShow = 201 then str(@YearIDFrom)+case when @SeasonFrom = 1 then '/03/31' when @SeasonFrom = 4 then '/06/31' when @SeasonFrom = 7 then '/09/30' else '/12/29' end	    else R.ReciptDate end AS ReciptDate
	  ,MAX(R.ReciptDate) AS ReciptDate
	,case when @StuffShow = 201 then 0
	    else R.Reciptnumber end AS Reciptnumber,
	  
	  SellsMethods.VajhTypes, 0 as SarFaslType
      ,0 as KalaType

      , RT.ForoushType, RT.KeshvarCode, RT.Kotaj_No, 
      RT.Kotaj_Date AS Kotaj_Date, RT.LC_No,
      RT.LC_Date AS LC_Date, 
      RT.GOmrok_Arzyabi,RT.GOmrok_khoruj,RT.AmountDeclaration,RT.AmountDeclarationArz
     ,RT.RTCarton,RT.RTWeight,RT.ArzType

            --, R.ReciptID, R.ServerID
	  ,case when @StuffShow = 201 then 0
	    else R.ReciptID end  AS ReciptID
	,case when @StuffShow = 201 then 0
	    else R.ServerID end ServerID
		, R.YearID

	  ,case when @chkPriceParvane=1 then 
             ROUND(SUM( (ISNULL(0,0)*(Ri.InputWeight + Ri.OutputWeight )/1000.0)
             *  ISNULL(Ri.StuffpublicPercentI,0)) * ISNULL(R.RialsEqual,0) ,0)
		else
            ROUND(SUM( (ISNULL(1,0)*(Ri.InputWeight + Ri.OutputWeight )/1000.0)
            *  ISNULL(Ri.StuffpublicPercentI,0)) * ISNULL(R.RialsEqual,0) ,0) end
	    AS PriceParvane
      --  AS PriceParvane // ISNULL(Ri.ArzRate,0) *
     ,ArzLookUps.Name AS ArzName,R.RialsEqual ,min( Ri.StuffpublicPercentI) AS StuffpublicPercentI
	 ,0  as SumTotalOutputPrice
	 ,
  ROUND(SUM( (InputEntity + OutputEntity) * UnitCommission +ROUND((InputWeight + OutputWeight) * Commission,0)+ TotalInputPrice + TotalOutputPrice) ,0) AS TotallCommissionTotalPrice
	 ,SUM(Ri.InputEntity+ri.OutputEntity) AS Entity,SUM(Ri.InputWeight+ri.OutputWeight) AS Weight , AVG(Ri.UnitSellPrice) AS UnitSellPrice
    FROM ReciptItems Ri INNER JOIN
    Recipts R ON R.ReciptID = Ri.ReciptID AND R.ServerID = Ri.ServerID AND
    R.YearID = Ri.YearID INNER JOIN
    Customers ON R.PersonID1 = Customers.CustID INNER JOIN
    --StuffCoding ON Ri.StuffCode = StuffCoding.c_StuffCode INNER JOIN
    ReciptTypes ON R.ReciptType = ReciptTypes.ReciptType
	 --INNER JOIN  StuffGroups ON StuffCoding.GroupID = StuffGroups.GroupID
    LEFT OUTER JOIN
    Zone ON Customers.CityCode = Zone.ShahrCode LEFT OUTER JOIN
    (SELECT DISTINCT OstanCode, Ostan
    FROM Zone) AS Zone_StateCode ON Customers.StateCode = Zone_StateCode.OstanCode

      INNER JOIN SellsMethods ON R.SellsMethod = SellsMethods.SellsMethod
      LEFT OUTER JOIN ReciptsTrades RT ON R.ReciptID = RT.ReciptID 
      AND R.ServerID = RT.ServerID AND R.YearID = RT.YearID

    LEFT OUTER JOIN  LookUps ArzLookUps ON R.ArzTypeID = ArzLookUps.LookUpID 

    WHERE (ReciptTypes.SellEffect <> 0) And
    (R.PersonID1 BETWEEN @CustIdFrom AND @CustIdTo) AND
    --(StuffGroups.GroupID BETWEEN @StuffGrpFrom AND @StuffGrpTo)AND
    ( CAST(SUBSTRING(R.ReciptDate, 6, 2) AS int) BETWEEN @SeasonFrom AND @SeasonTo ) AND
    ( R.ReciptDate BETWEEN @DateFrom AND @DateTo ) 
	AND ( Customers.CustomerGrpID BETWEEN @CustomerGrpIDFrom AND @CustomerGrpIDTo)
    AND ( R.ReciptState < 3)
	--AND ((@StuffKActive='-1') or StuffCoding.OwnerShipKind in (select part from SplitString(@StuffKindActive,',') ))
	AND ((@ReciptsSecondType='-1') or R.SecondType in (select part from SplitString(@ReciptsSecondType,',') ))

    AND (R.SellsEmporium BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)
    And ((@INSellsEmporium='-1') or exists( Select part From dbo.SplitString(@INSellsEmporium,',') where part = R.SellsEmporium)) 
    And ((@NotSellsEmporium='-1') or Not exists( Select part From dbo.SplitString(@NotSellsEmporium,',') where part = R.SellsEmporium)) 

    AND (R.SellsMethod BETWEEN @SellsMethodFrom AND @SellsMethodTo)
    And ((@INSellsMethod='-1') or exists( Select part From dbo.SplitString(@INSellsMethod,',') where part = R.SellsMethod)) 
    And ((@NotSellsMethod='-1') or Not exists( Select part From dbo.SplitString(@NotSellsMethod,',') where part = R.SellsMethod)) 


    AND (R.YearID BETWEEN @YearIDFrom AND @YearIDTo)
    AND ((@StoreID='-1') or R.StoreID in (select part from SplitString(@StoreID,',') ))
    AND ((ISNULL(LEN(Customers.EconomicNumber) + LEN(Customers.NationalID), 0) <> 0) OR 0 = @EconomicNumberNationalID )

    GROUP BY R.PersonID1, Customers.CustName, Customers.Address, Customers.PostalCode, Customers.EconomicNumber,
    --0 as GroupID,'' AS GroupName,
    ReciptTypes.SellEffect, Customers.City, Customers.NationalID, Customers.Tel
    , Customers.RegisterNumber, Customers.HCTarafGaradadTypeCode, Customers.HCKharidarTypeCode, Customers.CustFirstName,
    Customers.PerCityCode,
    Customers.StateCode, Customers.CityCode, Zone.Shahr, Zone_StateCode.Ostan, Customers.Mobile
      --,R.ReciptDate AS ReciptDate,R.Reciptnumber,
	  	--,case when @StuffShow = 201 then str(@YearIDFrom)+case when @SeasonFrom = 1 then '/03/31' when @SeasonFrom = 4 then '/06/31' when @SeasonFrom = 7 then '/09/30' else '/12/29' end	    else R.ReciptDate end
	,case when @StuffShow = 201 then 0
	    else R.Reciptnumber end ,
	  SellsMethods.VajhTypes--, StuffGroups.SarFaslType      ,StuffGroups.KalaType
      , RT.ForoushType, RT.KeshvarCode, RT.Kotaj_No, 
      RT.Kotaj_Date, RT.LC_No, RT.LC_Date, 
      RT.GOmrok_Arzyabi,RT.GOmrok_khoruj,RT.AmountDeclaration,RT.AmountDeclarationArz
     ,RT.RTCarton,RT.RTWeight,RT.ArzType
      --, R.ReciptID, R.ServerID
	  ,case when @StuffShow = 201 then 0
	    else R.ReciptID end  
	,case when @StuffShow = 201 then 0
	    else R.ServerID end 
		, R.YearID ,	  R.RialsEqual
	--,case when @StuffShow=0 then Ri.StuffCode else Cast( StuffGroups.GroupID AS BigInt) end 
	--,case when @StuffShow=0 then StuffCoding.c_StuffName else StuffGroups.GroupName end 
	 ,ArzLookUps.Name ,R.RialsEqual
    --ORDER BY ReciptTypes.SellEffect
	UNION ALL 

SELECT R.PersonID1, Customers.CustName, 
Customers.Address,len(Customers.Address) as LenAddress,
Customers.PostalCode, Customers.EconomicNumber
, 0 AS GroupID,min(Deficits.DeficitName)+'...'+max(Deficits.DeficitName)  AS c_StuffName
, SUM ( (ReciptsDeficits.DeficitAdd -ReciptsDeficits.DeficitDec) ) AS TotalOutputPrice
,0 as DeficitValue
, Customers.City, CASE Customers.NationalID WHEN '0' THEN '' ELSE Customers.NationalID END AS NationalID
, Customers.Tel
, CASE ReciptTypes.SellEffect WHEN 1 THEN 1 ELSE -1 END * SUM(0) AS TaxValue
, ROUND((CASE ReciptTypes.SellEffect WHEN 1 THEN 1 ELSE -1 END * SUM(0) * CAST( @Tax AS
Float) )/ CAST( @TaxTown AS Float) ,0) AS TaxValueOnTax
, ROUND((CASE ReciptTypes.SellEffect WHEN 1 THEN 1 ELSE -1 END * SUM(0) * CAST( @Town AS
Float))/ CAST( @TaxTown1 AS Float) ,0) AS TaxValueOnTown
, CASE ReciptTypes.SellEffect WHEN 1 THEN 1 ELSE -1 END * SUM(0) AS TotallSellPrice
, Customers.RegisterNumber, Customers.HCTarafGaradadTypeCode, Customers.HCKharidarTypeCode, Customers.CustFirstName,
Customers.PerCityCode,
Customers.StateCode, Customers.CityCode, Zone.Shahr, Zone_StateCode.Ostan, Customers.Mobile,
CASE WHEN Customers.CustName LIKE N'%'+ ISNULL(Customers.CustFirstName, '') +'%' THEN Customers.CustName
ELSE Customers.CustName + ' ' + ISNULL(Customers.CustFirstName, '') END AS FullCustName
,ReciptTypes.SellEffect
      --,R.ReciptDate AS ReciptDate,R.Reciptnumber,
	  	--,case when @StuffShow = 201 then str(@YearIDFrom)+case when @SeasonFrom = 1 then '/03/31' when @SeasonFrom = 4 then '/06/31' when @SeasonFrom = 7 then '/09/30' else '/12/29' end	    else R.ReciptDate end AS ReciptDate
	  ,MAX(R.ReciptDate) AS ReciptDate
	,case when @StuffShow = 201 then 0
	    else R.Reciptnumber end AS Reciptnumber,

SellsMethods.VajhTypes, 0 as SarFaslType
, 0 as  KalaType
, RT.ForoushType, RT.KeshvarCode, RT.Kotaj_No, 
RT.Kotaj_Date AS Kotaj_Date, RT.LC_No,
RT.LC_Date AS LC_Date, 
RT.GOmrok_Arzyabi,RT.GOmrok_khoruj,RT.AmountDeclaration,RT.AmountDeclarationArz
     ,RT.RTCarton,RT.RTWeight,RT.ArzType
      --, R.ReciptID, R.ServerID
	  ,case when @StuffShow = 201 then 0
	    else R.ReciptID end  AS ReciptID
	,case when @StuffShow = 201 then 0
	    else R.ServerID end ServerID
		, R.YearID
		,0 * ISNULL(R.RialsEqual,0) AS PriceParvane     ,ArzLookUps.Name AS ArzName,R.RialsEqual,0.0 as StuffpublicPercentI
 ,0.0  as SumTotalOutputPrice, 0 AS TotallCommissionTotalPrice
 ,0.0 AS Entity,0.0 AS Weight , 0 AS UnitSellPrice
FROM            Recipts R  INNER JOIN
                         Customers ON R.PersonID1 = Customers.CustID  INNER JOIN
                         ReciptTypes ON R.ReciptType = ReciptTypes.ReciptType  LEFT OUTER JOIN
                         Zone ON Customers.CityCode = Zone.ShahrCode LEFT OUTER JOIN
                             (SELECT DISTINCT OstanCode, Ostan
                                FROM            Zone AS Zone_1) AS Zone_StateCode ON Customers.StateCode = Zone_StateCode.OstanCode INNER JOIN
                         SellsMethods ON R.SellsMethod = SellsMethods.SellsMethod INNER JOIN
                         ReciptsDeficits ON R.ReciptID = ReciptsDeficits.ReciptID AND R.ServerID = ReciptsDeficits.ServerID AND R.YearID = ReciptsDeficits.YearID LEFT OUTER JOIN
                         ReciptsTrades RT ON R.ReciptID = RT.ReciptID AND R.ServerID = RT.ServerID AND R.YearID = RT.YearID
    LEFT OUTER JOIN  LookUps ArzLookUps ON R.ArzTypeID = ArzLookUps.LookUpID  JOIN
	Deficits ON Deficits.DeficitID = ReciptsDeficits.DeficitID
    WHERE (ReciptTypes.SellEffect <> 0)  AND (Deficits.TTMSActive = 1)
	And (R.PersonID1 BETWEEN @CustIdFrom AND @CustIdTo) 
	--AND (StuffGroups.GroupID BETWEEN @StuffGrpFrom AND @StuffGrpTo)
	AND (CAST(SUBSTRING(R.ReciptDate, 6, 2) AS int) BETWEEN @SeasonFrom AND @SeasonTo ) 
	AND (R.ReciptDate BETWEEN @DateFrom AND @DateTo ) 
	AND (Customers.CustomerGrpID BETWEEN @CustomerGrpIDFrom AND @CustomerGrpIDTo)
    AND (R.ReciptState < 3)
	--AND ((@StuffKActive='-1') or StuffCoding.OwnerShipKind in (select part from SplitString(@StuffKindActive,',') ))
    AND ((@ReciptsSecondType='-1') or R.SecondType in (select part from SplitString(@ReciptsSecondType,',') ))

    AND (R.SellsEmporium BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)
    And ((@INSellsEmporium='-1') or exists( Select part From dbo.SplitString(@INSellsEmporium,',') where part = R.SellsEmporium)) 
    And ((@NotSellsEmporium='-1') or Not exists( Select part From dbo.SplitString(@NotSellsEmporium,',') where part = R.SellsEmporium)) 

    AND (R.SellsMethod BETWEEN @SellsMethodFrom AND @SellsMethodTo)
    And ((@INSellsMethod='-1') or exists( Select part From dbo.SplitString(@INSellsMethod,',') where part = R.SellsMethod)) 
    And ((@NotSellsMethod='-1') or Not exists( Select part From dbo.SplitString(@NotSellsMethod,',') where part = R.SellsMethod)) 


    AND (R.YearID BETWEEN @YearIDFrom AND @YearIDTo)
    AND ((@StoreID='-1') or R.StoreID in (select part from SplitString(@StoreID,',') ))
    AND ((ISNULL(LEN(Customers.EconomicNumber) + LEN(Customers.NationalID), 0) <> 0) OR 0 = @EconomicNumberNationalID )


GROUP BY R.PersonID1, Customers.CustName, Customers.Address, Customers.PostalCode, Customers.EconomicNumber,

ReciptTypes.SellEffect, Customers.City, Customers.NationalID, Customers.Tel
, Customers.RegisterNumber, Customers.HCTarafGaradadTypeCode, Customers.HCKharidarTypeCode, Customers.CustFirstName,
Customers.PerCityCode,
Customers.StateCode, Customers.CityCode, Zone.Shahr, Zone_StateCode.Ostan, Customers.Mobile
      --,R.ReciptDate AS ReciptDate,R.Reciptnumber,
	  	--,case when @StuffShow = 201 then str(@YearIDFrom)+case when @SeasonFrom = 1 then '/03/31' when @SeasonFrom = 4 then '/06/31' when @SeasonFrom = 7 then '/09/30' else '/12/29' end	    else R.ReciptDate end 
	,case when @StuffShow = 201 then 0
	    else R.Reciptnumber end ,
SellsMethods.VajhTypes
, RT.ForoushType, RT.KeshvarCode, RT.Kotaj_No, 
RT.Kotaj_Date, RT.LC_No, RT.LC_Date, 
RT.GOmrok_Arzyabi,RT.GOmrok_khoruj,RT.AmountDeclaration,RT.AmountDeclarationArz
     ,RT.RTCarton,RT.RTWeight,RT.ArzType
      --, R.ReciptID, R.ServerID
	  ,case when @StuffShow = 201 then 0
	    else R.ReciptID end  
	,case when @StuffShow = 201 then 0
	    else R.ServerID end 
		, R.YearID,R.RialsEqual
,ArzLookUps.Name
)

