CREATE FUNCTION Fn_CheckCalc (@YearID int =1397 ,@ServerID int=0,@ReciptID int=1)
    RETURNS @retFindReports TABLE 
  (
	FormCaption varchar(150)  COLLATE DATABASE_DEFAULT ,
	ReciptNumber int ,
	ReciptDate char(10),
	DefaultDate char(10),
	YearID int ,
	ServerID int ,
	ReciptID int ,
	FormID int ,
	Amount money 
  )
  AS 
BEGIN  
INSERT INTO @retFindReports


SELECT        'مبلغ فاکتور' AS Caption,R.ReciptNumber, ReciptDate,DefaultDate, T.YearID, T.ServerID, 0 AS FormID, T.ReciptID, SUM(T.TotallSellPrice) AS TotallSellPrice
FROM            ReciptItems AS T INNER JOIN
                         Recipts R ON T.ReciptID = R.ReciptID AND T.ServerID = R.ServerID AND T.YearID = R.YearID
WHERE        (T.YearID = @YearID) AND (T.ServerID = T.ServerID) AND (T.ReciptID = @ReciptID)
GROUP BY R.ReciptDate,R.ReciptNumber,T.ReciptID, T.ServerID, T.YearID,DefaultDate
union all 
SELECT     'مبلغ نقدی' AS Caption ,FormNumber ,FormDate ,DefaultDate , YearID, ServerID, FormID,    ReciptID, -Amount
FROM            Forms
WHERE        (ReciptID = @ReciptID ) AND (YearID = @YearID) AND (ServerID = ServerID)

INSERT INTO @retFindReports
  select   'باقی مانده' AS Caption ,0 as ReciptNumber,dbo.MiladiToShamsi(getdate()),max(DefaultDate), @YearID  as   YearID,@ServerID as ServerID,0 as  FormID, @ReciptID as   ReciptID,sum(Amount) as Amount
  from @retFindReports
     RETURN
END
