GO 
SET ANSI_NULLS OFF 
GO 
CREATE FUNCTION CashAccount (@TypeDoc1 int =1 ,@TypeDoc2 int =-1,
						@TypeDoc3 int =-1 ,@TypeDoc4 int =1 ,
						@CustIDFrom  int = 0 , @CustIDTo int = 999999999 ,
						@DateFrom  Char(10) ='0001/01/01' , @DateTo Char(10) = '9999/99/99' ,
						@YearIDFrom  int = 0 , @YearIDTo int = 9999 ,
				@SellsMethodFrom  int = 0 , @SellsMethodTo int = 999999999 ,
				@SellsEmporiumFrom  int = 0 , @SellsEmporiumTo int = 999999999 ,@DefaultDateActive Tinyint=0)

RETURNS table  AS  
return (
SELECT	Forms.ServerID, Forms.YearID, Forms.FormID, Forms.FormNumber, Forms.FormDate,
		case WHEN ( Forms.DefaultDate <'0001/01/01' or Forms.DefaultDate  is null ) THEN Forms.FormDate else Forms.DefaultDate end AS DefaultDate
		 ,Forms.DefaultDuration,
		'0' AS checkNumber , '0' AS checkDate , '' AS BankName , '' AS AccountNumber , 
		Forms.FormType, FormTypes.FormCaption, FormTypes.FormCaption_L2,  '' c_StuffName_L2,  '' UnitName_l2, 
		Forms.CustomerID1, Forms.CustomerID2, Forms.FomNote,Forms.AidInfoNo, 
		Forms.AidInfoDate,
		case FormTypes.bedbes WHEN 1 THEN ISNULL(Forms.ArzAmount,0) else 0 end AS Arzbed ,----------------------11111111111111
		case FormTypes.bedbes WHEN 0 THEN ISNULL(Forms.ArzAmount,0) else 0 end AS Arzbes 
		,ISNULL(Forms.ArzTypeID,0) AS ArzTypeID,Currencies.CurrenciesName,Currencies.CurrencySymbol,ISNULL(Forms.ArzRate,0) AS ArzRate,
		case FormTypes.bedbes WHEN 1 THEN Forms.Amount else 0 end AS bed ,
		case FormTypes.bedbes WHEN 0 THEN Forms.Amount else 0 end AS bes ,
		Forms.BudgetCode, Forms.ProjectID, Forms.CustomerName2 , 
		Forms.CustomerID2 AS DetailCustID , Forms.CustomerID1 AS CustIDForShow, 1 AS kind , 
		LookUps.Code, LookUps.Name , Forms.SellsMethod, SellsMethods.SellsMethodName,
		Forms.SellsEmporium ,SE.SellsEmporiumName, Forms.TruckNumber ,
		Forms.RelatedID , 1 AS RelatedKind , FormTypes.Customer1DocType AS DocType, 
		Forms.CustomerID3 ,0 AS CashWage ,0 AS FormItemID, Forms.DocNo, Forms.DocDate,Forms.FormState,0 PersonID1D,Forms.FormDate AS FormDateNoCheck,'' AS FormDateCheck
FROM	Forms  INNER JOIN
        SellsMethods ON Forms.SellsMethod = SellsMethods.SellsMethod INNER JOIN
		FormTypes ON Forms.FormType = FormTypes.FormType LEFT OUTER JOIN
		LookUps ON Forms.PayTypes = LookUps.LookUpID
		LEFT OUTER JOIN Currencies ON ISNULL(Forms.ArzTypeID,0) = Currencies.CurrenciesID 	INNER JOIN
        SellsEmporiums SE ON Forms.SellsEmporium = SE.SellsEmporium 

WHERE	(FormTypes.DisplayFormType in(0,7)) AND 
		(FormTypes.Customer1DocType in (@TypeDoc1 ,@TypeDoc2,@TypeDoc3,@TypeDoc4))And 
		(Forms.CustomerID1 between @CustIDFrom and @CustIDTo ) AND 
		(CASE WHEN @DefaultDateActive = 0 THEN Forms.FormDate ELSE Forms.DefaultDate END between @DateFrom and @DateTo ) AND
		
		(Forms.YearID between @YearIDFrom AND @YearIDTo )AND 
		(FormState<10)  AND 
		(Forms.SellsMethod  BETWEEN @SellsMethodFrom AND @SellsMethodTo) AND 
		(Forms.SellsEmporium  BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)
		
--------------------------------
union all
-----------------------------------  برای تاثیر فرمهای وجه نقد در گزارشات عملکرد مشتریان طراحی شده است مربوط به مشتری 2 میباشد
SELECT	Forms.ServerID, Forms.YearID,Forms.FormID, Forms.FormNumber, Forms.FormDate,
		case WHEN ( Forms.DefaultDate <'0001/01/01' or Forms.DefaultDate  is null ) THEN Forms.FormDate else Forms.DefaultDate end AS DefaultDate
		,Forms.DefaultDuration ,
		'0' AS checkNumber , '0' AS checkDate , '' AS BankName , '' AS AccountNumber , 
		Forms.FormType, FormTypes.FormCaption, FormTypes.FormCaption_L2, '' c_StuffName_L2,  '' UnitName_l2, 
		Forms.CustomerID2, Forms.CustomerID1, Forms.FomNote,Forms.AidInfoNo, 
		Forms.AidInfoDate,
		case FormTypes.bedbes WHEN 0 THEN ISNULL(Forms.ArzAmount,0) else 0 end AS Arzbed ,
		case FormTypes.bedbes WHEN 1 THEN ISNULL(Forms.ArzAmount,0) else 0 end AS Arzbes 
		,ISNULL(Forms.ArzTypeID,0) AS ArzTypeID,Currencies.CurrenciesName,Currencies.CurrencySymbol,ISNULL(Forms.ArzRate,0) AS ArzRate ,
		case FormTypes.bedbes WHEN 0 THEN Forms.Amount else 0 end AS bed ,
		case FormTypes.bedbes WHEN 1 THEN Forms.Amount else 0 end AS bes ,
		Forms.BudgetCode, Forms.ProjectID, Forms.CustomerName2 , 
		Forms.CustomerID2 AS DetailCustID , Forms.CustomerID1 AS CustIDForShow , 1 AS kind, 
		LookUps.Code, LookUps.Name , Forms.SellsMethod, SellsMethods.SellsMethodName, 
		Forms.SellsEmporium ,SE.SellsEmporiumName , Forms.TruckNumber ,
		Forms.RelatedID , 1 AS RelatedKind , FormTypes.Customer2DocType AS DocType, 
		Forms.CustomerID3 ,0 AS CashWage ,0 AS FormItemID, Forms.DocNo, Forms.DocDate,Forms.FormState,0 PersonID1D,Forms.FormDate AS FormDateNoCheck,'' AS FormDateCheck
FROM	Forms  INNER JOIN
        SellsMethods ON Forms.SellsMethod = SellsMethods.SellsMethod INNER JOIN
		FormTypes ON Forms.FormType = FormTypes.FormType LEFT OUTER JOIN
		LookUps ON Forms.PayTypes = LookUps.LookUpID
		LEFT OUTER JOIN Currencies ON ISNULL(Forms.ArzTypeID,0) = Currencies.CurrenciesID 	INNER JOIN
        SellsEmporiums SE ON Forms.SellsEmporium = SE.SellsEmporium 	

WHERE (FormTypes.DisplayFormType in(0,7)) AND 
		(FormTypes.Customer2DocType in (@TypeDoc1 ,@TypeDoc2,@TypeDoc3,@TypeDoc4)) And 
		(Forms.CustomerID2 between @CustIDFrom and @CustIDTo ) AND 
		(CASE WHEN @DefaultDateActive = 0 THEN Forms.FormDate ELSE Forms.DefaultDate END between @DateFrom and @DateTo ) AND
		( Forms.YearID between @YearIDFrom AND @YearIDTo )AND 
		(FormState<10) AND 
		(Forms.SellsMethod  BETWEEN @SellsMethodFrom AND @SellsMethodTo) AND 
		(Forms.SellsEmporium  BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)
----------------------------
UNION ALL
-----------------------------------  برای تاثیر فرمهای چک و تنخواه  در گزارشات عملکرد مشتریان طراحی شده است مربوط به مشتری 1 میباشد
SELECT	Forms.ServerID, Forms.YearID,Forms.FormID, Forms.FormNumber, Forms.FormDate,
		case WHEN ( Forms.DefaultDate <'0001/01/01' or Forms.DefaultDate  is null ) THEN RIGHT( FormItems.CheckDate,10) else Forms.DefaultDate end AS DefaultDate
		,Forms.DefaultDuration ,
		FormItems.CheckNumber, RIGHT( FormItems.CheckDate,10), FormItems.BankName , FormItems.AccountNumber , Forms.FormType, 
		FormTypes.FormCaption, FormTypes.FormCaption_L2,   '' c_StuffName_L2,  '' UnitName_l2, 
		case WHEN  FormTypes.Customer1DocType in ( 3,4,11) and @TypeDoc2 >0 
			THEN FormItems.CustomerID2
			else Forms.CustomerID1 end  AS CustomerID1 , 
		case WHEN (FormTypes.CustomerDetailsDocType<>0 ) 
			THEN FormItems.CustomerID2
			else Forms.CustomerID2 end AS CustomerID2 , 
		ISNULL(Forms.FomNote, '')+' '+ISNULL(FormItems.ItemNote, '') AS FomNote, Forms.AidInfoNo, Forms.AidInfoDate,
		case FormTypes.bedbes WHEN 1 THEN ISNULL(FormItems.ArzAmount,0)  else 0 end AS Arzbed ,
		case FormTypes.bedbes WHEN 0 THEN ISNULL(FormItems.ArzAmount,0)  else 0 end AS Arzbes 
		,ISNULL(Forms.ArzTypeID,0) AS ArzTypeID,Currencies.CurrenciesName,Currencies.CurrencySymbol,ISNULL(Forms.ArzRate,0) AS ArzRate ,

	    case 	 WHEN FormTypes.bedbes=1 and formtypes.DisplayFormType <> 3  THEN FormItems.ItemAmount - isnull(CashWage,0) 
		     WHEN FormTypes.bedbes=1 and formtypes.DisplayFormType = 3  THEN FormItems.ItemAmount else 0 end AS bed ,
		case 	 WHEN FormTypes.bedbes=0 and formtypes.DisplayFormType <> 3  THEN FormItems.ItemAmount - isnull(CashWage,0) 
		     WHEN FormTypes.bedbes=0 and formtypes.DisplayFormType = 3  THEN FormItems.ItemAmount else 0 end AS bes ,
		case FormTypes.BudgetCodePosition
			WHEN 0 THEN 0
			WHEN 1 THEN FormItems.BudgetCode
			WHEN 2 THEN FormItems.BudgetCode
			WHEN 3 THEN Forms.BudgetCode
			else 0 
		end AS BudgetCode ,
		case FormTypes.BudgetCodePosition
			WHEN 0 THEN 0
			WHEN 1 THEN FormItems.ProjectID
			WHEN 2 THEN FormItems.ProjectID
			WHEN 3 THEN Forms.ProjectID
			else 0 
		end AS ProjectID ,
		case FormTypes.Customer2ActiveOnDetail
			WHEN 0 THEN Forms.CustomerName2
			WHEN 1 THEN null
			WHEN 2 THEN null
			WHEN 3 THEN Forms.CustomerName2
			else str(Forms.CustomerID2) 
		end AS CustomerName2 , 
		FormItems.CustomerID2  AS DetailCustID ,Forms.CustomerID1 AS CustIDForShow ,  2 AS kind , 
		LookUps.Code, LookUps.Name , Forms.SellsMethod, SellsMethods.SellsMethodName, 
		Forms.SellsEmporium ,SE.SellsEmporiumName,Forms.TruckNumber ,FormItems.RelatedID , 2 AS RelatedKind , 

		case FormTypes.Customer1DocType 
			WHEN 13 THEN 
				case FormItems.CheckType  WHEN 0 THEN 6 else 2 end 
			WHEN 14 THEN 
				case FormItems.CheckType  WHEN 1 THEN -5 else 2 end 
			WHEN 15 THEN 
				case FormItems.CheckType  WHEN 0 THEN 6 else -5 end 
			else FormTypes.Customer1DocType  
		end  AS DocType, 

		Forms.CustomerID3 ,FormItems.CashWage , FormItemID, Forms.DocNo, Forms.DocDate,Forms.FormState,FormItems.CustomerID2 PersonID1D,'' AS FormDateNoCheck,Forms.FormDate AS FormDateCheck
FROM	Forms  INNER JOIN
        SellsMethods ON Forms.SellsMethod = SellsMethods.SellsMethod INNER JOIN
		FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
		FormItems ON Forms.FormID = FormItems.FormID and Forms.ServerID = FormItems.ServerID and Forms.YearID = FormItems.YearID  LEFT OUTER JOIN
		LookUps ON Forms.PayTypes = LookUps.LookUpID
       left outer join (select preFormItemID ,PerServerID,forms.YearID
							from forms inner join FormItems on forms.FormID=FormItems.FormID 
																and forms.YearID=FormItems.YearID
																and forms.ServerID=FormItems.ServerID
							where FormType=51
		 ) s on s.preFormItemID=FormItems.FormItemID and s.PerServerID=FormItems.ServerID and s.YearID=FormItems.YearID
		LEFT OUTER JOIN Currencies ON ISNULL(Forms.ArzTypeID,0) = Currencies.CurrenciesID 		INNER JOIN
        SellsEmporiums SE ON Forms.SellsEmporium = SE.SellsEmporium 
WHERE (		
		case FormTypes.Customer1DocType 
				WHEN 13 THEN 
					case FormItems.CheckType  WHEN 0 THEN 6 else 2 end 
				WHEN 14 THEN 
					case FormItems.CheckType  WHEN 1 THEN -5 else 2 end 
				WHEN 15 THEN 
					case FormItems.CheckType  WHEN 0 THEN 6 else -5 end 
				else FormTypes.Customer1DocType  
			end  in (@TypeDoc1 ,@TypeDoc2,@TypeDoc3,@TypeDoc4)
		) AND
		(forms.FormType <> case  WHEN s.preFormItemID=FormItems.FormItemID THEN  50 else 0 end 	)
		and 
		( 
			case WHEN  FormTypes.Customer1DocType in ( 3,4,11) and @TypeDoc2 >0 
				THEN FormItems.CustomerID2
				else Forms.CustomerID1 
			end between @CustIDFrom and @CustIDTo 
		) AND 
		(CASE WHEN @DefaultDateActive = 0 THEN Forms.FormDate ELSE Forms.DefaultDate END between @DateFrom and @DateTo ) AND
		(Forms.YearID between @YearIDFrom AND @YearIDTo )AND 
		(FormState<10 ) AND 
		(Forms.SellsMethod  BETWEEN @SellsMethodFrom AND @SellsMethodTo) AND 
		(Forms.SellsEmporium  BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)
----------------------------------------
union all
-----------------------------------  برای تاثیر فرمهای چک و تنخواه  در گزارشات عملکرد مشتریان طراحی شده است مربوط به مشتری 2 میباشد
SELECT	Forms.ServerID, Forms.YearID,Forms.FormID, Forms.FormNumber, Forms.FormDate,
		case WHEN ( Forms.DefaultDate <'0001/01/01' or Forms.DefaultDate  is null ) THEN RIGHT( FormItems.CheckDate,10) else Forms.DefaultDate end AS DefaultDate
		,Forms.DefaultDuration ,
		FormItems.CheckNumber, RIGHT( FormItems.CheckDate,10) , 
		FormItems.BankName , FormItems.AccountNumber ,Forms.FormType, 
		FormTypes.FormCaption, FormTypes.FormCaption_L2,   '' c_StuffName_L2,  '' UnitName_l2, 
		case WHEN  FormTypes.Customer2DocType in ( 3,4,11) and @TypeDoc2 >0 
			THEN FormItems.CustomerID2
			else Forms.CustomerID2 
		end  AS CustomerID2 , 
		Forms.CustomerID1, 	ISNULL(Forms.FomNote, '')+' '+ISNULL(FormItems.ItemNote, '') AS FomNote, 
		Forms.AidInfoNo, Forms.AidInfoDate,
		case FormTypes.bedbes WHEN 0 THEN ISNULL(FormItems.ArzAmount,0)  else 0 end AS Arzbed ,
		case FormTypes.bedbes WHEN 1 THEN ISNULL(FormItems.ArzAmount,0)  else 0 end AS Arzbes ,
		ISNULL(Forms.ArzTypeID,0) AS ArzTypeID,Currencies.CurrenciesName,Currencies.CurrencySymbol,ISNULL(Forms.ArzRate,0) AS ArzRate ,
case WHEN FormTypes.bedbes=0 and formtypes.DisplayFormType <> 3  THEN FormItems.ItemAmount - isnull(CashWage,0) 
		     WHEN FormTypes.bedbes=0 and formtypes.DisplayFormType = 3  THEN FormItems.ItemAmount 
		 
		else 0 end AS bed ,
		case WHEN FormTypes.bedbes= 1   and formtypes.DisplayFormType <> 3   THEN FormItems.ItemAmount - isnull(CashWage,0) 
		     WHEN FormTypes.bedbes=1 and formtypes.DisplayFormType = 3  THEN FormItems.ItemAmount 
		
		else 0 end AS bes ,
		case FormTypes.BudgetCodePosition
			WHEN 0 THEN 0
			WHEN 1 THEN FormItems.BudgetCode
			WHEN 2 THEN FormItems.BudgetCode
			WHEN 3 THEN Forms.BudgetCode
			else 0 
		end AS BudgetCode ,
		case FormTypes.BudgetCodePosition
			WHEN 0 THEN 0
			WHEN 1 THEN FormItems.ProjectID
			WHEN 2 THEN FormItems.ProjectID
			WHEN 3 THEN Forms.ProjectID
			else 0 
		end AS ProjectID ,
		case FormTypes.Customer2ActiveOnDetail
			WHEN 0 THEN Forms.CustomerName2
			WHEN 1 THEN null
			WHEN 2 THEN null
			WHEN 3 THEN Forms.CustomerName2
			else null 
		end AS CustomerName2 ,  
		case WHEN FormTypes.CustomerDetailsDocType=0 
			THEN Forms.CustomerID2
			else FormItems.CustomerID2 
		end   AS DetailCustID ,
		Forms.CustomerID1 AS CustIDForShow , 2 AS kind ,  LookUps.Code, LookUps.Name , Forms.SellsMethod, 
		SellsMethods.SellsMethodName, Forms.SellsEmporium ,SE.SellsEmporiumName,Forms.TruckNumber ,	FormItems.RelatedID , 2 AS RelatedKind , 
		case FormTypes.Customer2DocType 
			WHEN 13 THEN 
				case FormItems.CheckType  WHEN 0 THEN 6 else 2 end 
			WHEN 14 THEN 
				case FormItems.CheckType  WHEN 1 THEN -5 else 2 end 
			WHEN 15 THEN 
				case FormItems.CheckType  WHEN 0 THEN 6 else -5 end 
			else FormTypes.Customer2DocType  
			end AS DocType 	, Forms.CustomerID3 ,FormItems.CashWage , FormItemID, Forms.DocNo, Forms.DocDate,Forms.FormState,FormItems.CustomerID2 PersonID1D,'' AS FormDateNoCheck,Forms.FormDate AS FormDateCheck
FROM	Forms  INNER JOIN
        SellsMethods ON Forms.SellsMethod = SellsMethods.SellsMethod INNER JOIN
		FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
		FormItems ON Forms.FormID = FormItems.FormID and Forms.ServerID = FormItems.ServerID and Forms.YearID = FormItems.YearID  LEFT OUTER JOIN
		LookUps ON Forms.PayTypes = LookUps.LookUpID
		LEFT OUTER JOIN Currencies ON ISNULL(Forms.ArzTypeID,0) = Currencies.CurrenciesID 	INNER JOIN
        SellsEmporiums SE ON Forms.SellsEmporium = SE.SellsEmporium 	
WHERE	(
			case FormTypes.Customer2DocType 
				WHEN 13 THEN 
					case FormItems.CheckType  WHEN 0 THEN 6 else 2 end 
				WHEN 14 THEN 
					case FormItems.CheckType  WHEN 1 THEN -5 else 2 end 
				WHEN 15 THEN 
					case FormItems.CheckType  WHEN 0 THEN 6 else -5 end 
				else FormTypes.Customer2DocType  
			end  in (@TypeDoc1 ,@TypeDoc2,@TypeDoc3,@TypeDoc4)
		)  AND 
		( 
			case WHEN  FormTypes.Customer2DocType in ( 3,4,11) and @TypeDoc2 >0 
				THEN FormItems.CustomerID2
				else Forms.CustomerID2 
			end  between @CustIDFrom and @CustIDTo 
		) AND 
		(CASE WHEN @DefaultDateActive = 0 THEN Forms.FormDate ELSE Forms.DefaultDate END between @DateFrom and @DateTo )AND
		( Forms.YearID between @YearIDFrom AND @YearIDTo )AND 
		(FormState<10) AND 
		(Forms.SellsMethod  BETWEEN @SellsMethodFrom AND @SellsMethodTo) AND 
		(Forms.SellsEmporium  BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)

----------------- برای زمانیکه از مشتری دیتیل استفاده میشود ----------
UNION ALL 
------------------
SELECT	Forms.ServerID, Forms.YearID,Forms.FormID, Forms.FormNumber, Forms.FormDate,
		case WHEN ( Forms.DefaultDate <'0001/01/01' or Forms.DefaultDate  is null ) 
			THEN RIGHT( FormItems.CheckDate,10)
			else Forms.DefaultDate 
		end AS DefaultDate,Forms.DefaultDuration ,
		FormItems.CheckNumber, RIGHT( FormItems.CheckDate,10), FormItems.BankName , FormItems.AccountNumber ,
		Forms.FormType, FormTypes.FormCaption, FormTypes.FormCaption_L2,   '' c_StuffName_L2,  '' UnitName_l2, 
		case WHEN Severable.CustID >0 THEN Severable.CustID else FormItems.CustomerID2 end AS CustomerID2 , 
		Forms.CustomerID1 ,ISNULL(Forms.FomNote, '')+' '+ISNULL(FormItems.ItemNote, '') AS FomNote, 
		Forms.AidInfoNo, Forms.AidInfoDate,
		case FormTypes.BedBesDetails 
			WHEN 1 THEN 
				case WHEN Severable.ArzAmount>0 THEN ISNULL(Severable.ArzAmount,0) else  ISNULL(FormItems.ArzAmount,0)  end 
			else 0 
		end AS Arzbed ,
		case FormTypes.BedBesDetails 
			WHEN 2 THEN 
				case WHEN Severable.ArzAmount>0 THEN ISNULL(Severable.ArzAmount,0) else  ISNULL(FormItems.ArzAmount,0)  end  
			else 0 
		end AS Arzbes ,ISNULL(Forms.ArzTypeID,0) AS ArzTypeID,Currencies.CurrenciesName,Currencies.CurrencySymbol,ISNULL(Forms.ArzRate,0) AS ArzRate ,
		case FormTypes.BedBesDetails 
			WHEN 1 THEN  
				case WHEN ( Severable.Amount + Severable.DeficitAmount) > 0 THEN (Severable.Amount + Severable.DeficitAmount)  
					else    FormItems.ItemAmount - isnull(CashWage,0)   
				end  
			else 0 
		end  AS bed ,
		case FormTypes.BedBesDetails 
			WHEN 2 THEN  
				case WHEN(Severable.Amount + Severable.DeficitAmount)>0 THEN (Severable.Amount + Severable.DeficitAmount)  
					else   FormItems.ItemAmount - isnull(CashWage,0)    
				end  
			else 0 
		end  AS bes ,

		case FormTypes.BudgetCodePosition
			WHEN 0 THEN 0
			WHEN 1 THEN FormItems.BudgetCode
			WHEN 2 THEN FormItems.BudgetCode
			WHEN 3 THEN Forms.BudgetCode
			else 0 
		end AS BudgetCode ,
		case FormTypes.BudgetCodePosition
			WHEN 0 THEN 0
			WHEN 1 THEN FormItems.ProjectID
			WHEN 2 THEN FormItems.ProjectID
			WHEN 3 THEN Forms.ProjectID
			else 0 
		end AS ProjectID ,
		case FormTypes.Customer2ActiveOnDetail
			WHEN 0 THEN Forms.CustomerName2
			WHEN 1 THEN null
			WHEN 2 THEN null
			WHEN 3 THEN Forms.CustomerName2
			else str(Forms.CustomerID2) 
		end AS CustomerName2 ,
		case WHEN FormTypes.CustomerDetailsDocType=0 THEN Forms.CustomerID2 
			else 
				case WHEN Severable.CustID >0 THEN Severable.CustID else FormItems.CustomerID2 end  
		end  AS DetailCustID ,
		Forms.CustomerID1 AS CustIDForShow , 2 AS kind , LookUps.Code, LookUps.Name, Forms.SellsMethod, 
		SellsMethods.SellsMethodName, Forms.SellsEmporium,SE.SellsEmporiumName ,Forms.TruckNumber ,FormItems.RelatedID , 2 AS RelatedKind ,
		case FormTypes.CustomerDetailsDocType 
			WHEN 13 THEN 
				case FormItems.CheckType  WHEN 0 THEN 6 else 2 end 
			WHEN 14 THEN 
				case FormItems.CheckType  WHEN 1 THEN -5 else 2 end 
			WHEN 15 THEN 
				case FormItems.CheckType  WHEN 0 THEN 6 else -5 end 
			else FormTypes.CustomerDetailsDocType  
		end  AS DocType, Forms.CustomerID3,FormItems.CashWage , FormItems.FormItemID, Forms.DocNo, Forms.DocDate,Forms.FormState,FormItems.CustomerID2 PersonID1D,'' AS FormDateNoCheck,Forms.FormDate AS FormDateCheck

FROM	Forms INNER JOIN
		SellsMethods ON Forms.SellsMethod = SellsMethods.SellsMethod INNER JOIN
		FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
		FormItems ON Forms.FormID = FormItems.FormID AND Forms.ServerID = FormItems.ServerID AND 
		Forms.YearID = FormItems.YearID LEFT OUTER JOIN
		Severable ON FormItems.FormItemID = Severable.FormItemID AND FormItems.FormID = Severable.FormID AND 
		FormItems.ServerID = Severable.ServerID AND FormItems.YearID = Severable.YearID LEFT OUTER JOIN
		LookUps ON Forms.PayTypes = LookUps.LookUpID
		LEFT OUTER JOIN Currencies ON ISNULL(Forms.ArzTypeID,0) = Currencies.CurrenciesID	INNER JOIN
        SellsEmporiums SE ON Forms.SellsEmporium = SE.SellsEmporium  	

WHERE	(
			case FormTypes.CustomerDetailsDocType 
				WHEN 13 THEN 
					case FormItems.CheckType  WHEN 0 THEN 6 else 2 end 
				WHEN 14 THEN 
					case FormItems.CheckType  WHEN 1 THEN -5 else 2 end 
				WHEN 15 THEN 
					case FormItems.CheckType  WHEN 0 THEN 6 else -5 end 
				else FormTypes.CustomerDetailsDocType  
			end in (@TypeDoc1 ,@TypeDoc2,@TypeDoc3,@TypeDoc4)
		) AND 
		( FormTypes.BedBesDetails <>0 ) AND 
		( case WHEN Severable.CustID >0 THEN Severable.CustID else FormItems.CustomerID2 end  between @CustIDFrom and @CustIDTo ) AND 
		( CASE WHEN @DefaultDateActive = 0 THEN Forms.FormDate ELSE Forms.DefaultDate END between @DateFrom and @DateTo ) AND
		( Forms.YearID between @YearIDFrom AND @YearIDTo )AND 
		(FormState<10) AND 
		(Forms.SellsMethod  BETWEEN @SellsMethodFrom AND @SellsMethodTo) AND 
		(Forms.SellsEmporium  BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)
