		(Forms.SellsEmporium  BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)
		and Customer3Active <> 0
		and case when Forms.CustomerID2=Forms.CustomerID3 and FormTypes.Customer2DocType in (@TypeDoc1 ,@TypeDoc2,@TypeDoc3,@TypeDoc4) then 0 else 1 end =1

