		Forms.CustomerID4, Forms.CustomerID1, Forms.FomNote,Forms.AidInfoNo, 
		Forms.AidInfoDate,
		case FormTypes.bedbes WHEN 0 THEN ISNULL(Forms.ArzAmount,0) else 0 end AS Arzbed ,
		case FormTypes.bedbes WHEN 1 THEN ISNULL(Forms.ArzAmount,0) else 0 end AS Arzbes 
		,ISNULL(Forms.ArzTypeID,0) AS ArzTypeID,Currencies.CurrenciesName,Currencies.CurrencySymbol,ISNULL(Forms.ArzRate,0) AS ArzRate ,
		case FormTypes.bedbes WHEN 0 THEN Forms.Amount else 0 end AS bed ,
		case FormTypes.bedbes WHEN 1 THEN Forms.Amount else 0 end AS bes ,
		Forms.BudgetCode, Forms.ProjectID, Forms.CustomerName2 , 
		Forms.CustomerID2 AS DetailCustID , Forms.CustomerID1 AS CustIDForShow , 1 AS kind, 
		LookUps.Code, LookUps.Name , Forms.SellsMethod, SellsMethods.SellsMethodName, 
		Forms.SellsEmporium ,SE.SellsEmporiumName,Forms.TruckNumber ,
		Forms.RelatedID , 1 AS RelatedKind , FormTypes.Customer2DocType AS DocType, 
		Forms.CustomerID3 ,0 AS CashWage ,0 AS FormItemID, Forms.DocNo, Forms.DocDate,Forms.FormState,0 PersonID1D,Forms.FormDate AS FormDateNoCheck,'' AS FormDateCheck
FROM	Forms  INNER JOIN
        SellsMethods ON Forms.SellsMethod = SellsMethods.SellsMethod INNER JOIN
		FormTypes ON Forms.FormType = FormTypes.FormType LEFT OUTER JOIN
		LookUps ON Forms.PayTypes = LookUps.LookUpID
		LEFT OUTER JOIN Currencies ON ISNULL(Forms.ArzTypeID,0) = Currencies.CurrenciesID	INNER JOIN
        SellsEmporiums SE ON Forms.SellsEmporium = SE.SellsEmporium  	

WHERE (FormTypes.DisplayFormType in(0,7)) AND 
        (Customer3Effect <>0 ) AND
		(FormTypes.Customer2DocType in (@TypeDoc1 ,@TypeDoc2,@TypeDoc3,@TypeDoc4)) And 
		(Forms.CustomerID4 between @CustIDFrom and @CustIDTo ) AND 
		(CASE WHEN @DefaultDateActive = 0 THEN Forms.FormDate ELSE Forms.DefaultDate END between @DateFrom and @DateTo ) AND
		( Forms.YearID between @YearIDFrom AND @YearIDTo )AND 

		(FormState<10) AND 
		(Forms.SellsMethod  BETWEEN @SellsMethodFrom AND @SellsMethodTo) AND 
		(Forms.SellsEmporium  BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)
		and Customer4Active <> 0
		and case when Forms.CustomerID4=Forms.CustomerID3 and FormTypes.Customer2DocType in (@TypeDoc1 ,@TypeDoc2,@TypeDoc3,@TypeDoc4) then 0 else 1 end =1
----------------------------------------
)

  
