CREATE  FUNCTION [dbo].[ReciptAccount] ( @TypeDoc1 int =1, 
				@PersonID1From  int = 0 , @PersonID1To int = 999999999 ,
				@DateFrom  Char(10) ='0001/01/01' , @DateTo Char(10) = '9999/99/99'  ,
				@YearIDFrom  int = 0 , @YearIDTo int = 9999 ,
				@SellsMethodFrom  int = 0 , @SellsMethodTo int = 999999999 ,
				@SellsEmporiumFrom  int = 0 , @SellsEmporiumTo int = 999999999 ,@DefaultDateActive Tinyint=0)
				
RETURNS table  AS  
return
(
SELECT	Recipts.ServerID ,Recipts.YearID ,Recipts.ReciptID,Recipts.ReciptNumber, Recipts.ReciptDate, 
		case WHEN Recipts.DefaultDate <'0001/01/01' THEN Recipts.ReciptDate else Recipts.DefaultDate end AS DefaultDate ,Recipts.DefaultDuration,
		Recipts.ReciptType,  ReciptTypes.ReciptCaption,
		Case WHEN isnull(PersonID2Bed ,0) = 1 THEN  Recipts.PersonID2 
		else 
			Case isnull(Customers.SellsDefaultState,0)
				WHEN 0 THEN Recipts.PersonID1
				WHEN 1 THEN Recipts.PersonID2
			Else 
				Recipts.PersonID1  
			end 
		end AS PersonID1, Recipts.PersonID2, Recipts.ReciptNote,

		case WHEN EffectOnCustomer =1 THEN	ISNULL(SUM(ReciptItems.ArzAmount),0) else   0 end AS Arzbed , 
		case WHEN EffectOnCustomer =2 THEN	ISNULL(SUM(ReciptItems.ArzAmount),0) else   0 end AS Arzbes  ,
		ISNULL(Recipts.ArzTypeID,0) AS ArzTypeID,Currencies.CurrenciesName,Currencies.CurrencySymbol,Recipts.RialsEqual AS ArzRate ,
----- tagirat 1394/02/08   		1399/08/25
		case WHEN EffectOnCustomer =1 THEN
			case 
			 WHEN CommissionActive In (5) THEN 
			Sum(UnitCommission * (ReciptItems.InputEntity + ReciptItems.OutputEntity))+ 
				Sum(isnull(TaxValue,0)) - SUM(ISNULL(isnull(DeficitValue,0)+isnull(DeficitValue2,0)+isnull(DeficitValue4,0)+isnull(DeficitValue3,0),0)) +
				ISNULL(AllDeficits_ForRecipts.DeficitAdd - AllDeficits_ForRecipts.DeficitDec,0)

               WHEN CommissionActive Not In (1,2) THEN 
				SUM(ReciptItems.TotalInputPrice) + SUM(ReciptItems.TotalOutputPrice) + 
				Sum(isnull(TaxValue,0)) - SUM(ISNULL(isnull(DeficitValue,0)+isnull(DeficitValue2,0)+isnull(DeficitValue4,0)+isnull(DeficitValue3,0),0)) +
				ISNULL(AllDeficits_ForRecipts.DeficitAdd - AllDeficits_ForRecipts.DeficitDec,0)

			else Sum(UnitCommission * (ReciptItems.InputEntity + ReciptItems.OutputEntity)) 
			    +SUM(ReciptItems.TotalInputPrice) + SUM(ReciptItems.TotalOutputPrice) + 
				Sum(isnull(TaxValue,0)) - SUM(ISNULL(isnull(DeficitValue,0)+isnull(DeficitValue2,0)+isnull(DeficitValue4,0)+isnull(DeficitValue3,0),0)) +
				ISNULL(AllDeficits_ForRecipts.DeficitAdd - AllDeficits_ForRecipts.DeficitDec,0)end 
		else   0 end AS bed , 
		case WHEN EffectOnCustomer =2 THEN	
			case 
			 WHEN CommissionActive In (5) THEN 
                 SUM(UnitCommission * (ReciptItems.InputEntity + ReciptItems.OutputEntity)) + 
				Sum(isnull(TaxValue,0)) - SUM(ISNULL(isnull(DeficitValue,0)+isnull(DeficitValue2,0)+isnull(DeficitValue4,0)+isnull(DeficitValue3,0),0)) +	
				ISNULL(AllDeficits_ForRecipts.DeficitAdd - AllDeficits_ForRecipts.DeficitDec,0)

             WHEN CommissionActive Not In (1,2) THEN 	
				SUM(ReciptItems.TotalInputPrice) + SUM(ReciptItems.TotalOutputPrice) + 
				Sum(isnull(TaxValue,0)) - SUM(ISNULL(isnull(DeficitValue,0)+isnull(DeficitValue2,0)+isnull(DeficitValue4,0)+isnull(DeficitValue3,0),0)) +	
				ISNULL(AllDeficits_ForRecipts.DeficitAdd - AllDeficits_ForRecipts.DeficitDec,0)

			else sum(UnitCommission * (ReciptItems.InputEntity + ReciptItems.OutputEntity))
			     + SUM(ReciptItems.TotalInputPrice) + SUM(ReciptItems.TotalOutputPrice) + 
				Sum(isnull(TaxValue,0)) - SUM(ISNULL(isnull(DeficitValue,0)+isnull(DeficitValue2,0)+isnull(DeficitValue4,0)+isnull(DeficitValue3,0),0)) +	
				ISNULL(AllDeficits_ForRecipts.DeficitAdd - AllDeficits_ForRecipts.DeficitDec,0) end 
		else   0 end AS bes  ,
----- tagirat 1394/02/08   	1399/08/25	
		Recipts.StoreID AS StoreIDForShow , 3 AS kind ,  LookUps.Code, LookUps.Name ,
		Recipts.SellsMethod, SellsMethods.SellsMethodName , Recipts.SellsEmporium ,SE.SellsEmporiumName,Recipts.TruckNumber ,
        Recipts.RelatedID , 3 AS RelatedKind, Recipts.DocNo, Recipts.DocDate,Recipts.ReciptState ,Recipts.AidNumber ,Recipts.AidDate

FROM	ReciptItems INNER JOIN
		Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
		ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType  INNER JOIN
		SellsMethods ON Recipts.SellsMethod = SellsMethods.SellsMethod  INNER JOIN
		Customers ON Recipts.PersonID1 = Customers.CustID Left Outer JOIN
		AllDeficits_ForRecipts ON Recipts.ReciptID = AllDeficits_ForRecipts.ReciptID 
		AND AllDeficits_ForRecipts.ServerID = Recipts.ServerID AND AllDeficits_ForRecipts.YearID = Recipts.YearID
		Left Outer JOIN
        LookUps ON Recipts.SecondType = LookUps.LookUpID
		LEFT OUTER JOIN Currencies ON ISNULL(Recipts.ArzTypeID,0) = Currencies.CurrenciesID	INNER JOIN
        SellsEmporiums SE ON Recipts.SellsEmporium = SE.SellsEmporium 	
WHERE	(EffectOnCustomer in (1,2) ) AND (Recipts.ReciptState < 3) AND 
		(@TypeDoc1 in (1,2,10))
        AND (Recipts.SellsMethod  BETWEEN @SellsMethodFrom AND @SellsMethodTo)
        AND (Recipts.SellsEmporium  BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)

AND 			Case WHEN isnull(PersonID2Bed ,0) = 1 THEN  Recipts.PersonID2 
		else 
			Case isnull(Customers.SellsDefaultState,0)
				WHEN 0 THEN Recipts.PersonID1
				WHEN 1 THEN Recipts.PersonID2
			Else 
				Recipts.PersonID1  
			end 
		end  between @PersonID1From and @PersonID1To  And 
		
		(CASE WHEN @DefaultDateActive = 0 THEN Recipts.ReciptDate ELSE Recipts.DefaultDate END  between @DateFrom and @DateTo ) AND 
 		(Recipts.YearID between @YearIDFrom AND @YearIDTo )	

GROUP BY Recipts.ServerID,Recipts.YearID ,
----- tagirat 1394/02/08   
ReciptTypes.CommissionActive ,
----- tagirat 1394/02/08   
		Case WHEN isnull(PersonID2Bed ,0) = 1 THEN  Recipts.PersonID2 
		else 
			Case isnull(Customers.SellsDefaultState,0)
				WHEN 0 THEN Recipts.PersonID1
				WHEN 1 THEN Recipts.PersonID2
			Else 
				Recipts.PersonID1  
			end 
		end  , Recipts.ReciptID, Recipts.ReciptType, Recipts.PersonID2,
		Recipts.ReciptNumber, Recipts.ReciptDate, ReciptTypes.ReciptCaption, 
		Recipts.ReciptNote, Recipts.StoreID ,EffectOnCustomer ,
		AllDeficits_ForRecipts.DeficitAdd ,AllDeficits_ForRecipts.DeficitDec ,  LookUps.Code, LookUps.Name ,
		Recipts.SellsMethod, SellsMethods.SellsMethodName ,Recipts.SellsEmporium ,SE.SellsEmporiumName,Recipts.TruckNumber ,
         Recipts.RelatedID ,
				case WHEN Recipts.DefaultDate <'0001/01/01' THEN Recipts.ReciptDate else Recipts.DefaultDate end,Recipts.DefaultDuration 
				,ISNULL(Recipts.ArzTypeID,0) ,Currencies.CurrenciesName,Currencies.CurrencySymbol,Recipts.RialsEqual , Recipts.DocNo, Recipts.DocDate,Recipts.ReciptState
				 ,Recipts.AidNumber ,Recipts.AidDate
	
----------------------------
