		Recipts.PersonID2, Recipts.ReciptNote,

		0 AS Arzbed ,   0 AS Arzbes  ,ISNULL(Recipts.ArzTypeID,0) AS ArzTypeID,Currencies.CurrenciesName,Currencies.CurrencySymbol,Recipts.RialsEqual AS ArzRate,
			sum(case WHEN ReciptTypesAccCode.bedbes = 0 THEN 
				case  InfoKind 
					WHEN 0 THEN isnull(TaxValue, 0) 
					WHEN 1 THEN isnull(Portage, 0) 
					WHEN 2 THEN isnull(Article, 0) 
					WHEN 3 THEN isnull(Wage, 0) 
					WHEN 4 THEN isnull(Scoria, 0) 
					WHEN 5 THEN ISNULL(DeficitValue+DeficitValue2+DeficitValue4+DeficitValue3,0) 
					WHEN 20 THEN ISNULL(DeficitValue+DeficitValue2+DeficitValue4+DeficitValue3,0) 
				else 0 end 
			else 0 end) AS bed 
			 ,
			sum(case WHEN ReciptTypesAccCode.bedbes = 1 THEN 
				case  InfoKind 
					WHEN 0 THEN isnull(TaxValue, 0) 
					WHEN 1 THEN isnull(Portage, 0) 
					WHEN 2 THEN isnull(Article, 0) 
					WHEN 3 THEN isnull(Wage, 0) 
					WHEN 4 THEN isnull(Scoria, 0) 
					WHEN 5 THEN ISNULL(DeficitValue+DeficitValue2+DeficitValue4+DeficitValue3,0) 
					WHEN 20 THEN ISNULL(DeficitValue+DeficitValue2+DeficitValue4+DeficitValue3,0) 
				else 0 end 
			else 0 end) AS bes, 
  		
		Recipts.StoreID AS StoreIDForShow , 3 AS kind ,  LookUps.Code, LookUps.Name ,
		Recipts.SellsMethod, SellsMethods.SellsMethodName , Recipts.SellsEmporium ,SE.SellsEmporiumName,Recipts.TruckNumber ,
        Recipts.RelatedID , 3 AS RelatedKind, Recipts.DocNo, Recipts.DocDate,Recipts.ReciptState ,Recipts.AidNumber ,Recipts.AidDate

FROM	ReciptItems INNER JOIN
		Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
		ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType  INNER JOIN
		SellsMethods ON Recipts.SellsMethod = SellsMethods.SellsMethod  INNER JOIN
		Customers ON Recipts.PersonID1 = Customers.CustID Left Outer JOIN
		AllDeficits_ForRecipts ON Recipts.ReciptID = AllDeficits_ForRecipts.ReciptID 
		AND AllDeficits_ForRecipts.ServerID = Recipts.ServerID AND AllDeficits_ForRecipts.YearID = Recipts.YearID
		Left Outer JOIN
        LookUps ON Recipts.SecondType = LookUps.LookUpID inner join 
			ReciptTypesAccCode on ReciptTypes.ReciptType = ReciptTypesAccCode.ReciptType
			left outer join 
				(select distinct PrvYearID , preReciptItemID ,ServerID 
				FROM	ReciptItems 
				where yearid between @YearIDFrom AND @YearIDTo and not (PrvYearID  is null) )_ReciptItems 
			on ReciptItems.ReciptItemID = _ReciptItems.preReciptItemID and ReciptItems.YearID = _ReciptItems.PrvYearID and ReciptItems.ServerID = _ReciptItems.ServerID 

						left outer join 

				(select distinct PrvYearID , ParentReciptID ,ServerID , ReciptType
				FROM	Recipts 
				where yearid between @YearIDFrom AND @YearIDTo and not (PrvYearID  is null)   )_Recipts 
			on Recipts.ReciptID = _Recipts.ParentReciptID and Recipts.YearID = _Recipts.PrvYearID and Recipts.ServerID = _Recipts.ServerID and 
			ReciptTypes.CorrelateReciptType<>_Recipts.ReciptType
		LEFT OUTER JOIN Currencies ON ISNULL(Recipts.ArzTypeID,0) = Currencies.CurrenciesID INNER JOIN
        SellsEmporiums SE ON Recipts.SellsEmporium = SE.SellsEmporium 	 	

WHERE	(EffectOnCustomer in (3,4)) AND 
		(Recipts.ReciptState < 3) AND 

		--(@TypeDoc1 in (1,2,10))
        --AND 
		(Recipts.SellsMethod  BETWEEN @SellsMethodFrom AND @SellsMethodTo) AND 
		(Recipts.SellsEmporium  BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)AND 
		(_Recipts.ParentReciptID is null and _ReciptItems.preReciptItemID is null ) AND 
		(case  InfoKind 
					WHEN 0 THEN isnull(TaxValue, 0) 
					WHEN 1 THEN isnull(Portage, 0) 
					WHEN 2 THEN isnull(Article, 0) 
					WHEN 3 THEN isnull(Wage, 0) 
					WHEN 4 THEN isnull(Scoria, 0) 
					WHEN 5 THEN ISNULL(DeficitValue+DeficitValue2+DeficitValue4+DeficitValue3,0) 
					WHEN 20 THEN ISNULL(DeficitValue+DeficitValue2+DeficitValue4+DeficitValue3,0) 
				else 0 end <> 0)

AND 	(ReciptTypesAccCode.CustID  between @PersonID1From and @PersonID1To)  And 
		(CASE WHEN @DefaultDateActive = 0 THEN Recipts.ReciptDate ELSE Recipts.DefaultDate END  between @DateFrom and @DateTo ) AND 
 		(Recipts.YearID between @YearIDFrom AND @YearIDTo )	

GROUP BY Recipts.ServerID,Recipts.YearID ,ReciptTypes.CommissionActive ,ISNULL(Recipts.ArzTypeID,0) ,Currencies.CurrenciesName,Currencies.CurrencySymbol,Recipts.RialsEqual,
		ReciptTypesAccCode.CustID  , Recipts.ReciptID, Recipts.ReciptType, Recipts.PersonID2,
		Recipts.ReciptNumber, Recipts.ReciptDate, ReciptTypes.ReciptCaption, 
		Recipts.ReciptNote, Recipts.StoreID ,EffectOnCustomer ,
		AllDeficits_ForRecipts.DeficitAdd ,AllDeficits_ForRecipts.DeficitDec ,  LookUps.Code, LookUps.Name ,
		Recipts.SellsMethod, SellsMethods.SellsMethodName ,Recipts.SellsEmporium ,SE.SellsEmporiumName,Recipts.TruckNumber ,
        Recipts.RelatedID ,
		case WHEN Recipts.DefaultDate <'0001/01/01' THEN Recipts.ReciptDate else Recipts.DefaultDate end ,Recipts.DefaultDuration
		, Recipts.DocNo, Recipts.DocDate,Recipts.ReciptState ,Recipts.AidNumber ,Recipts.AidDate



