		end AS ReciptCaption, 
		ReciptsPayments.CustID AS PersonID1, 
		Recipts.PersonID2, ReciptsPayments.Note,0 AS Arzbed , 0 AS Arzbes ,
		ISNULL(Recipts.ArzTypeID,0) AS ArzTypeID,Currencies.CurrenciesName,Currencies.CurrencySymbol,Recipts.RialsEqual AS ArzRate,
		case WHEN  ReciptTypes.SellEffect = 2 THEN sum(ReciptsPayments.Payment) else 0 end AS bed ,
		case WHEN  ReciptTypes.SellEffect = 1 THEN sum(ReciptsPayments.Payment) 
			 WHEN (ReciptTypes.SellEffect = 0) and (ReciptTypes.AutoInsertPostInsert = 4) THEN sum(ReciptsPayments.Payment)
		else 0 end AS bes, 
		Recipts.StoreID AS StoreIDForShow , 3 AS kind ,  LookUps.Code, LookUps.Name ,
		Recipts.SellsMethod, SellsMethods.SellsMethodName , Recipts.SellsEmporium ,SE.SellsEmporiumName,Recipts.TruckNumber ,
        Recipts.RelatedID , 3 AS RelatedKind, Recipts.DocNo, Recipts.DocDate,Recipts.ReciptState ,Recipts.AidNumber ,Recipts.AidDate

FROM	ReciptsPayments INNER JOIN
		Recipts ON	Recipts.ReciptID = ReciptsPayments.ReciptID AND 
					ReciptsPayments.ServerID = Recipts.ServerID AND 
					ReciptsPayments.YearID = Recipts.YearID INNER JOIN
		ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType  INNER JOIN
		SellsMethods ON Recipts.SellsMethod = SellsMethods.SellsMethod  INNER JOIN
		Customers ON ReciptsPayments.CustID = Customers.CustID Left Outer JOIN
        LookUps ON Recipts.SecondType = LookUps.LookUpID
		LEFT OUTER JOIN Currencies ON ISNULL(Recipts.ArzTypeID,0) = Currencies.CurrenciesID INNER JOIN
        SellsEmporiums SE ON Recipts.SellsEmporium = SE.SellsEmporium 		

WHERE	(Recipts.ReciptState < 3) AND 
		(Recipts.SellsMethod  BETWEEN @SellsMethodFrom AND @SellsMethodTo) AND 
		(Recipts.SellsEmporium  BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)AND 
		(Payment <> 0)
AND 	ReciptsPayments.CustID  between @PersonID1From and @PersonID1To  And 
		(CASE WHEN @DefaultDateActive = 0 THEN Recipts.ReciptDate ELSE Recipts.DefaultDate END  between @DateFrom and @DateTo ) AND 
 		(Recipts.YearID between @YearIDFrom AND @YearIDTo )	

GROUP BY Recipts.ServerID,Recipts.YearID ,ReciptTypes.CommissionActive ,
		ReciptsPayments.CustID  , Recipts.ReciptID, Recipts.ReciptType, Recipts.PersonID2,
		Recipts.ReciptNumber, Recipts.ReciptDate, ReciptTypes.SellEffect ,		
		PaymentKind , ReciptTypes.ReciptCaption, 
		ReciptsPayments.Note, Recipts.StoreID ,EffectOnCustomer ,LookUps.Code, LookUps.Name ,
		Recipts.SellsMethod, SellsMethods.SellsMethodName ,Recipts.SellsEmporium ,SE.SellsEmporiumName,Recipts.TruckNumber , Recipts.RelatedID ,
		case WHEN Recipts.DefaultDate <'0001/01/01' THEN Recipts.ReciptDate else Recipts.DefaultDate end ,Recipts.DefaultDuration 
		,ReciptTypes.AutoInsertPostInsert
		,ISNULL(Recipts.ArzTypeID,0) ,Currencies.CurrenciesName,Currencies.CurrencySymbol,Recipts.RialsEqual
		, Recipts.DocNo, Recipts.DocDate,Recipts.ReciptState ,Recipts.AidNumber ,Recipts.AidDate

----------------------------
UNION ALL
---------------------------
----------------------------- برای اضافه نمودن کسورات و اضافات خطی در گزارش عملکردمشتري 
SELECT  Recipts.ServerID,Recipts.YearID ,Recipts.ReciptID,Recipts.ReciptNumber, 
         Recipts.ReciptDate, 
		 		case WHEN Recipts.DefaultDate <'0001/01/01' THEN Recipts.ReciptDate else Recipts.DefaultDate end AS DefaultDate ,Recipts.DefaultDuration,
		Recipts.ReciptType, 
		case  InfoKind WHEN 1 THEN 'کرایه حمل' else '' end  +'--'+ReciptTypes.ReciptCaption	 AS ReciptCaption, 
		case when ReciptTypesAccCode.CustID =-1 then Recipts.PersonID1 else 0 end AS PersonID1, 

		Recipts.PersonID2, Recipts.ReciptNote,
		  case WHEN  Recipts.portagebedbes=1 THEN ISNULL((ReciptItems.ArzPortage),0) else   0 end AS Arzbed , 
  case WHEN  Recipts.portagebedbes=2 THEN ISNULL((ReciptItems.ArzPortage),0) else   0 end AS Arzbes,
		 
		ISNULL(Recipts.ArzTypeID,0) AS ArzTypeID,Currencies.CurrenciesName,Currencies.CurrencySymbol,Recipts.RialsEqual AS ArzRate,
		case WHEN  Recipts.portagebedbes=1 THEN 
  case  InfoKind 
   WHEN 1 THEN isnull(Portage, 0) 
  else 0 end 
 else 0 end AS bed 
  ,
 case WHEN  Recipts.portagebedbes=2 THEN 
  case  InfoKind 
   WHEN 1 THEN isnull(Portage, 0) 
  else 0 end 
 else 0 end AS bes, 
		Recipts.StoreID AS StoreIDForShow , 3 AS kind ,  LookUps.Code, LookUps.Name ,
		Recipts.SellsMethod, SellsMethods.SellsMethodName , Recipts.SellsEmporium ,Se.SellsEmporiumName,Recipts.TruckNumber ,
        Recipts.RelatedID , 3 AS RelatedKind, Recipts.DocNo, Recipts.DocDate,Recipts.ReciptState ,Recipts.AidNumber ,Recipts.AidDate

FROM  ReciptItems 
  INNER JOIN Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID 
   AND ReciptItems.YearID = Recipts.YearID 
  INNER JOIN ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType 
  INNER JOIN SellsMethods ON Recipts.SellsMethod = SellsMethods.SellsMethod 
  INNER JOIN  Customers ON Recipts.PersonID1 = Customers.CustID 
  INNER JOIN StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode  
  LEFT OUTER JOIN Units ON StuffCoding.n_UnitCode = Units.UnitCode   
  LEFT OUTER JOIN LookUps ON Recipts.SecondType = LookUps.LookUpID 
  INNER JOIN ReciptTypesAccCode on ReciptTypes.ReciptType = ReciptTypesAccCode.ReciptType
        LEFT OUTER JOIN Currencies ON ISNULL(Recipts.ArzTypeID,0) = Currencies.CurrenciesID INNER JOIN
        SellsEmporiums SE ON Recipts.SellsEmporium = SE.SellsEmporium 	

WHERE (EffectOnCustomer in (1,2)) AND 
  (Recipts.ReciptState < 3) AND
  (case when ReciptTypesAccCode.CustID =-1 then Recipts.PersonID1 else -1 end between @PersonID1From and @PersonID1To) And 
  (CASE WHEN @DefaultDateActive = 0 THEN Recipts.ReciptDate ELSE Recipts.DefaultDate END  between @DateFrom and @DateTo ) AND 
   (Recipts.YearID between @YearIDFrom AND @YearIDTo ) AND 
   (Recipts.SellsMethod between @SellsMethodFrom AND @SellsMethodTo ) AND  
   (Recipts.SellsEmporium between @SellsEmporiumFrom AND @SellsEmporiumTo ) 
  AND case when Recipts.portagebedbes <> 0 and isnull(ReciptTypesAccCode.CustID,0) <> 0 then 1 else 0 end =1

