CREATE FUNCTION [dbo].[AllAccount] ( @TypeDoc1 int =1 ,@TypeDoc2 int =-1,
				@TypeDoc3 int =-1 ,@TypeDoc4 int =-1 , 
				@CustIDFrom  int = 0 , @CustIDTo int = 999999999 ,
				@DateFrom  Char(10) ='0001/01/01' , @DateTo Char(10) = '1999/12/30',
				@DateFromRemain  Char(10) ='0001/01/00' , 
				@YearIDFrom  int = 0 , @YearIDTo int = 9999,
				@SellsMethodFrom  int = 0 , @SellsMethodTo int = 999999999 ,
				@SellsEmporiumFrom  int = 0 , @SellsEmporiumTo int = 999999999 ,@DefaultDateActive Tinyint=0)

RETURNS table  AS  
return (
SELECT     ServerID, YearID, FormID, FormNumber, FormDate, DefaultDate,DefaultDuration, checkNumber, checkDate, BankName, AccountNumber, 
FormType, FormCaption, CustomerID1, 
           CustomerID2, FomNote, AidInfoNo, AidInfoDate,
		    Arzbed, Arzbes,ArzTypeID,CurrenciesName,CurrencySymbol, ArzRate,
		    bed, bes, BudgetCode, ProjectID, CustomerName2, DetailCustID, CustIDForShow, kind, Code, Name, SellsMethod, 
           SellsMethodName,SellsEmporium,SellsEmporiumName,TruckNumber , RelatedID, RelatedKind, DocType
           ,1 AS AnalizeType, 0 AS RelaID
		,CASE WHEN bes>bed THEN 1 ELSE 0 END AS BedOrderBes,FormItemID, DocNo, DocDate,
		CASE WHEN  FormState= 0 THEN  'موقت'
             WHEN  FormState= 1 THEN  'قطعي'
             WHEN  FormState=10 THEN  'باطله'
             WHEN  FormState=11 THEN  'رزرو'
             WHEN  FormState=12 THEN  'پیش نویس'
	    ELSE '' END AS FormStates,''  AS ReciptDateMax, FormDateNoCheck, FormDateCheck
		
		
		
FROM         CashAccount(@TypeDoc1 ,@TypeDoc2 ,@TypeDoc3 ,@TypeDoc4  
						, @CustIDFrom  , @CustIDTo,@DateFrom,@DateTo ,@YearIDFrom ,@YearIDTo,@SellsMethodFrom  , @SellsMethodTo  ,
				         @SellsEmporiumFrom  , @SellsEmporiumTo ,@DefaultDateActive ) CashAccount

UNION ALL

SELECT  ServerID, YearID , ReciptID,ReciptNumber, ReciptDate,DefaultDate,DefaultDuration, '0' AS CheckNo , '0'  AS CheckDate , 
		'' AS BankName , '' AS AccountNumber ,ReciptType, ReciptCaption,
		PersonID1,PersonID2, ReciptNote, AidNumber AS AidNo ,  AidDate ,
		    Arzbed, Arzbes,ArzTypeID,CurrenciesName,CurrencySymbol, ArzRate,		    
		bed, bes ,0 AS BudgetCode, 0 AS ProjectID, '' AS CuctName2 , 0 AS DetailCustID ,
		StoreIDForShow ,kind,  Code,  Name ,SellsMethod, SellsMethodName, SellsEmporium,SellsEmporiumName,TruckNumber ,
		RelatedID , RelatedKind, 10 AS doctype , 1 AS AnalizeType, 0 AS RelaID
		,CASE WHEN bes>bed THEN 1 else 0 end AS BedOrderBes, 0 AS FormItemID, DocNo, DocDate,
		 CASE  WHEN ReciptState = 0 THEN 'موقت'
               WHEN ReciptState = 1 THEN 'قطعي'
               WHEN ReciptState = 2 THEN 'دائم'
               WHEN ReciptState = 3 THEN 'باطله'
               WHEN ReciptState = 4 THEN 'رزرو'
               WHEN ReciptState = 5 THEN 'پیش نویس'
			   ELSE '' 
		 END AS ReciptState,ReciptDate ReciptDateMax,'' FormDateNoCheck,'' FormDateCheck

		
FROM	ReciptAccount(@TypeDoc1 , @CustIDFrom  , @CustIDTo ,@DateFrom,@DateTo ,@YearIDFrom ,@YearIDTo,@SellsMethodFrom  , @SellsMethodTo  ,
				         @SellsEmporiumFrom  , @SellsEmporiumTo ,@DefaultDateActive ) ReciptAccount
---where (Bed+Bes>0)   مشکل در گردش فرمها

UNION ALL
------------------  مانده نقل از قبل ------------------
--                                     به علت آنالیز مبلغ سال و مشتری ترکیب شد
SELECT   max(ServerID), min(YearID) , 
--- -CAST(right(min(YearID),2)+LTRIM(CustomerID1)AS INT) AS ReciptID
 -CustomerID1 AS ReciptID
, 0 AS FormNumber, @DateFromRemain AS FormDate,@DateFromRemain AS DefaultDate,0 AS DefaultDuration, '0' AS checkNumber,
		'0' AS checkDate,'' AS BankName , '' AS AccountNumber  , 0 AS FormType,	'نقل از قبل' AS FormCaption, 
		 CustomerID1 , 0 AS PersonID2 , 'نقل از قبل'  AS FomNote, '0' AS AidInfoNo, 
		 '0' AS AidInfoDate, 
		 Sum(ISNULL(Arzbed,0)) AS Arzbed , Sum(ISNULL(Arzbes,0)) AS Arzbes , ISNULL(ArzTypeID,0) ArzTypeID, CurrenciesName,CurrencySymbol, max(ISNULL(ArzRate,0)) AS ArzRate,

		-- Case WHEN Sum(bed)-Sum(bes) >0 THEN 
		--	Sum(bed)-Sum(bes) else 0 end  AS bed, 
		--Case WHEN Sum(bed)-Sum(bes) <0 THEN 
		--	 -(Sum(bed)-Sum(bes)) else 0 end  AS bes    
		---البرز میکرو گردش دار می خواهند غیر فعال شد
		 Sum(bed) AS bed , Sum(bes) AS bes 


		 , 0 AS BudgetCode, 0 AS ProjectID,	
		 '' AS CustName2 ,  0 AS DetailCustID ,0 AS CustIDForShow ,0 AS kind , 0 AS  Code, '' AS  Name ,0 AS SellsMethod, 
		 '' AS SellsMethodName,  SellsEmporium ,'' as SellsEmporiumName,null TruckNumber ,
		-1 AS RelatedID , 0 AS RelatedKind,   doctype, 0 AS AnalizeType, 0 AS RelaID
		,case WHEN Sum(bes)>Sum(bed) THEN 1 else 0 end AS BedOrderBes,0 AS FormItemID,0 AS DocNo,'' AS  DocDate,'' AS FormState,'' AS ReciptDateMax,'' FormDateNoCheck,'' FormDateCheck

FROM     (
-------
SELECT   ServerID, YearID , CustomerID1 , Arzbed,Arzbes,ArzTypeID,CurrenciesName,CurrencySymbol, ArzRate, bed,bes ,doctype ,SellsEmporium,TruckNumber 
FROM     CashAccount(@TypeDoc1 ,@TypeDoc2 ,@TypeDoc3 ,@TypeDoc4 , @CustIDFrom  , 
		 @CustIDTo , '01/01/00', @DateFromRemain ,@YearIDFrom ,@YearIDTo,@SellsMethodFrom  , @SellsMethodTo  ,
				         @SellsEmporiumFrom  , @SellsEmporiumTo ,@DefaultDateActive  ) CashAccount

UNION ALL

SELECT  ServerID, YearID , PersonID1, Arzbed,Arzbes,ArzTypeID,CurrenciesName,CurrencySymbol, ArzRate, bed,bes  ,  @TypeDoc1 AS doctype,SellsEmporium,TruckNumber 
		
FROM	ReciptAccount(@TypeDoc1 , @CustIDFrom  , @CustIDTo , '01/01/00', 
		@DateFromRemain ,@YearIDFrom ,@YearIDTo ,@SellsMethodFrom  , @SellsMethodTo  ,
				         @SellsEmporiumFrom  , @SellsEmporiumTo ,@DefaultDateActive 
		) ReciptAccount

Union all
--------------------------- مانده ابتداي سال -----------------------
SELECT	 0 AS ServerID ,@YearIDFrom AS YearID , CustID ,0 AS Arzbed,0 AS Arzbes,ISNULL(ArzTypeID,0) AS ArzTypeID,Currencies.CurrenciesName,Currencies.CurrencySymbol,0 AS  ArzRate,
		Case WHEN firstBalance >0 THEN 
			firstBalance else 0 end  AS bed, 
		Case WHEN firstBalance <0 THEN 
			- firstBalance else 0 end  AS bes , @TypeDoc1 AS doctype , customers.SellsEmporium,NULL TruckNumber 
FROM	customers
      LEFT OUTER JOIN Currencies ON ISNULL(customers.ArzTypeID,0) = Currencies.CurrenciesID INNER JOIN
        SellsEmporiums SE ON customers.SellsEmporium = SE.SellsEmporium 	
WHERE	firstBalance <> 0 And
 		(CustID between @CustIDFrom and @CustIDTo ) AND 
 		(@TypeDoc1 in (1,2,10) or @TypeDoc2 in (1,2,10) or 
 			@TypeDoc3 in(1,2,10) or @TypeDoc4 in (1,2,10))
 		 AND (customers.SellsEmporium between @SellsEmporiumFrom and @SellsEmporiumTo )
 			
UNION ALL 
-------------------------- مانده ابتداي سال بتفكيك سال مالي -----------------------
SELECT    0 AS ServerID, YearID,  PersonID1
,
  CASE WHEN ArzRemain > 0 THEN ISNULL(ArzRemain,0) ELSE 0 END AS Arzbed, 
  CASE WHEN ArzRemain < 0 THEN - ISNULL(ArzRemain,0) ELSE 0 END AS Arzbes ,


ArzTypeID,CurrenciesName,Currencies.CurrencySymbol,0 AS ArzRate, 
  CASE WHEN Rate > 0 THEN Rate ELSE 0 END AS bed, 
  CASE WHEN Rate < 0 THEN - Rate ELSE 0 END AS bes ,
   @TypeDoc1 AS doctype, RemainsEarly.SellsEmporium,null TruckNumber 
FROM         RemainsEarly
					  LEFT OUTER JOIN Currencies ON ISNULL(RemainsEarly.ArzTypeID,0) = Currencies.CurrenciesID INNER JOIN
        SellsEmporiums SE ON RemainsEarly.SellsEmporium = SE.SellsEmporium 		
WHERE     (Rate <> 0) And
 		(PersonID1 between @CustIDFrom and @CustIDTo ) AND 
 		(@TypeDoc1 in (1,2,10) or @TypeDoc2 in (1,2,10) or 
 			@TypeDoc3 in(1,2,10) or @TypeDoc4 in (1,2,10)) And 
 			(YearID BETWEEN @YearIDFrom  AND @YearIDFrom )
 		 AND (RemainsEarly.SellsEmporium between @SellsEmporiumFrom and @SellsEmporiumTo )

) FirstBalance 
Group By CustomerID1, doctype, SellsEmporium,ISNULL(ArzTypeID,0),  CurrenciesName,CurrencySymbol


UNION ALL
---------------------------------------- اين قسمت براي اضافه کردن چکهاي واگذاري به مشتريان با شرط تاريخ سررسيد موجود در تنظيمات سيستم اضافه شده است  ---------------------
SELECT	Forms.ServerID, Forms.YearID,Forms.FormID, Forms.FormNumber, Forms.FormDate,

case WHEN Forms.DefaultDate <'0001/01/01' THEN RIGHT( FormItems.CheckDate,10) else Forms.DefaultDate end AS DefaultDate,Forms.DefaultDuration,
--ISNULL(Forms.DefaultDate,FormItems.CheckDate) AS DefaultDate,
	 FormItems.CheckNumber, RIGHT( FormItems.CheckDate,10), 
		FormItems.BankName , FormItems.AccountNumber ,Forms.FormType, 
		FormTypes.FormCaption,  FormItems.CustomerID2 , Forms.CustomerID1 ,
		ISNULL(Forms.FomNote, '')+' '+ISNULL(FormItems.ItemNote, '') AS FomNote, Forms.AidInfoNo, Forms.AidInfoDate,

		ISNULL(FormItems.ArzAmount,0) AS Arzbed ,
		0 AS Arzbes ,ISNULL(Forms.ArzTypeID,0) AS ArzTypeID,Currencies.CurrenciesName,Currencies.CurrencySymbol, ISNULL(Forms.ArzRate,0) AS ArzRate,

		FormItems.ItemAmount AS bed ,
		0 AS bes ,
		case FormTypes.BudgetCodePosition
			WHEN 0 THEN 0
			WHEN 1 THEN FormItems.BudgetCode
			WHEN 2 THEN FormItems.BudgetCode
			WHEN 3 THEN Forms.BudgetCode
		else 0 end AS BudgetCode ,
		case FormTypes.BudgetCodePosition
			WHEN 0 THEN 0
			WHEN 1 THEN FormItems.ProjectID
			WHEN 2 THEN FormItems.ProjectID
			WHEN 3 THEN Forms.ProjectID
		else 0 end AS ProjectID ,
		case FormTypes.Customer2ActiveOnDetail
			WHEN 0 THEN Forms.CustomerName2
			WHEN 1 THEN null
			WHEN 2 THEN null
			WHEN 3 THEN Forms.CustomerName2
		else str(Forms.CustomerID2) end AS CustomerName2 ,
		FormItems.CustomerID2   AS DetailCustID ,Forms.CustomerID1 AS CustIDForShow , 2 AS kind , 
		LookUps.Code, LookUps.Name, Forms.SellsMethod, SellsMethods.SellsMethodName,
		Forms.SellsEmporium ,SE.SellsEmporiumName,Forms.TruckNumber ,
		FormItems.RelatedID , 2 AS RelatedKind ,
		12 AS DocType  ,1 AS AnalizeType, 0 AS RelaID
		,0 AS BedOrderBes,FormItems.FormItemID, DocNo, DocDate,
		CASE WHEN  FormState= 0 THEN  'موقت'
             WHEN  FormState= 1 THEN  'قطعي'
             WHEN  FormState=10 THEN  'باطله'
             WHEN  FormState=11 THEN  'رزرو'
             WHEN  FormState=12 THEN  'پیش نویس'
	    ELSE '' END AS FormStates ,'' as MaxReciptDate,'' FormDateNoCheck,FormDate FormDateCheck
FROM	Forms INNER JOIN
	SellsMethods ON Forms.SellsMethod = SellsMethods.SellsMethod INNER JOIN
	FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
	FormItems ON Forms.FormID = FormItems.FormID AND Forms.ServerID = FormItems.ServerID AND 
		Forms.YearID = FormItems.YearID LEFT OUTER JOIN
	FormItems FormItems_1 ON FormItems.FormItemID = FormItems_1.preFormItemID AND FormItems.YearID = FormItems_1.YearID AND 
	FormItems.ServerID = FormItems_1.ServerID LEFT OUTER JOIN
	LookUps ON Forms.PayTypes = LookUps.LookUpID
    LEFT OUTER JOIN Currencies ON ISNULL(Forms.ArzTypeID,0) = Currencies.CurrenciesID  INNER JOIN
	SellsEmporiums SE ON Forms.SellsEmporium = SE.SellsEmporium 
WHERE  @TypeDoc1  in  ( 1 ,2 ,10 ) and @TypeDoc2  in  ( 3,4,11)   and
	( FormItems.CustomerID2 between @CustIDFrom and @CustIDTo ) AND 
	( CASE WHEN @DefaultDateActive = 0 THEN Forms.FormDate ELSE Forms.DefaultDate END  between @DateFrom and @DateTo ) AND
	( Forms.YearID between @YearIDFrom AND @YearIDTo ) AND  
	( FormState<10 ) And 
	( FormItems.CheckDate >= 
		right(dbo.MiladiTOShamsi(
			 dbo.ShamsiToMiladi( @DateTo ) - 
			 ( dbo.GetCustCheckDateOffset() ) 
			 ) , 8 ) ) and
	((dbo.GetCreditChecked5())=1) and 
	( FormItems_1.preFormItemID IS NULL) and forms.FormType = 12

 AND (Forms.SellsMethod  BETWEEN @SellsMethodFrom AND @SellsMethodTo)
 AND (Forms.SellsEmporium  BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)
)


