CREATE FUNCTION [dbo].[AllAccountReleted] ( @TypeDoc1 int =1 ,@TypeDoc2 int =-1,
				@TypeDoc3 int =-1 ,@TypeDoc4 int =-1 , 
				@CustIDFrom  int = 0 , @CustIDTo int = 999999999 ,
				@DateFrom  Char(10) ='0001/01/01' , @DateTo Char(10) = '9999/99/99',
				@DateFromRemain  Char(10) ='01/01/00' , 
				@YearIDFrom  int = 0 , @YearIDTo int = 9999,
				@SellsMethodFrom  int = 0 , @SellsMethodTo int = 999999999 ,
				@SellsEmporiumFrom  int = 0 , @SellsEmporiumTo int = 999999999,@DefaultDateActive Tinyint=0)


RETURNS table  AS  
return (

SELECT  AllAccount_1.ServerID, AllAccount_1.YearID, AllAccount_1.FormID, AllAccount_1.FormNumber, AllAccount_1.FormDate, AllAccount_1.DefaultDate,AllAccount_1.DefaultDuration, AllAccount_1.checkNumber, 
        RIGHT( AllAccount_1.CheckDate,10) AS checkDate, AllAccount_1.BankName, AllAccount_1.AccountNumber, AllAccount_1.FormType, AllAccount_1.FormCaption, 
        AllAccount_1.CustomerID1, AllAccount_1.CustomerID2, AllAccount_1.FomNote, AllAccount_1.AidInfoDate, AllAccount_1.AidInfoNo, 
        /*AllAccount_1.bed -*/ CASE WHEN AllAccount_1.bed > 0 THEN ABS(ISNULL(Rele.SumRel, AllAccount_1.bed)) ELSE 0 END AS bed, 
        /*AllAccount_1.bes -*/ CASE WHEN AllAccount_1.bes > 0 THEN ABS(ISNULL(Rele.SumRel, AllAccount_1.bes)) ELSE 0 END AS bes,

					  
		AllAccount_1.BudgetCode, 
        AllAccount_1.ProjectID, AllAccount_1.CustomerName2, AllAccount_1.DetailCustID, AllAccount_1.CustIDForShow, AllAccount_1.kind, AllAccount_1.Code, 
        AllAccount_1.Name, AllAccount_1.SellsMethod, AllAccount_1.SellsMethodName
		,CASE WHEN ISNULL(Rele.ID,0)=0  THEN AllAccount_1.RelatedID ELSE Rele.RelatedID END  AS RelatedID
		,CASE WHEN ISNULL(Rele.ID,0)=0  THEN AllAccount_1.RelatedKind ELSE Rele.Kind END  AS RelatedKind
		,CASE WHEN ISNULL(Rele.ID,0)=0  THEN AllAccount_1.AnalizeType ELSE 2 END  AS AnalizeType
		--, 0 AS RelaID
		,Rele.ID AS RelaID
		,AllAccount_1.FormItemID ,ArzRate,Arzbed , Arzbes ,ArzTypeID,CurrenciesName,CurrencySymbol, TruckNumber,SellsEmporiumName 
FROM         AllAccount(@TypeDoc1, @TypeDoc2, @TypeDoc3, @TypeDoc4, @CustIDFrom, @CustIDTo, @DateFrom, @DateTo, @DateFromRemain, @YearIDFrom, @YearIDTo,@SellsMethodFrom  , @SellsMethodTo  ,
				         @SellsEmporiumFrom  , @SellsEmporiumTo,@DefaultDateActive ) 
                      AS AllAccount_1   Left Outer JOIN
                          (SELECT    ID,RelatedID, ParentID, YearID, ServerID, Kind, /*SUM*/(Bed - Bes) AS SumRel
                             FROM         Related
							 WHERE ISNULL(FormItemID,0) = 0
                             --GROUP BY ParentID, YearID, ServerID, Kind
							 ) AS Rele ON AllAccount_1.ServerID = Rele.ServerID AND AllAccount_1.YearID = Rele.YearID AND 
                      AllAccount_1.FormID = Rele.ParentID AND AllAccount_1.Kind = Rele.Kind AND AllAccount_1.Kind <> 2 
     WHERE (AllAccount_1.FormItemID = 0 )


UNION ALL


SELECT  AllAccount_1.ServerID, AllAccount_1.YearID, AllAccount_1.FormID, AllAccount_1.FormNumber, AllAccount_1.FormDate, AllAccount_1.DefaultDate,AllAccount_1.DefaultDuration, AllAccount_1.checkNumber, 
       RIGHT( AllAccount_1.CheckDate,10) AS checkDate, AllAccount_1.BankName, AllAccount_1.AccountNumber, AllAccount_1.FormType, AllAccount_1.FormCaption, 
        AllAccount_1.CustomerID1, AllAccount_1.CustomerID2, AllAccount_1.FomNote, AllAccount_1.AidInfoDate, AllAccount_1.AidInfoNo, 
		CASE WHEN ISNULL(Rele.ID,0)=0 THEN AllAccount_1.bed ELSE Rele.bed END AS bed,
		CASE WHEN ISNULL(Rele.ID,0)=0 THEN AllAccount_1.bes ELSE Rele.bes END AS bes,
        --Rele.bed , Rele.bes, 
		AllAccount_1.BudgetCode, 
        AllAccount_1.ProjectID, AllAccount_1.CustomerName2, AllAccount_1.DetailCustID, AllAccount_1.CustIDForShow, AllAccount_1.kind, AllAccount_1.Code, 
        AllAccount_1.Name, AllAccount_1.SellsMethod, AllAccount_1.SellsMethodName
		,CASE WHEN ISNULL(Rele.ID,0)=0  THEN AllAccount_1.RelatedID ELSE Rele.RelatedID END  AS RelatedID
		,CASE WHEN ISNULL(Rele.ID,0)=0  THEN AllAccount_1.RelatedKind ELSE Rele.Kind END  AS RelatedKind
		,CASE WHEN ISNULL(Rele.ID,0)=0  THEN AllAccount_1.AnalizeType ELSE 2 END  AS AnalizeType
		,Rele.ID AS RelaID
		,AllAccount_1.FormItemID,ArzRate,Arzbed , Arzbes ,ArzTypeID,CurrenciesName,CurrencySymbol, TruckNumber ,SellsEmporiumName
FROM   AllAccount(@TypeDoc1, @TypeDoc2, @TypeDoc3, @TypeDoc4, @CustIDFrom, @CustIDTo, @DateFrom, @DateTo, @DateFromRemain, @YearIDFrom, @YearIDTo,@SellsMethodFrom  , @SellsMethodTo  ,
				         @SellsEmporiumFrom  , @SellsEmporiumTo,@DefaultDateActive )
						AS AllAccount_1  Left Outer JOIN Related Rele on AllAccount_1.ServerID = Rele.ServerID AND AllAccount_1.YearID = Rele.YearID AND 
                      AllAccount_1.FormID = Rele.ParentID AND AllAccount_1.Kind = Rele.Kind
					  AND AllAccount_1.FormItemID = Rele.FormItemID  
					   WHERE (AllAccount_1.kind = 2)
)

