CREATE  FUNCTION [dbo].[CashAccountOnCustomerID3] (@TypeDoc1 int =1 ,@TypeDoc2 int =-1,
						@TypeDoc3 int =-1 ,@TypeDoc4 int =1 ,
						@CustIDFrom  int = 0 , @CustIDTo int = 999999999 ,
						@DateFrom  Char(10) ='0001/01/01' , @DateTo Char(10) = '9999/99/99' ,
						@YearIDFrom  int = 0 , @YearIDTo int = 9999 ,
				@SellsMethodFrom  int = 0 , @SellsMethodTo int = 999999999 ,
				@SellsEmporiumFrom  int = 0 , @SellsEmporiumTo int = 999999999 )

RETURNS table  AS  
return (
SELECT	Forms.ServerID, Forms.YearID, Forms.FormID, Forms.FormNumber, Forms.FormDate,
case WHEN Forms.DefaultDate <'0001/01/01' THEN Forms.FormDate else Forms.DefaultDate end AS DefaultDate,Forms.DefaultDuration ,
--ISNULL(Forms.DefaultDate,Forms.FormDate) AS DefaultDate ,
       '0' AS checkNumber , 
		'0' AS checkDate , '' AS BankName , '' AS AccountNumber , 
		Forms.FormType, FormTypes.FormCaption, 
		Forms.CustomerID1 AS PersonID1, Forms.CustomerID2 AS PersonID2, Forms.CustomerID3 AS PersonID3, Forms.FomNote,Forms.AidInfoNo, 
		Forms.AidInfoDate,
		case FormTypes.bedbes WHEN 1 THEN Forms.Amount else 0 end AS bed ,
		case FormTypes.bedbes WHEN 0 THEN Forms.Amount else 0 end AS bes ,
		Forms.BudgetCode, Forms.ProjectID, Forms.CustomerName2 , 
		Forms.CustomerID2 AS DetailCustID , Forms.CustomerID1 AS CustIDForShow, 1 AS kind , 
		LookUps.Code, LookUps.Name , Forms.SellsMethod, SellsMethods.SellsMethodName, 
		Forms.RelatedID , 1 AS RelatedKind , FormTypes.Customer1DocType AS DocType
FROM	Forms  INNER JOIN
        SellsMethods ON Forms.SellsMethod = SellsMethods.SellsMethod INNER JOIN
		FormTypes ON Forms.FormType = FormTypes.FormType	LEFT OUTER JOIN
		LookUps ON Forms.PayTypes = LookUps.LookUpID
WHERE	(FormTypes.DisplayFormType in(0,7)) AND 
		(FormTypes.Customer1DocType in (@TypeDoc1 ,@TypeDoc2,@TypeDoc3,@TypeDoc4))And 
		(Forms.CustomerID3 between @CustIDFrom and @CustIDTo ) AND 
		(Forms.FormDate between @DateFrom and @DateTo ) AND
		(Forms.YearID between @YearIDFrom AND @YearIDTo )
		AND FormState<10
 AND (Forms.SellsMethod  BETWEEN @SellsMethodFrom AND @SellsMethodTo)
 AND (Forms.SellsEmporium  BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)

union all

SELECT	Forms.ServerID, Forms.YearID,Forms.FormID, Forms.FormNumber, Forms.FormDate,
case WHEN Forms.DefaultDate <'0001/01/01' THEN Forms.FormDate else Forms.DefaultDate end AS DefaultDate,Forms.DefaultDuration ,
--ISNULL(Forms.DefaultDate,Forms.FormDate) AS DefaultDate,
  '0' AS checkNumber , 
		'0' AS checkDate , '' AS BankName , '' AS AccountNumber , 
		Forms.FormType, FormTypes.FormCaption, 
		Forms.CustomerID1 AS PersonID1, Forms.CustomerID2 AS PersonID2, Forms.CustomerID3 AS PersonID3, Forms.FomNote,Forms.AidInfoNo, 
		Forms.AidInfoDate,
		case FormTypes.bedbes WHEN 0 THEN Forms.Amount else 0 end AS bed ,
		case FormTypes.bedbes WHEN 1 THEN Forms.Amount else 0 end AS bes ,
		Forms.BudgetCode, Forms.ProjectID, Forms.CustomerName2 , 
		Forms.CustomerID2 AS DetailCustID , Forms.CustomerID1 AS CustIDForShow , 1 AS kind, 
		LookUps.Code, LookUps.Name , Forms.SellsMethod, SellsMethods.SellsMethodName, 
		Forms.RelatedID , 1 AS RelatedKind, FormTypes.Customer1DocType AS DocType
FROM	Forms  INNER JOIN
        SellsMethods ON Forms.SellsMethod = SellsMethods.SellsMethod INNER JOIN
		FormTypes ON Forms.FormType = FormTypes.FormType LEFT OUTER JOIN
		LookUps ON Forms.PayTypes = LookUps.LookUpID
WHERE	(FormTypes.DisplayFormType in(0,7)) AND 
		(FormTypes.Customer2DocType in (@TypeDoc1 ,@TypeDoc2,@TypeDoc3,@TypeDoc4)) And 
		(Forms.CustomerID3 between @CustIDFrom and @CustIDTo ) AND 
		(Forms.FormDate between @DateFrom and @DateTo ) AND
		( Forms.YearID between @YearIDFrom AND @YearIDTo )
		AND FormState<10
AND (Forms.SellsMethod  BETWEEN @SellsMethodFrom AND @SellsMethodTo)
 AND (Forms.SellsEmporium  BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)
		
UNION ALL

SELECT	Forms.ServerID, Forms.YearID,Forms.FormID, Forms.FormNumber, Forms.FormDate,
case WHEN Forms.DefaultDate <'0001/01/01' THEN RIGHT( FormItems.CheckDate,10) else Forms.DefaultDate end AS DefaultDate,Forms.DefaultDuration ,
--ISNULL(Forms.DefaultDate,FormItems.CheckDate) AS DefaultDate,
 FormItems.CheckNumber, 
		RIGHT( FormItems.CheckDate,10), FormItems.BankName , FormItems.AccountNumber , Forms.FormType, 
		FormTypes.FormCaption, Forms.CustomerID1 AS PersonID1, 
		case WHEN (FormTypes.CustomerDetailsDocType<>0 ) THEN 
			 FormItems.CustomerID2
		else Forms.CustomerID2 end AS PersonID2 , Forms.CustomerID3 AS PersonID3,
		ISNULL(Forms.FomNote, '')+' '+ISNULL(FormItems.ItemNote, '') AS FomNote, Forms.AidInfoNo, Forms.AidInfoDate,
		case FormTypes.bedbes WHEN 1 THEN FormItems.ItemAmount - isnull(CashWage,0) else 0 end AS bed ,
		case FormTypes.bedbes WHEN 0 THEN FormItems.ItemAmount - isnull(CashWage,0) else 0 end AS bes ,
		case FormTypes.BudgetCodePosition
			WHEN 0 THEN 0
			WHEN 1 THEN FormItems.BudgetCode
			WHEN 2 THEN FormItems.BudgetCode
			WHEN 3 THEN Forms.BudgetCode
		else 0 end AS BudgetCode ,
		case FormTypes.BudgetCodePosition
			WHEN 0 THEN 0
			WHEN 1 THEN FormItems.ProjectID
			WHEN 2 THEN FormItems.ProjectID
			WHEN 3 THEN Forms.ProjectID
		else 0 end AS ProjectID ,
		case FormTypes.Customer2ActiveOnDetail
			WHEN 0 THEN Forms.CustomerName2
			WHEN 1 THEN null
			WHEN 2 THEN null
			WHEN 3 THEN Forms.CustomerName2
		else str(Forms.CustomerID2) end AS CustomerName2 , 
		FormItems.CustomerID2  AS DetailCustID ,Forms.CustomerID1 AS CustIDForShow ,  2 AS kind , 
		LookUps.Code, LookUps.Name , Forms.SellsMethod, SellsMethods.SellsMethodName, 
		FormItems.RelatedID , 2 AS RelatedKind, FormTypes.Customer1DocType AS DocType
FROM	Forms  INNER JOIN
        SellsMethods ON Forms.SellsMethod = SellsMethods.SellsMethod INNER JOIN
		FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
		FormItems ON Forms.FormID = FormItems.FormID and Forms.ServerID = FormItems.ServerID and Forms.YearID = FormItems.YearID  LEFT OUTER JOIN
		LookUps ON Forms.PayTypes = LookUps.LookUpID
WHERE	(case FormTypes.Customer1DocType 
			WHEN 13 THEN 
			case FormItems.CheckType  WHEN 0 THEN 6 else 2 end			
			WHEN 14 THEN 
			case FormItems.CheckType  WHEN 1 THEN -5 else 2 end		
			WHEN 15 THEN 
			case FormItems.CheckType  WHEN 0 THEN 6 else -5 end	
		else FormTypes.Customer1DocType  end  
			in (@TypeDoc1 ,@TypeDoc2,@TypeDoc3,@TypeDoc4)) AND
		(Forms.CustomerID3 between @CustIDFrom and @CustIDTo ) AND 
		(Forms.FormDate between @DateFrom and @DateTo ) AND
		( Forms.YearID between @YearIDFrom AND @YearIDTo )
		AND FormState<10
AND (Forms.SellsMethod  BETWEEN @SellsMethodFrom AND @SellsMethodTo)
 AND (Forms.SellsEmporium  BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)

union all

SELECT	Forms.ServerID, Forms.YearID,Forms.FormID, Forms.FormNumber, Forms.FormDate,
case WHEN Forms.DefaultDate <'0001/01/01' THEN RIGHT( FormItems.CheckDate,10) else Forms.DefaultDate end AS DefaultDate,Forms.DefaultDuration,
--ISNULL(Forms.DefaultDate,FormItems.CheckDate ) AS DefaultDate,
 FormItems.CheckNumber, RIGHT( FormItems.CheckDate,10) , 
		FormItems.BankName , FormItems.AccountNumber ,Forms.FormType, 
		FormTypes.FormCaption,Forms.CustomerID1 AS PersonID1, Forms.CustomerID2 AS PersonID2, Forms.CustomerID3 AS PersonID3, 
		ISNULL(Forms.FomNote, '')+' '+ISNULL(FormItems.ItemNote, '') AS FomNote, Forms.AidInfoNo, Forms.AidInfoDate,
		case FormTypes.bedbes WHEN 0 THEN FormItems.ItemAmount - isnull(CashWage,0) else 0 end AS bed ,
		case FormTypes.bedbes WHEN 1 THEN FormItems.ItemAmount - isnull(CashWage,0) else 0 end AS bes ,
		case FormTypes.BudgetCodePosition
			WHEN 0 THEN 0
			WHEN 1 THEN FormItems.BudgetCode
			WHEN 2 THEN FormItems.BudgetCode
			WHEN 3 THEN Forms.BudgetCode
		else 0 end AS BudgetCode ,
		case FormTypes.BudgetCodePosition
			WHEN 0 THEN 0
			WHEN 1 THEN FormItems.ProjectID
			WHEN 2 THEN FormItems.ProjectID
			WHEN 3 THEN Forms.ProjectID
		else 0 end AS ProjectID ,
		case FormTypes.Customer2ActiveOnDetail
			WHEN 0 THEN Forms.CustomerName2
			WHEN 1 THEN null
			WHEN 2 THEN null
			WHEN 3 THEN Forms.CustomerName2
		else null end AS CustomerName2 ,  
		case WHEN FormTypes.CustomerDetailsDocType=0 THEN 
			 Forms.CustomerID2
		else FormItems.CustomerID2 end   AS DetailCustID ,Forms.CustomerID1 AS CustIDForShow , 
		2 AS kind ,  LookUps.Code, LookUps.Name , Forms.SellsMethod, SellsMethods.SellsMethodName, 
		FormItems.RelatedID , 2 AS RelatedKind, FormTypes.Customer1DocType AS DocType
FROM	Forms  INNER JOIN
        SellsMethods ON Forms.SellsMethod = SellsMethods.SellsMethod INNER JOIN
		FormTypes ON Forms.FormType = FormTypes.FormType INNER JOIN
		FormItems ON Forms.FormID = FormItems.FormID and Forms.ServerID = FormItems.ServerID and Forms.YearID = FormItems.YearID  LEFT OUTER JOIN
		LookUps ON Forms.PayTypes = LookUps.LookUpID
WHERE	(case FormTypes.Customer2DocType 
			WHEN 13 THEN 
			case FormItems.CheckType  WHEN 0 THEN 6 else 2 end			
			WHEN 14 THEN 
			case FormItems.CheckType  WHEN 1 THEN -5 else 2 end		
			WHEN 15 THEN 
			case FormItems.CheckType  WHEN 0 THEN 6 else -5 end		
		else FormTypes.Customer2DocType  end  
			in (@TypeDoc1 ,@TypeDoc2,@TypeDoc3,@TypeDoc4))  AND 
		(Forms.CustomerID3 between @CustIDFrom and @CustIDTo ) AND 
		(Forms.FormDate between @DateFrom and @DateTo )AND
		( Forms.YearID between @YearIDFrom AND @YearIDTo )
		AND FormState<10
AND (Forms.SellsMethod  BETWEEN @SellsMethodFrom AND @SellsMethodTo)
 AND (Forms.SellsEmporium  BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)

----------------- براي زمانيكه از مشتري ديتيل استفاده ميشود ----------
UNION ALL 

