				@YearIDFrom  int = 0 , @YearIDTo int = 9999 ,
				@SellsMethodFrom  int = 0 , @SellsMethodTo int = 999999999 ,
				@SellsEmporiumFrom  int = 0 , @SellsEmporiumTo int = 999999999  )
				
RETURNS table AS  
return
(
SELECT  Recipts.ServerID, Recipts.YearID, Recipts.ReciptID, Recipts.ReciptNumber, Recipts.ReciptDate, 
case WHEN Recipts.DefaultDate <'0001/01/01' THEN Recipts.ReciptDate else Recipts.DefaultDate end AS DefaultDate,Recipts.DefaultDuration,
--ISNULL(Recipts.DefaultDate, Recipts.ReciptDate) AS DefaultDate, 
Recipts.ReciptType, ReciptTypes.ReciptCaption, ReciptTypes.ReciptCaption_L2, Recipts.PersonID3 AS PersonID3, Recipts.PersonID1, Recipts.PersonID2,
              Recipts.ReciptNote, 
              CASE WHEN EffectOnCustomer = 1 THEN Ri.TotalOutputPrice + Ri.TotalInputPrice + isnull(TaxValue, 0) - ISNULL(DeficitValue+DeficitValue2+DeficitValue4+DeficitValue3,0) ELSE 0 END AS bed, 
              CASE WHEN EffectOnCustomer = 2 THEN Ri.TotalInputPrice + Ri.TotalOutputPrice + isnull(TaxValue, 0) - ISNULL(DeficitValue+DeficitValue2+DeficitValue4+DeficitValue3,0) ELSE 0 END AS bes,
              Recipts.StoreID AS StoreIDForShow, 3 AS kind, LookUps.Code, LookUps.Name, Recipts.SellsMethod, 
              SellsMethods.SellsMethodName, Recipts.RelatedID, 3 AS RelatedKind, Ri.StuffCode, StuffCoding.c_StuffName, Ri.ControlCode, 
              Units.UnitName, Ri.OutputEntity - Ri.InputEntity AS Entity, Ri.OutputWeight - Ri.InputWeight AS Weight, 
              Ri.ItemNote, Ri.StuffDiameter, Ri.StuffSize, Ri.StuffAlloy, Ri.UnitSellPrice,
              StuffCoding.c_StuffTecInfo, Recipts.SellsEmporium, SellsEmporiumName
			          ,Recipts.AidNumber ,Recipts.AidDate


FROM    ReciptItems Ri INNER JOIN
              Recipts ON Ri.ReciptID = Recipts.ReciptID AND Ri.ServerID = Recipts.ServerID AND 
              Ri.YearID = Recipts.YearID INNER JOIN
              ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType INNER JOIN
              SellsMethods ON Recipts.SellsMethod = SellsMethods.SellsMethod INNER JOIN
              Customers ON Recipts.PersonID3 = Customers.CustID INNER JOIN
              StuffCoding ON Ri.StuffCode = StuffCoding.c_StuffCode  LEFT OUTER JOIN
              Units ON StuffCoding.n_UnitCode = Units.UnitCode Left Outer JOIN
              LookUps ON Recipts.SecondType = LookUps.LookUpID INNER JOIN
        SellsEmporiums SE ON Recipts.SellsEmporium = SE.SellsEmporium

WHERE   (EffectOnCustomer <> 0) AND (Recipts.ReciptState < 3)  
		   AND(@TypeDoc1 in (1,2,10))
           AND(Recipts.PersonID3  between @PersonID1From and @PersonID1To) 
		   AND(Recipts.ReciptDate  between @DateFrom and @DateTo )  
 		   AND(Recipts.YearID between @YearIDFrom AND @YearIDTo )	
           AND(Recipts.SellsMethod  BETWEEN @SellsMethodFrom AND @SellsMethodTo)
           AND(Recipts.SellsEmporium  BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)

UNION ALL	

SELECT Recipts.ServerID, Recipts.YearID, Recipts.ReciptID, Recipts.ReciptNumber, Recipts.ReciptDate, 
case WHEN Recipts.DefaultDate <'0001/01/01' THEN Recipts.ReciptDate else Recipts.DefaultDate end AS DefaultDate,recipts.DefaultDuration,		
---		ISNULL(Recipts.DefaultDate, Recipts.ReciptDate)AS DefaultDate,
		 Recipts.ReciptType, 
		ReciptTypes.ReciptCaption, ReciptTypes.ReciptCaption_L2, Recipts.PersonID3, Recipts.PersonID1, Recipts.PersonID2,
		Recipts.ReciptNote, 
					case WHEN EffectOnCustomer =1 THEN		
						ReciptsDeficits.DeficitAdd 
					else   ReciptsDeficits.DeficitDec  end AS bed , 
					case WHEN EffectOnCustomer =2 THEN		
						ReciptsDeficits.DeficitAdd  
					else  ReciptsDeficits.DeficitDec end AS bes  , 
					
					
		Recipts.StoreID AS StoreIDForShow, 3 AS kind, LookUps.Code, LookUps.Name, 
		Recipts.SellsMethod,SellsMethods.SellsMethodName, Recipts.RelatedID, 3 AS RelatedKind, 
		'' AS StuffCode, '' AS c_StuffName, 0 AS ControlCode, 
        '' AS UnitName,0  AS Entity, 0 AS Weight, ReciptsDeficits.DeficitNote,
        0.0 AS StuffDiameter, '' AS StuffSize, '' AS StuffAlloy, 0 AS UnitSellPrice,
        '' AS c_StuffTecInfo, Recipts.SellsEmporium, SellsEmporiumName
		        ,Recipts.AidNumber ,Recipts.AidDate


FROM	ReciptsDeficits INNER JOIN
                      Recipts ON ReciptsDeficits.ReciptID = Recipts.ReciptID AND ReciptsDeficits.ServerID = Recipts.ServerID AND 
                      ReciptsDeficits.YearID = Recipts.YearID INNER JOIN
                      ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType INNER JOIN
                      SellsMethods ON Recipts.SellsMethod = SellsMethods.SellsMethod INNER JOIN
                      Customers ON Recipts.PersonID3 = Customers.CustID Left Outer JOIN
			LookUps ON Recipts.SecondType = LookUps.LookUpID INNER JOIN
        SellsEmporiums SE ON Recipts.SellsEmporium = SE.SellsEmporium


WHERE	(EffectOnCustomer <> 0) AND (Recipts.ReciptState < 3) AND 
		(@TypeDoc1 in (1,2,10))

        AND (Recipts.PersonID3  between @PersonID1From and @PersonID1To) 
		AND (Recipts.ReciptDate  between @DateFrom and @DateTo )  
 		AND (Recipts.YearID between @YearIDFrom AND @YearIDTo )	
 AND (Recipts.SellsMethod  BETWEEN @SellsMethodFrom AND @SellsMethodTo)
 AND (Recipts.SellsEmporium  BETWEEN @SellsEmporiumFrom AND @SellsEmporiumTo)

                      
)  
   

