CREATE FUNCTION [dbo].[AllAccountItemOnPersonID3] ( @TypeDoc1 int =1 ,@TypeDoc2 int =-1,
				@TypeDoc3 int =-1 ,@TypeDoc4 int =-1 , 
				@CustIDFrom  int = 0 , @CustIDTo int = 999999999 ,
				@DateFrom  Char(10) ='0001/01/01' , @DateTo Char(10) = '9999/99/99',
				@DateFromRemain  Char(10) ='01/01/00' , 
				@YearIDFrom  int = 0 , @YearIDTo int = 9999,
				@SellsMethodFrom  int = 0 , @SellsMethodTo int = 999999999 ,
				@SellsEmporiumFrom  int = 0 , @SellsEmporiumTo int = 999999999)
RETURNS table  AS  
return (

SELECT  ServerID, YearID, ReciptID,ReciptNumber, ReciptDate, DefaultDate,DefaultDuration,
  	        '0' AS CheckNo, '0'  AS CheckDate, '' AS BankName, '' AS AccountNumber, ReciptType,
  	        ReciptCaption,PersonID1 ,PersonID2, PersonID3, ReciptNote, 0 AS AidNo, '' AS AidDate,
  	        bed, bes, 0 AS BudgetCode, 0 AS ProjectID, '' AS CuctomerName2, 0 AS DetailCustID,
  	        StoreIDForShow AS StoreID, kind, Code, Name ,SellsMethod, SellsMethodName, RelatedID,
  	        RelatedKind, 1 AS AnalizeType, 0 AS RelaID, StuffCode, c_StuffName, controlcode, UnitName,
  	        entity, Weight, ItemNote, StuffDiameter, StuffSize, UnitSellPrice 
		
FROM	ReciptItemsAccountOnPersonID3(@TypeDoc1 , @CustIDFrom  , @CustIDTo ,@DateFrom,@DateTo ,@YearIDFrom ,@YearIDTo,
				@SellsMethodFrom , @SellsMethodTo ,
				@SellsEmporiumFrom , @SellsEmporiumTo  ) ReciptItemsAccount

UNION ALL

SELECT  ServerID, YearID, FormID, FormNumber, FormDate, DefaultDate,DefaultDuration, checkNumber, checkDate, BankName,
            AccountNumber, FormType, FormCaption,PersonID1,PersonID2, PersonID3, FomNote, AidInfoNo, 
            AidInfoDate,bed, bes, BudgetCode, ProjectID , CustomerName2, DetailCustID,
            CustIDForShow, kind, Code, Name, SellsMethod,SellsMethodName, 
            RelatedID, RelatedKind, 1 AS AnalizeType, 0 AS RelaID ,'' AS  StuffCode,'' AS c_StuffName , 0 AS controlcode , 
		    '' AS UnitName,0.0 AS entity, 0.0 AS weight,FomNote AS ItemNote,0.0 AS StuffDiameter, '' AS StuffSize,0 AS UnitSellPrice  
FROM   CashAccountOnCustomerID3(@TypeDoc1 ,@TypeDoc2 ,@TypeDoc3 ,@TypeDoc4,
			  @CustIDFrom, @CustIDTo, @DateFrom, @DateTo, @YearIDFrom, @YearIDTo,
			  @SellsMethodFrom, @SellsMethodTo, @SellsEmporiumFrom, @SellsEmporiumTo) CashAccount

UNION ALL

------------------  مانده نقل از قبل ------------------

SELECT   max(ServerID), min(YearID) , 0 AS ReciptID, 0 AS FormNumber, @DateFromRemain AS FormDate,@DateFromRemain AS DefaultDate,0 AS DefaultDuration, '0' AS checkNumber,
		    '0' AS checkDate,'' AS BankName , '' AS AccountNumber  , 0 AS FormType,	'نقل از قبل' AS FormCaption, 
		    0 AS PersonID1, 0 AS PersonID2 , PersonID3,  'نقل از قبل' AS FomNote, '0' AS AidInfoNo, 
		    '0' AS AidInfoDate, Sum(bed) AS bed , Sum(bes) AS bes , 0 AS BudgetCode, 0 AS ProjectID,	
		    '' AS CustName2 ,  0 AS DetailCustID ,0 AS CustIDForShow ,0 AS kind , 0 AS  Code, '' AS  Name ,0 AS SellsMethod, 
		    '' AS SellsMethodName, 
		    -1 AS RelatedID , 0 AS RelatedKind,0 AS AnalizeType, 0 AS RelaID ,
		    '' AS  StuffCode,'' AS c_StuffName , 0 AS controlcode , 
		    '' AS UnitName,0.0 AS entity, 0.0 AS weight,'' AS ItemNote,0.0 AS StuffDiameter, '' AS StuffSize,
		    0 AS UnitSellPrice  

FROM     (
-------
SELECT   ServerID, YearID , PersonID3, bed,bes 
FROM     CashAccountOnCustomerID3(@TypeDoc1 ,@TypeDoc2 ,@TypeDoc3 ,@TypeDoc4 , @CustIDFrom  , 
		 @CustIDTo , '01/01/00', @DateFromRemain ,@YearIDFrom ,@YearIDTo ,
				@SellsMethodFrom   , @SellsMethodTo ,
				@SellsEmporiumFrom , @SellsEmporiumTo  ) CashAccount

UNION ALL

SELECT  ServerID, YearID , PersonID3, bed,bes 
		
FROM	ReciptItemsAccountOnPersonID3(@TypeDoc1 , @CustIDFrom  , @CustIDTo , '01/01/00', 
		@DateFromRemain ,@YearIDFrom ,@YearIDTo ,
				@SellsMethodFrom   , @SellsMethodTo ,
				@SellsEmporiumFrom , @SellsEmporiumTo 
		) ReciptItemsAccount

Union all
--------------------------- مانده ابتداي سال -----------------------
SELECT	@YearIDFrom AS YearID , 0 AS ServerID , CustID  AS PersonID3,
		Case WHEN firstBalance >0 THEN 
			firstBalance else 0 end  AS bed, 
		Case WHEN firstBalance <0 THEN 
			- firstBalance else 0 end  AS bes 
FROM	customers
WHERE	firstBalance <> 0 And
 		(CustID between @CustIDFrom and @CustIDTo ) AND 
 		(@TypeDoc1 in (1,2,10) or @TypeDoc2 in (1,2,10) or 
 			@TypeDoc3 in(1,2,10) or @TypeDoc4 in (1,2,10))
 		 AND (SellsEmporium between @SellsEmporiumFrom and @SellsEmporiumTo )
 			
UNION ALL 
-------------------------- مانده ابتداي سال بتفكيك سال مالي -----------------------
SELECT     YearID, 0 AS ServerID, PersonID1 AS PersonID3, CASE WHEN Rate > 0 THEN Rate ELSE 0 END AS bed, CASE WHEN Rate < 0 THEN - Rate ELSE 0 END AS bes
FROM         RemainsEarly
WHERE     (Rate <> 0) And
 		(PersonID1 between @CustIDFrom and @CustIDTo ) AND 
 		(@TypeDoc1 in (1,2,10) or @TypeDoc2 in (1,2,10) or 
 			@TypeDoc3 in(1,2,10) or @TypeDoc4 in (1,2,10)) And 
 			(YearID BETWEEN @YearIDFrom  AND @YearIDFrom )
 		 AND (SellsEmporium between @SellsEmporiumFrom and @SellsEmporiumTo )

) FirstBalance 
Group By PersonID3
)


