CREATE  FUNCTION [dbo].[ReciptItemsAccount] ( @TypeDoc1 int =1, 
				@PersonID1From  int = 0 , @PersonID1To int = 999999999 ,
				@DateFrom  Char(10) ='0001/01/01' , @DateTo Char(10) = '9999/99/99'  ,
				@YearIDFrom  int = 0 , @YearIDTo int = 9999 ,
				@SellsMethodFrom  int = 0 , @SellsMethodTo int = 999999999 ,
				@SellsEmporiumFrom  int = 0 , @SellsEmporiumTo int = 999999999  ,@DefaultDateActive Tinyint=0 )
				
RETURNS table  AS  
return
(
------------------------------------- مربوط به فروشنده و خریدار میباشد 
SELECT	Recipts.ServerID, Recipts.YearID, Recipts.ReciptID, Recipts.ReciptNumber, Recipts.ReciptDate, 
		case WHEN Recipts.DefaultDate <'0001/01/01' THEN Recipts.ReciptDate else Recipts.DefaultDate end AS DefaultDate,Recipts.DefaultDuration,
		Recipts.ReciptType, ReciptTypes.ReciptCaption, ReciptTypes.ReciptCaption_L2, StuffCoding.c_StuffName_L2,  Units.UnitName_l2,
		Case WHEN isnull(PersonID2Bed ,0) = 1 THEN  Recipts.PersonID2 
		else 
			Case isnull(Customers.SellsDefaultState,0)
				WHEN 0 THEN Recipts.PersonID1
				WHEN 1 THEN Recipts.PersonID2
			Else 
				Recipts.PersonID1  
			end 
		end AS PersonID1,
		--CASE isnull(Customers.SellsDefaultState, 0) 
		--	WHEN 0 THEN Recipts.PersonID1 
		--	WHEN 1 THEN Recipts.PersonID2 
		--	ELSE CASE WHEN isnull(PersonID2Bed, 0) = 0 THEN Recipts.PersonID1 ELSE Recipts.PersonID2 END 
		--END AS PersonID1,
		 Recipts.PersonID2, Recipts.ReciptNote, 
		case WHEN EffectOnCustomer =1 THEN
			case 
			 WHEN CommissionActive In (5) THEN 
			(UnitCommission * (ReciptItems.InputEntity + ReciptItems.OutputEntity))+ 
				(isnull(TaxValue,0)) - (ISNULL(isnull(DeficitValue,0)+isnull(DeficitValue2,0)+isnull(DeficitValue4,0)+isnull(DeficitValue3,0),0)) 

               WHEN CommissionActive Not In (1,2) THEN 
				(ReciptItems.TotalInputPrice) + (ReciptItems.TotalOutputPrice) + 
				(isnull(TaxValue,0)) - (ISNULL(isnull(DeficitValue,0)+isnull(DeficitValue2,0)+isnull(DeficitValue4,0)+isnull(DeficitValue3,0),0)) 

			else (UnitCommission * (ReciptItems.InputEntity + ReciptItems.OutputEntity)) 
			    +(ReciptItems.TotalInputPrice) + (ReciptItems.TotalOutputPrice) + 
				(isnull(TaxValue,0)) - (ISNULL(isnull(DeficitValue,0)+isnull(DeficitValue2,0)+isnull(DeficitValue4,0)+isnull(DeficitValue3,0),0))  end 
		else   0 end AS bed , 
		case WHEN EffectOnCustomer =2 THEN	
			case 
			 WHEN CommissionActive In (5) THEN 
                 (UnitCommission * (ReciptItems.InputEntity + ReciptItems.OutputEntity)) + 
				(isnull(TaxValue,0)) - (ISNULL(isnull(DeficitValue,0)+isnull(DeficitValue2,0)+isnull(DeficitValue4,0)+isnull(DeficitValue3,0),0)) 

             WHEN CommissionActive Not In (1,2) THEN 	
				(ReciptItems.TotalInputPrice) + (ReciptItems.TotalOutputPrice) + 
				(isnull(TaxValue,0)) - (ISNULL(isnull(DeficitValue,0)+isnull(DeficitValue2,0)+isnull(DeficitValue4,0)+isnull(DeficitValue3,0),0)) 

			else (UnitCommission * (ReciptItems.InputEntity + ReciptItems.OutputEntity))
			     + (ReciptItems.TotalInputPrice) + (ReciptItems.TotalOutputPrice) + 
				(isnull(TaxValue,0)) - (ISNULL(isnull(DeficitValue,0)+isnull(DeficitValue2,0)+isnull(DeficitValue4,0)+isnull(DeficitValue3,0),0)) end 
		else   0 end AS bes  ,


		Recipts.StoreID AS StoreIDForShow, 3 AS kind, LookUps.Code, LookUps.Name, Recipts.SellsMethod, 
		SellsMethods.SellsMethodName, Recipts.RelatedID, 3 AS RelatedKind, ReciptItems.StuffCode, 
		StuffCoding.c_StuffName, ReciptItems.ControlCode, Units.UnitName, 
		ReciptItems.InputEntity + ReciptItems.OutputEntity AS Entity, 
		ReciptItems.InputWeight + ReciptItems.OutputWeight AS Weight, 
		ReciptItems.ItemNote, ReciptItems.StuffDiameter, ReciptItems.StuffSize, ReciptItems.StuffAlloy, 
		ReciptItems.UnitSellPrice  ,ReciptItems.WaterCo,
		ISNULL(ReciptItems.DeficitValue, 0) + ReciptItems.DeficitValue2 + ReciptItems.DeficitValue4+ ReciptItems.DeficitValue3 AS DeficitValue,
		Recipts.PersonID3,TotalInputPrice+TotalOutputPrice AS TotalPrice ,TaxValue,
		StuffCoding.c_StuffTecInfo, ReciptItemID,

		case WHEN EffectOnCustomer =1 THEN	ISNULL((ReciptItems.ArzAmount),0) else   0 end AS Arzbed , 
		case WHEN EffectOnCustomer =2 THEN	ISNULL((ReciptItems.ArzAmount),0) else   0 end AS Arzbes,
		ISNULL(Recipts.ArzTypeID,0) AS ArzTypeID,Currencies.CurrenciesName,Currencies.CurrencySymbol,Recipts.RialsEqual ,ReciptItems.ArzRate,ReciptItems.CurrencyDiscounts
		,ReciptItems.MachineNo,ReciptItems.AidNumber AS AidNumberD,ReciptItems.AidDate AS AidDateD,ReciptItems.PersonID1 PersonID1D
		, UnitCommission,(InputEntity + OutputEntity) * UnitCommission AS TotallCommission, Recipts.SellsEmporium, SellsEmporiumName
		,Recipts.AidNumber ,Recipts.AidDate


FROM    ReciptItems INNER JOIN
        Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND 
        ReciptItems.YearID = Recipts.YearID INNER JOIN
        ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType INNER JOIN
        SellsMethods ON Recipts.SellsMethod = SellsMethods.SellsMethod INNER JOIN
        Customers ON Recipts.PersonID1 = Customers.CustID INNER JOIN
        StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode  LEFT OUTER JOIN
        Units ON StuffCoding.n_UnitCode = Units.UnitCode 		Left Outer JOIN
        LookUps ON Recipts.SecondType = LookUps.LookUpID
        LEFT OUTER JOIN Currencies ON ISNULL(Recipts.ArzTypeID,0) = Currencies.CurrenciesID INNER JOIN
        SellsEmporiums SE ON Recipts.SellsEmporium = SE.SellsEmporium
WHERE	(EffectOnCustomer in ( 1 , 2 )) AND (Recipts.ReciptState < 3) AND 
		(@TypeDoc1 in (1,2,10)) AND  	
		Case WHEN isnull(PersonID2Bed ,0) = 1 THEN  Recipts.PersonID2 
		else 
			Case isnull(Customers.SellsDefaultState,0)
				WHEN 0 THEN Recipts.PersonID1
				WHEN 1 THEN Recipts.PersonID2
			Else 
				Recipts.PersonID1  
			end 
		end    between @PersonID1From and @PersonID1To  And 
		(CASE WHEN @DefaultDateActive = 0 THEN Recipts.ReciptDate ELSE Recipts.DefaultDate END  between @DateFrom and @DateTo ) AND 
 		(Recipts.YearID between @YearIDFrom AND @YearIDTo )	AND 
 		(Recipts.SellsMethod between @SellsMethodFrom AND @SellsMethodTo )	AND  
 		(Recipts.SellsEmporium between @SellsEmporiumFrom AND @SellsEmporiumTo )	
--------------------------------- 
UNION ALL	
---------------------------------  مربوط به کسورات و اضافات در پایین فرم میباشد 
SELECT	Recipts.ServerID, Recipts.YearID, Recipts.ReciptID, Recipts.ReciptNumber, Recipts.ReciptDate, 
		case WHEN Recipts.DefaultDate <'0001/01/01' THEN Recipts.ReciptDate else Recipts.DefaultDate end AS DefaultDate,Recipts.DefaultDuration,
		Recipts.ReciptType, 
		Deficits.DeficitName+ ' ' + ReciptTypes.ReciptCaption AS ReciptCaption, ReciptTypes.ReciptCaption_L2,  '' c_StuffName_L2,  '' UnitName_l2,
		Case WHEN isnull(PersonID2Bed ,0) = 1 THEN  Recipts.PersonID2 
		else 
			Case isnull(Customers.SellsDefaultState,0)
				WHEN 0 THEN Recipts.PersonID1
				WHEN 1 THEN Recipts.PersonID2
			Else 
				Recipts.PersonID1  
			end 
		end AS PersonID1,
		--CASE isnull(Customers.SellsDefaultState, 0) 
		--	WHEN 0 THEN Recipts.PersonID1 
		--	WHEN 1 THEN Recipts.PersonID2 
		--	ELSE CASE 
		--		WHEN isnull(PersonID2Bed, 0) = 0 THEN Recipts.PersonID1 
		--		ELSE Recipts.PersonID2 END 
		--	END AS PersonID1, 
		Recipts.PersonID2, 
		Recipts.ReciptNote, 
		case WHEN EffectOnCustomer =1 THEN		
			ReciptsDeficits.DeficitAdd 
		else   ReciptsDeficits.DeficitDec  end AS bed , 

		case WHEN EffectOnCustomer =2 THEN		
			ReciptsDeficits.DeficitAdd  
		else  ReciptsDeficits.DeficitDec 
		end AS bes  , 
		Recipts.StoreID AS StoreIDForShow, 3 AS kind, LookUps.Code, LookUps.Name, 
		Recipts.SellsMethod,SellsMethods.SellsMethodName, Recipts.RelatedID, 3 AS RelatedKind, 
		'' AS StuffCode, '' AS c_StuffName, 0 AS ControlCode, '' AS UnitName,0.0  AS Entity, 0.0 AS Weight, 
		ReciptsDeficits.DeficitNote,0.0 AS StuffDiameter, '' AS StuffSize, '' AS StuffAlloy, 0 AS UnitSellPrice,
		0 AS WaterCo,0 AS DeficitValue,Recipts.PersonID3 ,0 AS TotalPrice ,0 AS TaxValue ,
		'' AS c_StuffTecInfo ,0 AS ReciptItemID,

		case WHEN EffectOnCustomer =1 THEN	ISNULL((ReciptsDeficits.ArzAmount),0) else   0 end AS Arzbed , 
		case WHEN EffectOnCustomer =2 THEN	ISNULL((ReciptsDeficits.ArzAmount),0) else   0 end AS Arzbes,
		ISNULL(Recipts.ArzTypeID,0) AS ArzTypeID,Currencies.CurrenciesName,Currencies.CurrencySymbol,Recipts.RialsEqual ,0 as ArzRate,0.0 as CurrencyDiscounts
		,'' MachineNo,'0.0' AidNumberD,''  AidDateD,0 PersonID1D,0 UnitCommission,0 AS TotallCommission, Recipts.SellsEmporium, SellsEmporiumName
        ,Recipts.AidNumber ,Recipts.AidDate

FROM	ReciptsDeficits INNER JOIN
		Recipts ON ReciptsDeficits.ReciptID = Recipts.ReciptID AND ReciptsDeficits.ServerID = Recipts.ServerID AND 
		ReciptsDeficits.YearID = Recipts.YearID INNER JOIN
		ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType INNER JOIN
		SellsMethods ON Recipts.SellsMethod = SellsMethods.SellsMethod INNER JOIN
		Customers ON Recipts.PersonID1 = Customers.CustID INNER JOIN
		Deficits ON ReciptsDeficits.DeficitID = Deficits.DeficitID LEFT OUTER JOIN
		LookUps ON Recipts.SecondType = LookUps.LookUpID
        LEFT OUTER JOIN Currencies ON ISNULL(Recipts.ArzTypeID,0) = Currencies.CurrenciesID INNER JOIN
        SellsEmporiums SE ON Recipts.SellsEmporium = SE.SellsEmporium

WHERE	(EffectOnCustomer in ( 1 , 2 ) ) AND (Recipts.ReciptState < 3) AND 
		(@TypeDoc1 in (1,2,10)) AND  
		Case WHEN isnull(PersonID2Bed ,0) = 1 THEN  Recipts.PersonID2 
		else 
			Case isnull(Customers.SellsDefaultState,0)
				WHEN 0 THEN Recipts.PersonID1
				WHEN 1 THEN Recipts.PersonID2
			Else 
				Recipts.PersonID1  
			end 
		end  between @PersonID1From and @PersonID1To  And 
		
		(CASE WHEN @DefaultDateActive = 0 THEN Recipts.ReciptDate ELSE Recipts.DefaultDate END  between @DateFrom and @DateTo ) AND 
 		(Recipts.YearID between @YearIDFrom AND @YearIDTo )	AND 
 		(Recipts.SellsMethod between @SellsMethodFrom AND @SellsMethodTo )	AND 
 		(Recipts.SellsEmporium between @SellsEmporiumFrom AND @SellsEmporiumTo )	
------------------------
UNION ALL
----------------------------- برای اضافه نمودن کسورات و اضافات خطی در گزارش و تراز عملکرد 
SELECT     Recipts.ServerID, Recipts.YearID, Recipts.ReciptID, Recipts.ReciptNumber, Recipts.ReciptDate, 
case WHEN Recipts.DefaultDate <'0001/01/01' THEN Recipts.ReciptDate else Recipts.DefaultDate end AS DefaultDate,Recipts.DefaultDuration,
---			ISNULL(Recipts.DefaultDate, Recipts.ReciptDate) AS DefaultDate, 
			Recipts.ReciptType, 
			ReciptTypes.ReciptCaption,  ReciptTypes.ReciptCaption_L2,  StuffCoding.c_StuffName_L2,  Units.UnitName_l2,
			ReciptTypesAccCode.CustID AS PersonID1, 
			Recipts.PersonID2, Recipts.ReciptNote, 
			case WHEN ReciptTypesAccCode.bedbes = 0 THEN 
				case  InfoKind 
					WHEN 0 THEN isnull(TaxValue, 0) 
					WHEN 1 THEN isnull(Portage, 0) 
					WHEN 2 THEN isnull(Article, 0) 
					WHEN 3 THEN isnull(Wage, 0) 
					WHEN 4 THEN isnull(Scoria, 0) 
					WHEN 5  THEN ISNULL(DeficitValue+DeficitValue2+DeficitValue4+DeficitValue3,0) 
					WHEN 20 THEN ISNULL(DeficitValue+DeficitValue2+DeficitValue4+DeficitValue3,0) 
				else 0 end 
			else 0 end AS bed 
			 ,
			case WHEN ReciptTypesAccCode.bedbes = 1 THEN 
				case  InfoKind 
					WHEN 0 THEN isnull(TaxValue, 0) 
					WHEN 1 THEN isnull(Portage, 0) 
					WHEN 2 THEN isnull(Article, 0) 
					WHEN 3 THEN isnull(Wage, 0) 
					WHEN 4 THEN isnull(Scoria, 0) 
					WHEN 5  THEN ISNULL(DeficitValue+DeficitValue2+DeficitValue4+DeficitValue3,0) 
					WHEN 20 THEN ISNULL(DeficitValue+DeficitValue2+DeficitValue4+DeficitValue3,0) 
				else 0 end 
			else 0 end AS bes, 

                      Recipts.StoreID AS StoreIDForShow, 3 AS kind, LookUps.Code, LookUps.Name, Recipts.SellsMethod, 
                      SellsMethods.SellsMethodName, Recipts.RelatedID, 3 AS RelatedKind, ReciptItems.StuffCode, StuffCoding.c_StuffName, ReciptItems.ControlCode, 
                      Units.UnitName, ReciptItems.InputEntity + ReciptItems.OutputEntity AS Entity, ReciptItems.InputWeight + ReciptItems.OutputWeight AS Weight, 
                      ReciptItems.ItemNote, ReciptItems.StuffDiameter, ReciptItems.StuffSize, ReciptItems.StuffAlloy, ReciptItems.UnitSellPrice  ,
                      ReciptItems.WaterCo,ISNULL(ReciptItems.DeficitValue, 0) + ReciptItems.DeficitValue2 + ReciptItems.DeficitValue4+ ReciptItems.DeficitValue3 AS DeficitValue
                       ,Recipts.PersonID3
                      ,TotalInputPrice+TotalOutputPrice AS TotalPrice ,TaxValue,
                       StuffCoding.c_StuffTecInfo, ReciptItemID,

		case WHEN EffectOnCustomer =1 THEN	ISNULL((ReciptItems.ArzAmount),0) else   0 end AS Arzbed , 
		case WHEN EffectOnCustomer =2 THEN	ISNULL((ReciptItems.ArzAmount),0) else   0 end AS Arzbes,
		ISNULL(Recipts.ArzTypeID,0) AS ArzTypeID,Currencies.CurrenciesName,Currencies.CurrencySymbol,Recipts.RialsEqual ,ReciptItems.ArzRate,ReciptItems.CurrencyDiscounts
		,ReciptItems.MachineNo,ReciptItems.AidNumber AS AidNumberD,ReciptItems.AidDate AS AidDateD,ReciptItems.PersonID1 PersonID1D
		, UnitCommission,(InputEntity + OutputEntity) * UnitCommission AS TotallCommission, Recipts.SellsEmporium, SellsEmporiumName
        ,Recipts.AidNumber ,Recipts.AidDate
FROM         ReciptItems INNER JOIN
                      Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND 
                      ReciptItems.YearID = Recipts.YearID INNER JOIN
                      ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType INNER JOIN
                      SellsMethods ON Recipts.SellsMethod = SellsMethods.SellsMethod INNER JOIN
                      Customers ON Recipts.PersonID1 = Customers.CustID INNER JOIN
                      StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode  LEFT OUTER JOIN
                      Units ON StuffCoding.n_UnitCode = Units.UnitCode 		Left Outer JOIN
			LookUps ON Recipts.SecondType = LookUps.LookUpID inner join 
			ReciptTypesAccCode on ReciptTypes.ReciptType = ReciptTypesAccCode.ReciptType
        LEFT OUTER JOIN Currencies ON ISNULL(Recipts.ArzTypeID,0) = Currencies.CurrenciesID INNER JOIN
        SellsEmporiums SE ON Recipts.SellsEmporium = SE.SellsEmporium

WHERE	 (EffectOnCustomer in ( 1 , 2 ) ) AND 
(Recipts.ReciptState < 3) AND 
	--	(@TypeDoc1 in (1,2,10)) AND  	
		  ReciptTypesAccCode.CustID between @PersonID1From and @PersonID1To  And 
		
 	(CASE WHEN @DefaultDateActive = 0 THEN Recipts.ReciptDate ELSE Recipts.DefaultDate END  between @DateFrom and @DateTo ) AND 
 		(Recipts.YearID between @YearIDFrom AND @YearIDTo )	AND 
 		(Recipts.SellsMethod between @SellsMethodFrom AND @SellsMethodTo )	AND  
