SELECT	Recipts.ServerID, Recipts.YearID, Recipts.ReciptID, Recipts.ReciptNumber, Recipts.ReciptDate, 
		case WHEN Recipts.DefaultDate <'0001/01/01' THEN Recipts.ReciptDate else Recipts.DefaultDate end AS DefaultDate,Recipts.DefaultDuration,
