			case WHEN CommissionActive Not In (1,2) THEN 
				ReciptItems.TotalInputPrice + ReciptItems.TotalOutputPrice + 
				isnull(TaxValue, 0) - ISNULL(DeficitValue+DeficitValue2+DeficitValue4+DeficitValue3,0) 
			else 
				UnitCommission * (ReciptItems.InputEntity + ReciptItems.OutputEntity)+
				ReciptItems.TotalInputPrice + ReciptItems.TotalOutputPrice + 
				isnull(TaxValue, 0) - ISNULL(DeficitValue+DeficitValue2+DeficitValue4+DeficitValue3,0)  
			end 
			ELSE 0 
		END AS bed, 
		CASE WHEN EffectOnCustomer3 = 2 THEN 
			case WHEN CommissionActive Not In (1,2) THEN 
				ReciptItems.TotalInputPrice + ReciptItems.TotalOutputPrice + isnull(TaxValue, 0) 
				- ISNULL(DeficitValue+DeficitValue2+DeficitValue4+DeficitValue3,0) 
			else 
				UnitCommission * (ReciptItems.InputEntity + ReciptItems.OutputEntity)+ 
