		ISNULL(Recipts.ArzTypeID,0) AS ArzTypeID,Currencies.CurrenciesName,Currencies.CurrencySymbol,Recipts.RialsEqual ,0.0 as ArzRate,0.0 AS CurrencyDiscounts
		,'' MachineNo,'0.0' AidNumberD,'' AidDateD,0 PersonID1D,0 UnitCommission,0 AS TotallCommission, Recipts.SellsEmporium, SellsEmporiumName
		        ,Recipts.AidNumber ,Recipts.AidDate

FROM	ReciptsDeficits INNER JOIN
		Recipts ON ReciptsDeficits.ReciptID = Recipts.ReciptID AND ReciptsDeficits.ServerID = Recipts.ServerID AND 
		ReciptsDeficits.YearID = Recipts.YearID INNER JOIN
		ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType INNER JOIN
		SellsMethods ON Recipts.SellsMethod = SellsMethods.SellsMethod INNER JOIN
		Customers ON Recipts.PersonID4 = Customers.CustID INNER JOIN
		Deficits ON ReciptsDeficits.DeficitID = Deficits.DeficitID LEFT OUTER JOIN
		LookUps ON Recipts.SecondType = LookUps.LookUpID left outer join 
		(	
			select distinct PrvYearID , ParentReciptID ,ServerID , ReciptType
			FROM	Recipts 
			where yearid between @YearIDFrom AND @YearIDTo and not (PrvYearID  is null)   
		)_Recipts on Recipts.ReciptID = _Recipts.ParentReciptID and Recipts.YearID = _Recipts.PrvYearID and 
					Recipts.ServerID = _Recipts.ServerID and ReciptTypes.CorrelateReciptType<>_Recipts.ReciptType
        LEFT OUTER JOIN Currencies ON ISNULL(Recipts.ArzTypeID,0) = Currencies.CurrenciesID INNER JOIN
        SellsEmporiums SE ON Recipts.SellsEmporium = SE.SellsEmporium
 
WHERE	EffectOnCustomer4 in ( 1 , 2 ) and 
		(Recipts.ReciptState < 3) AND 
		(@TypeDoc1 in (1,2,10)) AND 
		(Recipts.PersonID4 between @PersonID1From and @PersonID1To ) And 
		(CASE WHEN @DefaultDateActive = 0 THEN Recipts.ReciptDate ELSE Recipts.DefaultDate END  between @DateFrom and @DateTo ) AND 
 		(Recipts.YearID between @YearIDFrom AND @YearIDTo )	AND 
 		(Recipts.SellsMethod between @SellsMethodFrom AND @SellsMethodTo )	AND 
 		(Recipts.SellsEmporium between @SellsEmporiumFrom AND @SellsEmporiumTo )	
----------------------------------------
union all
----------------------------- برای اضافه نمودن کسورات و اضافات خطی در گزارش و تراز عملکرد 
SELECT distinct Recipts.ServerID, Recipts.YearID, Recipts.ReciptID, Recipts.ReciptNumber, Recipts.ReciptDate, 
 case WHEN Recipts.DefaultDate <'0001/01/01' THEN Recipts.ReciptDate else Recipts.DefaultDate end AS DefaultDate,
 Recipts.DefaultDuration,Recipts.ReciptType,
 ReciptTypes.ReciptCaption,  ReciptTypes.ReciptCaption_L2,  StuffCoding.c_StuffName_L2,  Units.UnitName_l2,
 case when ReciptTypesAccCode.CustID =-1 then Recipts.PersonID1 else 0 end AS PersonID1, 
 Recipts.PersonID2, Recipts.ReciptNote, 
 case WHEN  Recipts.portagebedbes=1 THEN 
  case  InfoKind 
   WHEN 1 THEN isnull(Portage, 0) 
  else 0 end 
 else 0 end AS bed 
  ,
 case WHEN  Recipts.portagebedbes=2 THEN 
  case  InfoKind 
   WHEN 1 THEN isnull(Portage, 0) 
  else 0 end 
 else 0 end AS bes, 
 Recipts.StoreID AS StoreIDForShow, 3 AS kind, LookUps.Code, LookUps.Name, Recipts.SellsMethod, 
            SellsMethods.SellsMethodName, Recipts.RelatedID, 3 AS RelatedKind, ReciptItems.StuffCode, 
 case  InfoKind WHEN 1 THEN 'کرایه حمل' else '' end  +'--'+ StuffCoding.c_StuffName as  c_StuffName,
 ReciptItems.ControlCode, 
                      '' as UnitName, 0.0 AS Entity, 0.0 AS Weight, 
                      ReciptItems.ItemNote, ReciptItems.StuffDiameter, ReciptItems.StuffSize, ReciptItems.StuffAlloy, 0 as UnitSellPrice  ,
                      ReciptItems.WaterCo,0 AS DeficitValue
                       ,0 as PersonID3
                      , 0 as  TotalPrice , 0 as TaxValue,
                       StuffCoding.c_StuffTecInfo, ReciptItemID,

  case WHEN  Recipts.portagebedbes=1 THEN ISNULL((ReciptItems.ArzPortage),0) else   0 end AS Arzbed , 
  case WHEN  Recipts.portagebedbes=2 THEN ISNULL((ReciptItems.ArzPortage),0) else   0 end AS Arzbes,
  ISNULL(Recipts.ArzTypeID,0) AS ArzTypeID,Currencies.CurrenciesName,Currencies.CurrencySymbol,Recipts.RialsEqual ,ReciptItems.ArzRate as ArzRate,ReciptItems.CurrencyDiscounts
  ,ReciptItems.MachineNo,ReciptItems.AidNumber AS AidNumberD,ReciptItems.AidDate AS AidDateD,ReciptItems.PersonID1 PersonID1D
  , UnitCommission,(InputEntity + OutputEntity) * UnitCommission AS TotallCommission, Recipts.SellsEmporium, SellsEmporiumName
        ,Recipts.AidNumber ,Recipts.AidDate

FROM  ReciptItems 
  INNER JOIN Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID 
   AND ReciptItems.YearID = Recipts.YearID 
  INNER JOIN ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType 
  INNER JOIN SellsMethods ON Recipts.SellsMethod = SellsMethods.SellsMethod 
  INNER JOIN  Customers ON Recipts.PersonID1 = Customers.CustID 
  INNER JOIN StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode  
  LEFT OUTER JOIN Units ON StuffCoding.n_UnitCode = Units.UnitCode   
  LEFT OUTER JOIN LookUps ON Recipts.SecondType = LookUps.LookUpID 
  INNER JOIN ReciptTypesAccCode on ReciptTypes.ReciptType = ReciptTypesAccCode.ReciptType
        LEFT OUTER JOIN Currencies ON ISNULL(Recipts.ArzTypeID,0) = Currencies.CurrenciesID INNER JOIN
        SellsEmporiums SE ON Recipts.SellsEmporium = SE.SellsEmporium

WHERE (EffectOnCustomer in (1,2)) AND 
  (Recipts.ReciptState < 3) AND
  (case when ReciptTypesAccCode.CustID =-1 then Recipts.PersonID1 else -1 end between @PersonID1From and @PersonID1To) And 
  (CASE WHEN @DefaultDateActive = 0 THEN Recipts.ReciptDate ELSE Recipts.DefaultDate END  between @DateFrom and @DateTo ) AND 
   (Recipts.YearID between @YearIDFrom AND @YearIDTo ) AND 
   (Recipts.SellsMethod between @SellsMethodFrom AND @SellsMethodTo ) AND  
   (Recipts.SellsEmporium between @SellsEmporiumFrom AND @SellsEmporiumTo ) 
  AND case when Recipts.portagebedbes <> 0 and isnull(ReciptTypesAccCode.CustID,0) <> 0 then 1 else 0 end =1


UNION ALL
