SELECT distinct R.ServerID, R.YearID, R.ReciptID, R.ReciptNumber, Reg.RegDate, case WHEN R.DefaultDate <'0001/01/01' THEN Reg.RegDate else R.DefaultDate end AS DefaultDate,
 R.DefaultDuration,R.ReciptType
 ,  'تعديلات بهاي کالا'   +'--'+ReciptTypes.ReciptCaption	 AS ReciptCaption
 , 'Product price adjustments --'+ReciptTypes.ReciptCaption_L2 AS ReciptCaption_L2 ,'Product price adjustments --'+ StuffCoding.c_StuffName_L2, '' UnitName_l2,

     Reg.CustID AS PersonID1,  R.PersonID2, R.ReciptNote, 
		case WHEN EffectOnCustomerReg = 1 THEN 	RegPrice else   0 end AS bed , 
		case WHEN EffectOnCustomerReg = 2 THEN	RegPrice else   0 end AS bes  ,
 R.StoreID AS StoreIDForShow, 3 AS kind, LookUps.Code, LookUps.Name, R.SellsMethod,  SellsMethods.SellsMethodName, R.RelatedID, 3 AS RelatedKind, RI.StuffCode, 
  'تعديلات بهاي کالا'   +'--'+ StuffCoding.c_StuffName as  c_StuffName, RI.ControlCode,'' as UnitName, 0.0 AS Entity, 0.0 AS Weight, 
 RI.ItemNote, RI.StuffDiameter, RI.StuffSize, RI.StuffAlloy, 0 as UnitSellPrice  , RI.WaterCo,0 AS DeficitValue ,0 as PersonID3  , 0 as  TotalPrice , 0 as TaxValue,
 StuffCoding.c_StuffTecInfo, RI.ReciptItemID,   0  AS Arzbed ,      0  AS Arzbes,  ISNULL(Reg.ArzTypeID,0) AS ArzTypeID,Currencies.CurrenciesName,Currencies.CurrencySymbol,
 R.RialsEqual ,RI.ArzRate as ArzRate,RI.CurrencyDiscounts  ,RI.MachineNo,RI.AidNumber AS AidNumberD,RI.AidDate AS AidDateD,RI.PersonID1 PersonID1D
, UnitCommission,(InputEntity + OutputEntity) * UnitCommission AS TotallCommission , R.SellsEmporium, SellsEmporiumName
        ,R.AidNumber ,R.AidDate

FROM  ReciptItems AS RI
  INNER JOIN Recipts AS R ON RI.ReciptID = R.ReciptID AND RI.ServerID = R.ServerID AND RI.YearID = R.YearID 
  INNER JOIN ReciptTypes ON R.ReciptType = ReciptTypes.ReciptType 
  INNER JOIN SellsMethods ON R.SellsMethod = SellsMethods.SellsMethod 
  INNER JOIN StuffCoding ON RI.StuffCode = StuffCoding.c_StuffCode  
  LEFT OUTER JOIN Units ON StuffCoding.n_UnitCode = Units.UnitCode   
  LEFT OUTER JOIN LookUps ON R.SecondType = LookUps.LookUpID 
  INNER JOIN ReciptsRegulates AS Reg ON RI.ReciptItemID = Reg.ReciptItemID AND RI.ReciptID = Reg.ReciptID AND RI.ServerID = Reg.ServerID AND RI.YearID = Reg.YearID
  INNER JOIN  Customers ON Reg.CustID = Customers.CustID INNER JOIN
        SellsEmporiums SE ON R.SellsEmporium = SE.SellsEmporium
  LEFT OUTER JOIN Currencies ON ISNULL(Reg.ArzTypeID,0) = Currencies.CurrenciesID 

WHERE   (EffectOnCustomerReg in (1,2)) 
 AND (R.ReciptState < 3) 
 AND ( Reg.CustID  between @PersonID1From and @PersonID1To) 
 And (CASE WHEN @DefaultDateActive = 0 THEN Reg.RegDate ELSE R.DefaultDate END  between @DateFrom and @DateTo ) 
 AND (R.YearID between @YearIDFrom AND @YearIDTo ) 
 AND (R.SellsMethod between @SellsMethodFrom AND @SellsMethodTo ) 
 AND (R.SellsEmporium between @SellsEmporiumFrom AND @SellsEmporiumTo )  

