CREATE VIEW YearCustomer 
AS
SELECT AllAcc.CustomerID1 AS PersonID1,  SUM(AllAcc.bed - AllAcc.bes) AS balance
FROM   dbo.AllAccount(10 ,-1 ,-1 ,-1 , DEFAULT  ,DEFAULT   ,'' , DEFAULT ,''   , DEFAULT   , DEFAULT
                        , DEFAULT   , DEFAULT, DEFAULT   , DEFAULT , DEFAULT) AS AllAcc 
GROUP BY AllAcc.CustomerID1

