CREATE FUNCTION [dbo].[AllAccountItem] ( @TypeDoc1 int =1 ,@TypeDoc2 int =-1,
				@TypeDoc3 int =-1 ,@TypeDoc4 int =-1 , 
				@CustIDFrom  int = 0 , @CustIDTo int = 999999999 ,
				@DateFrom  Char(10) ='0001/01/01' , @DateTo Char(10) = '9999/99/99',
				@DateFromRemain  Char(10) ='0001/01/00' , 
				@YearIDFrom  int = 0 , @YearIDTo int = 9999,
				@SellsMethodFrom  int = 0 , @SellsMethodTo int = 999999999 ,
				@SellsEmporiumFrom  int = 0 , @SellsEmporiumTo int = 999999999 ,@DefaultDateActive Tinyint=0)
RETURNS table  AS  
return (

SELECT  ServerID, YearID , ReciptID,ReciptNumber, ReciptDate,DefaultDate,DefaultDuration,
		 '0' AS CheckNo , '0'  AS CheckDate , 
		'' AS BankName , '' AS AccountNumber ,ReciptType, ReciptCaption,ReciptCaption_L2, c_StuffName_L2,  UnitName_l2,
		PersonID1,PersonID2, ReciptNote, AidNumber AS AidNo ,  AidDate ,
		bed, bes ,0 AS BudgetCode, 0 AS ProjectID, '' AS CuctomerName2 , 0 AS DetailCustID ,
		StoreIDForShow AS StoreID ,kind,  Code,  Name ,SellsMethod, SellsMethodName, 
		RelatedID , RelatedKind,0 AS doctype ,1 AS AnalizeType, 0 AS RelaID , StuffCode,c_StuffName , controlcode , 
		UnitName,entity,ReciptItemsAccount.weight,ItemNote,StuffDiameter,StuffSize,StuffAlloy,UnitSellPrice,
        WaterCo,DeficitValue,PersonID3 ,TotalPrice ,TaxValue,c_StuffTecInfo, ReciptItemID,Arzbed, Arzbes,ArzTypeID,CurrenciesName,CurrencySymbol, ArzRate,RialsEqual
		,CurrencyDiscounts,MachineNo,AidNumberD,  AidDateD, PersonID1D, UnitCommission, TotallCommission, SellsEmporium, SellsEmporiumName
		
		
		
FROM	ReciptItemsAccount(@TypeDoc1 , @CustIDFrom  , @CustIDTo ,@DateFrom,@DateTo ,@YearIDFrom ,@YearIDTo,
				@SellsMethodFrom   , @SellsMethodTo ,
				@SellsEmporiumFrom , @SellsEmporiumTo ,@DefaultDateActive  ) ReciptItemsAccount

UNION ALL

SELECT     ServerID, YearID, FormID, FormNumber, FormDate,  DefaultDate ,DefaultDuration, checkNumber, checkDate, BankName, AccountNumber, FormType
, FormCaption,FormCaption_L2, c_StuffName_L2,  UnitName_l2, CustomerID1, 
                      CustomerID2, FomNote, AidInfoNo, AidInfoDate, bed, bes, BudgetCode, ProjectID, CustomerName2, DetailCustID, CustIDForShow, kind, Code, Name, SellsMethod, 
                      SellsMethodName, RelatedID, RelatedKind, DocType
                      ,1 AS AnalizeType, 0 AS RelaID ,0 AS  StuffCode,'' AS c_StuffName , 0 AS controlcode , 
		'' AS UnitName,0.0 AS entity, 0.0 AS weight,FomNote AS ItemNote,0.0 AS StuffDiameter, '' AS StuffSize,'' AS StuffAlloy,
		0 AS UnitSellPrice ,
                      0 AS WaterCo,0 AS DeficitValue ,CustomerID3 AS PersonID3, 0 AS TotalPrice ,0 AS TaxValue,
                      '' AS c_StuffTecInfo,0 AS ReciptItemID,Arzbed, Arzbes,ArzTypeID,CurrenciesName,CurrencySymbol, ArzRate,0.0 RialsEqual
					  ,0.0 AS CurrencyDiscounts,'' MachineNo,'0.0' AidNumberD,''  AidDateD, PersonID1D,0 UnitCommission,0 TotallCommission
					  , SellsEmporium, SellsEmporiumName

FROM         CashAccount(@TypeDoc1 ,@TypeDoc2 ,@TypeDoc3 ,@TypeDoc4  
						, @CustIDFrom  , @CustIDTo,@DateFrom,@DateTo ,@YearIDFrom ,@YearIDTo,
				@SellsMethodFrom   , @SellsMethodTo ,
				@SellsEmporiumFrom , @SellsEmporiumTo ,@DefaultDateActive  ) CashAccount

UNION ALL

------------------  مانده نقل از قبل ------------------

SELECT   max(ServerID), min(YearID) , 0 AS ReciptID, 0 AS FormNumber, @DateFromRemain AS FormDate
           ,@DateFromRemain AS DefaultDate,0 AS DefaultDuration, '0' AS checkNumber,
		'0' AS checkDate,'' AS BankName , '' AS AccountNumber  , 0 AS FormType,	'نقل از قبل' AS FormCaption,'Quote from before' AS FormCaption_L2, '' c_StuffName_L2,  '' UnitName_l2, 
		 CustomerID1 , 0 AS PersonID2 , 'نقل از قبل'  AS FomNote, '0' AS AidInfoNo, 
		 '0' AS AidInfoDate, Sum(bed) AS bed , Sum(bes) AS bes , 0 AS BudgetCode, 0 AS ProjectID,	
		 '' AS CustName2 ,  0 AS DetailCustID ,0 AS CustIDForShow ,0 AS kind , 0 AS  Code, '' AS  Name ,0 AS SellsMethod, 
		 '' AS SellsMethodName, 
		-1 AS RelatedID , 0 AS RelatedKind, 0 AS doctype ,0 AS AnalizeType, 0 AS RelaID ,
		0 AS  StuffCode,'' AS c_StuffName , 0 AS controlcode , 
		'' AS UnitName,0.0 AS entity, 0.0 AS weight,'' AS ItemNote,0.0 AS StuffDiameter, '' AS StuffSize,'' AS StuffAlloy,
		0 AS UnitSellPrice  ,
        0 AS WaterCo,0 AS DeficitValue  ,0 AS PersonID3,0 AS TotalPrice,0 AS TaxValue,
        '' AS c_StuffTecInfo,0 AS ReciptItemID,ISNULL(Sum(Arzbed),0) AS Arzbed , ISNULL(Sum(Arzbes),0) AS Arzbes,
		max(ArzTypeID) AS ArzTypeID,max(CurrenciesName),max(CurrencySymbol),max(ArzRate) AS  ArzRate  ,0.0 RialsEqual,0.0 AS CurrencyDiscounts
		,'' MachineNo,'0.0' AidNumberD, '' AidDateD,0 PersonID1D,0 UnitCommission,0 TotallCommission
		,0 as SellsEmporium,'' as SellsEmporiumName



FROM     (
-------
SELECT   ServerID, YearID , CustomerID1 , bed,bes ,Arzbed, Arzbes,ArzTypeID,CurrenciesName,CurrencySymbol, ArzRate
FROM     CashAccount(@TypeDoc1 ,@TypeDoc2 ,@TypeDoc3 ,@TypeDoc4 , @CustIDFrom  , 
		 @CustIDTo , '01/01/00', @DateFromRemain ,@YearIDFrom ,@YearIDTo,
				@SellsMethodFrom   , @SellsMethodTo ,
				@SellsEmporiumFrom , @SellsEmporiumTo ,@DefaultDateActive   ) CashAccount

UNION ALL

SELECT  ServerID, YearID , PersonID1, bed,bes ,Arzbed, Arzbes,ArzTypeID,CurrenciesName,CurrencySymbol, ArzRate
		
FROM	ReciptItemsAccount(@TypeDoc1 , @CustIDFrom  , @CustIDTo , '01/01/00', 
		@DateFromRemain ,@YearIDFrom ,@YearIDTo ,
				@SellsMethodFrom   , @SellsMethodTo ,
				@SellsEmporiumFrom , @SellsEmporiumTo , @DefaultDateActive 
		) ReciptItemsAccount

Union all
--------------------------- مانده ابتداي سال -----------------------
SELECT	@YearIDFrom AS YearID , 0 AS ServerID , CustID ,
		Case WHEN firstBalance >0 THEN 
			firstBalance else 0 end  AS bed, 
		Case WHEN firstBalance <0 THEN 
			- firstBalance else 0 end  AS bes ,
		0 AS Arzbed ,0 AS Arzbes ,0 AS ArzTypeID,CurrenciesName,Currencies.CurrencySymbol,0 AS ArzRate
FROM	customers
    LEFT OUTER JOIN Currencies ON ISNULL(customers.ArzTypeID,0) = Currencies.CurrenciesID 	

WHERE	firstBalance <> 0 And
 		(CustID between @CustIDFrom and @CustIDTo ) AND 
 		(@TypeDoc1 in (1,2,10) or @TypeDoc2 in (1,2,10) or 
 			@TypeDoc3 in(1,2,10) or @TypeDoc4 in (1,2,10))
 		 AND (SellsEmporium between @SellsEmporiumFrom and @SellsEmporiumTo )
 			
UNION ALL 
-------------------------- مانده ابتداي سال بتفكيك سال مالي -----------------------
SELECT     YearID, 0 AS ServerID, PersonID1, CASE WHEN Rate > 0 THEN Rate ELSE 0 END AS bed, CASE WHEN Rate < 0 THEN - Rate ELSE 0 END AS bes
, CASE WHEN ArzRemain > 0 THEN  ISNULL(ArzRemain,0) ELSE 0 END AS Arzbed
, CASE WHEN ArzRemain < 0 THEN -ISNULL(ArzRemain,0) ELSE 0 END AS Arzbes,ArzTypeID,CurrenciesName,Currencies.CurrencySymbol,0 AS ArzRate
FROM         RemainsEarly
        LEFT OUTER JOIN Currencies ON ISNULL(RemainsEarly.ArzTypeID,0) = Currencies.CurrenciesID 
WHERE     (Rate <> 0) And
 		(PersonID1 between @CustIDFrom and @CustIDTo ) AND 
 		(@TypeDoc1 in (1,2,10) or @TypeDoc2 in (1,2,10) or 
 			@TypeDoc3 in(1,2,10) or @TypeDoc4 in (1,2,10)) And 
 			(YearID BETWEEN @YearIDFrom  AND @YearIDFrom )
 		 AND (SellsEmporium between @SellsEmporiumFrom and @SellsEmporiumTo )

) FirstBalance 
Group By CustomerID1
)
