CREATE FUNCTION GetCostOfStorage( @Remaining float, @TransferDate char(10),@CurrentDate char(10),@UnitSell money)
RETURNS float
AS
BEGIN
DECLARE @CurrentTime int
DECLARE @Time int
DECLARE @TransferDateM datetime
DECLARE @CurrentDateM datetime
SELECT  @TransferDateM=dbo.ShamsiToMiladi(@TransferDate)
SELECT  @CurrentDateM=dbo.ShamsiToMiladi(@CurrentDate)
SELECT  @CurrentTime= DATEDIFF(d, @TransferDateM, @CurrentDateM)

  if @Remaining<500000 set @Time=15  else  if @Remaining>500000 set @Time=60

  if @CurrentTime>@Time
  begin
    set @Remaining= @Remaining-ROUND(( @Remaining*2/@UnitSell) , 0, 1)
  end

RETURN (@Remaining)

END

