CREATE FUNCTION Fn_CostOfStorage ( @ReciptType int =25 )

RETURNS table  AS  
return 
(
SELECT ReciptID,ServerID,YearID,min(CostOfStorage) AS CostOfStorage FROM(

SELECT  TOP (100) PERCENT ReciptID,ServerID,YearID,
  ReUseAbleWeight /*-SUM(ReUseAbleWeight-dbo.GetCostOfStorage(ReUseAbleWeight, ReciptDate, TozinDate, UnitSellPrice)) 
        OVER(PARTITION by ReciptID ORDER BY TozinDate ROWS UNBOUNDED PRECEDING) */
		 AS CostOfStorage

FROM(
SELECT	Recipts.ReciptID,Recipts.ServerID,Recipts.YearID,ReciptItems.UnitSellPrice,Recipts.ReciptDate , TozinDate
		,InputEntity + OutputEntity/*-SUM(ISNULL(tozin.MachineFullWeight ,0)) OVER(PARTITION by Recipts.ReciptID ORDER BY TozinDate ROWS UNBOUNDED PRECEDING )*/ AS ReUseAbleWeight 
		 	
FROM	Recipts INNER JOIN
		ReciptItems on ReciptItems.ReciptID = Recipts.ReciptID and ReciptItems.YearID = Recipts.YearID  AND 
		ReciptItems.ServerID = Recipts.ServerID   INNER JOIN
		ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType Left Outer Join 
		(
				SELECT RelatedRecipts , SUM(MachineFullWeight)-SUM(MachineWeight) AS MachineFullWeight  , TozinDate
			FROM tozin
			WHERE RelatedRecipts IS NOT  NULL AND (ReciptType = @ReciptType ) and (tozin.TozinState <> 3) And (tozin.MachineFullWeight >0)
				group by  RelatedRecipts, TozinDate		
		) tozin on LTRIM(Recipts.ServerID) + '-' + LTRIM(Recipts.YearID) + '-' + LTRIM(ReciptItems.ReciptItemID) = RelatedRecipts  

WHERE  (Recipts.ReciptState <> 3) and 
		Recipts.ReciptType in (SELECT part FROM  SplitString ((
		SELECT RecallReciptTypes FROM Recipttypes WHERE recipttype = @ReciptType ) ,',') a  )
		AND (Recipts.YearID >=96)


		)Recipts_1

			ORDER BY TozinDate DESC 

			)Recipts_12

GROUP BY ReciptID,ServerID,YearID
)

