CREATE FUNCTION Fn_RelatedReciptItemsTozin ( @ReciptType int =25  ,  @UserID int=0 , @UserAdmin Tinyint =1 )

RETURNS table  AS  
return 
(
SELECT Recipts.ReciptID,LTRIM(Recipts.ServerID) + '-' + LTRIM(Recipts.YearID) + '-' + LTRIM(ReciptItems.ReciptItemID) AS RelatedNo,
 'شماره حواله'+ LTRIM(Recipts.ReciptNumber) + '-'  + Recipts.ReciptDate + '-'  + Customers.CustName AS RelatedName ,
 Recipts.ReciptType , ReciptItems.StuffCode , recipts.StoreID ,Recipts.StoreID2 , Stores2.c_StoreName AS StoreName2, Recipts.PersonID1 ,
 ReciptItems.InputEntity + OutputEntity AS Entity ,InputWeight + OutputWeight AS Weight  ,
 isnull(tozin.MachineFullWeight ,0) AS MachineFullWeight , 
 OutputEntity - isnull(tozin.MachineFullWeight ,0)- isnull(th.InputEntity,0) AS UseAbleWeight 
,Recipts.ReciptNumber,Recipts.ReciptDate , Customers.CustName,ReciptItems.ReciptItemID, 
 Recipts.PersonID2 ,Customers2.CustName AS CustName2
,OutputEntity -(ISNULL(tozin.MachineFullWeight ,0))- isnull(th.InputEntity,0)  AS ReUseAbleWeight 
, OutputEntity -(ISNULL(tozin.MachineFullWeight ,0))- isnull(th.InputEntity,0) AS CostOfStorage
,ReciptItems.YearID , Recipts.SecondType 
FROM Recipts INNER JOIN
ReciptItems on ReciptItems.ReciptID = Recipts.ReciptID and ReciptItems.YearID = Recipts.YearID  AND 
ReciptItems.ServerID = Recipts.ServerID  INNER JOIN 
Customers ON Recipts.PersonID1 = Customers.CustID INNER JOIN
ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType LEFT OUTER JOIN 
(SELECT RelatedRecipts , sum(MachineFullWeight)-sum(MachineWeight) AS MachineFullWeight  FROM tozin
where RelatedRecipts IS NOT  NULL AND (ReciptType = @ReciptType ) and (tozin.TozinState <> 3) And (tozin.MachineFullWeight >0)group by  RelatedRecipts
) tozin on LTRIM(Recipts.ServerID) + '-' + LTRIM(Recipts.YearID) + '-' + LTRIM(ReciptItems.ReciptItemID) = RelatedRecipts  INNER JOIN 
Customers AS Customers2 ON Recipts.PersonID2 = Customers2.CustID 


LEFT OUTER JOIN 
dbo.Fn_CostOfStorage ( @ReciptType  ) AS  Fn_CostOfStorage on Fn_CostOfStorage.ReciptID = Recipts.ReciptID and Fn_CostOfStorage.YearID = Recipts.YearID  AND 
Fn_CostOfStorage.ServerID = Recipts.ServerID LEFT OUTER JOIN Stores AS Stores2 on Stores2.n_StoreID =  Recipts.StoreID2

left outer join (SELECT RI172.preReciptItemID,RI172.YearID,sum(RI172.InputEntity) as InputEntity ,RI172.ServerID
    FROM recipts R172 inner join 
     ReciptItems RI172 on R172.ReciptID=RI172.ReciptID and R172.YearID=RI172.YearID and RI172.ServerID=R172.ServerID
 where R172.ReciptType=172
group by RI172.preReciptItemID,RI172.YearID,RI172.ServerID
) TH on TH.preReciptItemID =ReciptItems.ReciptItemID 
 and th.YearID=ReciptItems.YearID
 and th.ServerID =ReciptItems.ServerID




WHERE  (Recipts.ReciptState <> 3) and 

Recipts.ReciptType in (select part from  SplitString ((
select RecallReciptTypes from Recipttypes where recipttype = @ReciptType ) ,',') a  )
AND (Recipts.YearID >=96)


)
