CREATE FUNCTION Fn_RelatedReciptItemsTozin1 ( @ReciptType int =25  ,  @UserID int=0 , @UserAdmin Tinyint =1 , @DateIn datetime ='2020-03-29 14:06:59.000')

RETURNS table  AS  
return 
(
	SELECT	
			R.ReciptID, RI.ReciptItemID,RI.YearID,R.ReciptState, R.AidDate as reciptdate, R.ReciptType, R.ReciptNumber, R.ReciptNote,
			LTRIM(R.ServerID) + '-' + LTRIM(R.YearID) + '-' + LTRIM(RI.ReciptItemID) AS RelatedNo,
			'شماره حواله' + LTRIM(R.ReciptNumber) +'-'+ R.ReciptDate +'-'+ isnull(CT1.CustFirstName,'') +' '+ CT1.CustName AS RelatedName ,
			RI.StuffCode, SC.c_StuffName as StuffName, R.StoreID, 
			R.PersonID1, isnull(CT1.CustFirstName,'') +' '+ CT1.CustName as CustName, isnull(CT1.Mobile,'') +'-'+ isnull(CT1.Tel,'') as tel,
			R.PersonID2, isnull(CT2.CustFirstName,'') +' '+ CT2.CustName AS CustName2, SC.Carton,
			InputEntity + OutputEntity as entity, InputWeight + OutputWeight as Weight,
			round(isnull(TZ.MachineFullWeight,0) / SC.Carton,2)   as MachineFullWeight, 
			case when isnull(SC.Carton,0) = 0 then 0 else round (OutputEntity - round (isnull(TZ.MachineFullWeight,0) / SC.Carton,2),2) end  as UseAbleWeight,
			case when isnull(SC.Carton,0) = 0 then 0 else round (OutputEntity - round (isnull(TZ.MachineFullWeight,0) / SC.Carton,2),2)  end as ReUseAbleWeight
			,U.UseUnitID, UseUnitName, L.LookUpID, L.Name , CM.ID as MasirID, CM.MasirNote  as Masir, countE as ExitCount
		

	FROM				Recipts R 
			INNER JOIN	ReciptItems  RI  ON RI.ReciptID  = R.ReciptID and RI.YearID = R.YearID  AND RI.ServerID = R.ServerID  
			INNER JOIN 	Customers    CT1 ON R.PersonID1  = CT1.CustID 
			INNER JOIN  Customers    CT2 ON R.PersonID2  = CT2.CustID 
			INNER JOIN  ReciptTypes  RT  ON R.ReciptType = RT.ReciptType 
    		INNER JOIN  StuffCoding  SC  on RI.StuffCode = SC.c_StuffCode
			INNER JOIN  StuffGroups  SG  on SC.GroupID=SG.GroupID
			INNER JOIN  StuffCodingLinked SL on RI.StuffCode=SL.c_StuffCode
			INNER JOIN (
						select Max(SecondTypeItem) as SecondTypeItem, reciptitems.ReciptID,YearID,ServerID,min(StuffCode) as StuffCode, max(UseUnitID) as UseUnitID
						from ReciptItems 
						group by  reciptitems.ReciptID,YearID,ServerID 
						) RRI on SL.StuffCode=RRI.StuffCode and RI.ReciptID = RRI.ReciptID and RI.YearID = RRI.YearID
			INNER JOIN  UseUnits  U on RRI.UseUnitID =U.UseUnitID
			INNER JOIN  LookUps   L on RRI.SecondTypeItem =L.LookUpID
			INNER JOIN  CustomersMasir CM on R.MasirID=CM.ID and R.PersonID1= CM.PersonID1
			LEFT  JOIN 	(
							select tozin.RelatedRecipts, sum(tozin.MachineFullWeight) - sum(tozin.MachineWeight) as MachineFullWeight, tz2.cunt as countE
							from tozin inner join 
								(
									select  tz2.RelatedRecipts,count(tz2.RelatedRecipts) as Cunt
									from tozin as tz2
									group by   tz2.RelatedRecipts
								) as tz2 ON  tozin.RelatedRecipts = tz2.RelatedRecipts
							where tozin.RelatedRecipts IS NOT  NULL AND (tozin.ReciptType = @ReciptType) and (tozin.TozinState <> 3) 
							And (tozin.MachineFullWeight >0) and (tozin.ExitDate <= @DateIn )
							group by  tozin.RelatedRecipts ,tz2.cunt
						) TZ on LTRIM(R.ServerID) + '-' + LTRIM(R.YearID) + '-' + LTRIM(RI.ReciptItemID) = RelatedRecipts  

	WHERE		R.ReciptState <> 3
			AND SarFaslType   <> 3
			AND R.ReciptType in (select part from  SplitString ((select RecallReciptTypes from Recipttypes where recipttype = @ReciptType) ,',') a)
			AND R.YearID >= 1396
)
