       Max( CASE WHEN  Coefficient=3 THEN AmountRate ELSE 0.0 END) AS Amount3,
       Max( CASE WHEN  Coefficient=3 THEN PENote ELSE '' END) AS PENote3,

	   Max( CASE WHEN  Coefficient=4 THEN EffectName ELSE ''END) AS EffectName4,
       Max( CASE WHEN  Coefficient=4 THEN AmountRate ELSE 0.0 END) AS Amount4,
       Max( CASE WHEN  Coefficient=4 THEN PENote ELSE '' END) AS PENote4,

	   Max( CASE WHEN  Coefficient=5 THEN EffectName ELSE ''END) AS EffectName5,
       Max( CASE WHEN  Coefficient=5 THEN AmountRate ELSE 0.0 END) AS Amount5 ,
       Max( CASE WHEN  Coefficient=5 THEN PENote ELSE '' END) AS PENote5,

