       Max( CASE WHEN  Coefficient=6 THEN AmountRate ELSE 0.0 END) AS Amount6,
       Max( CASE WHEN  Coefficient=6 THEN PENote ELSE '' END) AS PENote6,

	   Max( CASE WHEN  Coefficient=7 THEN EffectName ELSE ''END) AS EffectName7,
       Max( CASE WHEN  Coefficient=7 THEN AmountRate ELSE 0.0 END) AS Amount7,
       Max( CASE WHEN  Coefficient=7 THEN PENote ELSE '' END) AS PENote7,

	   Max( CASE WHEN  Coefficient=8 THEN EffectName ELSE ''END) AS EffectName8,
       Max( CASE WHEN  Coefficient=8 THEN AmountRate ELSE 0.0 END) AS Amount8,
       Max( CASE WHEN  Coefficient=8 THEN PENote ELSE '' END) AS PENote8,

	   Max( CASE WHEN  Coefficient=9 THEN EffectName ELSE ''END) AS EffectName9,
       Max( CASE WHEN  Coefficient=9 THEN AmountRate ELSE 0.0 END) AS Amount9,
       Max( CASE WHEN  Coefficient=9 THEN PENote ELSE '' END) AS PENote9,

	   Max( CASE WHEN  Coefficient=10 THEN EffectName ELSE ''END) AS EffectName10,
       Max( CASE WHEN  Coefficient=10 THEN AmountRate ELSE 0.0 END) AS Amount10,
       Max( CASE WHEN  Coefficient=10 THEN PENote ELSE '' END) AS PENote10


