CREATE VIEW dbo.Vu_RelatedReciptTypes
AS
SELECT Recipts.ReciptID,LTRIM(Recipts.ServerID) + '-' + LTRIM(Recipts.YearID) + '-' + LTRIM(Recipts.ReciptID) AS RelatedNo,
 ReciptTypes.ReciptCaption + '-' + LTRIM(Recipts.ReciptNumber) + ' - ' + Recipts.ReciptDate + '-' + ISNULL
 (Recipts.ReciptNote, '')+ '-' + Customers.CustName AS RelatedName ,Recipts.ReciptType,Recipts.ReciptNumber,Recipts.ReciptDate,Recipts.YearID
FROM Recipts INNER JOIN
   Customers ON Recipts.PersonID1 = Customers.CustID INNER JOIN
   ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType
WHERE  (Recipts.ReciptState <> 3)
