CREATE VIEW dbo.Vu_RelatedReciptTypesItem
AS
SELECT   Ri.ID,  T.ReciptCaption + '-' + LTRIM(R.ReciptNumber) + ' - ' 
  + R.ReciptDate + '-' + ISNULL(R.ReciptNote, '') + '-' + C.CustName + ':' + Sc.c_StuffName AS RelatedName, 
                         R.ReciptID,R.ReciptType,R.ReciptNumber,R.ReciptDate,R.YearID ,ri.StuffCode ,Sc.c_StuffName
FROM            Recipts AS R INNER JOIN
                         Customers AS C ON R.PersonID1 = C.CustID INNER JOIN
                         ReciptTypes AS T ON R.ReciptType = T.ReciptType INNER JOIN
                         ReciptItems AS Ri ON R.ReciptID = Ri.ReciptID AND R.ServerID = Ri.ServerID AND R.YearID = Ri.YearID INNER JOIN
                         StuffCoding AS Sc ON Ri.StuffCode = Sc.c_StuffCode
WHERE        (R.ReciptState <> 3)
