CREATE FUNCTION GetControlCode (@StoreID int,@YearID  int ,@ReciptType int )
RETURNS bigint 
begin  
    RETURN(
SELECT   LTRIM(@StoreID)+LTRIM(@YearID)+RIGHT( '00000'+LTRIM(  MAX(ReciptItems.ControlCode)+1),5) AS ControlCode
FROM            ReciptItems INNER JOIN
                         Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID
WHERE        (ReciptItems.YearID = @YearID) AND (Recipts.StoreID = @StoreID) AND (Recipts.ReciptType = @ReciptType) 
            )  
end

