CREATE FUNCTION QuotedStr (@strinq  varchar(200)  )
RETURNS varchar(200) 
BEGIN
   declare @S Varchar(200)
    if CHARINDEX('/', @strinq )=0 
        set @S= @strinq 
   else set @S= ''''+@strinq+''''   
   RETURN(@S)  
END
