CREATE PROCEDURE [dbo].[GeneralReport] 
 @BaseParam VARCHAR(50),
 @AddParam VARCHAR(3),
 @Filter VARCHAR(100),
 @SliceCodeFlag BIT,
 @SliceCaptionFlag BIT,
 @EffectType INT, 
 @UnitePriceType INT,  
 @SqlWhere VARCHAR(1000),
 @AItemsFields VARCHAR(100)
 
AS
BEGIN

DECLARE @SqlSelect    VARCHAR(4000)
DECLARE @SqlJoin      VARCHAR(1000)
DECLARE @SqlGroup     VARCHAR(4000)
DECLARE @SqlTopic     VARCHAR(1000)
DECLARE @SqlFinal     VARCHAR(8000)
DECLARE @SqlInput     VARCHAR(4000)

DECLARE @OldCode      VARCHAR(1000)
DECLARE @SliceCode    VARCHAR(1000)
DECLARE @SliceCaption NVARCHAR(1000)
 
DECLARE @ID           VARCHAR(12)
DECLARE @fldName      VARCHAR(200)
DECLARE @AliasName    VARCHAR(50)
DECLARE @tblName      VARCHAR(30)
DECLARE @TopicName    VARCHAR(200)
DECLARE @Current      VARCHAR(50) 
DECLARE @JoinFldName  VARCHAR(50)
DECLARE @CaptionName  NVARCHAR(50)



DECLARE @AddStuffParam    BIT
DECLARE @AddCustParam1    BIT
DECLARE @AddCustParam2    BIT
DECLARE @AddCustParam3    BIT
DECLARE @AddCustParamItem BIT

--DECLARE @SQLStuffTecInfoActive varchar(20)
 
SET @SqlSelect    = ''
SET @SqlJoin      = ''
SET @SqlGroup     = ''
SET @SqlTopic     = ''
SET @SqlFinal     = ''
SET @SqlInput     = ''
SET @OldCode      = ''
SET @SliceCode    = ''
SET @SliceCaption = ''
--SET @SQLStuffTecInfoActive = ''

SET @AddStuffParam    = 0
SET @AddCustParam1    = 0
SET @AddCustParam2    = 0
SET @AddCustParam3    = 0
SET @AddCustParamItem = 0
--Added
DECLARE @SQLSUM NVARCHAR(1000);
SET @SQLSUM = '';

DECLARE @SqlView VARCHAR(8000)
SET @SqlView = '';
------------------------------------------------------------------------------------------------------------------------------------------
DECLARE @SqlViewFilter2 VARCHAR(8000)
SET @SqlViewFilter2 = '';
------------------------------------------------------------------------------------------------------------------------------------------

--Added    
DECLARE @ActiveSellPrice2  int
SELECT   @ActiveSellPrice2=ActiveSellPrice2     FROM            Config

SET @Current = @BaseParam +','+ @AddParam 

DECLARE QAnalize CURSOR 
    FOR(
	     SELECT Util.Analyze.ID,TableName,REPLACE( FieldName,'ReciptItems','R'),AliasName ,JoinFieldName,CaptionName,TopicName
	     FROM Util.Analyze  INNER JOIN SplitString(@Current,',') SP ON SP.part =  Util.Analyze.ID 
	    ); 

OPEN QAnalize 
FETCH FROM QAnalize INTO @ID, @tblName, @fldName, @AliasName, @JoinFldName, @CaptionName, @TopicName ;
WHILE @@FETCH_STATUS = 0 
BEGIN
     
       SET @SqlGroup = @SqlGroup +  ISNULL(@AliasName,@tblName) +'.'+@JoinFldName  +' , '+ ISNULL(@AliasName,@tblName) +'.'+ @TopicName +','

       SET @SqlSelect = @SqlSelect + ' ISNULL(CAST('+ ISNULL(@AliasName,@tblName) +'.'+@JoinFldName +' AS VARCHAR(100)),0) +''-''+ '
       SET @SqlTopic = @SqlTopic + ' ISNULL(CAST('+ISNULL(@AliasName,@tblName) +'.'+ @TopicName +' AS VARCHAR(100)),''--'') +''-''+ ' 
       
       
       IF (@SliceCaptionFlag  = 1)
       BEGIN
          SET @SliceCaption  =  @SliceCaption +  'ISNULL(CAST(' +ISNULL(@AliasName,@tblName) + '.' + @TopicName + ' AS NVARCHAR(100)),'' '') AS'+'['+'عنوان '+ @CaptionName +'],'      
       END
       
       IF (@SliceCodeFlag = 1)
       BEGIN 
          SET @SliceCode = @SliceCode + '  ISNULL(CAST('+ ISNULL(@AliasName,@tblName) +'.'+@JoinFldName +' AS VARCHAR(100)),0) '+ ' AS ['+@CaptionName+'], '
       END
            
          --AddStuffGroup
          IF (@ID = 4)
          BEGIN
             IF(@AddStuffParam = 1)  GOTO FetchState;
             ELSE  SET @AddStuffParam = 1          
          END
          IF ((@ID = 2) AND (@AddStuffParam = 0)) 
          BEGIN
               SET @AddStuffParam = 1
               SET @SqlJoin = @SqlJoin + ' INNER JOIN StuffCoding ON StuffCoding.c_StuffCode=R.StuffCode ' 
          END
          --AddStuffGroup
          
          
          --AddCustomerGroup1
          IF (@ID = 9)
          BEGIN
             IF(@AddCustParam1 = 1)  GOTO FetchState;
             ELSE  SET @AddCustParam1 = 1          
          END
          IF (( @ID in( 5 , 22 ,23 )) AND (@AddCustParam1 = 0)) 
          BEGIN
               SET @AddCustParam1 = 1
               SET @SqlJoin = @SqlJoin + ' INNER JOIN Customers C1 ON C1.CustID = R.PersonID1 ' 
          END
          --AddCustomerGroup1
       
          
          --AddCustomerGroup2
          IF (@ID = 10)
          BEGIN
             IF(@AddCustParam2 = 1)  GOTO  FetchState;
             ELSE  SET @AddCustParam2 = 1          
          END
          IF (( @ID = 6) AND (@AddCustParam2 = 0)) 
          BEGIN
               SET @AddCustParam2 = 1
               SET @SqlJoin = @SqlJoin + ' INNER JOIN Customers C2 ON C2.CustID = R.PersonID2 ' 
          END
          --AddCustomerGroup2
          
          
          --AddCustomerGroup3
          IF (@ID = 11)
          BEGIN
             IF(@AddCustParam3 = 1)  GOTO  FetchState;
             ELSE  SET @AddCustParam3 = 1          
          END
          IF (( @ID = 7) AND (@AddCustParam3 = 0)) 
          BEGIN
               SET @AddCustParam3 = 1
               SET @SqlJoin = @SqlJoin + ' INNER JOIN Customers C3 ON C3.CustID = R.PersonID3 ' 
          END
          --AddCustomerGroup3
          
          
          --AddCustomerGroupItem
          IF (@ID = 12)
          BEGIN
             IF(@AddCustParamItem = 1)  GOTO  FetchState;
             ELSE  SET @AddCustParamItem = 1          
          END
          IF (( @ID = 8) AND (@AddCustParamItem = 0)) 
          BEGIN
               SET @AddCustParamItem = 1
               SET @SqlJoin = @SqlJoin + ' INNER JOIN Customers CItem ON CItem.CustID = R.PersonID1D ' 
          END
          --AddCustomerGroupItem

   
       SET @SqlJoin = @SqlJoin + ' INNER JOIN ' + @tblName + ' '+ISNULL(@AliasName ,'')+ ' ON ' +'ISNULL('+ @fldName +',0)'+' = ' + ISNULL(@AliasName,@tblName) +'.'+@JoinFldName
       
       FetchState: FETCH NEXT FROM QAnalize INTO @ID, @tblName,@fldName,@AliasName ,@JoinFldName ,@CaptionName,@TopicName ;

END

CLOSE QAnalize ;	
DEALLOCATE QAnalize ; 


--IF (@ActiveInput = 1 )
  IF(@EffectType in (2,5,6,  8  ))
  BEGIN 
	SET @SqlInput =   ',SUM(R.InputEntity) AS EntityInput, SUM(R.InputWeight) AS WeightInput, ' ;

	IF(@UnitePriceType in (1,3))
	SET @SqlInput = @SqlInput
					+ 'CASE WHEN SUM(R.InputEntity) = 0 THEN 0 ELSE ROUND(SUM(R.TotalInputPrice)  ' 
					+ '/ SUM(R.InputEntity),0) END AS PriceUnitInEntity,' ;

	IF (@UnitePriceType in (2,3))
	SET @SqlInput = @SqlInput
					+ 'CASE WHEN SUM(R.InputWeight) = 0 THEN 0 ELSE ROUND(SUM(R.TotalInputPrice)  '
					+ '/ SUM(R.InputWeight),0) END AS PriceUnitInWeight,';
					
	SET @SqlInput = @SqlInput+ 'cast(SUM(R.TotalInputPrice) as decimal(38,0) )  AS PriceTotalInput   ' ;
	SET @SQLSUM = @SQLSUM +'SUM(EntityInput) AS EntityInput, SUM(WeightInput) AS WeightInput, cast(SUM(PriceTotalInput) as decimal(38,0) )  AS PriceTotalInput'+',' 
					
END
--IF (@ActiveOutput = 1 )
IF (@EffectType in (4,6,  8  ))
BEGIN 
	SET @SqlInput = @SqlInput+ ',SUM(R.OutputEntity) AS EntityOutput, SUM(R.OutputWeight) AS WeightOutput, ' ;
	IF (@UnitePriceType in (1,3))
	SET @SqlInput = @SqlInput
					+ 'CASE WHEN SUM(R.OutputEntity) =0 THEN 0 ELSE ROUND(SUM(R.TotalOutputPrice ) '
					+ '/ SUM(R.OutputEntity),0) END AS PriceUnitOutEntity,' ;

	IF (@UnitePriceType in (2,3))
	SET @SqlInput = @SqlInput					
					+ 'CASE WHEN SUM(R.OutputWeight) =0 THEN 0 ELSE ROUND(SUM(R.TotalOutputPrice ) '
					+ '/ SUM(R.OutputWeight),0) END AS PriceUnitOutWeight,' ;



	SET @SqlInput = @SqlInput
					+ 'cast(SUM(R.TotalOutputPrice) as decimal(38,0) ) AS PriceTotalOutput  ' ;
	SET @SQLSUM = @SQLSUM +'SUM(EntityOutput) AS EntityOutput, SUM(WeightOutput) AS WeightOutput, cast( SUM(PriceTotalOutput) as decimal(38,0) )  AS PriceTotalOutput'+',' 


END 					
IF (@EffectType in (6))
BEGIN 
	SET @SqlInput = @SqlInput
				+ ',SUM(R.InputEntity-R.OutputEntity) AS Entity, '
				+ 'SUM(R.InputWeight - R.OutputWeight) AS Weight,'
	IF (@UnitePriceType in (1,3))
	SET @SqlInput = @SqlInput
                + 'CASE WHEN SUM(R.InputEntity - R.OutputEntity)=0 THEN 0 ELSE ROUND(SUM(R.TotalInputPrice -R.TotalOutputPrice) '                
                + '/ SUM(R.InputEntity-R.OutputEntity),0) END AS UnitEntityPrice, '

	IF (@UnitePriceType in (2,3))
	SET @SqlInput = @SqlInput	
                + 'CASE WHEN SUM(R.InputWeight - R.OutputWeight)=0 THEN 0 ELSE ROUND(SUM(R.TotalInputPrice -R.TotalOutputPrice) '                
                + '/ SUM(R.InputWeight-R.OutputWeight),0) END AS UnitWeightPrice, '
                
	SET @SqlInput = @SqlInput
					+ 'SUM(R.TotalInputPrice-R.TotalOutputPrice) AS Price  ' ;
	SET @SQLSUM = @SQLSUM +'SUM(Entity) AS Entity, SUM(Weight) AS Weight, SUM(Price) AS Price'+',' 				
END 
IF (@ActiveSellPrice2 = 1)
BEGIN
	SET @SqlInput = @SqlInput
					+ ',SUM(R.TotallSellPrice) AS PriceArzeshAfzode  ' ;
	SET @SQLSUM = @SQLSUM +'SUM(PriceArzeshAfzode) AS PriceArzeshAfzode'+',' 				
END

 SET @SqlSelect = LEFT (@SqlSelect , LEN(@SqlSelect)-5)
 SET @SqlTopic = LEFT  (@SqlTopic, LEN(@SqlTopic)-5) 
 SET @SqlGroup = @SqlGroup + @SqlTopic +','+ @SqlSelect 
 SET @SQLSUM = LEFT( @SQLSUM ,LEN(@SQLSUM)-1) 
 
 
 IF (@AddParam  <> '')
 BEGIN
	SELECT @OldCode = @OldCode + 'Cast(' + REPLACE( FieldName,'ReciptItems','R') +' AS VARCHAR(20)) +''-''+'      
	FROM Util.Analyze  INNER JOIN SplitString(@BaseParam,',') SP ON SP.part = Util.Analyze.ID 

	SET @OldCode   =  LEFT (@OldCode, (LEN(@OldCode) - 5))  ; 
	
	IF (@Filter <> '') 
	BEGIN
		IF (@SqlWhere = '')  
			SET @SqlWhere =  ' WHERE '+ @OldCode +'='''+@Filter+' '''	
		ELSE		
			SET @SqlWhere =  @SqlWhere +' AND '+ @OldCode +'='''+@Filter+' '''		
	END;	
 END;

--Added QAnalizeItems
DECLARE @SqlGroupItem NVARCHAR(1000)
DECLARE @SqlSelectItem NVARCHAR(1000)

DECLARE @IDItem INT
DECLARE @fldNameItem NVARCHAR(50)
DECLARE @DispalyNameItem NVARCHAR(50)

SET @SqlGroupItem = ''
SET @SqlSelectItem = ''

SET @Current = @AItemsFields

DECLARE QAnalizeItems CURSOR 
    FOR(
	     SELECT Util.AnalyzeItems.ID,REPLACE( FieldName,'ReciptItems','R') FieldName, DisPlayName
         FROM Util.AnalyzeItems  INNER JOIN SplitString(@Current,',') SP ON SP.part =  Util.AnalyzeItems.ID 
	    ); 

OPEN QAnalizeItems 
FETCH FROM QAnalizeItems INTO @IDItem, @fldNameItem, @DispalyNameItem ;
WHILE @@FETCH_STATUS = 0 
BEGIN  
	   IF( NOT((@fldNameItem LIKE 'SUM(%)')OR(@fldNameItem LIKE 'AVG(%)')OR(@fldNameItem LIKE 'MIN(%)')
	           OR(@fldNameItem LIKE 'MAX(%)')OR(@fldNameItem LIKE 'COUNT(%)')) )
	   BEGIN
         SET @SqlGroupItem = @SqlGroupItem + @fldNameItem +','
       END
       SET @SqlSelectItem = @SqlSelectItem + 'ISNULL(CAST('+ @fldNameItem +' AS VARCHAR(100)), 0) AS ['+ @DispalyNameItem +'],'
  
       FETCH NEXT FROM QAnalizeItems INTO @IDItem, @fldNameItem, @DispalyNameItem ;
END

CLOSE QAnalizeItems ;	
DEALLOCATE QAnalizeItems ; 
--Added QAnalizeItems

--if (SELECT StuffTecInfoActive From config)=1
  --IF  (@AddStuffParam = 1) 
    --SET @SQLStuffTecInfoActive =',StuffCoding.c_StuffTecInfo'

SET  @SqlFinal = 'SELECT '+ @SqlSelectItem+ @SliceCode+ @SliceCaption+ @SqlSelect +' As AllColumn , '+ @SqlTopic +' AS AllCaption ' 
				--+@SQLStuffTecInfoActive
				+ @SqlInput 
			--	+ ' FROM Recipts INNER JOIN'	 
				+ ' FROM ReciptItems_Stock_Oper R '	 

				
DECLARE @Count INT;

				 
SET @SqlFinal = @SqlFinal --+ ' R ON Recipts.ReciptID=R.ReciptID AND Recipts.ServerID=R.ServerID AND Recipts.YearID=R.YearID INNER JOIN'
               --+ CHAR(13) + ' ReciptTypes ON Recipts.ReciptType=ReciptTypes.ReciptType '
               + CHAR(13) + ' LEFT OUTER JOIN LookUps AS L_ST ON R.SecondType = L_ST.LookUpID '
               + CHAR(13) + @SqlJoin 
               + CHAR(13) + @SqlWhere
               + CHAR(13) + ' GROUP BY '+ @SqlGroupItem + @SqlGroup --+@SQLStuffTecInfoActive

EXEC('IF EXISTS (SELECT * FROM sysobjects WHERE id = object_id( N''[dbo].[view_GeneralReport]'') AND OBJECTPROPERTY(id, N''IsView'') = 1)'
                 +' DROP view [dbo].[view_GeneralReport]')

--create view LowerCase
SET @SqlView =  'create view [dbo].[view_GeneralReport]  AS ' 
               + CHAR(13) + 'SELECT ''جمع:''AS [ ],' +  @SQLSUM + ' FROM (' 
               + CHAR(13) + @SqlFinal +') AS Temp'

------------------------------------------------------------------------------------------------------------------------------------------
EXEC('IF EXISTS (SELECT * FROM sysobjects WHERE id = object_id( N''[dbo].[view_GeneralReportFilter2]'') AND OBJECTPROPERTY(id, N''IsView'') = 1)'
                 +' DROP view [dbo].[view_GeneralReportFilter2]')

--create view LowerCase
SET @SqlViewFilter2 =  'create view [dbo].[view_GeneralReportFilter2]  AS ' + @SqlFinal 
------------------------------------------------------------------------------------------------------------------------------------------


--PRINT @SqlFinal
EXEC (@SqlFinal)


--PRINT (@SqlView)
EXEC (@SqlView)

------------------------------------------------------------------------------------------------------------------------------------------
EXEC (@SqlViewFilter2)
------------------------------------------------------------------------------------------------------------------------------------------

END 
GO 
SET QUOTED_IDENTIFIER OFF 
GO 
SET ANSI_NULLS ON 
GO 
