CREATE PROCEDURE Tsh.GeneralReport
 @BaseParam VARCHAR(50),
 @AddParam VARCHAR(3),
 @Filter VARCHAR(100),
 @SliceCodeFlag BIT,
 @SliceCaptionFlag BIT, 
 @SqlWhere VARCHAR(1000)
 
AS
BEGIN

DECLARE @SqlSelect    VARCHAR(4000)
DECLARE @SqlJoin      VARCHAR(2000)
DECLARE @SqlGroup     VARCHAR(4000)
DECLARE @SqlTopic     VARCHAR(1000)
DECLARE @SqlFinal     VARCHAR(8000)

DECLARE @OldCode      VARCHAR(1000)
DECLARE @SliceCode    VARCHAR(1000)
DECLARE @SliceCaption NVARCHAR(1000)
 
DECLARE @ID           VARCHAR(2)
DECLARE @fldName      VARCHAR(200)
DECLARE @AliasName    VARCHAR(50)
DECLARE @tblName      VARCHAR(30)
DECLARE @TopicName    VARCHAR(200)
DECLARE @Current      VARCHAR(50) 
DECLARE @JoinFldName  VARCHAR(50)
DECLARE @CaptionName  NVARCHAR(50)

SET @SqlSelect    = ''
SET @SqlJoin      = ''
SET @SqlGroup     = ''
SET @SqlTopic     = ''
SET @SqlFinal     = ''
SET @OldCode      = ''
SET @SliceCode    = ''
SET @SliceCaption = ''

DECLARE @SQLSUM NVARCHAR(1000);
SET @SQLSUM = '';

DECLARE @SqlView VARCHAR(8000)
SET @SqlView = '';

SET @Current = @BaseParam +','+ @AddParam 

DECLARE QAnalize CURSOR 
    FOR(
	     SELECT Util.Analyze.ID,TableName,FieldName,AliasName ,JoinFieldName,CaptionName,TopicName
	     FROM Util.Analyze INNER JOIN SplitString(@Current,',') SP ON SP.part =  Util.Analyze.ID 
	     WHERE TableKind = 21
	    ); 

OPEN QAnalize 
FETCH FROM QAnalize INTO @ID, @tblName, @fldName, @AliasName, @JoinFldName, @CaptionName, @TopicName ;
WHILE @@FETCH_STATUS = 0 
BEGIN
     
       SET @SqlGroup = @SqlGroup +  ISNULL(@AliasName,@tblName) +'.'+@JoinFldName  +' , '+ ISNULL(@AliasName,@tblName) +'.'+ @TopicName +','

       SET @SqlSelect = @SqlSelect + ' ISNULL(CAST('+ ISNULL(@AliasName,@tblName) +'.'+@JoinFldName +' AS VARCHAR(100)),0) +''-''+ '
       SET @SqlTopic = @SqlTopic + ' ISNULL(CAST('+ISNULL(@AliasName,@tblName) +'.'+ @TopicName +' AS VARCHAR(100)),''--'') +''-''+ ' 
       
       IF (@SliceCaptionFlag  = 1)
       BEGIN
          SET @SliceCaption  =  @SliceCaption + ' ISNULL(CAST(' +ISNULL(@AliasName,@tblName) + '.' + @TopicName + ' AS NVARCHAR(100)),'' '') AS'+'['+'عنوان '+ @CaptionName +'],'      
       END
       
       IF (@SliceCodeFlag = 1)
       BEGIN 
          SET @SliceCode = @SliceCode + ' ISNULL(CAST('+ ISNULL(@AliasName,@tblName) +'.'+@JoinFldName +' AS VARCHAR(100)),0) '+ ' AS ['+ @CaptionName +'], '
       END     
   
       SET @SqlJoin = @SqlJoin + ' INNER JOIN ' + @tblName + ' '+ISNULL(@AliasName ,'')+ ' ON ' +'ISNULL('+ @fldName +',0)'+' = ' + ISNULL(@AliasName,@tblName) +'.'+@JoinFldName
       
       FETCH NEXT FROM QAnalize INTO @ID, @tblName, @fldName, @AliasName, @JoinFldName, @CaptionName, @TopicName ;

END

CLOSE QAnalize ;	
DEALLOCATE QAnalize ; 

 SET @SqlSelect = LEFT (@SqlSelect , LEN(@SqlSelect)-5)
 SET @SqlTopic = LEFT  (@SqlTopic, LEN(@SqlTopic)-5) 
 SET @SqlGroup = @SqlGroup + @SqlTopic +','+ @SqlSelect 
 
 IF (@AddParam  <> '')
 BEGIN
	SELECT @OldCode = @OldCode + 'Cast(' + FieldName +' AS VARCHAR(20)) +''-''+'      
	FROM Util.Analyze INNER JOIN SplitString(@BaseParam,',') SP ON SP.part = Util.Analyze.ID 

	SET @OldCode   =  LEFT (@OldCode, (LEN(@OldCode) - 5))  ; 
	
	IF (@Filter <> '') 
	BEGIN
		IF (@SqlWhere = '')  
			SET @SqlWhere =  ' WHERE '+ @OldCode +'='''+@Filter+' '''	
		ELSE		
			SET @SqlWhere =  @SqlWhere +' AND '+ @OldCode +'='''+@Filter+' '''		
	END;	
 END;


SET  @SqlFinal = 'SELECT '+ @SliceCode+ @SliceCaption+ @SqlSelect +' As AllColumn , '+ @SqlTopic +' AS AllCaption ' 
			 
SET @SqlFinal = @SqlFinal
               + CHAR(13) + ',SUM(dbo.TimeToInt(convert(char(10),Func.functionhour, 108)) ) AS SUMFunctionHour,SUM(Func.FunctionAmount) AS SUMFunctionAmount, '
               + CHAR(13) + ' SUM(CASE ShiftWork WHEN 0 THEN dbo.TimeToInt(CONVERT(CHAR(10),ShiftWorkTime,108)) ELSE 0 END ) AS SUMShiftWork0, '
               + CHAR(13) + ' SUM(CASE ShiftWork WHEN 1 THEN dbo.TimeToInt(CONVERT(CHAR(10),ShiftWorkTime,108)) ELSE 0 END ) AS SUMShiftWork1, '
               + CHAR(13) + ' SUM(CASE ShiftWork WHEN 2 THEN dbo.TimeToInt(CONVERT(CHAR(10),ShiftWorkTime,108)) ELSE 0 END ) AS SUMShiftWork2, '
               + CHAR(13) + ' SUM(CASE ShiftWork WHEN 3 THEN dbo.TimeToInt(CONVERT(CHAR(10),ShiftWorkTime,108)) ELSE 0 END ) AS SUMShiftWork3, '
               + CHAR(13) + ' SUM(dbo.TimeToInt(CONVERT(CHAR(10),OverTime,108)))AS SUMOverTime , ' 
                          + ' SUM(Func.Amount1) AS SUMAmount1, SUM(Func.Amount2) AS SUMAmount2, SUM(Func.Amount3) AS SUMAmount3 '
               + CHAR(13) + ' FROM Tsh.Functions Func INNER JOIN
                         dbo.Customers AS CustomersWorkShop ON Func.WorkShopId = CustomersWorkShop.CustID ' + @SqlJoin 
               + CHAR(13) + @SqlWhere 
               + CHAR(13) + ' GROUP BY '+ @SqlGroup 

SET @SQLSUM = ' SUM(SUMFunctionHour) AS SUMFunctionHour, SUM(SUMFunctionAmount) AS SUMFunctionAmount,' 
              + CHAR(13) + 'SUM(SUMShiftWork0) AS SUMShiftWork0,SUM(SUMShiftWork1) AS SUMShiftWork1,SUM(SUMShiftWork2) AS SUMShiftWork2,'
              + CHAR(13) + 'SUM(SUMShiftWork3) AS SUMShiftWork3,SUM(SUMOverTime) AS SUMOverTime,' 
              + CHAR(13) + 'SUM(SUMAmount1) AS SUMAmount1, SUM(SUMAmount2) AS SUMAmount2, SUM(SUMAmount3) AS SUMAmount3'

EXEC('IF EXISTS (SELECT * FROM sysobjects WHERE id = object_id( N''[Tsh].[view_GeneralReport]'') AND OBJECTPROPERTY(id, N''IsView'') = 1)'
                 +' DROP view [Tsh].[view_GeneralReport]')
--create view LowerCase
SET @SqlView =  'create view [Tsh].[view_GeneralReport]  AS ' 
               + CHAR(13) + 'SELECT ''جمع:''AS [ ],' +  @SQLSUM + ' FROM (' 
               + CHAR(13) + @SqlFinal +') AS Temp'

--PRINT @SqlFinal
EXEC (@SqlFinal)

--PRINT (@SqlView)
--PRINT LEN(@SqlView)

EXEC (@SqlView)

END

GO 
SET QUOTED_IDENTIFIER OFF 
GO 
SET ANSI_NULLS ON 
GO 
