CREATE FUNCTION   Fn_rptCustomersBalance2F(  @TypeDoc1 int = 10 ,@TypeDoc2 int = -1,
				@TypeDoc3 int = -1 ,@TypeDoc4 int = -1 ,
  @PersonID1From int=-999999999
, @PersonID1To int=999999999
, @FormDate0To char(10)='0000/00/00'
, @CheckDateTo char(10)='0000/00/00'
, @YearIDFrom Bigint=1382
, @YearIDTo Bigint=1999
, @SellsMethodFrom int=-999999999
, @SellsMethodTo int=999999999
, @SellsEmporiumFrom int=-999999999
, @SellsEmporiumTo int=999999999
, @CustomerGrpID1From int=-999999999
, @CustomerGrpID1To int=999999999
, @VasetFrom int=-999999999
, @VasetTo int=999999999
, @SUMAccFrom Bigint=-999999999999999999
, @SUMAccTo Bigint=999999999999999999
,@FormTypeCecksIn varchar(1000)
,@FormTypeBank varchar(1000)
,@CheckReturned varchar(1000)
,@SaderehBardashtNashode varchar(1000)='50,54'
 )
RETURNS table  AS  

return (
  SELECT  Balance.PersonID1 , Balance.CustName , 

    Balance.Tel, Balance.Address, Balance.Mobile,Balance.NationalID,Balance.FirstBalance,

    case when Balance.balance >0 then Balance.balance else 0 end as bed ,
	isnull(Bankbalance.Bankbalance ,0) as Bankbalance,
    isnull(Check_IN.CheckINCashier ,0) as CheckINCashier ,
    isnull(Check_INbanK.CheckINBank,0) as CheckINBank ,
    isnull(Check_returend.Check_returend,0) as CheckReturned ,
    isnull(Check_Saderh.Check_Saderh,0) as Check_Saderh ,

	

   isnull(Check_InMoshtari.CheckInMoshtari,0) as CheckInMoshtari,
   isnull(Taahods.Taahod,0) as Taahod,
   isnull(PayTaahods.PayTaahod,0) as PayTaahod,
   
   isnull(Check_Hoquqis.Check_Hoquqi,0) as Hoquqi,
   isnull(Check_Tazmins.Check_Tazmin,0) as Tazmin,
   

	



	

    case when Balance.balance <0 then Balance.balance else 0 end as bes ,
    (Balance.balance + isnull(Check_IN.CheckINCashier ,0) + isnull(Check_INbanK.CheckINBank,0))
    +isnull(Check_InMoshtari.CheckInMoshtari,0) +isnull(Check_Saderh.Check_Saderh,0) +isnull(Taahods.Taahod,0)  /*+ isnull(Bankbalance.Bankbalance ,0)*/  as Balance
    From (

    SELECT	AllAcc.CustomerID1 AS PersonID1, CASE WHEN LEN(isnull(C.CustFirstName,'')) = 0 THEN C.CustName 
      ELSE  C.CustFirstName+' ' +C.CustName END+dbo.GetBlacklistMarker(C.Blacklist ) AS CustName, C.Tel, C.Address,
    C.Mobile,C.NationalID,

    SUM(CASE WHEN AllAcc.kind = 0 THEN AllAcc.bed - AllAcc.bes ELSE 0 END) AS FirstBalance,
    SUM(AllAcc.bed)-
    CASE WHEN SUM(CASE WHEN AllAcc.kind = 0 THEN AllAcc.bed - AllAcc.bes ELSE 0
    END)> 0
    THEN SUM(CASE WHEN AllAcc.kind = 0 THEN AllAcc.bed - AllAcc.bes ELSE 0
    END)
    ELSE 0
    END
    AS bed,
    SUM(CASE WHEN doctype IN (1, 2, 10) THEN AllAcc.bes ELSE 0 END) -
    CASE WHEN SUM(CASE WHEN AllAcc.kind = 0 THEN AllAcc.bed - AllAcc.bes ELSE 0
    END)< 0
    THEN - SUM(CASE WHEN AllAcc.kind = 0 THEN AllAcc.bed - AllAcc.bes ELSE
    0 END)
    ELSE 0
    END
    AS bes,
    SUM(CASE WHEN doctype IN (1, 2, 10) THEN AllAcc.bed - AllAcc.bes ELSE 0 END) AS balance
    FROM	CustomersGroup RIGHT OUTER JOIN
    dbo.AllAccount(@TypeDoc1  ,@TypeDoc2 ,
				@TypeDoc3  ,@TypeDoc4, @PersonID1From, @PersonID1To, '0', @FormDate0To, '0',
    @YearIDFrom, @YearIDTo, @SellsMethodFrom, @SellsMethodTo, @SellsEmporiumFrom,   @SellsEmporiumTo , DEFAULT)	AS AllAcc INNER JOIN
    Customers C ON AllAcc.CustomerID1 = C.CustID  ON
    CustomersGroup.CustomerGrpID = C.CustomerGrpID

    WHERE ( C.CustID in (SELECT  CustID FROM Vu_CustomersGroups
                WHERE  (CustomerGroupID BETWEEN @CustomerGrpID1From AND @CustomerGrpID1To )))
          AND (AllAcc.CustomerID1 <> 0)

    --if opt.ChkUsersCustomersGroupsActive then
    --begin
    --  AND (dbo.ChkUsersCustomersGroups( @UserAdmin , @UserID , AllAcc.CustomerID1 ) = 1)
    --  Parameters.ParamByName('UserID').Value @= User.ID;
    --  Parameters.ParamByName('UserAdmin').Value @= IfThen(User.admin, 1, 0);
    --end;

    AND ((C.PersonID1 BETWEEN @VasetFrom AND @VasetTo ) OR (C.PersonID1=0))

    GROUP BY AllAcc.CustomerID1, C.CustName,C.CustFirstName, C.Tel, C.Address, C.Mobile,
    C.FirstBalance,C.NationalID,C.Blacklist


    ) Balance left outer join
	(
SELECT  CustomerID1, sum( bed- bes) AS Bankbalance
FROM         dbo.AllAccount( 2 , 1, 2 , 10 , @PersonID1From, @PersonID1To, '0', @FormDate0To, '0',
    @YearIDFrom, @YearIDTo, @SellsMethodFrom, @SellsMethodTo, @SellsEmporiumFrom,   @SellsEmporiumTo , DEFAULT ) AS AllAccount_1

group by CustomerID1


    ) Bankbalance  on Bankbalance.CustomerID1 = Balance.PersonID1  left outer join
    
    (
    SELECT	formitems.customerid2 as customerid2 , sum(formitems.itemamount) as CheckINCashier
    from	formitems inner join
    forms on formitems.yearid = forms.yearid and formitems.serverid = forms.serverid and
    formitems.formid = forms.formid inner join
    formtypes on forms.formtype = formtypes.formtype left outer join
     (	SELECT	formitems.preformitemid ,formitems.perserverid ,formitems.yearid
    from	formitems inner join
    forms on formitems.yearid = forms.yearid and formitems.serverid =
    forms.serverid and formitems.formid = forms.formid
    where	(forms.formdate <= @FormDate0To) and (formitems.CheckDate <= @CheckDateTo) and
    (forms.formstate<10) and
    (forms.yearid between @yearidfrom and @yearidto)
    ) formitems_1 on formitems.serverid =formitems_1.perserverid and formitems.yearid =
    formitems_1.yearid and
    formitems.formitemid = formitems_1.preformitemid
    where (formitems_1.preformitemid is null) 
     AND (forms.formtype  IN (SELECT part FROM dbo.SplitString(@FormTypeCecksIn,',')))


   and (formitems.customerid2 between @PersonID1From and @PersonID1To) and
    (forms.formdate <= @FormDate0To ) and (formitems.CheckDate <= @CheckDateTo) and
    (forms.formstate<10) and
    (forms.yearid between @yearidfrom and @yearidto)
    Group By formitems.customerid2
    
    ) Check_IN on Balance.PersonID1 = Check_IN.customerid2 Left outer join
    
    (
    
    SELECT	formitems.customerid2 as customerid2 , sum(formitems.itemamount) as CheckINBank
    from	formitems inner join
    forms on formitems.yearid = forms.yearid and formitems.serverid = forms.serverid and
    formitems.formid = forms.formid inner join
    formtypes on forms.formtype = formtypes.formtype left outer join
    (	SELECT	formitems.preformitemid ,formitems.perserverid ,formitems.yearid
    from	formitems inner join
    forms on formitems.yearid = forms.yearid and formitems.serverid =
    forms.serverid and formitems.formid = forms.formid
    where	(forms.formdate <= @FormDate0To) and (formitems.CheckDate <= @CheckDateTo) and
    (forms.formstate<10) and
    (forms.yearid between @yearidfrom and @yearidto)
    ) formitems_1 on formitems.serverid =formitems_1.perserverid and formitems.yearid =
    formitems_1.yearid and
    formitems.formitemid = formitems_1.preformitemid
    where (formitems_1.preformitemid is null) 
     AND (forms.formtype  IN (SELECT part FROM dbo.SplitString(@FormTypeBank,',')))
	 AND
    (formitems.customerid2 between @PersonID1From and @PersonID1To) and
    (forms.formdate <= @FormDate0To ) and (formitems.CheckDate <= @CheckDateTo) and
    (forms.formstate<10) and
    (forms.yearid between @yearidfrom and @yearidto)
    Group By formitems.customerid2
    
    ) Check_INbanK on Balance.PersonID1 = Check_INbanK.customerid2

    Left outer join
    (
    
    SELECT	formitems.customerid2 as customerid2 , sum(formitems.itemamount) as CheckInMoshtari
    FROM FormItems INNER JOIN
    Forms ON FormItems.YearID = Forms.YearID AND FormItems.ServerID = Forms.ServerID AND FormItems.FormID =
    Forms.FormID INNER JOIN
    FormTypes ON Forms.FormType = FormTypes.FormType LEFT OUTER JOIN
    Customers Customers_1 ON Forms.CustomerID1 = Customers_1.CustID LEFT OUTER JOIN
    Customers Customers_2 ON FormItems.CustomerID2 = Customers_2.CustID

    where
    (forms.formtype in(12))and
    (formitems.customerid2 between @PersonID1From and @PersonID1To) and
    (forms.formdate <= @FormDate0To ) AND ((FormItems.CheckDate <= @CheckDateTo) and   (FormItems.CheckDate >= dbo.MiladiToShamsi(getdate()-1)) and   
    (forms.formstate <10) and
    
    (forms.yearid between @yearidfrom and @yearidto)
     )
    Group By formitems.customerid2
    
    ) Check_InMoshtari on Balance.PersonID1 = Check_InMoshtari.customerid2

	left outer join 
	(SELECT	formitems.customerid2 as customerid2 , sum(formitems.itemamount) as Check_returend
    from	formitems inner join
    forms on formitems.yearid = forms.yearid and formitems.serverid = forms.serverid and
    formitems.formid = forms.formid inner join
    formtypes on forms.formtype = formtypes.formtype left outer join
    (	SELECT	formitems.preformitemid ,formitems.perserverid ,formitems.yearid
    from	formitems inner join
    forms on formitems.yearid = forms.yearid and formitems.serverid =
    forms.serverid and formitems.formid = forms.formid
    where	(forms.formdate <= @FormDate0To) and (formitems.CheckDate <= @CheckDateTo) and
    (forms.formstate<10) and
    (forms.yearid between @yearidfrom and @yearidto)
    ) formitems_1 on formitems.serverid =formitems_1.perserverid and formitems.yearid =
    formitems_1.yearid and
    formitems.formitemid = formitems_1.preformitemid
    where (formitems_1.preformitemid is null) 
     AND ((forms.formtype  IN (SELECT part FROM dbo.SplitString(@CheckReturned,',')))
	 or (forms.formtype  IN (24)))
	 AND
    (formitems.customerid2 between @PersonID1From and @PersonID1To) and
    (forms.formdate <= @FormDate0To ) and (formitems.CheckDate <= @CheckDateTo) and
    (forms.formstate<10) and
    (forms.yearid between @yearidfrom and @yearidto)
    Group By formitems.customerid2
    
    ) Check_returend on Balance.PersonID1 = Check_returend.customerid2


	left outer join 
	(SELECT	formitems.customerid2 as customerid2 , sum(formitems.itemamount) as Check_Saderh
    from	formitems inner join
    forms on formitems.yearid = forms.yearid and formitems.serverid = forms.serverid and
    formitems.formid = forms.formid inner join
    formtypes on forms.formtype = formtypes.formtype left outer join
    (	SELECT	formitems.preformitemid ,formitems.perserverid ,formitems.yearid
    from	formitems inner join
    forms on formitems.yearid = forms.yearid and formitems.serverid =
    forms.serverid and formitems.formid = forms.formid
    where	(forms.formdate <= @FormDate0To) and (formitems.CheckDate <= @CheckDateTo) and
    (forms.formstate<10) and
    (forms.yearid between @yearidfrom and @yearidto)
    ) formitems_1 on formitems.serverid =formitems_1.perserverid and formitems.yearid =
    formitems_1.yearid and
    formitems.formitemid = formitems_1.preformitemid
    where (formitems_1.preformitemid is null) 
     AND ((forms.formtype  IN (SELECT part FROM dbo.SplitString(@SaderehBardashtNashode,',')))
	 )
	 AND
    (formitems.customerid2 between @PersonID1From and @PersonID1To) and
    (forms.formdate <= @FormDate0To ) and (formitems.CheckDate <= @CheckDateTo)  and
    (forms.formstate<10) and
    (forms.yearid between @yearidfrom and @yearidto)
    Group By formitems.customerid2
    
    ) Check_Saderh on Balance.PersonID1 = Check_Saderh.customerid2


		left outer join	(
		SELECT        Forms.CustomerID1 AS customerid1, SUM(Forms.Amount) AS Taahod
		FROM            Forms INNER JOIN
								 FormTypes ON Forms.FormType = FormTypes.FormType
		WHERE        (Forms.FormType = 122) 
		AND (Forms.CustomerID1 BETWEEN @PersonID1From AND @PersonID1To) 
		AND (Forms.FormDate <= @FormDate0To) 
		AND (Forms.FormState < 10) 
		AND (Forms.YearID BETWEEN @yearidfrom AND @yearidto)
		GROUP BY Forms.CustomerID1
    
			) Taahods on Balance.PersonID1 = Taahods.CustomerID1   

	left outer join 
	(SELECT	formitems.customerid2 as customerid2 , sum(formitems.itemamount) as Check_Hoquqi
    from	formitems inner join
    forms on formitems.yearid = forms.yearid and formitems.serverid = forms.serverid and
    formitems.formid = forms.formid inner join
    formtypes on forms.formtype = formtypes.formtype left outer join
    (	SELECT	formitems.preformitemid ,formitems.perserverid ,formitems.yearid
    from	formitems inner join
    forms on formitems.yearid = forms.yearid and formitems.serverid =
    forms.serverid and formitems.formid = forms.formid
    where	(forms.formdate <= @FormDate0To) and (formitems.CheckDate <= @CheckDateTo) and
    (forms.formstate<10) and
    (forms.yearid between @yearidfrom and @yearidto)
    ) formitems_1 on formitems.serverid =formitems_1.perserverid and formitems.yearid =
    formitems_1.yearid and
    formitems.formitemid = formitems_1.preformitemid
    where (formitems_1.preformitemid is null) 
     AND ((forms.formtype  IN (SELECT part FROM dbo.SplitString('183',',')))
	 )
	 AND
    (formitems.customerid2 between @PersonID1From and @PersonID1To) and
    (forms.formdate <= @FormDate0To ) and (formitems.CheckDate <= @CheckDateTo)  and
    (forms.formstate<10) and
    (forms.yearid between @yearidfrom and @yearidto)
    Group By formitems.customerid2
    
    ) Check_Hoquqis on Balance.PersonID1 = Check_Hoquqis.customerid2

	left outer join	(
		SELECT        Forms.CustomerID1 AS customerid1, SUM(Forms.Amount) AS PayTaahod
		FROM            Forms INNER JOIN
								 FormTypes ON Forms.FormType = FormTypes.FormType
		WHERE        (Forms.FormType = 123) 
		AND (Forms.CustomerID1 BETWEEN @PersonID1From AND @PersonID1To) 
		AND (Forms.AIDINFODate <= @FormDate0To) 
		AND (Forms.FormState < 10) 
		AND (Forms.YearID BETWEEN @yearidfrom AND @yearidto)
		GROUP BY Forms.CustomerID1
    
			) PayTaahods on Balance.PersonID1 = PayTaahods.CustomerID1   

	left outer join 
	(SELECT	formitems.customerid2 as customerid2 , sum(formitems.itemamount) as Check_Tazmin
    from	formitems inner join
    forms on formitems.yearid = forms.yearid and formitems.serverid = forms.serverid and
    formitems.formid = forms.formid inner join
    formtypes on forms.formtype = formtypes.formtype left outer join
    (	SELECT	formitems.preformitemid ,formitems.perserverid ,formitems.yearid
    from	formitems inner join
    forms on formitems.yearid = forms.yearid and formitems.serverid =
    forms.serverid and formitems.formid = forms.formid
    where	(forms.formdate <= @FormDate0To) and (formitems.CheckDate <= @CheckDateTo) and
    (forms.formstate<10) and
    (forms.yearid between @yearidfrom and @yearidto)
    ) formitems_1 on formitems.serverid =formitems_1.perserverid and formitems.yearid =
    formitems_1.yearid and
    formitems.formitemid = formitems_1.preformitemid
    where (formitems_1.preformitemid is null) 
     AND ((forms.formtype  IN (SELECT part FROM dbo.SplitString('73,80',',')))
	 )
	 AND
    (formitems.customerid2 between @PersonID1From and @PersonID1To) and
    (forms.formdate <= @FormDate0To ) and (formitems.CheckDate <= @CheckDateTo)  and
    (forms.formstate<10) and
    (forms.yearid between @yearidfrom and @yearidto)
    Group By formitems.customerid2
    
    ) Check_Tazmins on Balance.PersonID1 = Check_Tazmins.customerid2

    WHERE --(( Balance.balance + isnull(Check_IN.CheckINCashier ,0) + isnull(Check_INbanK.CheckINBank,0) +isnull(Check_InMoshtari.CheckInMoshtari,0))<>0)    AND
	( ( Balance.balance + isnull(Check_IN.CheckINCashier ,0) + isnull(Check_INbanK.CheckINBank,0)+isnull(Check_InMoshtari.CheckInMoshtari,0)) BETWEEN @SUMAccFrom AND @SUMAccTo)

    --order by ( Balance.balance + isnull(Check_IN.CheckINCashier ,0) + isnull(Check_INbanK.CheckINBank,0)+isnull(Check_InMoshtari.CheckInMoshtari,0)) desc
)


