CREATE PROCEDURE SP_MatrixUnlimit  @COls varchar(200), @Rows varchar(200) ,  @CircleKind int, @Where varchar(max)
   , @ActiveColumns bigint=1 , @ShareColumns bigint=0 , @MatrixNo int=0
AS BEGIN
 SET NOCOUNT ON
exec('	IF OBJECT_ID(''TempDB.dbo.##tblTempUnlimit'') IS NOT NULL 
	   DROP TABLE ##tblTempUnlimit')
set @MatrixNo=0
if (select count(*) from FaraSystems.dbo.MatrixSave where MatrixNo =@MatrixNo)=0
INSERT INTO FaraSystems.dbo.MatrixSave (MatrixNo)
VALUES (@MatrixNo)



DECLARE  @ActiveRowShare bit
DECLARE  @ActiveColShare bit 
DECLARE  @ActiveGrowColShare bit
DECLARE  @ActivePartCol bit

if (@ShareColumns & 1 = 1) set @ActiveRowShare=1     else set @ActiveRowShare=0
if (@ShareColumns & 2 = 2) set @ActiveColShare=1     else set @ActiveColShare=0
if (@ShareColumns & 4 = 4) set @ActiveGrowColShare=1 else set @ActiveGrowColShare=0
if (@ShareColumns & 8 = 8) set @ActivePartCol=1      else set @ActivePartCol=0

DECLARE @Current varchar(20)
DECLARE @InnerSql varchar(max)
DECLARE @Sql varchar(max)

SET @Current = LTRIM(RTRIM(@COls)) + ',' + LTRIM(RTRIM(@Rows)) 
SET @InnerSql = ''
SET @Sql = ''


DECLARE @Row         varchar(20)= ''
DECLARE @Id          varchar(20)= ''
DECLARE @fldName     varchar(200)= ''
DECLARE @AliasName   varchar(50)= ''
DECLARE @tblName     varchar(30)= ''
DECLARE @TopicName   varchar(200)= ''
DECLARE @JoinFldName varchar(50)= ''
DECLARE @CurCaptionName NVARCHAR(50)= ''



DECLARE @SelectCol         varchar(max)
DECLARE @SelectRow         varchar(max)

DECLARE @SelectColCT         varchar(max)
DECLARE @SelectRowCT         varchar(max)


DECLARE @GroupCol          varchar(max)
DECLARE @GroupRow          varchar(max)
DECLARE @Join           varchar(max)
DECLARE @EntityKind     varchar(max)
DECLARE @UnitPriceKind  varchar(max)
DECLARE @PriceKind      varchar(max)
DECLARE @TotalPriceKind varchar(max)
DECLARE @DeficitWPriceKind varchar(max)


SET @SelectCol         = ''
SET @SelectRow         = ''

SET @SelectColCT         = ''
SET @SelectRowCT         = ''


SET @GroupCol          = ''
SET @GroupRow          = ''
SET @Join           = ''
SET @EntityKind     = ''
SET @UnitPriceKind  = ''
SET @PriceKind      = ''
SET @TotalPriceKind = ''
set @DeficitWPriceKind =''

DECLARE @Group    varchar(max)=''
DECLARE @SelectTemp    varchar(max)=''
DECLARE @DECLAREvar    varchar(max)=''
DECLARE @CURSORSel    varchar(max)=''


DECLARE cur_InnerSql CURSOR FOR( 	SELECT ROW_NUMBER() OVER(ORDER BY SP.RowEnter ASC) AS Row#,Analyze.ID, TableName,FieldName,AliasName ,JoinFieldName,CaptionName,TopicName
	                                FROM Util.Analyze  INNER JOIN SplitString(@COls,',') SP ON SP.part =  Analyze.ID	
									WHERE TableKind = 24
									 ) 

OPEN cur_InnerSql
FETCH FROM cur_InnerSql into @Row,@Id, @tblName, @fldName, @AliasName, @JoinFldName, @CurCaptionName, @TopicName 
WHILE @@fetch_status = 0 
	BEGIN
		declare @FiledName varchar(max)
		set @FiledName=',CAST( ' + case when CHARINDEX('SUBSTRING', @TopicName)=0 then ISNULL(@AliasName,@tblName) + '.' + ISNULL(@TopicName, @JoinFldName) 
			else 	@TopicName end +' AS NVARCHAR(100))'

		if ltrim(@tblName)<>''
		begin
	 	SET @SelectCol = @SelectCol + 'CAST( ' +@fldName + ' AS NVARCHAR(500)) AS C'+ltrim(@Row)+	@FiledName +'AS CN'+ltrim(@Row)+',' 
	 	SET @SelectColCT = @SelectColCT + ' C'+ltrim(@Row) +',CN'+ltrim(@Row)+',' 

	 	SET @DECLAREvar = @DECLAREvar +CHAR(13) + 'DECLARE @CodeC'+ltrim(@Row) +' VARCHAR(100) ' +CHAR(13)+'DECLARE @CodeN'+ltrim(@Row)+' VARCHAR(100) =''''' 
	 	--SET @DECLAREvar = @DECLAREvar +CHAR(13) + 'DECLARE @CodeN'+ltrim(@Row) +' VARCHAR(100) ' +CHAR(13)+'DECLARE @NameN'+ltrim(@Row)+' VARCHAR(100) =''''' 
	 	SET @CURSORSel = @CURSORSel + ' @CodeC'+ltrim(@Row) +', @CodeN'+ltrim(@Row)+',' --+ ' @CodeN'+ltrim(@Row) +', @NameN'+ltrim(@Row)+',' 

	 	SET @DECLAREvar = @DECLAREvar +CHAR(13) + 'DECLARE @CodeTempBC'+ltrim(@Row) +' VARCHAR(18) ' +CHAR(13)



       end
		  
		if ltrim(@tblName)<>''
		SET @GroupCol = @GroupCol +CHAR(13)+ 'CAST( ' +@fldName + ' AS NVARCHAR(500)) '+@FiledName +' ,'  

		if ltrim(@tblName)<>''
		  if UPPER( ltrim(@tblName))='TSH.CALENDAR' 
		    SET @Join = ' Tsh.Calendar ' + ISNULL(@AliasName,'') + ' ON ' + ISNULL(@AliasName,'') + '.CalendarDate = R.ReciptDate LEFT OUTER JOIN '+ CHAR(13) + @Join 
		  else

		   SET @Join = @tblName + ' ' + ISNULL(@AliasName,'') + ' ON ' + 
		
		   case when CHARINDEX('SUBSTRING', @JoinFldName)=0 then
             		  ISNULL(@AliasName,@tblName) + '.' + @JoinFldName  
			else 	@JoinFldName end	  
					  + ' = '+ @fldName 
		 +  case when /*Tsh.Calendar*/@Id not in (141,142,143) then   ' INNER JOIN ' else  ' LEFT OUTER JOIN ' end + CHAR(13) + @Join 

	FETCH NEXT FROM cur_InnerSql into @Row,@ID, @tblName, @fldName, @AliasName, @JoinFldName, @CurCaptionName, @TopicName 
	END

CLOSE cur_InnerSql 	
DEALLOCATE cur_InnerSql 

DECLARE @RowCount int=  @Row       



DECLARE cur_InnerSql CURSOR FOR( 	SELECT ROW_NUMBER() OVER(ORDER BY SP.RowEnter ASC) AS Row#,Analyze.ID, TableName,FieldName,AliasName ,JoinFieldName,CaptionName,TopicName
	                                FROM Util.Analyze  INNER JOIN SplitString(@Rows,',') SP ON SP.part =  Analyze.ID	WHERE TableKind = 24 
									 ) 

OPEN cur_InnerSql
FETCH FROM cur_InnerSql into @Row,@Id, @tblName, @fldName, @AliasName, @JoinFldName, @CurCaptionName, @TopicName 
WHILE @@fetch_status = 0 
	BEGIN
		set @FiledName=',CAST( ' + case when CHARINDEX('SUBSTRING', @TopicName)=0 then ISNULL(@AliasName,@tblName) + '.' + ISNULL(@TopicName, @JoinFldName) 
			else 	@TopicName end +' AS NVARCHAR(100))'

		if ltrim(@tblName)<>''
		begin
		SET @SelectRow = @SelectRow + 'CAST( ' +@fldName + ' AS NVARCHAR(500)) AS R'+ltrim(@Row)+@FiledName +'AS RN'+ltrim(@Row)+',' 
		SET @SelectRowCT = @SelectRowCT + 'R'+ltrim(@Row)+',RN'+ltrim(@Row)+',' 
SET @Group = @Group + 'R'+ltrim(@Row)+',RN'+ltrim(@Row)+',' 
SET @SelectTemp = @SelectTemp + 'R'+ltrim(@Row)+' AS [کد'+ @CurCaptionName +'], RN'+ltrim(@Row)+' AS ['+ @CurCaptionName+'],'  
       end
		  
		if ltrim(@tblName)<>''
		SET @GroupRow = @GroupRow +CHAR(13)+ 'CAST( ' +@fldName + ' AS NVARCHAR(500)) '+@FiledName +' ,'  

		if ltrim(@tblName)<>''
		  if UPPER( ltrim(@tblName))='TSH.CALENDAR' 
		    SET @Join = ' Tsh.Calendar ' + ISNULL(@AliasName,'') + ' ON ' + ISNULL(@AliasName,'') + '.CalendarDate = R.ReciptDate LEFT OUTER JOIN '+ CHAR(13) + @Join 
		  else

		   SET @Join = @tblName + ' ' + ISNULL(@AliasName,'') + ' ON ' + 
		
		   case when CHARINDEX('SUBSTRING', @JoinFldName)=0 then
             		  ISNULL(@AliasName,@tblName) + '.' + @JoinFldName  
			else 	@JoinFldName end	  
					  + ' = '+ @fldName 
		 +  case when /*Tsh.Calendar*/@Id not in (141,142,143,145,146) then   ' INNER JOIN ' else  ' LEFT OUTER JOIN ' end + CHAR(13) + @Join 


	FETCH NEXT FROM cur_InnerSql into @Row,@ID, @tblName, @fldName, @AliasName, @JoinFldName, @CurCaptionName, @TopicName 
	END
		 if  --CHARINDEX(@Join,'StuffGroups SG ON' )=0 and
		    CHARINDEX('StuffCoding SC ON SC.c_StuffCode' ,@Join)=0
		   SET @Join = REPLACE ( @Join ,'StuffGroups SG ON','StuffCoding SC ON SC.c_StuffCode = Ri.StuffCode INNER JOIN  StuffGroups SG ON')  

		   
	SET @SelectCol = LEFT(@SelectCol, (LEN(@SelectCol) - 1))  
	SET @SelectRow = LEFT(@SelectRow, (LEN(@SelectRow) - 1))  
	SET @GroupCol = LEFT(@GroupCol, (LEN(@GroupCol) - 1)) 
	SET @GroupRow = LEFT(@GroupRow, (LEN(@GroupRow) - 1)) 
	SET @Group = LEFT(@Group, (LEN(@Group) - 1)) 
	SET @Join = LEFT(@Join, (LEN(@Join) - 12))  


	--IF OBJECT_ID('tempdb..##tblTempUnlimit') IS NOT NULL 
	--   DROP TABLE ##tblTempUnlimit
	SET @EntityKind = CASE @CircleKind WHEN 0 THEN 'SUM(Ri.InputEntity) - SUM(Ri.OutputEntity)'
	                                  WHEN 1 THEN 'SUM(Ri.InputEntity)'
									  WHEN 2 THEN 'SUM(Ri.OutputEntity)'
									  WHEN 3 THEN 'SUM(Ri.OutputEntity) - SUM(Ri.InputEntity)' ELSE '' END 

	SET @UnitPriceKind = CASE @CircleKind WHEN 0 THEN 'AVG(Ri.UnitSellPrice) '
	                                      WHEN 1 THEN 'AVG(Ri.UnitSellPrice)'
									      WHEN 2 THEN 'AVG(Ri.UnitSellPrice)'
									      WHEN 3 THEN 'AVG(Ri.UnitSellPrice) ' ELSE '' END 

	SET @PriceKind = CASE @CircleKind WHEN 0 THEN 'SUM(Ri.TotalInputPrice) - SUM(Ri.TotalOutputPrice)'
	                                  WHEN 1 THEN 'SUM(Ri.TotalInputPrice)'
									  WHEN 2 THEN 'SUM(Ri.TotalOutputPrice)'
									  WHEN 3 THEN 'SUM(Ri.TotalOutputPrice) - SUM(Ri.TotalInputPrice)' ELSE '' END 


	SET @TotalPriceKind = CASE @CircleKind WHEN 0 THEN 'SUM(Ri.TotallSellPrice) '
	                                  WHEN 1 THEN 'SUM(Ri.TotallSellPrice)'
									  WHEN 2 THEN 'SUM(Ri.TotallSellPrice)'
									  WHEN 3 THEN 'SUM(Ri.TotallSellPrice) ' ELSE '' END 

	SET @DeficitWPriceKind = CASE @CircleKind WHEN 0 THEN 'SUM(Ri.TotalInputPrice) - SUM(Ri.TotalOutputPrice)- SUM(Ri.DeficitValue)'
	                                  WHEN 1 THEN 'SUM(Ri.TotalInputPrice)- SUM(Ri.DeficitValue)'
									  WHEN 2 THEN 'SUM(Ri.TotalOutputPrice)- SUM(Ri.DeficitValue)'
									  WHEN 3 THEN 'SUM(Ri.TotalOutputPrice) - SUM(Ri.TotalInputPrice)- SUM(Ri.DeficitValue)' ELSE '' END 

			  

DECLARE @From varchar(max)
SET @From=CHAR(13) +'FROM ' 
	+' Recipts R INNER JOIN ReciptItems Ri ON R.ReciptID = Ri.ReciptID AND R.ServerID = Ri.ServerID '
	+' AND R.YearID = Ri.YearID INNER JOIN '
	+ CHAR(13) + @Join  
	+' LEFT OUTER JOIN LookUps LookUps_I ON Ri.SecondTypeItem = LookUps_I.LookUpID '
	+' LEFT OUTER JOIN LookUps LookUps_M ON R.SecondType = LookUps_M.LookUpID '
	+CHAR(13)+ @Where
	
	SET @InnerSql = 'SELECT ' + @Selectcol +CHAR(13)+','+ @SelectRow +CHAR(13)+ ',ROUND('+ @EntityKind +',2) AS P1' + ',ROUND('+ @UnitPriceKind +',2) AS P2' 
	           +',ROUND('+ @PriceKind +',2) AS P3' + ',ROUND('+ @TotalPriceKind +',2) AS P4' + ',ROUND('+ @DeficitWPriceKind +',2) AS P5' + CHAR(13) 
										 +' Into ##tblTempUnlimit ' +
										  @From 
										  +CHAR(13)+' GROUP BY ' + @GroupCol+','+ @GroupRow

CLOSE cur_InnerSql 	
DEALLOCATE cur_InnerSql 


EXEC (@InnerSql)
print (@InnerSql)




