DECLARE @ColCodeLoopTemp varchar(max)=''
DECLARE @ColCodeLoopCaption varchar(max)=''
DECLARE @ColCodeLoopCaptionC varchar(max)=''
DECLARE @CodeTemp varchar(max)=''
DECLARE @cnt INT = 2
WHILE @cnt <= @ROWCOUNT begin

  	set @ColCodeLoop = @ColCodeLoop + '+'' AND C'+ltrim(@cnt)+'=''+dbo.QuotedStr(@CodeC'+ltrim(@cnt)+')'
  	set @ColCodeLoopTemp = @ColCodeLoopTemp + '+'' AND C'+ltrim(@cnt)+'=''+dbo.QuotedStr(@CodeTempBC'+ltrim(@cnt)+')'



	set @ColCodeLoopCaption = @ColCodeLoopCaption + '+''|''+@CodeN'+ltrim(@cnt)+''
	set @ColCodeLoopCaptionC = @ColCodeLoopCaptionC + '+''|''+@CodeC'+ltrim(@cnt)+''

	

	set @CodeTemp = @CodeTemp +'SET @CodeTempBC'+ltrim(@cnt)+' = @CodeC'+ltrim(@cnt)+CHAR(13)	

    SET @cnt = @cnt + 1
END 

