				   '+ ''AS [''+ @CodeC1 '+@ColCodeLoopCaptionC+'+''|''+''خالص]'' '+CHAR(13)+

      'if @P5Active=1 '+CHAR(13)+
			'SET @qry = @qry + CASE WHEN @SumColumn5 = ''0.00'' or @SumColumn5 = ''''  THEN ''0 '' '+CHAR(13)+
			      'ELSE '' ,CAST(ROUND(SUM(CASE WHEN C1=''+dbo.QuotedStr(@CodeC1) '+
				  @ColCodeLoop+'+'' THEN P5 else 0 END)/CAST(''+left(@SumColumn5, len(@SumColumn5)-3)+'' AS BIGINT)*100,2) AS FLOAT) '' END '+CHAR(13)+
				   '+ ''AS [''+ @CodeC1 '+@ColCodeLoopCaptionC+'+''|''+''تخفیف]'' '+CHAR(13)+

        'end '+CHAR(13)+
		-----------------------------------------
		'FETCH NEXT FROM cur_Matrix into '+ @CURSORSel +' @SumColumn1, @SumColumn2, @SumColumn3, @SumColumn4,@SumColumn5 '+CHAR(13)+
	'END '+CHAR(13)+
' CLOSE cur_Matrix '+CHAR(13)+
'DEALLOCATE cur_Matrix '+CHAR(13)+

	  'if (@ActivePartCol=1) '+CHAR(13)+
	  'begin '+CHAR(13)+
	  'if (@PartColP1<>''0'') '+CHAR(13)+
		'SET @qry = @qry +CHAR(13) +@PartColSqlP1 '+CHAR(13)+
	  'if (@PartColP2<>''0'') '+CHAR(13)+
		'SET @qry = @qry +CHAR(13) +@PartColSqlP2 '+CHAR(13)+
	  'if (@PartColP3<>''0'') '+CHAR(13)+
		'SET @qry = @qry +CHAR(13) +@PartColSqlP3 '+CHAR(13)+
	  'if (@PartColP4<>''0'') '+CHAR(13)+
		'SET @qry = @qry +CHAR(13) +@PartColSqlP4 '+CHAR(13)+
	  'if (@PartColP5<>''0'') '+CHAR(13)+
		'SET @qry = @qry +CHAR(13) +@PartColSqlP5 '+CHAR(13)+

      'end '+CHAR(13)+



'UPDATE FaraSystems.dbo.MatrixSave SET MatrixSQL =rtrim(ltrim(@qry)) WHERE(MatrixNo='+ltrim(@MatrixNo)+')' 
--print len(@mySQL)
--print (@mySQL)

exec (@mySQL)

declare @Select2 varchar(max)
select @Select2 = MatrixSQL FRom FaraSystems.dbo.MatrixSave
WHERE        (MatrixNo = @MatrixNo)

--print(@Select2)
--exec (@Select)
--SET @Select = left(@Select, (LEN(@Select) - 1))  

declare @SelectSum varchar(max)=''
      if @P1Active=1
		SET @SelectSum = @SelectSum +',sum(p1) AS جمعمقدار'
      if @P2Active=1
		SET @SelectSum = @SelectSum +',sum(p2) AS [میانگین فی]'
      if @P3Active=1
		SET @SelectSum = @SelectSum +',sum(p3) AS جمعکل'
      if @P4Active=1
		SET @SelectSum = @SelectSum +',sum(p4) AS جمعکلخالص'
      if @P5Active=1
		SET @SelectSum = @SelectSum +',sum(p5) AS جمعکلتخفیف'

	SET @SelectTemp = LEFT(@SelectTemp, (LEN(@SelectTemp) - 1))  


SET @Sql = 'SELECT '+@SelectTemp + CHAR(13) + @Select2 + CHAR(13) +@SelectSum+ CHAR(13) + '  FROM (SELECT * FROM ##tblTempUnlimit) AS Temp ' 
             + CHAR(13) + 'GROUP BY '+@Group

declare @Row1 varchar(100)             
select @Row1=part from SplitString(@Rows,',') 
if (@Row1='141')or(@Row1='142')or(@Row1='143')
SET @Sql =@Sql+ CHAR(13) +' ORDER BY R1' 
else
SET @Sql =@Sql+ CHAR(13) +' ORDER BY CAST(R1 AS BIGINT)'


DECLARE @MAXCol INTEGER


IF (LEN(@Sql) > 7995)
BEGIN
	IF (( SELECT COUNT(*) FROM (SELECT * FROM ##tblTempUnlimit ) AS a)> 50) 
		BEGIN
			SET @MAXCol = CASE  CAST(@ActiveColShare AS smallint) + CAST(@ActiveRowShare AS smallint) WHEN 0 THEN 60 WHEN 1 THEN 30 WHEN 2 THEN  15 END
			RAISERROR ('تعداد ستونهاي انتخابي نبايد بيشتر از %d باشد', 16, 1 , @MAXCol )
		END 
	ELSE
	RAISERROR ('لطفا در محدوده تعداد ستونهاي انتخابي را کم کنيد', 16, 1) 
END

--print (@Sql)
EXEC (@Sql)

---UPDATE FaraSystems.dbo.MatrixSave SET COl_s =rtrim(ltrim(@COls)),  Row_s =rtrim(ltrim(@Rows)) WHERE(MatrixNo=@MatrixNo)
delete  FRom FaraSystems.dbo.MatrixSave
WHERE   (MatrixNo = @MatrixNo) AND (LTRIM(MatrixName)='')
 


END

