CREATE PROCEDURE dbo.USP_NEWYEARE_STORE (@mojoodi int ,@customer int, @yearidfrom int, @yearidto int ,@Serverid int )

AS

begin
set nocount on

DECLARE @DEL INT
DECLARE @IDRECIPT INT
DECLARE @StoreID int ,@Reciptid int
DECLARE @DATE CHAR(10)
DECLARE @IDSEED INT
DECLARE @SUMC MONEY
-------------------------------------------------------------------------------------

SELECT  @SUMC = SUM(ISNULL(FirstBalance, 0)) 
FROM         Customers

IF @SUMC <>0 

BEGIN 
INSERT INTO RemainsEarly (YearID, PersonID1, Rate,InfoKind,Note)

SELECT     @yearidTo ,CustID, FirstBalance,0,'انتقالي از مانده معرفي مشتريان '
FROM         Customers
WHERE     (FirstBalance IS NOT NULL) AND (FirstBalance <> 0)

UPDATE Customers 
	SET FirstBalance= 0

END 

IF (@mojoodi =1 )
begin



create table #YearStuff(
	StoreID int NULL,
	StuffCode bigint NULL,
	StuffSize varchar(12) NOT NULL,
	StuffDiameter float NOT NULL,
	StuffAlloy varchar(12) NOT NULL,
	InputEntity float NOT NULL,
	InputWeight float NOT NULL,
	ControlCode bigint NOT NULL,
	StuffGrade tinyint NOT NULL,
	TotalInputPrice money NOT NULL,
	UnitSellPrice money NOT NULL,
	TotallSellPrice money NOT NULL,
	ItemNote varchar(100) NULL,
	PersonID1 int NULL,
    ServerID int NOT NULL,
	YearID int NOT NULL,
	n_ValuationType INT NOT NULL,
	IDKEY int IDENTITY(1,1) NOT NULL,
	SpecialCode char(25) 
	
) 

 INSERT INTO #YearStuff(StoreID ,StuffCode,StuffDiameter,StuffSize ,StuffAlloy,StuffGrade,InputEntity ,InputWeight,TotalInputPrice 
     ,n_ValuationType,ControlCode,PersonID1,ItemNote,YearID,ServerID,UnitSellPrice ,TotallSellPrice ,SpecialCode )
    
    
SELECT     ReciptItems_Stock.StoreID, ReciptItems_Stock.StuffCode, 0.0 AS StuffDiameter, '' AS StuffSize, '' AS StuffAlloy, 1 AS StuffGrade, 
                      ROUND(SUM(ReciptItems_Stock.InputEntity - ReciptItems_Stock.OutputEntity), 3) AS Entity, 
                      ROUND(SUM(ReciptItems_Stock.InputWeight - ReciptItems_Stock.OutputWeight), 3) AS Weight, 
                      SUM(ReciptItems_Stock.TotalInputPrice - ReciptItems_Stock.TotalOutputPrice) AS Price, Stores.n_ValuationType, 0 AS ControlCode, 0 AS PersonID1, 
                      '' AS ItemNote,@yearidto , 
                      --dbo.ReciptItems_Stock.ServerID,
					  @ServerID as ServerID,
                      
                      (CASE WHEN 
                                    
                      ROUND(SUM(ReciptItems_Stock.InputEntity - ReciptItems_Stock.OutputEntity), 3)<>0 
                       THEN  
                       ROUND(SUM(ReciptItems_Stock.TotalInputPrice - ReciptItems_Stock.TotalOutputPrice),0) 
                              / ROUND(SUM(ReciptItems_Stock.InputEntity - ReciptItems_Stock.OutputEntity), 3)
                      ELSE  0  
                      END ) AS UNITE   
                    ,SUM(ReciptItems_Stock.TotalInputPrice - ReciptItems_Stock.TotalOutputPrice) AS SELPRICE ,SpecialCode
FROM         ReciptItems_Stock INNER JOIN
                      Stores ON ReciptItems_Stock.StoreID = Stores.n_StoreID
WHERE   ReciptItems_Stock.YearID =@yearidfrom
GROUP BY ReciptItems_Stock.StoreID, ReciptItems_Stock.StuffCode, Stores.n_ValuationType, ReciptItems_Stock.YearID--, ReciptItems_Stock.ServerID
         ,ReciptItems_Stock.SpecialCode
HAVING      (SUM(ReciptItems_Stock.InputEntity - ReciptItems_Stock.OutputEntity) >= 0.0001) OR
                      (SUM(ReciptItems_Stock.InputEntity - ReciptItems_Stock.OutputEntity) <= - 0.0001) OR
                      (SUM(ReciptItems_Stock.InputWeight - ReciptItems_Stock.OutputWeight) >= 0.0001) OR
                      (SUM(ReciptItems_Stock.InputWeight - ReciptItems_Stock.OutputWeight) <= - 0.0001)
             
 ------------------------------------------------------cursor-----------------------------------------------------

DECLARE C CURSOR for
	SELECT StoreID--,Serverid  
	FROM dbo.Recipts
	GROUP BY StoreID--,Serverid 
	ORDER BY  StoreID-- ,Serverid
	
	
OPEN C

FETCH NEXT FROM C INTO @StoreID --,@Serverid

	WHILE @@FETCH_STATUS =0
	
	 BEGIN 
	
	SELECT @IDRECIPT=ISNULL(MAX(ReciptID),1) FROM Recipts  WHERE YearID=@yearidto
	
	SET @DATE = CAST (@yearidto AS CHAR(10))+'/01/01'
	 INSERT INTO  Recipts (ReciptID, StoreID, ReciptNumber, ReciptDate, ReciptType, ModifyDate, ServerID, YearID,operatorid,personid1)
		
			SELECT   @IDRECIPT+1 AS RECIPTID, @StoreID AS STOREID, 1 AS RECIPTNO, @DATE AS RECIPTDATE, 1 AS RECIPTTYPE, GETDATE() AS MODIFYDATE, @Serverid AS SERVERID, 
                      @yearidto, 127 AS OPERATORID, 0 AS PERSONELID
			FROM         Recipts
			WHERE  StoreID=@StoreID --and Serverid = @Serverid 
			        and yearid=@yearidfrom
			GROUP BY StoreID --,Serverid
			
			
			SELECT @IDSEED=ISNULL(MAX(ReciptItemID),1) FROM ReciptItems  WHERE YearID=@yearidto
			
	  		
	  		INSERT INTO   ReciptItems  (ReciptItemID, ReciptID,StuffCode,  StuffDiameter, StuffSize,StuffAlloy,StuffGrade, InputEntity, InputWeight, TotalInputPrice
			, ControlCode, PersonID1,SERVERID,YEARID,UnitSellPrice,TotallSellPrice,SpecialCode)
	  		
	  		SELECT IDKEY+@IDSEED,@IDRECIPT+1,StuffCode,StuffDiameter,StuffSize ,StuffAlloy,StuffGrade,InputEntity ,InputWeight,TotalInputPrice 
			 ,ControlCode,PersonID1,@Serverid ,YearID ,UnitSellPrice ,TotallSellPrice,SpecialCode 
	  		FROM #YearStuff
	  		WHERE  StoreID=@StoreID 
			          --and Serverid = @Serverid 
					  and yearid=@yearidTO 
	  		
	  	  		

     FETCH NEXT FROM C INTO @StoreID --,@Serverid
END


CLOSE C
DEALLOCATE C
                                      
                  
end ------end if	



 IF (@customer  =1 )
  
BEGIN 

SELECT   @DEL=count(PersonID1)
FROM         RemainsEarly
where PersonID1  not in ((SELECT CustID FROM Customers INNER JOIN
							CustomersGroup ON Customers.CustomerGrpID = CustomersGroup.CustomerGrpID
								WHERE (CustomersGroup.GroupType IN (1, 2)))) and yearid=@yearidto 
IF (@DEL<>0)
 BEGIN
 
DELETE FROM RemainsEarly
WHERE     (YearID = @yearidto) AND (PersonID1 not IN
                          ((SELECT     Customers.CustID
                              FROM          Customers INNER JOIN
                                                     CustomersGroup ON Customers.CustomerGrpID = CustomersGroup.CustomerGrpID
                              WHERE      (CustomersGroup.GroupType IN (1, 2)))))
 END

INSERT INTO RemainsEarly (YearID, PersonID1, Rate,InfoKind,SellsEmporium)

SELECT     @yearidto,CustomerID1 AS PersonID1, SUM(bed - bes) AS balance,0,SellsEmporium
FROM         dbo.AllAccount(10, - 1, - 1, - 1, DEFAULT, DEFAULT, '', DEFAULT, '', @yearidfrom,
               @yearidfrom,0,999999,0,999999, DEFAULT) AS AllAcc

			
WHERE	CustomerID1 NOT IN (SELECT     Customers.CustID
							FROM         Customers INNER JOIN
							CustomersGroup ON Customers.CustomerGrpID = CustomersGroup.CustomerGrpID
							WHERE     (CustomersGroup.GroupType IN (1, 2)))
GROUP BY CustomerID1,SellsEmporium
ORDER BY CustomerID1



END ----ENDIF



END ---END SP
