CREATE PROCEDURE dbo.USP_NEWYEARE_check (@BAcheck int,@Scheck int,@Bcheck int,
                                         @Tcheck int, @Socheck int,@yearidfrom int, @yearidto int ,@VaGOzarBeMoshtaricheck int,@DaryafteSofte int ,@DaryafteZemanatNaame int
										 , @chkBank1 int, @chkCash2 int ,@chkLoan7 int  ,  @chkSupplier17 int, @assigned_legal int)
										 

AS


begin
set nocount on
 
DECLARE @serverid int
DECLARE @Customerid1 INT
DECLARE @Customerid2 INT
DECLARE @SellsEmporium INT
DECLARE @DEL INT
DECLARE @DATEFROM Char(10)
DECLARE @DATETO Char(10)
DECLARE @DateFromRemain char(10)
DECLARE @FORMID1 INT 
DECLARE @FORMNO1 INT 
DECLARE @DATEFORM Char(10)
DECLARE @MAXITEM1 INT
DECLARE @SUMC MONEY
-------------------------------------------------------------------------------------

SELECT  @SUMC = SUM(ISNULL(FirstBalance, 0)) 
FROM         Customers

IF @SUMC <>0 

BEGIN 
INSERT INTO RemainsEarly (YearID, PersonID1, Rate,InfoKind,Note)

SELECT     @yearidTo ,CustID, FirstBalance,0,'انتقالي از مانده معرفي مشتريان '
FROM         Customers
WHERE     (FirstBalance IS NOT NULL) AND (FirstBalance <> 0)

UPDATE Customers 
	SET FirstBalance= 0

END 

	DECLARE  @YearF char(4)
	if len(ltrim(@yearidfrom))=2 
	  set  @YearF='13'+ltrim(@yearidfrom)
    else
	  set  @YearF=ltrim(@yearidfrom)

	DECLARE  @YearT char(4)
	if len(ltrim(@yearidto))=2 
	  set  @YearT='13'+ltrim(@yearidto)
    else
	  set  @YearT=ltrim(@yearidto)


 SET @DATEFROM =RIGHT( @YearF+'/01/01',10)
 SET @DATETO=RIGHT(@YearF+'/12/29',10)

SET @DateFromRemain=dbo.miladitoshamsi(DATEADD( day,-1,dbo.ShamsiToMiladi(@DATEFROM)))



-------------------------------------mande bankha va sandoogh  @chkCash int,  @chkSupplier int ,@chkLoan
 
IF (@chkBank1=1)or(@chkCash2=1)or(@chkSupplier17=1)or(@chkLoan7=1)

BEGIN
SELECT   @DEL=count(PersonID1)
FROM         RemainsEarly
where PersonID1 in ((SELECT CustID FROM Customers INNER JOIN
							CustomersGroup ON Customers.CustomerGrpID = CustomersGroup.CustomerGrpID
								WHERE (CustomersGroup.GroupType IN (@chkBank1, @chkCash2,@chkLoan7,@chkSupplier17)))) and yearid=@yearidto 
IF (@DEL<>0)
 BEGIN
 
DELETE FROM RemainsEarly
WHERE     (YearID = @yearidto) AND (PersonID1 IN
                          ((SELECT     Customers.CustID
                              FROM          Customers INNER JOIN
                                                     CustomersGroup ON Customers.CustomerGrpID = CustomersGroup.CustomerGrpID
                              WHERE      (CustomersGroup.GroupType IN (@chkBank1,@chkCash2,@chkLoan7,@chkSupplier17)))))
 END



 
 INSERT INTO RemainsEarly (YearID, PersonID1, Rate,InfoKind)
	

	
	
	SELECT @yearidto,customerid1,ISNULL( SUM(bed -bes) ,0),0
	FROM  AllAccount(1,2,10,-1, 1 ,999999999,@DATEFROM ,@DATETO ,
                    @DateFromRemain , @yearidfrom ,@yearidfrom ,0,999999,0,999999 , DEFAULT)
	WHERE   customerid1 IN ((SELECT CustID FROM Customers INNER JOIN
							CustomersGroup ON Customers.CustomerGrpID = CustomersGroup.CustomerGrpID
								WHERE (CustomersGroup.GroupType IN (@chkBank1, @chkCash2,@chkLoan7,@chkSupplier17))))                          
	GROUP BY  customerid1
                    
 
 
 
 
END----END IF 


