create table #FormItems(
	FormItemID int NOT NULL,
	FormID int NOT NULL,
	Row int NOT NULL,
	CheckNumber char(20) ,
	CheckDate VARchar(10) ,
	CheckType tinyint ,
	ItemAmount money ,
	ItemNote varchar(255) ,
	BankName varchar(20) ,
	FCustomerID1 int ,
	FCustomerID2 int ,
	SellsEmporium int ,
	City char(20) ,
	CustomerID2D int ,
	AccountNumberNew varchar(60) ,
	AccountNumber char(25) ,
	CheckState tinyint NOT NULL,
	CheckFor varchar(255) ,	
	ServerID int NOT NULL,
	FORMTYPE int NOT NULL,
	YEARID int NOT NULL,

    TopicCode bigint ,
	DetailCode varchar(12) ,
	CTopicCode varchar(12) ,
	CTopicCode2 varchar(12) ,
	ProjectID int ,
	AidInfoNo varchar(40) ,
	AidInfoDate Char(10) ,
	AmountArz float ,
	BudgetCode int ,
	CashWage money ,
	AccState tinyint ,
	ItemState tinyint NOT NULL,
	ItemStateComment nvarchar(200) ,
	SeverableAmount tinyint NOT NULL,
	VAT money NOT NULL,
	AccountNumberNew1 varchar(60) ,
	TopicTypesI int ,
	CTopicCode3 varchar(12) NOT NULL,
	ArzTypeID int ,
	ArzAmount money NOT NULL,
	ArzRate float ,
	DayDelay int ,
	AmountDelay decimal(18, 4) NOT NULL,
	CheckCounter int ,
	ProductCode bigint ,
	LineCorrosion bit NULL,
	VatCo float NULL,
	PO varchar(30) NULL,
	HunterCode char(20) NULL,
    OtherNationalCode varchar(12) NULL,
	SyadSystem bit NOT NULL,
	InsertDatei datetime NULL,
	ArzAmountExchange money NOT NULL,
	ArzRateExchange float NOT NULL,
	ArzTypeIDExchange int NULL,
	SwiftCode varchar(20) NULL,
	IBAN varchar(40) NULL,

	idkey int IDENTITY(1,1) NOT NULL
)


INSERT INTO #FormItems (FormItemID,FormID,Row,CheckNumber,CheckDate,CheckType,
ItemAmount,ItemNote,BankName,City,
CustomerID2D,AccountNumberNew,AccountNumber,CheckState,CheckFor,
ServerID,FormType,YEARID,FCustomerID1,FCustomerID2 ,SellsEmporium
, TopicCode, DetailCode, CTopicCode, CTopicCode2, ProjectID, 
AidInfoNo, AidInfoDate, AmountArz, BudgetCode, CashWage, AccState, ItemState, 
ItemStateComment, SeverableAmount, VAT, AccountNumberNew1, TopicTypesI, CTopicCode3, ArzTypeID, 
ArzAmount, ArzRate, DayDelay, AmountDelay, CheckCounter, ProductCode, LineCorrosion, VatCo, PO, HunterCode, OtherNationalCode, SyadSystem, InsertDatei 
,ArzAmountExchange ,ArzRateExchange ,	ArzTypeIDExchange ,	SwiftCode ,	IBAN 



)
 
 
SELECT      FormItems.FormItemID,FormItems.FormID,FormItems.Row,FormItems.CheckNumber,FormItems.CheckDate,FormItems.CheckType,
FormItems.ItemAmount,FormItems.ItemNote,FormItems.BankName,FormItems.City,
FormItems.CustomerID2,FormItems.AccountNumberNew ,FormItems.AccountNumber,FormItems.CheckState, FormItems.CheckFor,
FormItems.ServerID,Forms.FormType,FormItems.YearID,Forms.CustomerID1 ,Forms.CustomerID2 ,Forms.SellsEmporium
, FormItems.TopicCode, FormItems.DetailCode, FormItems.CTopicCode, FormItems.CTopicCode2, FormItems.ProjectID,  
FormItems.AidInfoNo, FormItems.AidInfoDate, FormItems.AmountArz, FormItems.BudgetCode, FormItems.CashWage, FormItems.AccState, FormItems.ItemState, 
FormItems.ItemStateComment, FormItems.SeverableAmount, FormItems.VAT, FormItems.AccountNumberNew1, FormItems.TopicTypesI, FormItems.CTopicCode3, FormItems.ArzTypeID, 
FormItems.ArzAmount, FormItems.ArzRate, FormItems.DayDelay, FormItems.AmountDelay, FormItems.CheckCounter, FormItems.ProductCode, FormItems.LineCorrosion, FormItems.VatCo, FormItems.PO
, FormItems.HunterCode, OtherNationalCode, SyadSystem, InsertDatei,FormItems.ArzAmountExchange ,FormItems.ArzRateExchange ,	FormItems.ArzTypeIDExchange ,	SwiftCode ,	IBAN


                      
FROM         FormItems INNER JOIN
                      Forms ON FormItems.FormID = Forms.FormID AND FormItems.ServerID = Forms.ServerID AND 
                      FormItems.YearID = Forms.YearID INNER JOIN
                      dbo.FormTypes ON Forms.FormType = dbo.FormTypes.FormType LEFT OUTER JOIN
                      dbo.Customers AS Customers_2 ON FormItems.CustomerID2 = Customers_2.CustID LEFT OUTER JOIN
                      dbo.Customers AS Customers_1 ON Forms.CustomerID1 = Customers_1.CustID LEFT OUTER JOIN
                      (select FormItemID,preFormItemID from FormItems where YearID=@YEARIDFROM) AS FormItems_1 
					              ON FormItems.FormItemID = FormItems_1.preFormItemID
WHERE     (FormItems_1.preFormItemID IS NULL) AND (FormItems.YearID=@YEARIDFROM)
     AND (Forms.FormState <>10)
ORDER BY FormItems.CheckDate



IF (@Scheck=1)

BEGIN


----------------------------------



DECLARE C CURSOR for
SELECT  DISTINCT SERVERID,CustomerID1,CustomerID2,SellsEmporium
FROM  FormS 
WHERE     (FormType IN (10, 15, 21, 105,29)) 
ORDER BY SERVERID 

OPEN C

FETCH NEXT FROM C INTO @Serverid,@Customerid1 ,@Customerid2,@SellsEmporium

	WHILE @@FETCH_STATUS =0
	
	BEGIN 
	
	SELECT  @FORMID1=ISNULL(MAX (FORMID),1)+1 FROM FORMS WHERE YEARID=@YEARIDTO
	
	SELECT  @FORMNO1=ISNULL(MAX (FormNumber),1)+1 FROM FORMS WHERE YEARID=@YEARIDTO AND FormType =21
	
	
	SET  @DATEFORM =RIGHT(@YearT +'/01/01',10)
	
	SELECT @MAXITEM1= ISNULL (MAX (FORMITEMID),1) FROM FORMITEMS WHERE YEARID=@YEARIDTO
 
	
 
 
 INSERT INTO FORMS(FormID, FormType, FormNumber, FormDate, CustomerID1,CustomerID2,SellsEmporium, ModifyDate, ServerID, YearID,amount,BudgetCode)
 
 
	SELECT DISTINCT 	@FORMID1,21,@FORMNO1,@DATEFORM,FCustomerID1,FCustomerID2,SellsEmporium, GETDATE(),@SERVERID,@YEARIDTO,0,0
	FROM         #FormItems
	WHERE     (FormType IN (10, 15, 21, 105,29)) AND (FCustomerID1=@Customerid1) AND (FCustomerID2=@Customerid2) AND(SellsEmporium=@SellsEmporium) AND (SERVERID=@SERVERID )  
 
 
INSERT INTO FormItems (FormItemID,FormID,Row,CheckNumber,CheckDate,CheckType,
ItemAmount,ItemNote,BankName,City,
CustomerID2,AccountNumberNew,AccountNumber,CheckState,CheckFor,ServerID,YEARID
, TopicCode, DetailCode, CTopicCode, CTopicCode2, ProjectID,
AidInfoNo, AidInfoDate, AmountArz, BudgetCode, CashWage, AccState, ItemState, 
ItemStateComment, SeverableAmount, VAT, AccountNumberNew1, TopicTypesI, CTopicCode3, ArzTypeID, 
ArzAmount, ArzRate, DayDelay, AmountDelay, CheckCounter, ProductCode, LineCorrosion, VatCo, PO, HunterCode, OtherNationalCode, SyadSystem, InsertDatei,
ArzAmountExchange ,ArzRateExchange ,	ArzTypeIDExchange ,	SwiftCode ,	IBAN

)
 
 
 SELECT  @MAXITEM1+idkey,@FORMID1,Row,CheckNumber,CheckDate,CheckType,
ItemAmount,ItemNote,BankName,City,
CustomerID2D,AccountNumberNew,AccountNumber,CheckState,CheckFor,@Serverid,@YEARIDTO
, TopicCode, DetailCode, CTopicCode, CTopicCode2, ProjectID,  
AidInfoNo, AidInfoDate, AmountArz, BudgetCode, CashWage, AccState, ItemState, 
ItemStateComment, SeverableAmount, VAT, AccountNumberNew1, TopicTypesI, CTopicCode3, ArzTypeID, 
ArzAmount, ArzRate, DayDelay, AmountDelay, CheckCounter, ProductCode, LineCorrosion, VatCo, PO, HunterCode, OtherNationalCode, SyadSystem, InsertDatei,
ArzAmountExchange ,ArzRateExchange ,	ArzTypeIDExchange ,	SwiftCode ,	IBAN

 
 FROM        #FormItems 
 WHERE     (FormType IN (10, 15, 21, 105,29)) AND (FCustomerID1=@Customerid1) AND (FCustomerID2=@Customerid2)AND(SellsEmporium=@SellsEmporium)  AND (SERVERID=@SERVERID )
 
  FETCH NEXT FROM C INTO @Serverid,@Customerid1,@Customerid2,@SellsEmporium
 
 END


CLOSE C
DEALLOCATE C



END 


--------------------------------NAZDE BANK------------------------------------------

-----------------------------------
IF (@Bcheck=1)

BEGIN

DECLARE C CURSOR for
SELECT  DISTINCT SERVERID,CustomerID1,CustomerID2,SellsEmporium
FROM  FormS 
WHERE     (FormType IN (11,22,19)) 
ORDER BY SERVERID 

OPEN C

FETCH NEXT FROM C INTO @Serverid,@Customerid1 ,@Customerid2,@SellsEmporium

	WHILE @@FETCH_STATUS =0
	
	BEGIN 
	
	SELECT  @FORMID1=ISNULL(MAX (FORMID),1)+1 FROM FORMS WHERE (YEARID=@YEARIDTO)

	SELECT  @FORMNO1=ISNULL(MAX (FormNumber),1)+1 FROM FORMS WHERE (YEARID=@YEARIDTO) AND (FormType =22)
	SET  @DATEFORM =RIGHT(@YearT +'/01/01',10)
	SELECT @MAXITEM1= ISNULL (MAX (FORMITEMID),1) FROM FORMITEMS WHERE (YEARID=@YEARIDTO)
 
	
 
 
 INSERT INTO FORMS(FormID, FormType, FormNumber, FormDate, CustomerID1,CustomerID2,SellsEmporium, ModifyDate, ServerID, YearID,amount,BudgetCode)
 
 
	SELECT DISTINCT 	@FORMID1,22,@FORMNO1,@DATEFORM,FCustomerID1,FCustomerID2,SellsEmporium, GETDATE(),@SERVERID,@YEARIDTO,0,0
	FROM         #FormItems
	WHERE     (FormType IN (11,22,19)) AND (FCustomerID1=@Customerid1) AND (FCustomerID2=@Customerid2)AND(SellsEmporium=@SellsEmporium) AND (SERVERID=@SERVERID  )
 
 
 
INSERT INTO FormItems (FormItemID,FormID,Row,CheckNumber,CheckDate,CheckType,
