	WHILE @@FETCH_STATUS =0
	
	BEGIN 
	
	SELECT  @FORMID1=ISNULL(MAX (FORMID),1)+1 FROM FORMS WHERE YEARID=@YEARIDTO

	SELECT  @FORMNO1=ISNULL(MAX (FormNumber),1)+1 FROM FORMS WHERE YEARID=@YEARIDTO AND FormType =184
	SET  @DATEFORM =RIGHT(@YearT+'/01/01',10)
	SELECT @MAXITEM1= ISNULL (MAX (FORMITEMID),1) FROM FORMITEMS WHERE YEARID=@YEARIDTO
 
	
 
 
 INSERT INTO FORMS(FormID, FormType, FormNumber, FormDate, CustomerID1,CustomerID2,SellsEmporium, ModifyDate, ServerID, YearID,amount,BudgetCode)
 
 
	SELECT DISTINCT 	@FORMID1,184,@FORMNO1,@DATEFORM,FCustomerID1,FCustomerID2,SellsEmporium, GETDATE(),@SERVERID,@YEARIDTO,0,0
	FROM         #FormItems
	WHERE     (FormType IN (183,184)) AND (FCustomerID1=@Customerid1) AND (FCustomerID2=@Customerid2)AND(SellsEmporium=@SellsEmporium) AND (SERVERID=@SERVERID  )  
 
 
 
INSERT INTO FormItems (FormItemID,FormID,Row,CheckNumber,CheckDate,CheckType,
ItemAmount,ItemNote,BankName,City,
CustomerID2,AccountNumberNew,AccountNumber,CheckState,CheckFor,ServerID,YEARID
, TopicCode, DetailCode, CTopicCode, CTopicCode2, ProjectID,  
AidInfoNo, AidInfoDate, AmountArz, BudgetCode, CashWage, AccState, ItemState, 
ItemStateComment, SeverableAmount, VAT, AccountNumberNew1, TopicTypesI, CTopicCode3, ArzTypeID, 
ArzAmount, ArzRate, DayDelay, AmountDelay, CheckCounter, ProductCode, LineCorrosion, VatCo, PO, HunterCode, OtherNationalCode, SyadSystem, InsertDatei,
ArzAmountExchange ,ArzRateExchange ,	ArzTypeIDExchange ,	SwiftCode ,	IBAN
)
 
 
 SELECT  @MAXITEM1+idkey,@FORMID1,Row,CheckNumber,CheckDate,CheckType,
ItemAmount,ItemNote,BankName,City,
CustomerID2D,AccountNumberNew,AccountNumber,CheckState,CheckFor,@Serverid,@YEARIDTO
, TopicCode, DetailCode, CTopicCode, CTopicCode2, ProjectID,  
AidInfoNo, AidInfoDate, AmountArz, BudgetCode, CashWage, AccState, ItemState, 
ItemStateComment, SeverableAmount, VAT, AccountNumberNew1, TopicTypesI, CTopicCode3, ArzTypeID, 
ArzAmount, ArzRate, DayDelay, AmountDelay,  CheckCounter, ProductCode, LineCorrosion, VatCo, PO, HunterCode, OtherNationalCode, SyadSystem, InsertDatei,
ArzAmountExchange ,ArzRateExchange ,	ArzTypeIDExchange ,	SwiftCode ,	IBAN

 
 FROM        #FormItems 
 WHERE     (FormType IN (183,184)) AND (FCustomerID1=@Customerid1) AND (FCustomerID2=@Customerid2)AND(SellsEmporium=@SellsEmporium) AND (SERVERID=@SERVERID  )
 
  FETCH NEXT FROM C INTO @Serverid,@Customerid1,@Customerid2,@SellsEmporium
 
 END


CLOSE C
DEALLOCATE C
END 
