-------------------------------------On ReciptItems For Delete

CREATE TRIGGER TR_NotAllowDeleteTrans1OnRItems
ON ReciptItems AFTER DELETE
AS
begin
SET NOCOUNT ON;
    -- شرط اول: اگر فرم ارسال شده باشد (Transmittal IN(1,3))
    IF EXISTS (
        SELECT 1
        FROM deleted d
        INNER JOIN Recipts r 
            ON d.ReciptID = r.ReciptID 
            AND d.ServerID = r.ServerID 
            AND d.YearID = r.YearID 
        WHERE r.Transmittal IN (1, 3)
    )
    BEGIN
        RAISERROR('اطلاعات پس از ارسال شدن قابل حذف نمی باشد', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

    -- شرط دوم: اگر ReciptItemID در preReciptItemID سطرهای دیگر استفاده شده باشد
    IF EXISTS (
        SELECT 1
        FROM deleted d
        WHERE EXISTS (
            SELECT 1
            FROM ReciptItems ri
            WHERE ri.preReciptItemID = d.ReciptItemID
          --  AND ri.ReciptID = d.ReciptID
              AND ri.ServerID = d.ServerID
              AND ri.YearID = d.YearID
        )
    )
    BEGIN
        RAISERROR('این ردیف در فرم های دیگر فراخوانی شده و قابل حذف نیست.', 16, 1);
        ROLLBACK TRANSACTION;
        RETURN;
    END

end
