CREATE  FUNCTION  CalcLoan (@YearMounth char(7) ='1493/03' ,@FormDate Char(10) ='1493/03/18')
RETURNS bigint
AS
BEGIN
DECLARE @Price MONEY


SELECT @Price=SUM(ItemAmount) FROM (
---   محاسبه سند پرداخت هزينه و سود بانكي سپردهها
SELECT        SUM(case when Forms.FormType=104 then -FormItems.ItemAmount else FormItems.ItemAmount end) AS ItemAmount
FROM            Forms INNER JOIN
                         FormItems ON Forms.FormID = FormItems.FormID AND Forms.ServerID = FormItems.ServerID AND Forms.YearID = FormItems.YearID
WHERE        (Forms.FormType in( 104,112 )  ) AND (LEFT(RIGHT(FormItems.CheckDate, 10), 7)  = @YearMounth)
---   محاسبه سند پرداخت هزينه و سود بانكي سپردهها

UNION ALL
------     محاسبه  فرع وام 
SELECT        SUM(FormItems.CashWage) AS AmountDelay
FROM            Forms INNER JOIN
                         FormItems ON Forms.FormID = FormItems.FormID AND Forms.ServerID = FormItems.ServerID AND Forms.YearID = FormItems.YearID
WHERE        (Forms.FormType IN( 110,111)) AND ( LEFT(RIGHT(FormItems.CheckDate, 10), 7)  = @YearMounth)
------     محاسبه  فرع وام 

UNION ALL
------     محاسبه جرائم 
SELECT        SUM(Amount) AS Amount
FROM            Forms 
WHERE        (Forms.FormType = 113) AND (LEFT(RIGHT(FormDate, 10), 7)  = @YearMounth) 
------     محاسبه جرائم 

--UNION ALL

-----         محاسبه جريمه دير كرد سهام
--SELECT        SUM(dbo.GetAmountDelay(DATEDIFF(day, dbo.ShamsiToMiladi(@FormDate), dbo.ShamsiToMiladi(FormItems.CheckDate)), FormItems.ItemAmount)) AS Expr3
--FROM            Forms INNER JOIN
--                         FormItems ON Forms.FormID = FormItems.FormID AND Forms.ServerID = FormItems.ServerID AND Forms.YearID = FormItems.YearID
--WHERE        (Forms.FormType = 103) AND ( LEFT(RIGHT(FormItems.CheckDate, 10), 7)  = @YearMounth)
-----         محاسبه جريمه دير كرد سهام
)abcd



RETURN (@Price)

END
