CREATE VIEW [dbo].[View_SahamVaSoodTaghsimi]
AS
SELECT        FormItems.CustomerID2, CAST(SUM(CASE WHEN Forms.FormType IN (103, 114) 
                         THEN FormItems.ItemAmount ELSE - (FormItems.ItemAmount + ISNULL(FormItems.CashWage, 0)) END) AS float) AS ItemAmount
FROM            dbo.FormItems AS FormItems INNER JOIN
                         dbo.Forms AS Forms ON FormItems.FormID = Forms.FormID AND FormItems.ServerID = Forms.ServerID AND FormItems.YearID = Forms.YearID
WHERE        (Forms.FormType IN (103, 114, 2, 111))
GROUP BY FormItems.CustomerID2

