CREATE PROCEDURE NewTransForms @OldTransFormID int, @TransFormID int OUTPUT as
begin
SET NOCOUNT ON
DECLARE @ID int
DECLARE @ProcessProduceID int
DECLARE @TransFormNo int
DECLARE   @Query varchar(8000)
DECLARE   @ColumnsName varchar(8000)
SET @ColumnsName = dbo.S_F_GetColumnsName('TransForms')
SET @Query='INSERT INTO TransForms  ('+@ColumnsName+')'

SET @ColumnsName = REPLACE(@ColumnsName,' TransFormID,','')
SET @TransFormID=(SELECT MAX(TransFormID)+1 FROM TransForms)

SET @ColumnsName = REPLACE(@ColumnsName,' TransFormNo,','')
SET @TransFormNo=(SELECT MAX(TransFormNo)+1 FROM TransForms)

SET @Query=@Query+' SELECT '+str(@TransFormID)+', '+str(@TransFormNo)+', '+@ColumnsName+'
              FROM  TransForms WHERE (TransFormID = '+str(@OldTransFormID)+')'

Exec (@Query)

SET @ID=  (SELECT MAX(ID)+1  FROM TransFormItems)
SET @ColumnsName =' ID,'+  dbo.S_F_GetColumnsName('TransFormItems')
SET @ColumnsName = REPLACE(@ColumnsName,' TransFormID,',str(@TransFormID)+' AS TransFormID, ')
SET @ColumnsName = REPLACE(@ColumnsName,' ID,','IDENTITY(int, 1,1) AS ID,')

set @Query='SELECT '+@ColumnsName+'
            INTO ##NewTable
            FROM  TransFormItems WHERE (TransFormID = '+str(@OldTransFormID)+')'

Exec (@Query)



SET @ColumnsName =' ID,'+ dbo.S_F_GetColumnsName('TransFormItems')
SET @Query='INSERT INTO TransFormItems    ('+@ColumnsName+')'
SET @ColumnsName = REPLACE(@ColumnsName,' ID,','ID+'+STR(@ID)+' AS ID,')
SET @Query=@Query+'SELECT '+@ColumnsName+' FROM ##NewTable'

Exec (@Query)

----------------------------------------ProcessProduce-------------------------------------------------
SET @ProcessProduceID=  (SELECT MAX(ProcessProduceID)+1  FROM ProcessProduce)


SET @ColumnsName = dbo.S_F_GetColumnsName('ProcessProduce')
SET @ColumnsName = REPLACE(@ColumnsName,' TransFormID',str(@TransFormID)+' AS TransFormID ')
SET @ColumnsName = REPLACE(@ColumnsName,' ProcessProduceID,','IDENTITY(int, 1,1) AS ProcessProduceID,')

set @Query='SELECT '+@ColumnsName+'
            INTO ##NewTable2
            FROM  ProcessProduce WHERE (TransFormID = '+str(@OldTransFormID)+')'

Exec (@Query)


SET @ColumnsName = dbo.S_F_GetColumnsName('ProcessProduce')
set @Query='INSERT INTO ProcessProduce    ('+@ColumnsName+')'
SET @ColumnsName = REPLACE(@ColumnsName,' ProcessProduceID,','ProcessProduceID+'+STR(@ProcessProduceID)+' AS ProcessProduceID,')

set @Query=@Query+'SELECT '+@ColumnsName+' FROM ##NewTable2'
Exec (@Query)

------------------------------------------ProcessProduce----------------------------------------------
RETURN(@TransFormID)
END


