CREATE  FUNCTION ProductionForecasts (
 @TransFormID1 int =1,@TransFormID2 int =2 ,@TransFormID3 int =3 ,
 @TransFormID4 int =4 ,@TransFormID5 int =5 ,@TransFormID6 int =6,
 @Edit1 int =1,@Edit2 int =2 ,@Edit3 int =3 ,
 @Edit4 int =4 ,@Edit5 int =5 ,@Edit6 int =6  )

RETURNS table  AS  
return (
SELECT	TransFormItems.StuffCode, StuffCoding.c_StuffName, Units.UnitName,
	sum(case when TransFormItems.TransFormID = @TransFormID1 then ISNULL(TransFormItems.Entity, 0) else 0 end) as Formol1 ,
	sum(case when TransFormItems.TransFormID = @TransFormID1 then ISNULL(TransFormItems.Entity, 0) * @Edit1 else 0 end) as Entity1 ,
	sum(case when TransFormItems.TransFormID = @TransFormID2 then ISNULL(TransFormItems.Entity, 0) else 0 end) as Formol2 ,
	sum(case when TransFormItems.TransFormID = @TransFormID2 then ISNULL(TransFormItems.Entity, 0) * @Edit2 else 0 end) as Entity2 ,
	sum(case when TransFormItems.TransFormID = @TransFormID3 then ISNULL(TransFormItems.Entity, 0) else 0 end) as Formol3 ,
	sum(case when TransFormItems.TransFormID = @TransFormID3 then ISNULL(TransFormItems.Entity, 0) * @Edit3 else 0 end) as Entity3 ,
	sum(case when TransFormItems.TransFormID = @TransFormID4 then ISNULL(TransFormItems.Entity, 0) else 0 end) as Formol4 ,
	sum(case when TransFormItems.TransFormID = @TransFormID4 then ISNULL(TransFormItems.Entity, 0) * @Edit4 else 0 end) as Entity4 ,
	sum(case when TransFormItems.TransFormID = @TransFormID5 then ISNULL(TransFormItems.Entity, 0) else 0 end) as Formol5 ,
	sum(case when TransFormItems.TransFormID = @TransFormID5 then ISNULL(TransFormItems.Entity, 0) * @Edit5 else 0 end) as Entity5 ,
	sum(case when TransFormItems.TransFormID = @TransFormID6 then ISNULL(TransFormItems.Entity, 0) else 0 end) as Formol6 ,
	sum(case when TransFormItems.TransFormID = @TransFormID6 then ISNULL(TransFormItems.Entity, 0) * @Edit6 else 0 end) as Entity6 
FROM	TransFormItems INNER JOIN
	StuffCoding ON TransFormItems.StuffCode = StuffCoding.c_StuffCode INNER JOIN
	Units ON StuffCoding.n_UnitCode = Units.UnitCode  
WHERE        (TransFormItems.InfoType = 0) and 	TransFormItems.TransFormID in(@TransFormID1,@TransFormID2,@TransFormID3,
@TransFormID4,@TransFormID5,@TransFormID6)
GROUP BY TransFormItems.StuffCode, StuffCoding.c_StuffName, Units.UnitName

---------------------------------------- ProductionForecasts -----------------------------------------------------------------
)

