CREATE  FUNCTION ProductionForecasts4Lbl (
 @TransFormID1 int =1,@TransFormID2 int =2 ,@TransFormID3 int =3 ,
 @TransFormID4 int =4 ,@TransFormID5 int =5 ,@TransFormID6 int =6,
 @Edit1 int =1,@Edit2 int =2 ,@Edit3 int =3 ,
 @Edit4 int =4 ,@Edit5 int =5 ,@Edit6 int =6  )

RETURNS table  AS  
return (

SELECT        1 AS Label, MIN(Formol1) AS Formol1
FROM            (SELECT        CASE WHEN ProductionForecasts.Formol1 <> 0 THEN (ISNULL(derivedtbl_Mojodi.SUMEntity, 0) 
                                                    - ProductionForecasts.Entity1 - ProductionForecasts.Entity2 - ProductionForecasts.Entity3 - ProductionForecasts.Entity4 - ProductionForecasts.Entity5 -
                                                     ProductionForecasts.Entity6) / ProductionForecasts.Formol1 ELSE 0 END AS Formol1
                           FROM            dbo.ProductionForecasts(
 @TransFormID1,@TransFormID2,@TransFormID3, @TransFormID4  ,@TransFormID5  ,@TransFormID6 ,
 @Edit1,@Edit2  ,@Edit3  , @Edit4  ,@Edit5  ,@Edit6)
                                                     AS ProductionForecasts LEFT OUTER JOIN
                                                        (SELECT        ReciptItems.StuffCode, ROUND(SUM(ReciptItems.InputEntity - ReciptItems.OutputEntity), 3) AS SUMEntity
                                                           FROM            ReciptItems INNER JOIN
                                                                                    Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND 
                                                                                    ReciptItems.YearID = Recipts.YearID INNER JOIN
                                                                                    ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType INNER JOIN
                                                                                    Stores ON Recipts.StoreID = Stores.n_StoreID
                                                           WHERE        (ReciptTypes.EffectType IN (2, 4)) AND (Recipts.ReciptState < 3)
                                                           GROUP BY ReciptItems.StuffCode) AS derivedtbl_Mojodi ON ProductionForecasts.StuffCode = derivedtbl_Mojodi.StuffCode
                           WHERE        (ProductionForecasts.Formol1 <> 0)) AS derivedtbl_1

UNION ALL

SELECT        2 AS Label, MIN(Formol2) AS Formol2
FROM            (SELECT        CASE WHEN ProductionForecasts.Formol2 <> 0 THEN (ISNULL(derivedtbl_Mojodi.SUMEntity, 0) 
                                                    - ProductionForecasts.Entity1 - ProductionForecasts.Entity2 - ProductionForecasts.Entity3 - ProductionForecasts.Entity4 - ProductionForecasts.Entity5 -
                                                     ProductionForecasts.Entity6) / ProductionForecasts.Formol2 ELSE 0 END AS Formol2
                           FROM            dbo.ProductionForecasts(
@TransFormID1,@TransFormID2,@TransFormID3, @TransFormID4  ,@TransFormID5  ,@TransFormID6 ,
 @Edit1,@Edit2  ,@Edit3  , @Edit4  ,@Edit5  ,@Edit6)
 						        AS ProductionForecasts LEFT OUTER JOIN
                                                        (SELECT        ReciptItems.StuffCode, ROUND(SUM(ReciptItems.InputEntity - ReciptItems.OutputEntity), 3) AS SUMEntity
                                                           FROM            ReciptItems INNER JOIN
                                                                                    Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND 
                                                                                    ReciptItems.YearID = Recipts.YearID INNER JOIN
                                                                                    ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType INNER JOIN
                                                                                    Stores ON Recipts.StoreID = Stores.n_StoreID
                                                           WHERE        (ReciptTypes.EffectType IN (2, 4)) AND (Recipts.ReciptState < 3)
                                                           GROUP BY ReciptItems.StuffCode) AS derivedtbl_Mojodi ON ProductionForecasts.StuffCode = derivedtbl_Mojodi.StuffCode
                           WHERE        (ProductionForecasts.Formol2 <> 0)) AS derivedtbl_1
UNION ALL

SELECT        3 AS Label, MIN(Formol3) AS Formol3
FROM            (SELECT        CASE WHEN ProductionForecasts.Formol3 <> 0 THEN (ISNULL(derivedtbl_Mojodi.SUMEntity, 0) 
                                                    - ProductionForecasts.Entity1 - ProductionForecasts.Entity2 - ProductionForecasts.Entity3 - ProductionForecasts.Entity4 - ProductionForecasts.Entity5 -
                                                     ProductionForecasts.Entity6) / ProductionForecasts.Formol3 ELSE 0 END AS Formol3
                           FROM            dbo.ProductionForecasts(
 @TransFormID1,@TransFormID2,@TransFormID3, @TransFormID4  ,@TransFormID5  ,@TransFormID6 ,
 @Edit1,@Edit2  ,@Edit3  , @Edit4  ,@Edit5  ,@Edit6)
                                                     AS ProductionForecasts LEFT OUTER JOIN
                                                        (SELECT        ReciptItems.StuffCode, ROUND(SUM(ReciptItems.InputEntity - ReciptItems.OutputEntity), 3) AS SUMEntity
                                                           FROM            ReciptItems INNER JOIN
                                                                                    Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND 
                                                                                    ReciptItems.YearID = Recipts.YearID INNER JOIN
                                                                                    ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType INNER JOIN
                                                                                    Stores ON Recipts.StoreID = Stores.n_StoreID
                                                           WHERE        (ReciptTypes.EffectType IN (2, 4)) AND (Recipts.ReciptState < 3)
                                                           GROUP BY ReciptItems.StuffCode) AS derivedtbl_Mojodi ON ProductionForecasts.StuffCode = derivedtbl_Mojodi.StuffCode
                           WHERE        (ProductionForecasts.Formol3 <> 0)) AS derivedtbl_1

UNION ALL
SELECT        4 AS Label, MIN(Formol4) AS Formol4
FROM            (SELECT        CASE WHEN ProductionForecasts.Formol4 <> 0 THEN (ISNULL(derivedtbl_Mojodi.SUMEntity, 0) 
                                                    - ProductionForecasts.Entity1 - ProductionForecasts.Entity2 - ProductionForecasts.Entity3 - ProductionForecasts.Entity4 - ProductionForecasts.Entity5 -
                                                     ProductionForecasts.Entity6) / ProductionForecasts.Formol4 ELSE 0 END AS Formol4
                           FROM            dbo.ProductionForecasts(
 @TransFormID1,@TransFormID2,@TransFormID3, @TransFormID4  ,@TransFormID5  ,@TransFormID6 ,
 @Edit1,@Edit2  ,@Edit3  , @Edit4  ,@Edit5  ,@Edit6)
                                                     AS ProductionForecasts LEFT OUTER JOIN
                                                        (SELECT        ReciptItems.StuffCode, ROUND(SUM(ReciptItems.InputEntity - ReciptItems.OutputEntity), 3) AS SUMEntity
                                                           FROM            ReciptItems INNER JOIN
                                                                                    Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND 
                                                                                    ReciptItems.YearID = Recipts.YearID INNER JOIN
                                                                                    ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType INNER JOIN
                                                                                    Stores ON Recipts.StoreID = Stores.n_StoreID
                                                           WHERE        (ReciptTypes.EffectType IN (2, 4)) AND (Recipts.ReciptState < 3)
                                                           GROUP BY ReciptItems.StuffCode) AS derivedtbl_Mojodi ON ProductionForecasts.StuffCode = derivedtbl_Mojodi.StuffCode
                           WHERE        (ProductionForecasts.Formol4 <> 0)) AS derivedtbl_1
UNION ALL
SELECT        5 AS Label, MIN(Formol5) AS Formol5
FROM            (SELECT        CASE WHEN ProductionForecasts.Formol5 <> 0 THEN (ISNULL(derivedtbl_Mojodi.SUMEntity, 0) 
                                                    - ProductionForecasts.Entity1 - ProductionForecasts.Entity2 - ProductionForecasts.Entity3 - ProductionForecasts.Entity4 - ProductionForecasts.Entity5 -
                                                     ProductionForecasts.Entity6) / ProductionForecasts.Formol5 ELSE 0 END AS Formol5
                           FROM            dbo.ProductionForecasts(
 @TransFormID1,@TransFormID2,@TransFormID3, @TransFormID4  ,@TransFormID5  ,@TransFormID6 ,
 @Edit1,@Edit2  ,@Edit3  , @Edit4  ,@Edit5  ,@Edit6)
                                                     AS ProductionForecasts LEFT OUTER JOIN
                                                        (SELECT        ReciptItems.StuffCode, ROUND(SUM(ReciptItems.InputEntity - ReciptItems.OutputEntity), 3) AS SUMEntity
                                                           FROM            ReciptItems INNER JOIN
                                                                                    Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND 
                                                                                    ReciptItems.YearID = Recipts.YearID INNER JOIN
                                                                                    ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType INNER JOIN
                                                                                    Stores ON Recipts.StoreID = Stores.n_StoreID
                                                           WHERE        (ReciptTypes.EffectType IN (2, 4)) AND (Recipts.ReciptState < 3)
                                                           GROUP BY ReciptItems.StuffCode) AS derivedtbl_Mojodi ON ProductionForecasts.StuffCode = derivedtbl_Mojodi.StuffCode
                           WHERE        (ProductionForecasts.Formol5 <> 0)) AS derivedtbl_1
UNION ALL
SELECT        6 AS Label, MIN(Formol6) AS Formol6
FROM            (SELECT        CASE WHEN ProductionForecasts.Formol6 <> 0 THEN (ISNULL(derivedtbl_Mojodi.SUMEntity, 0) 
                                                    - ProductionForecasts.Entity1 - ProductionForecasts.Entity2 - ProductionForecasts.Entity3 - ProductionForecasts.Entity4 - ProductionForecasts.Entity5 -
                                                     ProductionForecasts.Entity6) / ProductionForecasts.Formol6 ELSE 0 END AS Formol6
                           FROM            dbo.ProductionForecasts(
 @TransFormID1,@TransFormID2,@TransFormID3, @TransFormID4  ,@TransFormID5  ,@TransFormID6 ,
 @Edit1,@Edit2  ,@Edit3  , @Edit4  ,@Edit5  ,@Edit6)
                                                     AS ProductionForecasts LEFT OUTER JOIN
                                                        (SELECT        ReciptItems.StuffCode, ROUND(SUM(ReciptItems.InputEntity - ReciptItems.OutputEntity), 3) AS SUMEntity
                                                           FROM            ReciptItems INNER JOIN
                                                                                    Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND 
                                                                                    ReciptItems.YearID = Recipts.YearID INNER JOIN
                                                                                    ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType INNER JOIN
                                                                                    Stores ON Recipts.StoreID = Stores.n_StoreID
                                                           WHERE        (ReciptTypes.EffectType IN (2, 4)) AND (Recipts.ReciptState < 3)
                                                           GROUP BY ReciptItems.StuffCode) AS derivedtbl_Mojodi ON ProductionForecasts.StuffCode = derivedtbl_Mojodi.StuffCode
                           WHERE        (ProductionForecasts.Formol6 <> 0)) AS derivedtbl_1

---------------------------------------- ProductionForecasts4Lbl -----------------------------------------------------------------
)

