CREATE FUNCTION dbo.Get3FirstType( @ReciptType INT, @PersonID INT)
RETURNS DECIMAL(10, 2)
AS
BEGIN
DECLARE @Price DECIMAL(10, 2)

SELECT @Price = SUM(ReciptItems.TotalOutputPrice)
FROM Recipts INNER JOIN
        ReciptItems ON Recipts.ReciptID = ReciptItems.ReciptID AND Recipts.ServerID = ReciptItems.ServerID AND Recipts.YearID = ReciptItems.YearID
WHERE  (Recipts.ReciptType = @ReciptType) AND (Recipts.PersonID1 = @PersonID ) 
           AND (Recipts.ReciptID IN(SELECT TOP 3 ReciptID FROM Recipts
									 WHERE (ReciptType = @ReciptType) AND (PersonID1 = @PersonID )
									 GROUP BY PersonID1, ReciptDate, ReciptID
									 ORDER BY PersonID1, ReciptDate, ReciptID))
RETURN (@Price)
END

