CREATE FUNCTION Fn_rptCompare_Count_Entity    ( @YearIDFrom int , @YearIDTo int, @Date char(10)
                                              , @StoreID int, @CountID int  ,@chkNoCountingItems Tinyint  )  
RETURNS  table  AS 
Return  (
SELECT     AllStuffCode.StoreID, AllStuffCode.StuffCode, StuffCoding.c_StuffName,StuffCoding.c_StuffTecInfo, Units.UnitName, StuffCodeCountingItems.StuffSize,
                      StuffCodeCountingItems.StuffDiameter, StuffCodeCountingItems.StuffAlloy, StuffCodeCountingItems.StuffGrade, StuffCodeCountingItems.ControlCode,

                      StuffCodeCountingItems.Count1Entity, StuffCodeCountingItems.Count1Weight, 
					  StuffCodeCountingItems.Count2Entity, StuffCodeCountingItems.Count2Weight, 
					  StuffCodeCountingItems.Count3Entity, StuffCodeCountingItems.Count3Weight, 
					  StuffCodeEntity.Entity, 
					  StuffCodeEntity.Weight, 
					  
					  StuffCodeEntity.Price,
					  case when ( ( @chkNoCountingItems = 1 ) and  StuffCodeCountingItems.CountID IS NULL )
					  			then StuffCodeEntity.Entity 
							else StuffCodeCountingItems.DifferEntity
					  end as DifferEntity , 

					  case when ( ( @chkNoCountingItems = 1 ) and  StuffCodeCountingItems.CountID IS NULL )
					  			then StuffCodeEntity.Weight 
							else StuffCodeCountingItems.DifferWeight
					  end as DifferWeight , 
					  CAST(
                      ROUND(ISNULL((CASE  WHEN ((StuffCodeEntity.Entity) =0 or (StuffCodeEntity.Entity) is null ) THEN StuffCoding.SellPrice1
                      ELSE  (StuffCodeEntity.Price / (StuffCodeEntity.Entity)) END) * 
					  
						( case when ( ( @chkNoCountingItems = 1 ) and  StuffCodeCountingItems.CountID IS NULL )
					  			then StuffCodeEntity.Entity 
								else StuffCodeCountingItems.DifferEntity
							end
						) 					  
					  , 0), 0)  as DECIMAL(30,0))
                      AS DifferPrice,
                      CAST(StuffCodeEntity.TotallSellPrice as DECIMAL(30,0)) TotallSellPrice,
                      CAST(ROUND(ISNULL((CASE  WHEN ((StuffCodeEntity.Entity) =0 or (StuffCodeEntity.Entity) is null ) THEN StuffCoding.SellPrice1
                      ELSE (CAST(StuffCodeEntity.TotallSellPrice as DECIMAL(30,0)) / (StuffCodeEntity.Entity)) END)  * 
					  
					  (
						case when ( ( @chkNoCountingItems = 1 ) and  StuffCodeCountingItems.CountID IS NULL )
					  			then StuffCodeEntity.Entity 
							else StuffCodeCountingItems.DifferEntity
						end 					  
					  )
					  
					  ,0), 0)   as DECIMAL(30,0))
                      AS DifferTotallSellPrice,
                      ROUND( ISNULL(
					  (
						case when ( ( @chkNoCountingItems = 1 ) and  StuffCodeCountingItems.CountID IS NULL )
					  			then StuffCodeEntity.Entity 
							else StuffCodeCountingItems.DifferEntity
						end 					  
					  )
					  , 0) - isnull(StuffCodeEntity.Entity,0),4) AS OtherEntity,
                      ROUND( ISNULL(
					  (
					    case when ( ( @chkNoCountingItems = 1 ) and  StuffCodeCountingItems.CountID IS NULL )
					  			then StuffCodeEntity.Weight 
							else StuffCodeCountingItems.DifferWeight
						end
					  )
					  
					  , 0) - isnull(StuffCodeEntity.Weight,0),4) AS OtherWeight,
                      ROUND(ISNULL((CASE  WHEN ((StuffCodeEntity.Entity) =0 or (StuffCodeEntity.Entity) is null ) THEN StuffCoding.SellPrice1
                      ELSE  (StuffCodeEntity.Price / (StuffCodeEntity.Entity)) END) * 
					  (
						  case when ( ( @chkNoCountingItems = 1 ) and  StuffCodeCountingItems.CountID IS NULL )
						  			then StuffCodeEntity.Entity 
								else StuffCodeCountingItems.DifferEntity
						  end 
					  )					  
					  
					  , 0), 0)
                      - isnull(StuffCodeEntity.Price,0) AS OtherPrice,
                     cast( ROUND(ISNULL((CASE  WHEN ((StuffCodeEntity.Entity) =0 or (StuffCodeEntity.Entity) is null ) THEN StuffCoding.SellPrice1
                      ELSE (CAST(StuffCodeEntity.TotallSellPrice as DECIMAL(30,0)) / (StuffCodeEntity.Entity)) END)  * 
					  
					  (
						  case when ( ( @chkNoCountingItems = 1 ) and  StuffCodeCountingItems.CountID IS NULL )
					  				then StuffCodeEntity.Entity 
								else StuffCodeCountingItems.DifferEntity
						  end 
					  )
					  
					  
					   ,0), 0)
                      - isnull( CAST(StuffCodeEntity.TotallSellPrice as DECIMAL(30,0)) ,0)   as DECIMAL(30,0))AS OtherTotallSellPrice, StuffCodeCountingItems.CountID , StuffCoding.SellPrice1
          , Stores.c_StoreName


FROM         Units INNER JOIN
                      StuffCoding ON Units.UnitCode = StuffCoding.n_UnitCode RIGHT OUTER JOIN
                          (SELECT     StoreID, StuffCode
                             FROM         CountingItems
                             UNION
                             SELECT     StoreID, StuffCode
                             FROM         dbo.StuffCodeEntity(@YearIDFrom , @YearIDTo , @Date) AS StuffCodeEntity) AS AllStuffCode LEFT OUTER JOIN
                      dbo.StuffCodeCountingItems(@YearIDFrom , @YearIDTo , @Date ) AS StuffCodeCountingItems ON AllStuffCode.StoreID = StuffCodeCountingItems.StoreID AND 
                      AllStuffCode.StuffCode = StuffCodeCountingItems.StuffCode ON StuffCoding.c_StuffCode = AllStuffCode.StuffCode LEFT OUTER JOIN
                      dbo.StuffCodeEntity( @YearIDFrom , @YearIDTo , @Date ) AS StuffCodeEntity ON AllStuffCode.StoreID = StuffCodeEntity.StoreID AND
                      AllStuffCode.StuffCode = StuffCodeEntity.StuffCode INNER JOIN
                         Stores ON AllStuffCode.StoreID = Stores.n_StoreID





WHERE     (AllStuffCode.StoreID = @StoreID) AND (StuffCodeCountingItems.CountID = @CountID OR
                      StuffCodeCountingItems.CountID IS NULL) 
)
