CREATE PROCEDURE NewReciptsSplitRecall4PersonID @ID12 bigint, @NewPersonID1 int=0,  @ReciptNumber bigint OUTPUT as
begin
/*تغییر کد مشتری و فرم های مرتبط و فراخوان شده
 پیدا کردن حواله از فاکتور و خروجی کالا از حواله  و بعد تغییر و تفکیک کد مشتری */
SET NOCOUNT ON
DECLARE @ID9 Bigint
DECLARE @COUNT12 int
DECLARE @COUNT9 int
DECLARE @ServerID int
DECLARE @YearID int
DECLARE @ReciptID int
DECLARE @ReciptType9 int

SELECT @ServerID=ServerID,@YearID=YearID  FROM Recipts WHERE (ID= @ID12)

SELECT  @ID9 =min(R9.id) ,@COUNT12 = COUNT(*),@ReciptType9=Max(R9.ReciptType),@ReciptNumber=Max(R9.ReciptType)
FROM            Recipts AS R12 INNER JOIN
                         Recipts AS R11 ON R12.ReciptID = R11.ParentReciptID AND R12.ServerID = R11.ServerID AND R12.YearID = R11.YearID INNER JOIN
                         ReciptItems AS Ri11 ON R11.ReciptID = Ri11.ReciptID AND R11.ServerID = Ri11.ServerID AND R11.YearID = Ri11.YearID INNER JOIN
                         ReciptItems AS Ri9 ON Ri11.ServerID = Ri9.ServerID AND Ri11.YearID = Ri9.YearID AND Ri11.ReciptItemID = Ri9.preReciptItemID INNER JOIN
                         Recipts AS R9 ON R9.ReciptID = Ri9.ReciptID AND R9.ServerID = Ri9.ServerID AND R9.YearID = Ri9.YearID
WHERE        (R12.ID = @ID12) and (R12.DocNo < 1)and (R11.DocNo < 1)and (R9.DocNo < 1)
                             and (R12.ReciptState = 0)and (R11.ReciptState = 0)and (R9.ReciptState = 0)

if  isnull(@ReciptNumber,0) = 0
begin
  	  raiserror('خروجی کالا یافت نشد',16,1)
	  return(0)
end



update R12
set R12.PersonID1 = @NewPersonID1 
FROM            Recipts AS R12 INNER JOIN
                         Recipts AS R11 ON R12.ReciptID = R11.ParentReciptID AND R12.ServerID = R11.ServerID AND R12.YearID = R11.YearID INNER JOIN
                         ReciptItems AS Ri11 ON R11.ReciptID = Ri11.ReciptID AND R11.ServerID = Ri11.ServerID AND R11.YearID = Ri11.YearID INNER JOIN
                         ReciptItems AS Ri9 ON Ri11.ServerID = Ri9.ServerID AND Ri11.YearID = Ri9.YearID AND Ri11.ReciptItemID = Ri9.preReciptItemID INNER JOIN
                         Recipts AS R9 ON R9.ReciptID = Ri9.ReciptID AND R9.ServerID = Ri9.ServerID AND R9.YearID = Ri9.YearID
WHERE        (R12.ID = @ID12) and (R12.DocNo < 1)and (R11.DocNo < 1)and (R9.DocNo < 1)
                             and (R12.ReciptState = 0)and (R11.ReciptState = 0)and (R9.ReciptState = 0)


update R11
set R11.PersonID1 = @NewPersonID1 
FROM            Recipts AS R12 INNER JOIN
                         Recipts AS R11 ON R12.ReciptID = R11.ParentReciptID AND R12.ServerID = R11.ServerID AND R12.YearID = R11.YearID INNER JOIN
                         ReciptItems AS Ri11 ON R11.ReciptID = Ri11.ReciptID AND R11.ServerID = Ri11.ServerID AND R11.YearID = Ri11.YearID INNER JOIN
                         ReciptItems AS Ri9 ON Ri11.ServerID = Ri9.ServerID AND Ri11.YearID = Ri9.YearID AND Ri11.ReciptItemID = Ri9.preReciptItemID INNER JOIN
                         Recipts AS R9 ON R9.ReciptID = Ri9.ReciptID AND R9.ServerID = Ri9.ServerID AND R9.YearID = Ri9.YearID
WHERE        (R12.ID = @ID12) and (R12.DocNo < 1)and (R11.DocNo < 1)and (R9.DocNo < 1)
                             and (R12.ReciptState = 0)and (R11.ReciptState = 0)and (R9.ReciptState = 0)



SELECT @COUNT9 = ROW_NUMBER() OVER(ORDER BY Ri9.ID ASC) --,@IDs =@IDs+','+ ltrim(Ri9.ID) 
FROM ReciptItems AS Ri9  INNER JOIN
     Recipts AS R9 ON R9.ReciptID = Ri9.ReciptID AND R9.ServerID = Ri9.ServerID AND R9.YearID = Ri9.YearID
WHERE        (R9.ID = @ID9)

  
if @COUNT12<>@COUNT9 
begin
	declare   @Query varchar(8000)
	declare   @ColumnsName varchar(8000)
	SET @ColumnsName = dbo.S_F_GetColumnsName('Recipts')
	set @Query='INSERT INTO Recipts  ('+@ColumnsName+')'

	SET @ColumnsName = REPLACE(@ColumnsName,' ReciptID,','')
	SET @ColumnsName = REPLACE(@ColumnsName,' ID,','')
	SET @ReciptID=(SELECT MAX(ReciptID)+1 FROM Recipts WHERE (ServerID= @ServerID) AND (YearID= @YearID))

	SET @ReciptNumber=(SELECT MAX(ReciptNumber)+1 FROM Recipts WHERE (ServerID = @ServerID) AND (YearID = @YearID) AND (ReciptType = @ReciptType9))


	SET @ColumnsName = REPLACE(@ColumnsName,' ReciptNumber,',STR(@ReciptNumber)+' AS ReciptNumber,')

	SET @ColumnsName = REPLACE(@ColumnsName,' PersonID1,',STR(@NewPersonID1)+' AS PersonID1,')

	SET @ColumnsName = REPLACE(@ColumnsName,' ModifyDate,',' GETDATE() AS ModifyDate,')
	SET @ColumnsName = REPLACE(@ColumnsName,' OperatorID,','127,')

	set @Query= @Query+--- 'INSERT INTO Recipts  ('+@ColumnsName+')
				' SELECT '+STR(@ReciptID)+', '+@ColumnsName+'
				  FROM  Recipts WHERE (ID = '+STR(@ID9)+')'

	SET @Query = REPLACE(@Query,' ParentReciptID,','')
	SET @Query = REPLACE(@Query,' ParentCoReciptID,','')
	SET @Query = REPLACE(@Query,' DocNo,','')
	SET @Query = REPLACE(@Query,' DocDate,','')
	SET @Query = REPLACE(@Query,' FirstUser,','')
	SET @Query = REPLACE(@Query,' LastUser,','')
	SET @Query = REPLACE(@Query,' Transmittal,','')
	SET @Query = REPLACE(@Query,' keyID,','')
	SET @Query = REPLACE(@Query,' ID,','')
	SET @Query = REPLACE(@Query,' TAXID,','')
	SET @Query = REPLACE(@Query,' IRTAXID,','')
	SET @Query = REPLACE(@Query,' TAXUID,','')
	SET @Query = REPLACE(@Query,' REFERENCENUMBER,','')
	SET @Query = REPLACE(@Query,' DATE_OF_SEND_TO_TAX,','')
	SET @Query = REPLACE(@Query,' tax_status,','')

	Exec (@Query)
end
else
begin
UPDATE R9
	SET  R9.PersonID1 = @NewPersonID1
	FROM ReciptItems AS Ri9  INNER JOIN
		 Recipts AS R9 ON R9.ReciptID = Ri9.ReciptID AND R9.ServerID = Ri9.ServerID AND R9.YearID = Ri9.YearID
	WHERE        (R9.ID = @ID9)    and  (R9.DocNo < 1)
                             and (R9.ReciptState = 0)
end


UPDATE Ri9
SET Ri9.ReciptID = case when  @COUNT12<>@COUNT9 then @ReciptID else Ri9.ReciptID end
FROM ReciptItems AS Ri9  INNER JOIN
     Recipts AS R9 ON R9.ReciptID = Ri9.ReciptID AND R9.ServerID = Ri9.ServerID AND R9.YearID = Ri9.YearID
WHERE        (R9.ID = @ID9)  and (R9.DocNo < 1) and  (R9.ReciptState = 0)
 and Ri9.preReciptItemID in (

SELECT Ri11.ReciptItemID
FROM            Recipts AS R12 INNER JOIN
                         Recipts AS R11 ON R12.ReciptID = R11.ParentReciptID AND R12.ServerID = R11.ServerID AND R12.YearID = R11.YearID INNER JOIN
                         ReciptItems AS Ri11 ON R11.ReciptID = Ri11.ReciptID AND R11.ServerID = Ri11.ServerID AND R11.YearID = Ri11.YearID INNER JOIN
                         ReciptItems AS Ri9 ON Ri11.ServerID = Ri9.ServerID AND Ri11.YearID = Ri9.YearID AND Ri11.ReciptItemID = Ri9.preReciptItemID INNER JOIN
                         Recipts AS R9 ON R9.ReciptID = Ri9.ReciptID AND R9.ServerID = Ri9.ServerID AND R9.YearID = Ri9.YearID
WHERE        (R12.ID = @ID12) 
)

RETURN(@ReciptNumber)
END
