CREATE FUNCTION StuffCodeCountingDetails ( @YearIDFrom  int =1398 , @YearIDTo int =1398,@Date as Char(10) ='1398/12/29' )
RETURNS table  AS  
return (SELECT	CD.StuffCode, StuffCoding.c_StuffName, CD.CountEntity, 
		 isnull(StuffCodeEntity_c.Entity,0) as Entity,
		CD.CountEntity - isnull(StuffCodeEntity_c.Entity,0) AS DifferEntity,

		CD.StoreID, CD.CountID

FROM            (SELECT cd1.CountID, cd1.StoreID, ReciptItems.StuffCode, COUNT(cd1.DetailCaption) AS CountEntity
FROM            CountingDetails as cd1  INNER JOIN
                         (SELECT ReciptItems.StuffCode, ReciptItemsDetails.DetailCaption, MAX(ReciptItemsDetails.DetailsID) AS MaxDetailsID
FROM            ReciptItems INNER JOIN
                         ReciptItemsDetails ON ReciptItems.ReciptItemID = ReciptItemsDetails.ReciptItemID AND ReciptItems.ReciptID = ReciptItemsDetails.ReciptID AND ReciptItems.ServerID = ReciptItemsDetails.ServerID AND 
                         ReciptItems.YearID = ReciptItemsDetails.YearID
GROUP BY ReciptItems.StuffCode, ReciptItemsDetails.DetailCaption, ReciptItemsDetails.DetailsID
)ReciptItems ON cd1.DetailCaption = ReciptItems.DetailCaption
						
GROUP BY cd1.CountID, cd1.StoreID, ReciptItems.StuffCode) as CD
 INNER JOIN
                         StuffCoding ON CD.StuffCode = StuffCoding.c_StuffCode INNER JOIN
                         Counting ON CD.CountID = Counting.CountID LEFT OUTER JOIN
                         dbo.StuffCodeEntity(@YearIDFrom, @YearIDTo, @Date ) AS StuffCodeEntity_C ON CD.StoreID = StuffCodeEntity_C.StoreID AND 
                         CD.StuffCode = StuffCodeEntity_C.StuffCode  
						 
)


