CREATE FUNCTION Fn_rptCompare_Count_EntityD   ( @YearIDFrom int , @YearIDTo int, @Date char(10) , @StoreID int, @CountID int  )  
RETURNS  table  AS 
Return  (
SELECT     AllStuffCode.StoreID, AllStuffCode.StuffCode, StuffCoding.c_StuffName,StuffCoding.c_StuffTecInfo, Units.UnitName,
           SCD.CountEntity,  StuffCodeEntity.Entity,  StuffCodeEntity.Price,
					  case when (  SCD.CountID IS NULL )
					  			then StuffCodeEntity.Entity 
							else SCD.DifferEntity
					  end as DifferEntity , 
					  ROUND(ISNULL((CASE  WHEN ((StuffCodeEntity.Entity) =0 or (StuffCodeEntity.Entity) is null ) THEN StuffCoding.SellPrice1
                      ELSE  (StuffCodeEntity.Price / (StuffCodeEntity.Entity)) END) * 
					  
						( case when (   SCD.CountID IS NULL )
					  			then StuffCodeEntity.Entity 
								else SCD.DifferEntity
							end
						) 					  
					  , 0), 0)
                      AS DifferPrice,
                      StuffCodeEntity.TotallSellPrice,
                      ROUND(ISNULL((CASE  WHEN ((StuffCodeEntity.Entity) =0 or (StuffCodeEntity.Entity) is null ) THEN StuffCoding.SellPrice1
                      ELSE (StuffCodeEntity.TotallSellPrice / (StuffCodeEntity.Entity)) END)  * 
					  
					  (
						case when (  SCD.CountID IS NULL )
					  			then StuffCodeEntity.Entity 
							else SCD.DifferEntity
						end 					  
					  )
					  
					  ,0), 0)
                      AS DifferTotallSellPrice,
                      ROUND( ISNULL(
					  (
						case when (   SCD.CountID IS NULL )
					  			then StuffCodeEntity.Entity 
							else SCD.DifferEntity
						end 					  
					  )
					  , 0) - isnull(StuffCodeEntity.Entity,0),4) AS OtherEntity,
          
                      ROUND(ISNULL((CASE  WHEN ((StuffCodeEntity.Entity) =0 or (StuffCodeEntity.Entity) is null ) THEN StuffCoding.SellPrice1
                      ELSE  (StuffCodeEntity.Price / (StuffCodeEntity.Entity)) END) * 
					  (
						  case when (  SCD.CountID IS NULL )
						  			then StuffCodeEntity.Entity 
								else SCD.DifferEntity
						  end 
					  )					  
					  
					  , 0), 0)
                      - isnull(StuffCodeEntity.Price,0) AS OtherPrice,
                      ROUND(ISNULL((CASE  WHEN ((StuffCodeEntity.Entity) =0 or (StuffCodeEntity.Entity) is null ) THEN StuffCoding.SellPrice1
                      ELSE (StuffCodeEntity.TotallSellPrice / (StuffCodeEntity.Entity)) END)  * 
					  
					  (
						  case when (   SCD.CountID IS NULL )
					  				then StuffCodeEntity.Entity 
								else SCD.DifferEntity
						  end 
					  )
					  
					  
					   ,0), 0)
                      - isnull(StuffCodeEntity.TotallSellPrice,0) AS OtherTotallSellPrice, SCD.CountID , StuffCoding.SellPrice1
          , Stores.c_StoreName


FROM         Units INNER JOIN
                      StuffCoding ON Units.UnitCode = StuffCoding.n_UnitCode RIGHT OUTER JOIN
                          (
 						  SELECT DISTINCT cd2.StoreID, ReciptItems.StuffCode
                         FROM            CountingDetails cd2 INNER JOIN
                         ReciptItemsDetails ON cd2.DetailsID = ReciptItemsDetails.DetailsID INNER JOIN
                         ReciptItems ON ReciptItemsDetails.ReciptItemID = ReciptItems.ReciptItemID AND ReciptItemsDetails.ReciptID = ReciptItems.ReciptID AND ReciptItemsDetails.ServerID = ReciptItems.ServerID AND 
                         ReciptItemsDetails.YearID = ReciptItems.YearID  
                             UNION
                             SELECT     StoreID, StuffCode
                             FROM         dbo.StuffCodeEntity(@YearIDFrom , @YearIDTo , @Date) AS StuffCodeEntity) AS AllStuffCode LEFT OUTER JOIN
                      dbo.StuffCodeCountingDetails(@YearIDFrom , @YearIDTo , @Date ) AS SCD ON AllStuffCode.StoreID = SCD.StoreID AND 
                      AllStuffCode.StuffCode = SCD.StuffCode ON StuffCoding.c_StuffCode = AllStuffCode.StuffCode LEFT OUTER JOIN
                      dbo.StuffCodeEntity( @YearIDFrom , @YearIDTo , @Date ) AS StuffCodeEntity ON AllStuffCode.StoreID = StuffCodeEntity.StoreID AND
                      AllStuffCode.StuffCode = StuffCodeEntity.StuffCode INNER JOIN
                         Stores ON AllStuffCode.StoreID = Stores.n_StoreID
WHERE     (AllStuffCode.StoreID = @StoreID) AND (SCD.CountID = @CountID OR SCD.CountID IS NULL) 
)

