CREATE  FUNCTION Fn_FormsDes ( @YearID int =93,@FormType int =50 ,@kind int =1 )

RETURNS table  AS  
return (
SELECT        Kind, FormID, ServerID, YearID, FormType, FormNumber, FormDate, FormState, FomNote, Des
FROM            (

SELECT        1 AS Kind, dbo.Forms.FormID, dbo.Forms.ServerID, dbo.Forms.YearID, dbo.Forms.FormType, dbo.Forms.FormNumber, dbo.Forms.FormDate, 
                    dbo.Forms.FormState, dbo.Forms.FomNote, 'دریافت / پرداخت به  ' + dbo.Customers.CustName + '  بمبلغ  ' + STR(FormsItems.SumAmount) 
                    + '  ریال  ' AS Des
FROM            dbo.Forms INNER JOIN
                    dbo.Customers ON dbo.Forms.CustomerID2 = dbo.Customers.CustID LEFT OUTER JOIN
                        (SELECT        FormID, SUM(ItemAmount) AS SumAmount, ServerID, YearID
                            FROM            dbo.FormItems
                            GROUP BY FormID, ServerID, YearID) AS FormsItems ON dbo.Forms.FormID = FormsItems.FormID AND 
                    dbo.Forms.ServerID = FormsItems.ServerID AND dbo.Forms.YearID = FormsItems.YearID
where (dbo.Forms.YearID = @YearID) and  (dbo.Forms.FormType=@FormType)  and (@kind = 1)
-------------
UNION ALL
-------------
SELECT        2 AS kind, dbo.Recipts.ReciptID, dbo.Recipts.ServerID, dbo.Recipts.YearID, dbo.Recipts.ReciptType, dbo.Recipts.ReciptNumber, 
                        dbo.Recipts.ReciptDate, dbo.Recipts.ReciptState, dbo.Recipts.ReciptNote, 
                        dbo.ReciptTypes.ReciptCaption + '  به مبلغ ناخالص    ' + STR(ReciptItems.[Amount 1]) + '  و خالص  ' + STR(ReciptItems.[Amount 2]) 
                        + ' از مشتری  ' + Customers_1.CustName AS Expr3
FROM            dbo.Recipts INNER JOIN
                        dbo.Customers AS Customers_1 ON dbo.Recipts.PersonID1 = Customers_1.CustID INNER JOIN
                            (SELECT        ReciptID, ServerID, YearID, SUM(TotalInputPrice + TotalOutputPrice) AS [Amount 1], SUM(TotallSellPrice) AS [Amount 2]
                                FROM            dbo.ReciptItems AS ReciptItems_1
                                GROUP BY ReciptID, ServerID, YearID) AS ReciptItems ON dbo.Recipts.ReciptID = ReciptItems.ReciptID AND 
                        dbo.Recipts.ServerID = ReciptItems.ServerID AND dbo.Recipts.YearID = ReciptItems.YearID INNER JOIN
                        dbo.ReciptTypes ON dbo.Recipts.ReciptType = dbo.ReciptTypes.ReciptType
where (dbo.Recipts.YearID = @YearID) and  (dbo.Recipts.ReciptType=@FormType) and (@kind = 2)
						
) AS FormTitle
)

