CREATE  FUNCTION Fn_WorkFlow ( @YearID int =93,@FormType int =50 ,@kind int =1 )

RETURNS table  AS  
return (
SELECT	WF_TransWorkFlow.ID, WF_TransWorkFlow.kind, WF_TransWorkFlow.ServerID, 
		WF_TransWorkFlow.YearID,WF_TransWorkFlow.FormID,WF_TransWorkFlow.FormType, 
		WF_TransWorkFlow.ModifyDate, WF_TransWorkFlow.UserID, WF_TransWorkFlow.PositionCode, 
		WF_TransWorkFlow.SortAccept, WF_TransWorkFlow.Note, WF_TransWorkFlow.State, 
		ForControl.MaxSortAccept, View_FormsDes.FormNumber, View_FormsDes.FormDate, 
		CASE View_FormsDes.FormState 
			WHEN 0 THEN 'موقت' 
			WHEN 1 THEN 'قطعی' 
			WHEN 2 THEN 'دائم' 
			WHEN 3 THEN 'باطل' 
			WHEN 10 THEN 'باطل' 
    		ELSE 'باطل' END AS StateName,
		View_FormsDes.Des, View_FormsDes.FomNote,WF_TransWorkFlow.UserCitation
FROM	WF_TransWorkFlow INNER JOIN
		(
		select WF_TransWorkFlow.id ,WF_TransWorkFlow.SortAccept AS MaxSortAccept
		From
			(
				SELECT     kind, ServerID, YearID, FormID, FormType,  MAX(ModifyDate) AS ModifyDate
				FROM         WF_TransWorkFlow AS WF_TransWorkFlow_1
				WHERE     (State = 0) AND (kind = @Kind ) AND (FormType =@FormType )  and  (YearID = @YearID)
				GROUP BY kind, ServerID, YearID, FormID, FormType 
			) LastRecord  inner join WF_TransWorkFlow
		 on WF_TransWorkFlow.kind = LastRecord.kind and WF_TransWorkFlow.ServerID = LastRecord.ServerID and 
		 WF_TransWorkFlow.YearID = LastRecord.YearID and WF_TransWorkFlow.FormID =LastRecord.FormID and 
		 WF_TransWorkFlow.FormType=LastRecord.FormType and WF_TransWorkFlow.ModifyDate=LastRecord.ModifyDate
		) AS ForControl 
		ON WF_TransWorkFlow.id = ForControl.id  INNER JOIN
        Fn_FormsDes ( @YearID,@FormType  ,@kind ) AS View_FormsDes 
			ON 	WF_TransWorkFlow.kind = View_FormsDes.Kind AND 
				WF_TransWorkFlow.FormID = View_FormsDes.FormID AND 
				WF_TransWorkFlow.ServerID = View_FormsDes.ServerID AND 
				WF_TransWorkFlow.YearID = View_FormsDes.YearID AND 
				WF_TransWorkFlow.FormType = View_FormsDes.FormType
WHERE     (WF_TransWorkFlow.State = 0) AND (WF_TransWorkFlow.kind = @Kind ) AND (WF_TransWorkFlow.FormType =@FormType )  and  (WF_TransWorkFlow.YearID = @YearID)
)
