CREATE VIEW [dbo].[View_WF_TransWorkFlow]
AS
SELECT CASE WHEN WF_TransWorkFlow.UserCitation <> 0 THEN WF_TransWorkFlow.UserCitation ELSE WF_TransWorkFlow.UserID END AS UserID, dbo.WF_TransWorkFlow.ID, dbo.WF_TransWorkFlow.kind, 
    dbo.WF_TransWorkFlow.ServerID, dbo.WF_TransWorkFlow.YearID, dbo.WF_TransWorkFlow.FormID, dbo.WF_TransWorkFlow.FormType, dbo.WF_TransWorkFlow.ModifyDate, 
    dbo.WF_TransWorkFlow.UserID AS WorkUserID, CASE WHEN WF_TransWorkFlow.UserCitation <> 0 THEN Operators_1.PositionCode ELSE dbo.WF_TransWorkFlow.PositionCode END AS PositionCode, 
    dbo.WF_TransWorkFlow.SortAccept, dbo.WF_TransWorkFlow.State, dbo.WF_TransWorkFlow.Note, dbo.WF_TransWorkFlow.UserCitation, Operators_1.PositionCode AS WorkPositionCode, 
    CASE WHEN WF_TransWorkFlow.UserCitation <> 0 THEN 'ارجاع' ELSE 'تایید' END AS CitationNote, Operators.name AS ReferredTo, Operators_1.name AS Referring, 
    CASE WHEN  NOT Operators.name IS NULL THEN 'کاربر ' + Operators_1.name + ' به ' + Operators.name + ' ارجاع داده' ELSE '' END AS ReferringNote
FROM            dbo.WF_TransWorkFlow LEFT OUTER JOIN
                         FaraSystems.dbo.Operators AS Operators ON dbo.WF_TransWorkFlow.UserID = Operators.UserID LEFT OUTER JOIN
                         FaraSystems.dbo.Operators AS Operators_1 ON dbo.WF_TransWorkFlow.UserCitation = Operators_1.UserID

