CREATE FUNCTION InventoryAvilable4Sells (
		@DateFrom  Char(10) ='0001/01/01', @DateTo Char(10) = '9999/99/99'  ,
		@YearIDFrom  int = 0 , @YearIDTo int = 9999 ,
		@StoreIDFrom  int = 0 , @StoreIDTo int = 999999999  )
				
RETURNS table  AS  
return
(		
SELECT 	ServerID,YearID, StoreID, StuffCode, 
		ROUND(SUM(CASE WHEN kind =1 THEN InvEntity ELSE 0 END),2) AS InvEntity ,
		ROUND(SUM(CASE WHEN kind =1 THEN InvWeight ELSE 0 END),2) AS InvWeight ,
		ROUND(SUM(CASE WHEN kind =2 THEN InvEntity ELSE 0 END),2) AS EntityTheWay ,
		ROUND(SUM(CASE WHEN kind =2 THEN InvWeight ELSE 0 END),2) AS WeightTheWay  ,
		ROUND(SUM(CASE WHEN kind =3 THEN InvEntity ELSE 0 END),2) AS EntityTheWay2 ,
		ROUND(SUM(CASE WHEN kind =3 THEN InvWeight ELSE 0 END),2) AS WeightTheWay2 ,
		ROUND(SUM(CASE WHEN kind =4 THEN InvEntity ELSE 0 END),2) AS EntityTheWay_Dec ,
		ROUND(SUM(CASE WHEN kind =4 THEN InvWeight ELSE 0 END),2) AS WeightTheWay_Dec ,
		ROUND(sum(InvEntity),2) AS EntityAvilable4Sells, ROUND(sum(InvWeight),2) AS WeightAvilable4Sells,
		ROUND(SUM(CASE WHEN kind in(1,2,3) THEN InvEntity ELSE 0 END),2) AS AvilableEntity ,
		ROUND(SUM(CASE WHEN kind in(1,2,3) THEN InvWeight ELSE 0 END),2) AS AvilableWeight 

FROM 
(
SELECT	1 AS kind , Recipts.ServerID, Recipts.YearID, 
		Recipts.StoreID, 
		ReciptItems.StuffCode, 
		sum(ReciptItems.InputEntity - ReciptItems.OutputEntity) AS InvEntity , 
		sum(ReciptItems.InputWeight - ReciptItems.OutputWeight) AS InvWeight 
FROM	Recipts INNER JOIN
        ReciptItems ON Recipts.ReciptID = ReciptItems.ReciptID AND Recipts.ServerID = ReciptItems.ServerID AND 
        Recipts.YearID = ReciptItems.YearID INNER JOIN
        ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType 
WHERE	(ReciptTypes.EffectType IN (2, 4, 6, 7,  8  )) AND (Recipts.ReciptState < 3) 
AND		(Recipts.YearID between @YearIDFrom  and @YearIDTo) 
AND		(Recipts.StoreID between @StoreIDFrom  and @StoreIDTo )
AND (CASE WHEN Recipts.DefaultDate IS NULL OR ltrim(Recipts.DefaultDate) = '' THEN Recipts.ReciptDate 
                                                                              ELSE Recipts.DefaultDate END BETWEEN @DateFrom AND @DateTo)
Group By Recipts.ServerID, Recipts.YearID, 
		Recipts.StoreID, 
		ReciptItems.StuffCode
----------------------------------------------------------
UNION ALL
----------------------------------------------------------
SELECT	1 AS kind ,Recipts.ServerID, Recipts.YearID, 
		CASE ReciptTypes.IncreasingInventoryStore 
			WHEN 1 THEN Recipts.StoreID 
			WHEN 2 THEN Recipts.StoreID2 
			ELSE 0 
		END AS StoreID,
		ReciptItems.StuffCode, 
		sum(ReciptItems.OutputEntity) AS InvEntity,sum(ReciptItems.OutputWeight) AS InvWeight 
FROM	Recipts INNER JOIN
		ReciptItems ON Recipts.ReciptID = ReciptItems.ReciptID AND Recipts.ServerID = ReciptItems.ServerID AND 
		Recipts.YearID = ReciptItems.YearID INNER JOIN
		ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType  
WHERE	(ReciptTypes.EffectType IN (4, 7,  8  )) AND (Recipts.ReciptState < 3) AND 
		(ReciptTypes.IncreasingInventoryStore <>0) AND
		(Recipts.YearID between @YearIDFrom  and @YearIDTo)
		AND
		(CASE ReciptTypes.IncreasingInventoryStore 
			WHEN 1 THEN Recipts.StoreID 
			WHEN 2 THEN Recipts.StoreID2 
			ELSE 0 
		END between @StoreIDFrom  and @StoreIDTo )
		AND (CASE WHEN Recipts.DefaultDate IS NULL OR ltrim(Recipts.DefaultDate) = '' THEN Recipts.ReciptDate 
		                                                                              ELSE Recipts.DefaultDate END BETWEEN @DateFrom AND @DateTo)
Group By Recipts.ServerID, Recipts.YearID, 
		CASE ReciptTypes.IncreasingInventoryStore 
			WHEN 1 THEN Recipts.StoreID 
			WHEN 2 THEN Recipts.StoreID2 
			ELSE 0 
		END  ,
		ReciptItems.StuffCode
----------------------------- کاهنده و افزاینده موجودی - بدون نمایش انبار 2  
union all 
-----------------------------
SELECT	1 AS kind ,Recipts.ServerID, Recipts.YearID,
		Recipts.StoreID ,
		ReciptItems.ProductCode, 
		sum(ReciptItems.OutputEntity) AS InvEntity, sum(ReciptItems.OutputWeight) AS InvWeight 

FROM	Recipts INNER JOIN
		ReciptItems ON Recipts.ReciptID = ReciptItems.ReciptID AND Recipts.ServerID = ReciptItems.ServerID AND 
		Recipts.YearID = ReciptItems.YearID INNER JOIN
		ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType 
WHERE	(ReciptTypes.EffectType IN (8)) AND (Recipts.ReciptState < 3) AND 
		(ReciptTypes.IncreasingInventoryStore =0) and (ReciptTypes.IncreasingInventory =0 )  
	AND	(Recipts.YearID between @YearIDFrom  and @YearIDTo)
	AND	(Recipts.StoreID between @StoreIDFrom  and @StoreIDTo )
    AND (CASE WHEN Recipts.DefaultDate IS NULL OR ltrim(Recipts.DefaultDate) = '' THEN Recipts.ReciptDate 
		                                                                              ELSE Recipts.DefaultDate END BETWEEN @DateFrom AND @DateTo)
Group By Recipts.ServerID, Recipts.YearID, 
		Recipts.StoreID  ,
		ReciptItems.ProductCode
------------------------------
UNION ALL
------------------------------
SELECT	case  ReciptTypes.EffectType
	when 9 THEN 2 
	when 1 THEN 3 
	else 4 end AS kind , 
		Recipts.ServerID, Recipts.YearID, 
		Recipts.StoreID, 
		ReciptItems.StuffCode, 
		sum(ReciptItems.InputEntity - ReciptItems.OutputEntity) -sum(isnull(RecalEntity,0))  AS InvEntity , 
		sum(ReciptItems.InputWeight - ReciptItems.OutputWeight) -sum(isnull(Recalweight,0))  AS InvWeight 
FROM	Recipts INNER JOIN
        ReciptItems ON Recipts.ReciptID = ReciptItems.ReciptID AND Recipts.ServerID = ReciptItems.ServerID AND 
        Recipts.YearID = ReciptItems.YearID INNER JOIN
        ReciptTypes ON Recipts.ReciptType = ReciptTypes.ReciptType 
		left outer join 
			(select		PrvYearID , preReciptItemID ,ServerID , sum(InputEntity-OutputEntity) AS RecalEntity , sum(InputWeight-OutputWeight) AS Recalweight
				FROM	ReciptItems 
				where	(yearid between @YearIDFrom AND @YearIDTo) and not (PrvYearID  is null)
				group by PrvYearID , preReciptItemID ,ServerID  )_ReciptItems 
				on ReciptItems.ReciptItemID = _ReciptItems.preReciptItemID and ReciptItems.YearID = _ReciptItems.PrvYearID and ReciptItems.ServerID = _ReciptItems.ServerID 
		left outer join 
			(select distinct isnull(PrvYearID,yearid ) AS PrvYearID , ParentReciptID ,ServerID , ReciptType
				FROM	Recipts 
				where (yearid between @YearIDFrom AND @YearIDTo) and not (PrvYearID  is null) )_Recipts 
				on Recipts.ReciptID = _Recipts.ParentReciptID and Recipts.YearID = _Recipts.PrvYearID and Recipts.ServerID = _Recipts.ServerID	
			--and 
		--	ReciptTypes.CorrelateReciptType<>_Recipts.ReciptType
WHERE	(ReciptTypes.EffectType IN (1,3,9)) AND 
		(_Recipts.ParentReciptID IS NULL --and ( ReciptItems.InputEntity - ReciptItems.OutputEntity -  isnull(_ReciptItems.RecalEntity,0) <>0 )
		) 
		AND (Recipts.YearID  BETWEEN @YearIDFrom   and @YearIDTo)
		AND (Recipts.StoreID BETWEEN @StoreIDFrom  and @StoreIDTo)
		AND (CASE WHEN Recipts.DefaultDate IS NULL OR ltrim(Recipts.DefaultDate) = '' 
			      THEN Recipts.ReciptDate 
		          ELSE Recipts.DefaultDate END BETWEEN @DateFrom AND @DateTo)
		AND (CASE WHEN (ReciptTypes.EffectType = 9)      AND(Recipts.ReciptState IN (0,1))  THEN 1 
				  WHEN (ReciptTypes.EffectType in (1,3) )AND(Recipts.ReciptState IN (1)  )  THEN 1
				  ELSE 0 END =1)

GROUP BY CASE  ReciptTypes.EffectType
		 WHEN 9 THEN 2 
	     WHEN 1 THEN 3 
         ELSE 4 END ,
					Recipts.ServerID, Recipts.YearID, 
					Recipts.StoreID  ,
					ReciptItems.StuffCode
----------------------------------------------------------
 ) inv
Group by	ServerID,YearID, StoreID, StuffCode
)

