CREATE VIEW Vu_ReciptItems4Edit
AS
SELECT        ReciptItems.ReciptID, ReciptItems.ServerID, ReciptItems.YearID, Recipts.ReciptType, Recipts.ReciptNumber, Recipts.ReciptDate, Recipts.PersonID1, Customers.CustName, ReciptItems.StuffCode, 
                         StuffCoding.c_StuffName, ReciptItems.OutputEntity, ReciptItems.OutputWeight, 
						 ReciptItems.RequestedEntity, ReciptItems.RequestedWeight, 
						 CASE WHEN Recipts.ReciptState = 1 THEN ReciptItems.RequestedEntity ELSE 0 END RequestedEntityFinal ,
						 CASE WHEN Recipts.ReciptState = 1 THEN ReciptItems.RequestedWeight ELSE 0 END RequestedWeightFinal ,
						 ReciptItems.AcceptEntity, ReciptItems.AcceptWeight, 
                         ReciptItems.TotalOutputPrice, ReciptItems.UnitSellPrice, ReciptItems.TotallSellPrice, ReciptItems.TaxCo, ReciptItems.TaxValue,StuffCoding.Carton
						 ,Customers.NumberCreditInstallments,ReciptItems.TotalInputPrice,ReciptItems.InputEntity,ReciptItems.InputWeight,ReciptItems.ProductCode
FROM            ReciptItems INNER JOIN
                         Recipts ON ReciptItems.ReciptID = Recipts.ReciptID AND ReciptItems.ServerID = Recipts.ServerID AND ReciptItems.YearID = Recipts.YearID INNER JOIN
                         StuffCoding ON ReciptItems.StuffCode = StuffCoding.c_StuffCode INNER JOIN
                         Units ON StuffCoding.n_UnitCode = Units.UnitCode INNER JOIN
                         Customers ON Recipts.PersonID1 = Customers.CustID  left outer join 

       (select distinct isnull(PrvYearID,yearid ) AS PrvYearID , ParentReciptID ,ServerID , ReciptType
       FROM	Recipts 
       where  not (PrvYearID  is null) )_Recipts 
on Recipts.ReciptID = _Recipts.ParentReciptID 
and Recipts.YearID = _Recipts.PrvYearID and Recipts.ServerID = _Recipts.ServerID

WHERE (Recipts.ReciptState < 3) and _Recipts.ParentReciptID  is null

