CREATE FUNCTION dbo.JsonReplaceChars (@Str nvarchar(4000))
RETURNS nvarchar(4000)
AS
BEGIN
    set @Str=REPLACE(@Str,'"','\"')
    set @Str=REPLACE(@Str,'"',' ')
    set @Str=REPLACE(@Str,'\','\\')
    set @Str=REPLACE(@Str,'/','\/')
    set @Str=REPLACE(@Str,char(10),'\n')   
    set @Str=REPLACE(@Str,char(13),'\n')   
	RETURN @Str

END
GO 
