GO 
CREATE FUNCTION GetFirstChar (@strinq  varchar(200)  )
RETURNS varchar(1) 
BEGIN
  declare @c varchar(1)
  set @c=  LEFT(LTRIM( @strinq), 1)
  set @c=REPLACE(@c,'ک','ك') 
  RETURN(@c)
END
