CREATE FUNCTION GetParentForm(
    @StuffCode       BIGINT,
    @preReciptItemID INT,
    @ReciptItemID    INT,
    @YearID          INT
)
RETURNS NVARCHAR(1500)
AS
BEGIN
    DECLARE @Recall    NVARCHAR(500) = ''
    DECLARE @PrvYearID INT

    SELECT TOP 1 @PrvYearID = PrvYearID
    FROM   ReciptItems
    WHERE  ReciptItemID = @ReciptItemID
      AND  YearID       = @YearID
      AND  StuffCode    = @StuffCode

    SELECT @Recall = @Recall
        + CASE WHEN @Recall = '' THEN '' ELSE '|' END
        + LTRIM(STR(R.ReciptNumber)) + RT.ReciptCaption + R.ReciptDate
        + ' = ' + LTRIM(STR(RI.InputEntity + RI.OutputEntity))
    FROM 
	 (
        SELECT RI.ID, RI.ReciptID, RI.ServerID, RI.YearID,
               RI.InputEntity, RI.OutputEntity
        FROM   ReciptItems RI
        WHERE  RI.ReciptItemID = @preReciptItemID
          AND  RI.StuffCode    = @StuffCode
          AND  RI.YearID IN (@YearID, @PrvYearID)

        UNION

        SELECT RI.ID, RI.ReciptID, RI.ServerID, RI.YearID,
               RI.InputEntity, RI.OutputEntity
        FROM   ReciptItems RI
        WHERE  RI.preReciptItemID = @ReciptItemID
          AND  RI.StuffCode       = @StuffCode
          AND  (RI.PrvYearID = @YearID OR RI.YearID = @YearID)
    ) RI
    INNER JOIN Recipts     R  ON  R.ReciptID  = RI.ReciptID
                              AND R.ServerID  = RI.ServerID
                              AND R.YearID    = RI.YearID
    INNER JOIN ReciptTypes RT ON  RT.ReciptType = R.ReciptType
    ORDER BY RI.ID

    RETURN @Recall
END
