								@ReturnStuffCode Bigint OUTPUT as
								
BEGIN
SET NOCOUNT ON
BEGIN
if len(ltrim(RTRIM( @StuffName)))=0
BEGIN
SET @ReturnStuffCode=-5
    --نام وارد نشده
	return
END
  if (select count(*) From StuffCoding WHERE ExternalId =@ExternalId)=0
   begin
