--                         dbo.StuffGroups AS StuffGroups_1 ON dbo.StuffGroups.UperGroupId = StuffGroups_1.GroupID LEFT OUTER JOIN
--                         dbo.Units AS Units_3 ON dbo.StuffCoding.n_UnitCode = Units_3.UnitCode LEFT OUTER JOIN
