CREATE PROCEDURE ReciptReturn @ID bigint  --  کلید فرم برگشت از فروش ثبت شده
                  ,@NewID bigint = 0  
				  OUTPUT    --  خروجی پراسیجر برای نیاز احتمالی
as
BEGIN
SET NOCOUNT ON

DECLARE @IRTAXID varchar(100)  --  شمار منحصر به فرد مالیاتی فاکتور فروش اصلی

SELECT  @IRTAXID = IRTAXID FROM            Recipts WHERE        (ID = @ID)and (Recipts.Reciptstate <> 3)


---------------------   این قسمت برای برگشت ها برگشت از فروش در نظر گرفته شده
DECLARE @IDs varchar(8000)=rtrim(ltrim(@ID))
DECLARE @irFound varchar(100)
SELECT @IDs=@IDs+','+ltrim(id), @irFound=IRTAXID from Recipts WHERE 	(TAXID=@IRTAXID)
WHILE @irFound<>'' 
SELECT @IDs=@IDs+','+ltrim(id),@irFound=IRTAXID from Recipts WHERE 	(TAXID=@irFound)
--SELECT  part  FROM dbo.SplitString(@ids,',')
---------------------   این قسمت برای برگشت ها برگشت از فروش در نظر گرفته شده  
DECLARE @countForm int
SELECT @countForm=count( part)  FROM dbo.SplitString(@ids,',')

DECLARE @DiagnosisCalcTotalPrice tinyint
select  @DiagnosisCalcTotalPrice=EntityOrWeight from Config


---  سلکت زیر فرم برگشت از فروش و فرم فاکتور فروش را دارد با هم نمایش می شود که باید از هم کم شوند
SELECT   max(Row#) Row#,
_NationalStuffCode,  _Tax_mu,  _StuffName,ItemNote ,          
		SUM(OutputEntity-InputEntity ) AS InputEntity, 0 AS OutputEntity, SUM(OutputWeight-InputWeight) AS InputWeight, 0 AS OutputWeight, 
		SUM(ArzAmount) AS ArzAmount, max(UnitSellPrice) AS UnitSellPrice, 
	--max(DeficitValue) AS DeficitValue ,

		 MAX(TaxCo) AS TaxCo,abs(FLOOR(
		CAST(
--	case when SUM(InputEntity + InputWeight )>0 then --جهت پیدا کردن زمانی که ردیفی اصلا برگشت نخورده 
		case when @DiagnosisCalcTotalPrice in (0,2) then
		  FLOOR
		  ( ( max(UnitSellPrice)*SUM(OutputEntity - InputEntity ) -  FLOOR(  max(UnitSellPrice)*SUM(OutputEntity - InputEntity )    * MAX(WaterCo) / 100  )    )  * MAX(TaxCo) / 100 )
		else
		 -FLOOR
		  ( ( max(UnitSellPrice)*SUM(OutputWeight - InputWeight ) -  FLOOR(max(UnitSellPrice)*SUM(OutputWeight - InputWeight  )    * MAX(WaterCo) / 100  )  )  * MAX(TaxCo) / 100 )
		end
--	else max(TaxValue)	end  
	 AS money))
	 )AS TaxValue , 

	 FLOOR(
		CAST(
		case when @DiagnosisCalcTotalPrice in (0,2) then
		  FLOOR
		  (max(UnitSellPrice)*SUM(OutputEntity - InputEntity ))  
		else
		  FLOOR
		  (max(UnitSellPrice)*SUM(OutputWeight - InputWeight ))  
		end	AS money)) AS TotalInputPrice, 
		MAX(WaterCo) WaterCo ,
		CAST(
		case when @DiagnosisCalcTotalPrice in (0,2) then
		  FLOOR (  max(UnitSellPrice)*SUM(OutputEntity - InputEntity )    * MAX(WaterCo) / 100  )  
		else
		  FLOOR (max(UnitSellPrice)*SUM(OutputWeight - InputWeight  )    * MAX(WaterCo) / 100  )  
		end	AS money) AS DeficitValue, 


		0 AS TotalOutputPrice ,FLOOR(
			CAST(
case when SUM(InputEntity + InputWeight )>0 then --جهت پیدا کردن زمانی که ردیفی اصلا برگشت نخورده 
		case when @DiagnosisCalcTotalPrice in (0,2) then
		   FLOOR(max(UnitSellPrice)*SUM(OutputEntity-InputEntity )   -   FLOOR(  max(UnitSellPrice)*SUM(OutputEntity - InputEntity )    * MAX(WaterCo) / 100  )    +
		   ( ( max(UnitSellPrice)*SUM(OutputEntity-InputEntity ) -  FLOOR(  max(UnitSellPrice)*SUM(OutputEntity - InputEntity )    * MAX(WaterCo) / 100  ) )  * MAX(TaxCo) / 100 ) )
		else
		   FLOOR(max(UnitSellPrice)*SUM(OutputWeight-InputWeight )    -   FLOOR(max(UnitSellPrice)*SUM(OutputWeight - InputWeight  )    * MAX(WaterCo) / 100  )   +
		   ( ( max(UnitSellPrice)*SUM(OutputWeight-InputWeight ) -  FLOOR(max(UnitSellPrice)*SUM(OutputWeight - InputWeight  )    * MAX(WaterCo) / 100  )  )  * MAX(TaxCo) / 100 )) 
		end
	else SUM(TotallSellPrice)	end  AS money)) AS TotallSellPrice


	,	SUM(TotallCommission) AS TotallCommission, SUM(Wage) AS Wage

	,StuffSize,StuffDiameter,StuffAlloy--,@ids as IdS
	FROM  
(

SELECT TOP 100 PERCENT  max(Ri.ReciptItemID)ReciptItemID,ROW_NUMBER() OVER(ORDER BY max(Ri.ReciptItemID) ASC) AS Row# ,
Sc.NationalStuffCode AS _NationalStuffCode, U.Tax_mu AS _Tax_mu, - sum(Ri.TotallSellPrice) AS TotallSellPrice, Sc.c_StuffName AS _StuffName,ItemNote , 
                          sum(Ri.InputEntity)InputEntity , sum(Ri.OutputEntity) OutputEntity,  sum(Ri.InputWeight) InputWeight, sum(Ri.OutputWeight)OutputWeight, 
                         - sum(Ri.ArzAmount) AS ArzAmount, -0* max(Ri.UnitSellPrice) AS UnitSellPrice,  - sum(Ri.DeficitValue) AS DeficitValue, max(Ri.TaxCo)TaxCo, - sum(Ri.TaxValue) AS TaxValue,
						 - sum(Ri.TotallCommission) AS TotallCommission, - sum(Ri.Wage) Wage,   sum(Ri.TotalInputPrice)TotalInputPrice, 
                         sum( Ri.TotalOutputPrice)TotalOutputPrice,max(Ri.preReciptItemID) preReciptItemID,sum(DiagnosisCalcTotalPrice)DiagnosisCalcTotalPrice
						 ,StuffSize,StuffDiameter,StuffAlloy,max(WaterCo) WaterCo
FROM            Recipts AS R INNER JOIN
                         Vu_ReciptsGrid AS Ri ON R.ReciptID = Ri.ReciptID AND R.ServerID = Ri.ServerID AND R.YearID = Ri.YearID INNER JOIN
                         StuffCoding AS Sc ON Ri.StuffCode = Sc.c_StuffCode INNER JOIN
                         Units AS U ON Sc.n_UnitCode = U.UnitCode INNER JOIN
                         ReciptTypes1 T ON R.ReciptType = t.ReciptType
WHERE R.ID  IN (SELECT  part  FROM dbo.SplitString(@ids,','))
       and T.SellEffect = 2
	   and r.ReciptState<>3
GROUP BY Sc.NationalStuffCode, U.Tax_mu, Sc.c_StuffName,ItemNote , StuffSize,StuffDiameter,StuffAlloy ,case when @countForm = 2 then Ri.ReciptItemID else @countForm end
ORDER BY max(Ri.ReciptItemID)

union all

SELECT  TOP 100 PERCENT Ri.preReciptItemID,ROW_NUMBER() OVER(ORDER BY Ri.preReciptItemID ASC) AS Row# , 
Sc.NationalStuffCode AS _NationalStuffCode, U.Tax_mu AS _Tax_mu, Ri.TotallSellPrice, Sc.c_StuffName AS _StuffName,ItemNote ,  
                          Ri.InputEntity,  OutputEntity, InputWeight,  OutputWeight, 
                          ArzAmount,  UnitSellPrice,  DeficitValue,  TaxCo,  
                          TaxValue,  TotallCommission,  Ri.Wage,  TotalInputPrice, 
                          TotalOutputPrice,Ri.preReciptItemID,DiagnosisCalcTotalPrice,StuffSize,StuffDiameter,StuffAlloy,WaterCo
FROM            Recipts AS R INNER JOIN
                         Vu_ReciptsGrid AS Ri ON R.ReciptID = Ri.ReciptID AND R.ServerID = Ri.ServerID AND R.YearID = Ri.YearID INNER JOIN
                         StuffCoding AS Sc ON Ri.StuffCode = Sc.c_StuffCode INNER JOIN
                         Units AS U ON Sc.n_UnitCode = U.UnitCode INNER JOIN
                         ReciptTypes1 T ON R.ReciptType = t.ReciptType
WHERE  R.ID  IN (SELECT  part  FROM dbo.SplitString(@ids,',')) and
        T.SellEffect = 1
		and r.ReciptState<>3
ORDER BY Ri.preReciptItemID

)abc
GROUP BY -- Row#,
_NationalStuffCode,_Tax_mu,_StuffName,ItemNote , ISNULL(DiagnosisCalcTotalPrice,0),StuffSize,StuffDiameter,StuffAlloy
--HAVING SUM(OutputEntity-InputEntity )>0
order BY min(ReciptItemID)
--RETURN(0)
END
