CREATE PROCEDURE Sp_StuffCodingStock_In
@StoreIDFrom int,    
@StoreIDTo int,
@StuffCodeFrom Bigint,    --not use
@StuffCodeTo Bigint   --not use

AS
SET NOCOUNT ON
BEGIN

BEGIN TRAN

BEGIN TRY

INSERT INTO StuffCodingStock
                         (StuffCode, StoreID,  MinOrder, MaxOrder, OrderPoint, OptimumPoint, DayOfStorage)
SELECT        S.c_StuffCode, STs.n_StoreID,  S.n_minOrder, s.n_maxOrder, s.n_orderPoint, s.OptimumPoint, s.DayOfStorage
FROM            StuffCoding S INNER JOIN
                         StoreStuffs STs ON s.c_StuffCode = STs.c_StuffCode LEFT OUTER JOIN
                         StuffCodingStock AS S1 ON STs.n_StoreID = S1.StoreID AND s.c_StuffCode = S1.StuffCode
WHERE        (S1.StuffCode IS NULL) AND (STs.n_StoreID BETWEEN @StoreIDFrom AND  @StoreIDTo) And
                         (ISNULL(s.n_minOrder, 0) + ISNULL(s.n_maxOrder, 0) + ISNULL(s.n_orderPoint, 0) + ISNULL(s.OptimumPoint, 0) + ISNULL(s.DayOfStorage, 0) > 0)

--UPDATE       StuffCoding
--SET                 n_minOrder = 0, n_maxOrder = 0, n_orderPoint = 0, OptimumPoint = 0, DayOfStorage = 0
--FROM            StuffCoding S INNER JOIN
--                         StoreStuffs STs ON S.c_StuffCode = STs.c_StuffCode LEFT OUTER JOIN
--                         StuffCodingStock AS S1 ON STs.n_StoreID = S1.StoreID AND S.c_StuffCode = S1.StuffCode
--WHERE        (S1.StuffCode IS NULL) AND (STs.n_StoreID BETWEEN @StoreIDFrom AND @StoreIDTo) And
