AS
SET NOCOUNT ON
BEGIN

BEGIN TRAN

BEGIN TRY

INSERT INTO StuffCodingFacilities
                         (StuffCode, StoreID,  Cabinet, KeepPlace, Tierced)
SELECT        S.c_StuffCode, STs.n_StoreID, S.Cabinet, S.c_KeepPlace, S.Tierced
FROM            StuffCoding AS S INNER JOIN
                         StoreStuffs AS STs ON S.c_StuffCode = STs.c_StuffCode LEFT OUTER JOIN
                         StuffCodingFacilities AS S1 ON STs.n_StoreID = S1.StoreID AND S.c_StuffCode = S1.StuffCode
WHERE        (S1.StuffCode IS NULL) AND (STs.n_StoreID BETWEEN @StoreIDFrom AND @StoreIDTo) 
     AND (ISNULL(S.Cabinet, N'') <> '' OR ISNULL(S.c_KeepPlace, N'') <> '' OR ISNULL(S.Tierced, N'') <> '')

--UPDATE       StuffCoding
--SET                 Cabinet = '', c_KeepPlace = '', Tierced = ''
--FROM            StuffCoding S INNER JOIN
--                         StoreStuffs STs ON S.c_StuffCode = STs.c_StuffCode LEFT OUTER JOIN
--                         StuffCodingFacilities AS S1 ON STs.n_StoreID = S1.StoreID AND S.c_StuffCode = S1.StuffCode
--WHERE        (S1.StuffCode IS NULL) AND (STs.n_StoreID BETWEEN @StoreIDFrom AND @StoreIDTo) 
--     AND (ISNULL(S.Cabinet, N'') <> '' OR ISNULL(S.c_KeepPlace, N'') <> '' OR ISNULL(S.Tierced, N'') <> '')

   COMMIT TRAN

END TRY
BEGIN CATCH

  ROLLBACK TRAN

END CATCH

END 


