CREATE PROCEDURE [dbo].[Sp_allaccount]
			@PersonID1From Bigint		,
			@PersonID1To Bigint			,
			@MyDateFrom char(10)	    ,
			@YearIDFrom Bigint			,
			@YearIDTo Bigint			,
			@SellsMethodFrom Bigint		,
			@SellsMethodTo Bigint		,
			@SellsEmporiumFrom Bigint	,
			@SellsEmporiumTo Bigint		,
			@GroupType1 Bigint			,
			@GroupType2 Bigint			,
			@CustomerGrpID1From Bigint	,
			@CustomerGrpID1To Bigint	,
			@CustomerGrpID2From Bigint	,
			@CustomerGrpID2To Bigint	,
			@VasetFrom Bigint			,
			@VasetTo Bigint				,
			@SellsCodeFrom Bigint		,
			@SellsCodeTo Bigint			,
			@SUMAccFrom Bigint			,
			@SUMAccTo Bigint			
			AS 

BEGIN

	select si.sellscode  as [کدفروشنده],si.sellsname [نام‏فروشنده], allacc.customerid1 as [کدمشتري],customers.custfirstname + ' ' + customers.custname as [مشخصات], customers.tel as [تلفن], customers.address as [آدرس], customers.mobile as [موبايل],  sum(case when allacc.kind = 0 then allacc.bed - allacc.bes else 0 end)
as [مانده‏اول‏دوره], sum(allacc.bed) - case when sum(case when allacc.kind = 0 then allacc.bed - allacc.bes else 0 end) > 0 then 
sum(case when allacc.kind = 0 then allacc.bed - allacc.bes else 0 end) else 0 end as [بدهکار], sum(case when doctype in (1, 2, 10) then allacc.bes else 0 end) - case when 
sum(case when allacc.kind = 0 then allacc.bed - allacc.bes else 0 end) < 0 then - sum(case when allacc.kind = 0 then allacc.bed - allacc.bes else 0 end) else 0 end as [بستانکار], 
sum(case when doctype in (1, 2, 10) then allacc.bed - allacc.bes else 0 end) as [مانده],  sum(case when doctype in (11) then allacc.bed - allacc.bes else 0 end) as [اسناد‏برگشتي],
sum(case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-20,getdate())),10) and right(dbo.miladitoshamsi(getdate()),10) then  allacc.bed else 0 end) - case when 
sum(case when allacc.kind = 0 then case when allacc.formdate 
between right(dbo.miladitoshamsi( dateadd (day,-20,getdate())),10) 
and right(dbo.miladitoshamsi(getdate()),10) then allacc.bed - allacc.bes else 0 end else 0 end) > 0 then sum(case when allacc.kind = 0 
then case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-20,getdate())),10) and right(dbo.miladitoshamsi(getdate()),10) 
then allacc.bed - allacc.bes else 0 end else 0 end) else 0 end as [فروش‏20روزاخير] , sum(case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-20,getdate())),10)
and right(dbo.miladitoshamsi(getdate()),10) then  allacc.bes else 0 end) - case when sum(case when allacc.kind = 0 then case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-20,getdate())),10) 
and right(dbo.miladitoshamsi(getdate()),10) then allacc.bed - allacc.bes else 0 end else 0 end) > 0 then sum(case when allacc.kind = 0 then case when allacc.formdate
between right(dbo.miladitoshamsi(dateadd(day,-20,getdate())),10) and right(dbo.miladitoshamsi(getdate()),10) then allacc.bed - allacc.bes else 0 end else 0 end) else 0  end as [دريافتي20روزاخير]


,sum(case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-40,getdate())),10)
and right(dbo.miladitoshamsi(getdate()),10) then  allacc.bed else 0 end) - case when sum(case when allacc.kind = 0 then case when allacc.formdate 
between right(dbo.miladitoshamsi(dateadd(day,-40,getdate())),10) and right(dbo.miladitoshamsi(getdate()),10) then allacc.bed - allacc.bes else 0 end else 0 end) > 0 then 
sum(case when allacc.kind = 0 then case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-40,getdate())),10) and right(dbo.miladitoshamsi(getdate()),10) then allacc.bed - allacc.bes
else 0 end else 0 end) else 0  end as [فروش40روزاخير] , 

sum(case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-40,getdate())),10) and right(dbo.miladitoshamsi(getdate()),10) 
then  allacc.bes else 0 end) - case when sum(case when allacc.kind = 0 then case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-40,getdate())),10) and right(dbo.miladitoshamsi(getdate()),10) 
then allacc.bed - allacc.bes else 0 end else 0 end)   > 0 then sum(case when allacc.kind = 0 then case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-40,getdate())),10) 
and right(dbo.miladitoshamsi(getdate()),10) then allacc.bed - allacc.bes else 0 end else 0 end) else 0 end as [دريافتي40روزاخير] 


,sum(case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-60,getdate())),10)
and right(dbo.miladitoshamsi(getdate()),10) then  allacc.bed else 0 end) - case when sum(case when allacc.kind = 0 then case when allacc.formdate 
between right(dbo.miladitoshamsi(dateadd(day,-60,getdate())),10) and right(dbo.miladitoshamsi(getdate()),10) then allacc.bed - allacc.bes else 0 end else 0 end) > 0 then 
sum(case when allacc.kind = 0 then case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-60,getdate())),10) and right(dbo.miladitoshamsi(getdate()),10) then allacc.bed - allacc.bes
else 0 end else 0 end) else 0  end as [فروش60روزاخير] , 

sum(case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-60,getdate())),10) and right(dbo.miladitoshamsi(getdate()),10) 
then  allacc.bes else 0 end) - case when sum(case when allacc.kind = 0 then case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-60,getdate())),10) and right(dbo.miladitoshamsi(getdate()),10) 
then allacc.bed - allacc.bes else 0 end else 0 end)   > 0 then sum(case when allacc.kind = 0 then case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-60,getdate())),10) 
and right(dbo.miladitoshamsi(getdate()),10) then allacc.bed - allacc.bes else 0 end else 0 end) else 0 end as [دريافتي60روزاخير] 


,sum(case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-80,getdate())),10)
and right(dbo.miladitoshamsi(getdate()),10) then  allacc.bed else 0 end) - case when sum(case when allacc.kind = 0 then case when allacc.formdate 
between right(dbo.miladitoshamsi(dateadd(day,-80,getdate())),10) and right(dbo.miladitoshamsi(getdate()),10) then allacc.bed - allacc.bes else 0 end else 0 end) > 0 then 
sum(case when allacc.kind = 0 then case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-80,getdate())),10) and right(dbo.miladitoshamsi(getdate()),10) then allacc.bed - allacc.bes
else 0 end else 0 end) else 0  end as [فروش80روزاخير] , 

sum(case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-80,getdate())),10) and right(dbo.miladitoshamsi(getdate()),10) 
then  allacc.bes else 0 end) - case when sum(case when allacc.kind = 0 then case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-80,getdate())),10) and right(dbo.miladitoshamsi(getdate()),10) 
then allacc.bed - allacc.bes else 0 end else 0 end)   > 0 then sum(case when allacc.kind = 0 then case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-80,getdate())),10) 
and right(dbo.miladitoshamsi(getdate()),10) then allacc.bed - allacc.bes else 0 end else 0 end) else 0 end as [دريافتي80روزاخير] 



,sum(case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-100,getdate())),10)
and right(dbo.miladitoshamsi(getdate()),10) then  allacc.bed else 0 end) - case when sum(case when allacc.kind = 0 then case when allacc.formdate 
between right(dbo.miladitoshamsi(dateadd(day,-100,getdate())),10) and right(dbo.miladitoshamsi(getdate()),10) then allacc.bed - allacc.bes else 0 end else 0 end) > 0 then 
sum(case when allacc.kind = 0 then case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-100,getdate())),10) and right(dbo.miladitoshamsi(getdate()),10) then allacc.bed - allacc.bes
else 0 end else 0 end) else 0  end as [فروش100روزاخير] , 

sum(case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-100,getdate())),10) and right(dbo.miladitoshamsi(getdate()),10) 
then  allacc.bes else 0 end) - case when sum(case when allacc.kind = 0 then case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-100,getdate())),10) and right(dbo.miladitoshamsi(getdate()),10) 
then allacc.bed - allacc.bes else 0 end else 0 end)   > 0 then sum(case when allacc.kind = 0 then case when allacc.formdate between right(dbo.miladitoshamsi(dateadd(day,-100,getdate())),10) 
and right(dbo.miladitoshamsi(getdate()),10) then allacc.bed - allacc.bes else 0 end else 0 end) else 0 end as [دريافتي100روزاخير] 


 from   customersgroup right outer join dbo.allaccount(10,-1, -1,- 1, @personid1from,@personid1to, '', @mydatefrom , '', @yearidfrom , @yearidto , @sellsmethodfrom , @sellsmethodto , @sellsemporiumfrom , 
 @sellsemporiumto ,default) as allacc 
 inner join customers on allacc.customerid1 = customers.custid 
 left outer join customersgroup as othergroups 
 inner join customersothergroups  on othergroups.customergrpid = customersothergroups.customergrpid on customers.custid = customersothergroups.custid on customersgroup.customergrpid = customers.customergrpid 
 left outer join customersactivity ca on ca.personid1 = customers.custid 
 left outer join  sellsinfo si on ca.sellscode = si.sellscode 
 where ((othergroups.grouptype in( @grouptype1 ) )
 or (customersgroup.grouptype  in( @grouptype2 ) ))  and ((customersgroup.customergrpid between @customergrpid1from and @customergrpid1to) or (customersothergroups.customergrpid 
 between @customergrpid2from and @customergrpid2to) ) and (allacc.customerid1<> 0) and ((customers.personid1 between @vasetfrom and @vasetto ) or (customers.personid1=0)) and (isnull(si.sellscode,0)
 between @sellscodefrom and @sellscodeto)
group by allacc.customerid1,customers.custname,customers.tel,customers.address,customers.mobile,customers.firstbalance,si.sellscode,si.sellsname,custfirstname having (sum(allacc.bed - allacc.bes) 
between @sumaccfrom and @sumaccto) order by allacc.customerid1
END

