CREATE VIEW dbo.Anb_Master_Details_P AS
SELECT 
    SC.c_StuffCode AS Part_Code,
    S.n_StoreID AS Anb_Code,
    S.c_StoreName AS Anb_Desc,
    CAST(SC.c_StuffName AS NVARCHAR(4000)) AS Part_Desc,
    U.UnitCode AS PU_Code,
    U.UnitName AS PU_Desc,
    SUM(CASE WHEN RIS.EffectType IN (2,6) THEN RIS.In_Entity ELSE -RIS.Out_Entity END) AS QTY,
    SC.c_StuffTecInfo AS Spec_No,
    ISNULL(SCS.OrderPoint, 0) AS Order_P,
    ISNULL(SCS.MinOrder, 0) AS Order_Q,
    ISNULL(MP.Price, SC.SellPrice1) AS Price,
    CAST(0 AS BIT) AS Update_Flag,
    CAST(
        CAST(SC.c_StuffCode AS VARCHAR(20)) + 
        RIGHT('000' + CAST(S.n_StoreID AS VARCHAR(3)), 3)
    AS BIGINT) AS Part_PCode,
    CAST(SC.sd1 AS NVARCHAR(2000)) AS F1_Val,
    CAST(SC.sd2 AS NVARCHAR(2000)) AS F2_Val,
    CAST(SC.sd3 AS NVARCHAR(2000)) AS F3_Val,
    CAST(SC.sd4 AS NVARCHAR(2000)) AS F4_Val,
    CAST(SC.sd5 AS NVARCHAR(2000)) AS F5_Val
FROM dbo.StuffCoding SC
INNER JOIN dbo.StuffGroups SG ON SC.GroupID = SG.GroupID
INNER JOIN dbo.Units U ON SC.n_UnitCode = U.UnitCode
INNER JOIN dbo.ReciptItems_Stock RIS ON SC.c_StuffCode = RIS.StuffCode
INNER JOIN dbo.Stores S ON RIS.StoreID = S.n_StoreID
LEFT JOIN dbo.StuffCodingStock SCS 
    ON SC.c_StuffCode = SCS.StuffCode 
    AND S.n_StoreID = SCS.StoreID
LEFT JOIN (
    SELECT MI.StuffCode, MAX(MI.SellPrice1) AS Price
    FROM dbo.ManifestoItems MI
    INNER JOIN dbo.Manifesto M ON MI.ManifestoID = M.ManifestoID
    WHERE LEFT(M.ManifestoRunDate, 4) = '1404'
      AND ISNULL(M.Active, 1) = 1 AND ISNULL(MI.Active, 1) = 1
    GROUP BY MI.StuffCode
) MP ON SC.c_StuffCode = MP.StuffCode
--WHERE SG.SarFaslType IN (5)
--  AND S.StoreKind = 1
--  AND RIS.YearID = 1404
GROUP BY 
    SC.c_StuffCode, S.n_StoreID, S.c_StoreName, SC.c_StuffName, 
    U.UnitCode, U.UnitName, SC.c_StuffTecInfo, 
    SCS.OrderPoint, SCS.MinOrder, MP.Price, SC.SellPrice1,
    SC.sd1, SC.sd2, SC.sd3, SC.sd4, SC.sd5;
