CREATE PROCEDURE Tsh.FillCalendar
    @ShamsiYear CHAR(4)   -- مثال: 1403
AS
BEGIN
    SET NOCOUNT ON;

    ---------------------------------------------------------
    -- تبدیل سال شمسی به تاریخ شروع و پایان میلادی
    ---------------------------------------------------------
    DECLARE 
        @StartShamsi CHAR(10) = @ShamsiYear + '/01/01',
        @EndShamsi   CHAR(10) = @ShamsiYear + '/12/29',   -- برای کبیسه بعداً اصلاح می‌شود
        @StartMiladi DATE,
        @EndMiladi   DATE;

    SET @StartMiladi = dbo.ShamsiToMiladi(@StartShamsi);
    SET @EndMiladi   = dbo.ShamsiToMiladi(@EndShamsi);

    ---------------------------------------------------------
    -- اگر سال کبیسه شمسی باشد، 30 اسفند داریم
    -- یعنی روز بعد از 29 اسفند هنوز ماه 12 است
    ---------------------------------------------------------
    IF SUBSTRING(dbo.MiladiToShamsi(DATEADD(DAY, 1, @EndMiladi)), 6, 2) = '12'
    BEGIN
        SET @EndMiladi = DATEADD(DAY, 1, @EndMiladi);  -- اضافه کردن روز 30 اسفند
    END

    ---------------------------------------------------------
    -- جدول کمکی تولید اعداد (حداکثر 366 روز در سال)
    -- از master..spt_values استفاده می‌کنیم
    ---------------------------------------------------------
    ;WITH Nums AS (
        SELECT ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1 AS n
        FROM master..spt_values
        WHERE type = 'P'
    ),
    Days AS (
        SELECT DATEADD(DAY, n, @StartMiladi) AS dte
        FROM Nums
        WHERE n <= DATEDIFF(DAY, @StartMiladi, @EndMiladi)
    )

    ---------------------------------------------------------
    -- درج رکوردهای تقویم
    ---------------------------------------------------------
    INSERT INTO Tsh.Calendar
    (
        CalendarDate,
        YearNO,
        MonthNO,
        DayNo,
        WeekDayID,
        WeekDayName,
        CalendarKind,
        WeekInYear
    )
    SELECT 
          SUBSTRING(dbo.MiladiTOShamsi(dte), 1, 10)           AS CalendarDate,
          SUBSTRING(dbo.MiladiTOShamsi(dte), 1, 4)            AS YearNO,
          SUBSTRING(dbo.MiladiTOShamsi(dte), 6, 2)            AS MonthNO,
          SUBSTRING(dbo.MiladiTOShamsi(dte), 9, 2)            AS DayNo,

          CASE WHEN DATEPART(WEEKDAY, dte) = 7 
               THEN 1 
               ELSE DATEPART(WEEKDAY, dte) + 1 
          END                                                AS WeekDayID,
          
          CASE DATEPART(WEEKDAY, dte)
               WHEN 1 THEN N'يكشنبه'
               WHEN 2 THEN N'دوشنبه'
               WHEN 3 THEN N'سه‌شنبه'
               WHEN 4 THEN N'چهارشنبه'
               WHEN 5 THEN N'پنجشنبه'
               WHEN 6 THEN N'جمعه'
               WHEN 7 THEN N'شنبه'
          END                                                AS WeekDayName,
          
          CASE WHEN DATEPART(WEEKDAY, dte) = 6 
               THEN 1 
               ELSE 0 
          END                                                AS CalendarKind,

          DATEPART(WEEK, dte)                                AS WeekInYear
    FROM Days
    WHERE SUBSTRING(dbo.MiladiTOShamsi(dte), 1, 10)
          NOT IN (SELECT CalendarDate FROM Tsh.Calendar)
    ORDER BY dte;
END

