CREATE PROCEDURE [dbo].[rpt_CustomerAccount_Summary]
    @YearIdFrom   int,
    @YearIdTo     int,
    @PersonIdFrom int,
    @PersonIdTo   int,
    @DateFrom     char(10),
    @DateTo       char(10),
    @DateFromRemain       char(10)
AS
BEGIN
    SET NOCOUNT ON;
SELECT AllAcc.PersonID1 
,SUM(CASE WHEN kind = 0 AND recipttype = 0   THEN ABS(bed-bes) ELSE 0 END) AS [نقل از قبل]
,SUM(CASE WHEN kind = 1 AND recipttype = 1   THEN ABS(bed-bes) ELSE 0 END) AS [دریافت وجه نقد]
,SUM(CASE WHEN kind = 1 AND recipttype = 2   THEN ABS(bed-bes) ELSE 0 END) AS [پرداخت وجه نقد]
,SUM(CASE WHEN kind = 3 AND recipttype = 5   THEN ABS(bed-bes) ELSE 0 END) AS [رسید کالا]
,SUM(CASE WHEN kind = 3 AND recipttype = 6   THEN ABS(bed-bes) ELSE 0 END) AS [برگشت از فروش]
,SUM(CASE WHEN kind = 2 AND recipttype = 10  THEN ABS(bed-bes) ELSE 0 END) AS [دریافت چک]
,SUM(CASE WHEN kind = 2 AND recipttype = 12  THEN ABS(bed-bes) ELSE 0 END) AS [واگذار چک دریافتی به مشتری]
,SUM(CASE WHEN kind = 3 AND recipttype = 12  THEN ABS(bed-bes) ELSE 0 END) AS [فاکتور فروش]
,SUM(CASE WHEN kind = 3 AND recipttype = 14  THEN ABS(bed-bes) ELSE 0 END) AS [برگشت از خرید]
,SUM(CASE WHEN kind = 2 AND recipttype = 18  THEN ABS(bed-bes) ELSE 0 END) AS [برگشت چکهای واگذاری به مشتری]
,SUM(CASE WHEN kind = 2 AND recipttype = 25  THEN ABS(bed-bes) ELSE 0 END) AS [عودت چکهای دریافتی به مشتری]
,SUM(CASE WHEN kind = 2 AND recipttype = 26  THEN ABS(bed-bes) ELSE 0 END) AS [عودت چکهای برگشتی به مشتری]
,SUM(CASE WHEN kind = 2 AND recipttype = 50  THEN ABS(bed-bes) ELSE 0 END) AS [صدور چک]
,SUM(CASE WHEN kind = 1 AND recipttype = 90  THEN ABS(bed-bes) ELSE 0 END) AS [فیش و حواله های بانکی]
,SUM(CASE WHEN kind = 1 AND recipttype = 91  THEN ABS(bed-bes) ELSE 0 END) AS [سایر پرداختی ها]
,SUM(CASE WHEN kind = 1 AND recipttype = 101 THEN ABS(bed-bes) ELSE 0 END) AS [اعلامیه بدهکار]
,SUM(CASE WHEN kind = 1 AND recipttype = 102 THEN ABS(bed-bes) ELSE 0 END) AS [اعلامیه بستانکار]
,SUM(CASE WHEN kind = 2 AND recipttype = 103 THEN ABS(bed-bes) ELSE 0 END) AS [صورت خلاصه تنخواه گردان]
,SUM(bed-bes) AS [مانده]
FROM dbo.AllAccountItem(10, - 1, - 1, - 1, @PersonIDFrom, @PersonIDTo, @DateFrom, @DateTo, @DateFromRemain, @YearIDFrom, @YearIDTo, 0, 999999999, 0, 999999999, DEFAULT) AS AllAcc
  join Customers cg on cg.custid=AllAcc.PersonID1
 where custid between @PersonIdFrom and @PersonIdTo
          and customergrpid=7
GROUP BY AllAcc.PersonID1 
option (recompile);
END
GO

